--
-- Name: _create_payroll_slip_from_wizard_internal(jsonb, uuid[], uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._create_payroll_slip_from_wizard_internal(p_payload jsonb, p_ledger_entry_ids uuid[] DEFAULT ARRAY[]::uuid[], p_bonus_request_ids uuid[] DEFAULT ARRAY[]::uuid[], p_penalty_request_ids uuid[] DEFAULT ARRAY[]::uuid[], p_advance_ids uuid[] DEFAULT ARRAY[]::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_employee_id uuid := nullif(p_payload->>'employee_id', '')::uuid;
  v_period_start date := nullif(p_payload->>'period_start', '')::date;
  v_period_end date := nullif(p_payload->>'period_end', '')::date;
  v_slip_id uuid;
  v_requested_count integer;
  v_verified_count integer;
begin
  if v_org_id is null or v_employee_id is null or v_period_start is null or v_period_end is null then
    raise exception 'invalid_payroll_wizard_payload';
  end if;
  if v_period_end < v_period_start then
    raise exception 'invalid_payroll_period';
  end if;

  perform 1 from public.employees
  where id = v_employee_id and org_id = v_org_id
  for update;
  if not found then
    raise exception 'payroll_employee_not_found';
  end if;

  if exists (
    select 1 from public.payroll_slips
    where org_id = v_org_id
      and employee_id = v_employee_id
      and period_start = v_period_start
      and period_end = v_period_end
      and coalesce(status, 'draft') <> 'canceled'
  ) then
    raise exception 'payroll_slip_already_exists';
  end if;

  select count(*) into v_requested_count
  from (select distinct value from unnest(coalesce(p_ledger_entry_ids, array[]::uuid[])) as value) requested;
  select count(*) into v_verified_count
  from public.payroll_calculation_entries
  where org_id = v_org_id
    and employee_id = v_employee_id
    and period_start = v_period_start
    and period_end = v_period_end
    and status in ('draft', 'proposed')
    and id = any(coalesce(p_ledger_entry_ids, array[]::uuid[]));
  if v_requested_count <> v_verified_count then
    raise exception 'payroll_ledger_entries_changed';
  end if;

  -- Keep the context active for the complete write sequence, including any
  -- payroll-side trigger that runs while the new slip is inserted.
  perform set_config('app.payroll_source_sync', 'active', true);

  insert into public.payroll_slips (
    org_id, name, system_code, employee_id, period_start, period_end, status, assignee_id,
    base_salary, task_wage_total, bonus_total, deduction_total,
    insurance_employee_amount, insurance_employer_amount, gross_amount, net_amount,
    lines, payments, performance_snapshot, task_ids, notes
  ) values (
    v_org_id,
    coalesce(p_payload->>'name', ''),
    nullif(p_payload->>'system_code', ''),
    v_employee_id, v_period_start, v_period_end, coalesce(nullif(p_payload->>'status', ''), 'draft'),
    nullif(p_payload->>'assignee_id', '')::uuid,
    coalesce((p_payload->>'base_salary')::numeric, 0),
    coalesce((p_payload->>'task_wage_total')::numeric, 0),
    coalesce((p_payload->>'bonus_total')::numeric, 0),
    coalesce((p_payload->>'deduction_total')::numeric, 0),
    coalesce((p_payload->>'insurance_employee_amount')::numeric, 0),
    coalesce((p_payload->>'insurance_employer_amount')::numeric, 0),
    coalesce((p_payload->>'gross_amount')::numeric, 0),
    coalesce((p_payload->>'net_amount')::numeric, 0),
    coalesce(p_payload->'lines', '[]'::jsonb),
    coalesce(p_payload->'payments', '[]'::jsonb),
    coalesce(p_payload->'performance_snapshot', '{}'::jsonb),
    coalesce(p_payload->'task_ids', '[]'::jsonb),
    nullif(p_payload->>'notes', '')
  ) returning id into v_slip_id;

  update public.payroll_calculation_entries
  set status = 'included_in_payroll', payroll_slip_id = v_slip_id, updated_at = now()
  where id = any(coalesce(p_ledger_entry_ids, array[]::uuid[]))
    and org_id = v_org_id;

  select count(*) into v_requested_count from (select distinct value from unnest(coalesce(p_bonus_request_ids, array[]::uuid[])) as value) requested;
  select count(*) into v_verified_count from public.employee_bonus_requests
  where org_id = v_org_id and employee_id = v_employee_id and id = any(coalesce(p_bonus_request_ids, array[]::uuid[]))
    and related_payroll_slip_id is null;
  if v_requested_count <> v_verified_count then raise exception 'payroll_bonus_requests_changed'; end if;
  update public.employee_bonus_requests set related_payroll_slip_id = v_slip_id, updated_at = now()
  where id = any(coalesce(p_bonus_request_ids, array[]::uuid[])) and org_id = v_org_id;

  select count(*) into v_requested_count from (select distinct value from unnest(coalesce(p_penalty_request_ids, array[]::uuid[])) as value) requested;
  select count(*) into v_verified_count from public.employee_penalty_requests
  where org_id = v_org_id and employee_id = v_employee_id and id = any(coalesce(p_penalty_request_ids, array[]::uuid[]))
    and related_payroll_slip_id is null;
  if v_requested_count <> v_verified_count then raise exception 'payroll_penalty_requests_changed'; end if;
  update public.employee_penalty_requests set related_payroll_slip_id = v_slip_id, updated_at = now()
  where id = any(coalesce(p_penalty_request_ids, array[]::uuid[])) and org_id = v_org_id;

  select count(*) into v_requested_count from (select distinct value from unnest(coalesce(p_advance_ids, array[]::uuid[])) as value) requested;
  select count(*) into v_verified_count from public.employee_advances
  where org_id = v_org_id and employee_id = v_employee_id and id = any(coalesce(p_advance_ids, array[]::uuid[]))
    and related_payroll_slip_id is null;
  if v_requested_count <> v_verified_count then raise exception 'payroll_advances_changed'; end if;
  update public.employee_advances set related_payroll_slip_id = v_slip_id, updated_at = now()
  where id = any(coalesce(p_advance_ids, array[]::uuid[])) and org_id = v_org_id;

  return v_slip_id;
end;
$$;


--
-- Name: _delivery_normalize_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._delivery_normalize_phone(p_raw text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select case
    when regexp_replace(translate(coalesce(p_raw, ''), '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '[^0-9]', '', 'g') ~ '^00989[0-9]{9}$' then '0' || substr(regexp_replace(translate(coalesce(p_raw, ''), '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '[^0-9]', '', 'g'), 5)
    when regexp_replace(translate(coalesce(p_raw, ''), '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '[^0-9]', '', 'g') ~ '^989[0-9]{9}$' then '0' || substr(regexp_replace(translate(coalesce(p_raw, ''), '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '[^0-9]', '', 'g'), 3)
    when regexp_replace(translate(coalesce(p_raw, ''), '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '[^0-9]', '', 'g') ~ '^9[0-9]{9}$' then '0' || regexp_replace(translate(coalesce(p_raw, ''), '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '[^0-9]', '', 'g')
    else regexp_replace(translate(coalesce(p_raw, ''), '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '[^0-9]', '', 'g') end
$_$;


--
-- Name: _delivery_public_phone_options(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._delivery_public_phone_options(p_phone_1 text, p_phone_2 text DEFAULT NULL::text, p_phone_3 text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare v_result jsonb := '[]'::jsonb; v_seen text[] := array[]::text[]; v_phone text; v_raw text; v_index integer := 0;
begin
  foreach v_raw in array array[p_phone_1, p_phone_2, p_phone_3] loop
    v_phone := public._delivery_normalize_phone(v_raw);
    if v_phone ~ '^09[0-9]{9}$' and not (v_phone = any(v_seen)) then
      v_index := v_index + 1; v_seen := array_append(v_seen, v_phone);
      v_result := v_result || jsonb_build_array(jsonb_build_object('label', case when v_index = 1 then 'موبایل اصلی' else 'موبایل ' || v_index::text end, 'value', 'phone_' || v_index::text, 'phone', v_phone));
    end if;
  end loop;
  return v_result;
end;
$_$;


--
-- Name: _get_operational_financial_history(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._get_operational_financial_history(p_org_id uuid, p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  if p_org_id is null
    or p_entity_id is null
    or p_entity_type not in ('customer', 'supplier', 'employee')
  then
    return jsonb_build_object(
      'rows', '[]'::jsonb,
      'summary', jsonb_build_object('total_debit', 0, 'total_credit', 0, 'final_balance', 0, 'source', 'central_financial_history')
    );
  end if;

  with recursive financial_link_pairs as (
    select 'customer'::text source_type, c.id source_id, 'supplier'::text target_type, c.linked_supplier_id target_id
    from public.customers c where c.org_id = p_org_id and c.linked_supplier_id is not null
    union all
    select 'customer', c.id, 'employee', c.linked_employee_id
    from public.customers c where c.org_id = p_org_id and c.linked_employee_id is not null
    union all
    select 'supplier', s.id, 'customer', s.linked_customer_id
    from public.suppliers s where s.org_id = p_org_id and s.linked_customer_id is not null
    union all
    select 'supplier', s.id, 'employee', s.linked_employee_id
    from public.suppliers s where s.org_id = p_org_id and s.linked_employee_id is not null
    union all
    select 'employee', e.id, 'customer', e.linked_customer_id
    from public.employees e where e.org_id = p_org_id and e.linked_customer_id is not null
    union all
    select 'employee', e.id, 'supplier', e.linked_supplier_id
    from public.employees e where e.org_id = p_org_id and e.linked_supplier_id is not null
  ), financial_links as (
    select source_type, source_id, target_type, target_id from financial_link_pairs
    union all
    select target_type, target_id, source_type, source_id from financial_link_pairs
  ), entity_scope(entity_type, entity_id) as (
    select p_entity_type, p_entity_id
    union
    select link.target_type, link.target_id
    from financial_links link
    join entity_scope current_entity
      on current_entity.entity_type = link.source_type
      and current_entity.entity_id = link.source_id
  ), scoped_customers as (
    select entity_id id from entity_scope where entity_type = 'customer'
  ), scoped_suppliers as (
    select entity_id id from entity_scope where entity_type = 'supplier'
  ), scoped_employees as (
    select e.id, e.related_profile_id
    from public.employees e
    join entity_scope scope on scope.entity_type = 'employee' and scope.entity_id = e.id
    where e.org_id = p_org_id
  ), scoped_sales_invoices as (
    select i.id
    from public.invoices i
    where i.org_id = p_org_id and i.customer_id in (select id from scoped_customers)
  ), scoped_purchase_invoices as (
    select i.id
    from public.purchase_invoices i
    where i.org_id = p_org_id and i.supplier_id in (select id from scoped_suppliers)
  ), scoped_expense_documents as (
    select e.id
    from public.expense_documents e
    where e.org_id = p_org_id and (
      e.customer_id in (select id from scoped_customers)
      or e.supplier_id in (select id from scoped_suppliers)
      or e.employee_id in (select id from scoped_employees)
      or e.employee_id in (select related_profile_id from scoped_employees where related_profile_id is not null)
    )
  ), scoped_payroll_slips as (
    select p.id
    from public.payroll_slips p
    where p.org_id = p_org_id and p.employee_id in (select id from scoped_employees)
  ), scoped_employee_advances as (
    select a.id
    from public.employee_advances a
    where a.org_id = p_org_id and a.employee_id in (select id from scoped_employees)
  ), raw_rows as (
    select
      'opening'::text row_type,
      'مانده اول دوره'::text source_label,
      'customers'::text source_module_id,
      c.id::text source_record_id,
      ''::text payment_type,
      'opening'::text status,
      ''::text cheque_status,
      c.created_at::date row_date,
      case when coalesce(c.previous_system_balance_total, 0) >= 0 then abs(c.previous_system_balance_total) else 0 end debit,
      case when coalesce(c.previous_system_balance_total, 0) < 0 then abs(c.previous_system_balance_total) else 0 end credit,
      coalesce(nullif(btrim(c.system_code), ''), nullif(btrim(c.business_name), ''), nullif(btrim(c.full_name), ''), 'بدون عنوان') invoice_label,
      '-'::text bank_label,
      'مانده اول دوره سیستم قبلی'::text description,
      c.created_at,
      null::text bank_module_id,
      null::text bank_record_id,
      'opening_customer_' || c.id::text key
    from public.customers c
    where c.org_id = p_org_id and c.id in (select id from scoped_customers)
      and coalesce(c.previous_system_balance_total, 0) <> 0

    union all

    select
      'opening', 'مانده اول دوره', 'suppliers', s.id::text, '', 'opening', '', s.created_at::date,
      case when coalesce(s.previous_system_balance_total, 0) < 0 then abs(s.previous_system_balance_total) else 0 end,
      case when coalesce(s.previous_system_balance_total, 0) >= 0 then abs(s.previous_system_balance_total) else 0 end,
      coalesce(nullif(btrim(s.system_code), ''), nullif(btrim(s.business_name), ''), nullif(btrim(s.full_name), ''), 'بدون عنوان'),
      '-', 'مانده اول دوره سیستم قبلی', s.created_at, null, null, 'opening_supplier_' || s.id::text
    from public.suppliers s
    where s.org_id = p_org_id and s.id in (select id from scoped_suppliers)
      and coalesce(s.previous_system_balance_total, 0) <> 0

    union all

    select
      'opening', 'مانده اول دوره', 'employees', e.id::text, '', 'opening', '', e.created_at::date,
      case when coalesce(e.previous_system_balance_total, 0) < 0 then abs(e.previous_system_balance_total) else 0 end,
      case when coalesce(e.previous_system_balance_total, 0) >= 0 then abs(e.previous_system_balance_total) else 0 end,
      coalesce(nullif(btrim(e.system_code), ''), nullif(btrim(e.full_name), ''), 'بدون عنوان'),
      '-', 'مانده اول دوره سیستم قبلی', e.created_at, null, null, 'opening_employee_' || e.id::text
    from public.employees e
    where e.org_id = p_org_id and e.id in (select id from scoped_employees)
      and coalesce(e.previous_system_balance_total, 0) <> 0

    union all

    select
      'invoice', 'صدور فاکتور فروش', 'invoices', i.id::text, '', i.status, '', i.invoice_date,
      abs(coalesce(i.total_invoice_amount, 0)), 0,
      coalesce(public.financial_history_document_reference(i.system_code, i.name), 'بدون عنوان'), '-',
      concat('فاکتور فروش', case when coalesce(i.remaining_balance, 0) <> 0 then ' | مانده: ' || i.remaining_balance else '' end),
      i.created_at, null, null, 'invoice_' || i.id::text
    from public.invoices i
    where i.org_id = p_org_id and i.customer_id in (select id from scoped_customers)
      and i.status in ('confirmed', 'final', 'settled', 'completed')
      and coalesce(i.total_invoice_amount, 0) > 0

    union all

    select
      'invoice', 'ثبت فاکتور خرید', 'purchase_invoices', i.id::text, '', i.status, '', i.invoice_date,
      0, abs(coalesce(i.total_invoice_amount, 0)),
      coalesce(public.financial_history_document_reference(i.system_code, i.name), 'بدون عنوان'), '-',
      concat('فاکتور خرید', case when coalesce(i.remaining_balance, 0) <> 0 then ' | مانده: ' || i.remaining_balance else '' end),
      i.created_at, null, null, 'purchase_invoice_' || i.id::text
    from public.purchase_invoices i
    where i.org_id = p_org_id and i.supplier_id in (select id from scoped_suppliers)
      and i.status in ('confirmed', 'final', 'settled', 'completed')
      and coalesce(i.total_invoice_amount, 0) > 0

    union all

    select
      'payroll_slip', 'فیش حقوقی', 'payroll_slips', p.id::text, '', p.status, '', p.period_end,
      0, abs(coalesce(p.gross_amount, p.earnings_total - p.deduction_total, 0)),
      coalesce(public.financial_history_document_reference(p.system_code, p.name), 'بدون عنوان'), '-',
      'تعهد پرداخت حقوق', p.created_at, null, null, 'payroll_' || p.id::text
    from public.payroll_slips p
    where p.org_id = p_org_id and p.employee_id in (select id from scoped_employees)
      and p.status in ('approved', 'paid', 'posted')
      and coalesce(p.gross_amount, p.earnings_total - p.deduction_total, 0) > 0

    union all

    select
      'expense', 'ثبت هزینه', 'expense_documents', e.id::text, '', e.status, '', e.expense_date,
      0, abs(coalesce(e.total_amount, 0)),
      coalesce(public.financial_history_document_reference(e.system_code, e.name), 'بدون عنوان'), '-',
      concat('هزینه', case when coalesce(e.remaining_amount, 0) <> 0 then ' | مانده: ' || e.remaining_amount else '' end),
      e.created_at, null, null, 'expense_' || e.id::text
    from public.expense_documents e
    where e.org_id = p_org_id and e.status in ('approved', 'paid', 'posted', 'settled', 'completed')
      and coalesce(e.total_amount, 0) > 0
      and (
        e.customer_id in (select id from scoped_customers)
        or e.supplier_id in (select id from scoped_suppliers)
        or e.employee_id in (select id from scoped_employees)
        or e.employee_id in (select related_profile_id from scoped_employees where related_profile_id is not null)
      )

    union all

    select
      'barter', 'تهاتر', 'barters', b.id::text, 'barter', b.status, '', b.barter_date,
      case when b.barter_type = 'outgoing' then abs(coalesce(b.initial_amount, 0)) else 0 end,
      case when b.barter_type = 'incoming' then abs(coalesce(b.initial_amount, 0)) else 0 end,
      coalesce(public.financial_history_document_reference(b.system_code, b.name), 'بدون عنوان'), '-', coalesce(b.notes, ''),
      b.created_at, null, null, 'barter_' || b.id::text
    from public.barters b
    where b.org_id = p_org_id and b.status <> 'canceled'
      and (
        b.customer_id in (select id from scoped_customers)
        or b.supplier_id in (select id from scoped_suppliers)
        or b.employee_id in (select id from scoped_employees)
        or b.employee_id in (select related_profile_id from scoped_employees where related_profile_id is not null)
      )

    union all

    select
      case when operation.operation_type = 'payment' then 'payment' else 'receipt' end,
      case
        when operation.sales_invoice_id is not null then 'دریافت فاکتور فروش'
        when operation.purchase_invoice_id is not null then 'پرداخت فاکتور خرید'
        when operation.expense_document_id is not null then 'پرداخت هزینه'
        when operation.employee_advance_id is not null then 'پرداخت مساعده'
        when operation.payroll_slip_id is not null then 'پرداخت فیش حقوقی'
        else 'ثبت مستقیم نقد و بانک'
      end,
      case
        when operation.sales_invoice_id is not null then 'invoices'
        when operation.purchase_invoice_id is not null then 'purchase_invoices'
        when operation.expense_document_id is not null then 'expense_documents'
        when operation.employee_advance_id is not null then 'employee_advances'
        when operation.payroll_slip_id is not null then 'payroll_slips'
        else 'cash_bank_operations'
      end,
      coalesce(operation.sales_invoice_id, operation.purchase_invoice_id, operation.expense_document_id, operation.employee_advance_id, operation.payroll_slip_id, operation.id)::text,
      coalesce(operation.payment_type, ''), coalesce(operation.status, ''), coalesce(cheque.status, ''), operation.operation_date,
      case when operation.operation_type = 'payment' then abs(coalesce(operation.amount, 0)) else 0 end,
      case when operation.operation_type = 'receipt' then abs(coalesce(operation.amount, 0)) else 0 end,
      coalesce(
        public.financial_history_document_reference(sales.system_code, sales.name),
        public.financial_history_document_reference(purchase.system_code, purchase.name),
        public.financial_history_document_reference(expense.system_code, expense.name),
        public.financial_history_document_reference(advance.system_code, advance.name),
        public.financial_history_document_reference(payroll.system_code, payroll.name),
        '-'
      ),
      case
        when bank.id is not null then concat(coalesce(nullif(btrim(bank.bank_name), ''), 'بانک'), case when nullif(btrim(bank.account_number), '') is not null then ' (' || bank.account_number || ')' else '' end)
        when cash.id is not null then concat(coalesce(nullif(btrim(cash.name), ''), 'صندوق'), case when nullif(btrim(cash.code), '') is not null then ' (' || cash.code || ')' else '' end)
        when petty.id is not null then concat(coalesce(nullif(btrim(petty.name), ''), 'تنخواه'), case when nullif(btrim(petty.code), '') is not null then ' (' || petty.code || ')' else '' end)
        else '-'
      end,
      coalesce(operation.description, ''), operation.created_at,
      case when bank.id is not null then 'bank_accounts' when cash.id is not null then 'cash_boxes' when petty.id is not null then 'petty_funds' else null end,
      coalesce(bank.id, cash.id, petty.id)::text,
      'operation_' || operation.id::text
    from public.cash_bank_operations operation
    left join public.invoices sales on sales.id = operation.sales_invoice_id and sales.org_id = p_org_id
    left join public.purchase_invoices purchase on purchase.id = operation.purchase_invoice_id and purchase.org_id = p_org_id
    left join public.expense_documents expense on expense.id = operation.expense_document_id and expense.org_id = p_org_id
    left join public.employee_advances advance on advance.id = operation.employee_advance_id and advance.org_id = p_org_id
    left join public.payroll_slips payroll on payroll.id = operation.payroll_slip_id and payroll.org_id = p_org_id
    left join public.cheques cheque on cheque.id = operation.cheque_id and cheque.org_id = p_org_id
    left join public.bank_accounts bank on bank.org_id = p_org_id and bank.id = coalesce(operation.payment_bank_account_id, operation.receipt_bank_account_id, operation.bank_account_id)
    left join public.cash_boxes cash on cash.org_id = p_org_id and cash.id = coalesce(operation.payment_cash_box_id, operation.receipt_cash_box_id, operation.cash_box_id)
    left join public.petty_funds petty on petty.org_id = p_org_id and petty.id = coalesce(operation.payment_petty_fund_id, operation.receipt_petty_fund_id, operation.petty_fund_id)
    where operation.org_id = p_org_id
      and operation.operation_type <> 'transfer'
      and lower(coalesce(operation.status, '')) in ('received', 'approved', 'paid', 'settled', 'cleared', 'completed')
      and not (lower(coalesce(operation.payment_type, '')) = 'cheque' and lower(coalesce(cheque.status, '')) in ('bounced', 'returned'))
      and (
        operation.customer_id in (select id from scoped_customers)
        or operation.supplier_id in (select id from scoped_suppliers)
        or operation.sales_invoice_id in (select id from scoped_sales_invoices)
        or operation.purchase_invoice_id in (select id from scoped_purchase_invoices)
        or operation.expense_document_id in (select id from scoped_expense_documents)
        or operation.payroll_slip_id in (select id from scoped_payroll_slips)
        or operation.employee_advance_id in (select id from scoped_employee_advances)
        or exists (
          select 1 from scoped_employees employee
          where operation.employee_id = employee.id or operation.employee_id = employee.related_profile_id
        )
      )

    union all

    select
      case when source.operation_type = 'receipt' then 'receipt' else 'payment' end,
      source.source_label, source.module_id, source.id::text,
      coalesce(payment.item ->> 'payment_type', ''), coalesce(payment.item ->> 'status', 'received'), coalesce(payment.item ->> 'cheque_status', ''),
      public.financial_history_payment_event_date(payment.item),
      case when source.operation_type = 'payment' then public.financial_history_payment_amount(payment.item) else 0 end,
      case when source.operation_type = 'receipt' then public.financial_history_payment_amount(payment.item) else 0 end,
      source.invoice_label, '-', coalesce(payment.item ->> 'description', ''), source.created_at, null, null,
      'legacy_payment_' || source.module_id || '_' || source.id::text || '_' || payment.ordinality::text
    from (
      select 'invoices'::text module_id, 'receipt'::text operation_type, 'دریافت فاکتور فروش'::text source_label,
        i.id, i.invoice_date row_date, i.created_at, i.payments,
        coalesce(public.financial_history_document_reference(i.system_code, i.name), 'بدون عنوان') invoice_label
      from public.invoices i
      where i.org_id = p_org_id and i.customer_id in (select id from scoped_customers)
      union all
      select 'purchase_invoices', 'payment', 'پرداخت فاکتور خرید', i.id, i.invoice_date, i.created_at, i.payments,
        coalesce(public.financial_history_document_reference(i.system_code, i.name), 'بدون عنوان')
      from public.purchase_invoices i
      where i.org_id = p_org_id and i.supplier_id in (select id from scoped_suppliers)
      union all
      select 'expense_documents', 'payment', 'پرداخت هزینه', e.id, e.expense_date, e.created_at, e.payments,
        coalesce(public.financial_history_document_reference(e.system_code, e.name), 'بدون عنوان')
      from public.expense_documents e
      where e.org_id = p_org_id and (
        e.customer_id in (select id from scoped_customers)
        or e.supplier_id in (select id from scoped_suppliers)
        or e.employee_id in (select id from scoped_employees)
        or e.employee_id in (select related_profile_id from scoped_employees where related_profile_id is not null)
      )
      union all
      select 'payroll_slips', 'payment', 'پرداخت فیش حقوقی', p.id, p.period_end, p.created_at, p.payments,
        coalesce(public.financial_history_document_reference(p.system_code, p.name), 'بدون عنوان')
      from public.payroll_slips p
      where p.org_id = p_org_id and p.employee_id in (select id from scoped_employees)
    ) source
    cross join lateral jsonb_array_elements(coalesce(source.payments, '[]'::jsonb)) with ordinality payment(item, ordinality)
    where public.financial_history_payment_is_final(payment.item)
      and public.financial_history_payment_amount(payment.item) > 0
      -- مساعدهٔ متصل به فیش، همان پرداخت مساعده است و ردیف جداگانهٔ نقد/بانک نمی‌سازد.
      and not (source.module_id = 'payroll_slips' and nullif(trim(coalesce(payment.item ->> 'employee_advance_id', '')), '') is not null)
      and not exists (
        select 1
        from public.cash_bank_operations operation
        where operation.org_id = p_org_id
          and lower(coalesce(operation.status, '')) <> 'canceled'
          and (
            operation.id::text = nullif(payment.item ->> '_cash_bank_operation_id', '')
            or (
              operation.metadata ->> 'source_table' = source.module_id
              and operation.metadata ->> 'source_record_id' = source.id::text
              and operation.metadata ->> 'source_row_key' = coalesce(
                nullif(payment.item ->> 'row_key', ''),
                nullif(payment.item ->> '_cash_bank_operation_id', ''),
                'legacy_' || (payment.ordinality - 1)::text
              )
            )
          )
      )

    union all

    select
      'payment', 'پرداخت مساعده', 'employee_advances', advance.id::text,
      coalesce(payment.item ->> 'payment_type', 'credit'), coalesce(payment.item ->> 'status', advance.status), coalesce(payment.item ->> 'cheque_status', ''),
      public.financial_history_payment_event_date(payment.item),
      public.financial_history_payment_amount(payment.item), 0,
      coalesce(public.financial_history_document_reference(advance.system_code, advance.name), 'بدون عنوان'), '-',
      coalesce(payment.item ->> 'description', 'پرداخت مساعده'), advance.created_at, null, null,
      'advance_payment_' || advance.id::text || '_' || payment.ordinality::text
    from public.employee_advances advance
    cross join lateral (
      select item, ordinality
      from jsonb_array_elements(coalesce(advance.payments, '[]'::jsonb)) with ordinality payment_source(item, ordinality)
      union all
      select jsonb_build_object('amount', advance.paid_amount, 'status', advance.status), 0::bigint
      where jsonb_array_length(coalesce(advance.payments, '[]'::jsonb)) = 0
        and coalesce(advance.paid_amount, 0) > 0
    ) payment(item, ordinality)
    where advance.org_id = p_org_id
      and advance.employee_id in (select id from scoped_employees)
      and lower(coalesce(advance.status, '')) in ('paid', 'settled', 'completed', 'posted')
      and public.financial_history_payment_is_final(payment.item)
      and public.financial_history_payment_amount(payment.item) > 0
      and not exists (
        select 1
        from public.cash_bank_operations operation
        where operation.org_id = p_org_id
          and lower(coalesce(operation.status, '')) <> 'canceled'
          and (
            operation.id::text = nullif(payment.item ->> '_cash_bank_operation_id', '')
            or operation.employee_advance_id = advance.id
            or (
              operation.metadata ->> 'source_table' = 'employee_advances'
              and operation.metadata ->> 'source_record_id' = advance.id::text
              and operation.metadata ->> 'source_row_key' = coalesce(
                nullif(payment.item ->> 'row_key', ''),
                nullif(payment.item ->> '_cash_bank_operation_id', ''),
                'legacy_' || greatest(payment.ordinality - 1, 0)::text
              )
            )
          )
      )
  ), ranked_rows as (
    select
      raw_rows.*,
      sum(coalesce(raw_rows.debit, 0) - coalesce(raw_rows.credit, 0)) over (
        order by (raw_rows.row_type = 'opening') desc, coalesce(raw_rows.row_date, raw_rows.created_at::date), raw_rows.key
        rows between unbounded preceding and current row
      ) balance
    from raw_rows
  )
  select jsonb_build_object(
    'rows', coalesce(
      jsonb_agg(jsonb_build_object(
        'key', key,
        'row_type', row_type,
        'source_label', source_label,
        'source_module_id', source_module_id,
        'source_record_id', source_record_id,
        'payment_type', payment_type,
        'status', status,
        'cheque_status', cheque_status,
        'date', row_date,
        'debit', debit,
        'credit', credit,
        'balance', balance,
        'invoice_label', invoice_label,
        'bank_label', bank_label,
        'description', description,
        'created_at', created_at,
        'bank_module_id', bank_module_id,
        'bank_record_id', bank_record_id
      ) order by (row_type = 'opening') desc, coalesce(row_date, created_at::date), key),
      '[]'::jsonb
    ),
    'summary', jsonb_build_object(
      'total_debit', coalesce(sum(debit), 0),
      'total_credit', coalesce(sum(credit), 0),
      'final_balance', coalesce(sum(debit - credit), 0),
      'source', 'central_financial_history'
    )
  ) into v_result
  from ranked_rows;

  return coalesce(v_result, jsonb_build_object(
    'rows', '[]'::jsonb,
    'summary', jsonb_build_object('total_debit', 0, 'total_credit', 0, 'final_balance', 0, 'source', 'central_financial_history')
  ));
end;
$$;


--
-- Name: _normalize_phone_for_match(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._normalize_phone_for_match(p_raw text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN d LIKE '0098%'                      THEN '0' || substring(d FROM 5)
    WHEN length(d) = 12 AND d LIKE '98%'     THEN '0' || substring(d FROM 3)
    WHEN length(d) = 10 AND d LIKE '9%'      THEN '0' || d
    ELSE d
  END
  FROM (
    SELECT regexp_replace(
      translate(COALESCE(p_raw, ''), '۰۱۲۳۴۵۶۷۸۹', '0123456789'),
      '[^0-9]', '', 'g'
    ) AS d
  ) sub
$$;


--
-- Name: _release_payroll_sources_internal(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._release_payroll_sources_internal(p_org_id uuid, p_payroll_slip_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_snapshot jsonb := '{}'::jsonb;
begin
  if p_org_id is null or p_payroll_slip_id is null then
    return;
  end if;

  perform set_config('app.payroll_source_sync', 'active', true);

  select coalesce(performance_snapshot, '{}'::jsonb)
    into v_snapshot
  from public.payroll_slips
  where id = p_payroll_slip_id
    and org_id = p_org_id;

  with linked_commission_entries as (
    select entry.*
    from public.payroll_calculation_entries entry
    where entry.org_id = p_org_id
      and entry.source_type = 'commission'
      and (
        entry.payroll_slip_id = p_payroll_slip_id
        or entry.id in (
          select snapshot_entry.value::uuid
          from jsonb_array_elements_text(coalesce(v_snapshot->'payroll_ledger_entry_ids', '[]'::jsonb)) as snapshot_entry(value)
          where snapshot_entry.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        )
      )
  ), released_commission_keys as (
    select distinct nullif(trim(payroll_line.value->>'source_key'), '') as source_key
    from linked_commission_entries entry
    cross join lateral jsonb_array_elements(coalesce(entry.details->'rows', '[]'::jsonb)) as invoice_row(value)
    cross join lateral jsonb_array_elements(coalesce(invoice_row.value->'lines', '[]'::jsonb)) as payroll_line(value)
  ), released_commission_scopes as (
    select distinct
      entry.employee_id,
      entry.period_start,
      entry.period_end,
      nullif(trim(entry.details->>'basis'), '') as source_basis,
      nullif(trim(entry.details->>'percent_mode'), '') as percent_mode
    from linked_commission_entries entry
  )
  update public.commission_drafts draft
  set
    posted_amount = 0,
    remaining_amount = greatest(0, coalesce(draft.entitled_amount, 0)),
    draft_status = 'draft',
    updated_at = now()
  where draft.org_id = p_org_id
    and (
      draft.source_key in (select source_key from released_commission_keys where source_key is not null)
      or exists (
        select 1
        from released_commission_scopes scope
        where scope.employee_id = draft.employee_id
          and scope.period_start = draft.period_start
          and scope.period_end = draft.period_end
          and scope.source_basis = draft.source_basis
          and scope.percent_mode = draft.percent_mode
      )
    );

  update public.payroll_calculation_entries entry
  set
    status = case when entry.status = 'included_in_payroll' then 'draft' else entry.status end,
    payroll_slip_id = null,
    updated_at = now()
  where entry.org_id = p_org_id
    and (
      entry.payroll_slip_id = p_payroll_slip_id
      or entry.id in (
        select snapshot_entry.value::uuid
        from jsonb_array_elements_text(coalesce(v_snapshot->'payroll_ledger_entry_ids', '[]'::jsonb)) as snapshot_entry(value)
        where snapshot_entry.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
    );

  update public.employee_bonus_requests
  set related_payroll_slip_id = null, updated_at = now()
  where org_id = p_org_id and related_payroll_slip_id = p_payroll_slip_id;

  update public.employee_penalty_requests
  set related_payroll_slip_id = null, updated_at = now()
  where org_id = p_org_id and related_payroll_slip_id = p_payroll_slip_id;

  update public.employee_advances advance
  set related_payroll_slip_id = null, updated_at = now()
  where advance.org_id = p_org_id
    and (
      advance.related_payroll_slip_id = p_payroll_slip_id
      or advance.id in (
        select snapshot_entry.value::uuid
        from jsonb_array_elements_text(coalesce(v_snapshot->'employee_advance_ids', '[]'::jsonb)) as snapshot_entry(value)
        where snapshot_entry.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
    );
end;
$_$;


--
-- Name: _resolve_org_for_public_delivery(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._resolve_org_for_public_delivery(p_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_org_id uuid;
begin
  if p_code is null or p_code !~ '^[0-9A-Za-z]{8,64}$' then return null; end if;
  select d.org_id into v_org_id from public.delivery_forms d where d.public_slug = p_code or d.public_token = p_code limit 1;
  return v_org_id;
end;
$_$;


--
-- Name: _resolve_org_for_public_invoice(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._resolve_org_for_public_invoice(p_system_code text, p_module text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid;
begin
  if p_system_code is null
     or p_system_code !~ '^[0-9A-Za-z]{8,64}$'
     or p_module not in ('invoices', 'purchase_invoices') then
    return null;
  end if;

  if p_module = 'invoices' then
    select i.org_id
    into v_org_id
    from public.invoices i
    where i.public_slug = p_system_code
       or i.public_token = p_system_code
    limit 1;
  else
    select i.org_id
    into v_org_id
    from public.purchase_invoices i
    where i.public_slug = p_system_code
       or i.public_token = p_system_code
    limit 1;
  end if;

  return v_org_id;
end;
$_$;


--
-- Name: _resolve_web_form_link_context(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._resolve_web_form_link_context(p_access_token text, p_web_form_id uuid DEFAULT NULL::uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_token text := lower(trim(coalesce(p_access_token, '')));
  v_row public.web_form_link_tokens%rowtype;
begin
  if v_token = '' then
    return '{}'::jsonb;
  end if;

  select *
    into v_row
  from public.web_form_link_tokens
  where access_token = v_token
  limit 1;

  if v_row.id is null then
    raise exception 'WEB_FORM_TOKEN_INVALID';
  end if;

  if v_row.expires_at <= now() then
    raise exception 'WEB_FORM_TOKEN_EXPIRED';
  end if;

  if p_web_form_id is not null and v_row.web_form_id is distinct from p_web_form_id then
    raise exception 'WEB_FORM_TOKEN_MISMATCH';
  end if;

  if p_org_id is not null and v_row.org_id is distinct from p_org_id then
    raise exception 'WEB_FORM_TOKEN_ORG_MISMATCH';
  end if;

  return jsonb_build_object(
    'token_id', v_row.id,
    'org_id', v_row.org_id,
    'web_form_id', v_row.web_form_id,
    'target_module_id', v_row.target_module_id,
    'related_module_id', v_row.related_module_id,
    'related_record_id', v_row.related_record_id,
    'expires_at', v_row.expires_at
  );
end;
$$;


--
-- Name: _sync_customer_financial_stats_for_org(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sync_customer_financial_stats_for_org(p_org_id uuid, p_customer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer record;
  v_history jsonb;
  v_summary jsonb;
  v_current_count numeric(18,3) := 0;
  v_current_purchase_total numeric(18,2) := 0;
  v_current_first date;
  v_current_last date;
  v_first date;
  v_last date;
begin
  if p_org_id is null or p_customer_id is null then return; end if;

  -- قفل رکوردهای مشتری حفظ می‌شود؛ فقط همین فیلدهای مشتق‌شده با context داخلی
  -- و محدود، برای همگام‌سازی دفتر مالی اجازهٔ تغییر دارند.
  perform set_config('app.financial_summary_sync', 'active', true);

  select * into v_customer
  from public.customers
  where id = p_customer_id and org_id = p_org_id;
  if not found then return; end if;

  select
    count(*)::numeric(18,3),
    coalesce(sum(coalesce(total_invoice_amount, 0)), 0),
    min(coalesce(invoice_date, created_at::date)),
    max(coalesce(invoice_date, created_at::date))
  into v_current_count, v_current_purchase_total, v_current_first, v_current_last
  from public.invoices
  where org_id = p_org_id
    and customer_id = p_customer_id
    and public.is_customer_purchase_status(status);

  v_history := public._get_operational_financial_history(p_org_id, 'customer', p_customer_id);
  v_summary := coalesce(v_history -> 'summary', '{}'::jsonb);
  v_first := least(coalesce(v_customer.previous_system_first_purchase_date, v_current_first), coalesce(v_current_first, v_customer.previous_system_first_purchase_date));
  v_last := greatest(coalesce(v_customer.previous_system_last_purchase_date, v_current_last), coalesce(v_current_last, v_customer.previous_system_last_purchase_date));

  update public.customers
  set
    first_purchase_date = v_first,
    last_purchase_date = v_last,
    purchase_count = coalesce(v_customer.previous_system_purchase_count, 0) + coalesce(v_current_count, 0),
    loyalty_total_spend = coalesce(v_customer.previous_system_invoice_total, 0) + coalesce(v_current_purchase_total, 0),
    total_spend = coalesce(nullif(v_summary ->> 'total_debit', '')::numeric, 0),
    total_paid_amount = coalesce(nullif(v_summary ->> 'total_credit', '')::numeric, 0),
    total_balance = coalesce(nullif(v_summary ->> 'final_balance', '')::numeric, 0),
    acquaintance_days = case when v_first is null then null else greatest(0, current_date - v_first) end,
    cooperation_days = case when v_first is null or v_last is null then null else greatest(0, v_last - v_first) end
  where id = p_customer_id and org_id = p_org_id;
end;
$$;


--
-- Name: acquire_ai_image_worker_lease(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_ai_image_worker_lease(p_lease_seconds integer DEFAULT 1020) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_token uuid;
  v_lease_seconds integer := least(greatest(coalesce(p_lease_seconds, 1020), 300), 1800);
begin
  insert into public.ai_image_worker_execution_leases (
    lease_key,
    lease_token,
    lease_expires_at,
    updated_at
  )
  values (
    'ai-image-worker',
    gen_random_uuid(),
    now() + make_interval(secs => v_lease_seconds),
    now()
  )
  on conflict (lease_key) do update
  set
    lease_token = excluded.lease_token,
    lease_expires_at = excluded.lease_expires_at,
    updated_at = now()
  where public.ai_image_worker_execution_leases.lease_expires_at <= now()
  returning lease_token into v_token;

  return v_token;
end;
$$;


--
-- Name: acquire_workflow_runner_lease(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acquire_workflow_runner_lease(p_lease_seconds integer DEFAULT 240) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_token uuid;
  v_lease_seconds integer := least(greatest(coalesce(p_lease_seconds, 240), 60), 600);
begin
  insert into public.workflow_runner_execution_leases (
    lease_key,
    lease_token,
    lease_expires_at,
    updated_at
  )
  values (
    'workflow-interval-runner',
    gen_random_uuid(),
    now() + make_interval(secs => v_lease_seconds),
    now()
  )
  on conflict (lease_key) do update
  set
    lease_token = excluded.lease_token,
    lease_expires_at = excluded.lease_expires_at,
    updated_at = excluded.updated_at
  where public.workflow_runner_execution_leases.lease_expires_at <= now()
  returning lease_token into v_token;

  return v_token;
end;
$$;


--
-- Name: activate_current_user_organization(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_current_user_organization(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists(select 1 from public.user_organization_memberships m
    join public.organizations o on o.id=m.org_id and o.is_active
    where m.user_id=auth.uid() and m.org_id=p_org_id and m.is_active)
  then raise exception 'دسترسی شما به این سازمان فعال نیست.' using errcode='42501'; end if;
  return jsonb_build_object('success',true,'org_id',p_org_id,'organization_name',public.organization_display_name(p_org_id),
    'resolved_host',public.organization_access_host(p_org_id));
end;
$$;


--
-- Name: activate_process_run_nodes(uuid, uuid, text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_process_run_nodes(p_org_id uuid, p_process_run_id uuid, p_node_keys text[], p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_current_org_id uuid;
  v_run public.process_runs%rowtype;
  v_stage public.process_run_stages%rowtype;
  v_reference_stage public.process_run_stages%rowtype;
  v_task_id uuid;
  v_created_task_ids uuid[] := '{}'::uuid[];
  v_existing_task_ids uuid[] := '{}'::uuid[];
  v_metadata jsonb;
  v_graph jsonb;
  v_anchor_type text;
  v_anchor_node_key text;
  v_parent_trigger_key text;
  v_reference_node_key text;
  v_anchor_at timestamptz;
  v_due_at timestamptz;
  v_start_at timestamptz;
  v_duration_value numeric;
  v_duration_unit text;
  v_recurrence jsonb;
  v_actor_user_id uuid;
begin
  v_current_org_id := public.current_org_id();
  if coalesce(auth.role(), '') <> 'service_role' then
    if auth.uid() is null
      or p_org_id is null
      or v_current_org_id is null
      or p_org_id <> v_current_org_id then
      raise exception 'دسترسی فعال‌سازی مراحل این فرآیند وجود ندارد.' using errcode = '42501';
    end if;
  end if;

  select * into v_run
  from public.process_runs r
  where r.id = p_process_run_id and r.org_id = p_org_id;
  if v_run.id is null then
    raise exception 'اجرای فرآیند برای سازمان جاری پیدا نشد.' using errcode = 'P0001';
  end if;

  v_actor_user_id := coalesce(p_actor_user_id, auth.uid());
  if v_actor_user_id is not null and not exists (
    select 1 from public.profiles p where p.id = v_actor_user_id and p.org_id = p_org_id
  ) then
    v_actor_user_id := null;
  end if;

  for v_stage in
    select s.*
    from public.process_run_stages s
    where s.process_run_id = p_process_run_id
      and coalesce(s.process_node_key, s.metadata ->> 'process_node_key') = any(coalesce(p_node_keys, '{}'::text[]))
    order by coalesce(s.process_lane_key, s.metadata ->> 'process_lane_key', 'lane_1'), s.sort_order, s.created_at
    for update
  loop
    if v_stage.task_id is not null then
      v_existing_task_ids := array_append(v_existing_task_ids, v_stage.task_id);
      continue;
    end if;

    v_metadata := coalesce(v_stage.metadata, '{}'::jsonb);
    v_graph := coalesce(v_metadata -> 'process_graph', '{}'::jsonb);
    v_anchor_type := coalesce(
      nullif(v_metadata ->> 'due_anchor_type', ''),
      case coalesce(v_metadata ->> 'duration_from', '')
        when 'project_start' then 'process_start'
        when 'previous_stage_end' then 'previous_stage_due'
        else null
      end,
      'process_start'
    );
    v_anchor_node_key := nullif(v_metadata ->> 'due_anchor_stage_node_key', '');
    v_reference_node_key := null;
    v_anchor_at := null;

    if v_anchor_type in ('specific_stage_due', 'specific_stage_completed') then
      v_reference_node_key := v_anchor_node_key;
    elsif v_anchor_type in ('previous_stage_due', 'previous_stage_completed') then
      select s.process_node_key into v_reference_node_key
      from public.process_run_stages s
      where s.process_run_id = p_process_run_id
        and coalesce(s.process_lane_key, s.metadata ->> 'process_lane_key', 'lane_1')
          = coalesce(v_stage.process_lane_key, v_stage.metadata ->> 'process_lane_key', 'lane_1')
        and s.sort_order < v_stage.sort_order
      order by s.sort_order desc, s.created_at desc limit 1;

      if v_reference_node_key is null and jsonb_typeof(v_graph -> 'lanes') = 'array' then
        select nullif(lane ->> 'parentTriggerKey', '') into v_parent_trigger_key
        from jsonb_array_elements(v_graph -> 'lanes') lane
        where lane ->> 'key' = coalesce(v_stage.process_lane_key, v_stage.metadata ->> 'process_lane_key', 'lane_1')
        limit 1;
        if v_parent_trigger_key is not null and jsonb_typeof(v_graph -> 'triggers') = 'array' then
          select nullif(trigger_row ->> 'sourceNodeKey', '') into v_reference_node_key
          from jsonb_array_elements(v_graph -> 'triggers') trigger_row
          where trigger_row ->> 'key' = v_parent_trigger_key
          limit 1;
        end if;
      end if;
    end if;

    if v_reference_node_key is not null then
      select s.* into v_reference_stage
      from public.process_run_stages s
      where s.process_run_id = p_process_run_id
        and coalesce(s.process_node_key, s.metadata ->> 'process_node_key') = v_reference_node_key
      limit 1;
      if v_anchor_type in ('previous_stage_due', 'specific_stage_due') then
        select coalesce(t.due_date, v_reference_stage.planned_due_at) into v_anchor_at
        from (select 1) seed left join public.tasks t on t.id = v_reference_stage.task_id;
      elsif v_anchor_type in ('previous_stage_completed', 'specific_stage_completed') then
        select coalesce(t.completed_at, t.actual_end_at, v_reference_stage.completed_at) into v_anchor_at
        from (select 1) seed left join public.tasks t on t.id = v_reference_stage.task_id;
      end if;
    elsif v_anchor_type = 'process_start' then
      v_anchor_at := coalesce(v_run.started_at, v_run.created_at, now());
    end if;

    v_duration_value := greatest(0, coalesce(nullif(v_metadata ->> 'duration_value', '')::numeric, 0));
    v_duration_unit := case when v_metadata ->> 'duration_unit' = 'hour' then 'hour' else 'day' end;
    v_due_at := case
      when v_anchor_at is null then null
      when v_duration_value <= 0 then v_anchor_at
      when v_duration_unit = 'hour' then v_anchor_at + make_interval(hours => v_duration_value::integer)
      else v_anchor_at + make_interval(days => v_duration_value::integer)
    end;
    v_start_at := nullif(v_metadata ->> 'start_date', '')::timestamptz;

    v_recurrence := coalesce(v_metadata -> 'recurrence_info', '{}'::jsonb)
      || jsonb_build_object(
        'task_type', nullif(v_metadata ->> 'task_type', ''),
        'process_automation_rules', coalesce(v_metadata -> 'automation_rules', '[]'::jsonb),
        'process_target_module_ids', coalesce(v_metadata -> 'process_target_module_ids', '[]'::jsonb),
        'process_links', coalesce(v_metadata -> 'process_link_map', jsonb_build_object(v_run.module_id, v_run.record_id)),
        'process_run_id', v_run.id,
        'process_run_stage_id', v_stage.id,
        'process_node_key', coalesce(v_stage.process_node_key, v_metadata ->> 'process_node_key'),
        'process_lane_key', coalesce(v_stage.process_lane_key, v_metadata ->> 'process_lane_key', 'lane_1'),
        'process_graph', coalesce(v_metadata -> 'process_graph', '{}'::jsonb),
        'process_task_custom_fields', coalesce(v_metadata -> 'process_task_custom_fields', '[]'::jsonb),
        'process_task_status_options', coalesce(v_metadata -> 'process_task_status_options', '[]'::jsonb),
        'process_task_custom_field_values', coalesce(v_metadata -> 'process_task_custom_field_values', '{}'::jsonb),
        'due_anchor_type', nullif(v_metadata ->> 'due_anchor_type', ''),
        'due_anchor_stage_node_key', nullif(v_metadata ->> 'due_anchor_stage_node_key', ''),
        'duration_value', coalesce(nullif(v_metadata ->> 'duration_value', '')::numeric, 0),
        'duration_unit', coalesce(nullif(v_metadata ->> 'duration_unit', ''), 'day'),
        'start_date', v_start_at,
        'start_duration_from', nullif(v_metadata ->> 'start_duration_from', ''),
        'start_duration_value', coalesce(nullif(v_metadata ->> 'start_duration_value', '')::numeric, 0),
        'start_duration_unit', coalesce(nullif(v_metadata ->> 'start_duration_unit', ''), 'day'),
        'start_anchor_stage_node_key', nullif(v_metadata ->> 'start_anchor_stage_node_key', ''),
        'process_group', jsonb_build_object('id', v_run.process_group_id, 'name', v_run.process_name, 'template_id', v_run.template_id)
      );

    insert into public.tasks (
      org_id, name, status, priority, description, task_type,
      assignee_id, assignee_role_id, assignee_type, wage, weight, tags,
      sort_order, due_date, start_date, source_template_id, source_stage_sort_order,
      process_group_id, process_run_id, process_run_stage_id, process_node_key, process_lane_key,
      source_module_id, source_record_id, related_to_module, project_id, marketing_lead_id,
      related_customer, related_invoice, purchase_invoice_id, related_production_order,
      recurrence_info, created_by, updated_by
    ) values (
      p_org_id, v_stage.stage_name, 'todo', coalesce(nullif(v_metadata ->> 'priority', ''), 'medium'),
      nullif(v_metadata ->> 'description', ''), nullif(v_metadata ->> 'task_type', ''),
      v_stage.assignee_user_id, v_stage.assignee_role_id,
      case when v_stage.assignee_role_id is not null then 'role' when v_stage.assignee_user_id is not null then 'user' else null end,
      coalesce(v_stage.wage, 0), coalesce(nullif(v_metadata ->> 'weight', '')::numeric, 0), coalesce(v_metadata -> 'tags', '[]'::jsonb),
      v_stage.sort_order, v_due_at, v_start_at, v_run.template_id, v_stage.sort_order,
      v_run.process_group_id, v_run.id, v_stage.id,
      coalesce(v_stage.process_node_key, v_metadata ->> 'process_node_key'), coalesce(v_stage.process_lane_key, v_metadata ->> 'process_lane_key', 'lane_1'),
      v_run.module_id, v_run.record_id, v_run.module_id,
      case when v_run.module_id = 'projects' then v_run.record_id else null end,
      case when v_run.module_id = 'marketing_leads' then v_run.record_id else null end,
      case when v_run.module_id = 'customers' then v_run.record_id else null end,
      case when v_run.module_id = 'invoices' then v_run.record_id else null end,
      case when v_run.module_id = 'purchase_invoices' then v_run.record_id else null end,
      case when v_run.module_id = 'production_orders' then v_run.record_id else null end,
      v_recurrence, v_actor_user_id, v_actor_user_id
    ) returning id into v_task_id;

    update public.process_run_stages
    set task_id = v_task_id, planned_due_at = v_due_at, updated_at = now()
    where id = v_stage.id;
    v_created_task_ids := array_append(v_created_task_ids, v_task_id);
  end loop;

  return jsonb_build_object(
    'process_run_id', p_process_run_id,
    'created_task_ids', to_jsonb(v_created_task_ids),
    'existing_task_ids', to_jsonb(v_existing_task_ids)
  );
end;
$$;


--
-- Name: activate_saas_admin_panel_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_saas_admin_panel_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org uuid;
begin
  select s.org_id into v_org from public.saas_org_settings s where s.is_billing_provider
    and lower(s.resolved_host)='panel.tazesystem.ir' limit 1;
  if not exists(select 1 from public.user_organization_memberships m
    join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
    where m.user_id=auth.uid() and m.org_id=v_org and m.is_active
      and coalesce((r.permissions->'__saas_admin'->>'view')::boolean,false)) then
    -- Preserve the existing explicitly granted SaaS-admin eligibility, without moving identity.
    if not exists(select 1 from public.user_organization_memberships m
      join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
      where m.user_id=auth.uid() and m.is_active
        and public.org_is_saas_admin(m.org_id)
        and coalesce((r.permissions->'__saas_admin'->>'view')::boolean,false)) then
      raise exception 'دسترسی به پنل مدیریت تازه سیستم برای این حساب فعال نیست.' using errcode='42501';
    end if;
    insert into public.user_organization_memberships(user_id,org_id,role_id,software_role,is_active)
    select auth.uid(),v_org,r.id,'admin',true from public.org_roles r where r.org_id=v_org
      and coalesce((r.permissions->'__saas_admin'->>'view')::boolean,false) order by r.created_at limit 1
    on conflict(user_id,org_id) do nothing;
  end if;
  return public.activate_current_user_organization(v_org);
end;
$$;


--
-- Name: activate_saas_order_items(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_saas_order_items(p_order_id uuid, p_payment_transaction_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT 'online'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare order_row public.saas_orders%rowtype; entry record; inner_entry record; catalog_row public.saas_catalog_items%rowtype; subscription_row public.saas_recurring_subscriptions%rowtype; item_quantity numeric; item_amount numeric; cycle text; now_at timestamptz := now();
begin
  select * into order_row from public.saas_orders where id=p_order_id for update;
  if order_row.id is null then raise exception 'saas_order_not_found'; end if;
  if order_row.status='paid' then return jsonb_build_object('success',true,'already_applied',true); end if;
  for entry in select value from jsonb_array_elements(order_row.items) loop
    item_quantity := greatest(coalesce((entry.value ->> 'quantity')::numeric,1),1);
    if entry.value ->> 'item_kind' = 'plan' then
      update public.saas_org_settings set plan_code=entry.value ->> 'entitlement_code', is_readonly=case when is_demo then false else is_readonly end, is_demo=false, trial_ends_at=null, status=case when status in ('draft','trial','demo') then 'active' else status end, billing_readonly=false, billing_readonly_at=null, updated_at=now() where org_id=order_row.org_id;
      update public.saas_recurring_subscriptions set status='cancelled', updated_at=now() where org_id=order_row.org_id and item_kind='plan' and status in ('active','grace');
      insert into public.saas_recurring_subscriptions(org_id,item_kind,source_code,entitlement_code,quantity,amount_irt,status,current_period_starts_at,current_period_ends_at,next_invoice_at,source_order_id,metadata) values(order_row.org_id,'plan','plan:'||(entry.value ->> 'entitlement_code'),entry.value ->> 'entitlement_code',greatest(3,coalesce((entry.value -> 'metadata' ->> 'billable_users')::integer,1)),greatest(coalesce((entry.value ->> 'line_total_irt')::numeric,(entry.value ->> 'unit_price_irt')::numeric,0),0),'active',now_at,now_at+interval '30 days',now_at+interval '23 days',order_row.id,jsonb_build_object('payment_method',p_payment_method,'payment_transaction_id',p_payment_transaction_id));
    elsif entry.value ->> 'item_kind' = 'bundle' then
      select * into catalog_row from public.saas_catalog_items where code=entry.value ->> 'code' limit 1;
      cycle := coalesce(catalog_row.billing_cycle, entry.value ->> 'billing_cycle', 'one_time');
      if cycle='monthly' then
        select * into subscription_row from public.saas_recurring_subscriptions where org_id=order_row.org_id and item_kind='bundle' and source_code=entry.value ->> 'code' and status in ('active','grace') for update;
        if subscription_row.id is null then
          insert into public.saas_recurring_subscriptions(org_id,item_kind,source_code,entitlement_code,quantity,amount_irt,status,current_period_starts_at,current_period_ends_at,next_invoice_at,source_order_id,metadata) values(order_row.org_id,'bundle',entry.value ->> 'code',entry.value ->> 'entitlement_code',item_quantity,greatest(coalesce((entry.value ->> 'line_total_irt')::numeric,0),0),'active',now_at,now_at+interval '30 days',now_at+interval '23 days',order_row.id,coalesce(catalog_row.metadata,entry.value -> 'metadata','{}'::jsonb) || jsonb_build_object('payment_method',p_payment_method,'payment_transaction_id',p_payment_transaction_id)) returning * into subscription_row;
        else
          update public.saas_recurring_subscriptions set quantity=quantity+item_quantity, amount_irt=amount_irt+greatest(coalesce((entry.value ->> 'line_total_irt')::numeric,0),0), current_period_ends_at=greatest(current_period_ends_at,now_at+interval '30 days'), next_invoice_at=greatest(next_invoice_at,now_at+interval '23 days'), updated_at=now() where id=subscription_row.id returning * into subscription_row;
        end if;
        perform public.refresh_saas_subscription_entitlement(subscription_row.id);
      else
        for inner_entry in select value from jsonb_array_elements(coalesce(catalog_row.metadata -> 'included_items', entry.value -> 'metadata' -> 'included_items','[]'::jsonb)) loop
          insert into public.saas_org_entitlements(org_id,item_kind,entitlement_code,quantity,state,source,order_id,created_by,metadata) values(order_row.org_id,inner_entry.value ->> 'item_kind',inner_entry.value ->> 'entitlement_code',coalesce((inner_entry.value ->> 'quantity')::numeric,1),'enabled','purchase',order_row.id,order_row.created_by,jsonb_build_object('bundle_code',entry.value ->> 'code','payment_transaction_id',p_payment_transaction_id,'payment_method',p_payment_method));
        end loop;
      end if;
    else
      select * into catalog_row from public.saas_catalog_items where code=entry.value ->> 'code' limit 1;
      cycle := coalesce(catalog_row.billing_cycle,entry.value ->> 'billing_cycle','one_time');
      if cycle='monthly' then
        select * into subscription_row from public.saas_recurring_subscriptions where org_id=order_row.org_id and item_kind=entry.value ->> 'item_kind' and source_code=entry.value ->> 'code' and status in ('active','grace') for update;
        if subscription_row.id is null then
          insert into public.saas_recurring_subscriptions(org_id,item_kind,source_code,entitlement_code,quantity,amount_irt,status,current_period_starts_at,current_period_ends_at,next_invoice_at,source_order_id,metadata) values(order_row.org_id,entry.value ->> 'item_kind',entry.value ->> 'code',entry.value ->> 'entitlement_code',item_quantity,greatest(coalesce((entry.value ->> 'line_total_irt')::numeric,0),0),'active',now_at,now_at+interval '30 days',now_at+interval '23 days',order_row.id,jsonb_build_object('payment_method',p_payment_method,'payment_transaction_id',p_payment_transaction_id)) returning * into subscription_row;
        else update public.saas_recurring_subscriptions set quantity=quantity+item_quantity, amount_irt=amount_irt+greatest(coalesce((entry.value ->> 'line_total_irt')::numeric,0),0), current_period_ends_at=greatest(current_period_ends_at,now_at+interval '30 days'), next_invoice_at=greatest(next_invoice_at,now_at+interval '23 days'), updated_at=now() where id=subscription_row.id returning * into subscription_row; end if;
        perform public.refresh_saas_subscription_entitlement(subscription_row.id);
      else
        insert into public.saas_org_entitlements(org_id,item_kind,entitlement_code,quantity,state,source,order_id,created_by,metadata) values(order_row.org_id,entry.value ->> 'item_kind',entry.value ->> 'entitlement_code',item_quantity,'enabled','purchase',order_row.id,order_row.created_by,jsonb_build_object('payment_transaction_id',p_payment_transaction_id,'payment_method',p_payment_method));
      end if;
    end if;
  end loop;
  update public.saas_orders set status='paid', payment_transaction_id=coalesce(p_payment_transaction_id,payment_transaction_id), paid_at=now(), metadata=metadata || jsonb_build_object('payment_method',p_payment_method), updated_at=now() where id=order_row.id;
  return jsonb_build_object('success',true,'order_id',order_row.id);
end; $$;


--
-- Name: activate_saas_subscription_invoice(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_saas_subscription_invoice(p_invoice_id uuid, p_payment_transaction_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT 'online'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare invoice_row public.saas_subscription_invoices%rowtype; subscription_row public.saas_recurring_subscriptions%rowtype;
begin
  select * into invoice_row from public.saas_subscription_invoices where id = p_invoice_id for update;
  if invoice_row.id is null then raise exception 'saas_subscription_invoice_not_found'; end if;
  if invoice_row.status = 'paid' then return jsonb_build_object('success', true, 'already_applied', true); end if;
  if invoice_row.status not in ('issued', 'overdue') then raise exception 'saas_subscription_invoice_not_payable'; end if;
  select * into subscription_row from public.saas_recurring_subscriptions where id = invoice_row.subscription_id for update;
  if subscription_row.id is null then raise exception 'saas_subscription_not_found'; end if;
  update public.saas_subscription_invoices set status = 'paid', payment_transaction_id = coalesce(p_payment_transaction_id, payment_transaction_id), paid_at = now(), metadata = metadata || jsonb_build_object('payment_method', p_payment_method), updated_at = now() where id = invoice_row.id;
  update public.saas_recurring_subscriptions set status = 'active', current_period_starts_at = invoice_row.period_starts_at, current_period_ends_at = invoice_row.period_ends_at, next_invoice_at = invoice_row.period_ends_at - interval '7 days', last_invoice_at = now(), updated_at = now() where id = subscription_row.id;
  if subscription_row.item_kind = 'plan' then
    update public.saas_org_settings set billing_readonly = false, billing_readonly_at = null, status = case when status = 'past_due' then 'active' else status end, updated_at = now() where org_id = subscription_row.org_id;
  else
    perform public.refresh_saas_subscription_entitlement(subscription_row.id);
  end if;
  return jsonb_build_object('success', true, 'invoice_id', invoice_row.id);
end; $$;


--
-- Name: admin_adjust_saas_org_account(uuid, numeric, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_adjust_saas_org_account(p_org_id uuid, p_sms_delta numeric DEFAULT 0, p_ai_delta_irt numeric DEFAULT 0, p_billing_wallet_delta_irt numeric DEFAULT 0, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sms numeric := coalesce(p_sms_delta,0);
  v_ai numeric := coalesce(p_ai_delta_irt,0);
  v_wallet numeric := coalesce(p_billing_wallet_delta_irt,0);
  v_reason text := coalesce(nullif(trim(p_reason),''),'تغییر دستی مدیر تازه سیستم');
  v_wallet_row public.org_sms_wallets%rowtype;
  v_ai_row public.org_ai_wallets%rowtype;
  v_billing_row public.org_billing_wallets%rowtype;
begin
  if not public.current_user_has_saas_admin_permission('edit_orgs') then raise exception 'permission denied'; end if;
  if not exists(select 1 from public.saas_org_settings where org_id=p_org_id) then raise exception 'saas_org_not_found'; end if;
  if v_sms=0 and v_ai=0 and v_wallet=0 then raise exception 'admin_adjustment_empty'; end if;

  if v_sms<>0 then
    insert into public.org_sms_wallets(org_id,status) values(p_org_id,'active') on conflict(org_id) do nothing;
    select * into v_wallet_row from public.org_sms_wallets where org_id=p_org_id for update;
    if v_wallet_row.balance_irt+v_sms<0 then raise exception 'sms_wallet_negative_balance'; end if;
    update public.org_sms_wallets set balance_irt=balance_irt+v_sms,status='active',updated_at=now() where org_id=p_org_id returning * into v_wallet_row;
    insert into public.org_sms_wallet_transactions(org_id,kind,amount_irt,balance_after_irt,description,metadata,created_by)
    values(p_org_id,'admin_adjustment',v_sms,v_wallet_row.balance_irt,v_reason,jsonb_build_object('source','admin_adjustment'),auth.uid());
  end if;

  if v_ai<>0 then
    insert into public.org_ai_wallets(org_id,balance_irt,status) values(p_org_id,0,'active') on conflict(org_id) do nothing;
    select * into v_ai_row from public.org_ai_wallets where org_id=p_org_id for update;
    if v_ai_row.balance_irt+v_ai<0 then raise exception 'ai_wallet_negative_balance'; end if;
    update public.org_ai_wallets set balance_irt=balance_irt+v_ai,status='active',updated_at=now() where org_id=p_org_id returning * into v_ai_row;
    if v_ai>0 then insert into public.org_ai_credit_grants(org_id,amount_irt,reason,granted_by,metadata) values(p_org_id,v_ai,v_reason,auth.uid(),jsonb_build_object('source','admin_adjustment')); end if;
  end if;

  if v_wallet<>0 then
    insert into public.org_billing_wallets(org_id,balance_irt,status) values(p_org_id,0,'active') on conflict(org_id) do nothing;
    select * into v_billing_row from public.org_billing_wallets where org_id=p_org_id for update;
    if v_billing_row.balance_irt+v_wallet<0 then raise exception 'billing_wallet_negative_balance'; end if;
    update public.org_billing_wallets set balance_irt=balance_irt+v_wallet,updated_at=now() where org_id=p_org_id returning * into v_billing_row;
    insert into public.org_billing_wallet_transactions(org_id,kind,amount_irt,balance_after_irt,description,metadata,created_by)
    values(p_org_id,'admin_adjustment',v_wallet,v_billing_row.balance_irt,v_reason,jsonb_build_object('source','admin_adjustment'),auth.uid());
  end if;

  insert into public.saas_account_admin_history(org_id,kind,title,amount_irt,metadata,created_by)
  values(p_org_id,'admin_adjustment',v_reason,nullif(v_sms+v_ai+v_wallet,0),jsonb_build_object('sms_delta_irt',v_sms,'ai_delta_irt',v_ai,'billing_wallet_delta_irt',v_wallet),auth.uid());
  return public.saas_account_overview_payload(p_org_id);
end;
$$;


--
-- Name: admin_bootstrap_taze_system_provider_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_bootstrap_taze_system_provider_org() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare provider_org_id uuid; provider_role_id uuid;
begin
  if not public.current_user_has_saas_admin_permission() then raise exception 'permission denied'; end if;
  select org_id into provider_org_id from public.saas_org_settings where is_billing_provider limit 1;
  -- اگر سازمان پنل قبلاً به‌صورت دستی ساخته شده باشد، همان سازمان را به
  -- سازمانِ ارائه‌دهنده ارتقا می‌دهیم؛ سازمان موازی ایجاد نمی‌کنیم.
  if provider_org_id is null then
    select org_id into provider_org_id
    from public.saas_org_settings
    where lower(coalesce(resolved_host, '')) = 'panel.tazesystem.ir'
       or lower(coalesce(slug, '')) = 'panel'
    order by created_at asc
    limit 1;
  end if;
  if provider_org_id is null then
    insert into public.organizations(name, slug, is_active) values ('تازه سیستم', 'panel', true) returning id into provider_org_id;
    insert into public.org_roles(org_id, title, permissions, is_system) values (provider_org_id, 'مدیر تازه سیستم', jsonb_build_object('__saas_admin', jsonb_build_object('view', true, 'edit', true, 'edit_orgs', true, 'edit_requests', true)), true) returning id into provider_role_id;
    insert into public.saas_org_settings(org_id, slug, resolved_host, status, plan_code, is_demo, is_readonly, provisioning_source, dns_status, is_billing_provider, owner_name, owner_email, created_by, updated_by)
    select provider_org_id, 'panel', 'panel.tazesystem.ir', 'active', null, false, false, 'saas_provider', 'active', true, p.full_name, p.email, auth.uid(), auth.uid() from public.profiles p where p.id = auth.uid();
  else
    update public.saas_org_settings
    set is_billing_provider = true, status = 'active', updated_at = now(), updated_by = auth.uid()
    where org_id = provider_org_id;
    select id into provider_role_id from public.org_roles where org_id = provider_org_id and coalesce((permissions -> '__saas_admin' ->> 'view')::boolean, false) limit 1;
    if provider_role_id is null then
      insert into public.org_roles(org_id, title, permissions, is_system)
      values (provider_org_id, 'مدیر تازه سیستم', jsonb_build_object('__saas_admin', jsonb_build_object('view', true, 'edit', true, 'edit_orgs', true, 'edit_requests', true)), true)
      returning id into provider_role_id;
    end if;
  end if;
  insert into public.user_organization_memberships(user_id, org_id, role_id, software_role, is_owner, is_active) values (auth.uid(), provider_org_id, provider_role_id, 'admin', false, true)
  on conflict (user_id, org_id) do update set role_id = excluded.role_id, software_role = excluded.software_role, is_active = true, updated_at = now();
  return jsonb_build_object('success', true, 'host', 'panel.tazesystem.ir');
end; $$;


--
-- Name: admin_convert_demo_request_to_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_convert_demo_request_to_org(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  request_row public.saas_onboarding_requests%rowtype;
  existing_settings public.saas_org_settings%rowtype;
  target_org_id uuid;
  base_name text;
  base_slug text;
  final_slug text;
  slug_counter integer := 0;
  target_plan_code text := null;
  target_trial_days integer := 30;
begin
  if not public.current_user_has_saas_admin_permission() then
    raise exception 'permission denied';
  end if;

  select * into request_row
  from public.saas_onboarding_requests
  where id = p_request_id;

  if request_row.id is null then
    return jsonb_build_object('success', false, 'message', 'درخواست دمو یافت نشد.');
  end if;

  select * into existing_settings
  from public.saas_org_settings
  where request_id = request_row.id
  limit 1;

  if existing_settings.org_id is not null then
    return jsonb_build_object(
      'success', true,
      'message', 'این درخواست قبلاً به سازمان متصل شده است.',
      'source_id', existing_settings.org_id,
      'org_id', existing_settings.org_id
    );
  end if;

  if request_row.org_id is not null then
    select * into existing_settings
    from public.saas_org_settings
    where org_id = request_row.org_id
    limit 1;
    if existing_settings.org_id is not null then
      return jsonb_build_object(
        'success', true,
        'message', 'این درخواست قبلاً به سازمان متصل شده است.',
        'source_id', existing_settings.org_id,
        'org_id', existing_settings.org_id
      );
    end if;
  end if;

  select code, greatest(coalesce(trial_days, 30), 1)
  into target_plan_code, target_trial_days
  from public.saas_plans
  where is_active = true
    and (is_demo_default = true or lower(code) = 'public_demo_full')
  order by is_demo_default desc
  limit 1;

  base_name := coalesce(
    nullif(trim(coalesce(request_row.organization_name, '')), ''),
    nullif(trim(coalesce(request_row.business_name, '')), ''),
    nullif(trim(coalesce(request_row.full_name, '')), ''),
    'سازمان دمو'
  );
  base_slug := coalesce(
    nullif(public.normalize_saas_slug(request_row.requested_slug), ''),
    nullif(public.normalize_saas_slug(base_name), ''),
    'org' || to_char(now(), 'YYMMDDHH24MISS')
  );
  final_slug := base_slug;

  loop
    exit when not exists (
      select 1 from public.saas_org_settings where lower(coalesce(slug, '')) = lower(final_slug)
    ) and not exists (
      select 1 from public.organizations where lower(coalesce(slug, '')) = lower(final_slug)
    );
    slug_counter := slug_counter + 1;
    final_slug := base_slug || '-' || slug_counter::text;
    if slug_counter > 200 then
      return jsonb_build_object('success', false, 'message', 'Slug یکتا برای سازمان پیدا نشد.');
    end if;
  end loop;

  insert into public.organizations (
    name,
    slug,
    is_active,
    created_at,
    updated_at
  )
  values (
    base_name,
    final_slug,
    true,
    now(),
    now()
  )
  returning id into target_org_id;

  insert into public.saas_org_settings (
    org_id,
    slug,
    status,
    plan_code,
    trial_ends_at,
    is_demo,
    is_readonly,
    resolved_host,
    dns_status,
    provisioning_source,
    provisioned_at,
    primary_contact_mobile,
    request_id,
    owner_name,
    owner_email,
    created_at,
    updated_at
  )
  values (
    target_org_id,
    final_slug,
    'trial',
    target_plan_code,
    now() + make_interval(days => target_trial_days),
    coalesce(request_row.is_demo_request, true),
    false,
    final_slug || '.tazesystem.ir',
    'pending',
    'manual_from_request',
    now(),
    nullif(trim(coalesce(request_row.mobile, '')), ''),
    request_row.id,
    nullif(trim(coalesce(request_row.full_name, '')), ''),
    nullif(trim(coalesce(request_row.email, '')), ''),
    now(),
    now()
  );

  update public.saas_onboarding_requests
  set
    org_id = target_org_id,
    status = 'provisioned',
    requested_slug = coalesce(requested_slug, final_slug),
    updated_at = now()
  where id = request_row.id;

  return jsonb_build_object(
    'success', true,
    'message', 'سازمان از روی درخواست دمو ایجاد شد.',
    'source_id', target_org_id,
    'org_id', target_org_id
  );
end;
$$;


--
-- Name: admin_create_saas_order(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_create_saas_order(p_org_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare entry record; catalog public.saas_catalog_items%rowtype; plan public.saas_plans%rowtype; normalized_items jsonb:='[]'::jsonb; qty numeric; entitlement_quantity numeric; line_total numeric; total numeric:=0; order_id uuid; billable_users integer;
begin
  if not public.current_user_has_saas_admin_permission('edit_orgs') then raise exception 'permission denied'; end if;
  if p_org_id is null or not exists(select 1 from public.saas_org_settings where org_id=p_org_id) then raise exception 'saas_org_not_found'; end if;
  if public.org_is_saas_admin(p_org_id) then raise exception 'saas_admin_target_not_allowed'; end if;
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'order_items_required'; end if;
  billable_users := public.saas_billable_user_count(p_org_id);
  for entry in select value from jsonb_array_elements(p_items) loop
    qty:=greatest(1,least(coalesce((entry.value ->> 'quantity')::numeric,1),1000));
    if left(coalesce(entry.value ->> 'code',''),5)='plan:' then
      select * into plan from public.saas_plans where code=substr(entry.value ->> 'code',6) and is_active and is_public;
      if plan.id is null or coalesce(plan.price_per_user_monthly, plan.price_monthly)<=0 then raise exception 'catalog_item_not_available'; end if;
      line_total:=billable_users*coalesce(plan.price_per_user_monthly,plan.price_monthly);
      normalized_items:=normalized_items||jsonb_build_array(jsonb_build_object('code','plan:'||plan.code,'title',plan.title,'item_kind','plan','entitlement_code',plan.code,'quantity',1,'purchase_quantity',billable_users,'unit_price_irt',coalesce(plan.price_per_user_monthly,plan.price_monthly),'line_total_irt',line_total,'metadata',jsonb_build_object('billable_users',billable_users,'pricing_model','per_user'))); total:=total+line_total;
    else
      select * into catalog from public.saas_catalog_items where code=entry.value ->> 'code' and is_active and is_public and price_irt>0;
      if catalog.id is null then raise exception 'catalog_item_not_available'; end if;
      entitlement_quantity:=qty*catalog.quantity; line_total:=qty*catalog.price_irt;
      normalized_items:=normalized_items||jsonb_build_array(jsonb_build_object('code',catalog.code,'title',catalog.title,'item_kind',catalog.item_kind,'entitlement_code',catalog.entitlement_code,'quantity',entitlement_quantity,'purchase_quantity',qty,'unit_price_irt',catalog.price_irt,'line_total_irt',line_total,'billing_cycle',catalog.billing_cycle,'metadata',catalog.metadata)); total:=total+line_total;
    end if;
  end loop;
  insert into public.saas_orders(org_id,created_by,total_irt,items,metadata) values(p_org_id,auth.uid(),total,normalized_items,jsonb_build_object('source','saas_admin_cart','created_by_admin',auth.uid())) returning id into order_id;
  return jsonb_build_object('success',true,'order_id',order_id,'status','pending_payment','total_irt',total,'items',normalized_items);
end; $$;


