--
-- Name: admin_local_installation(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_local_installation(p_action text, p_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare o uuid:=public.current_org_id(); i public.saas_local_installations; j public.saas_local_jobs;
 r public.saas_local_releases; need text; c text; v_result jsonb; frozen boolean;
begin
 need:=case p_action when 'create' then 'build' when 'prepare' then 'build' when 'export_trial' then 'export' when 'export_final' then 'cutover'
 when 'download' then 'view' when 'link_ticket_code' then 'view' when 'import_report' then 'view' when 'detail' then 'view' when 'customers' then 'build'
 when 'set_recovery_key' then 'export' when 'authorize_receipt' then 'cutover' when 'issue_report_token' then 'build' when 'operators' then 'build' when 'review_interrupted' then 'build'
 when 'retry' then 'build' else null end;
 if need is null or not public.local_installation_can(need) then raise exception using errcode='42501',message='اجازهٔ انجام این عملیات را ندارید.'; end if;
 if p_action='operators' then
  select coalesce(jsonb_agg(x),'[]') into v_result from(select m.user_id as id,coalesce(nullif(p.full_name,''),'[بدون عنوان]') as name
   from public.user_organization_memberships m join public.profiles p on p.id=m.user_id where m.org_id=o and m.is_active order by p.full_name limit 100)x;
  return jsonb_build_object('operators',v_result);
 elsif p_action='customers' then
  select coalesce(jsonb_agg(x),'[]') into v_result from (select org_id as id, public.organization_display_name(org_id) as name
   from public.saas_org_settings where org_id<>o and (p_payload->>'cursor' is null or org_id::text>p_payload->>'cursor')
   and (nullif(trim(p_payload->>'search'),'') is null or public.organization_display_name(org_id) ilike '%'||left(p_payload->>'search',100)||'%') order by org_id limit 30) x;
  return jsonb_build_object('customers',v_result);
 end if;
 if p_action='create' then
  if length(trim(coalesce(p_payload->>'title','')))<2 or length(p_payload->>'title')>180 or
   coalesce(p_payload->>'admin_email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or
   coalesce(p_payload->>'public_url','') !~ '^https://[a-zA-Z0-9.-]+(:[0-9]{1,5})?$' or
   coalesce(p_payload->>'admin_name','')='' then raise exception 'نام نصب، نشانی امن و مشخصات مدیر را کامل کنید.'; end if;
  if not exists(select 1 from public.saas_org_settings where org_id=(p_payload->>'customer_org_id')::uuid and org_id<>o and not public.org_is_saas_admin(org_id))
   then raise exception 'سازمان مشتری معتبر نیست.'; end if;
  if nullif(p_payload->>'assigned_to','') is not null and not exists(select 1 from public.user_organization_memberships
   where org_id=o and user_id=(p_payload->>'assigned_to')::uuid and is_active) then raise exception 'مسئول باید عضو سازمان اپراتور باشد.'; end if;
  insert into public.saas_local_installations(org_id,customer_org_id,title,customer_name,assigned_to,install_kind,access_mode,public_url,tls_mode,delivery_mode,admin_name,admin_email,telemetry_enabled,created_by)
  values(o,(p_payload->>'customer_org_id')::uuid,trim(p_payload->>'title'),public.organization_display_name((p_payload->>'customer_org_id')::uuid),
   coalesce(nullif(p_payload->>'assigned_to','')::uuid,auth.uid()),p_payload->>'install_kind',p_payload->>'access_mode',p_payload->>'public_url',p_payload->>'tls_mode',p_payload->>'delivery_mode',
   left(p_payload->>'admin_name',180),left(p_payload->>'admin_email',254),coalesce((p_payload->>'telemetry_enabled')::boolean,false),auth.uid()) returning * into i;
  insert into public.saas_local_events(org_id,installation_id,event_type,message,actor_id) values(o,i.id,'created','پروندهٔ نصب ایجاد شد.',auth.uid());
  return jsonb_build_object('id',i.id);
 end if;
 select * into i from public.saas_local_installations where id=p_id and org_id=o for update;
 if not found then raise exception using errcode='42501',message='پروندهٔ نصب در دسترس نیست.'; end if;
 if p_action='detail' then
  return jsonb_build_object('installation',to_jsonb(i),'jobs',coalesce((select jsonb_agg(x) from
   (select id,kind,status,stage,requested_at,started_at,finished_at,attempt,error_code,message,result,release_id from public.saas_local_jobs where installation_id=i.id and org_id=o order by requested_at desc limit 30)x),'[]'),
   'events',coalesce((select jsonb_agg(x) from(select event_type,stage,message,created_at from public.saas_local_events where installation_id=i.id and org_id=o order by id desc limit 100)x),'[]'),
   'report',(select jsonb_build_object('report',report,'received_at',received_at,'source',source) from public.saas_local_reports where installation_id=i.id and org_id=o order by (report->>'generated_at')::timestamptz desc,received_at desc limit 1),
   'release',(select jsonb_build_object('version',version,'verified_at',verified_at) from public.saas_local_releases where org_id=o and is_current_central),
   'recovery_key_configured',exists(select 1 from public.saas_local_credentials where installation_id=i.id and recovery_public_key is not null),
   'source_frozen',exists(select 1 from public.saas_local_transfer_locks where org_id=i.customer_org_id),
   'tickets',case when public.support_is_operator('support_view') then coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'code',public.support_ticket_code(t.ticket_no),'subject',t.subject,'status',t.status)) from public.saas_local_ticket_links l join public.saas_support_tickets t on t.id=l.ticket_id and t.org_id=o where l.installation_id=i.id and l.org_id=o),'[]') else '[]'::jsonb end);
 elsif p_action='review_interrupted' then
  select * into j from public.saas_local_jobs where installation_id=i.id and status='needs_review' for update;
  if not found or p_payload->>'confirmation' is distinct from i.system_code or (j.kind<>'prepare' and not public.local_installation_can('cutover')) then
   raise exception 'بررسی خروجی، worker و قفل انتقال و تأیید کد نصب لازم است.'; end if;
  update public.saas_local_jobs set status='failed',finished_at=now(),error_code='INTERRUPTION_REVIEWED',message='توقف اجرا توسط اپراتور بررسی شد؛ عملیات جدید نیازمند درخواست جداست.' where id=j.id;
 elsif p_action='set_recovery_key' then
  if length(coalesce(p_payload->>'public_key','')) not between 400 and 8192 or p_payload->>'public_key' not like '-----BEGIN PUBLIC KEY-----%'
   or exists(select 1 from public.saas_local_jobs where installation_id=i.id and kind like 'export_%') then raise exception 'کلید عمومی معتبر را پیش از نخستین خروجی اطلاعات ثبت کنید.'; end if;
  insert into public.saas_local_credentials(installation_id,org_id,recovery_public_key) values(i.id,o,p_payload->>'public_key')
   on conflict(installation_id) do update set recovery_public_key=excluded.recovery_public_key;
 elsif p_action='issue_report_token' then
  if not i.telemetry_enabled then raise exception 'ارسال گزارش برای این نصب فعال نشده است.'; end if;
  c:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');
  insert into public.saas_local_credentials(installation_id,org_id,telemetry_token_hash) values(i.id,o,encode(sha256(convert_to(c,'UTF8')),'hex'))
   on conflict(installation_id) do update set telemetry_token_hash=excluded.telemetry_token_hash;
  insert into public.saas_local_events(org_id,installation_id,event_type,message,actor_id) values(o,i.id,p_action,'کلید ارسال گزارش صادر و کلید قبلی باطل شد.',auth.uid());
  return jsonb_build_object('token',c);
 elsif p_action='authorize_receipt' then
  select * into j from public.saas_local_jobs where id=(p_payload->>'job_id')::uuid and org_id=o and installation_id=i.id and status='succeeded' and kind in ('export_trial','export_final');
  if not found then raise exception 'خروجی قابل بررسی پیدا نشد.'; end if;
  return jsonb_build_object('job_id',j.id,'actor',auth.uid(),'public_key',(select recovery_public_key from public.saas_local_credentials where installation_id=i.id));
 elsif p_action='import_report' then
  v_result:=public.local_installation_safe_report(p_payload);
  insert into public.saas_local_reports(org_id,installation_id,report,source) values(o,i.id,v_result,'manual');
  update public.saas_local_installations set last_report_at=now() where id=i.id;
 elsif p_action='link_ticket_code' then
  if not public.support_is_operator('support_view') or not exists(select 1 from public.saas_support_tickets where public.support_ticket_code(ticket_no)=p_payload->>'code' and org_id=o and customer_org_id=i.customer_org_id)
   then raise exception 'تیکت متعلق به همین مشتری و قابل مشاهده انتخاب شود.'; end if;
  insert into public.saas_local_ticket_links select o,i.id,id from public.saas_support_tickets where org_id=o and customer_org_id=i.customer_org_id and public.support_ticket_code(ticket_no)=p_payload->>'code' on conflict do nothing;
 elsif p_action='download' then
  if not exists(select 1 from public.saas_local_jobs where id=(p_payload->>'job_id')::uuid and org_id=o and installation_id=i.id and status='succeeded') then raise exception 'بستهٔ آماده‌ای برای این عملیات وجود ندارد.'; end if;
  select * into j from public.saas_local_jobs where id=(p_payload->>'job_id')::uuid and org_id=o;
  if j.kind='prepare' and not public.local_installation_can('build') then raise exception using errcode='42501',message='اجازهٔ دریافت بسته را ندارید.'; end if;
  if j.kind<>'prepare' and not public.local_installation_can('export') then raise exception using errcode='42501',message='اجازهٔ دریافت خروجی داده را ندارید.'; end if;
  if j.kind<>'prepare' and (j.result->>'expires_at')::timestamptz<=now() then raise exception 'مهلت دریافت خروجی داده گذشته است.'; end if;
  insert into public.saas_local_events(org_id,installation_id,event_type,message,actor_id) values(o,i.id,'download','دریافت بسته درخواست شد.',auth.uid());
  return jsonb_build_object('path',j.result->>'artifact_path','release_id',j.release_id,'kind',j.kind);
 elsif p_action in ('prepare','export_trial','export_final','retry') then
  if exists(select 1 from public.saas_local_jobs where installation_id=i.id and status in ('queued','running','needs_review')) then
   select * into j from public.saas_local_jobs where installation_id=i.id and status in ('queued','running','needs_review');
   return jsonb_build_object('job_id',j.id,'existing',true);
  end if;
  if p_action='retry' then
   select * into j from public.saas_local_jobs where installation_id=i.id order by requested_at desc limit 1;
   if j.status<>'failed' or j.kind<>'prepare' then raise exception 'برای انتقال اطلاعات، عملیات جدید با بررسی مجوز اجرا کنید.'; end if;
  end if;
  select * into r from public.saas_local_releases where org_id=o and is_current_central;
  if not found then raise exception 'نسخهٔ جاری سرور مرکزی هنوز بستهٔ لوکال تأییدشده ندارد.'; end if;
  if p_action like 'export_%' then
   if i.install_kind<>'migration' then raise exception 'این پرونده برای نصب تازه است.'; end if;
   if r.manifest#>>'{checks,tenant_transfer}' is distinct from 'passed' then raise exception 'انتقال این نسخه هنوز آزمون و تأیید نشده است.'; end if;
   if p_action='export_final' and (p_payload->>'confirmation' is distinct from i.system_code or not exists(select 1 from public.saas_local_jobs where installation_id=i.id and release_id=r.id and kind='export_trial' and status='succeeded' and result->>'restore_verified'='true')) then
    raise exception 'بازیابی آزمایشی باید تأیید شود؛ کد نصب را برای انتقال نهایی وارد کنید.'; end if;
  end if;
  insert into public.saas_local_jobs(org_id,installation_id,release_id,kind,requested_by) values(o,i.id,r.id,case when p_action='retry' then j.kind else p_action end,auth.uid()) returning * into j;
  update public.saas_local_installations set status='preparing',updated_at=now() where id=i.id;
  insert into public.saas_local_events(org_id,installation_id,job_id,event_type,message,actor_id) values(o,i.id,j.id,'queued','عملیات در صف اجرا قرار گرفت.',auth.uid());
  return jsonb_build_object('job_id',j.id,'existing',false);
 end if;
 insert into public.saas_local_events(org_id,installation_id,event_type,message,actor_id) values(o,i.id,p_action,'پروندهٔ نصب به‌روز شد.',auth.uid());
 return jsonb_build_object('success',true);
end $_$;


--
-- Name: admin_provision_demo_request_with_access(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_provision_demo_request_with_access(p_request_id uuid, p_plan_code text DEFAULT NULL::text, p_module_overrides jsonb DEFAULT '{}'::jsonb, p_feature_overrides jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb; target uuid; request_org uuid;
begin
 if not public.current_user_has_saas_admin_permission('edit_orgs') then raise exception 'permission denied' using errcode='42501'; end if;
 if jsonb_typeof(p_module_overrides) is distinct from 'object' or jsonb_typeof(p_feature_overrides) is distinct from 'object'
  or exists(select 1 from jsonb_each(p_module_overrides||p_feature_overrides) where jsonb_typeof(value)<>'boolean') then raise exception 'invalid_access_overrides'; end if;
 perform 1 from public.saas_onboarding_requests where id=p_request_id for update;
 if not found then return jsonb_build_object('success',false,'message','درخواست دمو یافت نشد.'); end if;
 select s.org_id into request_org from public.saas_org_settings s join public.saas_onboarding_requests r on r.id=p_request_id where s.request_id=r.id or s.org_id=r.org_id limit 1;
 if request_org is not null then return jsonb_build_object('success',true,'org_id',request_org,'message','این درخواست قبلاً به سازمان متصل شده است.'); end if;
 result:=public.admin_convert_demo_request_to_org(p_request_id);
 if result->'success' is distinct from 'true'::jsonb then return result; end if;
 target:=coalesce(result->>'org_id',result->>'source_id')::uuid;
 if target is null then raise exception 'provisioned_org_missing'; end if;
 perform public.admin_update_saas_org_account(target,coalesce(p_plan_code,(select plan_code from public.saas_org_settings where org_id=target)),p_module_overrides,p_feature_overrides,'{}');
 return result;
end; $$;


--
-- Name: admin_saas_delete_demo_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_delete_demo_org(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  target_name text;
  target_demo boolean;
  target_table record;
begin
  if not public.current_user_has_saas_admin_permission() then
    raise exception 'permission denied';
  end if;
  select o.name, s.is_demo into target_name, target_demo
  from public.organizations o join public.saas_org_settings s on s.org_id = o.id
  where o.id = p_org_id
  for update;
  if target_name is null or target_demo is not true then
    return jsonb_build_object('success', false, 'message', 'حذف دائمی فقط برای نسخه دمو مجاز است.');
  end if;

  for target_table in
    select c.table_name
    from information_schema.columns c
    join information_schema.tables t
      on t.table_schema = c.table_schema and t.table_name = c.table_name
    where c.table_schema = 'public'
      and c.column_name = 'org_id'
      and t.table_type = 'BASE TABLE'
      and c.table_name <> 'organizations'
    order by case
      when c.table_name = 'profiles' then 90
      when c.table_name = 'org_roles' then 100
      when c.table_name = 'saas_org_settings' then 110
      else 10
    end
  loop
    execute format('delete from public.%I where org_id = $1', target_table.table_name) using p_org_id;
  end loop;

  delete from public.organizations where id = p_org_id;
  return jsonb_build_object('success', true, 'message', 'نسخه دمو و داده‌های وابسته حذف شد.');
exception
  when foreign_key_violation then
    raise exception 'حذف نسخه دمو به دلیل وابستگی داده‌ای متوقف شد. پیش از حذف، وابستگی‌های باقی‌مانده بررسی شود.';
end
$_$;


--
-- Name: admin_saas_delete_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_delete_request(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target public.saas_onboarding_requests%rowtype;
begin
  if not public.current_user_has_saas_admin_permission() then
    raise exception 'permission denied';
  end if;
  select * into target from public.saas_onboarding_requests where id = p_request_id;
  if target.id is null then
    return jsonb_build_object('success', false, 'message', 'درخواست پیدا نشد.');
  end if;
  if target.org_id is not null or target.status not in ('draft', 'failed', 'cancelled', 'needs_admin_review') then
    return jsonb_build_object('success', false, 'message', 'این درخواست به سازمان متصل است یا در وضعیت قابل حذف نیست.');
  end if;
  delete from public.saas_onboarding_requests where id = p_request_id;
  return jsonb_build_object('success', true, 'message', 'درخواست دمو حذف شد.');
end
$$;


--
-- Name: admin_saas_demo_delete_preflight(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_demo_delete_preflight(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  org_name text;
  demo boolean;
  users_count integer;
  seeded_count integer;
begin
  if not public.current_user_has_saas_admin_permission() then
    raise exception 'permission denied';
  end if;
  select o.name, s.is_demo into org_name, demo
  from public.organizations o join public.saas_org_settings s on s.org_id = o.id
  where o.id = p_org_id;
  if org_name is null or demo is not true then
    return jsonb_build_object('allowed', false, 'message', 'حذف دائمی فقط برای نسخه دمو مجاز است.');
  end if;
  select count(*) into users_count from public.profiles where org_id = p_org_id;
  select count(*) into seeded_count from public.demo_seed_records where org_id = p_org_id;
  return jsonb_build_object(
    'allowed', true,
    'organization_name', org_name,
    'users_count', users_count,
    'seeded_records_count', seeded_count,
    'user_ids', coalesce((select jsonb_agg(p.id) from public.profiles p where p.org_id = p_org_id), '[]'::jsonb)
  );
end
$$;


--
-- Name: admin_saas_edit_org(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_edit_org(p_org_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  caller_id   uuid := auth.uid();
  caller_role text;
begin
  select role into caller_role
  from public.profiles
  where id = caller_id
  limit 1;

  if caller_role not in ('super_admin', 'admin')
     and not public.current_user_has_saas_admin_permission('edit_orgs') then
    return jsonb_build_object('success', false, 'message', 'دسترسی کافی ندارید.');
  end if;

  -- فیلدهایی که ادمین می‌تواند مستقیماً ویرایش کند
  update public.saas_org_settings
  set
    plan_code              = case when p_patch ? 'plan_code'
                                  then nullif(trim(p_patch->>'plan_code'), '')
                                  else plan_code end,
    is_demo                = case when p_patch ? 'is_demo'
                                  then (p_patch->>'is_demo')::boolean
                                  else is_demo end,
    is_readonly            = case when p_patch ? 'is_readonly'
                                  then (p_patch->>'is_readonly')::boolean
                                  else is_readonly end,
    primary_contact_mobile = case when p_patch ? 'primary_contact_mobile'
                                  then nullif(trim(p_patch->>'primary_contact_mobile'), '')
                                  else primary_contact_mobile end,
    resolved_host          = case when p_patch ? 'resolved_host'
                                  then nullif(trim(p_patch->>'resolved_host'), '')
                                  else resolved_host end,
    trial_ends_at          = case when p_patch ? 'trial_ends_at'
                                  then (p_patch->>'trial_ends_at')::timestamptz
                                  else trial_ends_at end,
    updated_at             = now()
  where org_id = p_org_id;

  if not found then
    return jsonb_build_object('success', false, 'message', 'سازمان پیدا نشد.');
  end if;

  return jsonb_build_object('success', true, 'message', 'سازمان به‌روز شد.');
end;
$$;


--
-- Name: admin_saas_edit_request(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_edit_request(p_request_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  caller_id   uuid := auth.uid();
  caller_role text;
begin
  select role into caller_role
  from public.profiles
  where id = caller_id
  limit 1;

  if caller_role not in ('super_admin', 'admin')
     and not public.current_user_has_saas_admin_permission('edit_requests') then
    return jsonb_build_object('success', false, 'message', 'دسترسی کافی ندارید.');
  end if;

  update public.saas_onboarding_requests
  set
    status            = case when p_patch ? 'status'
                             then (p_patch->>'status')::text
                             else status end,
    full_name         = case when p_patch ? 'full_name'
                             then nullif(trim(p_patch->>'full_name'), '')
                             else full_name end,
    organization_name = case when p_patch ? 'organization_name'
                             then nullif(trim(p_patch->>'organization_name'), '')
                             else organization_name end,
    mobile            = case when p_patch ? 'mobile'
                             then nullif(trim(p_patch->>'mobile'), '')
                             else mobile end,
    email             = case when p_patch ? 'email'
                             then nullif(trim(p_patch->>'email'), '')
                             else email end,
    requested_slug    = case when p_patch ? 'requested_slug'
                             then nullif(lower(trim(p_patch->>'requested_slug')), '')
                             else requested_slug end,
    is_demo_request   = case when p_patch ? 'is_demo_request'
                             then (p_patch->>'is_demo_request')::boolean
                             else is_demo_request end,
    -- پاک کردن خطا با ارسال رشته خالی
    failure_code      = case when p_patch ? 'failure_code'
                             then nullif(trim(p_patch->>'failure_code'), '')
                             else failure_code end,
    failure_message   = case when p_patch ? 'failure_message'
                             then nullif(trim(p_patch->>'failure_message'), '')
                             else failure_message end,
    updated_at        = now()
  where id = p_request_id;

  if not found then
    return jsonb_build_object('success', false, 'message', 'درخواست پیدا نشد.');
  end if;

  return jsonb_build_object('success', true, 'message', 'درخواست به‌روز شد.');
end;
$$;


--
-- Name: admin_saas_extend_org_access(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_extend_org_access(p_org_id uuid, p_days integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_settings public.saas_org_settings%rowtype; v_subscription public.saas_recurring_subscriptions%rowtype;
  v_new_end timestamptz;
begin
  if not public.current_user_has_saas_admin_permission('edit_orgs') then
    raise exception 'permission denied' using errcode='42501'; end if;
  if p_days is null or p_days < 1 or p_days > 365 then
    raise exception 'invalid_extension_days' using errcode='22023'; end if;
  select * into v_settings from public.saas_org_settings where org_id=p_org_id for update;
  if v_settings.id is null then raise exception 'saas_org_not_found' using errcode='P0002'; end if;
  if v_settings.is_demo then return public.admin_saas_extend_org_trial(p_org_id,p_days); end if;
  select * into v_subscription from public.saas_recurring_subscriptions
    where org_id=p_org_id and item_kind='plan' and status in ('active','grace')
    order by current_period_ends_at desc limit 1 for update;
  if v_subscription.id is null then raise exception 'active_subscription_not_found' using errcode='P0002'; end if;
  if exists(select 1 from public.saas_subscription_invoices
    where subscription_id=v_subscription.id and status in ('issued','overdue')) then
    raise exception 'subscription_invoice_pending' using errcode='23514'; end if;
  v_new_end := greatest(v_subscription.current_period_ends_at,now())+make_interval(days=>p_days);
  update public.saas_recurring_subscriptions
    set current_period_ends_at=v_new_end,next_invoice_at=greatest(now(),v_new_end-interval '7 days'),
      status='active',updated_at=now()
    where id=v_subscription.id;
  update public.saas_org_settings set billing_readonly=false,billing_readonly_at=null,updated_at=now(),updated_by=auth.uid()
    where org_id=p_org_id;
  return jsonb_build_object('success',true,'new_access_ends_at',v_new_end,'mode','subscription');
end;
$$;


--
-- Name: admin_saas_extend_org_trial(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_extend_org_trial(p_org_id uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_new_end timestamptz;
begin
  if not public.current_user_has_saas_admin_permission('edit_orgs') then
    raise exception 'permission denied' using errcode='42501'; end if;
  if p_days is null or p_days < 1 or p_days > 365 then
    raise exception 'invalid_extension_days' using errcode='22023'; end if;
  update public.saas_org_settings
    set trial_ends_at = greatest(coalesce(trial_ends_at,now()),now()) + make_interval(days=>p_days),
        is_readonly = false, status = case when status='suspended' then 'trial' else status end,
        updated_at = now(), updated_by = auth.uid()
    where org_id = p_org_id and is_demo
    returning trial_ends_at into v_new_end;
  if v_new_end is null then raise exception 'demo_org_not_found' using errcode='P0002'; end if;
  update public.saas_renewal_requests set status='extended',resolved_at=now(),resolved_by=auth.uid(),updated_at=now()
    where org_id=p_org_id and status='pending';
  return jsonb_build_object('success',true,'new_trial_ends_at',v_new_end,'mode','demo');
end;
$$;


--
-- Name: admin_saas_set_org_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_set_org_status(p_org_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  caller_id   uuid := auth.uid();
  caller_role text;
begin
  if p_status not in ('active', 'trial', 'demo', 'suspended', 'cancelled') then
    return jsonb_build_object('success', false, 'message', 'وضعیت نامعتبر است.');
  end if;

  select role into caller_role
  from public.profiles
  where id = caller_id
  limit 1;

  if caller_role not in ('super_admin', 'admin')
     and not public.current_user_has_saas_admin_permission('edit_orgs') then
    return jsonb_build_object('success', false, 'message', 'دسترسی کافی ندارید.');
  end if;

  update public.saas_org_settings
  set status      = p_status,
      is_readonly = (p_status = 'suspended') or (is_readonly and p_status not in ('active', 'trial')),
      updated_at  = now()
  where org_id = p_org_id;

  if not found then
    return jsonb_build_object('success', false, 'message', 'سازمان پیدا نشد.');
  end if;

  return jsonb_build_object('success', true, 'message', 'وضعیت سازمان به‌روز شد.');
end;
$$;


--
-- Name: admin_saas_update_candidate_runtime(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_update_candidate_runtime(p_source_kind text, p_source_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_patch jsonb := coalesce(p_patch, '{}'::jsonb);
  v_source_kind text := case when lower(trim(coalesce(p_source_kind, 'org'))) = 'request' then 'request' else 'org' end;
begin
  if p_source_id is null then
    return jsonb_build_object('success', false, 'message', 'رکورد برای به‌روزرسانی پیدا نشد.');
  end if;

  if not public.current_user_has_saas_admin_permission() then
    return jsonb_build_object('success', false, 'message', 'دسترسی کافی ندارید.');
  end if;

  if v_source_kind = 'request' then
    update public.saas_onboarding_requests
    set
      assignee_type = case when v_patch ? 'assignee_type' then nullif(trim(v_patch->>'assignee_type'), '') else assignee_type end,
      assignee_id = case when v_patch ? 'assignee_id' then nullif(trim(v_patch->>'assignee_id'), '')::uuid else assignee_id end,
      assignee_role_id = case when v_patch ? 'assignee_role_id' then nullif(trim(v_patch->>'assignee_role_id'), '')::uuid else assignee_role_id end,
      process_template_id = case when v_patch ? 'process_template_id' then nullif(trim(v_patch->>'process_template_id'), '')::uuid else process_template_id end,
      execution_process_draft = case when v_patch ? 'execution_process_draft' then coalesce(v_patch->'execution_process_draft', '{}'::jsonb) else execution_process_draft end,
      updated_at = now()
    where id = p_source_id;
  else
    update public.saas_org_settings
    set
      assignee_type = case when v_patch ? 'assignee_type' then nullif(trim(v_patch->>'assignee_type'), '') else assignee_type end,
      assignee_id = case when v_patch ? 'assignee_id' then nullif(trim(v_patch->>'assignee_id'), '')::uuid else assignee_id end,
      assignee_role_id = case when v_patch ? 'assignee_role_id' then nullif(trim(v_patch->>'assignee_role_id'), '')::uuid else assignee_role_id end,
      process_template_id = case when v_patch ? 'process_template_id' then nullif(trim(v_patch->>'process_template_id'), '')::uuid else process_template_id end,
      execution_process_draft = case when v_patch ? 'execution_process_draft' then coalesce(v_patch->'execution_process_draft', '{}'::jsonb) else execution_process_draft end,
      updated_at = now()
    where org_id = p_source_id;
  end if;

  if not found then
    return jsonb_build_object('success', false, 'message', 'رکورد موردنظر پیدا نشد.');
  end if;

  return jsonb_build_object('success', true);
end;
$$;


--
-- Name: admin_saas_user_delete_preflight(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_user_delete_preflight(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target_profile public.profiles%rowtype;
  target_role public.org_roles%rowtype;
  target_org_name text;
  target_is_demo boolean := false;
  remaining_admins integer := 0;
begin
  if not public.current_user_has_saas_admin_permission() then
    raise exception 'permission denied';
  end if;
  if p_user_id = auth.uid() then
    return jsonb_build_object('allowed', false, 'message', 'نمی‌توانید حساب کاربری خودتان را حذف کنید.');
  end if;

  select * into target_profile from public.profiles where id = p_user_id;
  if target_profile.id is not null then
    select * into target_role from public.org_roles where id = target_profile.role_id;
    select o.name, coalesce(s.is_demo, false)
      into target_org_name, target_is_demo
    from public.organizations o
    left join public.saas_org_settings s on s.org_id = o.id
    where o.id = target_profile.org_id;
  end if;

  if coalesce((target_role.permissions -> '__saas_admin' ->> 'view')::boolean, false)
     or coalesce((target_role.permissions -> '__saas_admin' ->> 'edit')::boolean, false) then
    select count(*) into remaining_admins
    from public.profiles p
    join public.org_roles r on r.id = p.role_id
    where p.id <> p_user_id
      and coalesce(p.is_active, true)
      and (
        coalesce((r.permissions -> '__saas_admin' ->> 'view')::boolean, false)
        or coalesce((r.permissions -> '__saas_admin' ->> 'edit')::boolean, false)
      );
    if remaining_admins = 0 then
      return jsonb_build_object('allowed', false, 'message', 'آخرین مدیر تازه سیستم قابل حذف نیست.');
    end if;
  end if;

  return jsonb_build_object(
    'allowed', true,
    'profile_exists', target_profile.id is not null,
    'name', coalesce(target_profile.full_name, 'حساب بدون پروفایل'),
    'organization_name', target_org_name,
    'is_demo', target_is_demo
  );
end
$$;


--
-- Name: admin_saas_user_directory_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_saas_user_directory_options() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.current_user_has_saas_admin_permission() then
    raise exception 'permission denied';
  end if;
  return jsonb_build_object(
    'organizations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'value', o.id,
        'label', o.name,
        'slug', o.slug,
        'is_demo', coalesce(s.is_demo, false)
      ) order by o.name)
      from public.organizations o
      left join public.saas_org_settings s on s.org_id = o.id
      where coalesce(o.is_active, true)
    ), '[]'::jsonb),
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'value', r.id,
        'label', r.title,
        'org_id', r.org_id
      ) order by r.title)
      from public.org_roles r
    ), '[]'::jsonb)
  );
end
$$;


--
-- Name: admin_update_saas_order(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_saas_order(p_order_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare order_row public.saas_orders%rowtype; recreated jsonb;
begin
  if not public.current_user_has_saas_admin_permission('edit_orgs') then raise exception 'permission denied'; end if;
  select * into order_row from public.saas_orders where id = p_order_id for update;
  if order_row.id is null then raise exception 'saas_order_not_found'; end if;
  if public.org_is_saas_admin(order_row.org_id) then raise exception 'saas_admin_target_not_allowed'; end if;
  if order_row.status <> 'pending_payment' then raise exception 'saas_order_not_editable'; end if;
  delete from public.saas_orders where id = p_order_id;
  recreated := public.admin_create_saas_order(order_row.org_id, p_items);
  return recreated || jsonb_build_object('replaced_order_id', p_order_id);
end;
$$;


--
-- Name: admin_update_saas_org_account(uuid, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_saas_org_account(p_org_id uuid, p_plan_code text, p_module_overrides jsonb DEFAULT '{}'::jsonb, p_feature_overrides jsonb DEFAULT '{}'::jsonb, p_quota_adjustments jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare entry record;
begin
  if not public.current_user_has_saas_admin_permission('edit_orgs') then raise exception 'permission denied'; end if;
  if not exists (select 1 from public.saas_org_settings where org_id = p_org_id) then raise exception 'saas_org_not_found'; end if;
  if nullif(trim(coalesce(p_plan_code, '')), '') is not null and not exists (select 1 from public.saas_plans where lower(code) = lower(trim(p_plan_code)) and is_active) then raise exception 'plan_not_found'; end if;
  update public.saas_org_settings set plan_code = nullif(trim(p_plan_code), ''), module_overrides = coalesce(p_module_overrides, '{}'::jsonb), feature_overrides = coalesce(p_feature_overrides, '{}'::jsonb), updated_at = now(), updated_by = auth.uid() where org_id = p_org_id;
  delete from public.saas_org_entitlements where org_id = p_org_id and source = 'admin_adjustment' and item_kind = 'quota';
  for entry in select key, value from jsonb_each(coalesce(p_quota_adjustments, '{}'::jsonb)) loop
    if coalesce((entry.value #>> '{}')::numeric, 0) <> 0 then insert into public.saas_org_entitlements (org_id, item_kind, entitlement_code, quantity, state, source, created_by) values (p_org_id, 'quota', entry.key, greatest((entry.value #>> '{}')::numeric, 0), 'enabled', 'admin_adjustment', auth.uid()); end if;
  end loop;
  return public.saas_account_overview_payload(p_org_id);
end; $$;


--
-- Name: admin_upsert_saas_catalog_item(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_saas_catalog_item(p_item jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_code text := lower(nullif(trim(coalesce(p_item ->> 'code', '')), ''));
  v_kind text := lower(nullif(trim(coalesce(p_item ->> 'item_kind', '')), ''));
  v_cycle text := lower(coalesce(nullif(trim(p_item ->> 'billing_cycle'), ''), 'one_time'));
  saved public.saas_catalog_items%rowtype;
  old_metadata jsonb;
begin
  if not public.current_user_has_saas_admin_permission('edit_orgs') then raise exception 'permission denied'; end if;
  if v_code is null or v_code !~ '^[a-z0-9_:-]{3,80}$' then raise exception 'catalog_code_invalid'; end if;
  if v_kind not in ('module', 'feature', 'quota', 'bundle') then raise exception 'catalog_kind_invalid'; end if;
  if v_cycle not in ('one_time', 'monthly') then raise exception 'catalog_billing_cycle_invalid'; end if;
  select metadata into old_metadata from public.saas_catalog_items where code = v_code;
  if v_kind = 'bundle' and not (p_item ? 'metadata') and old_metadata is null then raise exception 'bundle_items_required'; end if;
  insert into public.saas_catalog_items(code, title, description, item_kind, entitlement_code, quantity, price_irt, billing_cycle, is_active, is_public, sort_order, metadata)
  values (v_code, nullif(trim(coalesce(p_item ->> 'title', '')), ''), nullif(trim(coalesce(p_item ->> 'description', '')), ''), v_kind, nullif(trim(coalesce(p_item ->> 'entitlement_code', '')), ''), greatest(coalesce((p_item ->> 'quantity')::numeric, 1), 1), greatest(coalesce((p_item ->> 'price_irt')::numeric, 0), 0), v_cycle, coalesce((p_item ->> 'is_active')::boolean, false), coalesce((p_item ->> 'is_public')::boolean, true), coalesce((p_item ->> 'sort_order')::integer, 100), case when p_item ? 'metadata' then coalesce(p_item -> 'metadata', '{}'::jsonb) else coalesce(old_metadata, '{}'::jsonb) end)
  on conflict (code) do update set title = excluded.title, description = excluded.description, item_kind = excluded.item_kind, entitlement_code = excluded.entitlement_code, quantity = excluded.quantity, price_irt = excluded.price_irt, billing_cycle = excluded.billing_cycle, is_active = excluded.is_active, is_public = excluded.is_public, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now()
  returning * into saved;
  if saved.title is null or saved.entitlement_code is null then raise exception 'catalog_title_and_entitlement_required'; end if;
  if saved.item_kind = 'bundle' and jsonb_array_length(coalesce(saved.metadata -> 'included_items', '[]'::jsonb)) = 0 then raise exception 'bundle_items_required'; end if;
  return to_jsonb(saved);
end; $_$;


--
-- Name: admin_upsert_saas_org_candidate(text, uuid, uuid, text, text, text, text, boolean, boolean, timestamp with time zone, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_saas_org_candidate(p_source_kind text DEFAULT 'org'::text, p_source_id uuid DEFAULT NULL::uuid, p_request_id uuid DEFAULT NULL::uuid, p_org_name text DEFAULT NULL::text, p_slug text DEFAULT NULL::text, p_status text DEFAULT 'trial'::text, p_plan_code text DEFAULT NULL::text, p_is_demo boolean DEFAULT true, p_is_readonly boolean DEFAULT false, p_trial_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_primary_contact_mobile text DEFAULT NULL::text, p_owner_name text DEFAULT NULL::text, p_owner_email text DEFAULT NULL::text, p_provisioning_source text DEFAULT NULL::text, p_request_status text DEFAULT NULL::text, p_industry text DEFAULT NULL::text, p_employee_count_band text DEFAULT NULL::text, p_discovery_source text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  normalized_source_kind text := case when lower(trim(coalesce(p_source_kind, 'org'))) = 'request' then 'request' else 'org' end;
  target_request_id uuid := coalesce(p_request_id, case when lower(trim(coalesce(p_source_kind, 'org'))) = 'request' then p_source_id else null end);
  target_org_id uuid := case when lower(trim(coalesce(p_source_kind, 'org'))) = 'org' then p_source_id else null end;
  request_row public.saas_onboarding_requests%rowtype;
  org_settings_row public.saas_org_settings%rowtype;
  normalized_org_name text := nullif(trim(coalesce(p_org_name, '')), '');
  normalized_slug text := nullif(public.normalize_saas_slug(p_slug), '');
  base_slug text;
  final_slug text;
  slug_counter integer := 0;
  normalized_status text := lower(trim(coalesce(p_status, 'trial')));
begin
  if not public.current_user_has_saas_admin_permission() then
    raise exception 'permission denied';
  end if;

  if normalized_source_kind = 'request' then
    if target_request_id is null then
      return jsonb_build_object('success', false, 'message', 'شناسه درخواست برای ویرایش در دسترس نیست.');
    end if;

    update public.saas_onboarding_requests
    set
      full_name = coalesce(nullif(trim(coalesce(p_owner_name, '')), ''), full_name),
      email = coalesce(nullif(trim(coalesce(p_owner_email, '')), ''), email),
      mobile = coalesce(nullif(trim(coalesce(p_primary_contact_mobile, '')), ''), mobile),
      organization_name = coalesce(normalized_org_name, organization_name),
      business_name = coalesce(normalized_org_name, business_name),
      requested_slug = coalesce(normalized_slug, requested_slug),
      status = coalesce(nullif(trim(coalesce(p_request_status, '')), ''), status),
      is_demo_request = coalesce(p_is_demo, is_demo_request),
      industry = coalesce(nullif(trim(coalesce(p_industry, '')), ''), industry),
      employee_count_band = coalesce(nullif(trim(coalesce(p_employee_count_band, '')), ''), employee_count_band),
      discovery_source = coalesce(nullif(trim(coalesce(p_discovery_source, '')), ''), discovery_source),
      updated_at = now()
    where id = target_request_id
    returning * into request_row;

    if request_row.id is null then
      return jsonb_build_object('success', false, 'message', 'درخواست دمو یافت نشد.');
    end if;

    return jsonb_build_object(
      'success', true,
      'source_id', request_row.id,
      'request_id', request_row.id
    );
  end if;

  if normalized_org_name is null then
    return jsonb_build_object('success', false, 'message', 'نام سازمان الزامی است.');
  end if;

  if target_org_id is not null then
    select * into org_settings_row
    from public.saas_org_settings
    where org_id = target_org_id;
  end if;

  base_slug := coalesce(
    normalized_slug,
    nullif(public.normalize_saas_slug(normalized_org_name), ''),
    'org' || to_char(now(), 'YYMMDDHH24MISS')
  );
  final_slug := base_slug;

  loop
    exit when not exists (
      select 1
      from public.saas_org_settings s
      where lower(coalesce(s.slug, '')) = lower(final_slug)
        and (target_org_id is null or s.org_id <> target_org_id)
    ) and not exists (
      select 1
      from public.organizations o
      where lower(coalesce(o.slug, '')) = lower(final_slug)
        and (target_org_id is null or o.id <> target_org_id)
    );
    slug_counter := slug_counter + 1;
    final_slug := base_slug || '-' || slug_counter::text;
    if slug_counter > 200 then
      return jsonb_build_object('success', false, 'message', 'Slug یکتا پیدا نشد.');
    end if;
  end loop;

  if target_org_id is null then
    insert into public.organizations (
      name,
      slug,
      is_active,
      created_at,
      updated_at
    )
    values (
      normalized_org_name,
      final_slug,
      normalized_status <> 'suspended',
      now(),
      now()
    )
    returning id into target_org_id;

    insert into public.saas_org_settings (
      org_id,
      slug,
      status,
      plan_code,
      trial_ends_at,
      is_demo,
      is_readonly,
      resolved_host,
      dns_status,
      provisioning_source,
      provisioned_at,
      primary_contact_mobile,
      request_id,
      owner_name,
      owner_email,
      created_at,
      updated_at
    )
    values (
      target_org_id,
      final_slug,
      normalized_status,
      nullif(trim(coalesce(p_plan_code, '')), ''),
      p_trial_ends_at,
      coalesce(p_is_demo, true),
      coalesce(p_is_readonly, false),
      null,
      'pending',
      coalesce(nullif(trim(coalesce(p_provisioning_source, '')), ''), 'manual_admin'),
      now(),
      nullif(trim(coalesce(p_primary_contact_mobile, '')), ''),
      target_request_id,
      nullif(trim(coalesce(p_owner_name, '')), ''),
      nullif(trim(coalesce(p_owner_email, '')), ''),
      now(),
      now()
    );
  else
    update public.organizations
    set
      name = normalized_org_name,
      slug = final_slug,
      is_active = normalized_status <> 'suspended',
      updated_at = now()
    where id = target_org_id;

    update public.saas_org_settings
    set
      slug = final_slug,
      status = normalized_status,
      plan_code = nullif(trim(coalesce(p_plan_code, '')), ''),
      trial_ends_at = coalesce(p_trial_ends_at, trial_ends_at),
      is_demo = coalesce(p_is_demo, is_demo),
      is_readonly = coalesce(p_is_readonly, is_readonly),
      primary_contact_mobile = coalesce(nullif(trim(coalesce(p_primary_contact_mobile, '')), ''), primary_contact_mobile),
      provisioning_source = coalesce(nullif(trim(coalesce(p_provisioning_source, '')), ''), provisioning_source),
      request_id = coalesce(target_request_id, request_id),
      owner_name = coalesce(nullif(trim(coalesce(p_owner_name, '')), ''), owner_name),
      owner_email = coalesce(nullif(trim(coalesce(p_owner_email, '')), ''), owner_email),
      updated_at = now()
    where org_id = target_org_id;
  end if;

  if target_request_id is not null then
    update public.saas_onboarding_requests
    set
      org_id = coalesce(org_id, target_org_id),
      organization_name = coalesce(normalized_org_name, organization_name),
      business_name = coalesce(normalized_org_name, business_name),
      requested_slug = coalesce(final_slug, requested_slug),
      full_name = coalesce(nullif(trim(coalesce(p_owner_name, '')), ''), full_name),
      email = coalesce(nullif(trim(coalesce(p_owner_email, '')), ''), email),
      mobile = coalesce(nullif(trim(coalesce(p_primary_contact_mobile, '')), ''), mobile),
      is_demo_request = coalesce(p_is_demo, is_demo_request),
      industry = coalesce(nullif(trim(coalesce(p_industry, '')), ''), industry),
      employee_count_band = coalesce(nullif(trim(coalesce(p_employee_count_band, '')), ''), employee_count_band),
      discovery_source = coalesce(nullif(trim(coalesce(p_discovery_source, '')), ''), discovery_source),
      updated_at = now()
    where id = target_request_id;
  end if;

  return jsonb_build_object(
    'success', true,
    'source_id', target_org_id,
    'org_id', target_org_id
  );
end;
$$;


--
-- Name: advertising_campaign_collaboration_workspace(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_collaboration_workspace(p_campaign_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org uuid := public.current_org_id(); v_role uuid := public.current_user_advertising_campaign_role_id();
        v_campaign jsonb; v_tools jsonb;
begin
  if auth.uid() is null or v_org is null
     or not public.current_user_can_access_advertising_campaign_module()
     or not public.current_user_has_role_permission_entry('advertising_campaigns','view',null,true) then
    raise exception 'دسترسی کمپین فعال نیست.' using errcode = '42501';
  end if;
  select jsonb_build_object(
      'id',c.id,'name',c.name,'system_code',c.system_code,'status',c.status,
      'image_url',c.image_url,'start_at',c.start_at,'end_at',c.end_at,'access_mode','tool_limited'
    ) into v_campaign
  from public.advertising_campaigns c
  where c.id=p_campaign_id and c.org_id=v_org
    and exists (
      select 1 from public.advertising_campaign_tools t where t.campaign_id=c.id and t.org_id=v_org
        and (auth.uid()=any(t.collaborator_user_ids) or v_role=any(t.collaborator_role_ids))
    );
  if v_campaign is null then raise exception 'کمپین یا همکاری مجاز پیدا نشد.' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id',t.id,'campaign_id',t.campaign_id,'tool_type',t.tool_type,'title',t.title,
      'enabled',t.enabled,'status',t.status,'is_automated',t.is_automated,
      'actual_cost',t.actual_cost,'actual_leads',t.actual_leads,'actual_customers',t.actual_customers,
      'actual_start_at',t.actual_start_at,'actual_end_at',t.actual_end_at,'result_summary',t.result_summary,
      'updated_at',t.updated_at
    ) order by t.created_at), '[]'::jsonb) into v_tools
  from public.advertising_campaign_tools t
  where t.campaign_id=p_campaign_id and t.org_id=v_org
    and (auth.uid()=any(t.collaborator_user_ids) or v_role=any(t.collaborator_role_ids));
  return jsonb_build_object('campaign',v_campaign,'tools',v_tools);
end;
$$;


--
-- Name: advertising_campaign_condition_matches(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_condition_matches(p_record jsonb, p_condition jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_field text := nullif(btrim(coalesce(p_condition->>'field','')), '');
  v_operator text := lower(btrim(coalesce(p_condition->>'operator','equals')));
  v_actual jsonb;
  v_expected jsonb := p_condition->'value';
  v_actual_text text;
  v_expected_text text;
  v_actual_num numeric;
  v_expected_num numeric;
begin
  if v_field is null or p_record is null then return false; end if;
  v_actual := p_record -> v_field;
  v_actual_text := lower(btrim(coalesce(p_record->>v_field,'')));
  v_expected_text := lower(btrim(coalesce(p_condition->>'value','')));

  if v_operator in ('is_empty','empty','is_null') then
    return v_actual is null or v_actual = 'null'::jsonb or v_actual_text = '';
  elsif v_operator in ('is_not_empty','not_empty','is_not_null') then
    return not (v_actual is null or v_actual = 'null'::jsonb or v_actual_text = '');
  elsif v_operator in ('equals','eq','=') then
    return v_actual_text = v_expected_text;
  elsif v_operator in ('not_equals','neq','!=','<>') then
    return v_actual_text <> v_expected_text;
  elsif v_operator in ('contains','includes') then
    if jsonb_typeof(v_actual) = 'array' then return v_actual @> jsonb_build_array(v_expected); end if;
    return position(v_expected_text in v_actual_text) > 0;
  elsif v_operator in ('not_contains','excludes') then
    if jsonb_typeof(v_actual) = 'array' then return not (v_actual @> jsonb_build_array(v_expected)); end if;
    return position(v_expected_text in v_actual_text) = 0;
  elsif v_operator in ('in','one_of') then
    return jsonb_typeof(v_expected) = 'array'
       and exists (select 1 from jsonb_array_elements_text(v_expected) x where lower(btrim(x)) = v_actual_text);
  elsif v_operator in ('not_in','none_of') then
    return jsonb_typeof(v_expected) <> 'array'
       or not exists (select 1 from jsonb_array_elements_text(v_expected) x where lower(btrim(x)) = v_actual_text);
  end if;

  begin
    v_actual_num := nullif(v_actual_text,'')::numeric;
    v_expected_num := nullif(v_expected_text,'')::numeric;
  exception when invalid_text_representation then return false;
  end;
  if v_operator in ('greater_than','gt','>') then return v_actual_num > v_expected_num; end if;
  if v_operator in ('greater_or_equal','gte','>=') then return v_actual_num >= v_expected_num; end if;
  if v_operator in ('less_than','lt','<') then return v_actual_num < v_expected_num; end if;
  if v_operator in ('less_or_equal','lte','<=') then return v_actual_num <= v_expected_num; end if;
  return false;
end;
$$;


--
-- Name: advertising_campaign_conditions_match(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_conditions_match(p_record jsonb, p_all jsonb, p_any jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select
    not exists (
      select 1 from jsonb_array_elements(
        case when jsonb_typeof(p_all) = 'array' then p_all else '[]'::jsonb end
      ) c where not public.advertising_campaign_condition_matches(p_record, c)
    )
    and (
      jsonb_array_length(case when jsonb_typeof(p_any) = 'array' then p_any else '[]'::jsonb end) = 0
      or exists (
        select 1 from jsonb_array_elements(
          case when jsonb_typeof(p_any) = 'array' then p_any else '[]'::jsonb end
        ) c where public.advertising_campaign_condition_matches(p_record, c)
      )
    )
$$;


--
-- Name: advertising_campaign_contact_key(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_contact_key(p_channel text, p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare v_channel text := lower(btrim(coalesce(p_channel,'')));
        v_value text := btrim(public.advertising_campaign_normalize_digits(p_value));
begin
  if v_channel = 'sms' then return public.kalam_phone_lookup_key(v_value); end if;
  if v_channel = 'email' then return lower(v_value); end if;
  return regexp_replace(lower(v_value), '\s+', '', 'g');
end;
$$;


--
-- Name: advertising_campaign_dashboard_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_dashboard_summary(p_campaign_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_result jsonb;
begin
  if not public.can_view_advertising_campaign(p_campaign_id) then
    raise exception 'دسترسی مشاهده کمپین را ندارید.' using errcode='42501';
  end if;
  select jsonb_build_object(
    'campaign_id', c.id,
    'estimated_cost', coalesce(sum(t.estimated_cost),0),
    'actual_cost', coalesce(sum(t.actual_cost),0),
    'expected_leads', coalesce(sum(t.expected_leads),0),
    'recorded_actual_leads', coalesce(sum(t.actual_leads),0),
    'expected_customers', coalesce(sum(t.expected_customers),0),
    'recorded_actual_customers', coalesce(sum(t.actual_customers),0),
    'attributed_leads', (select count(*) from public.marketing_leads l where l.org_id=c.org_id and l.advertising_campaign_id=c.id),
    'actual_leads', (select count(*) from public.marketing_leads l where l.org_id=c.org_id and l.advertising_campaign_id=c.id),
    'attributed_customers', (select count(*) from public.customers x where x.org_id=c.org_id and x.advertising_campaign_id=c.id),
    'actual_customers', (select count(*) from public.customers x where x.org_id=c.org_id and x.advertising_campaign_id=c.id),
    'attributed_invoices', (select count(*) from public.invoices i where i.org_id=c.org_id and i.advertising_campaign_id=c.id),
    'invoice_count', (select count(*) from public.invoices i where i.org_id=c.org_id and i.advertising_campaign_id=c.id),
    'attributed_revenue', (select coalesce(sum(coalesce(
      nullif(to_jsonb(i)->>'grand_total','')::numeric,
      nullif(to_jsonb(i)->>'final_total','')::numeric,
      nullif(to_jsonb(i)->>'total_invoice_amount','')::numeric,
      nullif(to_jsonb(i)->>'total_amount','')::numeric,0)),0)
      from public.invoices i where i.org_id=c.org_id and i.advertising_campaign_id=c.id),
    'sent_count',(select count(*) from public.outbound_messages m where m.org_id=c.org_id and m.advertising_campaign_id=c.id and m.status in ('provider_accepted','sent','delivered')),
    'delivered_count',(select count(*) from public.outbound_messages m where m.org_id=c.org_id and m.advertising_campaign_id=c.id and m.status='delivered'),
    'failed_count',(select count(*) from public.outbound_messages m where m.org_id=c.org_id and m.advertising_campaign_id=c.id and m.status in ('failed','not_delivered','operator_failed','filtered','blacklisted')),
    'replied_count',(select count(*) from public.advertising_campaign_responses r where r.org_id=c.org_id and r.campaign_id=c.id),
    'unsubscribed_count',(select count(*) from public.campaign_contact_suppressions s join public.advertising_campaign_responses r on r.id=s.source_response_id where r.campaign_id=c.id and s.org_id=c.org_id and s.is_active),
    'timeline',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'date',daily.day,'leads',daily.leads,'customers',daily.customers,
        'invoices',daily.invoices,'revenue',daily.revenue
      ) order by daily.day),'[]'::jsonb)
      from (
        select event_day as day,sum(leads) leads,sum(customers) customers,
               sum(invoices) invoices,sum(revenue) revenue
        from (
          select l.created_at::date event_day,count(*)::bigint leads,0::bigint customers,
                 0::bigint invoices,0::numeric revenue
          from public.marketing_leads l
          where l.org_id=c.org_id and l.advertising_campaign_id=c.id
            and l.created_at>=greatest(coalesce(c.start_at,now()-interval '365 days'),now()-interval '365 days')
          group by l.created_at::date
          union all
          select x.created_at::date,0::bigint,count(*)::bigint,0::bigint,0::numeric
          from public.customers x
          where x.org_id=c.org_id and x.advertising_campaign_id=c.id
            and x.created_at>=greatest(coalesce(c.start_at,now()-interval '365 days'),now()-interval '365 days')
          group by x.created_at::date
          union all
          select i.created_at::date,0::bigint,0::bigint,count(*)::bigint,
                 coalesce(sum(coalesce(nullif(to_jsonb(i)->>'grand_total','')::numeric,
                   nullif(to_jsonb(i)->>'final_total','')::numeric,
                   nullif(to_jsonb(i)->>'total_invoice_amount','')::numeric,0)),0)
          from public.invoices i
          where i.org_id=c.org_id and i.advertising_campaign_id=c.id
            and i.created_at>=greatest(coalesce(c.start_at,now()-interval '365 days'),now()-interval '365 days')
          group by i.created_at::date
        ) events group by event_day
      ) daily
    ),
    'delivery', jsonb_build_object(
      'total',(select count(*) from public.outbound_messages m where m.org_id=c.org_id and m.advertising_campaign_id=c.id),
      'succeeded',(select count(*) from public.outbound_messages m where m.org_id=c.org_id and m.advertising_campaign_id=c.id and m.status in ('provider_accepted','sent','delivered')),
      'failed',(select count(*) from public.outbound_messages m where m.org_id=c.org_id and m.advertising_campaign_id=c.id and m.status in ('failed','not_delivered','operator_failed','filtered','blacklisted')),
      'responses',(select count(*) from public.advertising_campaign_responses r where r.org_id=c.org_id and r.campaign_id=c.id)
    ),
    'tools', coalesce(jsonb_agg(jsonb_build_object(
      'id',t.id,'tool_type',t.tool_type,'title',t.title,'status',t.status,
      'estimated_cost',t.estimated_cost,'actual_cost',t.actual_cost,
      'expected_leads',t.expected_leads,'actual_leads',t.actual_leads,
      'expected_customers',t.expected_customers,'actual_customers',t.actual_customers,
      'planned_start_at',t.planned_start_at,'planned_end_at',t.planned_end_at,
      'actual_start_at',t.actual_start_at,'actual_end_at',t.actual_end_at,
      'attributed_leads',(select count(*) from public.marketing_leads l where l.org_id=c.org_id and l.advertising_campaign_tool_id=t.id),
      'attributed_customers',(select count(*) from public.customers x where x.org_id=c.org_id and x.advertising_campaign_tool_id=t.id),
      'attributed_invoices',(select count(*) from public.invoices i where i.org_id=c.org_id and i.advertising_campaign_tool_id=t.id)
    ) order by t.created_at) filter (where t.id is not null),'[]'::jsonb)
  ) into v_result
  from public.advertising_campaigns c
  left join public.advertising_campaign_tools t on t.campaign_id=c.id and t.enabled=true
  where c.id=p_campaign_id and c.org_id=public.current_org_id()
  group by c.id,c.org_id;
  return coalesce(v_result,'{}'::jsonb);
end;
$$;


--
-- Name: advertising_campaign_inbound_rule_matches(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_inbound_rule_matches(p_config jsonb, p_message text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare v_normalized text:=lower(regexp_replace(public.advertising_campaign_normalize_digits(p_message),'\s+','','g'));
        v_mode text:=lower(btrim(coalesce(p_config->>'inbound_match_mode','exact'))); v_expected text;
begin
  if coalesce((p_config->>'inbound_enabled')::boolean,false) is not true
     or jsonb_typeof(p_config->'inbound_expected_values') <> 'array'
     or jsonb_array_length(p_config->'inbound_expected_values')=0 then return false; end if;
  for v_expected in select value from jsonb_array_elements_text(p_config->'inbound_expected_values') loop
    v_expected:=lower(regexp_replace(public.advertising_campaign_normalize_digits(v_expected),'\s+','','g'));
    if v_expected<>'' and ((v_mode='contains' and position(v_expected in v_normalized)>0)
       or (v_mode<>'contains' and v_expected=v_normalized)) then return true; end if;
  end loop;
  return false;
exception when invalid_text_representation then return false;
end;
$$;


--
-- Name: advertising_campaign_normalize_digits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_normalize_digits(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select translate(coalesce(p_value, ''), '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789')
$$;


--
-- Name: advertising_campaign_preview_audience(uuid, text, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_preview_audience(p_campaign_id uuid, p_target_module_id text, p_conditions_all jsonb DEFAULT NULL::jsonb, p_conditions_any jsonb DEFAULT NULL::jsonb, p_sample_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_table text;
  v_all jsonb;
  v_any jsonb;
  v_row jsonb;
  v_count bigint := 0;
  v_samples jsonb := '[]'::jsonb;
  v_limit integer := least(greatest(coalesce(p_sample_limit,20),0),100);
  v_title text;
begin
  if not public.can_view_advertising_campaign(p_campaign_id) then
    raise exception 'دسترسی مشاهده کمپین را ندارید.' using errcode = '42501';
  end if;
  v_table := case p_target_module_id
    when 'marketing_leads' then 'marketing_leads'
    when 'customers' then 'customers'
    when 'invoices' then 'invoices'
    else null end;
  if v_table is null then raise exception 'ماژول هدف مخاطبان معتبر نیست.' using errcode = '22023'; end if;

  select coalesce(p_conditions_all, r.conditions_all, '[]'::jsonb),
         coalesce(p_conditions_any, r.conditions_any, '[]'::jsonb)
    into v_all, v_any
  from (select 1) seed
  left join public.advertising_campaign_audience_rules r
    on r.campaign_id = p_campaign_id and r.target_module_id = p_target_module_id and r.enabled = true;

  for v_row in execute format('select to_jsonb(t) from public.%I t where t.org_id = $1', v_table)
    using public.current_org_id()
  loop
    if public.advertising_campaign_conditions_match(v_row, v_all, v_any) then
      v_count := v_count + 1;
      if jsonb_array_length(v_samples) < v_limit then
        v_title := coalesce(
          nullif(v_row->>'name',''), nullif(v_row->>'full_name',''),
          nullif(v_row->>'business_name',''), nullif(v_row->>'system_code',''), '[بدون عنوان]'
        );
        v_samples := v_samples || jsonb_build_array(jsonb_build_object(
          'id', v_row->>'id', 'title', v_title, 'system_code', nullif(v_row->>'system_code','')
        ));
      end if;
    end if;
  end loop;
  return jsonb_build_object('target_module_id',p_target_module_id,'count',v_count,'samples',v_samples);
end;
$_$;


--
-- Name: advertising_campaign_reply_window_hours(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_reply_window_hours(p_config jsonb) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare v_value integer; v_unit text;
begin
  v_value:=coalesce(nullif(p_config->>'reply_window_value','')::integer,
                    nullif(p_config->>'reply_window_hours','')::integer,72);
  v_unit:=lower(btrim(coalesce(p_config->>'reply_window_unit','hour')));
  if v_unit='day' then v_value:=v_value*24; end if;
  return least(greatest(v_value,1),8760);
exception when invalid_text_representation or numeric_value_out_of_range then
  return 72;
end;
$$;


--
-- Name: advertising_campaign_tool_report(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advertising_campaign_tool_report(p_tool_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_tool public.advertising_campaign_tools%rowtype; v_limit int:=least(greatest(coalesce(p_limit,50),1),200);
        v_offset int:=greatest(coalesce(p_offset,0),0); v_records jsonb:='{}'::jsonb;
begin
  select * into v_tool from public.advertising_campaign_tools where id=p_tool_id and org_id=public.current_org_id();
  if v_tool.id is null or not public.can_collaborate_advertising_campaign_tool(p_tool_id) then
    raise exception 'دسترسی ابزار کمپین را ندارید.' using errcode='42501';
  end if;
  if public.current_user_has_role_permission_entry('marketing_leads','view',null,true) then
    v_records := v_records || jsonb_build_object('leads', coalesce((select jsonb_agg(x) from (
      select l.id,coalesce(nullif(l.name,''),nullif(l.business_name,''),nullif(l.system_code,''),'[بدون عنوان]') title,l.system_code,l.status,l.created_at
      from public.marketing_leads l where l.org_id=v_tool.org_id and l.advertising_campaign_tool_id=p_tool_id
      order by l.created_at desc limit v_limit offset v_offset) x),'[]'::jsonb));
  end if;
  if public.current_user_has_role_permission_entry('customers','view',null,true) then
    v_records := v_records || jsonb_build_object('customers', coalesce((select jsonb_agg(x) from (
      select c.id,coalesce(nullif(c.full_name,''),nullif(c.business_name,''),nullif(c.system_code,''),'[بدون عنوان]') title,c.system_code,c.created_at
      from public.customers c where c.org_id=v_tool.org_id and c.advertising_campaign_tool_id=p_tool_id
      order by c.created_at desc limit v_limit offset v_offset) x),'[]'::jsonb));
  end if;
  if public.current_user_has_role_permission_entry('invoices','view',null,true) then
    v_records := v_records || jsonb_build_object('invoices', coalesce((select jsonb_agg(x) from (
      select i.id,coalesce(nullif(i.name,''),nullif(i.system_code,''),'[بدون عنوان]') title,i.system_code,i.status,i.created_at,i.total_invoice_amount
      from public.invoices i where i.org_id=v_tool.org_id and i.advertising_campaign_tool_id=p_tool_id
      order by i.created_at desc limit v_limit offset v_offset) x),'[]'::jsonb));
  end if;
  return v_records || jsonb_build_object(
    'summary',jsonb_build_object(
      'estimated_cost',v_tool.estimated_cost,'actual_cost',v_tool.actual_cost,
      'expected_leads',v_tool.expected_leads,
      'actual_leads',(select count(*) from public.marketing_leads l where l.org_id=v_tool.org_id and l.advertising_campaign_tool_id=p_tool_id),
      'expected_customers',v_tool.expected_customers,
      'actual_customers',(select count(*) from public.customers c where c.org_id=v_tool.org_id and c.advertising_campaign_tool_id=p_tool_id),
      'invoice_count',(select count(*) from public.invoices i where i.org_id=v_tool.org_id and i.advertising_campaign_tool_id=p_tool_id),
      'attributed_revenue',(select coalesce(sum(coalesce(nullif(to_jsonb(i)->>'total_invoice_amount','')::numeric,nullif(to_jsonb(i)->>'grand_total','')::numeric,0)),0) from public.invoices i where i.org_id=v_tool.org_id and i.advertising_campaign_tool_id=p_tool_id),
      'sent_count',(select count(*) from public.outbound_messages m where m.org_id=v_tool.org_id and m.advertising_campaign_tool_id=p_tool_id and m.status in ('provider_accepted','sent','delivered')),
      'delivered_count',(select count(*) from public.outbound_messages m where m.org_id=v_tool.org_id and m.advertising_campaign_tool_id=p_tool_id and m.status='delivered'),
      'failed_count',(select count(*) from public.outbound_messages m where m.org_id=v_tool.org_id and m.advertising_campaign_tool_id=p_tool_id and m.status in ('failed','not_delivered','operator_failed','filtered','blacklisted')),
      'replied_count',(select count(*) from public.advertising_campaign_responses r where r.org_id=v_tool.org_id and r.tool_id=p_tool_id),
      'unsubscribed_count',(select count(*) from public.campaign_contact_suppressions s join public.advertising_campaign_responses r on r.id=s.source_response_id where r.tool_id=p_tool_id and s.org_id=v_tool.org_id and s.is_active)
    ),
    'tool',jsonb_build_object('id',v_tool.id,'tool_type',v_tool.tool_type,'title',v_tool.title,'status',v_tool.status,
      'estimated_cost',v_tool.estimated_cost,'actual_cost',v_tool.actual_cost,'expected_leads',v_tool.expected_leads,
      'actual_leads',v_tool.actual_leads,'expected_customers',v_tool.expected_customers,'actual_customers',v_tool.actual_customers),
    'totals',jsonb_build_object(
      'leads',(select count(*) from public.marketing_leads l where l.org_id=v_tool.org_id and l.advertising_campaign_tool_id=p_tool_id),
      'customers',(select count(*) from public.customers c where c.org_id=v_tool.org_id and c.advertising_campaign_tool_id=p_tool_id),
      'invoices',(select count(*) from public.invoices i where i.org_id=v_tool.org_id and i.advertising_campaign_tool_id=p_tool_id),
      'messages',(select count(*) from public.outbound_messages m where m.org_id=v_tool.org_id and m.advertising_campaign_tool_id=p_tool_id),
      'responses',(select count(*) from public.advertising_campaign_responses r where r.org_id=v_tool.org_id and r.tool_id=p_tool_id)
    ),'records',v_records,'limit',v_limit,'offset',v_offset);
end;
$$;


--
-- Name: ai_message_notification_ready(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_message_notification_ready(p_role text, p_content text, p_metadata jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
 select p_role='assistant' and length(trim(coalesce(p_content,'')))>0
  and coalesce(p_metadata->>'status','')<>'failed'
  and not coalesce(p_metadata,'{}'::jsonb) @> '{"pending_status":true}'
  and not coalesce(p_metadata,'{}'::jsonb) @> '{"streaming":true}'
  and not coalesce(p_metadata,'{}'::jsonb) @> '{"failed":true}'
  and not coalesce(p_metadata,'{}'::jsonb) @> '{"incomplete":true}'
  and not coalesce(p_metadata,'{}'::jsonb) @> '{"stopped":true}'
  and not coalesce(p_metadata,'{}'::jsonb) @> '{"internal_agent_step":true}'
  and not coalesce(p_metadata,'{}'::jsonb) @> '{"internal_agent_input":true}';
$$;


--
-- Name: ai_usage_token_count(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_usage_token_count(p_metadata jsonb) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  with source as (select case when jsonb_typeof(p_metadata->'usage')='object' then p_metadata->'usage' else coalesce(p_metadata,'{}'::jsonb) end j),
  values_text as (select coalesce(j->>'total_tokens',j->>'total',j->>'tokens',j->>'totalTokens') total,
    coalesce(j->>'prompt_tokens',j->>'prompt',j->>'input_tokens',j->>'input',j->>'promptTokens') input,
    coalesce(j->>'completion_tokens',j->>'completion',j->>'output_tokens',j->>'output',j->>'completionTokens') output from source)
  select greatest(0,ceil(case when total ~ '^-?\d+(\.\d+)?$' then total::numeric else
    (case when input ~ '^-?\d+(\.\d+)?$' then input::numeric else 0 end)+
    (case when output ~ '^-?\d+(\.\d+)?$' then output::numeric else 0 end) end)) from values_text;
$_$;


--
-- Name: allocate_invoice_payment_excess(text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_invoice_payment_excess(p_module_id text, p_source_invoice_id uuid, p_source_row_key text, p_source_payments jsonb, p_allocations jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_party_id uuid;
  v_source_total numeric(18,2);
  v_source_paid numeric(18,2) := 0;
  v_allocated numeric(18,2) := 0;
  v_item jsonb;
  v_payment jsonb;
  v_target_id uuid;
  v_target_party_id uuid;
  v_target_remaining numeric(18,2);
  v_amount numeric(18,2);
  v_status text;
  v_changed_ids uuid[] := array[p_source_invoice_id];
begin
  if v_org_id is null then
    raise exception 'سازمان فعال مشخص نیست.';
  end if;
  if p_module_id not in ('invoices', 'purchase_invoices') then
    raise exception 'ماژول فاکتور معتبر نیست.';
  end if;
  if p_source_invoice_id is null or nullif(trim(p_source_row_key), '') is null then
    raise exception 'اطلاعات ردیف مبدا کامل نیست.';
  end if;
  if jsonb_typeof(coalesce(p_source_payments, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_allocations, '[]'::jsonb)) <> 'array' then
    raise exception 'ساختار تخصیص معتبر نیست.';
  end if;

  if p_module_id = 'invoices' then
    select customer_id, total_invoice_amount
      into v_party_id, v_source_total
    from public.invoices
    where id = p_source_invoice_id
      and org_id = v_org_id
    for update;
  else
    select supplier_id, total_invoice_amount
      into v_party_id, v_source_total
    from public.purchase_invoices
    where id = p_source_invoice_id
      and org_id = v_org_id
    for update;
  end if;

  if v_party_id is null then
    raise exception 'فاکتور مبدا یا طرف حساب آن یافت نشد.';
  end if;

  for v_payment in select value from jsonb_array_elements(p_source_payments) loop
    v_status := lower(trim(coalesce(v_payment->>'status', '')));
    if (v_payment ? 'status')
       and v_status <> ''
       and v_status not in ('received', 'paid', 'approved', 'cleared') then
      continue;
    end if;
    begin
      v_source_paid := v_source_paid + abs(coalesce((v_payment->>'amount')::numeric, 0));
    exception when others then
      raise exception 'مبلغ یکی از ردیف‌های دریافت/پرداخت معتبر نیست.';
    end;
  end loop;

  if v_source_paid > coalesce(v_source_total, 0) then
    raise exception 'مبلغ فاکتور مبدا پس از تخصیص همچنان بیشتر از جمع فاکتور است.';
  end if;
  if abs(v_source_paid - coalesce(v_source_total, 0)) > 0.01 then
    raise exception 'برای توزیع اضافه‌مبلغ، فاکتور مبدا باید تا سقف مبلغ خود تسویه شود.';
  end if;

  for v_item in select value from jsonb_array_elements(p_allocations) loop
    begin
      v_amount := round(abs(coalesce((v_item->>'amount')::numeric, 0)), 2);
      v_target_id := (v_item->>'invoice_id')::uuid;
    exception when others then
      raise exception 'یکی از مقادیر تخصیص معتبر نیست.';
    end;
    if v_amount <= 0 or v_target_id = p_source_invoice_id then
      raise exception 'مقصد یا مبلغ تخصیص معتبر نیست.';
    end if;
    if jsonb_typeof(v_item->'payment_row') <> 'object' then
      raise exception 'اطلاعات ردیف تخصیص ناقص است.';
    end if;
    v_allocated := v_allocated + v_amount;
  end loop;

  if v_allocated <= 0 then
    raise exception 'حداقل یک تخصیص معتبر لازم است.';
  end if;

  -- Lock all destinations in a stable order before validating capacities.
  if p_module_id = 'invoices' then
    perform 1
    from public.invoices i
    where i.id in (
      select distinct (value->>'invoice_id')::uuid
      from jsonb_array_elements(p_allocations)
    )
      and i.org_id = v_org_id
    order by i.id
    for update;
  else
    perform 1
    from public.purchase_invoices i
    where i.id in (
      select distinct (value->>'invoice_id')::uuid
      from jsonb_array_elements(p_allocations)
    )
      and i.org_id = v_org_id
    order by i.id
    for update;
  end if;

  if p_module_id = 'invoices' then
    update public.invoices
    set payments = p_source_payments
    where id = p_source_invoice_id
      and org_id = v_org_id;
  else
    update public.purchase_invoices
    set payments = p_source_payments
    where id = p_source_invoice_id
      and org_id = v_org_id;
  end if;

  for v_item in select value from jsonb_array_elements(p_allocations) loop
    v_target_id := (v_item->>'invoice_id')::uuid;
    v_amount := round(abs((v_item->>'amount')::numeric), 2);

    if p_module_id = 'invoices' then
      select customer_id, remaining_balance
        into v_target_party_id, v_target_remaining
      from public.invoices
      where id = v_target_id
        and org_id = v_org_id
        and status is distinct from 'canceled';
    else
      select supplier_id, remaining_balance
        into v_target_party_id, v_target_remaining
      from public.purchase_invoices
      where id = v_target_id
        and org_id = v_org_id
        and status is distinct from 'canceled';
    end if;

    if v_target_party_id is null or v_target_party_id <> v_party_id then
      raise exception 'یکی از فاکتورهای مقصد متعلق به این طرف حساب نیست.';
    end if;
    if coalesce(v_target_remaining, 0) < v_amount then
      raise exception 'مانده یکی از فاکتورهای مقصد برای تخصیص کافی نیست.';
    end if;

    v_payment := (v_item->'payment_row')
      || jsonb_build_object(
        'amount', v_amount,
        '_cash_bank_operation_id', null,
        'allocation_source_invoice_id', p_source_invoice_id,
        'allocation_source_row_key', p_source_row_key
      );

    if p_module_id = 'invoices' then
      update public.invoices
      set payments = coalesce(payments, '[]'::jsonb) || jsonb_build_array(v_payment)
      where id = v_target_id
        and org_id = v_org_id;
    else
      update public.purchase_invoices
      set payments = coalesce(payments, '[]'::jsonb) || jsonb_build_array(v_payment)
      where id = v_target_id
        and org_id = v_org_id;
    end if;

    if not (v_target_id = any(v_changed_ids)) then
      v_changed_ids := array_append(v_changed_ids, v_target_id);
    end if;
  end loop;

  return (
    select jsonb_agg(jsonb_build_object('invoice_id', changed_id))
    from unnest(v_changed_ids) as changed_id
  );
end;
$$;


--
-- Name: allow_public_confirmation_otp_request(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allow_public_confirmation_otp_request(p_scope text, p_source_token text, p_module text, p_party text, p_phone text, p_client_ip text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_scope text := btrim(coalesce(p_scope, ''));
  v_source_token text := btrim(coalesce(p_source_token, ''));
  v_module text := btrim(coalesce(p_module, ''));
  v_party text := btrim(coalesce(p_party, ''));
  v_phone text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  v_client_ip text := nullif(btrim(coalesce(p_client_ip, '')), '');
  v_source_hash text;
  v_phone_hash text;
  v_ip_hash text;
  v_last_request_at timestamptz;
  v_window_count integer;
  v_request_id uuid;
  v_retry_after integer;
begin
  if v_scope not in ('invoice_confirmation', 'delivery_confirmation')
     or v_source_token = ''
     or length(v_source_token) > 256
     or v_module not in ('invoices', 'purchase_invoices', 'delivery_forms')
     or (v_scope = 'delivery_confirmation' and v_party not in ('delivered_by', 'received_by'))
     or (v_scope = 'invoice_confirmation' and v_party <> '')
     or v_phone !~ '^09[0-9]{9}$' then
    return jsonb_build_object('allowed', false, 'error', 'invalid_otp_request');
  end if;

  v_source_hash := encode(
    extensions.digest(v_scope || chr(31) || lower(v_module) || chr(31) || lower(v_party) || chr(31) || lower(v_source_token), 'sha256'),
    'hex'
  );
  v_phone_hash := encode(extensions.digest(v_phone, 'sha256'), 'hex');
  if v_client_ip is not null
     and length(v_client_ip) <= 64
     and v_client_ip ~ '^[0-9A-Fa-f:.]+$' then
    v_ip_hash := encode(extensions.digest(lower(v_client_ip), 'sha256'), 'hex');
  else
    v_ip_hash := null;
  end if;

  -- همزمانی درخواست‌های یک لینک را serialize می‌کند تا محدودیت با چند درخواست
  -- موازی دور زده نشود.
  perform pg_advisory_xact_lock(hashtext(v_scope || ':' || v_source_hash));

  delete from public.public_confirmation_otp_request_limits
  where requested_at < now() - interval '24 hours';

  select max(requested_at)
  into v_last_request_at
  from public.public_confirmation_otp_request_limits
  where scope = v_scope
    and source_hash = v_source_hash
    and phone_hash = v_phone_hash;

  if v_last_request_at is not null and v_last_request_at > now() - interval '90 seconds' then
    v_retry_after := greatest(1, ceil(extract(epoch from (v_last_request_at + interval '90 seconds' - now())))::integer);
    return jsonb_build_object(
      'allowed', false,
      'error', 'rate_limited',
      'retry_after_seconds', v_retry_after
    );
  end if;

  select count(*)
  into v_window_count
  from public.public_confirmation_otp_request_limits
  where scope = v_scope
    and source_hash = v_source_hash
    and requested_at > now() - interval '15 minutes';

  if v_window_count >= 5 then
    return jsonb_build_object(
      'allowed', false,
      'error', 'rate_limited',
      'retry_after_seconds', 900
    );
  end if;

  if v_ip_hash is not null then
    select count(*)
    into v_window_count
    from public.public_confirmation_otp_request_limits
    where scope = v_scope
      and ip_hash = v_ip_hash
      and requested_at > now() - interval '15 minutes';

    if v_window_count >= 25 then
      return jsonb_build_object(
        'allowed', false,
        'error', 'rate_limited',
        'retry_after_seconds', 900
      );
    end if;
  end if;

  insert into public.public_confirmation_otp_request_limits (
    scope,
    source_hash,
    phone_hash,
    ip_hash
  ) values (
    v_scope,
    v_source_hash,
    v_phone_hash,
    v_ip_hash
  ) returning id into v_request_id;

  return jsonb_build_object('allowed', true, 'request_id', v_request_id);
end;
$_$;


--
-- Name: append_online_invoice_payment_from_transaction(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_online_invoice_payment_from_transaction(p_transaction_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_tx public.payment_transactions%rowtype;
  v_invoice_json jsonb;
  v_settings jsonb := '{}'::jsonb;
  v_default_bank_account_id uuid := null;
  v_default_bank_account_raw text := null;
  v_responsible_id text := null;
  v_payment_row jsonb;
  v_exists boolean := false;
begin
  select *
  into v_tx
  from public.payment_transactions
  where id = p_transaction_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'تراکنش پیدا نشد.');
  end if;

  if v_tx.purpose <> 'online_invoice'
     or v_tx.module_id <> 'invoices'
     or v_tx.record_id is null
     or v_tx.status not in ('paid', 'verified') then
    return jsonb_build_object('success', false, 'message', 'تراکنش قابل ثبت روی فاکتور نیست.');
  end if;

  execute 'select to_jsonb(i) from public.invoices i where i.id = $1 and i.org_id = $2'
  into v_invoice_json
  using v_tx.record_id, v_tx.org_id;

  if v_invoice_json is null then
    return jsonb_build_object('success', false, 'message', 'فاکتور پیدا نشد.');
  end if;

  select coalesce(settings, '{}'::jsonb)
  into v_settings
  from public.integration_settings
  where org_id = v_tx.org_id
    and connection_type = 'payment_gateway'
    and provider = 'zarinpal'
  order by is_active desc, updated_at desc nulls last, created_at desc nulls last
  limit 1;

  v_default_bank_account_raw := nullif(trim(coalesce(v_settings ->> 'default_bank_account_id', '')), '');
  if v_default_bank_account_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    select ba.id
    into v_default_bank_account_id
    from public.bank_accounts ba
    where ba.id = v_default_bank_account_raw::uuid
      and ba.org_id = v_tx.org_id
      and coalesce(ba.is_active, true) = true
    limit 1;
  end if;

  v_responsible_id := nullif(trim(coalesce(
    v_invoice_json ->> 'assignee_id',
    v_invoice_json ->> 'marketer_id',
    v_invoice_json ->> 'salesperson_id',
    v_invoice_json ->> 'responsible_id',
    ''
  )), '');

  select exists (
    select 1
    from public.invoices i,
         lateral jsonb_array_elements(coalesce(i.payments, '[]'::jsonb)) payment_row(item)
    where i.id = v_tx.record_id
      and i.org_id = v_tx.org_id
      and (
        payment_row.item ->> 'gateway_transaction_id' = v_tx.id::text
        or payment_row.item ->> 'authority' = coalesce(v_tx.authority, '')
      )
  )
  into v_exists;

  if v_exists then
    return jsonb_build_object('success', true, 'already_exists', true, 'invoice_id', v_tx.record_id);
  end if;

  v_payment_row := jsonb_strip_nulls(jsonb_build_object(
    'row_key', 'gateway_' || replace(v_tx.id::text, '-', ''),
    'date', to_char(coalesce(v_tx.paid_at, v_tx.verified_at, now()), 'YYYY-MM-DD'),
    'amount', v_tx.amount,
    'payment_type', 'online',
    'status', 'received',
    'target_account', v_default_bank_account_id,
    'bank_account_id', v_default_bank_account_id,
    'responsible_id', v_responsible_id,
    'description', trim(both ' ' from concat('پرداخت آنلاین زرین‌پال', case when v_tx.ref_id is not null then ' - کد پیگیری: ' || v_tx.ref_id else '' end)),
    'source', 'online_gateway',
    'locked', true,
    '_readonly', true,
    '_lockedByGateway', true,
    '_lockedFields', jsonb_build_array('date', 'amount', 'payment_type', 'status', 'target_account', 'bank_account_id', 'description'),
    'gateway_provider', v_tx.provider,
    'gateway_scope', v_tx.gateway_scope,
    'gateway_transaction_id', v_tx.id::text,
    'authority', v_tx.authority,
    'ref_id', v_tx.ref_id
  ));

  update public.invoices
  set payments = coalesce(payments, '[]'::jsonb) || jsonb_build_array(v_payment_row),
      updated_at = now()
  where id = v_tx.record_id
    and org_id = v_tx.org_id;

  if not found then
    return jsonb_build_object('success', false, 'message', 'فاکتور پیدا نشد.');
  end if;

  update public.payment_transactions
  set metadata = coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'invoice_payment_appended', true,
        'invoice_payment_appended_at', now(),
        'invoice_payment_row_key', v_payment_row ->> 'row_key',
        'invoice_payment_target_account', v_default_bank_account_id,
        'invoice_payment_responsible_id', v_responsible_id
      )
  where id = v_tx.id;

  return jsonb_build_object(
    'success', true,
    'already_exists', false,
    'invoice_id', v_tx.record_id,
    'payment_row_key', v_payment_row ->> 'row_key'
  );
end;
$_$;


--
-- Name: apply_ai_process_task_change(uuid, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ai_process_task_change(p_task_id uuid, p_patch jsonb, p_custom_values jsonb DEFAULT '{}'::jsonb, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org uuid := public.current_org_id();
  v_task public.tasks%rowtype;
  v_next public.tasks%rowtype;
  v_field jsonb; v_key text; v_required text; v_value jsonb;
  v_recurrence jsonb; v_values jsonb; v_count integer;
  v_run_metadata jsonb := '{}'::jsonb; v_template_metadata jsonb := '{}'::jsonb;
  v_task_metadata jsonb; v_template_stage_id uuid; v_candidates jsonb;
begin
  if v_org is null or auth.uid() is null
    or not public.current_user_has_role_permission_entry('tasks','view',null,false)
    or not public.current_user_has_role_permission_entry('tasks','edit',null,false) then
    raise exception 'دسترسی ویرایش فعالیت تأیید نشد.' using errcode='42501';
  end if;
  if jsonb_typeof(p_patch) is distinct from 'object' or jsonb_typeof(p_custom_values) is distinct from 'object' then
    raise exception 'اطلاعات تغییر فعالیت معتبر نیست.' using errcode='22023';
  end if;
  for v_key in select jsonb_object_keys(p_patch) loop
    if v_key <> all(array['name','description','status','priority','start_date','due_date','assignee_id','assignee_role_id','assignee_type'])
      or not public.current_user_has_role_permission_entry('tasks','edit',v_key,true) then
      raise exception 'فیلد فعالیت برای تغییر مجاز نیست.' using errcode='42501';
    end if;
  end loop;
  select * into v_task from public.tasks where id=p_task_id and org_id=v_org for update;
  if not found then raise exception 'فعالیت پیدا نشد یا مجاز نیست.' using errcode='P0002'; end if;
  if p_expected_updated_at is distinct from v_task.updated_at then
    raise exception 'فعالیت پس از بررسی تغییر کرده است؛ دوباره اطلاعات را دریافت کنید.' using errcode='40001';
  end if;
  v_recurrence := case when jsonb_typeof(v_task.recurrence_info)='object' then v_task.recurrence_info else '{}'::jsonb end;
  v_task_metadata := coalesce(to_jsonb(v_task)->'metadata','{}'::jsonb);
  -- Match the V2 modal's legacy fallback, while a task snapshot always wins.
  -- Parent RLS and explicit source-field permissions apply to fallback reads.
  if v_task.process_run_stage_id is not null
    and public.current_user_has_role_permission_entry('process_runs','view',null,false)
    and public.current_user_has_role_permission_entry('process_runs','view','metadata',true) then
    select s.metadata,s.template_stage_id into v_run_metadata,v_template_stage_id
      from public.process_run_stages s join public.process_runs r on r.id=s.process_run_id
      where s.id=v_task.process_run_stage_id and r.id=v_task.process_run_id and r.org_id=v_org;
  end if;
  if public.current_user_has_role_permission_entry('process_templates','view',null,false)
    and public.current_user_has_role_permission_entry('process_templates','view','metadata',true) then
    select s.metadata into v_template_metadata from public.process_template_stages s
      join public.process_templates t on t.id=s.template_id and t.org_id=v_org
      where (s.id=v_template_stage_id or v_template_stage_id is null
        and s.template_id=v_task.source_template_id and s.sort_order=v_task.source_stage_sort_order)
      order by s.id limit 1;
  end if;
  foreach v_key in array array['process_task_custom_fields','process_task_status_options'] loop
    foreach v_candidates in array array[v_recurrence->v_key,v_task_metadata->v_key,v_run_metadata->v_key,v_template_metadata->v_key] loop
      if jsonb_typeof(v_candidates)='array' and jsonb_array_length(v_candidates)>0 then
        v_recurrence:=jsonb_set(v_recurrence,array[v_key],v_candidates,true); exit;
      end if;
    end loop;
  end loop;
  v_values := coalesce(v_template_metadata->'process_task_custom_field_values','{}'::jsonb)
    || coalesce(v_run_metadata->'process_task_custom_field_values','{}'::jsonb)
    || coalesce(v_task_metadata->'process_task_custom_field_values','{}'::jsonb)
    || coalesce(v_recurrence->'process_task_custom_field_values','{}'::jsonb) || p_custom_values;
  for v_key in select jsonb_object_keys(p_custom_values) loop
    if not public.current_user_has_role_permission_entry('tasks','edit','recurrence_info',true)
      or not public.current_user_has_role_permission_entry('tasks','edit',v_key,true)
      or not exists (select 1 from jsonb_array_elements(coalesce(v_recurrence->'process_task_custom_fields','[]'::jsonb)) f where f->>'key'=v_key and coalesce(f->>'readonly','false')<>'true') then
      raise exception 'فیلد اختصاصی برای تغییر مجاز نیست.' using errcode='42501';
    end if;
  end loop;
  v_next := jsonb_populate_record(v_task,p_patch);
  if p_patch ? 'status' and v_next.status is distinct from v_task.status then
    if v_next.status <> all(array['todo','planned','in_progress','review','done','completed','blocked','canceled','cancelled'])
      and not exists(select 1 from jsonb_array_elements(coalesce(v_recurrence->'process_task_status_options','[]'::jsonb)) o where o->>'value'=v_next.status) then
      raise exception 'وضعیت فعالیت معتبر نیست.' using errcode='22023';
    end if;
    for v_field in select * from jsonb_array_elements(coalesce(v_recurrence->'process_task_custom_fields','[]'::jsonb)) loop
      v_required := coalesce(v_field->>'requiredForStatus',v_field->>'required_for_status','');
      v_key := v_field->>'key'; v_value := coalesce(v_values->v_key,to_jsonb(v_next)->v_key);
      if (v_required=v_next.status or v_required in ('done','completed') and v_next.status in ('done','completed'))
        and (v_value is null or v_value in ('null'::jsonb,'""'::jsonb,'[]'::jsonb)) then
        raise exception 'فیلد اختصاصی لازم برای وضعیت مقصد تکمیل نشده است.' using errcode='23514';
      end if;
    end loop;
    if v_next.status in ('in_progress','review','done','completed') then
      v_next.start_date := coalesce(v_next.start_date,now());
      v_next.actual_start_at := coalesce(v_next.actual_start_at,v_next.start_date,now());
    end if;
    v_next.completed_at := case when v_next.status in ('done','completed') then coalesce(v_next.completed_at,now()) else null end;
    v_next.actual_end_at := case when v_next.status in ('done','completed') then coalesce(v_next.actual_end_at,v_next.completed_at,now()) else null end;
  end if;
  if v_values <> '{}'::jsonb then v_recurrence := jsonb_set(v_recurrence,'{process_task_custom_field_values}',v_values,true); end if;
  -- Existing task triggers enforce record locks, assignee organization and
  -- enqueue workflow events. An error rolls back both task and stage changes.
  update public.tasks set name=v_next.name, description=v_next.description,status=v_next.status,
    priority=v_next.priority,start_date=v_next.start_date,due_date=v_next.due_date,
    assignee_id=v_next.assignee_id,assignee_role_id=v_next.assignee_role_id,assignee_type=v_next.assignee_type,
    completed_at=v_next.completed_at,actual_start_at=v_next.actual_start_at,actual_end_at=v_next.actual_end_at,
    recurrence_info=v_recurrence,updated_at=now(),updated_by=auth.uid()
  where id=p_task_id and org_id=v_org returning * into v_next;
  if not found then raise exception 'ذخیره فعالیت تأیید نشد.' using errcode='P0002'; end if;
  if v_next.process_run_stage_id is not null then
    update public.process_run_stages s set
      status=case when v_next.status in ('done','completed') then 'done'
        when v_next.status in ('canceled','cancelled') then 'canceled'
        when v_next.status in ('in_progress','review') then 'in_progress'
        when v_next.status='blocked' then 'blocked' else 'todo' end,
      task_id=v_next.id,assignee_user_id=case when v_next.assignee_type='user' then v_next.assignee_id else null end,
      assignee_role_id=v_next.assignee_role_id,planned_due_at=v_next.due_date,
      started_at=v_next.actual_start_at,completed_at=v_next.completed_at,updated_at=now()
    where s.id=v_next.process_run_stage_id and s.process_run_id=v_next.process_run_id
      and exists(select 1 from public.process_runs r where r.id=s.process_run_id and r.org_id=v_org);
    get diagnostics v_count=row_count;
    if v_count<>1 then raise exception 'ذخیره مرحله اجرای فرآیند تأیید نشد.' using errcode='P0002'; end if;
  end if;
  return jsonb_build_object('id',v_next.id,'name',v_next.name,'status',v_next.status,'updated_at',v_next.updated_at);
end;
$$;


--
-- Name: apply_billboard_status_change(uuid, uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_billboard_status_change(p_change_id uuid, p_org_id uuid, p_actor_user_id uuid, p_is_workflow boolean DEFAULT false, p_approval_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_change public.billboard_status_changes%rowtype;
  v_billboard public.billboards%rowtype;
  v_tag_id uuid;
  v_status_label text;
begin
  if p_change_id is null or p_org_id is null or p_actor_user_id is null then
    raise exception 'اطلاعات اعمال تغییر وضعیت کامل نیست.' using errcode = '22023';
  end if;
  if not public.org_has_plan_module(p_org_id, 'billboards', false) then
    raise exception 'ماژول تبلیغات محیطی برای این سازمان فعال نیست.' using errcode = '42501';
  end if;

  select * into v_change
  from public.billboard_status_changes
  where id = p_change_id and org_id = p_org_id
  for update;
  if not found then
    raise exception 'درخواست تغییر وضعیت در سازمان جاری پیدا نشد.' using errcode = 'P0002';
  end if;

  select * into v_billboard
  from public.billboards
  where id = v_change.billboard_id and org_id = p_org_id
  for update;
  if not found then
    raise exception 'تابلوی مرتبط در سازمان جاری پیدا نشد.' using errcode = 'P0002';
  end if;

  if v_change.application_mode = 'add_tag' then
    if v_change.target_status not in ('oral_reserve', 'final_reserve', 'in_line') then
      raise exception 'این وضعیت فقط باید به‌عنوان وضعیت اصلی تابلو اعمال شود.' using errcode = '22023';
    end if;
    v_status_label := public.billboard_operational_status_label(v_change.target_status);
    select id into v_tag_id
    from public.tags
    where org_id = p_org_id and lower(title) = lower(v_status_label)
    order by created_at asc
    limit 1;
    if v_tag_id is null then
      begin
        insert into public.tags (org_id, title, color, created_by)
        values (p_org_id, v_status_label, '#1677ff', p_actor_user_id)
        returning id into v_tag_id;
      exception when unique_violation then
        select id into v_tag_id
        from public.tags
        where org_id = p_org_id and lower(title) = lower(v_status_label)
        order by created_at asc
        limit 1;
      end;
    end if;
    if v_tag_id is null then
      raise exception 'برچسب وضعیت تابلو ایجاد نشد.' using errcode = 'P0001';
    end if;
    insert into public.record_tags (org_id, module_id, record_id, tag_id, created_by)
    values (p_org_id, 'billboards', v_billboard.id::text, v_tag_id, p_actor_user_id)
    on conflict (module_id, record_id, tag_id) do nothing;
  else
    perform set_config('app.billboard_status_change_authorized', 'on', true);
    update public.billboards
    set status = v_change.target_status,
        related_customer = case
          when v_change.target_status in ('free', 'inactive', 'blocked') then null
          else coalesce(v_change.customer_id, related_customer)
        end,
        related_invoice = case
          when v_change.target_status in ('free', 'inactive', 'blocked') then null
          else coalesce(v_change.invoice_id, related_invoice)
        end,
        marketing_lead_id = case
          when v_change.target_status in ('free', 'inactive', 'blocked') then null
          else coalesce(v_change.marketing_lead_id, marketing_lead_id)
        end,
        start_date = case
          when v_change.target_status in ('free', 'inactive', 'blocked') then null
          else coalesce(v_change.start_date, start_date)
        end,
        end_date = case
          when v_change.target_status in ('free', 'inactive', 'blocked') then null
          else coalesce(v_change.end_date, end_date)
        end,
        updated_by = p_actor_user_id
    where id = v_billboard.id and org_id = p_org_id;
  end if;

  update public.billboard_status_changes
  set request_status = 'approved',
      approved_by = p_actor_user_id,
      approved_at = now(),
      approval_note = coalesce(nullif(trim(p_approval_note), ''), case when p_is_workflow then 'به‌صورت خودکار توسط گردش‌کار اعمال شد.' else null end),
      applied_tag_id = case when v_change.application_mode = 'add_tag' then v_tag_id else null end,
      execution_source = case when p_is_workflow then 'workflow' else 'manual' end,
      updated_at = now(),
      updated_by = p_actor_user_id
  where id = v_change.id and org_id = p_org_id;

  return v_change.id;
end;
$$;


--
-- Name: apply_customer_club_non_customer_referral_rewards_from_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_scope_condition_matches(p_record jsonb, p_condition jsonb)
returns boolean language plpgsql stable security invoker
set search_path = public
as $$
declare
  v_field text := p_condition->>'field';
  v_operator text := p_condition->>'operator';
  v_expected jsonb := p_condition->'value';
  v_actual jsonb := p_record->v_field;
  v_left text := btrim(coalesce(v_actual#>>'{}', ''));
  v_right text := btrim(coalesce(v_expected#>>'{}', ''));
  v_left_numeric numeric;
  v_right_numeric numeric;
  v_actual_day date;
  v_expected_day date;
  v_today date := (now() at time zone 'Asia/Tehran')::date;
  v_found boolean;
  v_related_parts text[];
  v_related_id text;
  v_related_module text;
  v_related_value jsonb;
  v_org_id uuid;
begin
  if v_field is null or v_field = '' or jsonb_typeof(p_record) is distinct from 'object' then return false; end if;
  if v_field = 'reservation_id' and p_record ? 'invoiceItems' then
    v_org_id := nullif(p_record->>'org_id', '')::uuid;
    if v_org_id is null or not public.org_has_plan_module(v_org_id, 'reservations', false) then return false; end if;
  end if;
  if starts_with(v_field, '__workflow_related__') then
    v_related_parts := string_to_array(substr(v_field, length('__workflow_related__') + 1), '::');
    if cardinality(v_related_parts) <> 3 or not (
      (v_related_parts[1] = 'product_id' and v_related_parts[2] in ('products', 'billboards'))
      or (v_related_parts[1] = 'reservation_id' and v_related_parts[2] = 'reservations')
    ) then return false; end if;
    v_org_id := coalesce(nullif(p_record->>'__condition_org_id', ''), nullif(p_record->>'org_id', ''))::uuid;
    if v_org_id is null or (auth.role() = 'authenticated' and v_org_id is distinct from public.current_org_id()) then return false; end if;
    v_related_value := p_record->v_related_parts[1];
    v_related_module := coalesce(v_related_value->>'moduleId', v_related_value->>'module', v_related_value->>'targetModule',
      case when v_related_parts[1] = 'product_id' then p_record->>'commission_product_module' end);
    if coalesce(v_related_module, '') <> '' and v_related_module <> v_related_parts[2] then return false; end if;
    v_related_id := case when jsonb_typeof(v_related_value) = 'object'
      then coalesce(v_related_value->>'id', v_related_value->>'value', v_related_value->>'record_id')
      else v_related_value#>>'{}' end;
    if coalesce(v_related_id, '') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then return false; end if;
    if current_user = 'authenticated'
      and not public.current_user_can_module_field(v_related_parts[2], 'view', v_related_parts[3]) then return false; end if;
    if v_related_parts[2] = 'products' then
      select to_jsonb(p)->v_related_parts[3] into v_actual from public.products p where p.id = v_related_id::uuid and p.org_id = v_org_id;
    elsif v_related_parts[2] = 'billboards' and public.org_has_plan_module(v_org_id, 'billboards', false) then
      select to_jsonb(b)->v_related_parts[3] into v_actual from public.billboards b where b.id = v_related_id::uuid and b.org_id = v_org_id;
    elsif v_related_parts[2] = 'reservations' and public.org_has_plan_module(v_org_id, 'reservations', false) then
      select to_jsonb(r)->v_related_parts[3] into v_actual from public.reservations r where r.id = v_related_id::uuid and r.org_id = v_org_id;
    else
      return false;
    end if;
    if v_actual is null then return false; end if;
    v_left := btrim(coalesce(v_actual#>>'{}', ''));
  end if;
  if v_operator in ('table_any', 'table_all') then
    if jsonb_typeof(v_expected) is distinct from 'array' or jsonb_typeof(v_actual) is distinct from 'array' then
      return false;
    end if;
    if jsonb_array_length(v_expected) = 0 or exists (
      select 1 from jsonb_array_elements(v_expected) cond
      where cond->>'operator' in ('table_any', 'table_all')
    ) then return false; end if;
    with rows as (
      select row_item from jsonb_array_elements(v_actual) row_item
      where jsonb_typeof(row_item) = 'object' and coalesce(row_item->>'deleted_at', '') = ''
        and not (row_item @> '{"is_deleted":true}' or row_item @> '{"deleted":true}'
          or row_item @> '{"_deleted":true}' or row_item @> '{"__deleted":true}' or row_item @> '{"_destroy":true}')
    ), matching as (
      select not exists (
        select 1 from jsonb_array_elements(v_expected) cond
        where public.record_scope_condition_matches(
          row_item || jsonb_build_object('__condition_org_id', p_record->'org_id'), cond
        ) is not true
      ) as matched from rows
    )
    select case when v_operator = 'table_all' then bool_and(matched) else bool_or(matched) end into v_found from matching;
    return coalesce(v_found, false);
  end if;
  if v_operator in ('is_null', 'not_null') then
    return (v_left in ('', '[]')) = (v_operator = 'is_null');
  end if;
  if v_operator = 'is_true' then return v_left in ('true', '1'); end if;
  if v_operator = 'is_false' then return v_left in ('false', '0'); end if;
  if v_operator in ('in', 'not_in') then
    if jsonb_typeof(v_expected) is distinct from 'array' then return false; end if;
    if jsonb_array_length(v_expected) = 0 then return false; end if;
    return exists (select 1 from jsonb_array_elements_text(v_expected) item where btrim(item) = v_left) = (v_operator = 'in');
  end if;
  if v_operator in ('after_date', 'before_date', 'date_between', 'is_today', 'is_yesterday', 'is_tomorrow') then
    if v_left !~ '^\d{4}-\d{2}-\d{2}' then return false; end if;
    v_actual_day := case when length(v_left) = 10 then v_left::date else (v_left::timestamptz at time zone 'Asia/Tehran')::date end;
    if v_operator = 'is_today' then return v_actual_day = v_today; end if;
    if v_operator = 'is_yesterday' then return v_actual_day = v_today - 1; end if;
    if v_operator = 'is_tomorrow' then return v_actual_day = v_today + 1; end if;
    if v_operator = 'date_between' then
      return coalesce(v_actual_day between left(v_expected->>'from', 10)::date and left(v_expected->>'to', 10)::date, false);
    end if;
    v_expected_day := case when length(v_right) = 10 then v_right::date else (v_right::timestamptz at time zone 'Asia/Tehran')::date end;
    return case when v_operator = 'after_date' then v_actual_day > v_expected_day else v_actual_day < v_expected_day end;
  end if;
  if v_expected is null or v_expected = 'null'::jsonb or v_right = '' then return false; end if;
  if v_operator in ('contains', 'not_contains') then return (strpos(lower(v_left), lower(v_right)) > 0) = (v_operator = 'contains'); end if;
  if v_operator = 'starts_with' then return left(lower(v_left), length(v_right)) = lower(v_right); end if;
  if v_operator = 'ends_with' then return right(lower(v_left), length(v_right)) = lower(v_right); end if;
  if v_operator in ('eq', 'neq') then
    if jsonb_typeof(v_actual) = 'number' and jsonb_typeof(v_expected) = 'number' then
      return (v_left::numeric = v_right::numeric) = (v_operator = 'eq');
    end if;
    return (v_left = v_right) = (v_operator = 'eq');
  end if;
  if v_operator in ('gt', 'gte', 'lt', 'lte') then
    if v_left !~ '^-?[0-9]+(\.[0-9]+)?$' or v_right !~ '^-?[0-9]+(\.[0-9]+)?$' then return false; end if;
    v_left_numeric := v_left::numeric;
    v_right_numeric := v_right::numeric;
    return case v_operator
      when 'gt' then v_left_numeric > v_right_numeric when 'gte' then v_left_numeric >= v_right_numeric
      when 'lt' then v_left_numeric < v_right_numeric else v_left_numeric <= v_right_numeric end;
  end if;
  return false;
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
  return false;
end;
$$;

CREATE FUNCTION public.customer_club_invoice_rule_conditions_match(
  p_invoice jsonb, p_customer jsonb, p_invoice_conditions jsonb, p_customer_all jsonb, p_customer_any jsonb
)
returns boolean language sql stable security invoker set search_path = public
as $$
  select case
    when p_invoice_conditions is null then
      jsonb_array_length(coalesce(p_customer_all, '[]'::jsonb)) = 0
      and jsonb_array_length(coalesce(p_customer_any, '[]'::jsonb)) = 0
    when jsonb_typeof(p_invoice_conditions) is distinct from 'array' then false
    when jsonb_array_length(p_invoice_conditions) = 0 then false
    else not exists (
      select 1 from jsonb_array_elements(p_invoice_conditions) cond
      where public.record_scope_condition_matches(p_invoice, cond) is not true
    ) and not exists (
      select 1 from jsonb_array_elements(coalesce(p_customer_all, '[]'::jsonb)) cond
      where public.record_scope_condition_matches(p_customer, cond) is not true
    ) and (
      jsonb_array_length(coalesce(p_customer_any, '[]'::jsonb)) = 0 or exists (
        select 1 from jsonb_array_elements(p_customer_any) cond
        group by cond->>'field'
        having case
          when bool_and(cond->>'operator' in ('neq', 'not_in', 'not_contains', 'is_false', 'is_null'))
            then bool_and(public.record_scope_condition_matches(p_customer, cond) is true)
          else bool_or(public.record_scope_condition_matches(p_customer, cond) is true)
        end
      )
    )
  end;
$$;

CREATE FUNCTION public.check_customer_club_invoice_rule_fields()
returns trigger language plpgsql security invoker set search_path = public
as $$
declare
  v_condition jsonb;
  v_row_condition jsonb;
  v_field text;
  v_related text[];
begin
  if auth.role() is distinct from 'authenticated' then return new; end if;
  if not (new.config ? 'invoice_conditions')
    and (tg_op = 'INSERT' or not (old.config ? 'invoice_conditions')) then return new; end if;
  if not public.current_user_can_module_field('__customer_club', 'edit', 'rules') then
    raise exception 'customer_club_rule_access_denied' using errcode = '42501';
  end if;
  if not (new.config ? 'invoice_conditions') then return new; end if;
  for v_condition in select value from jsonb_array_elements(new.config->'invoice_conditions') loop
    v_field := v_condition->>'field';
    if starts_with(v_field, '__workflow_related__') then
      v_related := string_to_array(substr(v_field, length('__workflow_related__') + 1), '::');
      if cardinality(v_related) <> 3 or not public.current_user_can_module_field('invoices', 'view', v_related[1])
        or not public.current_user_can_module_field(v_related[2], 'view', v_related[3]) then
        raise exception 'customer_club_condition_field_access_denied' using errcode = '42501';
      end if;
    elsif v_field is null or not public.current_user_can_module_field('invoices', 'view', v_field) then
      raise exception 'customer_club_condition_field_access_denied' using errcode = '42501';
    end if;
    if v_condition->>'operator' in ('table_any', 'table_all') then
      for v_row_condition in select value from jsonb_array_elements(v_condition->'value') loop
        if not starts_with(v_row_condition->>'field', '__workflow_related__') then continue; end if;
        v_related := string_to_array(substr(v_row_condition->>'field', length('__workflow_related__') + 1), '::');
        if cardinality(v_related) <> 3 or not public.current_user_can_module_field(v_related[2], 'view', v_related[3]) then
          raise exception 'customer_club_condition_field_access_denied' using errcode = '42501';
        end if;
      end loop;
    end if;
  end loop;
  for v_condition in
    select value from jsonb_array_elements(coalesce(new.config->'invoice_customer_conditions_all', '[]'::jsonb))
    union all
    select value from jsonb_array_elements(coalesce(new.config->'invoice_customer_conditions_any', '[]'::jsonb))
  loop
    if v_condition->>'field' is null or not public.current_user_can_module_field('customers', 'view', v_condition->>'field') then
      raise exception 'customer_club_condition_field_access_denied' using errcode = '42501';
    end if;
  end loop;
  return new;
end;
$$;

revoke all on function public.record_scope_condition_matches(jsonb, jsonb) from public, anon;
grant execute on function public.record_scope_condition_matches(jsonb, jsonb) to authenticated, service_role;
revoke all on function public.customer_club_invoice_rule_conditions_match(jsonb, jsonb, jsonb, jsonb, jsonb) from public, anon;
grant execute on function public.customer_club_invoice_rule_conditions_match(jsonb, jsonb, jsonb, jsonb, jsonb) to authenticated, service_role;

CREATE FUNCTION public.apply_customer_club_non_customer_referral_rewards_from_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rule record;
  v_org_id uuid := new.org_id;
  v_target_module text;
  v_target_id uuid;
  v_amount numeric(18,2);
  v_rule_ids uuid[] := '{}'::uuid[];
begin
  if v_org_id is null or (auth.role() = 'authenticated' and v_org_id is distinct from public.current_org_id()) then return new; end if;
  -- ابتدا تنها اقلام همین مسیر را پاک می‌کنیم؛ رکوردهای مشتری و پاداش‌های
  -- شرط‌دار در منبع مسئول خودشان باقی می‌مانند.

  delete from public.customer_club_entity_credits ledger
  using public.customer_loyalty_rules rule
  where ledger.rule_id = rule.id and ledger.org_id = v_org_id and rule.org_id = v_org_id
    and ledger.source_table = 'invoices' and ledger.source_record_id = new.id
    and ledger.source_type in ('conditioned_referral_reward')
    and rule.config ? 'invoice_conditions';

  if new.customer_id is null or not public.is_customer_purchase_status(new.status) then
    delete from public.customer_club_entity_credits
    where org_id = v_org_id and source_table = 'invoices' and source_record_id = new.id
      and source_type = 'referral_reward';
    return new;
  end if;

  select lower(trim(coalesce(c.referrer_module, ''))),
    case lower(trim(coalesce(c.referrer_module, '')))
      when 'employees' then c.referrer_employee_id
      when 'suppliers' then c.referrer_supplier_id
      else null
    end
  into v_target_module, v_target_id
  from public.customers c where c.id = new.customer_id and c.org_id = v_org_id;
  if v_target_module not in ('employees', 'suppliers') or v_target_id is null then
    delete from public.customer_club_entity_credits
    where org_id = v_org_id and source_table = 'invoices' and source_record_id = new.id
      and source_type = 'referral_reward';
    return new;
  end if;

  for v_rule in
    select * from public.customer_loyalty_rules
    where org_id = v_org_id and is_active = true and rule_type = 'referral'
      and (starts_at is null or starts_at <= coalesce(new.invoice_date, new.created_at::date, current_date))
      and (ends_at is null or ends_at >= coalesce(new.invoice_date, new.created_at::date, current_date))
      and public.customer_club_invoice_rule_conditions_match(
          to_jsonb(new),
          (select to_jsonb(c) from public.customers c where c.org_id = v_org_id and c.id = new.customer_id),
          config->'invoice_conditions',
          coalesce(config->'invoice_customer_conditions_all', conditions_all),
          coalesce(config->'invoice_customer_conditions_any', conditions_any)
        )
  loop
    v_amount := case when v_rule.reward_type = 'percent'
      then round(coalesce(new.total_invoice_amount, 0) * coalesce(v_rule.reward_percent, 0) / 100, 2)
      else coalesce(v_rule.reward_amount, 0) end;
    if v_rule.max_reward_amount is not null then v_amount := least(v_amount, v_rule.max_reward_amount); end if;
    if v_amount <= 0 then continue; end if;
    perform public.record_customer_club_entity_credit(
      v_target_module, v_target_id, v_rule.id, 'credit', 'referral_reward', 'invoices', new.id,
      v_amount, coalesce(new.invoice_date, new.created_at::date, current_date),
      'referral_reward:' || v_rule.id::text || ':' || new.id::text,
      'پاداش معرفی مشتری', jsonb_build_object('introduced_customer_id', new.customer_id)
    );
    v_rule_ids := array_append(v_rule_ids, v_rule.id);
  end loop;

  delete from public.customer_club_entity_credits e
  where e.org_id = v_org_id and e.source_table = 'invoices' and e.source_record_id = new.id
    and e.source_type = 'referral_reward' and coalesce(e.rule_id = any(v_rule_ids), false) = false;
  return new;
end;
$$;


--
-- Name: apply_customer_loyalty_credit_from_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_customer_loyalty_credit_from_invoice() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_payment jsonb;
  v_amount numeric(18,2);
  v_status text;
  v_type text;
  v_row_key text;
  v_existing_balance numeric(18,2) := 0;
  v_existing_source_debit numeric(18,2) := 0;
  v_previous_credit_total numeric(18,2) := 0;
  v_credit_total numeric(18,2) := 0;
  v_customer_id uuid;
  v_old_customer_id uuid;
begin
  -- فقط اجرای داخلیِ قابل اعتماد (مانند callback درگاه) به این شاخه می‌رسد.
  -- کاربران عادی همچنان با RLS و org_id نشست خود محدود هستند.
  if v_org_id is null then
    return new;
  end if;

  v_customer_id := new.customer_id;
  if tg_op = 'UPDATE' then
    v_old_customer_id := old.customer_id;
  end if;

  perform 1
  from public.customers
  where org_id = v_org_id
    and id = any(array_remove(array[v_old_customer_id, v_customer_id]::uuid[], null))
  order by id
  for update;

  if v_customer_id is null then
    delete from public.customer_loyalty_ledger
    where org_id = v_org_id
      and source_type = 'invoice_credit_payment'
      and source_table = 'invoices'
      and source_record_id = new.id;

    if v_old_customer_id is not null then
      perform public.sync_customer_loyalty_balance(v_old_customer_id);
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' and v_old_customer_id is not distinct from v_customer_id then
    for v_payment in select value from jsonb_array_elements(coalesce(old.payments, '[]'::jsonb)) loop
      v_type := lower(trim(coalesce(v_payment->>'payment_type', '')));
      v_status := lower(trim(coalesce(v_payment->>'status', '')));
      if v_type <> 'credit'
         or ((v_payment ? 'status') and v_status <> '' and v_status not in ('received', 'paid', 'approved', 'cleared'))
      then
        continue;
      end if;
      begin
        v_amount := abs((v_payment->>'amount')::numeric);
      exception when others then
        v_amount := 0;
      end;
      if v_amount > 0 then
        v_previous_credit_total := v_previous_credit_total + v_amount;
      end if;
    end loop;
  end if;

  for v_payment in select value from jsonb_array_elements(coalesce(new.payments, '[]'::jsonb)) loop
    v_type := lower(trim(coalesce(v_payment->>'payment_type', '')));
    v_status := lower(trim(coalesce(v_payment->>'status', '')));
    if v_type <> 'credit'
       or ((v_payment ? 'status') and v_status <> '' and v_status not in ('received', 'paid', 'approved', 'cleared'))
    then
      continue;
    end if;
    begin
      v_amount := abs((v_payment->>'amount')::numeric);
    exception when others then
      v_amount := 0;
    end;
    if v_amount > 0 then
      v_credit_total := v_credit_total + v_amount;
    end if;
  end loop;

  select coalesce(sum(case when entry_type = 'debit' then -amount else amount end), 0)
    into v_existing_balance
  from public.customer_loyalty_ledger
  where org_id = v_org_id
    and customer_id = v_customer_id;

  select coalesce(sum(amount), 0)
    into v_existing_source_debit
  from public.customer_loyalty_ledger
  where org_id = v_org_id
    and customer_id = v_customer_id
    and entry_type = 'debit'
    and source_type = 'invoice_credit_payment'
    and source_table = 'invoices'
    and source_record_id = new.id;

  if abs(v_existing_source_debit - v_previous_credit_total) > 0.01 then
    if v_credit_total > v_existing_balance + v_existing_source_debit + 0.01 then
      raise exception 'اعتبار باشگاه مشتریان برای این دریافت کافی نیست.';
    end if;
  elsif v_credit_total - v_previous_credit_total > v_existing_balance + 0.01 then
    raise exception 'اعتبار باشگاه مشتریان برای افزایش مبلغ اعتباری کافی نیست.';
  end if;

  delete from public.customer_loyalty_ledger
  where org_id = v_org_id
    and source_type = 'invoice_credit_payment'
    and source_table = 'invoices'
    and source_record_id = new.id;

  if v_old_customer_id is not null and v_old_customer_id is distinct from v_customer_id then
    perform public.sync_customer_loyalty_balance(v_old_customer_id);
  end if;

  for v_payment in select value from jsonb_array_elements(coalesce(new.payments, '[]'::jsonb)) loop
    v_type := lower(trim(coalesce(v_payment->>'payment_type', '')));
    v_status := lower(trim(coalesce(v_payment->>'status', '')));
    if v_type <> 'credit'
       or ((v_payment ? 'status') and v_status <> '' and v_status not in ('received', 'paid', 'approved', 'cleared'))
    then
      continue;
    end if;
    begin
      v_amount := abs((v_payment->>'amount')::numeric);
    exception when others then
      v_amount := 0;
    end;
    if v_amount <= 0 then
      continue;
    end if;
    v_row_key := coalesce(nullif(v_payment->>'row_key', ''), nullif(v_payment->>'key', ''), md5(v_payment::text));

    insert into public.customer_loyalty_ledger (
      org_id, customer_id, entry_type, source_type, source_table, source_record_id,
      source_row_key, amount, effective_date, idempotency_key, description, metadata
    ) values (
      v_org_id, v_customer_id, 'debit', 'invoice_credit_payment', 'invoices', new.id,
      v_row_key, v_amount, coalesce(nullif(v_payment->>'date', '')::date, coalesce(new.invoice_date, current_date)),
      'invoice_credit_payment:' || new.id::text || ':' || v_row_key,
      'مصرف اعتبار در فاکتور فروش',
      jsonb_build_object('invoice_name', coalesce(new.name, new.system_code), 'payment_row', v_payment)
    )
    on conflict (org_id, idempotency_key) do update
      set amount = excluded.amount,
          effective_date = excluded.effective_date,
          metadata = excluded.metadata;
  end loop;

  perform public.sync_customer_loyalty_balance(v_customer_id);
  return new;
end;
$$;


--
-- Name: apply_customer_loyalty_rewards_from_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_customer_loyalty_rewards_from_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := new.org_id;
  v_rule record;
  v_amount numeric(18,2);
  v_target_customer_id uuid;
  v_has_prior_purchase boolean;
  v_applied_rule_ids uuid[] := '{}'::uuid[];
  v_sync_customer_ids uuid[] := '{}'::uuid[];
  v_customer_id uuid;
begin
  if v_org_id is null or (auth.role() = 'authenticated' and v_org_id is distinct from public.current_org_id()) then
    return new;
  end if;

  -- پاداش‌های بدون شرط، منبع سروری دارند. پاداش‌های دارای شرط با کلید
  -- conditioned_* جدا هستند؛ فقط هنگام نامعتبرشدن فاکتور باید آن‌ها هم حذف شوند.
  select coalesce(array_agg(distinct customer_id), '{}'::uuid[])
    into v_sync_customer_ids
  from public.customer_loyalty_ledger
  where org_id = v_org_id
    and source_table = 'invoices'
    and source_record_id = new.id
    and source_type in (
      'cashback_reward', 'first_purchase_reward', 'referral_reward',
      'conditioned_cashback_reward', 'conditioned_first_purchase_reward', 'conditioned_referral_reward'
    );


  delete from public.customer_loyalty_ledger ledger
  using public.customer_loyalty_rules rule
  where ledger.rule_id = rule.id and ledger.org_id = v_org_id and rule.org_id = v_org_id
    and ledger.source_table = 'invoices' and ledger.source_record_id = new.id
    and ledger.source_type in ('conditioned_cashback_reward','conditioned_first_purchase_reward','conditioned_referral_reward')
    and rule.config ? 'invoice_conditions';

  if new.customer_id is not null and public.is_customer_purchase_status(new.status) then
    for v_rule in
      select *
      from public.customer_loyalty_rules
      where org_id = v_org_id
        and is_active = true
        and rule_type in ('cashback', 'first_purchase', 'referral')
        and (starts_at is null or starts_at <= coalesce(new.invoice_date, new.created_at::date, current_date))
        and (ends_at is null or ends_at >= coalesce(new.invoice_date, new.created_at::date, current_date))
        and public.customer_club_invoice_rule_conditions_match(
          to_jsonb(new),
          (select to_jsonb(c) from public.customers c where c.org_id = v_org_id and c.id = new.customer_id),
          config->'invoice_conditions',
          coalesce(config->'invoice_customer_conditions_all', conditions_all),
          coalesce(config->'invoice_customer_conditions_any', conditions_any)
        )
    loop
      v_amount := case
        when v_rule.reward_type = 'percent' then round(coalesce(new.total_invoice_amount, 0) * coalesce(v_rule.reward_percent, 0) / 100, 2)
        else coalesce(v_rule.reward_amount, 0)
      end;
      if v_rule.max_reward_amount is not null then
        v_amount := least(v_amount, v_rule.max_reward_amount);
      end if;
      if v_amount <= 0 then
        continue;
      end if;

      v_target_customer_id := new.customer_id;
      if v_rule.rule_type = 'first_purchase' then
        if exists (
          select 1
          from public.customers c
          where c.id = new.customer_id
            and c.org_id = v_org_id
            and coalesce(c.previous_system_purchase_count, 0) > 0
        ) then
          continue;
        end if;
        select exists(
          select 1
          from public.invoices i
          where i.org_id = v_org_id
            and i.customer_id = new.customer_id
            and i.id <> new.id
            and public.is_customer_purchase_status(i.status)
            and coalesce(i.invoice_date, i.created_at::date) <= coalesce(new.invoice_date, new.created_at::date)
        ) into v_has_prior_purchase;
        if v_has_prior_purchase then
          continue;
        end if;
      elsif v_rule.rule_type = 'referral' then
        select c.referrer_customer_id
          into v_target_customer_id
        from public.customers c
        where c.id = new.customer_id
          and c.org_id = v_org_id
          and c.referrer_module = 'customers';
        if v_target_customer_id is null then
          continue;
        end if;
      end if;

      insert into public.customer_loyalty_ledger (
        org_id, customer_id, rule_id, entry_type, source_type, source_table, source_record_id,
        amount, effective_date, idempotency_key, description, metadata
      ) values (
        v_org_id, v_target_customer_id, v_rule.id, 'credit', v_rule.rule_type || '_reward', 'invoices', new.id,
        v_amount, coalesce(new.invoice_date, new.created_at::date, current_date),
        v_rule.rule_type || '_reward:' || v_rule.id::text || ':' || new.id::text,
        case
          when v_rule.rule_type = 'referral' then 'پاداش معرفی مشتری'
          when v_rule.rule_type = 'cashback' then 'کش‌بک خرید'
          else 'هدیه اولین خرید'
        end,
        case when v_rule.rule_type = 'referral'
          then jsonb_build_object('introduced_customer_id', new.customer_id)
          else '{}'::jsonb
        end
      ) on conflict (org_id, idempotency_key) do update
        set customer_id = excluded.customer_id,
            amount = excluded.amount,
            effective_date = excluded.effective_date,
            description = excluded.description,
            metadata = excluded.metadata;

      v_applied_rule_ids := array_append(v_applied_rule_ids, v_rule.id);
      v_sync_customer_ids := array_append(v_sync_customer_ids, v_target_customer_id);
    end loop;
  end if;

  if new.customer_id is null or not public.is_customer_purchase_status(new.status) then
    -- لغو یا برگشت فاکتور، هیچ اعتبارِ منتسب به آن را باقی نمی‌گذارد؛ حتی اگر
    -- آن پاداش در زمان ذخیرهٔ دستی فاکتور با شرط‌های اختصاصی ایجاد شده باشد.
    delete from public.customer_loyalty_ledger ledger
    where ledger.org_id = v_org_id
      and ledger.source_table = 'invoices'
      and ledger.source_record_id = new.id
      and ledger.source_type in (
        'cashback_reward', 'first_purchase_reward', 'referral_reward',
        'conditioned_cashback_reward', 'conditioned_first_purchase_reward', 'conditioned_referral_reward'
      );
  else
    -- خروج از بازهٔ طرح یا تغییر معرف نباید اعتبار بدون شرطِ قدیمی را نگه دارد.
    delete from public.customer_loyalty_ledger ledger
    where ledger.org_id = v_org_id
      and ledger.source_table = 'invoices'
      and ledger.source_record_id = new.id
      and ledger.source_type in ('cashback_reward', 'first_purchase_reward', 'referral_reward')
      and coalesce(ledger.rule_id = any(v_applied_rule_ids), false) = false;
  end if;

  foreach v_customer_id in array v_sync_customer_ids loop
    if v_customer_id is null then
      continue;
    end if;
    perform public.sync_customer_loyalty_balance(v_customer_id);
  end loop;

  return new;
end;
$$;


--
-- Name: apply_full_demo_plan_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_full_demo_plan_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 if new.is_demo and (tg_op='INSERT' or old.is_demo is distinct from true) then
   select code into new.plan_code from public.saas_plans where is_active and is_demo_default order by sort_order,code limit 1;
   if new.plan_code is null then raise exception 'demo_plan_not_found'; end if;
   new.trial_ends_at:=now()+interval '15 days';
 end if;
 return new;
end; $$;


--
-- Name: apply_internal_asset_delivery(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_internal_asset_delivery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_profile_id uuid;
  v_item jsonb;
  v_asset_id uuid;
  v_asset_title text;
begin
  if new.org_id is null
     or new.form_type <> 'asset_delivery'
     or new.received_by_type <> 'internal'
     or new.status <> 'confirmed'
     or (tg_op = 'UPDATE' and old.status = 'confirmed') then
    return new;
  end if;

  if new.received_by_employee_id is null then
    raise exception 'برای تحویل داخلی مال، تحویل‌گیرنده داخلی را انتخاب کنید.';
  end if;
  if nullif(btrim(coalesce(new.storage_location, '')), '') is null then
    raise exception 'برای تحویل داخلی مال، محل نگهداری الزامی است.';
  end if;

  select e.related_profile_id
    into v_profile_id
  from public.employees e
  where e.id = new.received_by_employee_id
    and e.org_id = new.org_id
  limit 1;

  if v_profile_id is null then
    raise exception 'برای ثبت مسئول مال، ابتدا برای تحویل‌گیرنده داخلی کاربر مرتبط تعریف کنید.';
  end if;

  for v_item in
    select value from jsonb_array_elements(coalesce(new.items, '[]'::jsonb))
  loop
    begin
      v_asset_id := nullif(btrim(coalesce(v_item ->> 'asset_id', '')), '')::uuid;
    exception when invalid_text_representation then
      raise exception 'یکی از اقلام فرم تحویل، مال نامعتبر دارد.';
    end;
    if v_asset_id is null then
      continue;
    end if;

    update public.assets
    set assignee_id = v_profile_id,
        assignee_type = 'user',
        assignee_role_id = null,
        storage_location = new.storage_location,
        status = 'assigned'
    where id = v_asset_id
      and org_id = new.org_id
    returning name into v_asset_title;

    if not found then
      raise exception 'مال انتخاب‌شده متعلق به سازمان جاری نیست یا پیدا نشد.';
    end if;

    insert into public.changelogs (
      org_id, module_id, record_id, action, record_title, metadata
    ) values (
      new.org_id, 'assets', v_asset_id::text, 'update', v_asset_title,
      jsonb_build_object(
        'source', 'asset_delivery',
        'delivery_form_id', new.id::text,
        'summary', 'تحویل داخلی مال از طریق فرم تحویل ثبت شد.'
      )
    );
  end loop;

  return new;
end;
$$;


--
-- Name: apply_marketing_demo_entitlements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_marketing_demo_entitlements() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_industry text;
begin
  if new.is_demo is distinct from true or new.request_id is null then return new; end if;
  select industry into v_industry
  from public.saas_onboarding_requests
  where id = new.request_id;
  if v_industry = 'marketing' then
    new.module_overrides := coalesce(new.module_overrides, '{}'::jsonb)
      || jsonb_build_object('billboards', true, 'advertising_campaigns', true);
    new.feature_overrides := coalesce(new.feature_overrides, '{}'::jsonb)
      || jsonb_build_object('campaign_sms', true, 'campaign_email', true, 'campaign_instagram_post', true);
  end if;
  return new;
end;
$$;


--
-- Name: apply_online_account_card_payment_transaction(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_online_account_card_payment_transaction(p_transaction_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tx public.payment_transactions%rowtype;
  v_invoice record;
  v_remaining numeric;
  v_applied numeric := 0;
  v_row jsonb;
  v_index integer := 0;
  v_direct_receipt_id uuid;
  v_direct_receipt_amount numeric := 0;
begin
  select * into v_tx
  from public.payment_transactions
  where id = p_transaction_id
  for update;

  if not found
    or v_tx.purpose <> 'online_account_card'
    or v_tx.module_id <> 'customers'
    or v_tx.record_id is null
    or v_tx.status not in ('paid', 'verified')
  then
    return jsonb_build_object('success', false, 'message', 'تراکنش کارت حساب قابل ثبت نیست.');
  end if;

  if coalesce((v_tx.metadata ->> 'account_card_payment_applied')::boolean, false) then
    return jsonb_build_object('success', true, 'already_exists', true);
  end if;

  v_remaining := greatest(coalesce(v_tx.amount, 0), 0);
  for v_invoice in
    select id, remaining_balance
    from public.invoices
    where org_id = v_tx.org_id
      and customer_id = v_tx.record_id
      and status in ('confirmed', 'final', 'settled', 'completed')
      and coalesce(remaining_balance, 0) > 0
    order by invoice_date nulls last, created_at, id
    for update
  loop
    exit when v_remaining <= 0;
    v_index := v_index + 1;
    v_applied := least(v_remaining, greatest(coalesce(v_invoice.remaining_balance, 0), 0));
    v_row := jsonb_strip_nulls(jsonb_build_object(
      'row_key', 'gateway_' || replace(v_tx.id::text, '-', '') || '_' || v_index,
      'date', to_char(coalesce(v_tx.paid_at, v_tx.verified_at, now()), 'YYYY-MM-DD'),
      'amount', v_applied,
      'payment_type', 'online',
      'status', 'received',
      'description', trim(both ' ' from concat('پرداخت آنلاین زرین‌پال', case when v_tx.ref_id is not null then ' - کد پیگیری: ' || v_tx.ref_id else '' end)),
      'source', 'online_gateway',
      'locked', true,
      '_readonly', true,
      '_lockedByGateway', true,
      '_lockedFields', jsonb_build_array('date', 'amount', 'payment_type', 'status', 'description'),
      'gateway_provider', v_tx.provider,
      'gateway_scope', v_tx.gateway_scope,
      'gateway_transaction_id', v_tx.id::text,
      'authority', v_tx.authority,
      'ref_id', v_tx.ref_id
    ));

    update public.invoices
    set payments = coalesce(payments, '[]'::jsonb) || jsonb_build_array(v_row),
        updated_at = now()
    where id = v_invoice.id
      and org_id = v_tx.org_id;

    v_remaining := v_remaining - v_applied;
  end loop;

  v_direct_receipt_amount := v_remaining;
  if v_direct_receipt_amount > 0 then
    insert into public.cash_bank_operations (
      org_id,
      operation_type,
      payment_type,
      status,
      operation_date,
      amount,
      customer_id,
      description,
      metadata
    ) values (
      v_tx.org_id,
      'receipt',
      'online',
      'received',
      coalesce(v_tx.paid_at, v_tx.verified_at, now())::date,
      v_direct_receipt_amount,
      v_tx.record_id,
      trim(both ' ' from concat('پرداخت آنلاین زرین‌پال بابت مانده کارت حساب', case when v_tx.ref_id is not null then ' - کد پیگیری: ' || v_tx.ref_id else '' end)),
      jsonb_strip_nulls(jsonb_build_object(
        'source', 'online_gateway',
        'locked', true,
        '_readonly', true,
        '_lockedByGateway', true,
        '_lockedFields', jsonb_build_array('operation_date', 'amount', 'payment_type', 'status', 'description'),
        'gateway_provider', v_tx.provider,
        'gateway_scope', v_tx.gateway_scope,
        'gateway_transaction_id', v_tx.id::text,
        'authority', v_tx.authority,
        'ref_id', v_tx.ref_id,
        'account_card_id', v_tx.metadata ->> 'account_card_id'
      ))
    ) returning id into v_direct_receipt_id;
  end if;

  update public.payment_transactions
  set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
    'account_card_payment_applied', true,
    'account_card_payment_applied_at', now(),
    'allocated_amount', v_tx.amount - v_remaining,
    'direct_receipt_amount', v_direct_receipt_amount,
    'direct_receipt_operation_id', v_direct_receipt_id,
    'unallocated_amount', 0
  ))
  where id = v_tx.id;

  return jsonb_build_object(
    'success', true,
    'already_exists', false,
    'allocated_amount', v_tx.amount - v_remaining,
    'direct_receipt_amount', v_direct_receipt_amount,
    'unallocated_amount', 0
  );
end;
$$;


--
-- Name: apply_online_invoice_payment_transaction(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_online_invoice_payment_transaction(p_transaction_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tx public.payment_transactions%rowtype;
  v_pending_row_key text;
  v_has_pending_row boolean := false;
  v_exists boolean := false;
  v_updated_count integer := 0;
begin
  select * into v_tx
  from public.payment_transactions
  where id = p_transaction_id
  for update;

  if not found then return jsonb_build_object('success', false, 'message', 'تراکنش پیدا نشد.'); end if;
  if v_tx.purpose <> 'online_invoice'
     or v_tx.module_id <> 'invoices'
     or v_tx.record_id is null
     or v_tx.status not in ('paid', 'verified') then
    return jsonb_build_object('success', false, 'message', 'تراکنش قابل ثبت روی فاکتور نیست.');
  end if;

  select exists (
    select 1 from public.invoices i, lateral jsonb_array_elements(coalesce(i.payments, '[]'::jsonb)) p(item)
    where i.id = v_tx.record_id
      and i.org_id = v_tx.org_id
      and p.item ->> 'gateway_transaction_id' = v_tx.id::text
  ) into v_exists;
  if v_exists then
    return jsonb_build_object('success', true, 'already_exists', true, 'invoice_id', v_tx.record_id);
  end if;

  v_pending_row_key := nullif(btrim(coalesce(v_tx.metadata ->> 'pending_payment_row_key', '')), '');
  if v_pending_row_key is null then
    return public.append_online_invoice_payment_from_transaction(p_transaction_id);
  end if;

  select exists (
    select 1 from public.invoices i, lateral jsonb_array_elements(coalesce(i.payments, '[]'::jsonb)) p(item)
    where i.id = v_tx.record_id
      and i.org_id = v_tx.org_id
      and coalesce(p.item ->> 'row_key', p.item ->> 'payment_id', p.item ->> 'id') = v_pending_row_key
      and lower(coalesce(p.item ->> 'status', '')) = 'pending'
      and lower(coalesce(p.item ->> 'payment_type', '')) = 'online'
  ) into v_has_pending_row;
  if not v_has_pending_row then
    return jsonb_build_object('success', false, 'message', 'ردیف دریافت آنلاینِ در انتظار دیگر قابل پرداخت نیست.');
  end if;

  update public.invoices i
  set payments = (
    select coalesce(jsonb_agg(
      case when coalesce(p.item ->> 'row_key', p.item ->> 'payment_id', p.item ->> 'id') = v_pending_row_key then
        p.item || jsonb_strip_nulls(jsonb_build_object(
          'amount', v_tx.amount,
          'payment_type', 'online',
          'status', 'received',
          'date', to_char(coalesce(v_tx.paid_at, v_tx.verified_at, now()), 'YYYY-MM-DD'),
          'description', trim(both ' ' from concat(coalesce(p.item ->> 'description', ''), ' پرداخت آنلاین زرین‌پال', case when v_tx.ref_id is not null then ' - کد پیگیری: ' || v_tx.ref_id else '' end)),
          'gateway_provider', v_tx.provider,
          'gateway_scope', v_tx.gateway_scope,
          'gateway_transaction_id', v_tx.id::text,
          'authority', v_tx.authority,
          'ref_id', v_tx.ref_id,
          'locked', true,
          '_readonly', true,
          '_lockedByGateway', true,
          '_lockedFields', jsonb_build_array('date', 'amount', 'payment_type', 'status', 'description')
        ))
      else p.item end
      order by p.ordinality
    ), '[]'::jsonb)
    from jsonb_array_elements(coalesce(i.payments, '[]'::jsonb)) with ordinality p(item, ordinality)
  ), updated_at = now()
  where i.id = v_tx.record_id
    and i.org_id = v_tx.org_id;
  get diagnostics v_updated_count = row_count;
  if v_updated_count <> 1 then
    return jsonb_build_object('success', false, 'message', 'فاکتور برای ثبت دریافت پیدا نشد.');
  end if;

  update public.payment_transactions
  set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
    'invoice_payment_appended', true,
    'invoice_payment_appended_at', now(),
    'invoice_payment_row_key', v_pending_row_key,
    'invoice_payment_mode', 'pending_prepayment'
  )
  where id = v_tx.id;

  return jsonb_build_object(
    'success', true,
    'already_exists', false,
    'invoice_id', v_tx.record_id,
    'payment_row_key', v_pending_row_key
  );
end;
$$;


--
-- Name: apply_saas_billing_wallet_topup_payment_transaction(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_saas_billing_wallet_topup_payment_transaction(p_transaction_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  tx public.payment_transactions%rowtype;
  wallet public.org_billing_wallets%rowtype;
  sms public.org_sms_wallets%rowtype;
  gross numeric;
  net numeric;
  target text;
begin
  select * into tx from public.payment_transactions where id=p_transaction_id for update;
  if tx.id is null or tx.purpose<>'saas_billing_wallet_topup' or tx.status not in ('verified','paid') then raise exception 'payment_not_verified'; end if;
  target:=lower(coalesce(tx.metadata->>'wallet_target','billing'));
  gross:=greatest(0,coalesce((tx.metadata->>'wallet_amount_irt')::numeric,tx.amount,0));
  if gross<=0 then raise exception 'wallet_topup_amount_invalid'; end if;
  if target='sms' then
    if exists(select 1 from public.org_sms_wallet_transactions where org_id=tx.org_id and metadata->>'payment_transaction_id'=tx.id::text) then return jsonb_build_object('success',true,'already_applied',true); end if;
    net:=round(gross/1.10,2);
    insert into public.org_sms_wallets(org_id,status) values(tx.org_id,'active') on conflict(org_id) do nothing;
    select * into sms from public.org_sms_wallets where org_id=tx.org_id for update;
    if sms.status<>'active' then raise exception 'sms_wallet_blocked'; end if;
    update public.org_sms_wallets set balance_irt=balance_irt+net,updated_at=now() where org_id=tx.org_id returning * into sms;
    insert into public.org_sms_wallet_transactions(org_id,kind,amount_irt,balance_after_irt,description,metadata,created_by)
    values(tx.org_id,'topup',net,sms.balance_irt,'شارژ مستقیم کیف پول پیامک',jsonb_build_object('payment_transaction_id',tx.id,'gross_amount_irt',gross,'vat_percent',10,'net_amount_irt',net),tx.created_by);
    return jsonb_build_object('success',true,'wallet_target','sms','gross_amount_irt',gross,'vat_amount_irt',round(gross-net,2),'net_amount_irt',net,'balance_irt',sms.balance_irt);
  end if;
  if exists(select 1 from public.org_billing_wallet_transactions where payment_transaction_id=p_transaction_id) then return jsonb_build_object('success',true,'already_applied',true); end if;
  insert into public.org_billing_wallets(org_id) values(tx.org_id) on conflict(org_id) do nothing;
  select * into wallet from public.org_billing_wallets where org_id=tx.org_id for update;
  if wallet.status<>'active' then raise exception 'billing_wallet_blocked'; end if;
  update public.org_billing_wallets set balance_irt=balance_irt+gross,updated_at=now() where org_id=tx.org_id returning * into wallet;
  insert into public.org_billing_wallet_transactions(org_id,kind,amount_irt,balance_after_irt,payment_transaction_id,description,created_by)
  values(tx.org_id,'topup',gross,wallet.balance_irt,tx.id,'شارژ کیف پول سازمان',tx.created_by);
  return jsonb_build_object('success',true,'wallet_target','billing','balance_irt',wallet.balance_irt);
end;
$$;


--
-- Name: apply_saas_order_payment_transaction(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_saas_order_payment_transaction(p_transaction_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare tx public.payment_transactions%rowtype; order_id uuid;
begin
  select * into tx from public.payment_transactions where id = p_transaction_id for update;
  if tx.id is null or tx.purpose <> 'saas_account_order' or tx.status not in ('verified', 'paid') then raise exception 'payment_not_verified'; end if;
  order_id := (tx.metadata ->> 'saas_order_id')::uuid;
  if not exists (select 1 from public.saas_orders where id = order_id and org_id = tx.org_id) then raise exception 'saas_order_not_found'; end if;
  return public.activate_saas_order_items(order_id, tx.id, 'online');
end; $$;


--
-- Name: apply_saas_plan_invoice_term(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_saas_plan_invoice_term() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare months integer;
begin
  select coalesce((s.metadata->>'term_months')::integer,1) into months
  from public.saas_recurring_subscriptions s where s.id=new.subscription_id and s.org_id=new.org_id and s.item_kind='plan';
  if months in (3,6,12) then new.period_ends_at := new.period_starts_at + make_interval(months => months); end if;
  return new;
end $$;


--
-- Name: apply_saas_plan_order_term(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_saas_plan_order_term() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare item jsonb; months integer;
begin
  if new.item_kind <> 'plan' or new.source_order_id is null then return new; end if;
  select value into item from public.saas_orders o, jsonb_array_elements(o.items) value
  where o.id=new.source_order_id and o.org_id=new.org_id and value->>'item_kind'='plan' limit 1;
  months := coalesce((item->'metadata'->>'term_months')::integer,1);
  if months not in (1,3,6,12) then raise exception 'invalid_subscription_term'; end if;
  new.current_period_ends_at := new.current_period_starts_at + make_interval(months => months);
  new.next_invoice_at := new.current_period_ends_at - interval '7 days';
  new.metadata := coalesce(new.metadata,'{}'::jsonb) || jsonb_build_object('term_months',months);
  return new;
end $$;


--
-- Name: apply_saas_subscription_invoice_payment_transaction(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_saas_subscription_invoice_payment_transaction(p_transaction_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare tx public.payment_transactions%rowtype; invoice_id uuid;
begin
  select * into tx from public.payment_transactions where id = p_transaction_id for update;
  if tx.id is null or tx.purpose <> 'saas_subscription_invoice' or tx.status not in ('verified', 'paid') then raise exception 'payment_not_verified'; end if;
  invoice_id := (tx.metadata ->> 'saas_subscription_invoice_id')::uuid;
  if not exists (select 1 from public.saas_subscription_invoices where id = invoice_id and org_id = tx.org_id and total_irt = tx.amount) then raise exception 'saas_subscription_invoice_not_found'; end if;
  return public.activate_saas_subscription_invoice(invoice_id, tx.id, 'online');
end; $$;


--
-- Name: apply_web_form_attendance_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_web_form_attendance_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_auth_user_id uuid := auth.uid();
  v_employee_id uuid;
  v_related_profile_id uuid;
  v_submit_time timestamptz := coalesce(new.created_at, now());
  v_log_type text := '';
begin
  if coalesce(new.status, '') <> 'submitted'
     or coalesce(new.target_module_id, '') <> 'attendance_logs'
     or new.target_record_id is null then
    return new;
  end if;

  if v_auth_user_id is not null then
    select e.id, e.related_profile_id
      into v_employee_id, v_related_profile_id
    from public.employees e
    where e.related_profile_id = v_auth_user_id
      and (new.org_id is null or e.org_id = new.org_id)
    order by e.updated_at desc nulls last, e.created_at desc nulls last
    limit 1;
  end if;

  update public.attendance_logs al
  set
    source_type = 'web_form',
    employee_id = coalesce(al.employee_id, v_employee_id),
    related_profile_id = coalesce(al.related_profile_id, v_related_profile_id, v_auth_user_id),
    assignee_id = coalesce(al.assignee_id, v_related_profile_id, v_auth_user_id),
    actual_check_in_time = case
      when coalesce(al.log_type, 'check_in') = 'check_in' then v_submit_time
      else al.actual_check_in_time
    end,
    actual_check_out_time = case
      when coalesce(al.log_type, '') = 'check_out' then v_submit_time
      else al.actual_check_out_time
    end,
    updated_at = coalesce(al.updated_at, v_submit_time)
  where al.id = new.target_record_id
    and (new.org_id is null or al.org_id = new.org_id)
  returning coalesce(al.log_type, '')
    into v_log_type;

  new.record_payload := coalesce(new.record_payload, '{}'::jsonb)
    || jsonb_build_object('source_type', 'web_form');

  if v_employee_id is not null then
    new.record_payload := coalesce(new.record_payload, '{}'::jsonb)
      || jsonb_build_object('employee_id', v_employee_id);
  end if;

  if coalesce(v_log_type, 'check_in') = 'check_in' then
    new.record_payload := coalesce(new.record_payload, '{}'::jsonb)
      || jsonb_build_object('actual_check_in_time', v_submit_time);
  elsif v_log_type = 'check_out' then
    new.record_payload := coalesce(new.record_payload, '{}'::jsonb)
      || jsonb_build_object('actual_check_out_time', v_submit_time);
  end if;

  return new;
end;
$$;


--
-- Name: apply_web_form_current_employee_defaults(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_web_form_current_employee_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_form public.web_forms%rowtype;
  v_field record;
  v_employee_id uuid;
  v_auth_user_id uuid := auth.uid();
  v_target_table text := '';
  v_target_record_id text := '';
  v_column_exists boolean := false;
begin
  if coalesce(new.status, '') <> 'submitted' then
    return new;
  end if;

  v_target_table := trim(coalesce(new.target_module_id, ''));
  v_target_record_id := trim(coalesce(new.target_record_id::text, ''));
  if v_target_table = '' or v_target_record_id = '' then
    return new;
  end if;

  select *
    into v_form
  from public.web_forms
  where id = new.web_form_id
  limit 1;

  if v_form.id is null or coalesce(v_form.access_scope, 'public') <> 'internal' then
    return new;
  end if;

  for v_field in
    select wff.*
    from public.web_form_fields wff
    where wff.web_form_id = new.web_form_id
      and wff.is_active = true
      and coalesce(wff.field_type, '') = 'relation'
      and coalesce(wff.config->>'default_to_current_employee', '') = 'true'
      and trim(coalesce(wff.target_field_key, '')) <> ''
  loop
    select exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = v_target_table
        and c.column_name = v_field.target_field_key
    )
    into v_column_exists;

    if not v_column_exists then
      continue;
    end if;

    if v_auth_user_id is null then
      raise exception 'WEB_FORM_CURRENT_EMPLOYEE_AUTH_REQUIRED';
    end if;

    select e.id
      into v_employee_id
    from public.employees e
    where e.related_profile_id = v_auth_user_id
      and (new.org_id is null or e.org_id = new.org_id)
    order by e.updated_at desc nulls last, e.created_at desc nulls last
    limit 1;

    if v_employee_id is null then
      raise exception 'WEB_FORM_CURRENT_EMPLOYEE_NOT_FOUND';
    end if;

    execute format(
      'update public.%1$I set %2$I = $1 where id = $2::uuid',
      v_target_table,
      v_field.target_field_key
    )
    using v_employee_id, v_target_record_id;

    new.record_payload := coalesce(new.record_payload, '{}'::jsonb)
      || jsonb_build_object(v_field.target_field_key, v_employee_id);
  end loop;

  return new;
end;
$_$;


--
-- Name: apply_web_form_leave_review_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_web_form_leave_review_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(new.status, '') <> 'submitted'
     or coalesce(new.target_module_id, '') <> 'leave_requests'
     or new.target_record_id is null or new.org_id is null then
    return new;
  end if;

  update public.leave_requests lr
  set
    status = 'pending',
    updated_at = coalesce(new.created_at, now())
  where lr.id = new.target_record_id
    and lr.org_id = new.org_id;

  if not found then return new; end if;

  new.record_payload := coalesce(new.record_payload, '{}'::jsonb)
    || jsonb_build_object('status', 'pending');

  return new;
end;
$$;


--
-- Name: assert_process_assignee_org(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_process_assignee_org(p_org_id uuid, p_assignee_user_id uuid, p_assignee_role_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_org_id is null then
    raise exception 'سازمان فرآیند مشخص نیست.' using errcode = '42501';
  end if;

  if p_assignee_user_id is not null and not exists (
    select 1
    from public.profiles p
    where p.id = p_assignee_user_id
      and p.org_id = p_org_id
  ) then
    raise exception 'مسئول انتخاب‌شده متعلق به سازمان جاری نیست.' using errcode = '42501';
  end if;

  if p_assignee_role_id is not null and not exists (
    select 1
    from public.org_roles r
    where r.id = p_assignee_role_id
      and r.org_id = p_org_id
  ) then
    raise exception 'نقش انتخاب‌شده متعلق به سازمان جاری نیست.' using errcode = '42501';
  end if;
end;
$$;


--
-- Name: assign_system_code_from_module_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_system_code_from_module_settings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_current_code text;
  v_module_key text;
  v_org_id uuid;
  v_org_scope text;
  v_settings jsonb;
  v_naming jsonb;
  v_prefix text;
  v_start_raw text;
  v_width_raw text;
  v_start_number integer;
  v_number_width integer;
  v_last_number integer := 0;
  v_next_number integer := 0;
  v_candidate text;
  v_exists boolean;
  v_max_sequence integer := 2147483647;
  v_max_width integer := 20;
begin
  v_current_code := coalesce(to_jsonb(new) ->> 'system_code', '');
  if nullif(btrim(v_current_code), '') is not null then
    return new;
  end if;

  v_module_key := coalesce(nullif(btrim(tg_table_name), ''), 'module');
  v_org_id := nullif(to_jsonb(new) ->> 'org_id', '')::uuid;
  v_org_scope := coalesce(v_org_id::text, '__global__');
  v_start_number := case when v_module_key = 'customers' then 234 else 100 end;
  v_number_width := case when v_module_key = 'customers' then 3 else null end;

  v_settings := null;
  begin
    select settings
      into v_settings
    from public.integration_settings
    where connection_type = 'module_settings'
      and (v_org_id is null or org_id is null or org_id = v_org_id)
    order by case when org_id = v_org_id then 0 else 1 end, created_at desc
    limit 1;
  exception
    when undefined_table then
      v_settings := null;
  end;

  v_naming := coalesce(v_settings -> 'modules' -> v_module_key -> 'general' -> 'systemCodeNaming', '{}'::jsonb);
  v_prefix := upper(regexp_replace(coalesce(
    nullif(btrim(v_naming ->> 'prefix'), ''),
    nullif(btrim(v_naming ->> 'prefixLetter'), ''),
    nullif(left(v_module_key, 1), ''),
    'M'
  ), '[[:space:]]+', '', 'g'));
  if coalesce(v_prefix, '') = '' then
    v_prefix := 'M';
  end if;

  v_start_raw := coalesce(v_naming ->> 'startNumber', '');
  if v_start_raw ~ '^[0-9]+$' then
    if v_start_raw::numeric <= v_max_sequence then
      v_start_number := greatest(v_start_raw::numeric, 0)::integer;
    end if;
  end if;

  v_width_raw := coalesce(v_naming ->> 'numberWidth', '');
  if v_width_raw ~ '^[0-9]+$' then
    if v_width_raw::numeric between 1 and v_max_width then
      v_number_width := v_width_raw::integer;
    else
      v_number_width := null;
    end if;
  end if;

  if v_module_key = 'customers'
     and coalesce(v_naming ->> 'numberWidth', '') = ''
     and v_prefix = 'C'
     and v_start_number = 100 then
    v_start_number := 234;
    v_number_width := 3;
  end if;

  perform pg_advisory_xact_lock(
    hashtext(format('system_code:%s:%s:%s', v_module_key, v_org_scope, v_prefix))
  );

  insert into public.system_code_counters (table_name, org_scope, prefix, last_number)
  values (v_module_key, v_org_scope, v_prefix, greatest(v_start_number - 1, 0))
  on conflict (table_name, org_scope, prefix) do nothing;

  loop
    update public.system_code_counters
       set last_number = greatest(last_number + 1, v_start_number),
           updated_at = now()
     where table_name = v_module_key
       and org_scope = v_org_scope
       and prefix = v_prefix
     returning last_number into v_next_number;

    v_candidate := v_prefix || case
      when v_number_width is null then v_next_number::text
      else lpad(v_next_number::text, v_number_width, '0')
    end;

    execute format(
      'select exists(
         select 1
           from public.%I
          where ($1::uuid is null or org_id = $1)
            and upper(system_code) = upper($2)
       )',
      v_module_key
    )
    into v_exists
    using v_org_id, v_candidate;

    exit when not v_exists;

    v_last_number := public.find_system_code_last_number(v_module_key, v_org_id, v_prefix, v_max_sequence);
    update public.system_code_counters
       set last_number = greatest(last_number, v_last_number),
           updated_at = now()
     where table_name = v_module_key
       and org_scope = v_org_scope
       and prefix = v_prefix;
  end loop;

  new.system_code := v_candidate;
  return new;
end;
$_$;


--
-- Name: audit_saas_org_payment_hosts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_saas_org_payment_hosts() RETURNS TABLE(org_id uuid, org_name text, slug text, resolved_host text, host_status text, gateway_active boolean, online_invoice_payments_enabled boolean, gateway_scope text, payment_domain text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  with tenant_orgs as (
    select s.org_id, s.slug, s.resolved_host, false as is_internal_saas_admin
    from public.saas_org_settings s
  ),
  internal_saas_admin_orgs as (
    select distinct r.org_id, null::text as slug, 'kalam.tazesystem.ir'::text as resolved_host, true as is_internal_saas_admin
    from public.org_roles r
    where coalesce((r.permissions -> '__saas_admin' ->> 'view')::boolean, false) = true
       or coalesce((r.permissions -> '__saas_admin' ->> 'edit')::boolean, false) = true
       or exists (
         select 1
         from jsonb_each(coalesce(r.permissions -> '__saas_admin' -> 'fields', '{}'::jsonb)) as field_permission(key, value)
         where field_permission.value = 'true'::jsonb
       )
  ),
  audited_orgs as (
    select * from tenant_orgs
    union all
    select a.*
    from internal_saas_admin_orgs a
    where not exists (select 1 from tenant_orgs t where t.org_id = a.org_id)
  )
  select
    a.org_id,
    o.name,
    a.slug,
    a.resolved_host,
    case
      when a.is_internal_saas_admin then 'internal_saas_admin'
      when nullif(btrim(coalesce(a.resolved_host, '')), '') is null then 'missing_host'
      when lower(btrim(a.resolved_host)) !~ '^[a-z0-9.-]+$' then 'invalid_host'
      else 'ok'
    end,
    coalesce(g.is_active, false),
    coalesce((g.settings ->> 'online_invoice_payments_enabled')::boolean, false),
    coalesce(g.settings ->> 'gateway_scope', 'system'),
    coalesce(g.settings ->> 'payment_domain', '')
  from audited_orgs a
  join public.organizations o on o.id = a.org_id
  left join lateral (
    select i.is_active, i.settings
    from public.integration_settings i
    where i.org_id = a.org_id
      and i.connection_type = 'payment_gateway'
      and coalesce(i.provider, '') = 'zarinpal'
    order by i.is_active desc, i.updated_at desc nulls last, i.created_at desc nulls last
    limit 1
  ) g on true
  order by o.name, a.org_id;
$_$;


--
-- Name: begin_demo_seed_batch(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_demo_seed_batch(p_org_id uuid, p_user_id uuid, p_pack_key text, p_industry text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('demo:' || p_org_id::text, 0));
  if not exists(select 1 from public.saas_org_settings where org_id = p_org_id and is_demo) then
    raise exception 'این حساب آزمایشی نیست.';
  end if;
  if exists(select 1 from public.demo_seed_batches where org_id = p_org_id and cleared_at is null and status <> 'cleared') then
    raise exception 'داده‌های نمونه قبلی یا ساخت ناتمام وجود دارد؛ ابتدا آن‌ها را حذف کنید.';
  end if;
  insert into public.demo_seed_batches(org_id, pack_key, industry_key, seeded_by, status)
  values(p_org_id, p_pack_key, p_industry, p_user_id, 'seeding') returning id into result;
  return result;
end; $$;


--
-- Name: billboard_operational_status_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billboard_operational_status_label(p_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case trim(coalesce(p_status, ''))
    when 'free' then 'آزاد'
    when 'oral_reserve' then 'رزرو شفاهی'
    when 'final_reserve' then 'رزرو قطعی'
    when 'in_line' then 'در صف نصب'
    when 'opening' then 'در حال اکران'
    when 'near_finish' then 'نزدیک به اتمام'
    when 'opening_deadline_ended' then 'پایان مهلت اکران'
    when 'pickup_queue' then 'در صف جمع‌آوری'
    when 'inactive' then 'غیرفعال'
    when 'blocked' then 'مسدود'
    else 'وضعیت تعریف‌نشده'
  end;
$$;


--
-- Name: bind_voip_operator_identity(text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_voip_operator_identity(p_provider text, p_service_id text, p_extension text, p_operator_code text, p_provider_operator_id text, p_display_name text, p_profile_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_provider text := coalesce(nullif(trim(p_provider), ''), 'telefonchy');
  v_service_id text := nullif(trim(coalesce(p_service_id, '')), '');
  v_extension text := nullif(trim(coalesce(p_extension, '')), '');
  v_operator_code text := nullif(trim(coalesce(p_operator_code, '')), '');
  v_provider_operator_id text := nullif(trim(coalesce(p_provider_operator_id, '')), '');
  v_binding_id uuid;
begin
  if v_org_id is null or p_profile_id is null then raise exception 'اطلاعات اتصال اپراتور معتبر نیست.'; end if;
  if v_extension is null and v_operator_code is null and v_provider_operator_id is null then raise exception 'داخلی یا کد اپراتور لازم است.'; end if;
  if not exists (select 1 from public.profiles p where p.id = p_profile_id and p.org_id = v_org_id) then
    raise exception 'کاربر انتخاب‌شده در این سازمان یافت نشد.';
  end if;

  delete from public.voip_operator_identity_bindings b
  where b.org_id = v_org_id and b.provider = v_provider and coalesce(b.service_id, '') = coalesce(v_service_id, '')
    and (
      (v_extension is not null and b.extension = v_extension)
      or (v_operator_code is not null and b.operator_code = v_operator_code)
      or (v_provider_operator_id is not null and b.provider_operator_id = v_provider_operator_id)
    );

  insert into public.voip_operator_identity_bindings (
    org_id, provider, service_id, extension, operator_code, provider_operator_id, display_name, profile_id
  ) values (
    v_org_id, v_provider, v_service_id, v_extension, v_operator_code, v_provider_operator_id,
    nullif(trim(coalesce(p_display_name, '')), ''), p_profile_id
  ) returning id into v_binding_id;

  update public.profiles p
  set voip_enabled = true,
      voip_extension = coalesce(v_extension, p.voip_extension),
      voip_operator_code = coalesce(v_operator_code, p.voip_operator_code)
  where p.id = p_profile_id and p.org_id = v_org_id;

  update public.voip_call_logs c
  set assignee_id = p_profile_id,
      assignee_type = 'user',
      metadata = coalesce(c.metadata, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
        'provider_operator_name', nullif(trim(coalesce(p_display_name, '')), ''),
        'provider_operator_id', v_provider_operator_id
      ))
  where c.org_id = v_org_id and c.provider = v_provider
    and (v_service_id is null or c.service_id = v_service_id)
    and (
      (v_extension is not null and c.extension = v_extension)
      or (v_operator_code is not null and c.operator_code = v_operator_code)
      or (v_provider_operator_id is not null and c.metadata->>'provider_operator_id' = v_provider_operator_id)
    );
  return v_binding_id;
end;
$$;


--
-- Name: call_contact_condition_matches(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_contact_condition_matches(p_row jsonb, p_condition jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare f text:=p_condition->>'field';op text:=p_condition->>'operator';v jsonb;expected jsonb:=p_condition->'value';actual_text text;expected_text text;
begin
 if f is null or f!~'^[a-zA-Z_][a-zA-Z0-9_]*$' or not(p_row?f)then return null;end if;
 v:=p_row->f;actual_text:=p_row->>f;expected_text:=p_condition->>'value';
 case op
 when 'eq' then return actual_text is not distinct from expected_text;
 when 'neq' then return actual_text is not null and expected_text is not null and actual_text<>expected_text;
 when 'is_empty' then return actual_text is null or actual_text='';
 when 'is_not_empty' then return actual_text is not null and actual_text<>'';
 when 'contains' then return actual_text is not null and expected_text is not null and position(expected_text in actual_text)>0;
 when 'in' then if jsonb_typeof(expected)<>'array' then return null;end if;return exists(select 1 from jsonb_array_elements_text(expected)x where x=actual_text);
 when 'not_in' then if jsonb_typeof(expected)<>'array' then return null;end if;return actual_text is not null and not exists(select 1 from jsonb_array_elements_text(expected)x where x=actual_text);
 when 'gt','gte','lt','lte' then
  if actual_text is null or expected_text is null then return false;end if;
  if jsonb_typeof(v)='number' and jsonb_typeof(expected)='number' then
   return case op when 'gt' then actual_text::numeric>expected_text::numeric when 'gte' then actual_text::numeric>=expected_text::numeric when 'lt' then actual_text::numeric<expected_text::numeric else actual_text::numeric<=expected_text::numeric end;
  elsif jsonb_typeof(v)='string' and jsonb_typeof(expected)='string' then
   return case op when 'gt' then actual_text>expected_text when 'gte' then actual_text>=expected_text when 'lt' then actual_text<expected_text else actual_text<=expected_text end;
  end if;
  return false;
 else return null;
 end case;
exception when others then return null;
end;$_$;


--
-- Name: call_contact_scope_visible(jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_contact_scope_visible(p_context jsonb, p_module text, p_row jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare p jsonb:=coalesce(p_context->'permissions'->p_module,'{}');s text:=coalesce(nullif(p->>'record_scope',''),'all');
 u uuid:=auth.uid();r uuid:=nullif(p_context->>'role_id','')::uuid;allowed_roles uuid[];g jsonb:=p->'view_conditions';all_conditions jsonb;any_conditions jsonb;c jsonb;matched boolean;any_matched boolean:=false;
begin
 if not(p_context->'permissions'?p_module) or coalesce((p->>'view')::boolean,true)=false then return false;end if;
 if g?'conditions_all' or g?'conditions_any' then all_conditions:=coalesce(g->'conditions_all','[]');any_conditions:=coalesce(g->'conditions_any','[]');
 elsif g->>'logic'='or' then all_conditions:='[]';any_conditions:=coalesce(g->'conditions','[]');
 else all_conditions:=coalesce(g->'conditions','[]');any_conditions:='[]';end if;
 for c in select value from jsonb_array_elements(all_conditions)loop
  matched:=public.call_contact_condition_matches(p_row,c);if matched is distinct from true then return false;end if;
 end loop;
 for c in select value from jsonb_array_elements(any_conditions)loop
  matched:=public.call_contact_condition_matches(p_row,c);if matched is null then return false;end if;any_matched:=any_matched or matched;
 end loop;
 if jsonb_array_length(any_conditions)>0 and not any_matched then return false;end if;
 if s='all' then return true;end if;
 if u is null then return false;end if;
 if s='own' then return p_row->>'assignee_id'=u::text;end if;
 if s='team' then return p_row->>'assignee_id'=u::text or (r is not null and p_row->>'assignee_role_id'=r::text);end if;
 if s='subtree' then
  with recursive tree as(select id from public.org_roles where id=r and org_id=public.current_org_id()
   union select child.id from public.org_roles child join tree parent on child.parent_id=parent.id where child.org_id=public.current_org_id())
   select coalesce(array_agg(id),'{}'::uuid[]) into allowed_roles from tree;
  return p_row->>'assignee_role_id'=any(allowed_roles::text[]) or p_row->>'assignee_id'=u::text or exists(select 1 from public.user_organization_memberships m
    where m.org_id=public.current_org_id() and m.is_active and m.user_id::text=p_row->>'assignee_id' and m.role_id=any(allowed_roles));
 end if;
 return false;
exception when others then return false;
end;$$;


--
-- Name: can_access_product_site_content(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_product_site_content(p_org_id uuid, p_action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(p_action in ('view', 'edit') and exists (
    select 1
    from public.user_organization_memberships m
    left join public.org_roles r on r.id = m.role_id and r.org_id = m.org_id
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.is_active = true
      and p_org_id = public.current_org_id()
      and case
        when m.is_owner = true or lower(coalesce(m.software_role, '')) in ('super_admin', 'admin', 'manager') then true
        else coalesce((r.permissions -> 'products' ->> p_action)::boolean, true)
      end
  ), false);
$$;


--
-- Name: can_collaborate_advertising_campaign_tool(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_collaborate_advertising_campaign_tool(p_tool_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.advertising_campaign_tools tool
    where tool.id = p_tool_id
      and tool.org_id = public.current_org_id()
      and public.current_user_can_access_advertising_campaign_module()
      and public.current_user_has_role_permission_entry('advertising_campaigns', 'view', null, true)
      and (
        public.can_view_advertising_campaign(tool.campaign_id)
        or auth.uid() = any(tool.collaborator_user_ids)
        or public.current_user_advertising_campaign_role_id() = any(tool.collaborator_role_ids)
      )
  )
$$;


