  select public.can_view_advertising_campaign(p_campaign_id)
     and public.current_user_has_role_permission_entry('advertising_campaigns','edit',null,true)
$$;


--
-- Name: can_manage_billboard_status_change(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_billboard_status_change(p_action text DEFAULT 'request'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_permissions jsonb := '{}'::jsonb;
  v_module_permission jsonb := '{}'::jsonb;
  v_fields jsonb := '{}'::jsonb;
  v_action text := lower(coalesce(trim(p_action), 'request'));
begin
  if auth.uid() is null or public.current_org_id() is null then return false; end if;
  select coalesce(role_row.permissions, '{}'::jsonb)
    into v_permissions
  from public.profiles profile_row
  left join public.org_roles role_row
    on role_row.id = profile_row.role_id and role_row.org_id = profile_row.org_id
  where profile_row.id = auth.uid() and profile_row.org_id = public.current_org_id()
  limit 1;
  v_module_permission := coalesce(v_permissions -> 'billboard_status_changes', '{}'::jsonb);
  v_fields := coalesce(v_module_permission -> 'fields', '{}'::jsonb);
  if coalesce((v_module_permission ->> 'view')::boolean, true) is false then return false; end if;
  if v_action = 'approve' then
    return coalesce((v_fields ->> '__action_approve_billboard_status_change')::boolean,
                    (v_module_permission ->> 'edit')::boolean, true);
  end if;
  return coalesce((v_module_permission ->> 'edit')::boolean, true);
end;
$$;


--
-- Name: can_manage_organization_members(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_organization_members() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(exists(select 1 from public.user_organization_memberships m
    left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
    where m.user_id=auth.uid() and m.org_id=public.current_org_id() and m.is_active
    and (m.software_role in ('super_admin','admin','manager')
      or r.title in ('مدیر ارشد','مدیر سیستم','مدیر سازمان','مدیر'))),false);
$$;


--
-- Name: can_manage_tenant_site_pages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_tenant_site_pages(p_org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(exists (
    select 1 from public.user_organization_memberships m
    where m.org_id = p_org_id and m.user_id = auth.uid() and m.is_active = true
      and p_org_id = public.current_org_id()
      and (m.is_owner = true or lower(coalesce(m.software_role, '')) in ('super_admin', 'admin', 'manager'))
  ), false);
$$;


--
-- Name: can_view_advertising_campaign(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_advertising_campaign(p_campaign_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.advertising_campaigns campaign
    where campaign.id = p_campaign_id
      and campaign.org_id = public.current_org_id()
      and public.current_user_can_access_advertising_campaign_module()
      and public.current_user_has_role_permission_entry('advertising_campaigns', 'view', null, true)
      and (
        campaign.created_by = auth.uid()
        or (campaign.assignee_type = 'user' and campaign.assignee_id = auth.uid())
        or (campaign.assignee_type = 'role' and campaign.assignee_role_id = public.current_user_advertising_campaign_role_id())
        or auth.uid() = any(campaign.viewer_user_ids)
        or public.current_user_advertising_campaign_role_id() = any(campaign.viewer_role_ids)
        or public.current_user_has_role_permission_entry('advertising_campaigns', 'view', 'all_campaigns', false)
      )
  )
$$;


--
-- Name: canonicalize_auth_user_phone(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonicalize_auth_user_phone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare canonical text;
begin
  if new.phone is null or new.phone='' then return new; end if;
  canonical := public.normalize_iran_mobile_e164(new.phone);
  if canonical is not null then new.phone := substr(canonical,2);
  else
    new.phone := translate(trim(new.phone), '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789');
    new.phone := regexp_replace(new.phone, '[+[:space:]().‌-‏-]', '', 'g');
    if new.phone like '00%' then new.phone := substr(new.phone,3); end if;
    if new.phone !~ '^[1-9][0-9]{1,14}$' then
      raise exception 'شماره تلفن معتبر نیست.' using errcode='22023';
    end if;
  end if;
  return new;
end;
$_$;


--
-- Name: capture_advertising_campaign_sms_response(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_advertising_campaign_sms_response(p_org_id uuid, p_inbound_message_id uuid, p_sender text, p_receiver text, p_message_text text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_sender_key text:=public.advertising_campaign_contact_key('sms',p_sender); v_count int;
        v_message_id uuid; v_campaign_id uuid; v_tool_id uuid; v_dispatch_id uuid;
        v_source_module_id text; v_source_record_id uuid;
        v_response_id uuid; v_tool_config jsonb:='{}'::jsonb; v_rule_matches boolean:=false;
        v_normalized text:=lower(regexp_replace(public.advertising_campaign_normalize_digits(p_message_text),'\s+','','g'));
begin
  if p_org_id is null or v_sender_key='' or p_inbound_message_id is null then return null; end if;
  select count(*) into v_count
  from public.outbound_messages m
  join public.advertising_campaign_tools t on t.id=m.advertising_campaign_tool_id and t.org_id=p_org_id
  where m.org_id=p_org_id and m.channel_type='sms' and coalesce(m.direction,'outbound')='outbound'
    and public.advertising_campaign_contact_key('sms',m.recipient)=v_sender_key
    and (nullif(btrim(p_receiver),'') is null or nullif(btrim(m.sender),'') is null or btrim(m.sender)=btrim(p_receiver))
    and m.advertising_campaign_id is not null and m.status in ('provider_accepted','sent','delivered')
    and coalesce(m.sent_at,m.created_at) >= now() - make_interval(hours=>public.advertising_campaign_reply_window_hours(t.config));
  if coalesce(v_count,0)=0 then return null; end if;

  select m.id,m.advertising_campaign_id,m.advertising_campaign_tool_id,m.advertising_campaign_dispatch_id,
         r.source_module_id,r.source_record_id,t.config
    into v_message_id,v_campaign_id,v_tool_id,v_dispatch_id,v_source_module_id,v_source_record_id,v_tool_config
  from public.outbound_messages m
  join public.advertising_campaign_tools t on t.id=m.advertising_campaign_tool_id and t.org_id=p_org_id
  left join public.advertising_campaign_recipients r on r.outbound_message_id=m.id
  where m.org_id=p_org_id and m.channel_type='sms' and coalesce(m.direction,'outbound')='outbound'
    and public.advertising_campaign_contact_key('sms',m.recipient)=v_sender_key
    and (nullif(btrim(p_receiver),'') is null or nullif(btrim(m.sender),'') is null or btrim(m.sender)=btrim(p_receiver))
    and m.advertising_campaign_id is not null and m.status in ('provider_accepted','sent','delivered')
    and coalesce(m.sent_at,m.created_at) >= now() - make_interval(hours=>public.advertising_campaign_reply_window_hours(t.config))
  order by coalesce(m.sent_at,m.created_at) desc
  limit 1;
  v_rule_matches:=public.advertising_campaign_inbound_rule_matches(v_tool_config,p_message_text);

  insert into public.advertising_campaign_responses(
    org_id,campaign_id,tool_id,dispatch_id,inbound_message_id,source_module_id,source_record_id,
    sender,receiver,message_text,normalized_message,match_status,workflow_status,metadata
  ) values (
    p_org_id,v_campaign_id,v_tool_id,v_dispatch_id,p_inbound_message_id,
    v_source_module_id,v_source_record_id,p_sender,p_receiver,p_message_text,v_normalized,
    case when v_count=1 then 'matched' else 'ambiguous' end,
    case when v_count=1 and v_rule_matches then 'pending' else 'ignored' end,
    jsonb_build_object('candidate_count',v_count,'matched_outbound_message_id',v_message_id,
      'inbound_enabled',coalesce((v_tool_config->>'inbound_enabled')::boolean,false),
      'inbound_rule_match',v_rule_matches,
      'reply_window_hours',public.advertising_campaign_reply_window_hours(v_tool_config))
  ) on conflict (org_id,inbound_message_id) do update set updated_at=now()
  returning id into v_response_id;

  if v_normalized ~ 'لغو11' then
    insert into public.campaign_contact_suppressions(org_id,channel_type,contact_value,contact_key,reason,source_response_id)
    values(p_org_id,'sms',p_sender,v_sender_key,'لغو تبلیغات پیامکی',v_response_id)
    on conflict (org_id,channel_type,contact_key) where is_active=true
    do update set reason=excluded.reason,source_response_id=excluded.source_response_id,updated_at=now();
  end if;
  return v_response_id;
exception when invalid_text_representation then
  return null;
end;
$$;


--
-- Name: capture_commission_cheque_review(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_commission_cheque_review(p_cheque_id uuid, p_employee_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_cheque public.cheques%rowtype;
begin
  select * into v_cheque from public.cheques where id = p_cheque_id;
  if not found or v_cheque.org_id is null or v_cheque.status not in ('bounced','returned') then return; end if;
  insert into public.commission_review_cases
    (org_id,employee_id,ledger_entry_id,cheque_id,review_after,posted_amount_at_risk,details)
  select l.org_id,l.employee_id,l.id,v_cheque.id,greatest(l.period_end + 1,current_date),l.amount,
    jsonb_build_object('ledger_title', l.title, 'cheque_number', v_cheque.serial_no,
      'cheque_status',v_cheque.status,'calculation_snapshot',l.details,
      'amount_is_upper_bound',true,'requires_manual_recalculation',true)
  from public.payroll_calculation_entries l
  join public.employees e on e.id=l.employee_id and e.org_id=l.org_id
  where l.org_id = v_cheque.org_id and l.source_type = 'commission'
    and l.status not in ('draft','voided') and l.amount > 0
    and (p_employee_id is null or l.employee_id = p_employee_id)
    and (
      exists (select 1 from jsonb_array_elements(case when jsonb_typeof(l.details->'rows')='array' then l.details->'rows' else '[]'::jsonb end) r
        where exists (select 1 from jsonb_array_elements(case when jsonb_typeof(r->'cheque_payments')='array' then r->'cheque_payments' else '[]'::jsonb end) p
          where coalesce(p->>'cheque_id',p->>'spent_cheque_id') = v_cheque.id::text)
        or exists (select 1 from public.invoices i where i.org_id=l.org_id and i.id::text=r->>'invoice_id'
          and (i.payments @> jsonb_build_array(jsonb_build_object('cheque_id',v_cheque.id::text))
            or i.payments @> jsonb_build_array(jsonb_build_object('spent_cheque_id',v_cheque.id::text))
            or exists (select 1 from public.cash_bank_operations o
              where o.org_id=l.org_id and o.sales_invoice_id=i.id and o.cheque_id=v_cheque.id
                and o.operation_type <> 'payment' and o.operation_type <> 'transfer'))))
      or exists (select 1 from public.invoices i where i.org_id=l.org_id
        and i.id::text=coalesce(l.details->>'invoice_id',l.source_record_id::text)
        and (i.payments @> jsonb_build_array(jsonb_build_object('cheque_id',v_cheque.id::text))
          or i.payments @> jsonb_build_array(jsonb_build_object('spent_cheque_id',v_cheque.id::text))
          or exists (select 1 from public.cash_bank_operations o
            where o.org_id=l.org_id and o.sales_invoice_id=i.id and o.cheque_id=v_cheque.id
              and o.operation_type <> 'payment' and o.operation_type <> 'transfer')))
    )
  on conflict (org_id,ledger_entry_id,cheque_id,reason) do update
  set updated_at=now(), details=public.commission_review_cases.details || jsonb_build_object('cheque_status',v_cheque.status);
end;
$$;


--
-- Name: current_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_org_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_headers jsonb; v_host text; v_org uuid; v_requested text; v_candidates integer;
begin
  if auth.uid() is null then return null; end if;
  begin v_headers:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
  exception when others then return null; end;
  v_host:=lower(split_part(split_part(regexp_replace(coalesce(v_headers->>'origin',''),'^https?://',''), '/',1),':',1));
  -- Host binding wins over caller-provided context, including the internal and provider panels.
  if v_host not in ('','localhost','127.0.0.1','app.tazesystem.ir','tazesystem.ir','www.tazesystem.ir') then
    -- Same host resolution as get_public_branding, without materializing public
    -- branding, subscription and integration JSON for every RLS predicate.
    -- SECURITY DEFINER remains necessary to avoid recursive profile RLS;
    -- the active membership/organization check below remains mandatory.
    if v_host in ('kalam.tazesystem.ir','kalamapp.ir','www.kalamapp.ir') then
      select count(*), (array_agg(candidate.org_id))[1] into v_candidates,v_org
      from (
        select distinct cs.org_id from public.company_settings cs
        join public.org_roles r on r.org_id=cs.org_id
        left join public.saas_org_settings s on s.org_id=cs.org_id
        where cs.org_id is not null
          and coalesce(s.is_billing_provider,false)=false
          and nullif(trim(coalesce(s.resolved_host,'')),'') is null
          and (lower(coalesce(r.permissions->'__saas_admin'->>'view','false'))='true'
            or lower(coalesce(r.permissions->'__saas_admin'->>'edit','false'))='true')
      ) candidate;
      if v_candidates<>1 then return null; end if;
    else
      select s.org_id into v_org from public.saas_org_settings s
      join public.organizations o on o.id=s.org_id
      where lower(s.resolved_host)=v_host
      order by s.updated_at desc nulls last limit 1;
    end if;
    if v_org is null then return null; end if;
  else
    -- x-client-info is already allowed by Supabase CORS; no gateway configuration change is needed.
    v_requested:=coalesce(nullif(trim(v_headers->>'x-organization-id'),''),
      substring(coalesce(v_headers->>'x-client-info','') from '(?:^|;\s*)org=([0-9a-fA-F-]{36})(?:;|$)'));
    if v_requested is not null then
      begin v_org:=v_requested::uuid; exception when invalid_text_representation then return null; end;
    elsif v_host in ('app.tazesystem.ir','tazesystem.ir','www.tazesystem.ir') then
      return null; -- Shared login is not a tenant and must not inherit another tab's organization.
    else
      -- Compatibility for trusted server requests without Origin and local development.
      select org_id into v_org from public.profiles where id=auth.uid();
    end if;
  end if;
  if exists(select 1 from public.user_organization_memberships m
    join public.organizations o on o.id=m.org_id and o.is_active
    where m.user_id=auth.uid() and m.org_id=v_org and m.is_active)
  then return v_org; end if;
  return null;
end;
$_$;


--
-- Name: generate_short_share_token(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_short_share_token(p_length integer DEFAULT 10) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
  v_length integer := greatest(coalesce(p_length, 10), 8);
  v_seed text := encode(
    sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text as bytea)),
    'hex'
  );
  v_result text := '';
  v_index integer;
  v_pos integer;
  v_chunk text;
begin
  for v_pos in 0..(v_length - 1) loop
    if (v_pos * 2) + 2 > length(v_seed) then
      v_seed := v_seed || encode(
        sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text || v_pos::text as bytea)),
        'hex'
      );
    end if;
    v_chunk := substr(v_seed, (v_pos * 2) + 1, 2);
    v_index := mod(('x' || v_chunk)::bit(8)::integer, length(v_alphabet));
    v_result := v_result || substr(v_alphabet, v_index + 1, 1);
  end loop;
  return v_result;
end;
$$;


