    "position" text,
    team text,
    hire_date date,
    avatar_url text,
    bio text,
    role text DEFAULT 'viewer'::text NOT NULL,
    role_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    system_code text,
    bale_chat_id text,
    voip_operator_code text,
    voip_extension text,
    voip_service_id text,
    voip_enabled boolean DEFAULT false NOT NULL,
    voip_dial_mode text DEFAULT 'telefonchy_smartcall'::text NOT NULL,
    employee_id uuid,
    process_template_id uuid,
    execution_process_draft jsonb DEFAULT '[]'::jsonb NOT NULL,
    first_name text,
    last_name text,
    salary_type text,
    default_work_schedule_id uuid,
    has_flexible_hours boolean DEFAULT false NOT NULL,
    expected_daily_minutes integer DEFAULT 480 NOT NULL,
    grace_minutes_for_late integer DEFAULT 0 NOT NULL,
    overtime_auto_approve boolean DEFAULT false NOT NULL,
    leave_auto_approve boolean DEFAULT false NOT NULL,
    mission_auto_approve boolean DEFAULT false NOT NULL,
    base_salary numeric(18,2) DEFAULT 0 NOT NULL,
    hourly_rate numeric(18,2) DEFAULT 0 NOT NULL,
    overtime_rate numeric(18,2) DEFAULT 0 NOT NULL,
    late_penalty_rate numeric(18,2) DEFAULT 0 NOT NULL,
    early_bonus_rate numeric(18,2) DEFAULT 0 NOT NULL,
    production_bonus_rate numeric(18,2) DEFAULT 0 NOT NULL,
    commission_percentage numeric(8,4) DEFAULT 0 NOT NULL,
    tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    telegram_chat_id text,
    rubika_chat_id text,
    assignee_id uuid,
    assignee_type text,
    assignee_role_id uuid,
    CONSTRAINT profiles_assignee_type_check CHECK ((assignee_type = ANY (ARRAY['user'::text, 'role'::text]))),
    CONSTRAINT profiles_voip_dial_mode_check CHECK ((voip_dial_mode = ANY (ARRAY['webphone_webrtc'::text, 'telefonchy_smartcall'::text, 'sip_link'::text, 'tel_link'::text])))
);


