--
-- Name: cash_bank_unified_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cash_bank_unified_ledger WITH (security_invoker='true') AS
 WITH account_directory AS (
         SELECT (bank_accounts.id)::text AS id,
            'bank_accounts'::text AS module_id,
            concat_ws(' '::text, NULLIF(btrim(bank_accounts.bank_name), ''::text),
                CASE
                    WHEN (NULLIF(btrim(bank_accounts.account_number), ''::text) IS NOT NULL) THEN (('('::text || bank_accounts.account_number) || ')'::text)
                    ELSE NULL::text
                END) AS label
           FROM public.bank_accounts
          WHERE (bank_accounts.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT (cash_boxes.id)::text AS id,
            'cash_boxes'::text AS text,
            concat_ws(' '::text, NULLIF(btrim(cash_boxes.name), ''::text),
                CASE
                    WHEN (NULLIF(btrim(cash_boxes.code), ''::text) IS NOT NULL) THEN (('('::text || cash_boxes.code) || ')'::text)
                    ELSE NULL::text
                END) AS concat_ws
           FROM public.cash_boxes
          WHERE (cash_boxes.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT (petty_funds.id)::text AS id,
            'petty_funds'::text AS text,
            concat_ws(' '::text, NULLIF(btrim(petty_funds.name), ''::text),
                CASE
                    WHEN (NULLIF(btrim(petty_funds.code), ''::text) IS NOT NULL) THEN (('('::text || petty_funds.code) || ')'::text)
                    ELSE NULL::text
                END) AS concat_ws
           FROM public.petty_funds
          WHERE (petty_funds.org_id = ( SELECT public.current_org_id() AS current_org_id))
        ), party_directory AS (
         SELECT (customers.id)::text AS id,
            'customers'::text AS module_id,
            COALESCE(NULLIF(btrim(concat_ws(' '::text, customers.first_name, customers.last_name)), ''::text), NULLIF(btrim(customers.business_name), ''::text), NULLIF(btrim(customers.system_code), ''::text), 'بدون عنوان'::text) AS label
           FROM public.customers
          WHERE (customers.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT (suppliers.id)::text AS id,
            'suppliers'::text AS text,
            COALESCE(NULLIF(btrim(suppliers.business_name), ''::text), NULLIF(btrim(suppliers.full_name), ''::text), NULLIF(btrim(suppliers.system_code), ''::text), 'بدون عنوان'::text) AS "coalesce"
           FROM public.suppliers
          WHERE (suppliers.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT (profiles.id)::text AS id,
            'profiles'::text AS text,
            COALESCE(NULLIF(btrim(profiles.full_name), ''::text), NULLIF(btrim(concat_ws(' '::text, profiles.first_name, profiles.last_name)), ''::text), 'بدون عنوان'::text) AS "coalesce"
           FROM public.profiles
          WHERE (profiles.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT (employees.id)::text AS id,
            'employees'::text AS text,
            COALESCE(NULLIF(btrim(concat_ws(' '::text, employees.first_name, employees.last_name)), ''::text), NULLIF(btrim(employees.system_code), ''::text), 'بدون عنوان'::text) AS "coalesce"
           FROM public.employees
          WHERE (employees.org_id = ( SELECT public.current_org_id() AS current_org_id))
        ), source_rows AS (
         SELECT ('op_'::text || (op.id)::text) AS row_key,
            'cash_bank_operation'::text AS kind,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN 'transfer'::text
                    WHEN (op.operation_type = 'payment'::text) THEN 'payment'::text
                    ELSE 'receipt'::text
                END AS row_type,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN 'انتقال مستقیم نقد و بانک'::text
                    ELSE 'ثبت مستقیم نقد و بانک'::text
                END AS source_label,
            (op.id)::text AS source_record_id,
            COALESCE(op.payment_type, ''::text) AS payment_type,
            COALESCE(op.status, ''::text) AS status,
            op.operation_date AS row_date,
            COALESCE(op.amount, (0)::numeric) AS amount,
            '-'::text AS invoice_label,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN '-'::text
                    ELSE COALESCE(party.label, '-'::text)
                END AS person_label,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN concat_ws(' ← '::text, NULLIF(pay_account.label, ''::text), NULLIF(receive_account.label, ''::text))
                    ELSE COALESCE(account.label, '-'::text)
                END AS bank_label,
            COALESCE(NULLIF(concat_ws(' '::text, cheque.serial_no,
                CASE
                    WHEN (cheque.sayad_id IS NOT NULL) THEN (('('::text || cheque.sayad_id) || ')'::text)
                    ELSE NULL::text
                END), ''::text), '-'::text) AS cheque_label,
            COALESCE(op.description, ''::text) AS description,
            op.created_at,
            NULL::text AS invoice_module_id,
            NULL::text AS invoice_record_id,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN NULL::text
                    ELSE party.module_id
                END AS person_module_id,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN NULL::text
                    ELSE party.id
                END AS person_record_id,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN NULL::text
                    ELSE account.module_id
                END AS bank_module_id,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN NULL::text
                    ELSE account.id
                END AS bank_record_id,
                CASE
                    WHEN (op.operation_type = 'transfer'::text) THEN COALESCE(( SELECT jsonb_agg(relation_values.item) AS jsonb_agg
                       FROM ( VALUES (
                                    CASE
WHEN (pay_account.id IS NOT NULL) THEN jsonb_build_object('moduleId', pay_account.module_id, 'recordId', pay_account.id, 'label', pay_account.label)
ELSE NULL::jsonb
                                    END), (
                                    CASE
WHEN (receive_account.id IS NOT NULL) THEN jsonb_build_object('moduleId', receive_account.module_id, 'recordId', receive_account.id, 'label', receive_account.label)
ELSE NULL::jsonb
                                    END)) relation_values(item)
                      WHERE (relation_values.item IS NOT NULL)), '[]'::jsonb)
                    ELSE '[]'::jsonb
                END AS bank_relations,
                CASE
                    WHEN (cheque.id IS NOT NULL) THEN (cheque.id)::text
                    ELSE NULL::text
                END AS cheque_record_id
           FROM (((((public.cash_bank_operations op
             LEFT JOIN party_directory party ON (((((op.customer_id)::text = party.id) AND (party.module_id = 'customers'::text)) OR (((op.supplier_id)::text = party.id) AND (party.module_id = 'suppliers'::text)) OR (((op.employee_id)::text = party.id) AND (party.module_id = 'profiles'::text)))))
             LEFT JOIN account_directory account ON ((account.id = (COALESCE(op.bank_account_id, op.cash_box_id, op.petty_fund_id))::text)))
             LEFT JOIN account_directory pay_account ON ((pay_account.id = (COALESCE(op.payment_bank_account_id, op.payment_cash_box_id, op.payment_petty_fund_id))::text)))
             LEFT JOIN account_directory receive_account ON ((receive_account.id = (COALESCE(op.receipt_bank_account_id, op.receipt_cash_box_id, op.receipt_petty_fund_id))::text)))
             LEFT JOIN public.cheques cheque ON (((cheque.id = op.cheque_id) AND (cheque.org_id = ( SELECT public.current_org_id() AS current_org_id)))))
          WHERE ((op.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (COALESCE((op.metadata ->> 'is_auto_generated'::text), 'false'::text) <> 'true'::text) AND (op.sales_invoice_id IS NULL) AND (op.purchase_invoice_id IS NULL) AND (op.expense_document_id IS NULL) AND (op.employee_advance_id IS NULL) AND (op.payroll_slip_id IS NULL))
        UNION ALL
         SELECT ((('sales_'::text || (invoice.id)::text) || '_'::text) || (payment.ordinality)::text),
            'sales_payment'::text,
            'receipt'::text,
            'دریافت فاکتور فروش'::text,
            (invoice.id)::text AS id,
            COALESCE((payment.item ->> 'payment_type'::text), ''::text) AS "coalesce",
            COALESCE((payment.item ->> 'status'::text), ''::text) AS "coalesce",
            COALESCE((NULLIF((payment.item ->> 'date'::text), ''::text))::date, invoice.invoice_date) AS "coalesce",
                CASE
                    WHEN (COALESCE((payment.item ->> 'amount'::text), ''::text) ~ '^-?[0-9]+(\.[0-9]+)?$'::text) THEN ((payment.item ->> 'amount'::text))::numeric
                    ELSE (0)::numeric
                END AS "case",
            COALESCE(NULLIF(btrim(invoice.name), ''::text), NULLIF(btrim(invoice.system_code), ''::text), '-'::text) AS "coalesce",
            COALESCE(customer.label, '-'::text) AS "coalesce",
            COALESCE(account.label, '-'::text) AS "coalesce",
            COALESCE(cheque_label.label, '-'::text) AS "coalesce",
            COALESCE((payment.item ->> 'description'::text), ''::text) AS "coalesce",
            invoice.created_at,
            'invoices'::text,
            (invoice.id)::text AS id,
            'customers'::text,
            (invoice.customer_id)::text AS customer_id,
            account.module_id,
            account.id,
            '[]'::jsonb AS jsonb,
            NULLIF((payment.item ->> 'cheque_id'::text), ''::text) AS "nullif"
           FROM ((((public.invoices invoice
             CROSS JOIN LATERAL jsonb_array_elements(COALESCE(invoice.payments, '[]'::jsonb)) WITH ORDINALITY payment(item, ordinality))
             LEFT JOIN party_directory customer ON (((customer.id = (invoice.customer_id)::text) AND (customer.module_id = 'customers'::text))))
             LEFT JOIN account_directory account ON ((account.id = NULLIF((payment.item ->> 'target_account'::text), ''::text))))
             LEFT JOIN LATERAL ( SELECT COALESCE(NULLIF(concat_ws(' '::text, c.serial_no,
                        CASE
                            WHEN (c.sayad_id IS NOT NULL) THEN (('('::text || c.sayad_id) || ')'::text)
                            ELSE NULL::text
                        END), ''::text), '-'::text) AS label
                   FROM public.cheques c
                  WHERE ((c.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND ((c.id)::text = NULLIF((payment.item ->> 'cheque_id'::text), ''::text)))
                 LIMIT 1) cheque_label ON (true))
          WHERE (invoice.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT ((('purchase_'::text || (invoice.id)::text) || '_'::text) || (payment.ordinality)::text),
            'purchase_payment'::text,
            'payment'::text,
            'پرداخت فاکتور خرید'::text,
            (invoice.id)::text AS id,
            COALESCE((payment.item ->> 'payment_type'::text), ''::text) AS "coalesce",
            COALESCE((payment.item ->> 'status'::text), ''::text) AS "coalesce",
            COALESCE((NULLIF((payment.item ->> 'date'::text), ''::text))::date, invoice.invoice_date) AS "coalesce",
                CASE
                    WHEN (COALESCE((payment.item ->> 'amount'::text), ''::text) ~ '^-?[0-9]+(\.[0-9]+)?$'::text) THEN ((payment.item ->> 'amount'::text))::numeric
                    ELSE (0)::numeric
                END AS "case",
            COALESCE(NULLIF(btrim(invoice.name), ''::text), NULLIF(btrim(invoice.system_code), ''::text), '-'::text) AS "coalesce",
            COALESCE(supplier.label, '-'::text) AS "coalesce",
            COALESCE(account.label, '-'::text) AS "coalesce",
            COALESCE(cheque_label.label, '-'::text) AS "coalesce",
            COALESCE((payment.item ->> 'description'::text), ''::text) AS "coalesce",
            invoice.created_at,
            'purchase_invoices'::text,
            (invoice.id)::text AS id,
            'suppliers'::text,
            (invoice.supplier_id)::text AS supplier_id,
            account.module_id,
            account.id,
            '[]'::jsonb AS jsonb,
            NULLIF((payment.item ->> 'cheque_id'::text), ''::text) AS "nullif"
           FROM ((((public.purchase_invoices invoice
             CROSS JOIN LATERAL jsonb_array_elements(COALESCE(invoice.payments, '[]'::jsonb)) WITH ORDINALITY payment(item, ordinality))
             LEFT JOIN party_directory supplier ON (((supplier.id = (invoice.supplier_id)::text) AND (supplier.module_id = 'suppliers'::text))))
             LEFT JOIN account_directory account ON ((account.id = NULLIF((payment.item ->> 'source_account'::text), ''::text))))
             LEFT JOIN LATERAL ( SELECT COALESCE(NULLIF(concat_ws(' '::text, c.serial_no,
                        CASE
                            WHEN (c.sayad_id IS NOT NULL) THEN (('('::text || c.sayad_id) || ')'::text)
                            ELSE NULL::text
                        END), ''::text), '-'::text) AS label
                   FROM public.cheques c
                  WHERE ((c.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND ((c.id)::text = NULLIF((payment.item ->> 'cheque_id'::text), ''::text)))
                 LIMIT 1) cheque_label ON (true))
          WHERE (invoice.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT ('cheque_'::text || (cheque.id)::text),
            'cheque'::text,
            'cheque'::text,
                CASE
                    WHEN (cheque.cheque_type = 'issued'::text) THEN 'چک پرداختی'::text
                    ELSE 'چک دریافتی'::text
                END AS "case",
            (cheque.id)::text AS id,
            'cheque'::text,
            COALESCE(cheque.status, ''::text) AS "coalesce",
            COALESCE(cheque.due_date, cheque.issue_date) AS "coalesce",
            COALESCE(cheque.amount, (0)::numeric) AS "coalesce",
            '-'::text,
            COALESCE(party.label, '-'::text) AS "coalesce",
            COALESCE(account.label, '-'::text) AS "coalesce",
            COALESCE(NULLIF(concat_ws(' '::text, cheque.serial_no,
                CASE
                    WHEN (cheque.sayad_id IS NOT NULL) THEN (('('::text || cheque.sayad_id) || ')'::text)
                    ELSE NULL::text
                END), ''::text), '-'::text) AS "coalesce",
            COALESCE(cheque.notes, ''::text) AS "coalesce",
            cheque.created_at,
            NULL::text,
            NULL::text,
            party.module_id,
            party.id,
            account.module_id,
            account.id,
            '[]'::jsonb AS jsonb,
            (cheque.id)::text AS id
           FROM ((public.cheques cheque
             LEFT JOIN party_directory party ON (((party.id = (cheque.party_id)::text) AND (party.module_id =
                CASE cheque.party_type
                    WHEN 'customer'::text THEN 'customers'::text
                    WHEN 'supplier'::text THEN 'suppliers'::text
                    ELSE 'profiles'::text
                END))))
             LEFT JOIN account_directory account ON ((account.id = (cheque.bank_account_id)::text)))
          WHERE (cheque.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT ('barter_'::text || (barter.id)::text),
            'barter'::text,
            'barter'::text,
                CASE
                    WHEN (barter.barter_type = 'outgoing'::text) THEN 'تهاتر پرداختی'::text
                    ELSE 'تهاتر دریافتی'::text
                END AS "case",
            (barter.id)::text AS id,
            'barter'::text,
            COALESCE(barter.status, ''::text) AS "coalesce",
            barter.barter_date,
            COALESCE(barter.remaining_amount, (0)::numeric) AS "coalesce",
            COALESCE(NULLIF(btrim(sales.name), ''::text), NULLIF(btrim(sales.system_code), ''::text), NULLIF(btrim(purchase.name), ''::text), NULLIF(btrim(purchase.system_code), ''::text), '-'::text) AS "coalesce",
            COALESCE(customer.label, supplier.label, employee.label, '-'::text) AS "coalesce",
            '-'::text,
            '-'::text,
            COALESCE(barter.notes, ''::text) AS "coalesce",
            barter.created_at,
                CASE
                    WHEN (barter.source_invoice_id IS NOT NULL) THEN 'invoices'::text
                    WHEN (barter.source_purchase_invoice_id IS NOT NULL) THEN 'purchase_invoices'::text
                    ELSE NULL::text
                END AS "case",
            (COALESCE(barter.source_invoice_id, barter.source_purchase_invoice_id))::text AS "coalesce",
            COALESCE(customer.module_id, supplier.module_id, employee.module_id) AS "coalesce",
            COALESCE(customer.id, supplier.id, employee.id) AS "coalesce",
            NULL::text,
            NULL::text,
            '[]'::jsonb AS jsonb,
            NULL::text
           FROM (((((public.barters barter
             LEFT JOIN public.invoices sales ON (((sales.id = barter.source_invoice_id) AND (sales.org_id = ( SELECT public.current_org_id() AS current_org_id)))))
             LEFT JOIN public.purchase_invoices purchase ON (((purchase.id = barter.source_purchase_invoice_id) AND (purchase.org_id = ( SELECT public.current_org_id() AS current_org_id)))))
             LEFT JOIN party_directory customer ON (((customer.id = (barter.customer_id)::text) AND (customer.module_id = 'customers'::text))))
             LEFT JOIN party_directory supplier ON (((supplier.id = (barter.supplier_id)::text) AND (supplier.module_id = 'suppliers'::text))))
             LEFT JOIN party_directory employee ON (((employee.id = (barter.employee_id)::text) AND (employee.module_id = 'profiles'::text))))
          WHERE (barter.org_id = ( SELECT public.current_org_id() AS current_org_id))
        UNION ALL
         SELECT ('opening_bank_'::text || (account.id)::text),
            'bank_account_opening'::text,
            'opening'::text,
            'مانده اول دوره حساب بانکی'::text,
            (account.id)::text AS id,
            ''::text AS text,
            'opening'::text AS text,
            (account.created_at)::date AS created_at,
            abs(COALESCE(account.opening_balance, (0)::numeric)) AS abs,
            '-'::text AS text,
            '-'::text AS text,
            COALESCE(directory.label, '-'::text) AS "coalesce",
            '-'::text AS text,
            'مانده اول دوره حساب بانکی'::text AS text,
            account.created_at,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text,
            'bank_accounts'::text,
            (account.id)::text AS id,
            '[]'::jsonb AS jsonb,
            NULL::text
           FROM (public.bank_accounts account
             LEFT JOIN account_directory directory ON (((directory.id = (account.id)::text) AND (directory.module_id = 'bank_accounts'::text))))
          WHERE ((account.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (COALESCE(account.opening_balance, (0)::numeric) <> (0)::numeric))
        UNION ALL
         SELECT ('opening_cash_'::text || (account.id)::text),
            'cash_box_opening'::text,
            'opening'::text,
            'مانده اول دوره صندوق'::text,
            (account.id)::text AS id,
            ''::text AS text,
            'opening'::text AS text,
            (account.created_at)::date AS created_at,
            abs(COALESCE(account.opening_balance, (0)::numeric)) AS abs,
            '-'::text AS text,
            '-'::text AS text,
            COALESCE(directory.label, '-'::text) AS "coalesce",
            '-'::text AS text,
            'مانده اول دوره صندوق'::text AS text,
            account.created_at,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text,
            'cash_boxes'::text,
            (account.id)::text AS id,
            '[]'::jsonb AS jsonb,
            NULL::text
           FROM (public.cash_boxes account
             LEFT JOIN account_directory directory ON (((directory.id = (account.id)::text) AND (directory.module_id = 'cash_boxes'::text))))
          WHERE ((account.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (COALESCE(account.opening_balance, (0)::numeric) <> (0)::numeric))
        UNION ALL
         SELECT ('opening_petty_'::text || (account.id)::text),
            'petty_fund_opening'::text,
            'opening'::text,
            'مانده اول دوره تنخواه'::text,
            (account.id)::text AS id,
            ''::text AS text,
            'opening'::text AS text,
            (account.created_at)::date AS created_at,
            abs(COALESCE(account.opening_balance, (0)::numeric)) AS abs,
            '-'::text AS text,
            '-'::text AS text,
            COALESCE(directory.label, '-'::text) AS "coalesce",
            '-'::text AS text,
            'مانده اول دوره تنخواه'::text AS text,
            account.created_at,
            NULL::text,
            NULL::text,
            NULL::text,
            NULL::text,
            'petty_funds'::text,
            (account.id)::text AS id,
            '[]'::jsonb AS jsonb,
            NULL::text
           FROM (public.petty_funds account
             LEFT JOIN account_directory directory ON (((directory.id = (account.id)::text) AND (directory.module_id = 'petty_funds'::text))))
          WHERE ((account.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (COALESCE(account.opening_balance, (0)::numeric) <> (0)::numeric))
        UNION ALL
         SELECT ('opening_customer_'::text || (party.id)::text),
            'customer_opening'::text,
            'opening'::text,
            'مانده اول دوره مشتری'::text,
            (party.id)::text AS id,
            ''::text AS text,
            'opening'::text AS text,
            (party.created_at)::date AS created_at,
            abs(COALESCE(party.previous_system_balance_total, (0)::numeric)) AS abs,
            '-'::text AS text,
            COALESCE(directory.label, '-'::text) AS "coalesce",
            '-'::text AS text,
            '-'::text AS text,
                CASE
                    WHEN (party.previous_system_balance_total >= (0)::numeric) THEN 'مانده اول دوره مشتری: طلب از مشتری'::text
                    ELSE 'مانده اول دوره مشتری: بدهی به مشتری'::text
                END AS "case",
            party.created_at,
            NULL::text,
            NULL::text,
            'customers'::text,
            (party.id)::text AS id,
            NULL::text,
            NULL::text,
            '[]'::jsonb AS jsonb,
            NULL::text
           FROM (public.customers party
             LEFT JOIN party_directory directory ON (((directory.id = (party.id)::text) AND (directory.module_id = 'customers'::text))))
          WHERE ((party.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (COALESCE(party.previous_system_balance_total, (0)::numeric) <> (0)::numeric))
        UNION ALL
         SELECT ('opening_supplier_'::text || (party.id)::text),
            'supplier_opening'::text,
            'opening'::text,
            'مانده اول دوره تأمین‌کننده'::text,
            (party.id)::text AS id,
            ''::text AS text,
            'opening'::text AS text,
            (party.created_at)::date AS created_at,
            abs(COALESCE(party.previous_system_balance_total, (0)::numeric)) AS abs,
            '-'::text AS text,
            COALESCE(directory.label, '-'::text) AS "coalesce",
            '-'::text AS text,
            '-'::text AS text,
                CASE
                    WHEN (party.previous_system_balance_total >= (0)::numeric) THEN 'مانده اول دوره تأمین‌کننده: بدهی به تأمین‌کننده'::text
                    ELSE 'مانده اول دوره تأمین‌کننده: طلب از تأمین‌کننده'::text
                END AS "case",
            party.created_at,
            NULL::text,
            NULL::text,
            'suppliers'::text,
            (party.id)::text AS id,
            NULL::text,
            NULL::text,
            '[]'::jsonb AS jsonb,
            NULL::text
           FROM (public.suppliers party
             LEFT JOIN party_directory directory ON (((directory.id = (party.id)::text) AND (directory.module_id = 'suppliers'::text))))
          WHERE ((party.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (COALESCE(party.previous_system_balance_total, (0)::numeric) <> (0)::numeric))
        UNION ALL
         SELECT ('opening_employee_'::text || (party.id)::text),
            'employee_opening'::text,
            'opening'::text,
            'مانده اول دوره کارمند'::text,
            (party.id)::text AS id,
            ''::text AS text,
            'opening'::text AS text,
            (party.created_at)::date AS created_at,
            abs(COALESCE(party.previous_system_balance_total, (0)::numeric)) AS abs,
            '-'::text AS text,
            COALESCE(directory.label, '-'::text) AS "coalesce",
            '-'::text AS text,
            '-'::text AS text,
                CASE
                    WHEN (party.previous_system_balance_total >= (0)::numeric) THEN 'مانده اول دوره کارمند: بدهی به کارمند'::text
                    ELSE 'مانده اول دوره کارمند: طلب از کارمند'::text
                END AS "case",
            party.created_at,
            NULL::text,
            NULL::text,
            'employees'::text,
            (party.id)::text AS id,
            NULL::text,
            NULL::text,
            '[]'::jsonb AS jsonb,
            NULL::text
           FROM (public.employees party
             LEFT JOIN party_directory directory ON (((directory.id = (party.id)::text) AND (directory.module_id = 'employees'::text))))
          WHERE ((party.org_id = ( SELECT public.current_org_id() AS current_org_id)) AND (COALESCE(party.previous_system_balance_total, (0)::numeric) <> (0)::numeric))
        )
 SELECT source_rows.row_key,
    source_rows.kind,
    source_rows.row_type,
    source_rows.source_label,
    source_rows.source_record_id,
    source_rows.payment_type,
    source_rows.status,
    source_rows.row_date,
    source_rows.amount,
    source_rows.invoice_label,
    source_rows.person_label,
    source_rows.bank_label,
    source_rows.cheque_label,
    source_rows.description,
    source_rows.created_at,
    source_rows.invoice_module_id,
    source_rows.invoice_record_id,
    source_rows.person_module_id,
    source_rows.person_record_id,
    source_rows.bank_module_id,
    source_rows.bank_record_id,
    source_rows.bank_relations,
    source_rows.cheque_record_id
   FROM source_rows
  WHERE (( SELECT public.current_org_id() AS current_org_id) IS NOT NULL);


--
-- Name: cash_bank_unified_ledger_filtered(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cash_bank_unified_ledger_filtered(p_filters jsonb DEFAULT '{}'::jsonb) RETURNS SETOF public.cash_bank_unified_ledger
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select row_item.* from public.cash_bank_unified_ledger row_item
  where public.current_org_id() is not null and
(jsonb_array_length(coalesce(coalesce(p_filters, '{}'::jsonb)->'row_types', '[]'::jsonb)) = 0 or row_item.row_type in (select jsonb_array_elements_text(coalesce(p_filters, '{}'::jsonb)->'row_types')))
        and (jsonb_array_length(coalesce(coalesce(p_filters, '{}'::jsonb)->'payment_types', '[]'::jsonb)) = 0 or row_item.payment_type in (select jsonb_array_elements_text(coalesce(p_filters, '{}'::jsonb)->'payment_types')))
        and (jsonb_array_length(coalesce(coalesce(p_filters, '{}'::jsonb)->'statuses', '[]'::jsonb)) = 0 or row_item.status in (select jsonb_array_elements_text(coalesce(p_filters, '{}'::jsonb)->'statuses')))
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'source_query', '') is null or lower(row_item.source_label) like '%' || lower(coalesce(p_filters, '{}'::jsonb)->>'source_query') || '%')
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'invoice_query', '') is null or lower(row_item.invoice_label) like '%' || lower(coalesce(p_filters, '{}'::jsonb)->>'invoice_query') || '%')
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'person_query', '') is null or lower(row_item.person_label) like '%' || lower(coalesce(p_filters, '{}'::jsonb)->>'person_query') || '%')
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'bank_query', '') is null or lower(row_item.bank_label) like '%' || lower(coalesce(p_filters, '{}'::jsonb)->>'bank_query') || '%')
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'cheque_query', '') is null or lower(row_item.cheque_label) like '%' || lower(coalesce(p_filters, '{}'::jsonb)->>'cheque_query') || '%')
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'description_query', '') is null or lower(row_item.description) like '%' || lower(coalesce(p_filters, '{}'::jsonb)->>'description_query') || '%')
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'date_from', '') is null or row_item.row_date >= (coalesce(p_filters, '{}'::jsonb)->>'date_from')::date)
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'date_to', '') is null or row_item.row_date <= (coalesce(p_filters, '{}'::jsonb)->>'date_to')::date)
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'amount_from', '') is null or row_item.amount >= (coalesce(p_filters, '{}'::jsonb)->>'amount_from')::numeric)
        and (nullif(coalesce(p_filters, '{}'::jsonb)->>'amount_to', '') is null or row_item.amount <= (coalesce(p_filters, '{}'::jsonb)->>'amount_to')::numeric)
$$;


--
-- Name: charge_org_sms_wallet_usage(uuid, numeric, numeric, numeric, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.charge_org_sms_wallet_usage(p_org_id uuid, p_provider_before numeric, p_provider_after numeric, p_margin_percent numeric DEFAULT 30, p_message_count integer DEFAULT 1, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_raw numeric:=greatest(0,coalesce(p_provider_before,0)-coalesce(p_provider_after,0)); v_charge numeric:=round(v_raw*(1+greatest(0,coalesce(p_margin_percent,30))/100),2); w public.org_sms_wallets%rowtype; from_included numeric; from_balance numeric;
begin
 if p_org_id is null or v_raw<=0 then return jsonb_build_object('success',true,'raw_cost_irt',v_raw,'charged_irt',0); end if;
 if public.org_is_saas_admin(p_org_id) then return jsonb_build_object('success',true,'raw_cost_irt',v_raw,'charged_irt',0,'skipped','saas_admin_provider_account'); end if;
 insert into public.org_sms_wallets(org_id,status) values(p_org_id,'active') on conflict(org_id) do nothing;
 select * into w from public.org_sms_wallets where org_id=p_org_id for update;
 if w.status<>'active' then raise exception 'sms_wallet_blocked'; end if;
 from_included:=least(w.included_quota_irt,v_charge); from_balance:=v_charge-from_included;
 if w.included_quota_irt+w.balance_irt-w.reserved_irt<v_charge then raise exception 'sms_wallet_insufficient'; end if;
 update public.org_sms_wallets set included_quota_irt=included_quota_irt-from_included,balance_irt=balance_irt-from_balance,updated_at=now() where org_id=p_org_id returning * into w;
 insert into public.org_sms_wallet_transactions(org_id,kind,amount_irt,balance_after_irt,description,metadata) values(p_org_id,'usage',-v_charge,w.balance_irt,'هزینهٔ مصرف پیامک',w.metadata||coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('message_count',p_message_count,'raw_cost_irt',v_raw,'margin_percent',p_margin_percent,'provider_before',p_provider_before,'provider_after',p_provider_after,'charged_irt',v_charge));
 return jsonb_build_object('success',true,'raw_cost_irt',v_raw,'charged_irt',v_charge,'balance_irt',w.balance_irt,'included_quota_irt',w.included_quota_irt);
end; $$;


--
-- Name: check_phone_login_candidate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_phone_login_candidate(p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  normalized_phone text;
  profile_count integer := 0;
  active_profile_count integer := 0;
  auth_count integer := 0;
  phone_identity_count integer := 0;
  single_profile record;
begin
  normalized_phone := public.normalize_iran_mobile_e164(p_phone);

  if normalized_phone is null then
    return jsonb_build_object(
      'normalized_phone', null,
      'exists_in_profiles', false,
      'exists_in_auth', false,
      'has_phone_identity', false,
      'is_active', false,
      'matched_profile_count', 0,
      'active_profile_count', 0,
      'org_id', null,
      'role_id', null,
      'role', null
    );
  end if;

  with matched_profiles as (
    select distinct on (p.id)
      p.id,
      p.org_id,
      p.role_id,
      p.role,
      exists(select 1 from public.user_organization_memberships m join public.organizations o on o.id=m.org_id and o.is_active where m.user_id=p.id and m.is_active) as is_active
    from public.profiles p
    left join auth.users u on u.id = p.id
    where
      public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) = normalized_phone
      or (
        public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) is null
        and public.normalize_iran_mobile_e164(u.phone) = normalized_phone
      )
    order by p.id, p.created_at asc nulls last
  )
  select
    count(*),
    count(*) filter (where is_active)
  into profile_count, active_profile_count
  from matched_profiles;

  if profile_count = 1 then
    with matched_profiles as (
      select distinct on (p.id)
        p.id, p.org_id, p.role_id, p.role,
        exists(select 1 from public.user_organization_memberships m join public.organizations o on o.id=m.org_id and o.is_active where m.user_id=p.id and m.is_active) as is_active
      from public.profiles p
      left join auth.users u on u.id = p.id
      where
        public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) = normalized_phone
        or (
          public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) is null
          and public.normalize_iran_mobile_e164(u.phone) = normalized_phone
        )
      order by p.id, p.created_at asc nulls last
    )
    select * into single_profile from matched_profiles limit 1;
  end if;

  with matched_profiles as (
    select p.id
    from public.profiles p
    left join auth.users u on u.id = p.id
    where
      public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) = normalized_phone
      or (
        public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) is null
        and public.normalize_iran_mobile_e164(u.phone) = normalized_phone
      )
  )
  select count(*)
  into auth_count
  from auth.users u
  where public.normalize_iran_mobile_e164(u.phone) = normalized_phone
    and exists (select 1 from matched_profiles mp where mp.id = u.id);

  with matched_profiles as (
    select p.id
    from public.profiles p
    left join auth.users u on u.id = p.id
    where
      public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) = normalized_phone
      or (
        public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) is null
        and public.normalize_iran_mobile_e164(u.phone) = normalized_phone
      )
  )
  select count(*)
  into phone_identity_count
  from auth.users u
  where public.normalize_iran_mobile_e164(u.phone) = normalized_phone
    and u.phone_confirmed_at is not null
    and exists (select 1 from matched_profiles mp where mp.id = u.id)
    and (
      exists (
        select 1 from auth.identities i
        where i.user_id = u.id and i.provider = 'phone'
          and (
            public.normalize_iran_mobile_e164(i.identity_data ->> 'phone') = normalized_phone
            or coalesce((i.identity_data ->> 'phone_verified')::boolean, false) = true
          )
      )
      or public.normalize_iran_mobile_e164(u.phone) = normalized_phone
    );

  return jsonb_build_object(
    'normalized_phone', normalized_phone,
    'exists_in_profiles', profile_count > 0,
    'exists_in_auth', auth_count > 0,
    'has_phone_identity', phone_identity_count > 0,
    'is_active', active_profile_count > 0,
    'matched_profile_count', profile_count,
    'active_profile_count', active_profile_count,
    'org_id', null,
    'role_id', null,
    'role', null
  );

exception when others then
  -- خطای داخلی → JSON ایمن به‌جای 500.
  -- این باعث می‌شود lookupPhoneLoginCandidate در phoneAuth.ts
  -- مقدار null برنگرداند و login flow بلوک نشود.
  -- مقادیر false باعث می‌شوند کاربر به صورت "ناشناخته" دیده شود؛
  -- login واقعی از طریق OTP توسط Supabase Auth کنترل می‌شود.
  return jsonb_build_object(
    'normalized_phone', normalized_phone,
    'exists_in_profiles', false,
    'exists_in_auth', false,
    'has_phone_identity', false,
    'is_active', false,
    'matched_profile_count', 0,
    'active_profile_count', 0,
    'org_id', null,
    'role_id', null,
    'role', null,
    '_lookup_error', true
  );
end;
$$;


--
-- Name: check_saas_slug_availability(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_saas_slug_availability(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  normalized_slug text := public.normalize_saas_slug(p_slug);
  exists_conflict boolean;
begin
  if normalized_slug is null or length(normalized_slug) < 3 then
    return jsonb_build_object(
      'available', false,
      'normalized_slug', normalized_slug,
      'reason', 'invalid_slug'
    );
  end if;

  select exists (
    select 1
    from public.saas_org_settings
    where lower(slug) = lower(normalized_slug)
    union all
    select 1
    from public.organizations
    where lower(coalesce(slug, '')) = lower(normalized_slug)
    limit 1
  )
  into exists_conflict;

  return jsonb_build_object(
    'available', not exists_conflict,
    'normalized_slug', normalized_slug,
    'reason', case when exists_conflict then 'slug_taken' else null end
  );
end
$$;


