    locked_at timestamp with time zone,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_image_generation_jobs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT ai_image_generation_jobs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'completed'::text, 'failed'::text])))
);


--
-- Name: claim_ai_image_generation_job(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_ai_image_generation_job(p_lease_seconds integer DEFAULT 900) RETURNS SETOF public.ai_image_generation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_job public.ai_image_generation_jobs;
  v_lease integer := least(greatest(coalesce(p_lease_seconds, 900), 300), 1800);
  v_max_attempts constant integer := 12;
begin
  -- هیچ job ای در حالت running رها نمی‌شود: lease منقضی‌شده یا دوباره صف
  -- می‌شود یا، پس از سقف منطقی تلاش‌ها، نتیجهٔ نهایی failed می‌گیرد.
  update public.ai_image_generation_jobs
  set
    status = 'failed',
    completed_at = now(),
    locked_at = null,
    updated_at = now(),
    last_error = coalesce(last_error, 'پردازش تصویر پس از چند تلاش کامل نشد.')
  where attempts >= v_max_attempts
    and (
      status = 'pending'
      or (status = 'running' and locked_at < now() - make_interval(secs => v_lease))
    );

  update public.ai_image_generation_jobs
  set
    status = 'pending',
    available_at = now(),
    locked_at = null,
    updated_at = now(),
    last_error = coalesce(last_error, 'اجرای قبلی worker پیش از تکمیل متوقف شد.')
  where status = 'running'
    and locked_at < now() - make_interval(secs => v_lease)
    and attempts < v_max_attempts;

  select * into v_job
  from public.ai_image_generation_jobs
  where status = 'pending'
    and available_at <= now()
    and attempts < v_max_attempts
  order by available_at asc, created_at asc
  for update skip locked
  limit 1;

  if not found then
    return;
  end if;

  update public.ai_image_generation_jobs
  set
    status = 'running',
    attempts = attempts + 1,
    locked_at = now(),
    started_at = coalesce(started_at, now()),
    updated_at = now()
  where id = v_job.id
  returning * into v_job;

  return next v_job;
end;
$$;


