    CONSTRAINT workflow_interval_jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 10))),
    CONSTRAINT workflow_interval_jobs_page_offset_check CHECK ((page_offset >= 0)),
