  return v_rows > 0;
end;
$$;


--
-- Name: cleanup_orphan_record_locks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_orphan_record_locks() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_lock record;
  v_table_name text;
  v_table_regclass regclass;
  v_target_exists boolean;
  v_deleted_count integer := 0;
begin
  for v_lock in
    select id, org_id, module_id, record_id, metadata
    from public.record_locks
  loop
    v_table_name := coalesce(
      nullif(btrim(coalesce(v_lock.metadata ->> 'table_name', '')), ''),
      nullif(btrim(coalesce(public.resolve_record_lock_table_name(v_lock.module_id), '')), '')
    );
    select to_regclass(format('public.%I', v_table_name)) into v_table_regclass;

    if v_table_regclass is null then
      delete from public.record_locks where id = v_lock.id;
      v_deleted_count := v_deleted_count + 1;
      continue;
    end if;

    begin
      execute format(
        'select exists (select 1 from public.%I where id = $1 and org_id = $2)',
        v_table_name
      ) into v_target_exists using v_lock.record_id, v_lock.org_id;
    exception
      when undefined_column then
        execute format('select exists (select 1 from public.%I where id = $1)', v_table_name)
          into v_target_exists using v_lock.record_id;
    end;

    if not coalesce(v_target_exists, false) then
      delete from public.record_locks where id = v_lock.id;
      v_deleted_count := v_deleted_count + 1;
    end if;
  end loop;

  return v_deleted_count;
end;
$_$;


--
-- Name: cleanup_stale_invoice_payment_allocations(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_stale_invoice_payment_allocations(p_module_id text, p_source_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_table_name text;
  v_pending_invoice_ids uuid[] := array[p_source_invoice_id];
  v_affected_invoice_ids uuid[] := '{}'::uuid[];
  v_active_row_keys text[];
  v_current_invoice_id uuid;
  v_target_invoice_id uuid;
  v_pending_index integer := 1;
  v_removed_rows integer := 0;
  v_canceled_operations integer := 0;
  v_updated_count integer := 0;
begin
  if v_org_id is null then
    raise exception 'سازمان فعال مشخص نیست.';
  end if;
  if p_module_id not in ('invoices', 'purchase_invoices') or p_source_invoice_id is null then
    raise exception 'اطلاعات فاکتور برای پاک‌سازی تخصیص معتبر نیست.';
  end if;

  v_table_name := p_module_id;

  -- هر ردیفی که دیگر در فاکتور فعلی نیست یا وضعیت نهایی ندارد، نباید
  -- عملیات نقد و بانک فعال داشته باشد. این حالت حذف مستقیم یک ردیف مقصد را هم پوشش می‌دهد.
  while v_pending_index <= coalesce(array_length(v_pending_invoice_ids, 1), 0) loop
    v_current_invoice_id := v_pending_invoice_ids[v_pending_index];
    v_pending_index := v_pending_index + 1;

    execute format($sql$
      select coalesce(array_agg(distinct candidate.row_key), '{}'::text[])
      from public.%I invoice
      cross join lateral jsonb_array_elements(coalesce(invoice.payments, '[]'::jsonb)) with ordinality as payment(item, ordinality)
      cross join lateral unnest(array[
        nullif(trim(payment.item->>'row_key'), ''),
        nullif(trim(payment.item->>'_cash_bank_operation_id'), ''),
        nullif(trim(payment.item->>'_barter_allocation_key'), ''),
        case
          when nullif(trim(payment.item->>'key'), '') is not null
            then 'key_' || trim(payment.item->>'key')
          else null
        end,
        'legacy_' || (payment.ordinality - 1)::text
      ]) as candidate(row_key)
      where invoice.id = $1
        and invoice.org_id = $2
        and candidate.row_key is not null
        and (
          not (payment.item ? 'status')
          or nullif(trim(payment.item->>'status'), '') is null
          or lower(trim(payment.item->>'status')) in ('received', 'paid', 'approved', 'cleared')
        )
    $sql$, v_table_name) into v_active_row_keys using v_current_invoice_id, v_org_id;
    v_active_row_keys := coalesce(v_active_row_keys, '{}'::text[]);

    execute format($sql$
      update public.cash_bank_operations operation
      set status = 'canceled', updated_at = now()
      where operation.org_id = $1
        and coalesce(operation.status, '') <> 'canceled'
        and operation.metadata->>'is_auto_generated' = 'true'
        and operation.metadata->>'source_table' = $2
        and operation.metadata->>'source_record_id' = $3::text
        and nullif(trim(operation.metadata->>'source_row_key'), '') is not null
        and not (operation.metadata->>'source_row_key' = any($4))
    $sql$, v_table_name) using v_org_id, p_module_id, v_current_invoice_id, v_active_row_keys;
    get diagnostics v_updated_count = row_count;
    v_canceled_operations := v_canceled_operations + v_updated_count;

    -- ردیف‌های تخصیص‌یافته‌ای که ردیف مبداشان حذف یا لغو شده، از فاکتور مقصد پاک می‌شوند.
    -- هر مقصد وارد صف می‌شود تا تخصیص‌های چندمرحله‌ای نیز به شکل زنجیره‌ای پاک‌سازی شوند.
    for v_target_invoice_id in execute format($sql$
      select distinct target.id
      from public.%I target
      cross join lateral jsonb_array_elements(coalesce(target.payments, '[]'::jsonb)) as payment(item)
      where target.org_id = $1
        and target.payments @> jsonb_build_array(jsonb_build_object('allocation_source_invoice_id', $2::text))
        and payment.item->>'allocation_source_invoice_id' = $2::text
        and not (coalesce(payment.item->>'allocation_source_row_key', '') = any($3))
    $sql$, v_table_name) using v_org_id, v_current_invoice_id, v_active_row_keys
    loop
      execute format($sql$
        update public.%I target
        set payments = cleaned.payments
        from lateral (
          select coalesce(
            jsonb_agg(payment.item order by payment.ordinality) filter (
              where not (
                payment.item->>'allocation_source_invoice_id' = $1::text
                and not (coalesce(payment.item->>'allocation_source_row_key', '') = any($2))
              )
            ),
            '[]'::jsonb
          ) as payments
          from jsonb_array_elements(coalesce(target.payments, '[]'::jsonb)) with ordinality as payment(item, ordinality)
        ) cleaned
        where target.id = $3
          and target.org_id = $4
      $sql$, v_table_name) using v_current_invoice_id, v_active_row_keys, v_target_invoice_id, v_org_id;
      get diagnostics v_updated_count = row_count;
      v_removed_rows := v_removed_rows + v_updated_count;

      if not (v_target_invoice_id = any(v_pending_invoice_ids)) then
        v_pending_invoice_ids := array_append(v_pending_invoice_ids, v_target_invoice_id);
      end if;
      if not (v_target_invoice_id = any(v_affected_invoice_ids)) then
        v_affected_invoice_ids := array_append(v_affected_invoice_ids, v_target_invoice_id);
      end if;
    end loop;
  end loop;

  return jsonb_build_object(
    'affected_invoice_ids', to_jsonb(v_affected_invoice_ids),
    'removed_payment_groups', v_removed_rows,
    'canceled_operations', v_canceled_operations
  );
end;
$_$;


--
-- Name: clear_demo_seed_batches(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_demo_seed_batches(p_org_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare item record; fk record; n bigint; remaining integer; progress integer; has_org boolean; relation_oid regclass; child_org boolean; child_uuid boolean; blocked boolean; deleted integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('demo:' || p_org_id::text,0));
  -- A recent writer may still be creating records. A crashed run becomes recoverable after 15 minutes.
  if exists(select 1 from public.demo_seed_batches where org_id=p_org_id and status='seeding' and updated_at > now()-interval '15 minutes') then
    raise exception 'ساخت داده‌های نمونه هنوز در حال انجام است؛ کمی بعد دوباره تلاش کنید.';
  end if;
  perform 1 from public.demo_seed_batches where org_id=p_org_id and cleared_at is null for update;
  update public.demo_seed_batches set status='clearing' where org_id=p_org_id and cleared_at is null and status<>'cleared';

  create temporary table demo_delete_targets on commit drop as
    select distinct r.table_name,r.record_id from public.demo_seed_records r
    join public.demo_seed_batches b on b.id=r.batch_id and b.org_id=r.org_id
    where r.org_id=p_org_id and b.cleared_at is null;

  -- Fail before deleting anything if a real row would be removed by a cascading FK.
  -- Other external references are handled by PostgreSQL; restrictive relationships block atomically.
  for item in select distinct table_name from demo_delete_targets loop
    relation_oid := to_regclass(format('public.%I',item.table_name));
    if relation_oid is null then raise exception 'بخشی از داده‌های نمونه در دسترس نیست.'; end if;
    for fk in select c.conrelid,c.conkey,c.confkey,c.confdeltype,n.nspname,cl.relname
      from pg_constraint c join pg_class cl on cl.oid=c.conrelid join pg_namespace n on n.oid=cl.relnamespace
      where c.contype='f' and c.confrelid=relation_oid and c.confdeltype='c'
    loop
      if array_length(fk.conkey,1)<>1 or array_length(fk.confkey,1)<>1 then
        raise exception 'حذف نمونه با این وابستگی نیاز به بررسی دارد.';
      end if;
      select exists(select 1 from pg_attribute where attrelid=fk.conrelid and attname='org_id' and not attisdropped),
        exists(select 1 from pg_attribute where attrelid=fk.conrelid and attname='id' and atttypid='uuid'::regtype and not attisdropped)
        into child_org,child_uuid;
      if not child_uuid then
        execute format('select exists(select 1 from %I.%I c join public.%I p on c.%I=p.%I join demo_delete_targets d on d.table_name=$1 and d.record_id=p.id)',
          fk.nspname,fk.relname,item.table_name,
          (select attname from pg_attribute where attrelid=fk.conrelid and attnum=fk.conkey[1]),
          (select attname from pg_attribute where attrelid=relation_oid and attnum=fk.confkey[1])) into blocked using item.table_name;
      else
        execute format('select exists(select 1 from %I.%I c join public.%I p on c.%I=p.%I join demo_delete_targets d on d.table_name=$1 and d.record_id=p.id where not exists(select 1 from demo_delete_targets child where child.table_name=$2 and child.record_id=c.id)%s)',
          fk.nspname,fk.relname,item.table_name,
          (select attname from pg_attribute where attrelid=fk.conrelid and attnum=fk.conkey[1]),
          (select attname from pg_attribute where attrelid=relation_oid and attnum=fk.confkey[1]),
          case when child_org then ' or (c.org_id is distinct from $3 and p.id in (select record_id from demo_delete_targets where table_name=$1))' else '' end)
          into blocked using item.table_name,fk.relname,p_org_id;
      end if;
      if blocked then raise exception 'اطلاعات جدیدی به داده‌های نمونه وابسته شده است. ابتدا ارتباط آن‌ها را جدا کنید؛ هیچ داده‌ای حذف نشد.'; end if;
    end loop;
  end loop;

  -- Retry restrictive FK dependencies until children have been deleted. Each failed
  -- attempt rolls back in its own subtransaction; the entire cleanup is atomic.
  loop
    select count(*) into remaining from demo_delete_targets;
    exit when remaining=0;
    progress := 0;
    for item in select * from demo_delete_targets loop
      select exists(select 1 from information_schema.columns where table_schema='public' and table_name=item.table_name and column_name='org_id') into has_org;
      begin
        execute format('delete from public.%I where id=$1%s',item.table_name,case when has_org then ' and org_id=$2' else '' end) using item.record_id,p_org_id;
        get diagnostics n = row_count;
        deleted := deleted+n;
        delete from demo_delete_targets where table_name=item.table_name and record_id=item.record_id;
        progress := progress+1;
      exception when foreign_key_violation or restrict_violation then null;
      end;
    end loop;
    if progress=0 then raise exception 'داده‌های نمونه به اطلاعات دیگری متصل‌اند. ابتدا ارتباط آن‌ها را جدا کنید؛ هیچ داده‌ای حذف نشد.'; end if;
  end loop;
  update public.demo_seed_batches set status='cleared',cleared_by=p_user_id,cleared_at=now()
    where org_id=p_org_id and cleared_at is null;
  return jsonb_build_object('success',true,'status','cleared','has_seeded_batch',false,'seeded_records_count',0,'deleted_records_count',deleted);
end; $_$;


--
-- Name: cloud_org_has_plan_access(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cloud_org_has_plan_access(p_org_id uuid, p_key text, p_kind text, p_default boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare ctx record; policy jsonb; overrides jsonb; value jsonb; parent text; internal_org boolean;
begin
 if p_org_id is null or nullif(trim(p_key),'') is null or p_kind not in ('feature','module') then return false; end if;
 select s.org_id,s.status,s.is_demo,s.trial_ends_at,s.feature_overrides,s.module_overrides,
  p.id as plan_id,p.enabled_features,p.enabled_modules into ctx
 from public.saas_org_settings s left join public.saas_plans p on lower(p.code)=lower(s.plan_code) and p.is_active
 where s.org_id=p_org_id limit 1;
 internal_org:=public.org_is_saas_admin(p_org_id);
 if (ctx.org_id is null or ctx.plan_id is null) and not internal_org then return false; end if;
 if coalesce(ctx.status,'active') in ('suspended','failed','draft') or
  ((coalesce(ctx.is_demo,false) or coalesce(ctx.status,'') in ('trial','demo')) and (ctx.trial_ends_at is null or ctx.trial_ends_at<=now())) then return false; end if;
 policy:=case when p_kind='feature' then coalesce(ctx.enabled_features,'{}') else coalesce(ctx.enabled_modules,'{}') end;
 overrides:=case when p_kind='feature' then coalesce(ctx.feature_overrides,'{}') else coalesce(ctx.module_overrides,'{}') end;
 if overrides?p_key then value:=overrides->p_key;
 elsif exists(select 1 from public.saas_org_entitlements where org_id=p_org_id and item_kind=p_kind and entitlement_code=p_key and state='disabled' and (expires_at is null or expires_at>now())) then return false;
 elsif exists(select 1 from public.saas_org_entitlements where org_id=p_org_id and item_kind=p_kind and entitlement_code=p_key and state='enabled' and (expires_at is null or expires_at>now())) then return true;
 elsif policy?p_key then value:=policy->p_key;
 elsif internal_org then return true;
 elsif p_kind='feature' and p_key like 'ai_agent:%' and not exists(select 1 from jsonb_object_keys(policy) k where k like 'ai_agent:%') then return true;
 elsif p_kind='module' then
  parent:=public.saas_offering_keys()->'moduleParents'->>p_key;
  if parent is not null then value:=coalesce(ctx.enabled_modules->parent,'false'::jsonb);
  else
   parent:=public.saas_offering_keys()->'moduleFeatures'->>p_key;
   if parent is not null then value:=coalesce(ctx.enabled_features->parent,'false'::jsonb);
   elsif p_key='instructions' then return true; end if;
  end if;
 end if;
 if value is null then return coalesce(p_default,false); end if;
 return coalesce(value='true'::jsonb or lower(value#>>'{}') in ('true','1','yes','on','enabled','full','limited') or value->'enabled'='true'::jsonb or value->'available'='true'::jsonb,false);
end; $$;


--
-- Name: cloud_org_has_plan_feature(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cloud_org_has_plan_feature(p_org_id uuid, p_feature_key text, p_default_enabled boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 select public.cloud_org_has_plan_access(p_org_id,p_feature_key,'feature',p_default_enabled);
$$;


