BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: collect_record_file_bundle(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_record_file_bundle(p_module_id text, p_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_module_id text := trim(coalesce(p_module_id, ''));
  v_folders jsonb := '[]'::jsonb;
  v_entries jsonb := '[]'::jsonb;
  v_record_files jsonb := '[]'::jsonb;
begin
  if v_module_id = '' or p_record_id is null then
    return '{}'::jsonb;
  end if;

  if to_regclass('public.file_folders') is not null then
    select coalesce(jsonb_agg(to_jsonb(f) order by f.created_at, f.id), '[]'::jsonb)
    into v_folders
    from public.file_folders f
    where f.module_id = v_module_id
      and f.record_id = p_record_id;
  end if;

  if to_regclass('public.file_entries') is not null then
    select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at, e.id), '[]'::jsonb)
    into v_entries
    from public.file_entries e
    where e.module_id = v_module_id
      and e.record_id = p_record_id
      and coalesce(e.is_deleted, false) = false;
  end if;

  if to_regclass('public.record_files') is not null then
    select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at, r.id), '[]'::jsonb)
    into v_record_files
    from public.record_files r
    where (
      r.module_id = v_module_id
      and trim(coalesce(r.record_id, '')) = p_record_id::text
    ) or (
      r.source_module_id = v_module_id
      and trim(coalesce(r.source_record_id, '')) = p_record_id::text
    );
  end if;

  if jsonb_array_length(v_folders) = 0
     and jsonb_array_length(v_entries) = 0
     and jsonb_array_length(v_record_files) = 0 then
    return '{}'::jsonb;
  end if;

  return jsonb_build_object(
    'folders', v_folders,
    'entries', v_entries,
    'record_files', v_record_files
  );
end;
$$;


--
-- Name: combine_attendance_date_time(date, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.combine_attendance_date_time(p_date date, p_time time without time zone) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_date is null or p_time is null then null
    else ((p_date + p_time) at time zone 'Asia/Tehran')
  end
$$;


--
-- Name: complete_process_automation_first_match_execution(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_process_automation_first_match_execution(p_execution_key text, p_status text, p_last_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'دسترسی اجرای اتوماسیون فرآیند وجود ندارد.' using errcode = '42501';
  end if;
  if p_status not in ('succeeded', 'failed') then
    raise exception 'وضعیت اجرای اتوماسیون فرآیند نامعتبر است.' using errcode = '22023';
  end if;

  update public.process_automation_execution_claims
  set status = p_status,
      completed_at = now(),
      last_error = case when p_status = 'failed' then nullif(p_last_error, '') else null end,
      updated_at = now()
  where execution_key = p_execution_key and status = 'running';
  return found;
end;
$$;


--
-- Name: complete_workflow_action_execution(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_workflow_action_execution(p_execution_key text, p_status text, p_last_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'دسترسی اجرای اقدام خودکار وجود ندارد.' using errcode = '42501';
  end if;
  if p_status not in ('succeeded', 'failed', 'needs_attention') then
    raise exception 'وضعیت اجرای اقدام نامعتبر است.' using errcode = '22023';
  end if;

  update public.workflow_action_execution_claims
  set status = p_status,
      completed_at = now(),
      last_error = case when p_status = 'succeeded' then null else nullif(p_last_error, '') end,
      updated_at = now()
  where execution_key = p_execution_key
    and status = 'running';
  return found;
end;
$$;


--
-- Name: complete_workflow_event_first_match_execution(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_workflow_event_first_match_execution(p_execution_key text, p_status text, p_last_error text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'دسترسی اجرای گردش‌کار وجود ندارد.' using errcode = '42501';
  end if;
  if p_status not in ('succeeded', 'failed') then
    raise exception 'وضعیت اجرای گردش‌کار نامعتبر است.' using errcode = '22023';
  end if;

  update public.workflow_event_execution_claims
  set status = p_status,
      completed_at = now(),
      last_error = case when p_status = 'failed' then nullif(p_last_error, '') else null end,
      updated_at = now()
  where execution_key = p_execution_key
    and status = 'running';
  return found;
end;
$$;


--
-- Name: consume_phone_signup_invite(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_phone_signup_invite(p_phone text, p_user_id uuid DEFAULT NULL::uuid, p_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  normalized_phone text := public.normalize_iran_mobile_e164(p_phone);
  effective_user_id uuid := coalesce(p_user_id, auth.uid());
  caller_user_id uuid := auth.uid();
  invite_row public.phone_signup_invites%rowtype;
  existing_profile public.profiles%rowtype;
  conflicting_profile public.profiles%rowtype;
  conflicting_profile_count integer := 0;
  mobile_local text;
begin
  if normalized_phone is null then
    return jsonb_build_object(
      'success', false,
      'reason', 'invalid_phone'
    );
  end if;

  if effective_user_id is null then
    return jsonb_build_object(
      'success', false,
      'reason', 'missing_user'
    );
  end if;

  if caller_user_id is not null and caller_user_id <> effective_user_id then
    raise exception using
      errcode = '42501',
      message = 'consume_phone_signup_invite can only be used for the current user';
  end if;

  select *
    into invite_row
  from public.phone_signup_invites
  where phone_e164 = normalized_phone
    and consumed_at is null
  order by created_at desc
  limit 1
  for update;

  if not found then
    return jsonb_build_object(
      'success', false,
      'reason', 'invite_not_found',
      'normalized_phone', normalized_phone
    );
  end if;

  if invite_row.is_active = false then
    return jsonb_build_object(
      'success', false,
      'reason', 'invite_inactive',
      'invite_id', invite_row.id,
      'normalized_phone', normalized_phone
    );
  end if;

  select *
    into existing_profile
  from public.profiles
  where id = effective_user_id
  limit 1;

  with matched_profiles as (
    select
      p.*
    from public.profiles p
    left join auth.users u
      on u.id = p.id
    where (
      public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) = normalized_phone
      or (
        public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) is null
        and public.normalize_iran_mobile_e164(u.phone) = normalized_phone
      )
    )
      and p.id <> effective_user_id
  )
  select count(*)
    into conflicting_profile_count
  from matched_profiles;

  if conflicting_profile_count > 1 then
    return jsonb_build_object(
      'success', false,
      'reason', 'multiple_profiles',
      'invite_id', invite_row.id,
      'normalized_phone', normalized_phone
    );
  end if;

  if conflicting_profile_count = 1 then
    with matched_profiles as (
      select
        p.*
      from public.profiles p
      left join auth.users u
        on u.id = p.id
      where (
        public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) = normalized_phone
        or (
          public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) is null
          and public.normalize_iran_mobile_e164(u.phone) = normalized_phone
        )
      )
        and p.id <> effective_user_id
      order by p.created_at asc nulls last
      limit 1
    )
    select *
      into conflicting_profile
    from matched_profiles;

    return jsonb_build_object(
      'success', false,
      'reason', 'profile_org_conflict',
      'invite_id', invite_row.id,
      'normalized_phone', normalized_phone,
      'existing_org_id', conflicting_profile.org_id
    );
  end if;

  if existing_profile.id is not null and existing_profile.is_active = false then
    return jsonb_build_object(
      'success', false,
      'reason', 'profile_inactive',
      'invite_id', invite_row.id,
      'normalized_phone', normalized_phone
    );
  end if;

  if existing_profile.id is not null
     and existing_profile.org_id is not null
     and invite_row.org_id is not null
     and existing_profile.org_id <> invite_row.org_id then
    return jsonb_build_object(
      'success', false,
      'reason', 'profile_org_conflict',
      'invite_id', invite_row.id,
      'normalized_phone', normalized_phone,
      'existing_org_id', existing_profile.org_id
    );
  end if;

  mobile_local := regexp_replace(normalized_phone, '^\+98', '0');

  if existing_profile.id is null then
    insert into public.profiles (
      id,
      org_id,
      full_name,
      email,
      mobile_1,
      role_id,
      role,
      is_active
    ) values (
      effective_user_id,
      invite_row.org_id,
      nullif(trim(invite_row.full_name), ''),
      coalesce(nullif(trim(p_email), ''), nullif(trim(invite_row.email), '')),
      mobile_local,
      invite_row.role_id,
      coalesce(nullif(trim(invite_row.role), ''), 'viewer'),
      true
    );
  else
    update public.profiles
       set org_id = coalesce(public.profiles.org_id, invite_row.org_id),
           full_name = coalesce(nullif(public.profiles.full_name, ''), nullif(trim(invite_row.full_name), '')),
           email = coalesce(nullif(public.profiles.email, ''), coalesce(nullif(trim(p_email), ''), nullif(trim(invite_row.email), ''))),
           mobile_1 = coalesce(nullif(public.profiles.mobile_1, ''), mobile_local),
           role_id = coalesce(public.profiles.role_id, invite_row.role_id),
           role = coalesce(nullif(public.profiles.role, ''), nullif(trim(invite_row.role), ''), 'viewer')
     where id = effective_user_id;
  end if;

  update public.phone_signup_invites
     set consumed_at = now(),
         consumed_by = effective_user_id
   where id = invite_row.id;

  return jsonb_build_object(
    'success', true,
    'invite_id', invite_row.id,
    'profile_id', effective_user_id,
    'org_id', invite_row.org_id,
    'created_profile', (existing_profile.id is null)
  );
end;
$$;


--
-- Name: control_advertising_campaign_dispatch(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_advertising_campaign_dispatch(p_dispatch_id uuid, p_action text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_dispatch public.advertising_campaign_dispatches%rowtype; v_action text:=lower(btrim(coalesce(p_action,''))); v_status text;
        v_reset_count integer:=0;
begin
  select * into v_dispatch from public.advertising_campaign_dispatches where id=p_dispatch_id and org_id=public.current_org_id();
  if v_dispatch.id is null or not public.can_edit_advertising_campaign(v_dispatch.campaign_id)
    or not public.current_user_has_role_permission_entry('advertising_campaigns','edit','send',true) then
    raise exception 'اجازه کنترل ارسال را ندارید.' using errcode='42501';
  end if;
  v_status:=case
    when v_action='pause' and v_dispatch.status in ('queued','processing') then 'paused'
    when v_action='resume' and v_dispatch.status='paused' then 'queued'
    when v_action='cancel' and v_dispatch.status in ('draft','queued','processing','paused','failed') then 'canceled'
    when v_action='retry' and v_dispatch.status in ('failed','partial') then 'queued'
    else null end;
  if v_status is null then raise exception 'این تغییر وضعیت برای ارسال جاری مجاز نیست.' using errcode='22023'; end if;
  if v_action='retry' then
    update public.advertising_campaign_recipients set status='pending',error_message=null
    where dispatch_id=p_dispatch_id and org_id=v_dispatch.org_id
      and status='failed' and attempt_count < 5;
    get diagnostics v_reset_count = row_count;
    if v_reset_count=0 and not exists(
      select 1 from public.advertising_campaign_recipients
      where dispatch_id=p_dispatch_id and status='pending'
    ) then
      raise exception 'هیچ مخاطب ناموفقی در سقف مجاز تلاش مجدد باقی نمانده است.' using errcode='22023';
    end if;
  end if;
  update public.advertising_campaign_dispatches set status=v_status,
    available_at=case when v_status='queued' then now() else available_at end,
    claimed_at=case when v_status='queued' then null else claimed_at end,
    completed_at=case when v_status='canceled' then now() when v_status='queued' then null else completed_at end,
    attempts=case when v_action='retry' then 0 else attempts end,
    last_error=case when v_action='retry' then null else last_error end
  where id=p_dispatch_id;
  return v_status;
end;
$$;


--
-- Name: copy_process_run_stage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_process_run_stage(p_process_run_stage_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_source public.process_run_stages%rowtype;
  v_org_id uuid;
  v_new_stage_id uuid;
  v_node_key text;
begin
  select s.*
  into v_source
  from public.process_run_stages s
  where s.id = p_process_run_stage_id;

  select r.org_id
  into v_org_id
  from public.process_runs r
  where r.id = v_source.process_run_id;

  if auth.uid() is null
    or v_org_id is null
    or public.current_org_id() is null
    or v_org_id <> public.current_org_id() then
    raise exception 'دسترسی کپی مرحله فرآیند وجود ندارد.' using errcode = '42501';
  end if;

  update public.process_run_stages
  set sort_order = sort_order + 10,
      updated_at = now()
  where process_run_id = v_source.process_run_id
    and coalesce(process_lane_key, metadata ->> 'process_lane_key', 'lane_1')
      = coalesce(v_source.process_lane_key, v_source.metadata ->> 'process_lane_key', 'lane_1')
    and sort_order > v_source.sort_order;

  update public.tasks t
  set sort_order = s.sort_order,
      source_stage_sort_order = s.sort_order,
      updated_by = auth.uid(),
      updated_at = now()
  from public.process_run_stages s
  where s.process_run_id = v_source.process_run_id
    and s.task_id = t.id
    and t.org_id = v_org_id;

  v_node_key := 'stage_' || replace(gen_random_uuid()::text, '-', '');

  insert into public.process_run_stages (
    process_run_id,
    template_stage_id,
    stage_name,
    sort_order,
    status,
    assignee_user_id,
    assignee_role_id,
    wage,
    planned_due_at,
    started_at,
    completed_at,
    task_id,
    process_node_key,
    process_lane_key,
    metadata
  )
  values (
    v_source.process_run_id,
    null,
    coalesce(nullif(btrim(v_source.stage_name), ''), 'مرحله') || ' - کپی',
    v_source.sort_order + 10,
    'todo',
    v_source.assignee_user_id,
    v_source.assignee_role_id,
    v_source.wage,
    null,
    null,
    null,
    null,
    v_node_key,
    coalesce(v_source.process_lane_key, v_source.metadata ->> 'process_lane_key', 'lane_1'),
    (coalesce(v_source.metadata, '{}'::jsonb) - 'draft_stage_id')
      || jsonb_build_object(
        'process_node_key', v_node_key,
        'process_lane_key', coalesce(v_source.process_lane_key, v_source.metadata ->> 'process_lane_key', 'lane_1')
      )
  )
  returning id into v_new_stage_id;

  return v_new_stage_id;
end;
$$;


--
-- Name: create_advertising_campaign_dispatch(uuid, text, jsonb, jsonb, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_advertising_campaign_dispatch(p_tool_id uuid, p_channel_type text, p_recipients jsonb, p_message_snapshot jsonb DEFAULT '{}'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_tool public.advertising_campaign_tools%rowtype; v_dispatch_id uuid; v_item jsonb; v_contact text; v_key text;
        v_feature text; v_channel text:=lower(btrim(coalesce(p_channel_type,'')));
        v_group record; v_selected_group_count integer:=0;
        v_idempotency text:=coalesce(nullif(btrim(p_idempotency_key),''),gen_random_uuid()::text);
begin
  select * into v_tool from public.advertising_campaign_tools where id=p_tool_id and org_id=public.current_org_id();
  if v_tool.id is null or not public.can_edit_advertising_campaign(v_tool.campaign_id)
     or not public.current_user_has_role_permission_entry('advertising_campaigns','edit','send',true) then
    raise exception 'اجازه آماده‌سازی ارسال کمپین را ندارید.' using errcode='42501';
  end if;
  v_feature := case v_tool.tool_type when 'sms' then 'campaign_sms' when 'email' then 'campaign_email'
    when 'bot_group' then 'campaign_bot_group' when 'bot_private' then 'campaign_bot_private' else null end;
  if v_channel not in ('sms','email','bot_group','bot_private') or v_channel <> v_tool.tool_type then
    raise exception 'کانال ارسال با ابزار کمپین تطبیق ندارد.' using errcode='22023';
  end if;
  if not public.org_has_plan_module(v_tool.org_id,'advertising_campaigns',false)
     or v_feature is null
     or not public.org_has_plan_feature(v_tool.org_id,v_feature,false) then
    raise exception 'کانال ارسال در پلن سازمان فعال نیست.' using errcode='42501';
  end if;
  if jsonb_typeof(p_recipients) <> 'array' then raise exception 'فهرست مخاطبان معتبر نیست.' using errcode='22023'; end if;

  select id into v_dispatch_id from public.advertising_campaign_dispatches
  where org_id=v_tool.org_id and idempotency_key=v_idempotency;
  if v_dispatch_id is not null then return v_dispatch_id; end if;

  insert into public.advertising_campaign_dispatches(
    org_id,campaign_id,tool_id,channel_type,status,scheduled_at,available_at,
    audience_snapshot,message_snapshot,idempotency_key,created_by
  ) values (
    v_tool.org_id,v_tool.campaign_id,v_tool.id,v_channel,
    case when p_scheduled_at is null or p_scheduled_at<=now() then 'queued' else 'queued' end,
    p_scheduled_at,coalesce(p_scheduled_at,now()),
    jsonb_build_object('prepared_at',now(),'input_count',jsonb_array_length(p_recipients)),
    coalesce(p_message_snapshot,'{}'::jsonb),v_idempotency,auth.uid()
  ) returning id into v_dispatch_id;

  if v_tool.tool_type='bot_group' then
    for v_group in
      select g.id,g.bot_chat_id,g.group_title,g.channel_type,g.metadata
      from public.counterparty_bot_groups g
      where g.org_id=v_tool.org_id
        and g.status='active'
        and g.channel_type=lower(btrim(coalesce(v_tool.config->>'channel','')))
        and nullif(btrim(g.bot_chat_id),'') is not null
        and g.id in (
          select value::uuid
          from jsonb_array_elements_text(coalesce(v_tool.config->'group_ids','[]'::jsonb)) selected(value)
          where value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        )
    loop
      v_selected_group_count:=v_selected_group_count+1;
      v_contact:=btrim(v_group.bot_chat_id);
      v_key:=public.advertising_campaign_contact_key(v_channel,v_contact);
      insert into public.advertising_campaign_recipients(
        org_id,campaign_id,tool_id,dispatch_id,source_type,source_module_id,source_record_id,
        contact_value,contact_key,display_name,variables,status
      ) values (
        v_tool.org_id,v_tool.campaign_id,v_tool.id,v_dispatch_id,'internal','counterparty_bot_groups',v_group.id,
        v_contact,v_key,coalesce(nullif(v_group.group_title,''),'گروه بات'),
        jsonb_build_object('channel',v_group.channel_type,'group_id',v_group.id,'metadata',coalesce(v_group.metadata,'{}'::jsonb)),
        'pending'
      ) on conflict (dispatch_id,contact_key) do nothing;
    end loop;
    if v_selected_group_count=0 then
      delete from public.advertising_campaign_dispatches where id=v_dispatch_id;
      raise exception 'هیچ گروه فعال و معتبری برای ارسال انتخاب نشده است.' using errcode='22023';
    end if;
  else
    for v_item in select value from jsonb_array_elements(p_recipients) loop
      v_contact:=btrim(coalesce(v_item->>'contact_value',v_item->>'recipient',''));
      v_key:=public.advertising_campaign_contact_key(v_channel,v_contact);
      if v_key='' then continue; end if;
      insert into public.advertising_campaign_recipients(
        org_id,campaign_id,tool_id,dispatch_id,source_type,source_module_id,source_record_id,
        contact_value,contact_key,display_name,variables,status
      ) values (
        v_tool.org_id,v_tool.campaign_id,v_tool.id,v_dispatch_id,
        case when v_item->>'source_type'='file' then 'file' else 'internal' end,
        nullif(v_item->>'source_module_id',''),
        case when coalesce(v_item->>'source_record_id','') ~* '^[0-9a-f-]{36}$' then (v_item->>'source_record_id')::uuid else null end,
        v_contact,v_key,nullif(v_item->>'display_name',''),coalesce(v_item->'variables','{}'::jsonb),
        case when exists(select 1 from public.campaign_contact_suppressions s where s.org_id=v_tool.org_id
          and s.channel_type=v_channel and s.contact_key=v_key and s.is_active) then 'suppressed' else 'pending' end
      ) on conflict (dispatch_id,contact_key) do nothing;
    end loop;
  end if;
  update public.advertising_campaign_dispatches d set
    recipient_count=(select count(*) from public.advertising_campaign_recipients r where r.dispatch_id=d.id),
    skipped_count=(select count(*) from public.advertising_campaign_recipients r where r.dispatch_id=d.id and r.status='suppressed')
  where d.id=v_dispatch_id;
  update public.advertising_campaign_tools set status='scheduled',updated_by=auth.uid()
  where id=v_tool.id and status in ('draft','ready');
  return v_dispatch_id;
end;
$_$;


--
-- Name: create_advertising_campaign_dispatch_from_rules(uuid, text, jsonb, jsonb, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_advertising_campaign_dispatch_from_rules(p_tool_id uuid, p_channel_type text, p_file_recipients jsonb DEFAULT '[]'::jsonb, p_message_snapshot jsonb DEFAULT '{}'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_dispatch_id uuid; v_tool public.advertising_campaign_tools%rowtype; v_rule record; v_row jsonb; v_import_row record;
        v_contact text; v_contact_key text; v_customer jsonb; v_title text; v_bot_channel text;
begin
  v_dispatch_id := public.create_advertising_campaign_dispatch(
    p_tool_id,p_channel_type,coalesce(p_file_recipients,'[]'::jsonb),
    p_message_snapshot,p_scheduled_at,p_idempotency_key
  );
  select * into v_tool from public.advertising_campaign_tools where id=p_tool_id and org_id=public.current_org_id();
  if v_tool.id is null then raise exception 'ابزار کمپین پیدا نشد.'; end if;
  if v_tool.tool_type='bot_group' then return v_dispatch_id; end if;
  v_bot_channel:=lower(btrim(coalesce(v_tool.config->>'channel','')));
  if v_tool.tool_type='bot_private' and v_bot_channel not in ('telegram','bale','rubika') then
    raise exception 'پلتفرم ارسال خصوصی بات معتبر نیست.' using errcode='22023';
  end if;

  -- Completed file imports are materialized server-side. They are unioned with
  -- internal rules and the optional one-shot payload, then deduplicated by the
  -- dispatch/contact key unique constraint.
  for v_import_row in
    select r.*
    from public.advertising_campaign_import_rows r
    join public.advertising_campaign_imports i on i.id=r.import_id and i.org_id=r.org_id
    where r.org_id=v_tool.org_id and r.tool_id=v_tool.id and i.status='completed'
    order by r.created_at,r.id
  loop
    insert into public.advertising_campaign_recipients(
      org_id,campaign_id,tool_id,dispatch_id,source_type,source_module_id,source_record_id,
      contact_value,contact_key,display_name,variables,status
    ) values (
      v_tool.org_id,v_tool.campaign_id,v_tool.id,v_dispatch_id,'file',null,null,
      v_import_row.contact_value,v_import_row.contact_key,v_import_row.display_name,v_import_row.variables,
      case when exists(select 1 from public.campaign_contact_suppressions s where s.org_id=v_tool.org_id
        and s.channel_type=lower(btrim(p_channel_type)) and s.contact_key=v_import_row.contact_key and s.is_active)
        then 'suppressed' else 'pending' end
    ) on conflict (dispatch_id,contact_key) do update set
      variables=advertising_campaign_recipients.variables || excluded.variables,
      display_name=coalesce(advertising_campaign_recipients.display_name,excluded.display_name);
  end loop;

  for v_rule in select * from public.advertising_campaign_audience_rules
    where campaign_id=v_tool.campaign_id and org_id=v_tool.org_id and enabled=true
  loop
    for v_row in execute format('select to_jsonb(t) from public.%I t where t.org_id=$1',v_rule.target_module_id)
      using v_tool.org_id
    loop
      if not public.advertising_campaign_conditions_match(v_row,v_rule.conditions_all,v_rule.conditions_any) then continue; end if;
      v_customer := null;
      if v_rule.target_module_id='customers' then
        v_customer:=v_row;
      elsif nullif(v_row->>'customer_id','') is not null
            and coalesce(v_row->>'customer_id','') ~* '^[0-9a-f-]{36}$' then
        select to_jsonb(c) into v_customer from public.customers c
        where c.org_id=v_tool.org_id and c.id=(v_row->>'customer_id')::uuid;
      end if;
      v_contact := case lower(btrim(p_channel_type))
        when 'sms' then coalesce(nullif(v_row->>'mobile',''),nullif(v_row->>'mobile_1',''),nullif(v_row->>'phone',''),nullif(v_customer->>'mobile_1',''),nullif(v_customer->>'phone',''))
        when 'email' then coalesce(nullif(v_row->>'email',''),nullif(v_customer->>'email',''))
        when 'bot_private' then case v_bot_channel
          when 'telegram' then coalesce(nullif(v_row->>'telegram_chat_id',''),nullif(v_customer->>'telegram_chat_id',''))
          when 'bale' then coalesce(nullif(v_row->>'bale_chat_id',''),nullif(v_customer->>'bale_chat_id',''))
          when 'rubika' then coalesce(nullif(v_row->>'rubika_chat_id',''),nullif(v_customer->>'rubika_chat_id',''))
          else null end
        else null end;
      v_contact_key := public.advertising_campaign_contact_key(p_channel_type,v_contact);
      if coalesce(v_contact_key,'')='' then continue; end if;
      v_title := coalesce(nullif(v_row->>'name',''),nullif(v_row->>'full_name',''),nullif(v_row->>'business_name',''),nullif(v_row->>'system_code',''),'[بدون عنوان]');
      insert into public.advertising_campaign_recipients(
        org_id,campaign_id,tool_id,dispatch_id,source_type,source_module_id,source_record_id,
        contact_value,contact_key,display_name,variables,status
      ) values (
        v_tool.org_id,v_tool.campaign_id,v_tool.id,v_dispatch_id,'internal',v_rule.target_module_id,(v_row->>'id')::uuid,
        v_contact,v_contact_key,v_title,v_row,
        case when exists(select 1 from public.campaign_contact_suppressions s where s.org_id=v_tool.org_id
          and s.channel_type=lower(btrim(p_channel_type)) and s.contact_key=v_contact_key and s.is_active) then 'suppressed' else 'pending' end
      ) on conflict (dispatch_id,contact_key) do update set
        variables=advertising_campaign_recipients.variables || excluded.variables,
        display_name=coalesce(advertising_campaign_recipients.display_name,excluded.display_name);
    end loop;
  end loop;
  update public.advertising_campaign_dispatches d set
    recipient_count=(select count(*) from public.advertising_campaign_recipients r where r.dispatch_id=d.id),
    skipped_count=(select count(*) from public.advertising_campaign_recipients r where r.dispatch_id=d.id and r.status='suppressed'),
    audience_snapshot=d.audience_snapshot || jsonb_build_object('rules_materialized_at',now())
  where d.id=v_dispatch_id;
  return v_dispatch_id;
end;
$_$;


--
-- Name: create_advertising_campaign_test_dispatch(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_advertising_campaign_test_dispatch(p_tool_id uuid, p_recipient text, p_message_snapshot jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tool public.advertising_campaign_tools%rowtype;
  v_dispatch_id uuid;
  v_channel text;
  v_contact text:=btrim(coalesce(p_recipient,''));
  v_contact_key text;
  v_feature text;
  v_idempotency text:=coalesce(nullif(btrim(p_idempotency_key),''),gen_random_uuid()::text);
begin
  select * into v_tool
  from public.advertising_campaign_tools
  where id=p_tool_id and org_id=public.current_org_id();

  if v_tool.id is null
     or not public.can_edit_advertising_campaign(v_tool.campaign_id)
     or not public.current_user_has_role_permission_entry('advertising_campaigns','edit','send',true) then
    raise exception 'اجازه ارسال آزمایشی این ابزار را ندارید.' using errcode='42501';
  end if;

  v_channel:=lower(btrim(coalesce(v_tool.tool_type,'')));
  v_feature:=case v_channel
    when 'sms' then 'campaign_sms'
    when 'email' then 'campaign_email'
    when 'bot_group' then 'campaign_bot_group'
    when 'bot_private' then 'campaign_bot_private'
    else null
  end;
  if v_feature is null then
    raise exception 'این ابزار امکان ارسال آزمایشی خودکار ندارد.' using errcode='22023';
  end if;
  if not public.org_has_plan_module(v_tool.org_id,'advertising_campaigns',false)
     or not public.org_has_plan_feature(v_tool.org_id,v_feature,false) then
    raise exception 'کانال ارسال در پلن سازمان فعال نیست.' using errcode='42501';
  end if;
  if v_contact='' then
    raise exception 'گیرنده آزمایشی معتبر نیست.' using errcode='22023';
  end if;
  v_contact_key:=public.advertising_campaign_contact_key(v_channel,v_contact);
  if coalesce(v_contact_key,'')='' then
    raise exception 'گیرنده آزمایشی معتبر نیست.' using errcode='22023';
  end if;

  select id into v_dispatch_id
  from public.advertising_campaign_dispatches
  where org_id=v_tool.org_id and idempotency_key=v_idempotency;
  if v_dispatch_id is not null then return v_dispatch_id; end if;

  insert into public.advertising_campaign_dispatches(
    org_id,campaign_id,tool_id,channel_type,status,scheduled_at,available_at,
    audience_snapshot,message_snapshot,idempotency_key,recipient_count,created_by
  ) values (
    v_tool.org_id,v_tool.campaign_id,v_tool.id,v_channel,'queued',null,now(),
    jsonb_build_object('is_test',true,'prepared_at',now(),'input_count',1),
    coalesce(p_message_snapshot,'{}'::jsonb) || jsonb_build_object('is_test',true),
    v_idempotency,1,auth.uid()
  ) returning id into v_dispatch_id;

  insert into public.advertising_campaign_recipients(
    org_id,campaign_id,tool_id,dispatch_id,source_type,
    contact_value,contact_key,display_name,variables,status
  ) values (
    v_tool.org_id,v_tool.campaign_id,v_tool.id,v_dispatch_id,'internal',
    v_contact,v_contact_key,'ارسال آزمایشی',jsonb_build_object('is_test',true),'pending'
  );
  return v_dispatch_id;
end;
$$;


--
-- Name: create_billboard_status_change_process_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_billboard_status_change_process_run(p_change_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_change public.billboard_status_changes%rowtype;
  v_run_id uuid;
  v_template jsonb;
  v_stage jsonb;
  v_template_id uuid;
begin
  if v_org_id is null or auth.uid() is null then raise exception 'سازمان یا کاربر جاری معتبر نیست.'; end if;
  select * into v_change from public.billboard_status_changes where id = p_change_id and org_id = v_org_id for update;
  if not found then raise exception 'درخواست تغییر وضعیت پیدا نشد.'; end if;
  if v_change.process_run_id is not null then return v_change.process_run_id; end if;
  v_template := coalesce(v_change.process_template_snapshot -> 'template', '{}'::jsonb);
  if v_template = '{}'::jsonb then return null; end if;
  v_template_id := nullif(v_template ->> 'id', '')::uuid;
  insert into public.process_runs (
    org_id, template_id, module_id, record_id, process_name, status, copied_mode, started_at, created_by, updated_by
  ) values (
    v_org_id, case when exists (select 1 from public.process_templates where id = v_template_id and org_id = v_org_id) then v_template_id else null end, 'billboard_status_changes', v_change.id,
    coalesce(nullif(v_template ->> 'name', ''), 'فرآیند تغییر وضعیت تابلو'), 'active', 'auto', now(), auth.uid(), auth.uid()
  ) returning id into v_run_id;
  insert into public.process_run_links (org_id, process_run_id, module_id, record_id, is_primary)
  values (v_org_id, v_run_id, 'billboard_status_changes', v_change.id, true)
  on conflict (process_run_id, module_id, record_id) do update set org_id = excluded.org_id, is_primary = true;
  for v_stage in select value from jsonb_array_elements(coalesce(v_change.process_template_snapshot -> 'stages', '[]'::jsonb)) loop
    insert into public.process_run_stages (
      process_run_id, template_stage_id, stage_name, sort_order, status, assignee_user_id, assignee_role_id, wage,
      process_node_key, process_lane_key, metadata
    ) values (
      v_run_id,
      case when exists (select 1 from public.process_template_stages where id = nullif(v_stage ->> 'id', '')::uuid) then nullif(v_stage ->> 'id', '')::uuid else null end,
      coalesce(nullif(v_stage ->> 'stage_name', ''), 'مرحله بدون عنوان'),
      coalesce(nullif(v_stage ->> 'sort_order', '')::integer, 0),
      coalesce(nullif(v_stage ->> 'default_status', ''), 'pending'),
      nullif(v_stage ->> 'default_assignee_id', '')::uuid,
      nullif(v_stage ->> 'default_assignee_role_id', '')::uuid,
      coalesce(nullif(v_stage ->> 'wage', '')::numeric, 0),
      coalesce(nullif(v_stage ->> 'process_node_key', ''), nullif(v_stage -> 'metadata' ->> 'process_node_key', '')),
      coalesce(nullif(v_stage ->> 'process_lane_key', ''), nullif(v_stage -> 'metadata' ->> 'process_lane_key', ''), 'lane_1'),
      coalesce(v_stage -> 'metadata', '{}'::jsonb)
    );
  end loop;
  update public.billboard_status_changes set process_run_id = v_run_id where id = v_change.id;
  return v_run_id;
end;
$$;


--
-- Name: create_current_saas_order(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_current_saas_order(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_org_id uuid := public.current_org_id(); normalized_items jsonb := '[]'::jsonb;
  entry record; catalog public.saas_catalog_items%rowtype; plan public.saas_plans%rowtype;
  qty numeric; entitlement_quantity numeric; line_total numeric; total numeric := 0; order_id uuid;
  billable_users integer; term_months integer; users_discount numeric; term_discount numeric; plan_count integer := 0;
  monthly_price numeric; base_total numeric;
begin
  if auth.uid() is null or v_org_id is null then raise exception 'organization_access_denied'; end if;
  if not exists (select 1 from public.user_organization_memberships where user_id=auth.uid() and org_id=v_org_id and is_active and (is_owner or software_role='admin')) then raise exception 'organization_admin_required'; end if;
  if not exists (select 1 from public.saas_org_settings where org_id=v_org_id) then raise exception 'saas_org_not_found'; end if;
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'order_items_required'; end if;
  for entry in select value from jsonb_array_elements(p_items) loop
    if coalesce(entry.value->>'quantity','') !~ '^[0-9]+$' then raise exception 'order_quantity_invalid'; end if;
    qty := (entry.value->>'quantity')::numeric;
    if qty<1 or qty>1000 then raise exception 'order_quantity_invalid'; end if;
    if left(coalesce(entry.value->>'code',''),5)='plan:' then
      plan_count := plan_count+1;
      if plan_count>1 then raise exception 'multiple_plans_not_allowed'; end if;
      select * into plan from public.saas_plans where code=substr(entry.value->>'code',6) and is_active and is_public;
      if plan.id is null or coalesce(plan.price_per_user_monthly,plan.price_monthly)<=0 then raise exception 'catalog_item_not_available'; end if;
      if coalesce(entry.value->>'term_months','1') !~ '^(1|3|6|12)$' then raise exception 'invalid_subscription_term'; end if;
      term_months := coalesce((entry.value->>'term_months')::integer,1);
      select greatest(3,qty::integer,count(*)::integer) into billable_users from public.user_organization_memberships where org_id=v_org_id and is_active;
      select coalesce(max(discount_percent),0) into users_discount from public.saas_checkout_discount_rules where kind='users' and minimum_quantity<=billable_users;
      select coalesce(discount_percent,0) into term_discount from public.saas_checkout_discount_rules where kind='term' and minimum_quantity=term_months;
      monthly_price := coalesce(plan.price_per_user_monthly,plan.price_monthly);
      base_total := monthly_price*billable_users*term_months;
      if term_months=12 and coalesce(plan.price_per_user_yearly,plan.price_yearly,0)>0 then
        term_discount := round(100*(1-coalesce(plan.price_per_user_yearly,plan.price_yearly)/nullif(monthly_price*12,0)),2);
      end if;
      line_total := round(base_total*(1-users_discount/100)*(1-term_discount/100));
      normalized_items := normalized_items || jsonb_build_array(jsonb_build_object(
        'code','plan:'||plan.code,'title',plan.title,'item_kind','plan','entitlement_code',plan.code,
        'quantity',1,'purchase_quantity',billable_users,'unit_price_irt',monthly_price,
        'line_total_irt',line_total,'metadata',jsonb_build_object('billable_users',billable_users,
          'pricing_model','per_user','term_months',term_months,'users_discount_percent',users_discount,
          'term_discount_percent',term_discount,'base_total_irt',base_total)));
      total := total+line_total;
    else
      select * into catalog from public.saas_catalog_items where code=entry.value->>'code' and is_active and is_public and price_irt>0 and entitlement_code<>'support_tickets';
      if catalog.id is null then raise exception 'catalog_item_not_available'; end if;
      entitlement_quantity := qty*catalog.quantity; line_total := qty*catalog.price_irt;
      normalized_items := normalized_items || jsonb_build_array(jsonb_build_object(
        'code',catalog.code,'title',catalog.title,'item_kind',catalog.item_kind,'entitlement_code',catalog.entitlement_code,
        'quantity',entitlement_quantity,'purchase_quantity',qty,'unit_price_irt',catalog.price_irt,
        'line_total_irt',line_total,'billing_cycle',catalog.billing_cycle,'metadata',catalog.metadata));
      total := total+line_total;
    end if;
  end loop;
  insert into public.saas_orders(org_id,created_by,total_irt,items) values(v_org_id,auth.uid(),total,normalized_items) returning id into order_id;
  return jsonb_build_object('success',true,'order_id',order_id,'total_irt',total,'items',normalized_items);
end $_$;


--
-- Name: create_internal_message_v2(text, text, uuid[], uuid[], uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_internal_message_v2(p_conversation_key text, p_content text, p_mention_user_ids uuid[] DEFAULT '{}'::uuid[], p_mention_role_ids uuid[] DEFAULT '{}'::uuid[], p_reply_to uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_author_id uuid := auth.uid();
  v_author_name text := null;
  v_author_role_id uuid := null;
  v_key text := nullif(trim(coalesce(p_conversation_key, '')), '');
  v_content text := coalesce(p_content, '');
  v_target_user_id uuid := null;
  v_group_id uuid := null;
  v_group_user_ids uuid[] := '{}'::uuid[];
  v_group_role_ids uuid[] := '{}'::uuid[];
  v_mention_user_ids uuid[] := public.kalam_distinct_uuid_array(coalesce(p_mention_user_ids, '{}'::uuid[]));
  v_mention_role_ids uuid[] := public.kalam_distinct_uuid_array(coalesce(p_mention_role_ids, '{}'::uuid[]));
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_row public.notes%rowtype;
begin
  if v_org_id is null or v_author_id is null or v_key is null then
    raise exception 'internal_message_context_missing';
  end if;

  if nullif(trim(v_content), '') is null then
    raise exception 'internal_message_content_required';
  end if;

  select p.full_name, p.role_id
  into v_author_name, v_author_role_id
  from public.profiles p
  where p.id = v_author_id
    and p.org_id = v_org_id
    and coalesce(p.is_active, true) = true
  limit 1;

  if not found then
    raise exception 'internal_message_author_not_found';
  end if;

  v_metadata := v_metadata || jsonb_build_object(
    'conversation_key', v_key,
    'source_type', coalesce(nullif(trim(v_metadata->>'source_type'), ''), 'internal_message')
  );

  if v_key = 'mine' then
    v_mention_user_ids := '{}'::uuid[];
    v_mention_role_ids := '{}'::uuid[];
    v_metadata := v_metadata || jsonb_build_object('saved_message', true);
  elsif v_key like 'group:%' then
    v_group_id := public.kalam_try_uuid(substring(v_key from 7));
    if v_group_id is null then
      raise exception 'internal_message_group_invalid';
    end if;

    select coalesce(cg.user_ids, '{}'::uuid[]), coalesce(cg.role_ids, '{}'::uuid[])
    into v_group_user_ids, v_group_role_ids
    from public.chat_groups cg
    where cg.id = v_group_id
      and cg.org_id = v_org_id
    limit 1;

    if not found then
      raise exception 'internal_message_group_not_found';
    end if;

    if not (
      v_author_id = any(v_group_user_ids)
      or (v_author_role_id is not null and v_author_role_id = any(v_group_role_ids))
    ) then
      raise exception 'internal_message_group_access_denied';
    end if;

    v_mention_user_ids := public.kalam_distinct_uuid_array(
      v_mention_user_ids
      || array_remove(v_group_user_ids, v_author_id)
    );
    v_mention_role_ids := public.kalam_distinct_uuid_array(v_mention_role_ids || v_group_role_ids);
    v_metadata := v_metadata || jsonb_build_object('chat_group_id', v_group_id);
  elsif v_key like 'direct:%' then
    v_target_user_id := case
      when public.kalam_try_uuid(split_part(v_key, ':', 2)) = v_author_id
        then public.kalam_try_uuid(split_part(v_key, ':', 3))
      when public.kalam_try_uuid(split_part(v_key, ':', 3)) = v_author_id
        then public.kalam_try_uuid(split_part(v_key, ':', 2))
      else null
    end;

    if v_target_user_id is null then
      raise exception 'internal_message_direct_invalid';
    end if;

    perform 1
    from public.profiles p
    where p.id = v_target_user_id
      and p.org_id = v_org_id
      and coalesce(p.is_active, true) = true
    limit 1;

    if not found then
      raise exception 'internal_message_direct_target_not_found';
    end if;

    v_mention_user_ids := public.kalam_distinct_uuid_array(v_mention_user_ids || array[v_target_user_id]);
    v_metadata := v_metadata || jsonb_build_object('target_user_id', v_target_user_id);
  else
    raise exception 'internal_message_conversation_invalid';
  end if;

  insert into public.notes (
    org_id,
    module_id,
    record_id,
    content,
    reply_to,
    mention_user_ids,
    mention_role_ids,
    author_id,
    author_name,
    metadata
  )
  values (
    v_org_id,
    '',
    '',
    v_content,
    p_reply_to,
    v_mention_user_ids,
    v_mention_role_ids,
    v_author_id,
    nullif(trim(coalesce(v_author_name, '')), ''),
    v_metadata
  )
  returning * into v_row;

  return to_jsonb(v_row);
end;
$$;


--
-- Name: FUNCTION create_internal_message_v2(p_conversation_key text, p_content text, p_mention_user_ids uuid[], p_mention_role_ids uuid[], p_reply_to uuid, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_internal_message_v2(p_conversation_key text, p_content text, p_mention_user_ids uuid[], p_mention_role_ids uuid[], p_reply_to uuid, p_metadata jsonb) IS 'Creates an internal Messaging v2 note through a server-side per-org send path.';


--
-- Name: create_journal_entry_correction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_journal_entry_correction(p_entry_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_original public.journal_entries%rowtype;
  v_correction_id uuid;
  v_line record;
  v_total_debit numeric(18,2) := 0;
  v_total_credit numeric(18,2) := 0;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if v_user_id is null or v_org_id is null then
    raise exception 'دسترسی به سازمان جاری معتبر نیست.' using errcode = '42501';
  end if;
  if v_reason is null then
    raise exception 'دلیل اصلاح سند الزامی است.' using errcode = '22023';
  end if;

  select * into v_original
  from public.journal_entries
  where id = p_entry_id
    and org_id = v_org_id
  for update;

  if not found then
    raise exception 'سند موردنظر یافت نشد.' using errcode = 'P0002';
  end if;
  if v_original.status <> 'posted' then
    raise exception 'فقط سند ثبت‌شده قابل اصلاح کنترل‌شده است.' using errcode = '22023';
  end if;

  insert into public.journal_entries (
    org_id, fiscal_year_id, entry_date, description, status,
    source_module, source_table, source_record_id, reversal_of_entry_id,
    metadata, created_by, updated_by
  ) values (
    v_org_id, v_original.fiscal_year_id, v_original.entry_date,
    'پیش‌نویس اصلاح سند: ' || coalesce(v_original.entry_no, v_original.id::text),
    'draft', v_original.source_module, v_original.source_table,
    v_original.source_record_id, v_original.id,
    jsonb_build_object(
      'posting_mode', 'controlled_correction',
      'correction_reason', v_reason,
      'original_entry_id', v_original.id
    ),
    v_user_id, v_user_id
  ) returning id into v_correction_id;

  for v_line in
    select account_id, line_no, description, debit, credit, cost_center_id, project_id, party_type, party_id, metadata, tags
    from public.journal_lines
    where entry_id = v_original.id
    order by line_no
  loop
    insert into public.journal_lines (
      entry_id, line_no, account_id, description, debit, credit,
      cost_center_id, project_id, party_type, party_id, metadata, tags
    ) values (
      v_correction_id, v_line.line_no, v_line.account_id,
      'اصلاح: ' || coalesce(v_line.description, ''),
      v_line.credit, v_line.debit, v_line.cost_center_id,
      v_line.project_id, v_line.party_type, v_line.party_id,
      coalesce(v_line.metadata, '{}'::jsonb) || jsonb_build_object('correction_of_line', v_line.line_no),
      coalesce(v_line.tags, '[]'::jsonb)
    );
    v_total_debit := v_total_debit + coalesce(v_line.credit, 0);
    v_total_credit := v_total_credit + coalesce(v_line.debit, 0);
  end loop;

  update public.journal_entries
  set total_debit = v_total_debit,
      total_credit = v_total_credit,
      updated_at = now(),
      updated_by = v_user_id
  where id = v_correction_id;

  update public.journal_entries
  set status = 'reversed', updated_at = now(), updated_by = v_user_id
  where id = v_original.id;

  insert into public.journal_entry_corrections (
    org_id, original_entry_id, correction_entry_id, reason, created_by,
    before_snapshot, after_snapshot
  ) values (
    v_org_id, v_original.id, v_correction_id, v_reason, v_user_id,
    jsonb_build_object('status', v_original.status, 'entry_no', v_original.entry_no,
      'total_debit', v_original.total_debit, 'total_credit', v_original.total_credit),
    jsonb_build_object('status', 'draft', 'entry_id', v_correction_id,
      'total_debit', v_total_debit, 'total_credit', v_total_credit)
  );

  return v_correction_id;
end;
$$;


--
-- Name: create_org_story(text, jsonb, boolean, boolean, boolean, uuid[], uuid[], uuid[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_org_story(p_creator_name text, p_slides jsonb, p_is_org_wide boolean DEFAULT true, p_is_saas_wide boolean DEFAULT false, p_is_saas_admins_only boolean DEFAULT false, p_viewer_user_ids uuid[] DEFAULT '{}'::uuid[], p_viewer_role_ids uuid[] DEFAULT '{}'::uuid[], p_mention_user_ids uuid[] DEFAULT '{}'::uuid[], p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_creator_id uuid;
  v_org_id     uuid;
  v_story_id   uuid;
begin
  -- مقادیر server-side — اینجا auth.uid() و current_org_id() قابل اطمینان هستند
  v_creator_id := auth.uid();
  if v_creator_id is null then
    raise exception 'احراز هویت لازم است' using errcode = 'P0001';
  end if;

  v_org_id := public.current_org_id();
  if v_org_id is null then
    raise exception 'کاربر به سازمانی متصل نیست' using errcode = 'P0001';
  end if;

  -- اگر SaaS-wide است، دسترسی لازم را بررسی می‌کنیم
  if p_is_saas_wide then
    if not (
      public.current_user_has_saas_admin_permission('publish_saas_story')
      or public.current_user_has_saas_admin_permission('publish_saas_admin_story')
    ) then
      raise exception 'دسترسی انتشار استوری SaaS وجود ندارد' using errcode = 'P0001';
    end if;
  end if;

  -- INSERT — چون SECURITY DEFINER است و owner آن postgres است، RLS دور زده می‌شود
  insert into public.org_stories (
    creator_id,
    org_id,
    creator_name,
    slides,
    is_org_wide,
    is_saas_wide,
    is_saas_admins_only,
    viewer_user_ids,
    viewer_role_ids,
    mention_user_ids,
    expires_at,
    published_at,
    updated_at
  ) values (
    v_creator_id,
    v_org_id,
    p_creator_name,
    p_slides,
    p_is_org_wide,
    coalesce(p_is_saas_wide, false),
    coalesce(p_is_saas_admins_only, false) and coalesce(p_is_saas_wide, false),
    coalesce(p_viewer_user_ids, '{}'),
    coalesce(p_viewer_role_ids, '{}'),
    coalesce(p_mention_user_ids, '{}'),
    p_expires_at,
    now(),
    now()
  )
  returning id into v_story_id;

  return v_story_id;
end;
$$;


--
-- Name: create_org_story(text, jsonb, text, boolean, boolean, boolean, uuid[], uuid[], uuid[], uuid[], timestamp with time zone, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_org_story(p_creator_name text, p_slides jsonb, p_creator_avatar text DEFAULT NULL::text, p_is_org_wide boolean DEFAULT true, p_is_saas_wide boolean DEFAULT false, p_is_saas_admins_only boolean DEFAULT false, p_viewer_user_ids uuid[] DEFAULT '{}'::uuid[], p_viewer_role_ids uuid[] DEFAULT '{}'::uuid[], p_mention_user_ids uuid[] DEFAULT '{}'::uuid[], p_mention_role_ids uuid[] DEFAULT '{}'::uuid[], p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_delete_media_on_expire boolean DEFAULT false, p_settings jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_creator_id     uuid;
  v_org_id         uuid;
  v_story_id       uuid;
  v_is_saas_wide   boolean := coalesce(p_is_saas_wide, false);
  v_creator_name   text;
  v_creator_avatar text;
  v_settings       jsonb;
begin
  v_creator_id := auth.uid();
  if v_creator_id is null then
    raise exception 'احراز هویت لازم است' using errcode = 'P0001';
  end if;

  v_org_id := public.current_org_id();
  if v_org_id is null then
    raise exception 'کاربر به سازمانی متصل نیست' using errcode = 'P0001';
  end if;

  if not public.current_user_has_story_permission('publish') then
    raise exception 'دسترسی انتشار استوری وجود ندارد' using errcode = 'P0001';
  end if;

  if v_is_saas_wide then
    if not (
      public.current_user_has_saas_admin_permission('publish_saas_story')
      or public.current_user_has_saas_admin_permission('publish_saas_admin_story')
    ) then
      raise exception 'دسترسی انتشار استوری SaaS وجود ندارد' using errcode = 'P0001';
    end if;

    if coalesce(p_is_saas_admins_only, false)
       and not public.current_user_has_saas_admin_permission('publish_saas_admin_story') then
      raise exception 'دسترسی انتشار استوری ویژه مدیران SaaS وجود ندارد' using errcode = 'P0001';
    end if;

    v_creator_name := 'تازه سیستم';
    v_creator_avatar := '/brand/taze-system-logo-f01.webp';
  else
    v_creator_name := nullif(btrim(coalesce(p_creator_name, '')), '');
    v_creator_avatar := nullif(btrim(coalesce(p_creator_avatar, '')), '');
  end if;

  if p_slides is null or jsonb_typeof(p_slides) <> 'array' or jsonb_array_length(p_slides) = 0 then
    raise exception 'حداقل یک اسلاید لازم است' using errcode = 'P0001';
  end if;

  v_settings := case
    when jsonb_typeof(coalesce(p_settings, '{}'::jsonb)) = 'object'
      then coalesce(p_settings, '{}'::jsonb)
    else '{}'::jsonb
  end;

  insert into public.org_stories (
    creator_id,
    org_id,
    creator_name,
    creator_avatar,
    slides,
    is_org_wide,
    is_saas_wide,
    is_saas_admins_only,
    viewer_user_ids,
    viewer_role_ids,
    mention_user_ids,
    mention_role_ids,
    expires_at,
    delete_media_on_expire,
    settings,
    published_at,
    updated_at
  ) values (
    v_creator_id,
    v_org_id,
    v_creator_name,
    v_creator_avatar,
    p_slides,
    coalesce(p_is_org_wide, true),
    v_is_saas_wide,
    coalesce(p_is_saas_admins_only, false) and v_is_saas_wide,
    coalesce(p_viewer_user_ids, '{}'),
    coalesce(p_viewer_role_ids, '{}'),
    coalesce(p_mention_user_ids, '{}'),
    coalesce(p_mention_role_ids, '{}'),
    p_expires_at,
    coalesce(p_delete_media_on_expire, false),
    v_settings,
    now(),
    now()
  )
  returning id into v_story_id;

  return v_story_id;
end;
$$;


--
-- Name: create_payroll_slip_from_wizard(jsonb, uuid[], uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_payroll_slip_from_wizard(p_payload jsonb, p_ledger_entry_ids uuid[] DEFAULT ARRAY[]::uuid[], p_bonus_request_ids uuid[] DEFAULT ARRAY[]::uuid[], p_penalty_request_ids uuid[] DEFAULT ARRAY[]::uuid[], p_advance_ids uuid[] DEFAULT ARRAY[]::uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_employee_id uuid := nullif(trim(p_payload ->> 'employee_id'), '')::uuid;
  v_period_start date := nullif(trim(p_payload ->> 'period_start'), '')::date;
  v_period_end date := nullif(trim(p_payload ->> 'period_end'), '')::date;
  v_ledger_ids uuid[] := array[]::uuid[];
  v_bonus_ids uuid[] := array[]::uuid[];
  v_penalty_ids uuid[] := array[]::uuid[];
  v_advance_ids uuid[] := array[]::uuid[];
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_scope_token uuid := gen_random_uuid();
  v_slip_id uuid;
  v_verified_count integer;
  v_requested_count integer;
  v_advance_payments jsonb := '[]'::jsonb;
  v_clean_lines jsonb := '[]'::jsonb;
  v_existing_non_advance_payments jsonb := '[]'::jsonb;
begin
  if v_org_id is null or v_employee_id is null or v_period_start is null or v_period_end is null then
    raise exception 'invalid_payroll_wizard_payload';
  end if;
  if not public.current_user_has_role_permission_entry('payroll_slips', 'edit', null, true) then
    raise exception 'payroll_creation_not_allowed';
  end if;

  select coalesce(array_agg(distinct item), array[]::uuid[]) into v_ledger_ids
  from unnest(coalesce(p_ledger_entry_ids, array[]::uuid[])) item;
  select coalesce(array_agg(distinct item), array[]::uuid[]) into v_bonus_ids
  from unnest(coalesce(p_bonus_request_ids, array[]::uuid[])) item;
  select coalesce(array_agg(distinct item), array[]::uuid[]) into v_penalty_ids
  from unnest(coalesce(p_penalty_request_ids, array[]::uuid[])) item;
  select coalesce(array_agg(distinct item), array[]::uuid[]) into v_advance_ids
  from unnest(coalesce(p_advance_ids, array[]::uuid[])) item;

  perform 1 from public.payroll_calculation_entries
  where org_id = v_org_id and employee_id = v_employee_id
    and period_start = v_period_start and period_end = v_period_end
    and status in ('draft', 'proposed') and id = any(v_ledger_ids)
  for update;
  perform 1 from public.employee_bonus_requests
  where org_id = v_org_id and employee_id = v_employee_id
    and related_payroll_slip_id is null and id = any(v_bonus_ids)
  for update;
  perform 1 from public.employee_penalty_requests
  where org_id = v_org_id and employee_id = v_employee_id
    and related_payroll_slip_id is null and id = any(v_penalty_ids)
  for update;
  perform 1 from public.employee_advances
  where org_id = v_org_id and employee_id = v_employee_id
    and related_payroll_slip_id is null and id = any(v_advance_ids)
  for update;

  select count(*) into v_requested_count
  from unnest(v_advance_ids) requested(value);
  select count(*) into v_verified_count
  from public.employee_advances advance
  where advance.org_id = v_org_id
    and advance.employee_id = v_employee_id
    and advance.id = any(v_advance_ids)
    and advance.related_payroll_slip_id is null
    and lower(coalesce(advance.status, '')) in ('paid', 'settled', 'completed', 'posted')
    and coalesce(advance.paid_amount, 0) > 0;
  if v_requested_count <> v_verified_count then raise exception 'payroll_advances_changed'; end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'row_key', 'advance_' || advance.id::text,
      'employee_advance_id', advance.id::text,
      'payment_type', 'credit',
      'status', 'paid',
      'date', advance.request_date,
      'amount', advance.paid_amount,
      'description', concat('تسویه با مساعده: ', coalesce(
        nullif(btrim(advance.system_code), ''), nullif(btrim(advance.name), ''), 'بدون عنوان'
      )),
      'is_advance_settlement', true,
      '_readonly', true,
      '_lockedFields', jsonb_build_array('employee_advance_id', 'amount', 'payment_type', 'status')
    ) order by advance.request_date, advance.id
  ), '[]'::jsonb)
  into v_advance_payments
  from public.employee_advances advance
  where advance.org_id = v_org_id
    and advance.employee_id = v_employee_id
    and advance.id = any(v_advance_ids);

  select coalesce(jsonb_agg(line.value), '[]'::jsonb) into v_clean_lines
  from jsonb_array_elements(coalesce(v_payload -> 'lines', '[]'::jsonb)) line(value)
  where lower(coalesce(line.value ->> 'key', '')) <> 'employee_advance'
    and nullif(trim(coalesce(line.value -> 'metadata' ->> 'employee_advance_id', '')), '') is null;

  select coalesce(jsonb_agg(payment.value), '[]'::jsonb) into v_existing_non_advance_payments
  from jsonb_array_elements(coalesce(v_payload -> 'payments', '[]'::jsonb)) payment(value)
  where nullif(trim(coalesce(payment.value ->> 'employee_advance_id', '')), '') is null;

  insert into public.payroll_source_mutation_scopes(scope_token, org_id, table_name, record_id)
  select v_scope_token, v_org_id, source.table_name, source.record_id
  from (
    select 'payroll_calculation_entries'::text table_name, item record_id from unnest(v_ledger_ids) item
    union all select 'employee_bonus_requests', item from unnest(v_bonus_ids) item
    union all select 'employee_penalty_requests', item from unnest(v_penalty_ids) item
    union all select 'employee_advances', item from unnest(v_advance_ids) item
  ) source
  where source.record_id is not null
  on conflict do nothing;

  v_payload := v_payload || jsonb_build_object(
    'lines', v_clean_lines,
    'payments', v_existing_non_advance_payments || v_advance_payments,
    'performance_snapshot', coalesce(v_payload -> 'performance_snapshot', '{}'::jsonb)
      || jsonb_build_object(
        'payroll_ledger_entry_ids', to_jsonb(v_ledger_ids),
        'employee_advance_ids', to_jsonb(v_advance_ids)
      )
  );

  v_slip_id := public._create_payroll_slip_from_wizard_internal(
    v_payload, v_ledger_ids, v_bonus_ids, v_penalty_ids, v_advance_ids
  );

  delete from public.payroll_source_mutation_scopes where scope_token = v_scope_token;
  return v_slip_id;
end;
$$;


--
-- Name: create_process_run_from_template(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_process_run_from_template(p_org_id uuid, p_template_id uuid, p_module_id text, p_record_id uuid, p_process_name text DEFAULT NULL::text, p_copied_mode text DEFAULT 'manual'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_template_name text;
  v_current_org_id uuid;
begin
  if p_org_id is null then
    raise exception 'سازمان اجرای فرآیند مشخص نیست.' using errcode = '42501';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    v_current_org_id := public.current_org_id();
    if auth.uid() is null
      or v_current_org_id is null
      or p_org_id <> v_current_org_id then
      raise exception 'دسترسی ایجاد فرآیند برای این سازمان وجود ندارد.' using errcode = '42501';
    end if;
  end if;

  select t.name
  into v_template_name
  from public.process_templates t
  where t.id = p_template_id
    and t.org_id = p_org_id;

  if v_template_name is null then
    raise exception 'الگوی فرآیند برای این سازمان پیدا نشد.' using errcode = 'P0001';
  end if;

  insert into public.process_runs (
    org_id,
    template_id,
    module_id,
    record_id,
    process_name,
    status,
    copied_mode,
    started_at,
    created_by,
    updated_by
  )
  values (
    p_org_id,
    p_template_id,
    p_module_id,
    p_record_id,
    coalesce(nullif(btrim(coalesce(p_process_name, '')), ''), v_template_name),
    'active',
    case when p_copied_mode in ('manual', 'auto') then p_copied_mode else 'manual' end,
    now(),
    auth.uid(),
    auth.uid()
  )
  returning id into v_run_id;

  if p_record_id is not null
    and nullif(btrim(coalesce(p_module_id, '')), '') is not null then
    insert into public.process_run_links (
      org_id,
      process_run_id,
      module_id,
      record_id,
      is_primary
    )
    values (
      p_org_id,
      v_run_id,
      p_module_id,
      p_record_id,
      true
    )
    on conflict (process_run_id, module_id, record_id) do update
    set org_id = excluded.org_id,
        is_primary = true;
  end if;

  insert into public.process_run_stages (
    process_run_id,
    template_stage_id,
    stage_name,
    sort_order,
    status,
    assignee_user_id,
    assignee_role_id,
    wage,
    process_node_key,
    process_lane_key,
    metadata
  )
  select
    v_run_id,
    s.id,
    s.stage_name,
    s.sort_order,
    s.default_status,
    s.default_assignee_id,
    s.default_assignee_role_id,
    s.wage,
    coalesce(nullif(s.process_node_key, ''), nullif(s.metadata ->> 'process_node_key', '')),
    coalesce(nullif(s.process_lane_key, ''), nullif(s.metadata ->> 'process_lane_key', ''), 'lane_1'),
    s.metadata
  from public.process_template_stages s
  where s.template_id = p_template_id
  order by
    coalesce(nullif(s.process_lane_key, ''), nullif(s.metadata ->> 'process_lane_key', ''), 'lane_1'),
    s.sort_order,
    s.created_at;

  return v_run_id;
end;
$$;


--
-- Name: create_saas_sales_invoice_for_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_saas_sales_invoice_for_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  seller_org uuid;
  tenant_name text;
  total numeric := greatest(coalesce(new.total_irt,0),0);
  item_rows jsonb := coalesce(new.items,'[]'::jsonb);
  payment_row jsonb;
begin
  if new.status <> 'paid' or (tg_op='UPDATE' and old.status='paid') or total<=0 then return new; end if;
  select o.id into seller_org from public.organizations o where public.org_is_saas_admin(o.id) order by o.created_at limit 1;
  if seller_org is null then return new; end if;
  if exists(select 1 from public.invoices i where i.org_id=seller_org and coalesce(i.tags::text,'') like '%' || new.id::text || '%') then return new; end if;
  select name into tenant_name from public.organizations where id=new.org_id;
  payment_row := jsonb_build_object('payment_type',case when coalesce(new.metadata->>'payment_method','')='billing_wallet' then 'wallet' else 'online' end,'amount',total,'date',current_date,'note','دریافت بابت سفارش حساب SaaS','saas_order_id',new.id::text,'payment_transaction_id',new.payment_transaction_id::text);
  insert into public.invoices(org_id,name,invoice_date,status,tags,"invoiceItems",payments,total_invoice_amount,total_received_amount,remaining_balance,created_by,updated_by)
  values(seller_org,'فاکتور فروش حساب ' || coalesce(nullif(tenant_name,''),'سازمان'),current_date,'settled',jsonb_build_array(new.id::text),item_rows,jsonb_build_array(payment_row),total,total,0,new.created_by,new.created_by);
  return new;
exception when undefined_column then
  -- در نسخه‌های بسیار قدیمی که tags هنوز وجود ندارد، ثبت سفارش نباید شکست بخورد.
  return new;
end;
$$;


--
-- Name: create_saas_sales_invoice_for_subscription(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_saas_sales_invoice_for_subscription() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare seller_org uuid; tenant_name text; total numeric := greatest(coalesce(new.total_irt,0),0); payment_row jsonb;
begin
  if new.status <> 'paid' or (tg_op='UPDATE' and old.status='paid') or total<=0 then return new; end if;
  select o.id into seller_org from public.organizations o where public.org_is_saas_admin(o.id) order by o.created_at limit 1;
  if seller_org is null then return new; end if;
  if exists(select 1 from public.invoices i where i.org_id=seller_org and coalesce(i.tags::text,'') like '%' || new.id::text || '%') then return new; end if;
  select name into tenant_name from public.organizations where id=new.org_id;
  payment_row := jsonb_build_object('payment_type','online','amount',total,'date',current_date,'note','دریافت بابت تمدید اشتراک SaaS','saas_subscription_invoice_id',new.id::text,'payment_transaction_id',new.payment_transaction_id::text);
  insert into public.invoices(org_id,name,invoice_date,status,tags,"invoiceItems",payments,total_invoice_amount,total_received_amount,remaining_balance,created_by,updated_by)
  values(seller_org,'فاکتور تمدید حساب ' || coalesce(nullif(tenant_name,''),'سازمان'),current_date,'settled',jsonb_build_array(new.id::text),jsonb_build_array(jsonb_build_object('title','تمدید اشتراک','quantity',1,'unit_price',total,'total',total)),jsonb_build_array(payment_row),total,total,0,null,null);
  return new;
exception when undefined_column then return new;
end;
$$;


--
-- Name: create_web_form_link_token(uuid, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_web_form_link_token(p_web_form_id uuid, p_target_module_id text DEFAULT NULL::text, p_related_module_id text DEFAULT NULL::text, p_related_record_id uuid DEFAULT NULL::uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_form public.web_forms%rowtype;
  v_token text;
  v_row public.web_form_link_tokens%rowtype;
begin
  if auth.uid() is null then
    raise exception 'WEB_FORM_LINK_AUTH_REQUIRED';
  end if;

  if v_org_id is null then
    raise exception 'WEB_FORM_LINK_ORG_REQUIRED';
  end if;

  select *
    into v_form
  from public.web_forms
  where id = p_web_form_id
    and org_id = v_org_id
  limit 1;

  if v_form.id is null then
    raise exception 'WEB_FORM_NOT_FOUND';
  end if;

  v_token := substr(
    encode(sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text as bytea)), 'hex'),
    1,
    48
  );

  insert into public.web_form_link_tokens (
    org_id,
    web_form_id,
    target_module_id,
    related_module_id,
    related_record_id,
    access_token,
    expires_at,
    created_by
  )
  values (
    v_org_id,
    v_form.id,
    nullif(trim(coalesce(p_target_module_id, v_form.target_module_id, '')), ''),
    nullif(trim(coalesce(p_related_module_id, '')), ''),
    p_related_record_id,
    v_token,
    coalesce(p_expires_at, now() + interval '30 days'),
    auth.uid()
  )
  returning * into v_row;

  return jsonb_build_object(
    'id', v_row.id,
    'token', v_row.access_token,
    'expires_at', v_row.expires_at,
    'web_form_id', v_row.web_form_id,
    'target_module_id', v_row.target_module_id,
    'related_module_id', v_row.related_module_id,
    'related_record_id', v_row.related_record_id
  );
end;
$$;


--
-- Name: create_workflow_org_story(uuid, uuid, text, text, jsonb, boolean, uuid[], uuid[], uuid[], uuid[], timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_workflow_org_story(p_org_id uuid, p_creator_id uuid DEFAULT NULL::uuid, p_creator_name text DEFAULT NULL::text, p_creator_avatar text DEFAULT NULL::text, p_slides jsonb DEFAULT '[]'::jsonb, p_is_org_wide boolean DEFAULT true, p_viewer_user_ids uuid[] DEFAULT '{}'::uuid[], p_viewer_role_ids uuid[] DEFAULT '{}'::uuid[], p_mention_user_ids uuid[] DEFAULT '{}'::uuid[], p_mention_role_ids uuid[] DEFAULT '{}'::uuid[], p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_is_saas_wide boolean DEFAULT false, p_is_saas_admins_only boolean DEFAULT false, p_delete_media_on_expire boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_creator_profile record;
  v_creator_name    text;
  v_creator_avatar  text;
  v_story_id        uuid;
begin
  if p_org_id is null then
    raise exception 'سازمان استوری مشخص نیست' using errcode = 'P0001';
  end if;

  if not public.current_user_can_create_workflow_story(p_org_id, p_creator_id) then
    raise exception 'اجازه انتشار استوری خودکار وجود ندارد' using errcode = 'P0001';
  end if;

  if p_slides is null or jsonb_typeof(p_slides) <> 'array' or jsonb_array_length(p_slides) = 0 then
    raise exception 'حداقل یک اسلاید لازم است' using errcode = 'P0001';
  end if;

  if p_creator_id is not null then
    select id, full_name, email, mobile_1, avatar_url
      into v_creator_profile
    from public.profiles
    where id = p_creator_id
      and org_id = p_org_id
    limit 1;

    if v_creator_profile.id is null then
      raise exception 'منتشرکننده انتخاب‌شده در این سازمان پیدا نشد' using errcode = 'P0001';
    end if;
  end if;

  if coalesce(p_is_saas_wide, false) then
    if auth.role() <> 'service_role' and not (
      public.current_user_has_saas_admin_permission('publish_saas_story')
      or public.current_user_has_saas_admin_permission('publish_saas_admin_story')
    ) then
      raise exception 'دسترسی انتشار استوری SaaS وجود ندارد' using errcode = 'P0001';
    end if;

    v_creator_name := 'تازه سیستم';
    v_creator_avatar := '/brand/taze-system-logo-f01.webp';
  else
    v_creator_name := nullif(btrim(coalesce(p_creator_name, '')), '');
    if v_creator_name is null then
      if p_creator_id is null then
        v_creator_name := 'سیستم';
      else
        v_creator_name := coalesce(
          nullif(btrim(coalesce(v_creator_profile.full_name, '')), ''),
          nullif(btrim(coalesce(v_creator_profile.email, '')), ''),
          nullif(btrim(coalesce(v_creator_profile.mobile_1, '')), ''),
          'کاربر بدون نام'
        );
      end if;
    end if;

    v_creator_avatar := nullif(btrim(coalesce(p_creator_avatar, '')), '');
    if v_creator_avatar is null and p_creator_id is not null then
      v_creator_avatar := nullif(btrim(coalesce(v_creator_profile.avatar_url, '')), '');
    end if;
  end if;

  insert into public.org_stories (
    org_id,
    creator_id,
    creator_name,
    creator_avatar,
    slides,
    is_org_wide,
    is_saas_wide,
    is_saas_admins_only,
    viewer_user_ids,
    viewer_role_ids,
    mention_user_ids,
    mention_role_ids,
    expires_at,
    delete_media_on_expire,
    published_at,
    updated_at
  ) values (
    p_org_id,
    p_creator_id,
    v_creator_name,
    v_creator_avatar,
    p_slides,
    coalesce(p_is_org_wide, true),
    coalesce(p_is_saas_wide, false),
    coalesce(p_is_saas_admins_only, false) and coalesce(p_is_saas_wide, false),
    coalesce(p_viewer_user_ids, '{}'),
    coalesce(p_viewer_role_ids, '{}'),
    coalesce(p_mention_user_ids, '{}'),
    coalesce(p_mention_role_ids, '{}'),
    p_expires_at,
    coalesce(p_delete_media_on_expire, false),
    now(),
    now()
  )
  returning id into v_story_id;

  return v_story_id;
end;
$$;


