--
-- Name: current_user_can_create_workflow_story(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_can_create_workflow_story(p_org_id uuid, p_creator_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_creator_exists boolean := false;
begin
  if p_org_id is null then
    return false;
  end if;

  if p_creator_id is not null then
    select exists (
      select 1
      from public.profiles
      where id = p_creator_id
        and org_id = p_org_id
    ) into v_creator_exists;

    if not v_creator_exists then
      return false;
    end if;
  end if;

  if auth.role() = 'service_role' then
    return true;
  end if;

  if auth.uid() is null or public.current_org_id() is null or public.current_org_id() <> p_org_id then
    return false;
  end if;

  return public.current_user_has_story_permission('publish')
    or public.current_user_has_role_permission_entry('__workflows', 'edit', null, true);
end;
$$;


