--
-- Name: current_user_can_manage_org_integrations(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_can_manage_org_integrations(p_write boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare member record; settings jsonb; org uuid:=public.current_org_id();
begin
 if org is null or auth.uid() is null then return false; end if;
 select m.is_owner,m.software_role,m.role_id,r.id as valid_role,r.permissions into member
 from public.user_organization_memberships m left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
 where m.org_id=org and m.user_id=auth.uid() and m.is_active limit 1;
 if not found then return false; end if;
 if p_write and exists(select 1 from public.saas_org_settings where org_id=org and is_readonly) then return false; end if;
 if member.is_owner then return true; end if;
 if lower(coalesce(member.software_role,'')) not in ('super_admin','admin','manager') then return false; end if;
 if member.role_id is not null and member.valid_role is null then return false; end if;
 settings:=coalesce(member.permissions->'__settings_tabs','{}');
 return settings->'view' is distinct from 'false'::jsonb
   and settings->'fields'->'connections' is distinct from 'false'::jsonb
   and (not p_write or settings->'edit' is distinct from 'false'::jsonb);
end; $$;


--
-- Name: current_user_can_module_field(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_can_module_field(p_module text, p_action text, p_field text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare permission jsonb; field_permission jsonb; root_action text;
begin
  if auth.uid() is null or public.current_org_id() is null or p_module is null or p_action is null or p_action not in ('view','create','edit','delete') then return false; end if;
  select r.permissions->p_module into permission
    from public.user_organization_memberships m join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
    where m.user_id=auth.uid() and m.org_id=public.current_org_id() and m.is_active limit 1;
  if not found then return false; end if;
  permission:=coalesce(permission,'{}');
  if permission->'view'='false'::jsonb then return false; end if;
  root_action:=case when p_field is not null and p_action='delete' then 'edit' else p_action end;
  if root_action='create' then
    if coalesce(permission->'create',permission->'edit','true')='false'::jsonb then return false; end if;
  elsif permission->root_action='false'::jsonb then return false;
  end if;
  if p_field is null then return true; end if;
  field_permission:=coalesce(permission->'field_actions'->p_field,'{}');
  return coalesce(permission->'fields'->p_field,'true')<>'false'::jsonb
    and coalesce(field_permission->'view','true')<>'false'::jsonb
    and coalesce(field_permission->p_action,'true')<>'false'::jsonb;
end $$;


