--
-- Name: decide_billboard_status_change(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_billboard_status_change(p_change_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_change public.billboard_status_changes%rowtype;
  v_run_id uuid;
  v_initial_nodes text[];
begin
  if v_org_id is null or auth.uid() is null then raise exception 'سازمان یا کاربر جاری معتبر نیست.'; end if;
  if not public.current_org_has_plan_module('billboards', false) then raise exception 'ماژول تبلیغات محیطی برای سازمان جاری فعال نیست.' using errcode = '42501'; end if;
  if not public.current_org_has_plan_feature('billboard_status_management', true) or not public.can_manage_billboard_status_change('approve') then raise exception 'اجازه تأیید تغییر وضعیت ندارید.'; end if;
  select * into v_change from public.billboard_status_changes where id = p_change_id and org_id = v_org_id for update;
  if not found then raise exception 'درخواست تغییر وضعیت پیدا نشد.'; end if;
  if v_change.request_status <> 'pending_approval' then raise exception 'این درخواست قبلاً تعیین تکلیف شده است.'; end if;
  if lower(trim(coalesce(p_decision, ''))) = 'reject' then
    if nullif(trim(coalesce(p_note, '')), '') is null then raise exception 'دلیل رد درخواست الزامی است.'; end if;
    update public.billboard_status_changes set request_status = 'rejected', approved_by = auth.uid(), approved_at = now(), approval_note = trim(p_note), updated_at = now(), updated_by = auth.uid() where id = v_change.id and org_id = v_org_id;
    return v_change.id;
  end if;
  if lower(trim(coalesce(p_decision, ''))) <> 'approve' then raise exception 'تصمیم معتبر نیست.'; end if;
  if v_change.application_mode = 'main_status' and exists (select 1 from public.billboards where id = v_change.billboard_id and org_id = v_org_id and status is distinct from v_change.source_status) then
    update public.billboard_status_changes set request_status = 'needs_review', approved_by = auth.uid(), approved_at = now(), approval_note = coalesce(nullif(trim(p_note), ''), 'وضعیت تابلو پس از ثبت درخواست تغییر کرده است.'), updated_at = now(), updated_by = auth.uid() where id = v_change.id and org_id = v_org_id;
    return v_change.id;
  end if;
  perform public.apply_billboard_status_change(v_change.id, v_org_id, auth.uid(), false, p_note);
  if jsonb_typeof(v_change.process_template_snapshot -> 'template') = 'object' and v_change.process_template_snapshot -> 'template' <> '{}'::jsonb then
    v_run_id := public.create_billboard_status_change_process_run(v_change.id);
    select array_agg(process_node_key) into v_initial_nodes from (select distinct on (coalesce(process_lane_key, 'lane_1')) process_node_key from public.process_run_stages where process_run_id = v_run_id order by coalesce(process_lane_key, 'lane_1'), sort_order asc) x;
    if coalesce(array_length(v_initial_nodes, 1), 0) > 0 then perform public.activate_process_run_nodes(v_org_id, v_run_id, v_initial_nodes, auth.uid()); end if;
    update public.billboard_status_changes set process_run_id = v_run_id where id = v_change.id and org_id = v_org_id;
  end if;
  return v_change.id;
end;
$$;


--
-- Name: delete_current_saas_pending_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_current_saas_pending_order(p_order_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or public.current_org_id() is null then raise exception 'organization_access_denied' using errcode='42501'; end if;
  if not exists (select 1 from public.user_organization_memberships m where m.org_id=public.current_org_id() and m.user_id=auth.uid() and m.is_active and (m.is_owner or m.software_role='admin')) then raise exception 'organization_admin_required' using errcode='42501'; end if;
  if exists (select 1 from public.payment_transactions tx where tx.org_id=public.current_org_id() and tx.purpose='saas_account_order'
    and tx.metadata->>'saas_order_id'=p_order_id::text and tx.status in ('pending','redirected')) then raise exception 'saas_order_payment_in_progress'; end if;
  delete from public.saas_orders where id=p_order_id and org_id=public.current_org_id() and status='pending_payment' and payment_transaction_id is null;
  return found;
end $$;


--
-- Name: delete_module_records_with_cleanup(text, text, uuid[], jsonb, jsonb, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_module_records_with_cleanup(p_module_id text, p_source_table text, p_record_ids uuid[], p_relation_fields jsonb DEFAULT '[]'::jsonb, p_options jsonb DEFAULT '{}'::jsonb, p_deleted_by uuid DEFAULT auth.uid(), p_deleted_by_name text DEFAULT NULL::text, p_org_id uuid DEFAULT public.current_org_id()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_source_table text;
  v_module_id text := trim(coalesce(p_module_id, ''));
  v_record_id uuid;
  v_snapshot jsonb;
  v_stored_snapshot jsonb;
  v_delete_bundle jsonb;
  v_effective_org_id uuid := coalesce(p_org_id, public.current_org_id());
  v_record_title text;
  v_options jsonb := coalesce(p_options, '{}'::jsonb);
  v_delete_payments boolean := coalesce((v_options->>'deletePayments')::boolean, true);
  v_delete_related_activities boolean := coalesce((v_options->>'deleteRelatedActivities')::boolean, false);
  v_delete_files boolean := coalesce((v_options->>'deleteFiles')::boolean, false);
  v_process_mode text := lower(trim(coalesce(v_options->>'processMode', 'all')));
  v_replacement_id uuid := nullif(trim(coalesce(v_options->>'replacementRecordId', '')), '')::uuid;
  v_process_run_ids uuid[];
  v_runs_to_delete uuid[];
  v_runs_to_keep uuid[];
  v_direct_task_ids uuid[];
  v_payment_operation_ids uuid[];
  v_file_bundle jsonb;
  v_count integer := 0;
  v_result jsonb := jsonb_build_object('deleted_count', 0);
  v_run_id uuid;
  v_primary_link record;
begin
  if v_effective_org_id is null then
    raise exception 'سازمان جاری شناسایی نشد.';
  end if;

  v_source_table := public.resolve_recycle_bin_source_table(p_source_table);
  if v_source_table is null then
    raise exception 'منبع سطل بازیافت معتبر نیست: %', p_source_table;
  end if;

  if v_process_mode not in ('all', 'incomplete', 'none') then
    v_process_mode := 'all';
  end if;

  foreach v_record_id in array coalesce(p_record_ids, array[]::uuid[])
  loop
    execute format(
      'select to_jsonb(t) from public.%I t where t.id = $1',
      v_source_table
    )
    into v_snapshot
    using v_record_id;

    if v_snapshot is null then
      continue;
    end if;

    v_record_title := public.recycle_bin_record_title(v_snapshot);
    v_stored_snapshot := v_snapshot;
    v_delete_bundle := '{}'::jsonb;

    select coalesce(array_agg(distinct r.id), array[]::uuid[])
    into v_process_run_ids
    from (
      select pr.id
      from public.process_runs pr
      where pr.org_id = v_effective_org_id
        and pr.module_id = v_module_id
        and pr.record_id = v_record_id
      union
      select prl.process_run_id
      from public.process_run_links prl
      where prl.org_id = v_effective_org_id
        and prl.module_id = v_module_id
        and prl.record_id = v_record_id
    ) r;

    if v_process_mode = 'all' then
      v_runs_to_delete := v_process_run_ids;
    elsif v_process_mode = 'incomplete' then
      select coalesce(array_agg(id), array[]::uuid[])
      into v_runs_to_delete
      from public.process_runs
      where org_id = v_effective_org_id
        and id = any(coalesce(v_process_run_ids, array[]::uuid[]))
        and lower(trim(coalesce(status, ''))) not in ('completed', 'canceled', 'cancelled');
    else
      v_runs_to_delete := array[]::uuid[];
    end if;

    select coalesce(array_agg(id), array[]::uuid[])
    into v_runs_to_keep
    from public.process_runs
    where org_id = v_effective_org_id
      and id = any(coalesce(v_process_run_ids, array[]::uuid[]))
      and not (id = any(coalesce(v_runs_to_delete, array[]::uuid[])));

    if v_delete_payments then
      select coalesce(array_agg(distinct cbo.id), array[]::uuid[])
      into v_payment_operation_ids
      from public.cash_bank_operations cbo
      where cbo.org_id = v_effective_org_id
        and (
          (v_module_id = 'invoices' and cbo.sales_invoice_id = v_record_id)
          or (v_module_id = 'purchase_invoices' and cbo.purchase_invoice_id = v_record_id)
          or (v_module_id = 'expense_documents' and cbo.expense_document_id = v_record_id)
          or (v_module_id = 'employee_advances' and cbo.employee_advance_id = v_record_id)
          or (v_module_id = 'payroll_slips' and cbo.payroll_slip_id = v_record_id)
          or (
            trim(coalesce(cbo.metadata->>'source_table', '')) = v_module_id
            and trim(coalesce(cbo.metadata->>'source_record_id', '')) = v_record_id::text
          )
        );

      if coalesce(array_length(v_payment_operation_ids, 1), 0) > 0 then
        perform public.move_records_to_recycle_bin(
          'cash_bank_operations',
          'cash_bank_operations',
          v_payment_operation_ids,
          p_deleted_by,
          p_deleted_by_name,
          v_effective_org_id
        );
        v_delete_bundle := v_delete_bundle || jsonb_build_object('deleted_payment_operation_ids', to_jsonb(v_payment_operation_ids));
      end if;
    else
      perform public.detach_cash_bank_operations_for_source(v_module_id, v_record_id, v_record_title);
      v_stored_snapshot := public.recycle_bin_strip_payments(v_module_id, v_stored_snapshot);
    end if;

    if v_delete_files then
      v_file_bundle := public.collect_record_file_bundle(v_module_id, v_record_id);
      if v_file_bundle <> '{}'::jsonb then
        v_delete_bundle := v_delete_bundle || jsonb_build_object('record_file_bundle', v_file_bundle);
      end if;

      if to_regclass('public.record_files') is not null then
        delete from public.record_files
        where (
          module_id = v_module_id
          and trim(coalesce(record_id, '')) = v_record_id::text
        ) or (
          source_module_id = v_module_id
          and trim(coalesce(source_record_id, '')) = v_record_id::text
        );
      end if;

      if to_regclass('public.file_entries') is not null then
        delete from public.file_entries
        where module_id = v_module_id
          and record_id = v_record_id;
      end if;

      if to_regclass('public.file_folders') is not null then
        delete from public.file_folders
        where module_id = v_module_id
          and record_id = v_record_id;
      end if;
    end if;

    if coalesce(array_length(v_runs_to_delete, 1), 0) > 0 then
      if v_delete_related_activities then
        perform public.move_records_to_recycle_bin(
          'process_runs',
          'process_runs',
          v_runs_to_delete,
          p_deleted_by,
          p_deleted_by_name,
          v_effective_org_id
        );
      else
        perform public.delete_process_runs_keep_tasks(
          v_runs_to_delete,
          p_deleted_by,
          p_deleted_by_name,
          v_effective_org_id
        );
      end if;

      v_delete_bundle := v_delete_bundle || jsonb_build_object('deleted_process_run_ids', to_jsonb(v_runs_to_delete));
      v_stored_snapshot := public.recycle_bin_strip_process_fields(v_stored_snapshot);
    end if;

    select coalesce(array_agg(distinct t.id), array[]::uuid[])
    into v_direct_task_ids
    from public.tasks t
    where t.org_id = v_effective_org_id
      and t.source_module_id = v_module_id
      and t.source_record_id = v_record_id
      and not (t.process_run_id = any(coalesce(v_runs_to_delete, array[]::uuid[])));

    if v_delete_related_activities and coalesce(array_length(v_direct_task_ids, 1), 0) > 0 then
      perform public.move_records_to_recycle_bin(
        'tasks',
        'tasks',
        v_direct_task_ids,
        p_deleted_by,
        p_deleted_by_name,
        v_effective_org_id
      );
      v_delete_bundle := v_delete_bundle || jsonb_build_object('deleted_task_ids', to_jsonb(v_direct_task_ids));
    end if;

    if v_replacement_id is not null then
      perform public.merge_module_record_references(
        v_module_id,
        v_replacement_id,
        array[v_record_id],
        coalesce(p_relation_fields, '[]'::jsonb)
      );

      if not v_delete_files and to_regclass('public.file_entries') is not null then
        update public.file_entries
        set record_id = v_replacement_id
        where module_id = v_module_id
          and record_id = v_record_id;

        update public.file_entries
        set source_record_id = v_replacement_id
        where source_module_id = v_module_id
          and source_record_id = v_record_id;
      end if;

      if not v_delete_files and to_regclass('public.file_folders') is not null then
        update public.file_folders
        set record_id = v_replacement_id
        where module_id = v_module_id
          and record_id = v_record_id;
      end if;

      if not v_delete_related_activities then
        update public.tasks
        set source_record_id = v_replacement_id
        where org_id = v_effective_org_id
          and source_module_id = v_module_id
          and source_record_id = v_record_id;
      end if;
    end if;

    if coalesce(array_length(v_runs_to_keep, 1), 0) > 0 then
      foreach v_run_id in array v_runs_to_keep
      loop
        if v_replacement_id is not null then
          delete from public.process_run_links d
          where d.org_id = v_effective_org_id
            and d.process_run_id = v_run_id
            and d.module_id = v_module_id
            and d.record_id = v_record_id
            and exists (
              select 1
              from public.process_run_links s
              where s.org_id = d.org_id
                and s.process_run_id = d.process_run_id
                and s.module_id = v_module_id
                and s.record_id = v_replacement_id
            );

          update public.process_run_links
          set record_id = v_replacement_id
          where org_id = v_effective_org_id
            and process_run_id = v_run_id
            and module_id = v_module_id
            and record_id = v_record_id;

          update public.process_runs
          set module_id = v_module_id,
              record_id = v_replacement_id
          where org_id = v_effective_org_id
            and id = v_run_id
            and module_id = v_module_id
            and record_id = v_record_id;
        else
          delete from public.process_run_links
          where org_id = v_effective_org_id
            and process_run_id = v_run_id
            and module_id = v_module_id
            and record_id = v_record_id;

          update public.process_runs
          set module_id = coalesce((
                select l.module_id
                from public.process_run_links l
                where l.org_id = v_effective_org_id
                  and l.process_run_id = v_run_id
                order by l.is_primary desc, l.created_at asc, l.id asc
                limit 1
              ), null),
              record_id = coalesce((
                select l.record_id
                from public.process_run_links l
                where l.org_id = v_effective_org_id
                  and l.process_run_id = v_run_id
                order by l.is_primary desc, l.created_at asc, l.id asc
                limit 1
              ), null)
          where org_id = v_effective_org_id
            and id = v_run_id
            and module_id = v_module_id
            and record_id = v_record_id;
        end if;
      end loop;
    end if;

    if v_delete_bundle <> '{}'::jsonb then
      v_stored_snapshot := v_stored_snapshot || jsonb_build_object('__delete_bundle', v_delete_bundle);
    end if;

    delete from public.recycle_bin_records
    where source_table = v_source_table
      and source_record_id = v_record_id;

    insert into public.recycle_bin_records (
      org_id, module_id, source_table, source_record_id, record_title,
      snapshot, deleted_by, deleted_by_name
    )
    values (
      v_effective_org_id,
      v_module_id,
      v_source_table,
      v_record_id,
      public.recycle_bin_record_title(v_stored_snapshot),
      v_stored_snapshot,
      p_deleted_by,
      nullif(trim(coalesce(p_deleted_by_name, '')), '')
    );

    execute format(
      'delete from public.%I where id = $1',
      v_source_table
    )
    using v_record_id;

    v_count := v_count + 1;
  end loop;

  v_result := jsonb_build_object(
    'deleted_count', v_count,
    'module_id', v_module_id,
    'source_table', v_source_table
  );
  return v_result;
end;
$_$;


--
-- Name: delete_process_run_stages_v2_safe(uuid[], uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_process_run_stages_v2_safe(p_stage_ids uuid[], p_deleted_by uuid DEFAULT auth.uid(), p_deleted_by_name text DEFAULT NULL::text, p_org_id uuid DEFAULT public.current_org_id()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_current_org_id uuid := public.current_org_id();
  v_effective_org_id uuid := coalesce(p_org_id, public.current_org_id());
  v_stage record;
  v_deleted integer := 0;
begin
  if auth.uid() is null
    or v_effective_org_id is null
    or v_current_org_id is null
    or v_effective_org_id <> v_current_org_id then
    raise exception 'دسترسی حذف مرحله فرآیند برای این سازمان وجود ندارد.' using errcode = '42501';
  end if;

  for v_stage in
    select
      s.*,
      r.org_id,
      r.process_group_id
    from public.process_run_stages s
    join public.process_runs r on r.id = s.process_run_id
    where s.id = any(coalesce(p_stage_ids, array[]::uuid[]))
      and r.org_id = v_effective_org_id
  loop
    insert into public.process_v2_deleted_stage_marks (
      org_id,
      process_run_stage_id,
      process_run_id,
      process_group_id,
      template_stage_id,
      draft_stage_key,
      process_node_key,
      process_lane_key,
      deleted_by,
      deleted_by_name,
      deleted_at
    )
    values (
      v_effective_org_id,
      v_stage.id,
      v_stage.process_run_id,
      nullif(btrim(coalesce(v_stage.process_group_id, '')), ''),
      v_stage.template_stage_id,
      coalesce(
        nullif(btrim(coalesce(v_stage.metadata ->> 'draft_stage_key', '')), ''),
        nullif(btrim(coalesce(v_stage.metadata ->> 'draft_stage_id', '')), '')
      ),
      coalesce(
        nullif(btrim(coalesce(v_stage.process_node_key, '')), ''),
        nullif(btrim(coalesce(v_stage.metadata ->> 'process_node_key', '')), '')
      ),
      coalesce(
        nullif(btrim(coalesce(v_stage.process_lane_key, '')), ''),
        nullif(btrim(coalesce(v_stage.metadata ->> 'process_lane_key', '')), '')
      ),
      p_deleted_by,
      nullif(btrim(coalesce(p_deleted_by_name, '')), ''),
      now()
    )
    on conflict (org_id, process_run_stage_id) do update
    set process_run_id = excluded.process_run_id,
        process_group_id = excluded.process_group_id,
        template_stage_id = excluded.template_stage_id,
        draft_stage_key = excluded.draft_stage_key,
        process_node_key = excluded.process_node_key,
        process_lane_key = excluded.process_lane_key,
        deleted_by = excluded.deleted_by,
        deleted_by_name = excluded.deleted_by_name,
        deleted_at = excluded.deleted_at;

    v_deleted := v_deleted + 1;
  end loop;

  return v_deleted;
end;
$$;


--
-- Name: delete_process_runs_keep_tasks(uuid[], uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_process_runs_keep_tasks(p_run_ids uuid[], p_deleted_by uuid DEFAULT auth.uid(), p_deleted_by_name text DEFAULT NULL::text, p_org_id uuid DEFAULT public.current_org_id()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_org_id uuid := p_org_id;
  v_run_snapshot jsonb;
  v_stage_snapshot jsonb;
  v_count integer := 0;
begin
  if v_org_id is null then
    v_org_id := public.current_org_id();
  end if;
  if v_org_id is null then
    raise exception 'سازمان جاری شناسایی نشد.';
  end if;

  foreach v_run_id in array coalesce(p_run_ids, array[]::uuid[])
  loop
    select to_jsonb(r)
    into v_run_snapshot
    from public.process_runs r
    where r.id = v_run_id
      and r.org_id = v_org_id;

    if v_run_snapshot is null then
      continue;
    end if;

    for v_stage_snapshot in
      select to_jsonb(s)
      from public.process_run_stages s
      where s.process_run_id = v_run_id
    loop
      delete from public.recycle_bin_records
      where source_table = 'process_run_stages'
        and source_record_id = (v_stage_snapshot->>'id')::uuid;

      insert into public.recycle_bin_records (
        org_id, module_id, source_table, source_record_id, record_title,
        snapshot, deleted_by, deleted_by_name
      )
      values (
        v_org_id,
        'process_run_stages',
        'process_run_stages',
        (v_stage_snapshot->>'id')::uuid,
        public.recycle_bin_record_title(v_stage_snapshot),
        v_stage_snapshot,
        p_deleted_by,
        nullif(trim(coalesce(p_deleted_by_name, '')), '')
      );
      v_count := v_count + 1;
    end loop;

    update public.tasks
    set process_group_id = null,
        process_group_name = null,
        process_run_id = null,
        process_run_stage_id = null,
        recurrence_info = case
          when recurrence_info is null then null
          when jsonb_typeof(recurrence_info) <> 'object' then recurrence_info
          else recurrence_info - 'process_group' - 'process_run_id' - 'process_run_stage_id'
        end
    where org_id = v_org_id
      and (
        process_run_id = v_run_id
        or process_run_stage_id in (
          select s.id
          from public.process_run_stages s
          where s.process_run_id = v_run_id
        )
      );

    delete from public.process_run_links
    where org_id = v_org_id
      and process_run_id = v_run_id;

    delete from public.recycle_bin_records
    where source_table = 'process_runs'
      and source_record_id = v_run_id;

    insert into public.recycle_bin_records (
      org_id, module_id, source_table, source_record_id, record_title,
      snapshot, deleted_by, deleted_by_name
    )
    values (
      v_org_id,
      'process_runs',
      'process_runs',
      v_run_id,
      public.recycle_bin_record_title(v_run_snapshot),
      v_run_snapshot,
      p_deleted_by,
      nullif(trim(coalesce(p_deleted_by_name, '')), '')
    );

    delete from public.process_run_stages
    where process_run_id = v_run_id;

    delete from public.process_runs
    where id = v_run_id
      and org_id = v_org_id;

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


--
-- Name: detach_cash_bank_operations_for_source(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detach_cash_bank_operations_for_source(p_module_id text, p_record_id uuid, p_record_title text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_module_id text := trim(coalesce(p_module_id, ''));
  v_record_title text := nullif(trim(coalesce(p_record_title, '')), '');
  v_count integer := 0;
begin
  if p_record_id is null or v_module_id = '' or to_regclass('public.cash_bank_operations') is null then
    return 0;
  end if;

  if v_module_id = 'invoices' then
    update public.cash_bank_operations
    set sales_invoice_id = null,
        metadata = (coalesce(metadata, '{}'::jsonb) - 'source_table' - 'source_record_id' - 'source_block_id' - 'source_row_key')
          || jsonb_build_object(
            'is_auto_generated', false,
            'detached_source_table', v_module_id,
            'detached_source_record_id', p_record_id::text,
            'source_record_title', v_record_title
          )
    where sales_invoice_id = p_record_id;
  elsif v_module_id = 'purchase_invoices' then
    update public.cash_bank_operations
    set purchase_invoice_id = null,
        metadata = (coalesce(metadata, '{}'::jsonb) - 'source_table' - 'source_record_id' - 'source_block_id' - 'source_row_key')
          || jsonb_build_object(
            'is_auto_generated', false,
            'detached_source_table', v_module_id,
            'detached_source_record_id', p_record_id::text,
            'source_record_title', v_record_title
          )
    where purchase_invoice_id = p_record_id;
  elsif v_module_id = 'expense_documents' then
    update public.cash_bank_operations
    set expense_document_id = null,
        metadata = (coalesce(metadata, '{}'::jsonb) - 'source_table' - 'source_record_id' - 'source_block_id' - 'source_row_key')
          || jsonb_build_object(
            'is_auto_generated', false,
            'detached_source_table', v_module_id,
            'detached_source_record_id', p_record_id::text,
            'source_record_title', v_record_title
          )
    where expense_document_id = p_record_id;
  elsif v_module_id = 'employee_advances' then
    update public.cash_bank_operations
    set employee_advance_id = null,
        metadata = (coalesce(metadata, '{}'::jsonb) - 'source_table' - 'source_record_id' - 'source_block_id' - 'source_row_key')
          || jsonb_build_object(
            'is_auto_generated', false,
            'detached_source_table', v_module_id,
            'detached_source_record_id', p_record_id::text,
            'source_record_title', v_record_title
          )
    where employee_advance_id = p_record_id;
  elsif v_module_id = 'payroll_slips' then
    update public.cash_bank_operations
    set payroll_slip_id = null,
        metadata = (coalesce(metadata, '{}'::jsonb) - 'source_table' - 'source_record_id' - 'source_block_id' - 'source_row_key')
          || jsonb_build_object(
            'is_auto_generated', false,
            'detached_source_table', v_module_id,
            'detached_source_record_id', p_record_id::text,
            'source_record_title', v_record_title
          )
    where payroll_slip_id = p_record_id;
  else
    update public.cash_bank_operations
    set metadata = (coalesce(metadata, '{}'::jsonb) - 'source_table' - 'source_record_id' - 'source_block_id' - 'source_row_key')
      || jsonb_build_object(
        'is_auto_generated', false,
        'detached_source_table', v_module_id,
        'detached_source_record_id', p_record_id::text,
        'source_record_title', v_record_title
      )
    where trim(coalesce(metadata->>'source_table', '')) = v_module_id
      and trim(coalesce(metadata->>'source_record_id', '')) = p_record_id::text;
  end if;

  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
end;
$$;


--
-- Name: dismiss_user_announcement(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_user_announcement(p_announcement_id uuid, p_surface text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_surface text := public.normalize_announcement_surface(p_surface);
  v_org_id uuid := public.current_org_id();
begin
  if auth.uid() is null then raise exception 'permission denied'; end if;
  if v_surface not in ('public_site', 'user_panel', 'login_page') then raise exception 'surface is invalid'; end if;
  if not exists (select 1 from public.saas_user_announcements a where a.id = p_announcement_id and a.is_active and a.allow_dismiss) then return false; end if;
  insert into public.saas_user_announcement_dismissals(announcement_id,org_id,user_id,surface,dismissed_at)
  values(p_announcement_id,v_org_id,auth.uid(),v_surface,now())
  on conflict (announcement_id,user_id,surface) do update set org_id=excluded.org_id,dismissed_at=now();
  return true;
end;
$$;


--
-- Name: email_can_access(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_can_access(p_action text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare ctx jsonb:=public.get_current_organization_context(); root jsonb; fields jsonb;
begin
  if ctx is null or not public.current_org_has_plan_feature('organization_email',false) then return false; end if;
  root:=coalesce(ctx->'permissions'->'__communications','{}'::jsonb); fields:=coalesce(root->'fields','{}'::jsonb);
  if p_action='manage' then
    return ctx->>'role' in ('admin','super_admin','manager')
      and coalesce((ctx->'permissions'->'__settings_tabs'->>'edit')::boolean,true);
  end if;
  if coalesce((root->>'view')::boolean,true)=false or coalesce((fields->>'use_email')::boolean,true)=false then return false; end if;
  return p_action='view' or (p_action='send' and coalesce((root->>'edit')::boolean,true) and coalesce((fields->>'send_email')::boolean,true));
end;
$$;


--
-- Name: email_list_messages(text, integer, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_list_messages(p_folder text DEFAULT 'inbox'::text, p_limit integer DEFAULT 40, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_thread_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org uuid:=public.current_org_id(); result jsonb;
begin
  if not public.email_can_access('view') then raise exception 'دسترسی به صندوق ایمیل فعال نیست.' using errcode='42501'; end if;
  select coalesce(jsonb_agg(item order by item->>'message_at' desc,item->>'id' desc),'[]'::jsonb) into result from (
    select (to_jsonb(m)-'body_text')||jsonb_build_object('body_text',left(m.body_text,200),'is_read',r.message_id is not null) item
    from public.email_messages m left join public.email_message_receipts r on r.message_id=m.id and r.user_id=auth.uid() and r.org_id=v_org
    where m.org_id=v_org
      and (p_thread_id is not null and m.thread_id=p_thread_id or p_thread_id is null and (
        p_folder='all' or p_folder='inbox' and m.direction='inbound' or p_folder='sent' and m.direction='outbound'
        or p_folder='unread' and m.direction='inbound' and r.message_id is null))
      and (p_before is null or (m.message_at,m.id)<(p_before,coalesce(p_before_id,'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
    order by m.message_at desc,m.id desc limit least(greatest(p_limit,1),100)
  ) rows;
  return result;
end;
$$;


--
-- Name: email_mark_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_mark_read(p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org uuid:=public.current_org_id();
begin
  if not public.email_can_access('view') or not exists(select 1 from public.email_messages where id=p_message_id and org_id=v_org) then
    raise exception 'دسترسی به این ایمیل مجاز نیست.' using errcode='42501'; end if;
  insert into public.email_message_receipts(org_id,message_id,user_id) values(v_org,p_message_id,auth.uid())
    on conflict(message_id,user_id) do update set read_at=excluded.read_at;
end;
$$;


--
-- Name: employee_advance_payment_amount(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.employee_advance_payment_amount(p_payment jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_amount numeric := public.payroll_safe_numeric(p_payment->>'amount');
  v_total_price numeric := public.payroll_safe_numeric(p_payment->>'total_price');
  v_quantity numeric := public.payroll_safe_numeric(p_payment->>'quantity');
  v_unit_price numeric := public.payroll_safe_numeric(p_payment->>'unit_price');
begin
  if v_amount <> 0 then return abs(v_amount); end if;
  if v_total_price <> 0 then return abs(v_total_price); end if;
  if v_quantity > 0 and v_unit_price > 0 then return v_quantity * v_unit_price; end if;
  return 0;
end;
$$;


--
-- Name: enforce_internal_chat_plan_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_internal_chat_plan_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare row_data jsonb:=to_jsonb(new); meta jsonb:=coalesce(row_data->'metadata','{}');
begin
 if auth.uid() is not null and not (coalesce(meta->>'saved_message','false')='true' and coalesce(row_data->'mention_user_ids','[]'::jsonb)='[]'::jsonb and coalesce(row_data->'mention_role_ids','[]'::jsonb)='[]'::jsonb and nullif(meta->>'chat_group_id','') is null)
  and ((nullif(row_data->>'module_id','') is null and nullif(row_data->>'record_id','') is null) or nullif(meta->>'chat_group_id','') is not null)
  and not public.org_has_plan_feature(new.org_id,'internal_chat',true) then
  raise exception 'پیام‌رسانی داخلی در پلن سازمان فعال نیست.' using errcode='42501';
 end if;
 return new;
end; $$;


--
-- Name: enforce_saas_org_readonly(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_saas_org_readonly() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target_org uuid; settings_row record;
begin
  if auth.uid() is null or auth.role() = 'service_role' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    target_org := nullif(to_jsonb(old) ->> 'org_id', '')::uuid;
  else
    target_org := nullif(to_jsonb(new) ->> 'org_id', '')::uuid;
  end if;
  if target_org is null then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  select is_readonly, billing_readonly, trial_ends_at into settings_row
  from public.saas_org_settings where org_id = target_org;
  if found and (settings_row.is_readonly or settings_row.billing_readonly
    or (settings_row.trial_ends_at is not null and settings_row.trial_ends_at < now()))
    and not public.org_is_saas_admin(target_org)
    and not public.current_user_has_saas_admin_permission('edit_orgs') then
    raise exception 'saas_readonly_subscription_required';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end; $$;


--
-- Name: enforce_single_default_bank_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_single_default_bank_account() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(new.is_default, false) = true and new.org_id is not null then
    update public.bank_accounts
    set is_default = false
    where org_id = new.org_id
      and id <> coalesce(new.id, '00000000-0000-0000-0000-000000000000'::uuid)
      and is_default = true;
  end if;
  return new;
end;
$$;


--
-- Name: enqueue_ai_agent_task_run(uuid, uuid, integer, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_ai_agent_task_run(p_org_id uuid, p_workflow_id uuid, p_expected_revision integer, p_due_at timestamp with time zone, p_next_run_at timestamp with time zone, p_now timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_workflow public.workflows%rowtype;
  v_action jsonb;
  v_job_id uuid;
  v_dedupe text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'دسترسی صف اجرای ایجنت وجود ندارد.' using errcode = '42501';
  end if;
  if p_org_id is null or p_workflow_id is null or p_due_at is null or p_now is null then
    raise exception 'اطلاعات نوبت اجرای ایجنت ناقص است.' using errcode = '22023';
  end if;
  select * into v_workflow from public.workflows
  where id = p_workflow_id and org_id = p_org_id
  for update;
  if not found or not v_workflow.is_active or v_workflow.agent_task_config is null
     or v_workflow.trigger_type <> 'interval'
     or v_workflow.agent_task_revision <> p_expected_revision
     or v_workflow.agent_task_next_run_at is distinct from p_due_at
     or p_due_at > p_now then return null; end if;
  if (p_next_run_at is not null and p_next_run_at <= p_now)
     or (p_next_run_at is null and v_workflow.agent_task_config #>> '{schedule,kind}' is distinct from 'once') then
    raise exception 'موعد بعدی اجرای ایجنت معتبر نیست.' using errcode = '22023';
  end if;
  if v_workflow.created_by is null then
    raise exception 'صاحب کار خودکار مشخص نیست.' using errcode = '22023';
  end if;
  v_action := jsonb_build_object(
    'id', 'agent-task:' || v_workflow.id::text || ':' || p_expected_revision::text,
    'type', 'run_agent_task',
    'config', jsonb_build_object('workflow_id', v_workflow.id, 'task_revision', p_expected_revision)
  );
  v_dedupe := concat('agent-task:', p_org_id, ':', p_workflow_id, ':', p_expected_revision, ':', p_due_at);
  insert into public.workflow_interval_jobs (
    org_id, job_kind, dedupe_key, workflow_id, module_id, record_id, scheduled_due_at,
    action_index, is_terminal_action, max_attempts, payload
  ) values (
    p_org_id, 'workflow_action', v_dedupe, p_workflow_id, v_workflow.module_id, p_workflow_id, p_due_at,
    0, true, 1, jsonb_build_object(
      'workflow', to_jsonb(v_workflow), 'action', v_action,
      'record', jsonb_build_object('id', p_workflow_id, 'name', v_workflow.name),
      'actor_user_id', v_workflow.created_by, 'action_count', 1
    )
  ) on conflict (dedupe_key) do nothing returning id into v_job_id;
  if v_job_id is null then
    select id into v_job_id from public.workflow_interval_jobs where dedupe_key = v_dedupe and org_id = p_org_id;
  end if;
  update public.workflows set last_run_at = p_due_at,
    agent_task_next_run_at = p_next_run_at, server_queued_at = null
  where id = p_workflow_id and org_id = p_org_id;
  return v_job_id;
end;
$$;


--
-- Name: enqueue_customer_club_notifications(jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_customer_club_notifications(p_notifications jsonb, p_event_key text, p_customer_id uuid, p_context jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_org_id uuid := public.current_org_id(); v_actions jsonb;
begin
  if v_org_id is null or coalesce((p_notifications->p_event_key->>'enabled')::boolean, false) is not true then return; end if;
  v_actions := coalesce(p_notifications->p_event_key->'actions', '[]'::jsonb);
  if jsonb_typeof(v_actions) <> 'array' or jsonb_array_length(v_actions) = 0 then return; end if;
  insert into public.customer_club_notification_queue(org_id, event_key, customer_id, actions, context)
  values (v_org_id, p_event_key, p_customer_id, v_actions, coalesce(p_context, '{}'::jsonb));
end; $$;


--
-- Name: enqueue_customer_club_recipient_notifications(jsonb, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_customer_club_recipient_notifications(p_notifications jsonb, p_event_key text, p_recipient_module_id text, p_recipient_record_id uuid, p_context jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_actions jsonb;
  v_module text := lower(trim(coalesce(p_recipient_module_id, '')));
begin
  if v_org_id is null or v_module not in ('customers', 'suppliers', 'employees') or p_recipient_record_id is null
    or coalesce((p_notifications->p_event_key->>'enabled')::boolean, false) is not true then return; end if;
  v_actions := coalesce(p_notifications->p_event_key->'actions', '[]'::jsonb);
  if jsonb_typeof(v_actions) <> 'array' or jsonb_array_length(v_actions) = 0 then return; end if;
  insert into public.customer_club_notification_queue(
    org_id, event_key, customer_id, recipient_module_id, recipient_record_id, actions, context
  ) values (
    v_org_id, p_event_key,
    case when v_module = 'customers' then p_recipient_record_id else null end,
    v_module, p_recipient_record_id, v_actions, coalesce(p_context, '{}'::jsonb)
  );
end;
$$;


--
-- Name: enqueue_customer_club_reminder_actions(jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_customer_club_reminder_actions(p_notifications jsonb, p_customer_id uuid, p_context jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_action jsonb;
  v_timing jsonb;
  v_reference text;
  v_reference_at timestamptz;
  v_offset interval;
  v_available_at timestamptz;
begin
  if v_org_id is null or coalesce((p_notifications->'reminder'->>'enabled')::boolean, false) is not true then return; end if;
  for v_action in select value from jsonb_array_elements(coalesce(p_notifications->'reminder'->'actions', '[]'::jsonb)) loop
    v_timing := coalesce(v_action->'config'->'customer_club_reminder_timing', '{}'::jsonb);
    v_reference := coalesce(nullif(v_timing->>'reference', ''), 'credit_added');
    v_reference_at := case v_reference
      when 'plan_expiry' then nullif(p_context->>'plan_expires_at', '')::timestamptz
      when 'discount_expiry' then nullif(p_context->>'discount_expires_at', '')::timestamptz
      when 'credit_expiry' then nullif(p_context->>'credit_expires_at', '')::timestamptz
      else coalesce(nullif(p_context->>'credit_added_at', '')::timestamptz, now())
    end;
    if v_reference_at is null or (v_reference = 'credit_added' and coalesce(v_timing->>'direction', 'after') = 'before') then continue; end if;
    v_offset := make_interval(hours => case when coalesce(v_timing->>'unit', 'day') = 'hour' then greatest(0, coalesce((v_timing->>'value')::integer, 0)) else 0 end,
                              days => case when coalesce(v_timing->>'unit', 'day') = 'day' then greatest(0, coalesce((v_timing->>'value')::integer, 0)) else 0 end);
    v_available_at := case when coalesce(v_timing->>'direction', 'after') = 'before' then v_reference_at - v_offset else v_reference_at + v_offset end;
    insert into public.customer_club_notification_queue(org_id, event_key, customer_id, actions, context, available_at)
    values (v_org_id, 'reminder', p_customer_id, jsonb_build_array(v_action), coalesce(p_context, '{}'::jsonb), v_available_at);
  end loop;
end; $$;


--
-- Name: enqueue_saas_lifecycle_workflow_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_saas_lifecycle_workflow_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_provider uuid := public.support_provider_org_id();
  v_module text;
  v_row jsonb;
  v_old jsonb;
  v_org_name text;
  v_org_slug text;
  v_org_demo boolean;
  v_mobile text;
  v_role_title text;
  v_old_role_title text;
begin
  if v_provider is null then return new; end if;
  if tg_table_name = 'saas_org_settings' then
    v_module := 'saas_orgs';
    select name into v_org_name from public.organizations where id = new.org_id;
    select mobile into v_mobile from public.saas_onboarding_requests
      where org_id = new.org_id and status = 'provisioned'
      order by created_at desc limit 1;
    v_row := jsonb_build_object('id',new.id,'org_id',v_provider,
      'customer_org_id',new.org_id,'org_name',v_org_name,'slug',new.slug,
      'status',new.status,'plan_code',new.plan_code,'is_demo',new.is_demo,
      'resolved_host',new.resolved_host,'primary_contact_mobile',coalesce(new.primary_contact_mobile,v_mobile),
      'trial_ends_at',new.trial_ends_at,'is_readonly',new.is_readonly,
      'owner_name',new.owner_name,'owner_email',new.owner_email,
      'provisioning_source',new.provisioning_source,'provisioned_at',new.created_at);
    if tg_op = 'UPDATE' then
      v_old := jsonb_build_object('id',old.id,'org_id',v_provider,
        'customer_org_id',old.org_id,'org_name',v_org_name,'slug',old.slug,
        'status',old.status,'plan_code',old.plan_code,'is_demo',old.is_demo,
        'resolved_host',old.resolved_host,'primary_contact_mobile',coalesce(old.primary_contact_mobile,v_mobile),
        'trial_ends_at',old.trial_ends_at,'is_readonly',old.is_readonly,
        'owner_name',old.owner_name,'owner_email',old.owner_email,
        'provisioning_source',old.provisioning_source,'provisioned_at',old.created_at);
    end if;
  elsif tg_table_name = 'profiles' then
    if new.org_id is null then return new; end if;
    v_module := 'saas_users';
    select o.name,o.slug,s.is_demo into v_org_name,v_org_slug,v_org_demo
      from public.organizations o left join public.saas_org_settings s on s.org_id=o.id
      where o.id=new.org_id;
    select title into v_role_title from public.org_roles where id = new.role_id;
    v_row := jsonb_build_object('id',new.id,'org_id',v_provider,
      'customer_org_id',new.org_id,'org_name',v_org_name,'org_slug',v_org_slug,
      'is_demo',v_org_demo,'full_name',new.full_name,'email',new.email,
      'mobile',coalesce(new.mobile_1,new.mobile),'role',new.role,
      'role_id',new.role_id,'role_title',v_role_title,
      'software_role',new.role,'profile_exists',true,
      'is_active',new.is_active);
    if tg_op = 'UPDATE' then
      select title into v_old_role_title from public.org_roles where id = old.role_id;
      v_old := jsonb_build_object('id',old.id,'org_id',v_provider,
        'customer_org_id',old.org_id,'org_name',v_org_name,'org_slug',v_org_slug,
        'is_demo',v_org_demo,'full_name',old.full_name,'email',old.email,
        'mobile',coalesce(old.mobile_1,old.mobile),'role',old.role,
        'role_id',old.role_id,'role_title',v_old_role_title,
        'software_role',old.role,'profile_exists',true,
        'is_active',old.is_active);
    end if;
  elsif tg_table_name = 'saas_onboarding_requests' then
    v_module := 'saas_demo_requests';
    v_row := jsonb_build_object('id',new.id,'org_id',v_provider,
      'customer_org_id',new.org_id,'full_name',new.full_name,
      'organization_name',coalesce(new.organization_name,new.business_name),
      'mobile',new.mobile,'requested_slug',new.requested_slug,
      'demo_url',new.demo_url,
      'status',new.status,'failure_code',new.failure_code,
      'is_demo_request',new.is_demo_request,'industry',new.industry,
      'email',new.email,'business_name',new.business_name,
      'employee_count_band',new.employee_count_band,
      'discovery_source',new.discovery_source,'notes',new.notes,
      'provision_attempts',new.provision_attempts,
      'failure_message',new.failure_message,
      'created_at',new.created_at,'updated_at',new.updated_at);
    if tg_op = 'UPDATE' then
      v_old := jsonb_build_object('id',old.id,'org_id',v_provider,
        'customer_org_id',old.org_id,'full_name',old.full_name,
        'organization_name',coalesce(old.organization_name,old.business_name),
        'mobile',old.mobile,'requested_slug',old.requested_slug,
        'demo_url',old.demo_url,
        'status',old.status,'failure_code',old.failure_code,
        'is_demo_request',old.is_demo_request,'industry',old.industry,
        'email',old.email,'business_name',old.business_name,
        'employee_count_band',old.employee_count_band,
        'discovery_source',old.discovery_source,'notes',old.notes,
        'provision_attempts',old.provision_attempts,
        'failure_message',old.failure_message,
        'created_at',old.created_at,'updated_at',old.updated_at);
    end if;
  else
    return new;
  end if;
  if v_old is not distinct from v_row then return new; end if;
  if not exists (
    select 1 from public.workflows w
    where w.org_id=v_provider and w.is_active=true
      and (w.module_id=v_module or v_module=any(coalesce(w.module_ids,'{}'::text[])))
      and w.trigger_type in ('on_create','on_upsert')
  ) then return new; end if;
  insert into public.workflow_event_queue
    (org_id,source_table,record_id,event_type,record_snapshot,previous_snapshot,actor_user_id,priority)
  values (v_provider,v_module,(v_row->>'id')::uuid,
    case when tg_op='INSERT' then 'create' else 'upsert' end,
    v_row,v_old,auth.uid(),100);
  return new;
end;
$$;


--
-- Name: enqueue_saas_org_name_workflow_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_saas_org_name_workflow_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_provider uuid := public.support_provider_org_id();
  v_settings public.saas_org_settings%rowtype;
  v_snapshot jsonb;
begin
  if new.name is not distinct from old.name or v_provider is null then return new; end if;
  select * into v_settings from public.saas_org_settings where org_id = new.id;
  if v_settings.id is null then return new; end if;
  if not exists (select 1 from public.workflows w where w.org_id = v_provider
    and w.is_active and w.trigger_type = 'on_upsert'
    and (w.module_id = 'saas_orgs' or 'saas_orgs' = any(coalesce(w.module_ids, '{}'::text[]))))
    then return new;
  end if;
  v_snapshot := jsonb_build_object('id',v_settings.id,'org_id',v_provider,
    'customer_org_id',new.id,'org_name',new.name,'slug',v_settings.slug,
    'status',v_settings.status,'plan_code',v_settings.plan_code,
    'is_demo',v_settings.is_demo,'resolved_host',v_settings.resolved_host,
    'primary_contact_mobile',v_settings.primary_contact_mobile,
    'trial_ends_at',v_settings.trial_ends_at);
  insert into public.workflow_event_queue
    (org_id,source_table,record_id,event_type,record_snapshot,previous_snapshot,actor_user_id,priority)
  values (v_provider,'saas_orgs',v_settings.id,'upsert',v_snapshot,
    jsonb_set(v_snapshot,'{org_name}',to_jsonb(old.name)),auth.uid(),100);
  return new;
end;
$$;


--
-- Name: enqueue_workflow_event_from_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_workflow_event_from_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row jsonb;
  v_previous jsonb;
  v_org_id uuid;
  v_origin_execution_key text;
begin
  if tg_op = 'INSERT' then
    v_row := to_jsonb(new);
    v_previous := null;
  else
    if (to_jsonb(new) - 'updated_at' - 'last_seen_at')
       is not distinct from (to_jsonb(old) - 'updated_at' - 'last_seen_at') then
      return new;
    end if;
    v_row := to_jsonb(new);
    v_previous := to_jsonb(old);
  end if;

  v_org_id := nullif(v_row ->> 'org_id', '')::uuid;
  if v_org_id is null or nullif(v_row ->> 'id', '') is null then
    return new;
  end if;
  if tg_table_name <> 'tasks' and not exists (
    select 1
    from public.workflows w
    cross join lateral unnest(array_prepend(coalesce(w.module_id, ''), coalesce(w.module_ids, '{}'::text[]))) module_ref(module_id)
    where w.org_id = v_org_id and w.is_active = true and w.trigger_type in ('on_create', 'on_upsert')
      and lower(regexp_replace(module_ref.module_id, '([a-z0-9])([A-Z])', '\1_\2', 'g')) = tg_table_name
    limit 1
  ) then
    return new;
  end if;

  v_origin_execution_key := nullif(current_setting('app.workflow_origin_execution_key', true), '');
  insert into public.workflow_event_queue (
    org_id, source_table, record_id, event_type, record_snapshot, previous_snapshot,
    actor_user_id, priority, origin_execution_key
  ) values (
    v_org_id, tg_table_name, (v_row ->> 'id')::uuid,
    case when tg_op = 'INSERT' then 'create' else 'upsert' end,
    v_row, v_previous, auth.uid(),
    case when v_origin_execution_key is null then 100 else 50 end,
    v_origin_execution_key
  );
  return new;
end;
$$;


--
-- Name: ensure_module_settings_columns(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_module_settings_columns(p_module_id text, p_table_name text, p_fields jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  normalized_module text := lower(trim(coalesce(p_module_id, '')));
  normalized_table text := lower(trim(coalesce(p_table_name, '')));
  field_item jsonb;
  field_key text;
  field_type text;
  sql_type text;
  table_relkind "char";
  changed boolean := false;
  expected_table text;
begin
  if auth.uid() is null or public.current_org_id() is null then
    raise exception 'دسترسی سازمان جاری قابل تشخیص نیست.';
  end if;

  if not public.current_user_can_edit_module_settings(normalized_module) then
    raise exception 'برای ویرایش فیلدهای این ماژول دسترسی ندارید.';
  end if;

  if normalized_module !~ '^[a-z][a-z0-9_]*$'
     or normalized_table !~ '^[a-z][a-z0-9_]*$' then
    raise exception 'شناسه ماژول یا جدول معتبر نیست.';
  end if;

  expected_table := case normalized_module
    when 'voip_call_reports' then 'voip_call_logs'
    else normalized_module
  end;

  if normalized_table <> expected_table then
    raise exception 'جدول مقصد با ماژول انتخاب‌شده همخوانی ندارد.';
  end if;

  if normalized_table in (
    'organizations',
    'org_roles',
    'integration_settings',
    'company_settings',
    'app_schema_migrations',
    'system_code_counters'
  ) then
    raise exception 'این جدول برای فیلد سفارشی مجاز نیست.';
  end if;

  select c.relkind
    into table_relkind
  from pg_class c
  join pg_namespace n
    on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relname = normalized_table
    and c.relkind in ('r', 'p');

  if table_relkind is null then
    raise exception 'جدول مقصد برای فیلد سفارشی پیدا نشد.';
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = normalized_table
      and column_name = 'org_id'
  ) then
    raise exception 'جدول مقصد tenant-owned نیست.';
  end if;

  if p_fields is null or jsonb_typeof(p_fields) <> 'array' then
    return;
  end if;

  for field_item in
    select value from jsonb_array_elements(p_fields)
  loop
    field_key := lower(trim(coalesce(field_item ->> 'key', '')));
    field_type := lower(trim(coalesce(field_item ->> 'type', 'text')));

    if field_key = ''
       or field_key !~ '^[a-z][a-z0-9_]*$'
       or field_key in ('id', 'org_id', 'created_at', 'updated_at', 'created_by', 'updated_by') then
      raise exception 'کلید فیلد سفارشی معتبر نیست: %', field_key;
    end if;

    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = normalized_table
        and column_name = field_key
    ) then
      continue;
    end if;

    sql_type := case field_type
      when 'number' then 'numeric'
      when 'price' then 'numeric'
      when 'percentage' then 'numeric'
      when 'percentage_or_amount' then 'numeric'
      when 'checkbox' then 'boolean'
      when 'date' then 'date'
      when 'time' then 'time'
      when 'datetime' then 'timestamptz'
      when 'relation' then 'uuid'
      when 'user' then 'uuid'
      when 'multi_relation' then 'jsonb'
      when 'multi_select' then 'jsonb'
      when 'checklist' then 'jsonb'
      when 'json' then 'jsonb'
      when 'location' then 'jsonb'
      when 'progress_stages' then 'jsonb'
      else 'text'
    end;

    execute format('alter table public.%I add column if not exists %I %s', normalized_table, field_key, sql_type);
    changed := true;
  end loop;

  if changed then
    perform pg_notify('pgrst', 'reload schema');
  end if;
end
$_$;


--
-- Name: ensure_process_run_for_draft_group(uuid, text, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_process_run_for_draft_group(p_org_id uuid, p_module_id text, p_record_id uuid, p_process_group_id text, p_process_name text, p_template_id uuid DEFAULT NULL::uuid, p_stages jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_current_org_id uuid;
  v_run_id uuid;
  v_stage jsonb;
  v_stage_id uuid;
  v_template_stage_id uuid;
  v_draft_stage_id text;
  v_stage_name text;
  v_sort_order integer;
  v_status text;
  v_assignee_user_id uuid;
  v_assignee_role_id uuid;
  v_metadata jsonb;
  v_stage_rows jsonb := '[]'::jsonb;
  v_link record;
  v_link_record_id uuid;
  v_process_node_key text;
  v_process_lane_key text;
begin
  v_current_org_id := public.current_org_id();

  if auth.uid() is null
    or p_org_id is null
    or v_current_org_id is null
    or p_org_id <> v_current_org_id then
    raise exception 'دسترسی ایجاد اجرای فرآیند برای این سازمان وجود ندارد.' using errcode = '42501';
  end if;

  if nullif(btrim(coalesce(p_module_id, '')), '') is null
    or p_record_id is null
    or nullif(btrim(coalesce(p_process_group_id, '')), '') is null then
    raise exception 'اطلاعات اجرای فرآیند کامل نیست.' using errcode = '22023';
  end if;

  if p_template_id is not null and not exists (
    select 1
    from public.process_templates t
    where t.id = p_template_id
      and t.org_id = p_org_id
  ) then
    raise exception 'الگوی فرآیند برای سازمان جاری پیدا نشد.' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_org_id::text || ':' || p_module_id || ':' || p_record_id::text || ':' || p_process_group_id,
      0
    )
  );

  select r.id
  into v_run_id
  from public.process_runs r
  where r.org_id = p_org_id
    and r.module_id = p_module_id
    and r.record_id = p_record_id
    and r.process_group_id = p_process_group_id
  order by r.created_at desc, r.id desc
  limit 1;

  if v_run_id is null then
    insert into public.process_runs (
      org_id,
      template_id,
      module_id,
      record_id,
      process_name,
      status,
      copied_mode,
      started_at,
      process_group_id,
      created_by,
      updated_by
    )
    values (
      p_org_id,
      p_template_id,
      p_module_id,
      p_record_id,
      coalesce(nullif(btrim(coalesce(p_process_name, '')), ''), 'فرآیند'),
      'active',
      'manual',
      now(),
      p_process_group_id,
      auth.uid(),
      auth.uid()
    )
    returning id into v_run_id;
  end if;

  insert into public.process_run_links (
    org_id,
    process_run_id,
    module_id,
    record_id,
    is_primary
  )
  values (
    p_org_id,
    v_run_id,
    p_module_id,
    p_record_id,
    true
  )
  on conflict (process_run_id, module_id, record_id) do update
  set org_id = excluded.org_id,
      is_primary = public.process_run_links.is_primary or excluded.is_primary;

  for v_stage in
    select value
    from jsonb_array_elements(
      case when jsonb_typeof(p_stages) = 'array' then p_stages else '[]'::jsonb end
    )
  loop
    v_metadata := coalesce(v_stage -> 'metadata', '{}'::jsonb);
    v_draft_stage_id := coalesce(
      nullif(btrim(coalesce(v_stage ->> 'draft_stage_id', '')), ''),
      nullif(btrim(coalesce(v_metadata ->> 'draft_stage_id', '')), ''),
      nullif(btrim(coalesce(v_metadata ->> 'draft_stage_key', '')), '')
    );
    v_template_stage_id := public.kalam_try_uuid(v_stage ->> 'template_stage_id');
    v_stage_name := coalesce(nullif(btrim(coalesce(v_stage ->> 'stage_name', '')), ''), 'مرحله');
    v_sort_order := greatest(
      1,
      coalesce(
        case
          when coalesce(v_stage ->> 'sort_order', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            then (v_stage ->> 'sort_order')::numeric::integer
          else null
        end,
        10
      )
    );
    v_status := case lower(coalesce(v_stage ->> 'status', 'todo'))
      when 'in_progress' then 'in_progress'
      when 'done' then 'done'
      when 'blocked' then 'blocked'
      when 'canceled' then 'canceled'
      else 'todo'
    end;
    v_assignee_user_id := public.kalam_try_uuid(v_stage ->> 'assignee_user_id');
    v_assignee_role_id := public.kalam_try_uuid(v_stage ->> 'assignee_role_id');
    v_process_node_key := nullif(btrim(coalesce(v_stage ->> 'process_node_key', '')), '');
    v_process_lane_key := coalesce(nullif(btrim(coalesce(v_stage ->> 'process_lane_key', '')), ''), 'lane_1');
    v_metadata := v_metadata
      || jsonb_build_object(
        'draft_stage_id', v_draft_stage_id,
        'draft_stage_key', v_draft_stage_id,
        'process_group_id', p_process_group_id,
        'process_node_key', v_process_node_key,
        'process_lane_key', v_process_lane_key
      );

    if exists (
      select 1
      from public.process_v2_deleted_stage_marks m
      where m.org_id = p_org_id
        and m.process_run_id = v_run_id
        and coalesce(m.process_group_id, p_process_group_id) = p_process_group_id
        and (
          (v_template_stage_id is not null and m.template_stage_id = v_template_stage_id)
          or (v_draft_stage_id is not null and m.draft_stage_key = v_draft_stage_id)
          or (v_process_node_key is not null and m.process_node_key = v_process_node_key)
        )
    ) then
      continue;
    end if;

    perform public.assert_process_assignee_org(
      p_org_id,
      v_assignee_user_id,
      v_assignee_role_id
    );

    select s.id
    into v_stage_id
    from public.process_run_stages s
    where s.process_run_id = v_run_id
      and not exists (
        select 1
        from public.process_v2_deleted_stage_marks m
        where m.org_id = p_org_id
          and m.process_run_stage_id = s.id
      )
      and (
        (v_template_stage_id is not null and s.template_stage_id = v_template_stage_id)
        or (v_draft_stage_id is not null and s.metadata ->> 'draft_stage_id' = v_draft_stage_id)
        or (v_process_node_key is not null and s.process_node_key = v_process_node_key)
        or (s.sort_order = v_sort_order and lower(btrim(s.stage_name)) = lower(v_stage_name))
      )
    order by
      case when v_template_stage_id is not null and s.template_stage_id = v_template_stage_id then 0 else 1 end,
      case when v_draft_stage_id is not null and s.metadata ->> 'draft_stage_id' = v_draft_stage_id then 0 else 1 end,
      case when v_process_node_key is not null and s.process_node_key = v_process_node_key then 0 else 1 end,
      s.created_at,
      s.id
    limit 1;

    if v_stage_id is null then
      insert into public.process_run_stages (
        process_run_id,
        template_stage_id,
        stage_name,
        sort_order,
        status,
        assignee_user_id,
        assignee_role_id,
        wage,
        process_node_key,
        process_lane_key,
        metadata
      )
      values (
        v_run_id,
        v_template_stage_id,
        v_stage_name,
        v_sort_order,
        v_status,
        v_assignee_user_id,
        v_assignee_role_id,
        coalesce(
          case
            when coalesce(v_stage ->> 'wage', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              then (v_stage ->> 'wage')::numeric
            else null
          end,
          0
        ),
        v_process_node_key,
        v_process_lane_key,
        v_metadata
      )
      returning id into v_stage_id;
    else
      update public.process_run_stages
      set template_stage_id = v_template_stage_id,
          stage_name = v_stage_name,
          sort_order = v_sort_order,
          status = v_status,
          assignee_user_id = v_assignee_user_id,
          assignee_role_id = v_assignee_role_id,
          wage = coalesce(
            case
              when coalesce(v_stage ->> 'wage', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then (v_stage ->> 'wage')::numeric
              else null
            end,
            0
          ),
          process_node_key = v_process_node_key,
          process_lane_key = v_process_lane_key,
          metadata = v_metadata,
          updated_at = now()
      where id = v_stage_id;
    end if;

    for v_link in
      select key, value
      from jsonb_each_text(
        case
          when jsonb_typeof(v_metadata -> 'process_link_map') = 'object' then v_metadata -> 'process_link_map'
          when jsonb_typeof(v_metadata -> 'process_links') = 'object' then v_metadata -> 'process_links'
          else '{}'::jsonb
        end
      )
    loop
      v_link_record_id := public.kalam_try_uuid(v_link.value);
      if nullif(btrim(coalesce(v_link.key, '')), '') is not null
        and v_link_record_id is not null then
        insert into public.process_run_links (
          org_id,
          process_run_id,
          module_id,
          record_id,
          is_primary
        )
        values (
          p_org_id,
          v_run_id,
          v_link.key,
          v_link_record_id,
          v_link.key = p_module_id and v_link_record_id = p_record_id
        )
        on conflict (process_run_id, module_id, record_id) do update
        set org_id = excluded.org_id,
            is_primary = public.process_run_links.is_primary or excluded.is_primary;
      end if;
    end loop;

    v_stage_rows := v_stage_rows || jsonb_build_array(jsonb_build_object(
      'id', v_stage_id,
      'draft_stage_id', v_draft_stage_id,
      'template_stage_id', v_template_stage_id,
      'stage_name', v_stage_name,
      'sort_order', v_sort_order,
      'process_node_key', v_process_node_key
    ));
    v_stage_id := null;
  end loop;

  update public.tasks
  set process_run_id = v_run_id
  where org_id = p_org_id
    and process_group_id = p_process_group_id
    and source_module_id = p_module_id
    and source_record_id = p_record_id
    and process_run_id is null;

  return jsonb_build_object(
    'process_run_id', v_run_id,
    'stages', v_stage_rows
  );
end;
$_$;


--
-- Name: ensure_process_run_for_draft_group_v2(uuid, text, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_process_run_for_draft_group_v2(p_org_id uuid, p_module_id text, p_record_id uuid, p_process_group_id text, p_process_name text, p_template_id uuid DEFAULT NULL::uuid, p_stages jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_current_org_id uuid := public.current_org_id();
  v_run_id uuid;
  v_stage jsonb;
  v_stage_id uuid;
  v_existing_deleted boolean;
  v_template_stage_id uuid;
  v_draft_stage_key text;
  v_stage_name text;
  v_sort_order integer;
  v_status text;
  v_assignee_user_id uuid;
  v_assignee_role_id uuid;
  v_wage numeric;
  v_metadata jsonb;
  v_stage_rows jsonb := '[]'::jsonb;
  v_link record;
  v_link_record_id uuid;
  v_process_node_key text;
  v_process_lane_key text;
begin
  if auth.uid() is null
    or p_org_id is null
    or v_current_org_id is null
    or p_org_id <> v_current_org_id then
    raise exception 'دسترسی ایجاد اجرای فرآیند برای این سازمان وجود ندارد.' using errcode = '42501';
  end if;

  if nullif(btrim(coalesce(p_module_id, '')), '') is null
    or p_record_id is null
    or nullif(btrim(coalesce(p_process_group_id, '')), '') is null then
    raise exception 'اطلاعات اجرای فرآیند کامل نیست.' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_org_id::text || ':' || p_module_id || ':' || p_record_id::text || ':' || p_process_group_id,
      0
    )
  );

  select r.id
  into v_run_id
  from public.process_runs r
  where r.org_id = p_org_id
    and r.module_id = p_module_id
    and r.record_id = p_record_id
    and r.process_group_id = p_process_group_id
  order by r.created_at desc, r.id desc
  limit 1;

  if v_run_id is null then
    insert into public.process_runs (
      org_id,
      template_id,
      module_id,
      record_id,
      process_name,
      status,
      copied_mode,
      started_at,
      process_group_id,
      created_by,
      updated_by
    )
    values (
      p_org_id,
      p_template_id,
      p_module_id,
      p_record_id,
      coalesce(nullif(btrim(coalesce(p_process_name, '')), ''), 'فرآیند'),
      'active',
      'manual',
      now(),
      p_process_group_id,
      auth.uid(),
      auth.uid()
    )
    returning id into v_run_id;
  end if;

  insert into public.process_run_links (org_id, process_run_id, module_id, record_id, is_primary)
  values (p_org_id, v_run_id, p_module_id, p_record_id, true)
  on conflict (process_run_id, module_id, record_id) do update
  set org_id = excluded.org_id,
      is_primary = public.process_run_links.is_primary or excluded.is_primary;

  for v_stage in
    select value
    from jsonb_array_elements(
      case when jsonb_typeof(p_stages) = 'array' then p_stages else '[]'::jsonb end
    )
  loop
    v_metadata := coalesce(v_stage -> 'metadata', '{}'::jsonb);
    v_template_stage_id := public.kalam_try_uuid(v_stage ->> 'template_stage_id');
    v_draft_stage_key := coalesce(
      nullif(btrim(coalesce(v_stage ->> 'draft_stage_id', '')), ''),
      nullif(btrim(coalesce(v_metadata ->> 'draft_stage_key', '')), ''),
      nullif(btrim(coalesce(v_metadata ->> 'draft_stage_id', '')), '')
    );
    v_stage_name := coalesce(nullif(btrim(coalesce(v_stage ->> 'stage_name', '')), ''), 'مرحله');
    v_sort_order := greatest(
      1,
      coalesce(
        case
          when coalesce(v_stage ->> 'sort_order', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            then (v_stage ->> 'sort_order')::numeric::integer
          else null
        end,
        10
      )
    );
    v_status := case lower(coalesce(v_stage ->> 'status', 'todo'))
      when 'in_progress' then 'in_progress'
      when 'done' then 'done'
      when 'blocked' then 'blocked'
      when 'canceled' then 'canceled'
      else 'todo'
    end;
    v_assignee_user_id := public.kalam_try_uuid(v_stage ->> 'assignee_user_id');
    v_assignee_role_id := public.kalam_try_uuid(v_stage ->> 'assignee_role_id');
    v_process_node_key := nullif(btrim(coalesce(v_stage ->> 'process_node_key', '')), '');
    v_process_lane_key := coalesce(nullif(btrim(coalesce(v_stage ->> 'process_lane_key', '')), ''), 'lane_1');
    v_wage := coalesce(
      case
        when coalesce(v_stage ->> 'wage', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          then (v_stage ->> 'wage')::numeric
        else null
      end,
      0
    );
    v_metadata := v_metadata
      || jsonb_build_object(
        'draft_stage_id', v_draft_stage_key,
        'draft_stage_key', v_draft_stage_key,
        'process_group_id', p_process_group_id,
        'process_node_key', v_process_node_key,
        'process_lane_key', v_process_lane_key
      );

    select s.id,
           exists (
             select 1
             from public.process_v2_deleted_stage_marks m
             where m.org_id = p_org_id
               and (
                 m.process_run_stage_id = s.id
                 or (
                   m.process_run_id = v_run_id
                   and coalesce(m.process_group_id, p_process_group_id) = p_process_group_id
                   and (
                     (v_template_stage_id is not null and m.template_stage_id = v_template_stage_id)
                     or (v_draft_stage_key is not null and m.draft_stage_key = v_draft_stage_key)
                     or (v_process_node_key is not null and m.process_node_key = v_process_node_key)
                   )
                 )
               )
           )
    into v_stage_id, v_existing_deleted
    from public.process_run_stages s
    where s.process_run_id = v_run_id
      and (
        (v_template_stage_id is not null and s.template_stage_id = v_template_stage_id)
        or (v_draft_stage_key is not null and s.metadata ->> 'draft_stage_id' = v_draft_stage_key)
        or (v_draft_stage_key is not null and s.metadata ->> 'draft_stage_key' = v_draft_stage_key)
        or (v_process_node_key is not null and coalesce(s.process_node_key, s.metadata ->> 'process_node_key') = v_process_node_key)
        or (s.sort_order = v_sort_order and lower(btrim(s.stage_name)) = lower(v_stage_name))
      )
    order by
      case when v_template_stage_id is not null and s.template_stage_id = v_template_stage_id then 0 else 1 end,
      case when v_process_node_key is not null and coalesce(s.process_node_key, s.metadata ->> 'process_node_key') = v_process_node_key then 0 else 1 end,
      s.created_at,
      s.id
    limit 1;

    if coalesce(v_existing_deleted, false) then
      v_stage_id := null;
      continue;
    end if;

    begin
      perform public.assert_process_assignee_org(p_org_id, v_assignee_user_id, v_assignee_role_id);
    exception when others then
      v_assignee_user_id := null;
      v_assignee_role_id := null;
    end;

    if v_stage_id is null then
      insert into public.process_run_stages (
        process_run_id,
        template_stage_id,
        stage_name,
        sort_order,
        status,
        assignee_user_id,
        assignee_role_id,
        wage,
        process_node_key,
        process_lane_key,
        metadata
      )
      values (
        v_run_id,
        v_template_stage_id,
        v_stage_name,
        v_sort_order,
        v_status,
        v_assignee_user_id,
        v_assignee_role_id,
        v_wage,
        v_process_node_key,
        v_process_lane_key,
        v_metadata
      )
      returning id into v_stage_id;
    else
      update public.process_run_stages
      set template_stage_id = v_template_stage_id,
          stage_name = v_stage_name,
          sort_order = v_sort_order,
          status = v_status,
          assignee_user_id = v_assignee_user_id,
          assignee_role_id = v_assignee_role_id,
          wage = v_wage,
          process_node_key = v_process_node_key,
          process_lane_key = v_process_lane_key,
          metadata = v_metadata,
          updated_at = now()
      where id = v_stage_id;
    end if;

    for v_link in
      select key, value
      from jsonb_each_text(
        case
          when jsonb_typeof(v_metadata -> 'process_link_map') = 'object' then v_metadata -> 'process_link_map'
          when jsonb_typeof(v_metadata -> 'process_links') = 'object' then v_metadata -> 'process_links'
          else '{}'::jsonb
        end
      )
    loop
      v_link_record_id := public.kalam_try_uuid(v_link.value);
      if nullif(btrim(coalesce(v_link.key, '')), '') is not null
        and v_link_record_id is not null then
        insert into public.process_run_links (org_id, process_run_id, module_id, record_id, is_primary)
        values (p_org_id, v_run_id, v_link.key, v_link_record_id, v_link.key = p_module_id and v_link_record_id = p_record_id)
        on conflict (process_run_id, module_id, record_id) do update
        set org_id = excluded.org_id,
            is_primary = public.process_run_links.is_primary or excluded.is_primary;
      end if;
    end loop;

    v_stage_rows := v_stage_rows || jsonb_build_array(jsonb_build_object(
      'id', v_stage_id,
      'draft_stage_id', v_draft_stage_key,
      'template_stage_id', v_template_stage_id,
      'stage_name', v_stage_name,
      'sort_order', v_sort_order,
      'process_node_key', v_process_node_key
    ));
    v_stage_id := null;
    v_existing_deleted := false;
  end loop;

  update public.tasks
  set process_run_id = v_run_id
  where org_id = p_org_id
    and process_group_id = p_process_group_id
    and source_module_id = p_module_id
    and source_record_id = p_record_id
    and process_run_id is null;

  return jsonb_build_object('process_run_id', v_run_id, 'stages', v_stage_rows);
end;
$_$;


--
-- Name: ensure_retail_general_customer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_retail_general_customer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org_id uuid := public.current_org_id(); v_customer_id uuid;
begin
  if v_org_id is null then raise exception 'سازمان فعال یافت نشد'; end if;
  select id into v_customer_id from public.customers where org_id = v_org_id and is_retail_general_customer = true limit 1;
  if v_customer_id is not null then return v_customer_id; end if;
  insert into public.customers (org_id, full_name, person_type, status, is_retail_general_customer)
  values (v_org_id, 'مشتری عمومی', 'real', 'active', true)
  on conflict (org_id) where is_retail_general_customer = true do update set full_name = public.customers.full_name
  returning id into v_customer_id;
  return v_customer_id;
end;
$$;


--
-- Name: fill_saas_org_owner_projection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_saas_org_owner_projection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_name text; v_email text; v_mobile text;
begin
  if nullif(trim(coalesce(new.owner_name, '')), '') is not null
    and nullif(trim(coalesce(new.owner_email, '')), '') is not null then return new; end if;
  select p.full_name, p.email, coalesce(p.mobile_1,p.mobile)
    into v_name,v_email,v_mobile
  from public.user_organization_memberships m
  join public.profiles p on p.id = m.user_id
  where m.org_id = new.org_id and m.is_owner and m.is_active
  order by m.created_at limit 1;
  if v_name is null and v_email is null and new.created_by is not null then
    select p.full_name,p.email,coalesce(p.mobile_1,p.mobile)
      into v_name,v_email,v_mobile from public.profiles p where p.id = new.created_by;
  end if;
  new.owner_name := coalesce(nullif(trim(new.owner_name), ''), nullif(trim(v_name), ''), new.owner_name);
  new.owner_email := coalesce(nullif(trim(new.owner_email), ''), nullif(trim(v_email), ''), new.owner_email);
  new.primary_contact_mobile := coalesce(nullif(trim(new.primary_contact_mobile), ''), nullif(trim(v_mobile), ''), new.primary_contact_mobile);
  return new;
end;
$$;


--
-- Name: filter_call_contact_identities(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.filter_call_contact_identities(p_module_id text, p_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare result jsonb;ctx jsonb:=public.get_current_organization_context();begin
 if public.current_org_id() is null or p_module_id not in('customers','suppliers','employees') or coalesce(array_length(p_ids,1),0)>100 then raise exception 'invalid_contact_scope';end if;
 if not public.current_org_has_plan_module(p_module_id,false) then return '[]'::jsonb;end if;
 execute format('select coalesce(jsonb_agg(c.id),''[]''::jsonb) from public.%I c where c.org_id=$1 and c.id=any($2) and public.call_contact_scope_visible($3,$4,to_jsonb(c))',p_module_id)
 into result using public.current_org_id(),p_ids,ctx,p_module_id;
 return result;
end;$_$;


--
-- Name: filter_records_by_json_array_count(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.filter_records_by_json_array_count(p_table_name text, p_field_name text, p_operator text, p_count integer) RETURNS TABLE(record_id text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  normalized_table_name text := btrim(coalesce(p_table_name, ''));
  normalized_field_name text := btrim(coalesce(p_field_name, ''));
  comparison_operator text := btrim(coalesce(p_operator, ''));
  target_table regclass;
begin
  if public.current_org_id() is null then
    return;
  end if;

  if normalized_table_name = '' or normalized_field_name = '' or p_count is null or p_count < 0 then
    raise exception 'invalid_array_count_filter';
  end if;

  if comparison_operator not in ('gt', 'lt') then
    raise exception 'invalid_array_count_operator';
  end if;

  target_table := to_regclass(format('public.%I', normalized_table_name));
  if target_table is null then
    raise exception 'invalid_array_count_table';
  end if;

  if not exists (
    select 1
    from pg_attribute attribute
    where attribute.attrelid = target_table
      and attribute.attname = normalized_field_name
      and attribute.attnum > 0
      and not attribute.attisdropped
      and attribute.atttypid in ('json'::regtype, 'jsonb'::regtype)
  ) or not exists (
    select 1
    from pg_attribute attribute
    where attribute.attrelid = target_table
      and attribute.attname = 'org_id'
      and attribute.attnum > 0
      and not attribute.attisdropped
  ) or not exists (
    select 1
    from pg_attribute attribute
    where attribute.attrelid = target_table
      and attribute.attname = 'id'
      and attribute.attnum > 0
      and not attribute.attisdropped
  ) then
    raise exception 'invalid_array_count_field';
  end if;

  return query execute format(
    'select row.id::text
       from public.%1$I as row
      where row.org_id = public.current_org_id()
        and case
              when jsonb_typeof(row.%2$I::jsonb) = ''array'' then jsonb_array_length(row.%2$I::jsonb)
              else 0
            end %3$s $1',
    normalized_table_name,
    normalized_field_name,
    comparison_operator
  ) using p_count;
end;
$_$;


--
-- Name: finalize_advertising_campaign_audience(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_advertising_campaign_audience(p_campaign_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_campaign public.advertising_campaigns%rowtype;
  v_rule record;
  v_tool public.advertising_campaign_tools%rowtype;
  v_group record;
  v_import record;
  v_row jsonb;
  v_customer jsonb;
  v_groups jsonb;
  v_tool_counts jsonb := '{}'::jsonb;
  v_tool_configs jsonb := '{}'::jsonb;
  v_exclusions jsonb;
  v_next_config jsonb;
  v_contact_key text;
  v_ref text;
  v_contact text;
  v_channel text;
  v_bot_channel text;
  v_group_excluded boolean;
  v_group_suppressed boolean;
  v_tool_matched integer;
  v_tool_valid integer;
  v_tool_unique integer;
  v_tool_duplicate integer;
  v_tool_invalid integer;
  v_tool_excluded integer;
  v_tool_suppressed integer;
  v_tool_sendable integer;
  v_finalized_at timestamptz := clock_timestamp();
begin
  select * into v_campaign
  from public.advertising_campaigns
  where id=p_campaign_id and org_id=public.current_org_id();

  if v_campaign.id is null or not public.can_edit_advertising_campaign(p_campaign_id) then
    raise exception 'اجازه نهایی‌سازی مخاطبان این کمپین را ندارید.' using errcode='42501';
  end if;

  -- گروه بات مخاطب رکوردی ندارد. پیامک، ایمیل و پی‌وی بات با کانال واقعی خودشان
  -- سنجیده می‌شوند، چون معتبر بودن راه ارتباطی میان این ابزارها متفاوت است.
  for v_tool in
    select * from public.advertising_campaign_tools
    where campaign_id=p_campaign_id
      and org_id=v_campaign.org_id
      and enabled=true
      and tool_type in ('sms','email','bot_private')
      and case
        when jsonb_typeof(config->'audience_sources')='array' then config->'audience_sources' ? 'internal'
        else false
      end
    order by id
  loop
    v_channel := lower(btrim(v_tool.tool_type));
    v_bot_channel := lower(btrim(coalesce(v_tool.config->>'channel','')));
    v_exclusions := case
      when jsonb_typeof(v_tool.config->'excluded_audience_refs')='array'
        then v_tool.config->'excluded_audience_refs'
      else '[]'::jsonb
    end;
    v_groups := '{}'::jsonb;
    v_tool_matched := 0;
    v_tool_valid := 0;

    for v_rule in
      select * from public.advertising_campaign_audience_rules
      where campaign_id=p_campaign_id and org_id=v_campaign.org_id and enabled=true
    loop
      for v_row in execute format(
        'select to_jsonb(t) from public.%I t where t.org_id=$1 order by t.id',
        v_rule.target_module_id
      ) using v_campaign.org_id
      loop
        if not public.advertising_campaign_conditions_match(v_row,v_rule.conditions_all,v_rule.conditions_any) then
          continue;
        end if;
        v_tool_matched := v_tool_matched+1;
        v_ref := v_rule.target_module_id || ':' || coalesce(v_row->>'id','');
        v_customer := null;
        if v_rule.target_module_id='customers' then
          v_customer := v_row;
        elsif nullif(v_row->>'customer_id','') is not null
              and (v_row->>'customer_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
          select to_jsonb(c) into v_customer
          from public.customers c
          where c.org_id=v_campaign.org_id and c.id=(v_row->>'customer_id')::uuid;
        end if;

        v_contact := case v_channel
          when 'sms' then coalesce(
            nullif(v_row->>'mobile',''), nullif(v_row->>'mobile_1',''), nullif(v_row->>'phone',''),
            nullif(v_customer->>'mobile_1',''), nullif(v_customer->>'phone','')
          )
          when 'email' then coalesce(nullif(v_row->>'email',''),nullif(v_customer->>'email',''))
          when 'bot_private' then case v_bot_channel
            when 'telegram' then coalesce(nullif(v_row->>'telegram_chat_id',''),nullif(v_customer->>'telegram_chat_id',''))
            when 'bale' then coalesce(nullif(v_row->>'bale_chat_id',''),nullif(v_customer->>'bale_chat_id',''))
            when 'rubika' then coalesce(nullif(v_row->>'rubika_chat_id',''),nullif(v_customer->>'rubika_chat_id',''))
            else null
          end
          else null
        end;
        v_contact_key := public.advertising_campaign_contact_key(v_channel,v_contact);
        if coalesce(v_contact_key,'')='' then continue; end if;

        v_tool_valid := v_tool_valid+1;
        v_groups := v_groups || jsonb_build_object(
          v_contact_key,
          coalesce(v_groups->v_contact_key,'[]'::jsonb) || jsonb_build_array(v_ref)
        );
      end loop;
    end loop;

    -- فایل‌های کامل‌شده در اجرای واقعی با مخاطبان داخلی ادغام و سپس یکتا می‌شوند.
    if jsonb_typeof(v_tool.config->'audience_sources')='array'
       and v_tool.config->'audience_sources' ? 'excel' then
      for v_import in
        select r.id,r.contact_key
        from public.advertising_campaign_import_rows r
        join public.advertising_campaign_imports i
          on i.id=r.import_id and i.org_id=r.org_id
        where r.org_id=v_campaign.org_id
          and r.tool_id=v_tool.id
          and i.status='completed'
        order by r.created_at,r.id
      loop
        v_tool_matched := v_tool_matched+1;
        v_contact_key := btrim(coalesce(v_import.contact_key,''));
        if v_contact_key='' then continue; end if;
        v_tool_valid := v_tool_valid+1;
        v_ref := 'file:' || v_import.id::text;
        v_groups := v_groups || jsonb_build_object(
          v_contact_key,
          coalesce(v_groups->v_contact_key,'[]'::jsonb) || jsonb_build_array(v_ref)
        );
      end loop;
    end if;

    select count(*)::integer into v_tool_unique from jsonb_each(v_groups);
    v_tool_duplicate := greatest(v_tool_valid-v_tool_unique,0);
    v_tool_invalid := greatest(v_tool_matched-v_tool_valid,0);
    v_tool_excluded := 0;
    v_tool_suppressed := 0;
    v_tool_sendable := 0;

    for v_group in select key,value from jsonb_each(v_groups)
    loop
      select not exists (
        select 1 from jsonb_array_elements_text(v_group.value) as source_ref
        where not (v_exclusions ? source_ref.value)
      ) into v_group_excluded;
      select exists (
        select 1 from public.campaign_contact_suppressions s
        where s.org_id=v_campaign.org_id
          and s.channel_type=v_channel
          and s.contact_key=v_group.key
          and s.is_active
      ) into v_group_suppressed;
      if v_group_excluded then v_tool_excluded := v_tool_excluded+1; end if;
      if v_group_suppressed then v_tool_suppressed := v_tool_suppressed+1; end if;
      if not v_group_excluded and not v_group_suppressed then
        v_tool_sendable := v_tool_sendable+1;
      end if;
    end loop;

    v_next_config := coalesce(v_tool.config,'{}'::jsonb) || jsonb_build_object(
      'matched_audience_count',v_tool_matched,
      'unique_audience_count',v_tool_unique,
      'duplicate_audience_count',v_tool_duplicate,
      'invalid_audience_count',v_tool_invalid,
      'excluded_audience_count',v_tool_excluded,
      'suppressed_audience_count',v_tool_suppressed,
      'sendable_audience_count',v_tool_sendable,
      'audience_finalized_at',v_finalized_at
    );
    if v_channel in ('sms','email') then
      v_next_config := jsonb_set(v_next_config,'{estimated_audience}',to_jsonb(v_tool_sendable),true);
    end if;

    update public.advertising_campaign_tools
    set config=v_next_config, updated_at=v_finalized_at, updated_by=auth.uid()
    where id=v_tool.id and campaign_id=p_campaign_id and org_id=v_campaign.org_id;

    v_tool_counts := v_tool_counts || jsonb_build_object(v_tool.id::text,jsonb_build_object(
      'matched_count',v_tool_matched,
      'unique_count',v_tool_unique,
      'duplicate_count',v_tool_duplicate,
      'invalid_count',v_tool_invalid,
      'excluded_count',v_tool_excluded,
      'suppressed_count',v_tool_suppressed,
      'sendable_count',v_tool_sendable
    ));
    v_tool_configs := v_tool_configs || jsonb_build_object(v_tool.id::text,v_next_config);
  end loop;

  return jsonb_build_object(
    'tool_counts',v_tool_counts,
    'tool_configs',v_tool_configs,
    'finalized_at',v_finalized_at
  );
end;
$_$;


--
-- Name: financial_history_document_reference(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_history_document_reference(p_system_code text, p_title text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select nullif(concat_ws(
    ' — ',
    nullif(btrim(p_system_code), ''),
    nullif(btrim(p_title), '')
  ), '');
$$;


--
-- Name: financial_history_payment_amount(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_history_payment_amount(p_payment jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_amount numeric := public.financial_history_safe_numeric(p_payment ->> 'amount');
  v_total numeric := public.financial_history_safe_numeric(p_payment ->> 'total_price');
  v_quantity numeric := public.financial_history_safe_numeric(p_payment ->> 'quantity');
  v_unit_price numeric := public.financial_history_safe_numeric(p_payment ->> 'unit_price');
begin
  if v_amount <> 0 then return abs(v_amount); end if;
  if v_total <> 0 then return abs(v_total); end if;
  if v_quantity > 0 and v_unit_price > 0 then return v_quantity * v_unit_price; end if;
  return 0;
end;
$$;


--
-- Name: financial_history_payment_event_date(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_history_payment_event_date(p_payment jsonb) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_value text;
begin
  if p_payment is null then
    return null;
  end if;

  v_value := nullif(btrim(coalesce(
    p_payment ->> 'payment_date',
    p_payment ->> 'receipt_date',
    p_payment ->> 'operation_date',
    p_payment ->> 'paid_at',
    p_payment ->> 'received_at',
    p_payment ->> 'settled_at',
    p_payment ->> 'date',
    ''
  )), '');

  if v_value is null then
    return null;
  end if;

  if v_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    return v_value::date;
  end if;

  if v_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T[:space:]]' then
    return left(v_value, 10)::date;
  end if;

  return null;
exception
  when others then
    return null;
end;
$_$;


--
-- Name: financial_history_payment_is_final(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_history_payment_is_final(p_payment jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(nullif(lower(trim(p_payment ->> 'status')), ''), 'received')
    in ('received', 'approved', 'paid', 'settled', 'cleared', 'completed')
$$;


--
-- Name: financial_history_safe_numeric(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_history_safe_numeric(p_value text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_value text := replace(replace(replace(trim(coalesce(p_value, '')), ',', ''), '٬', ''), '،', '');
begin
  if v_value !~ '^[+-]?([0-9]+([.][0-9]+)?|[.][0-9]+)$' then
    return 0;
  end if;
  return v_value::numeric;
end;
$_$;


--
-- Name: find_profile_by_phone_for_auth(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_profile_by_phone_for_auth(p_phone text, p_exclude_user_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.profiles
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select p.* from public.profiles p
  where public.normalize_iran_mobile_e164(coalesce(nullif(p.mobile_1,''),nullif(p.mobile,'')))
      = public.normalize_iran_mobile_e164(p_phone)
    and (p_exclude_user_id is null or p.id<>p_exclude_user_id)
  limit 2;
$$;


--
-- Name: find_system_code_last_number(text, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_system_code_last_number(p_table_name text, p_org_id uuid, p_prefix text, p_max_sequence integer DEFAULT 2147483647) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_table_name text := nullif(btrim(p_table_name), '');
  v_prefix text := upper(btrim(coalesce(p_prefix, '')));
  v_prefix_length integer := char_length(v_prefix);
  v_last_number integer := 0;
begin
  if v_table_name is null or v_prefix = '' then
    return 0;
  end if;

  execute format(
    'select coalesce(max(suffix_value)::int, 0)
       from (
         select substring(upper(system_code) from %s) as suffix_text
           from public.%I
          where ($1::uuid is null or org_id = $1)
            and coalesce(system_code, '''') <> ''''
            and left(upper(system_code), %s) = $2
       ) matching_codes
       cross join lateral (
         select case
           when suffix_text ~ ''^[0-9]+$''
             and suffix_text::numeric between 0 and $3
             then suffix_text::numeric
           else null
         end as suffix_value
       ) normalized_codes
      where suffix_value is not null',
    v_prefix_length + 1,
    v_table_name,
    v_prefix_length
  )
  into v_last_number
  using p_org_id, v_prefix, greatest(coalesce(p_max_sequence, 2147483647), 0);

  return coalesce(v_last_number, 0);
end;
$_$;


--
-- Name: generate_delivery_share_token(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_delivery_share_token(p_length integer DEFAULT 10) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
  v_length integer := greatest(coalesce(p_length, 10), 8);
  v_seed text := encode(
    sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text as bytea)),
    'hex'
  );
  v_result text := '';
  v_index integer;
  v_pos integer;
  v_chunk text;
begin
  for v_pos in 0..(v_length - 1) loop
    if (v_pos * 2) + 2 > length(v_seed) then
      v_seed := v_seed || encode(
        sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text || v_pos::text as bytea)),
        'hex'
      );
    end if;
    v_chunk := substr(v_seed, (v_pos * 2) + 1, 2);
    v_index := mod(('x' || v_chunk)::bit(8)::integer, length(v_alphabet));
    v_result := v_result || substr(v_alphabet, v_index + 1, 1);
  end loop;
  return v_result;
end;
$$;


--
-- Name: get_accessible_sms_delivery_reports(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_sms_delivery_reports(p_limit integer DEFAULT 80) RETURNS TABLE(id uuid, title text, module_id text, record_id text, related_module_id text, related_record_id uuid, customer_id uuid, assignee_id uuid, assignee_type text, assignee_role_id uuid, direction text, provider text, provider_message_id text, sender text, recipient text, phone_number text, phone_number_id uuid, phone_match_status text, message_text text, status text, error_message text, metadata jsonb, sent_at timestamp with time zone, received_at timestamp with time zone, message_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select *
  from public.get_accessible_sms_delivery_reports_page(p_limit, null, null);
$$;


--
-- Name: get_accessible_sms_delivery_reports(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_sms_delivery_reports(p_limit integer DEFAULT 80, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, title text, module_id text, record_id text, related_module_id text, related_record_id uuid, customer_id uuid, assignee_id uuid, assignee_type text, assignee_role_id uuid, direction text, provider text, provider_message_id text, sender text, recipient text, phone_number text, phone_number_id uuid, phone_match_status text, message_text text, status text, error_message text, metadata jsonb, sent_at timestamp with time zone, received_at timestamp with time zone, message_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with limits as (select least(greatest(coalesce(p_limit, 80), 1), 200) as effective_limit),
  candidate_messages as (
    select m.*, coalesce(m.received_at, m.sent_at, m.created_at) as message_at
    from public.outbound_messages m
    cross join limits
    where m.org_id = public.current_org_id()
      and m.channel_type = 'sms'
      and (
        p_before_at is null
        or coalesce(m.received_at, m.sent_at, m.created_at) < p_before_at
        or (coalesce(m.received_at, m.sent_at, m.created_at) = p_before_at and p_before_id is not null and m.id < p_before_id)
      )
    order by coalesce(m.received_at, m.sent_at, m.created_at) desc nulls last, m.created_at desc, m.id desc
    limit least(greatest((select effective_limit from limits) * 20, 400), 2000)
  )
  select m.id, coalesce(nullif(m.title, ''), nullif(m.sender, ''), nullif(m.recipient, ''), 'پیامک'),
    m.module_id, m.record_id, m.related_module_id, public.kalam_try_uuid(m.related_record_id), m.customer_id,
    m.assignee_id, m.assignee_type, m.assignee_role_id, coalesce(nullif(m.direction, ''), 'outbound'), m.provider,
    m.provider_message_id, m.sender, m.recipient,
    case when coalesce(nullif(m.direction, ''), 'outbound') = 'inbound' then m.sender else m.recipient end,
    m.phone_number_id, m.phone_match_status, m.message_text, m.status, m.error_message, m.metadata,
    m.sent_at, m.received_at, m.message_at, m.created_at, m.updated_at
  from candidate_messages m
  where public.kalam_can_view_communication_record_v2(
    'sms', public.current_org_id(), m.assignee_type, m.assignee_id, m.assignee_role_id,
    m.module_id, public.kalam_try_uuid(m.record_id), m.related_module_id, public.kalam_try_uuid(m.related_record_id),
    m.customer_id, m.sender, m.recipient,
    case when coalesce(nullif(m.direction, ''), 'outbound') = 'inbound' then m.sender else m.recipient end,
    null, null, null
  )
  order by m.message_at desc nulls last, m.created_at desc, m.id desc
  limit (select effective_limit from limits);
$$;


--
-- Name: get_accessible_sms_delivery_reports_page(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_sms_delivery_reports_page(p_limit integer DEFAULT 80, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, title text, module_id text, record_id text, related_module_id text, related_record_id uuid, customer_id uuid, assignee_id uuid, assignee_type text, assignee_role_id uuid, direction text, provider text, provider_message_id text, sender text, recipient text, phone_number text, phone_number_id uuid, phone_match_status text, message_text text, status text, error_message text, metadata jsonb, sent_at timestamp with time zone, received_at timestamp with time zone, message_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid;
  v_permissions jsonb := '{}'::jsonb;
  v_profile_mobile_1 text;
  v_profile_mobile text;
  v_profile_phone text := '';
  v_profile_phone_tail text := '';
  v_allowed_role_ids uuid[] := array[]::uuid[];
  v_allowed_user_ids uuid[] := array[]::uuid[];
begin
  if v_user_id is null or v_org_id is null then
    return;
  end if;

  select
    profile.role_id,
    profile.mobile_1,
    profile.mobile,
    coalesce(role.permissions, '{}'::jsonb)
  into v_role_id, v_profile_mobile_1, v_profile_mobile, v_permissions
  from public.profiles profile
  left join public.org_roles role
    on role.id = profile.role_id
   and role.org_id = profile.org_id
  where profile.id = v_user_id
    and profile.org_id = v_org_id
  limit 1;

  if not found then
    return;
  end if;

  v_profile_phone := public.kalam_normalize_phone_digits(coalesce(v_profile_mobile_1, v_profile_mobile, ''));
  v_profile_phone_tail := case when length(v_profile_phone) >= 10 then right(v_profile_phone, 10) else v_profile_phone end;

  with recursive role_tree as (
    select role.id
    from public.org_roles role
    where role.id = v_role_id
      and role.org_id = v_org_id
    union all
    select child.id
    from public.org_roles child
    join role_tree parent on child.parent_id = parent.id
    where child.org_id = v_org_id
  )
  select coalesce(array_agg(id), array[]::uuid[])
    into v_allowed_role_ids
  from role_tree;

  select coalesce(array_agg(profile.id), array[]::uuid[])
    into v_allowed_user_ids
  from public.profiles profile
  where profile.org_id = v_org_id
    and (
      profile.id = v_user_id
      or profile.role_id = any(v_allowed_role_ids)
    );

  return query
  with limits as (
    select least(greatest(coalesce(p_limit, 80), 1), 200) as effective_limit
  ), candidate_messages as (
    select
      message.*,
      coalesce(message.received_at, message.sent_at, message.created_at) as resolved_message_at
    from public.outbound_messages message
    cross join limits
    where message.org_id = v_org_id
      and message.channel_type = 'sms'
      and (
        p_before_at is null
        or coalesce(message.received_at, message.sent_at, message.created_at) < p_before_at
        or (
          coalesce(message.received_at, message.sent_at, message.created_at) = p_before_at
          and p_before_id is not null
          and message.id < p_before_id
        )
      )
    order by coalesce(message.received_at, message.sent_at, message.created_at) desc nulls last,
      message.created_at desc,
      message.id desc
    limit least(greatest((select effective_limit from limits) * 20, 400), 2000)
  ), visible_messages as (
    select message.*
    from candidate_messages message
    where public.kalam_can_view_module_record_from_context(
      v_permissions,
      v_user_id,
      v_role_id,
      v_allowed_user_ids,
      v_allowed_role_ids,
      'sms_delivery_reports',
      message.assignee_type,
      message.assignee_id,
      message.assignee_role_id
    )
    or (
      v_profile_phone <> ''
      and (
        public.kalam_normalize_phone_digits(message.sender) like '%' || v_profile_phone
        or public.kalam_normalize_phone_digits(message.recipient) like '%' || v_profile_phone
        or public.kalam_normalize_phone_digits(
          case when coalesce(nullif(message.direction, ''), 'outbound') = 'inbound' then message.sender else message.recipient end
        ) like '%' || v_profile_phone
        or (
          v_profile_phone_tail <> ''
          and (
            right(public.kalam_normalize_phone_digits(message.sender), 10) = v_profile_phone_tail
            or right(public.kalam_normalize_phone_digits(message.recipient), 10) = v_profile_phone_tail
            or right(public.kalam_normalize_phone_digits(
              case when coalesce(nullif(message.direction, ''), 'outbound') = 'inbound' then message.sender else message.recipient end
            ), 10) = v_profile_phone_tail
          )
        )
      )
    )
    or (
      lower(coalesce(message.module_id, '')) = 'profiles'
      and public.kalam_try_uuid(message.record_id) = v_user_id
    )
    or (
      lower(coalesce(message.related_module_id, '')) = 'profiles'
      and public.kalam_try_uuid(message.related_record_id) = v_user_id
    )
    or exists (
      select 1
      from (
        select
          'customers'::text as target_module_id,
          customer.assignee_type,
          customer.assignee_id,
          customer.assignee_role_id
        from public.customers customer
        where customer.org_id = v_org_id
          and customer.id = any(array[
            case when lower(coalesce(message.module_id, '')) = 'customers' then public.kalam_try_uuid(message.record_id) end,
            case when lower(coalesce(message.related_module_id, '')) = 'customers' then public.kalam_try_uuid(message.related_record_id) end,
            message.customer_id
          ]::uuid[])

        union all

        select
          'suppliers'::text,
          supplier.assignee_type,
          supplier.assignee_id,
          supplier.assignee_role_id
        from public.suppliers supplier
        where supplier.org_id = v_org_id
          and supplier.id = any(array[
            case when lower(coalesce(message.module_id, '')) = 'suppliers' then public.kalam_try_uuid(message.record_id) end,
            case when lower(coalesce(message.related_module_id, '')) = 'suppliers' then public.kalam_try_uuid(message.related_record_id) end
          ]::uuid[])

        union all

        select
          'employees'::text,
          employee.assignee_type,
          employee.assignee_id,
          employee.assignee_role_id
        from public.employees employee
        where employee.org_id = v_org_id
          and employee.id = any(array[
            case when lower(coalesce(message.module_id, '')) = 'employees' then public.kalam_try_uuid(message.record_id) end,
            case when lower(coalesce(message.related_module_id, '')) = 'employees' then public.kalam_try_uuid(message.related_record_id) end
          ]::uuid[])
      ) target
      where public.kalam_can_view_module_record_from_context(
        v_permissions,
        v_user_id,
        v_role_id,
        v_allowed_user_ids,
        v_allowed_role_ids,
        target.target_module_id,
        target.assignee_type,
        target.assignee_id,
        target.assignee_role_id
      )
    )
  )
  select
    message.id,
    coalesce(nullif(message.title, ''), nullif(message.sender, ''), nullif(message.recipient, ''), 'پیامک'),
    message.module_id,
    message.record_id,
    message.related_module_id,
    public.kalam_try_uuid(message.related_record_id),
    message.customer_id,
    message.assignee_id,
    message.assignee_type,
    message.assignee_role_id,
    coalesce(nullif(message.direction, ''), 'outbound'),
    message.provider,
    message.provider_message_id,
    message.sender,
    message.recipient,
    case when coalesce(nullif(message.direction, ''), 'outbound') = 'inbound' then message.sender else message.recipient end,
    message.phone_number_id,
    message.phone_match_status,
    message.message_text,
    message.status,
    message.error_message,
    message.metadata,
    message.sent_at,
    message.received_at,
    message.resolved_message_at,
    message.created_at,
    message.updated_at
  from visible_messages message
  order by message.resolved_message_at desc nulls last, message.created_at desc, message.id desc
  limit (select effective_limit from limits);
end;
$$;


--
-- Name: get_accessible_voip_call_logs(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_voip_call_logs(p_limit integer DEFAULT 80, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, title text, direction text, status text, source_number text, destination_number text, extension text, module_id text, record_id text, related_module_id text, related_record_id uuid, phone_number_id uuid, phone_match_status text, assignee_id uuid, assignee_type text, assignee_role_id uuid, started_at timestamp with time zone, ended_at timestamp with time zone, created_at timestamp with time zone, talk_seconds integer, wait_seconds integer, call_id text, file_id text, recording_url text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with limits as (select least(greatest(coalesce(p_limit, 80), 1), 200) as effective_limit),
  candidate_calls as (
    select c.*
    from public.voip_call_logs c
    cross join limits
    where c.org_id = public.current_org_id()
      and (
        p_before_at is null
        or coalesce(c.started_at, c.created_at) < p_before_at
        or (coalesce(c.started_at, c.created_at) = p_before_at and p_before_id is not null and c.id < p_before_id)
      )
    order by c.started_at desc nulls last, c.created_at desc, c.id desc
    limit least(greatest((select effective_limit from limits) * 20, 400), 2000)
  )
  select c.id, c.title, c.direction, c.status, c.source_number, c.destination_number, c.extension,
    c.module_id, c.record_id, c.related_module_id, public.kalam_try_uuid(c.related_record_id), c.phone_number_id,
    c.phone_match_status, c.assignee_id, c.assignee_type, c.assignee_role_id, c.started_at, c.ended_at,
    c.created_at, c.talk_seconds, c.wait_seconds, c.call_id, c.file_id, c.recording_url
  from candidate_calls c
  where public.kalam_can_view_communication_record_v3(
    'voip', public.current_org_id(), c.assignee_type, c.assignee_id, c.assignee_role_id,
    c.module_id, public.kalam_try_uuid(c.record_id), c.related_module_id, public.kalam_try_uuid(c.related_record_id),
    null::uuid, c.source_number, c.destination_number, c.extension
  )
  order by c.started_at desc nulls last, c.created_at desc, c.id desc
  limit (select effective_limit from limits);
$$;


--
-- Name: get_accessible_voip_call_logs_page(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accessible_voip_call_logs_page(p_limit integer DEFAULT 80, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, title text, provider text, service_id text, direction text, status text, source_number text, destination_number text, extension text, target_extension text, target_endpoint_name text, operator_code text, module_id text, record_id text, related_module_id text, related_record_id uuid, phone_number_id uuid, phone_match_status text, assignee_id uuid, assignee_type text, assignee_role_id uuid, started_at timestamp with time zone, ended_at timestamp with time zone, created_at timestamp with time zone, talk_seconds integer, wait_seconds integer, call_id text, file_id text, recording_url text, operator_display_name text, provider_operator_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with limits as (select least(greatest(coalesce(p_limit, 80), 1), 200) as effective_limit),
  candidate_calls as (
    select c.* from public.voip_call_logs c cross join limits
    where c.org_id = public.current_org_id()
      and (p_before_at is null or coalesce(c.started_at, c.created_at) < p_before_at
        or (coalesce(c.started_at, c.created_at) = p_before_at and p_before_id is not null and c.id < p_before_id))
    order by c.started_at desc nulls last, c.created_at desc, c.id desc
    limit least(greatest((select effective_limit from limits) * 20, 400), 2000)
  )
  select c.id, c.title, c.provider, c.service_id, c.direction, c.status, c.source_number, c.destination_number,
    c.extension, c.target_extension, c.target_endpoint_name, c.operator_code,
    c.module_id, c.record_id, c.related_module_id, public.kalam_try_uuid(c.related_record_id), c.phone_number_id,
    c.phone_match_status, c.assignee_id, c.assignee_type, c.assignee_role_id, c.started_at, c.ended_at,
    c.created_at, c.talk_seconds, c.wait_seconds, c.call_id, c.file_id, c.recording_url,
    coalesce(nullif(trim(c.metadata->>'operator_display_name'), ''), nullif(trim(c.metadata->>'provider_operator_name'), '')),
    nullif(trim(c.metadata->>'provider_operator_id'), '')
  from candidate_calls c
  where public.kalam_can_view_communication_record_v3(
    'voip', public.current_org_id(), c.assignee_type, c.assignee_id, c.assignee_role_id,
    c.module_id, public.kalam_try_uuid(c.record_id), c.related_module_id, public.kalam_try_uuid(c.related_record_id),
    null::uuid, c.source_number, c.destination_number, c.extension
  )
  order by c.started_at desc nulls last, c.created_at desc, c.id desc
  limit (select effective_limit from limits);
$$;


--
-- Name: get_active_user_announcements(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_user_announcements(p_surface text, p_path text DEFAULT NULL::text, p_host text DEFAULT NULL::text) RETURNS TABLE(id uuid, kind text, title text, body text, media_items jsonb, allow_dismiss boolean, priority integer, conditions_all jsonb, conditions_any jsonb, starts_at timestamp with time zone, ends_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_surface text := public.normalize_announcement_surface(p_surface);
  v_path text := lower(trim(coalesce(p_path,'')));
  v_host text := lower(trim(coalesce(p_host,'')));
  v_org_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_role_id uuid := null;
  v_is_demo boolean := false;
begin
  if v_surface not in ('public_site','user_panel','login_page') then return; end if;
  if v_user_id is not null then select p.role_id into v_role_id from public.profiles p where p.id=v_user_id; end if;
  if v_org_id is not null then select coalesce(s.is_demo,false) into v_is_demo from public.saas_org_settings s where s.org_id=v_org_id; end if;
  return query
  select a.id, case when trim(coalesce(a.kind,'header'))='popup' then 'popup' else 'header' end,
    coalesce(a.title,''),coalesce(a.body,''),coalesce(a.media_items,'[]'::jsonb),coalesce(a.allow_dismiss,false),coalesce(a.priority,100),coalesce(a.conditions_all,'[]'::jsonb),coalesce(a.conditions_any,'[]'::jsonb),a.starts_at,a.ends_at
  from public.saas_user_announcements a
  where a.is_active and (a.starts_at is null or a.starts_at<=now()) and (a.ends_at is null or a.ends_at>=now())
    and ((v_surface='public_site' and a.show_on_public_site) or (v_surface='user_panel' and a.show_on_user_panel) or (v_surface='login_page' and a.show_on_login))
    and (coalesce(array_length(a.target_org_ids,1),0)=0 or (v_org_id is not null and v_org_id=any(a.target_org_ids)))
    and (coalesce(array_length(a.target_user_ids,1),0)=0 or (v_user_id is not null and v_user_id=any(a.target_user_ids)))
    and (coalesce(array_length(a.target_role_ids,1),0)=0 or (v_role_id is not null and v_role_id=any(a.target_role_ids)))
    and (coalesce(a.audience_scope,'all')='all' or (a.audience_scope='demo_only' and v_is_demo) or (a.audience_scope='non_demo_only' and not v_is_demo))
    and (coalesce(array_length(a.target_host_patterns,1),0)=0 or exists(select 1 from unnest(a.target_host_patterns) p(pattern) where v_host like replace(lower(trim(p.pattern)),'*','%')))
    and (coalesce(array_length(a.target_path_patterns,1),0)=0 or exists(select 1 from unnest(a.target_path_patterns) p(pattern) where v_path like replace(lower(trim(p.pattern)),'*','%')))
    and (not a.allow_dismiss or v_user_id is null or not exists(select 1 from public.saas_user_announcement_dismissals d where d.announcement_id=a.id and d.user_id=v_user_id and d.surface=v_surface and d.org_id is not distinct from v_org_id and d.dismissed_at::date=current_date))
  order by coalesce(a.priority,100),a.created_at desc;
end;
$$;


--
-- Name: get_ai_financial_snapshot(uuid, date, date, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_financial_snapshot(p_org_id uuid, p_date_from date, p_date_to date, p_include_accounting boolean DEFAULT false, p_include_sales boolean DEFAULT false, p_include_purchases boolean DEFAULT false, p_include_expenses boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with accounting_lines as (
    select
      je.id as entry_id,
      jl.id as line_id,
      coa.id as account_id,
      coa.code as account_code,
      coa.name as account_name,
      coa.account_type,
      coalesce(jl.debit, 0)::numeric as debit,
      coalesce(jl.credit, 0)::numeric as credit
    from public.journal_entries je
    join public.journal_lines jl on jl.entry_id = je.id
    join public.chart_of_accounts coa
      on coa.id = jl.account_id
      and coa.org_id = p_org_id
    where je.org_id = p_org_id
      and p_include_accounting
      and je.status = 'posted'
      and je.entry_date between p_date_from and p_date_to
      and coa.account_type in ('income', 'expense')
  ),
  account_totals as (
    select
      account_id,
      account_code,
      account_name,
      account_type,
      sum(debit)::numeric as debit,
      sum(credit)::numeric as credit,
      case
        when account_type = 'income' then sum(credit - debit)
        else sum(debit - credit)
      end::numeric as amount,
      count(*)::integer as line_count
    from accounting_lines
    group by account_id, account_code, account_name, account_type
  ),
  accounting_summary as (
    select
      coalesce(sum(amount) filter (where account_type = 'income'), 0)::numeric as income_total,
      coalesce(sum(amount) filter (where account_type = 'expense'), 0)::numeric as expense_total,
      coalesce(sum(line_count), 0)::integer as line_count
    from account_totals
  ),
  sales_summary as (
    select
      count(*)::integer as record_count,
      coalesce(sum(total_invoice_amount), 0)::numeric as total
    from public.invoices
    where p_include_sales
      and org_id = p_org_id
      and invoice_date between p_date_from and p_date_to
      and status in ('confirmed', 'final', 'prepayment', 'settled', 'completed')
  ),
  purchase_summary as (
    select
      count(*)::integer as record_count,
      coalesce(sum(total_invoice_amount), 0)::numeric as total
    from public.purchase_invoices
    where p_include_purchases
      and org_id = p_org_id
      and invoice_date between p_date_from and p_date_to
      and status in ('final', 'settled', 'completed')
  ),
  expense_summary as (
    select
      count(*)::integer as record_count,
      coalesce(sum(total_amount), 0)::numeric as total
    from public.expense_documents
    where p_include_expenses
      and org_id = p_org_id
      and expense_date between p_date_from and p_date_to
      and status in ('approved', 'paid', 'posted')
  )
  select jsonb_build_object(
    'kind', 'financial_snapshot',
    'date_from', p_date_from,
    'date_to', p_date_to,
    'accounting', jsonb_build_object(
      'basis', 'posted_journal_entries',
      'available', (select line_count > 0 from accounting_summary),
      'income_total', (select income_total from accounting_summary),
      'expense_total', (select expense_total from accounting_summary),
      'net_profit', (
        select income_total - expense_total
        from accounting_summary
      ),
      'posted_entry_count', (
        select count(distinct entry_id)::integer
        from accounting_lines
      ),
      'line_count', (select line_count from accounting_summary),
      'unposted_entry_count', (
        select case when p_include_accounting then count(*)::integer else 0 end
        from public.journal_entries je
        where p_include_accounting
          and je.org_id = p_org_id
          and je.entry_date between p_date_from and p_date_to
          and je.status <> 'posted'
      ),
      'top_income_accounts', coalesce((
        select jsonb_agg(jsonb_build_object(
          'account_code', q.account_code,
          'account_name', q.account_name,
          'amount', q.amount,
          'line_count', q.line_count
        ) order by abs(q.amount) desc)
        from (
          select account_code, account_name, amount, line_count
          from account_totals
          where account_type = 'income' and amount <> 0
          order by abs(amount) desc
          limit 10
        ) q
      ), '[]'::jsonb),
      'top_expense_accounts', coalesce((
        select jsonb_agg(jsonb_build_object(
          'account_code', q.account_code,
          'account_name', q.account_name,
          'amount', q.amount,
          'line_count', q.line_count
        ) order by abs(q.amount) desc)
        from (
          select account_code, account_name, amount, line_count
          from account_totals
          where account_type = 'expense' and amount <> 0
          order by abs(amount) desc
          limit 10
        ) q
      ), '[]'::jsonb)
    ),
    'operational', jsonb_build_object(
      'basis', 'finalized_operational_records',
      'approximate', true,
      'sales', case when p_include_sales then (
        select jsonb_build_object('record_count', record_count, 'total', total)
        from sales_summary
      ) else null end,
      'purchases', case when p_include_purchases then (
        select jsonb_build_object('record_count', record_count, 'total', total)
        from purchase_summary
      ) else null end,
      'expenses', case when p_include_expenses then (
        select jsonb_build_object('record_count', record_count, 'total', total)
        from expense_summary
      ) else null end
    )
  );
$$;


--
-- Name: get_ai_notification_snapshot_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_notification_snapshot_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 with events as materialized(select * from public.ai_notification_events),
 unread as materialized(select * from events where is_unread),
 grouped as (select conversation_key,thread_id,agent_key,count(*) as unread_count,max(created_at) as latest
  from unread group by conversation_key,thread_id,agent_key),
 agents as (select agent_key,sum(unread_count) as unread_count from grouped where agent_key is not null group by agent_key),
 recent as (select distinct on (conversation_key) * from unread where source_type='ai_message' order by conversation_key,created_at desc,source_id desc)
 select jsonb_build_object(
  'total',(select count(*) from unread),'agentNoteTotal',(select count(*) from unread where source_type='note'),
  'communicationAgentNoteTotal',(select count(*) from unread where source_type='note' and in_communication),
  'alertAgentNoteTotal',(select count(*) from events where source_type='note' and in_system_unread),
  'byAgent',coalesce((select jsonb_object_agg(agent_key,unread_count) from agents),'{}'::jsonb),
  'byConversation',coalesce((select jsonb_object_agg(conversation_key,unread_count) from
    (select * from grouped order by latest desc limit 200) g),'{}'::jsonb),
  'items',coalesce((select jsonb_agg(to_jsonb(r)-'content'||jsonb_build_object('content',left(r.content,500))) from
    (select * from recent order by created_at desc,source_id desc limit 20) r),'[]'::jsonb)
 );
$$;


--
-- Name: get_ai_usage_complete_statistics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_usage_complete_statistics(p_org_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with finalized as materialized (
    select org_id, user_id, model, capability, agent_key,
      coalesce(billed_amount_irt,0) billed, coalesce(raw_cost_irt,0) raw,
      coalesce(cached_input_tokens,0) cached, coalesce(cache_savings_irt,0) savings,
      public.ai_usage_token_count(usage) tokens
    from public.org_ai_usage_ledger
    where status = 'finalized' and (p_org_id is null or org_id = p_org_id)
  ), orgs as (
    select org_id, count(*) requests, sum(billed) billed_irt, sum(raw) raw_irt,
      array_agg(distinct model) filter (where model is not null) models
    from finalized group by org_id
  ), users as (
    select user_id, count(*) requests, sum(tokens) used_tokens, sum(billed) used_irt
    from finalized where user_id is not null group by user_id
  )
  select jsonb_build_object(
    'totals', (select jsonb_build_object('requests',count(*),
      'billed_amount_irt',coalesce(sum(billed),0),'raw_cost_irt',coalesce(sum(raw),0),
      'cached_input_tokens',coalesce(sum(cached),0),'cache_savings_irt',coalesce(sum(savings),0)) from finalized),
    'by_model', coalesce((select jsonb_object_agg(model, amount) from (select model,sum(billed) amount from finalized where model is not null group by model) s),'{}'::jsonb),
    'by_capability', coalesce((select jsonb_object_agg(capability, amount) from (select capability,sum(billed) amount from finalized where capability is not null group by capability) s),'{}'::jsonb),
    'by_agent', coalesce((select jsonb_object_agg(agent_key, amount) from (select agent_key,sum(billed) amount from finalized where agent_key is not null group by agent_key) s),'{}'::jsonb),
    'by_org', coalesce((select jsonb_agg(to_jsonb(orgs)) from orgs),'[]'::jsonb),
    'by_user', case when p_org_id is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(users)) from users),'[]'::jsonb) end
  );
$$;


--
-- Name: get_ai_user_daily_usage(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_user_daily_usage(p_org_id uuid, p_user_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('usedTokens',coalesce(sum(public.ai_usage_token_count(usage)),0),
    'usedIrt',coalesce(sum(billed_amount_irt),0),'requestCount',count(*))
  from public.org_ai_usage_ledger
  where org_id=p_org_id and user_id=p_user_id and status='finalized' and created_at>=p_start and created_at<p_end;
$$;


--
-- Name: get_bot_conversation_timeline(uuid, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bot_conversation_timeline(p_bot_group_id uuid, p_limit integer DEFAULT 10, p_before_cursor text DEFAULT NULL::text, p_include_unread_window boolean DEFAULT true) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.get_bot_conversation_timeline_legacy_unbounded(
    p_bot_group_id,
    least(greatest(coalesce(p_limit, 10), 1), 50),
    p_before_cursor,
    false
  );
$$;


--
-- Name: FUNCTION get_bot_conversation_timeline(p_bot_group_id uuid, p_limit integer, p_before_cursor text, p_include_unread_window boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_bot_conversation_timeline(p_bot_group_id uuid, p_limit integer, p_before_cursor text, p_include_unread_window boolean) IS 'Bounded bot timeline API. Unread count is returned separately; items never use the legacy unbounded unread window.';


--
-- Name: get_bot_conversation_timeline_legacy_unbounded(uuid, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bot_conversation_timeline_legacy_unbounded(p_bot_group_id uuid, p_limit integer DEFAULT 10, p_before_cursor text DEFAULT NULL::text, p_include_unread_window boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_limit integer := greatest(coalesce(p_limit, 10), 1);
  v_unread_count integer := 0;
  v_first_unread_id text := null;
  v_has_more_before boolean := false;
  v_next_before_cursor text := null;
  v_before_ts timestamptz := null;
  v_before_id text := null;
  v_items jsonb := '[]'::jsonb;
begin
  if v_user_id is null or v_org_id is null or p_bot_group_id is null then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null);
  end if;

  select p.role_id into v_role_id
  from public.profiles p
  where p.id = v_user_id
  limit 1;

  if not exists (
    select 1
    from public.counterparty_bot_groups g
    where g.id = p_bot_group_id
      and g.org_id = v_org_id
      and (
        (
          coalesce(jsonb_array_length(g.metadata->'allowed_user_ids'), 0) = 0
          and coalesce(jsonb_array_length(g.metadata->'allowed_role_ids'), 0) = 0
        )
        or v_user_id = any(public.kalam_jsonb_uuid_array(g.metadata->'allowed_user_ids'))
        or (v_role_id is not null and v_role_id = any(public.kalam_jsonb_uuid_array(g.metadata->'allowed_role_ids')))
      )
  ) then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null);
  end if;

  if nullif(trim(coalesce(p_before_cursor, '')), '') is not null then
    v_before_ts := nullif(split_part(p_before_cursor, '|', 1), '')::timestamptz;
    v_before_id := nullif(split_part(p_before_cursor, '|', 2), '');
  end if;

  select
    count(*) filter (where m.direction = 'inbound' and rs.read_at is null and rs.dismissed_at is null)::integer,
    min(m.id::text) filter (where m.direction = 'inbound' and rs.read_at is null and rs.dismissed_at is null)
  into v_unread_count, v_first_unread_id
  from public.counterparty_bot_messages m
  left join public.notification_read_states rs
    on rs.org_id = v_org_id
   and rs.user_id = v_user_id
   and rs.section = 'bot_messages'
   and rs.source_type = 'counterparty_bot_message'
   and rs.source_id = m.id::text
  where m.org_id = v_org_id
    and m.bot_group_id = p_bot_group_id;

  if v_before_ts is not null then
    with page as (
      select
        m.id,
        m.bot_group_id,
        m.direction,
        m.message_type,
        m.chat_id,
        m.provider_message_id,
        m.content_text,
        m.file_url,
        m.file_name,
        m.mime_type,
        m.payload,
        m.created_by,
        m.created_at
      from public.counterparty_bot_messages m
      where m.org_id = v_org_id
        and m.bot_group_id = p_bot_group_id
        and (
          m.created_at < v_before_ts
          or (m.created_at = v_before_ts and m.id::text < coalesce(v_before_id, ''))
        )
      order by m.created_at desc, m.id desc
      limit v_limit
    ),
    ordered as (
      select * from page order by created_at asc, id asc
    ),
    earliest as (
      select created_at, id::text as id_text
      from ordered
      order by created_at asc, id asc
      limit 1
    )
    select
      coalesce(jsonb_agg(to_jsonb(ordered.*) order by ordered.created_at asc, ordered.id asc), '[]'::jsonb),
      exists(
        select 1
        from public.counterparty_bot_messages m
        join earliest e on true
        where m.org_id = v_org_id
          and m.bot_group_id = p_bot_group_id
          and (
            m.created_at < e.created_at
            or (m.created_at = e.created_at and m.id::text < e.id_text)
          )
      ),
      (select public.kalam_cursor_value(created_at, id_text) from earliest)
    into v_items, v_has_more_before, v_next_before_cursor
    from ordered;

    return jsonb_build_object(
      'items', coalesce(v_items, '[]'::jsonb),
      'unread_count', coalesce(v_unread_count, 0),
      'first_unread_id', v_first_unread_id,
      'has_more_before', coalesce(v_has_more_before, false),
      'next_before_cursor', v_next_before_cursor
    );
  end if;

  if p_include_unread_window and coalesce(v_unread_count, 0) > 10 then
    with unread_rows as (
      select
        m.id,
        m.bot_group_id,
        m.direction,
        m.message_type,
        m.chat_id,
        m.provider_message_id,
        m.content_text,
        m.file_url,
        m.file_name,
        m.mime_type,
        m.payload,
        m.created_by,
        m.created_at
      from public.counterparty_bot_messages m
      left join public.notification_read_states rs
        on rs.org_id = v_org_id
       and rs.user_id = v_user_id
       and rs.section = 'bot_messages'
       and rs.source_type = 'counterparty_bot_message'
       and rs.source_id = m.id::text
      where m.org_id = v_org_id
        and m.bot_group_id = p_bot_group_id
        and m.direction = 'inbound'
        and rs.read_at is null
        and rs.dismissed_at is null
      order by m.created_at asc, m.id asc
    ),
    earliest as (
      select created_at, id::text as id_text
      from unread_rows
      order by created_at asc, id asc
      limit 1
    )
    select
      coalesce(jsonb_agg(to_jsonb(unread_rows.*) order by unread_rows.created_at asc, unread_rows.id asc), '[]'::jsonb),
      exists(
        select 1
        from public.counterparty_bot_messages m
        join earliest e on true
        where m.org_id = v_org_id
          and m.bot_group_id = p_bot_group_id
          and (
            m.created_at < e.created_at
            or (m.created_at = e.created_at and m.id::text < e.id_text)
          )
      ),
      (select public.kalam_cursor_value(created_at, id_text) from earliest)
    into v_items, v_has_more_before, v_next_before_cursor
    from unread_rows;
  else
    with latest_rows as (
      select
        m.id,
        m.bot_group_id,
        m.direction,
        m.message_type,
        m.chat_id,
        m.provider_message_id,
        m.content_text,
        m.file_url,
        m.file_name,
        m.mime_type,
        m.payload,
        m.created_by,
        m.created_at
      from public.counterparty_bot_messages m
      where m.org_id = v_org_id
        and m.bot_group_id = p_bot_group_id
      order by m.created_at desc, m.id desc
      limit greatest(v_limit, 10)
    ),
    ordered as (
      select * from latest_rows order by created_at asc, id asc
    ),
    earliest as (
      select created_at, id::text as id_text
      from ordered
      order by created_at asc, id asc
      limit 1
    )
    select
      coalesce(jsonb_agg(to_jsonb(ordered.*) order by ordered.created_at asc, ordered.id asc), '[]'::jsonb),
      exists(
        select 1
        from public.counterparty_bot_messages m
        join earliest e on true
        where m.org_id = v_org_id
          and m.bot_group_id = p_bot_group_id
          and (
            m.created_at < e.created_at
            or (m.created_at = e.created_at and m.id::text < e.id_text)
          )
      ),
      (select public.kalam_cursor_value(created_at, id_text) from earliest)
    into v_items, v_has_more_before, v_next_before_cursor
    from ordered;
  end if;

  return jsonb_build_object(
    'items', coalesce(v_items, '[]'::jsonb),
    'unread_count', coalesce(v_unread_count, 0),
    'first_unread_id', v_first_unread_id,
    'has_more_before', coalesce(v_has_more_before, false),
    'next_before_cursor', v_next_before_cursor
  );
end;
$$;


--
-- Name: get_bot_group_timeline_v2(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bot_group_timeline_v2(p_bot_group_id uuid, p_limit integer DEFAULT 40, p_before_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_limit integer := least(greatest(coalesce(p_limit, 40), 1), 50);
  v_before_ts timestamptz := null;
  v_before_id text := null;
begin
  if v_user_id is null
    or v_org_id is null
    or p_bot_group_id is null
    or not public.kalam_can_access_bot_group(p_bot_group_id, v_org_id) then
    return jsonb_build_object(
      'items', '[]'::jsonb,
      'unread_count', 0,
      'first_unread_id', null,
      'has_more_before', false,
      'next_before_cursor', null,
      'read_model', 'cursor'
    );
  end if;

  if nullif(trim(coalesce(p_before_cursor, '')), '') is not null then
    v_before_ts := nullif(split_part(p_before_cursor, '|', 1), '')::timestamptz;
    v_before_id := nullif(split_part(p_before_cursor, '|', 2), '');
  end if;

  return (
    with cursor_state as materialized (
      select read_through_at, read_through_id
      from public.communication_read_cursors
      where org_id = v_org_id
        and user_id = v_user_id
        and channel = 'bot'
        and conversation_key = 'bot:' || p_bot_group_id::text
    ),
    visible as materialized (
      select
        message_row.id,
        message_row.bot_group_id,
        message_row.direction,
        message_row.message_type,
        message_row.chat_id,
        message_row.provider_message_id,
        message_row.content_text,
        message_row.file_url,
        message_row.file_name,
        message_row.mime_type,
        message_row.payload,
        message_row.created_by,
        message_row.created_at,
        (
          message_row.direction <> 'inbound'
          or read_state.read_at is not null
          or read_state.dismissed_at is not null
          or (
            cursor_state.read_through_at is not null
            and (
              message_row.created_at < cursor_state.read_through_at
              or (
                message_row.created_at = cursor_state.read_through_at
                and message_row.id::text <= coalesce(cursor_state.read_through_id, message_row.id::text)
              )
            )
          )
        ) as is_read
      from public.counterparty_bot_messages message_row
      left join public.notification_read_states read_state
        on read_state.org_id = v_org_id
       and read_state.user_id = v_user_id
       and read_state.section = 'bot_messages'
       and read_state.source_type = 'counterparty_bot_message'
       and read_state.source_id = message_row.id::text
      left join cursor_state on true
      where message_row.org_id = v_org_id
        and message_row.bot_group_id = p_bot_group_id
    ),
    windowed as (
      select *
      from visible
      where v_before_ts is null
         or created_at < v_before_ts
         or (created_at = v_before_ts and id::text < coalesce(v_before_id, ''))
      order by created_at desc, id desc
      limit v_limit + 1
    ),
    page_desc as (
      select * from windowed order by created_at desc, id desc limit v_limit
    ),
    page as (
      select * from page_desc order by created_at asc, id asc
    ),
    earliest as (
      select created_at, id::text as id_text from page order by created_at asc, id asc limit 1
    )
    select jsonb_build_object(
      'items', coalesce((select 
jsonb_agg(
  to_jsonb(page) || jsonb_build_object(
    'payload',
    coalesce(page.payload, '{}'::jsonb) || jsonb_build_object(
      'read_receipts',
      public.kalam_message_read_receipts_v1(
        v_org_id,
        'bot',
        'bot:' || p_bot_group_id::text,
        page.created_by,
        page.created_at,
        page.id
      )
    )
  )
  order by page.created_at asc, page.id asc
) from page), '[]'::jsonb),
      'unread_count', coalesce((select count(*) filter (where not is_read)::integer from visible), 0),
      'first_unread_id', (select id::text from page where not is_read order by created_at asc, id asc limit 1),
      'has_more_before', (select count(*) > v_limit from windowed),
      'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
      'read_model', 'cursor'
    )
  );
end;
$$;


--
-- Name: get_cash_bank_dashboard_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cash_bank_dashboard_stats() RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'bankAccounts', (select count(*) from public.bank_accounts where org_id = public.current_org_id() and is_active = true),
    'cashBoxes', (select count(*) from public.cash_boxes where org_id = public.current_org_id() and is_active = true),
    'pettyFunds', (select count(*) from public.petty_funds where org_id = public.current_org_id() and is_active = true),
    'openCheques', (select count(*) from public.cheques where org_id = public.current_org_id() and status in ('new', 'in_bank')),
    'chequesAmount', (select coalesce(sum(amount), 0) from public.cheques where org_id = public.current_org_id() and status in ('new', 'in_bank')),
    'openBarters', (select count(*) from public.barters where org_id = public.current_org_id() and status in ('open', 'partial')),
    'bartersAmount', (select coalesce(sum(remaining_amount), 0) from public.barters where org_id = public.current_org_id() and status in ('open', 'partial'))
  )
  where public.current_org_id() is not null;
$$;


--
-- Name: get_cash_bank_unified_ledger_page(integer, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cash_bank_unified_ledger_page(p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_sort_field text DEFAULT 'date'::text, p_sort_order text DEFAULT 'desc'::text, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := least(greatest(coalesce(p_page_size, 20), 10), 200);
  v_sort_field text := case lower(coalesce(p_sort_field, ''))
    when 'row_type' then 'row_type' when 'source_label' then 'source_label'
    when 'payment_type' then 'payment_type' when 'status' then 'status'
    when 'date' then 'date' when 'amount' then 'amount'
    when 'invoice_label' then 'invoice_label' when 'person_label' then 'person_label'
    when 'bank_label' then 'bank_label' when 'cheque_label' then 'cheque_label'
    when 'description' then 'description' else 'date' end;
  v_sort_order text := case when lower(coalesce(p_sort_order, '')) = 'asc' then 'asc' else 'desc' end;
begin
  if v_org_id is null then
    return jsonb_build_object('rows', '[]'::jsonb, 'total', 0);
  end if;

  return (
    with filtered as (
      select * from public.cash_bank_unified_ledger_filtered(p_filters)
    ), ordered as (
      select * from filtered
      order by
        case when row_type = 'opening' then 0 else 1 end asc,
        case when v_sort_field = 'row_type' and v_sort_order = 'asc' then row_type end asc, case when v_sort_field = 'row_type' and v_sort_order = 'desc' then row_type end desc,
        case when v_sort_field = 'source_label' and v_sort_order = 'asc' then source_label end asc, case when v_sort_field = 'source_label' and v_sort_order = 'desc' then source_label end desc,
        case when v_sort_field = 'payment_type' and v_sort_order = 'asc' then payment_type end asc, case when v_sort_field = 'payment_type' and v_sort_order = 'desc' then payment_type end desc,
        case when v_sort_field = 'status' and v_sort_order = 'asc' then status end asc, case when v_sort_field = 'status' and v_sort_order = 'desc' then status end desc,
        case when v_sort_field = 'date' and v_sort_order = 'asc' then row_date end asc nulls last, case when v_sort_field = 'date' and v_sort_order = 'desc' then row_date end desc nulls last,
        case when v_sort_field = 'amount' and v_sort_order = 'asc' then amount end asc, case when v_sort_field = 'amount' and v_sort_order = 'desc' then amount end desc,
        case when v_sort_field = 'invoice_label' and v_sort_order = 'asc' then invoice_label end asc, case when v_sort_field = 'invoice_label' and v_sort_order = 'desc' then invoice_label end desc,
        case when v_sort_field = 'person_label' and v_sort_order = 'asc' then person_label end asc, case when v_sort_field = 'person_label' and v_sort_order = 'desc' then person_label end desc,
        case when v_sort_field = 'bank_label' and v_sort_order = 'asc' then bank_label end asc, case when v_sort_field = 'bank_label' and v_sort_order = 'desc' then bank_label end desc,
        case when v_sort_field = 'cheque_label' and v_sort_order = 'asc' then cheque_label end asc, case when v_sort_field = 'cheque_label' and v_sort_order = 'desc' then cheque_label end desc,
        case when v_sort_field = 'description' and v_sort_order = 'asc' then description end asc, case when v_sort_field = 'description' and v_sort_order = 'desc' then description end desc,
        row_key asc
    ), paged as (
      select * from ordered limit v_page_size offset (v_page - 1) * v_page_size
    )
    select jsonb_build_object('rows', coalesce(jsonb_agg(to_jsonb(paged)), '[]'::jsonb), 'total', (select count(*) from filtered)) from paged
  );
end;
$$;


--
-- Name: get_cash_bank_unified_ledger_totals(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cash_bank_unified_ledger_totals(p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'receiptTotal', coalesce(sum(amount) filter (where row_type = 'receipt'), 0)::text,
    'paymentTotal', coalesce(sum(amount) filter (where row_type = 'payment'), 0)::text,
    'rowCount', count(*)
  ) from public.cash_bank_unified_ledger_filtered(p_filters);
$$;


--
-- Name: get_cms_blog_post_by_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cms_blog_post_by_slug(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_post jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', p.id,
    'title', p.title,
    'slug', p.slug,
    'excerpt', p.excerpt,
    'content_blocks', p.content_blocks,
    'cover_image_url', p.cover_image_url,
    'author_id', p.author_id,
    'author_name', pr.full_name,
    'author_avatar', pr.avatar_url,
    'status', p.status,
    'is_featured', p.is_featured,
    'published_at', p.published_at,
    'reading_time_minutes', p.reading_time_minutes,
    'seo_title', p.seo_title,
    'seo_description', p.seo_description,
    'og_image_url', p.og_image_url,
    'canonical_url', p.canonical_url,
    'focus_keyword', p.focus_keyword,
    'schema_extra', p.schema_extra,
    'categories', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'slug', c.slug))
      FROM public.cms_blog_post_categories bpc
      JOIN public.cms_categories c ON c.id = bpc.category_id
      WHERE bpc.post_id = p.id
    ), '[]'::jsonb),
    'tags', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'slug', t.slug))
      FROM public.cms_blog_post_tags bpt
      JOIN public.cms_tags t ON t.id = bpt.tag_id
      WHERE bpt.post_id = p.id
    ), '[]'::jsonb),
    'created_at', p.created_at,
    'updated_at', p.updated_at
  ) INTO v_post
  FROM public.cms_blog_posts p
  LEFT JOIN public.profiles pr ON pr.id = p.author_id
  WHERE p.slug = p_slug AND p.status = 'published';

  RETURN v_post;
END;
$$;


--
-- Name: get_cms_blog_posts(text, boolean, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cms_blog_posts(p_status text DEFAULT 'published'::text, p_featured boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_category text DEFAULT NULL::text, p_tag text DEFAULT NULL::text) RETURNS TABLE(id uuid, title text, slug text, excerpt text, cover_image_url text, author_name text, author_avatar text, status text, is_featured boolean, published_at timestamp with time zone, reading_time_minutes integer, seo_title text, seo_description text, og_image_url text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.id, p.title, p.slug, p.excerpt, p.cover_image_url,
    pr.full_name, pr.avatar_url, p.status, p.is_featured, p.published_at,
    p.reading_time_minutes, p.seo_title, p.seo_description, p.og_image_url, p.created_at
  from public.cms_blog_posts p
  left join public.profiles pr on pr.id = p.author_id
  where p.status = 'published'
    and (p_featured is null or p.is_featured = p_featured)
    and (p_category is null or exists (
      select 1 from public.cms_blog_post_categories bpc
      join public.cms_categories c on c.id = bpc.category_id
      where bpc.post_id = p.id and c.slug = p_category
    ))
    and (p_tag is null or exists (
      select 1 from public.cms_blog_post_tags bpt
      join public.cms_tags t on t.id = bpt.tag_id
      where bpt.post_id = p.id and t.slug = p_tag
    ))
  order by p.published_at desc nulls last
  limit greatest(least(coalesce(p_limit, 20), 100), 1)
  offset greatest(coalesce(p_offset, 0), 0)
$$;


--
-- Name: get_cms_contextual_tutorial_posts(text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cms_contextual_tutorial_posts(p_contexts text[], p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, title text, slug text, excerpt text, cover_image_url text, help_group text, help_order integer, content_blocks jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.id,
    p.title,
    p.slug,
    p.excerpt,
    p.cover_image_url,
    coalesce(nullif(trim(p.help_group), ''), 'راهنما') as help_group,
    coalesce(p.help_order, 0) as help_order,
    p.content_blocks
  from public.cms_tutorial_posts p
  where p.status = 'published'
    and coalesce(p.help_contexts, '{}'::text[]) && coalesce(p_contexts, '{}'::text[])
  order by coalesce(p.help_order, 0), p.title
  limit greatest(least(coalesce(p_limit, 100), 100), 1)
$$;


