--
-- Name: get_cms_public_categories(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cms_public_categories(p_content_type text) RETURNS TABLE(id uuid, name text, slug text, sort_order integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
