--
-- Name: get_cms_tutorial_post_by_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cms_tutorial_post_by_slug(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_post jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', p.id,
    'title', p.title,
    'slug', p.slug,
    'excerpt', p.excerpt,
    'content_blocks', p.content_blocks,
    'cover_image_url', p.cover_image_url,
    'author_id', p.author_id,
    'author_name', pr.full_name,
    'author_avatar', pr.avatar_url,
    'status', p.status,
    'is_featured', p.is_featured,
    'published_at', p.published_at,
    'reading_time_minutes', p.reading_time_minutes,
    'difficulty_level', p.difficulty_level,
    'duration_minutes', p.duration_minutes,
    'series_id', p.series_id,
    'series_order', p.series_order,
    'series', CASE WHEN p.series_id IS NOT NULL THEN (
      SELECT jsonb_build_object(
        'id', s.id, 'title', s.title, 'slug', s.slug,
        'posts', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', sp.id, 'title', sp.title, 'slug', sp.slug,
            'series_order', sp.series_order, 'status', sp.status
          ) ORDER BY sp.series_order)
          FROM public.cms_tutorial_posts sp
          WHERE sp.series_id = p.series_id AND sp.status = 'published'
        ), '[]'::jsonb)
      )
      FROM public.cms_tutorial_series s WHERE s.id = p.series_id
    ) ELSE NULL END,
    'seo_title', p.seo_title,
    'seo_description', p.seo_description,
    'og_image_url', p.og_image_url,
    'canonical_url', p.canonical_url,
    'focus_keyword', p.focus_keyword,
    'schema_extra', p.schema_extra,
    'categories', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'slug', c.slug))
      FROM public.cms_tutorial_post_categories tpc
      JOIN public.cms_categories c ON c.id = tpc.category_id
      WHERE tpc.post_id = p.id
    ), '[]'::jsonb),
    'tags', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'slug', t.slug))
      FROM public.cms_tutorial_post_tags tpt
      JOIN public.cms_tags t ON t.id = tpt.tag_id
      WHERE tpt.post_id = p.id
    ), '[]'::jsonb),
    'created_at', p.created_at,
    'updated_at', p.updated_at
  ) INTO v_post
  FROM public.cms_tutorial_posts p
  LEFT JOIN public.profiles pr ON pr.id = p.author_id
  WHERE p.slug = p_slug AND p.status = 'published';

  RETURN v_post;
END;
$$;


--
-- Name: get_cms_tutorial_posts(text, boolean, integer, integer, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cms_tutorial_posts(p_status text DEFAULT 'published'::text, p_featured boolean DEFAULT NULL::boolean, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_category text DEFAULT NULL::text, p_tag text DEFAULT NULL::text, p_series_id uuid DEFAULT NULL::uuid, p_difficulty text DEFAULT NULL::text) RETURNS TABLE(id uuid, title text, slug text, excerpt text, cover_image_url text, author_name text, author_avatar text, status text, is_featured boolean, published_at timestamp with time zone, reading_time_minutes integer, difficulty_level text, duration_minutes integer, series_id uuid, series_order integer, seo_title text, seo_description text, og_image_url text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.id, p.title, p.slug, p.excerpt, p.cover_image_url,
    pr.full_name, pr.avatar_url, p.status, p.is_featured, p.published_at,
    p.reading_time_minutes, p.difficulty_level, p.duration_minutes,
    p.series_id, p.series_order, p.seo_title, p.seo_description, p.og_image_url, p.created_at
  from public.cms_tutorial_posts p
  left join public.profiles pr on pr.id = p.author_id
  where p.status = 'published'
    and (p_featured is null or p.is_featured = p_featured)
    and (p_series_id is null or p.series_id = p_series_id)
    and (p_difficulty is null or p.difficulty_level = p_difficulty)
    and (p_category is null or exists (
      select 1 from public.cms_tutorial_post_categories tpc
      join public.cms_categories c on c.id = tpc.category_id
      where tpc.post_id = p.id and c.slug = p_category
    ))
    and (p_tag is null or exists (
      select 1 from public.cms_tutorial_post_tags tpt
      join public.cms_tags t on t.id = tpt.tag_id
      where tpt.post_id = p.id and t.slug = p_tag
    ))
  order by case when p_series_id is not null then p.series_order else 0 end,
    p.published_at desc nulls last
  limit greatest(least(coalesce(p_limit, 20), 100), 1)
  offset greatest(coalesce(p_offset, 0), 0)
$$;


--
-- Name: get_communication_badge_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_communication_badge_summary() RETURNS TABLE(internal_unread integer, bot_unread integer, total_unread integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select auth.uid() as user_id, public.current_org_id() as org_id, p.role_id
    from public.profiles p
    where p.id = auth.uid()
      and p.org_id = public.current_org_id()
    limit 1
  ),
  internal_scoped as (
    select
      me.user_id,
      me.org_id,
      n.id as message_id,
      n.author_id,
      n.created_at,
      coalesce(
        nii.conversation_key,
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
        )
      ) as conversation_key,
      rs.read_at,
      rs.dismissed_at
    from me
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'notes'
     and nii.source_type = 'note'
     and lower(trim(coalesce(nii.category, ''))) not in ('system', 'assistant')
     and (
       nii.is_org_wide = true
       or me.user_id = any(nii.target_user_ids)
       or (me.role_id is not null and me.role_id = any(nii.target_role_ids))
     )
    join public.notes n
      on n.id::text = nii.source_id
     and n.org_id = nii.org_id
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'notes'
     and rs.source_type = 'note'
     and rs.source_id = nii.source_id
  ),
  internal_total as (
    select count(*)::integer as value
    from internal_scoped scoped
    left join public.communication_read_cursors crc
      on crc.org_id = scoped.org_id
     and crc.user_id = scoped.user_id
     and crc.channel = 'internal'
     and crc.conversation_key = scoped.conversation_key
    where scoped.conversation_key is not null
      and scoped.conversation_key <> 'system'
      and scoped.author_id is distinct from scoped.user_id
      and scoped.read_at is null
      and scoped.dismissed_at is null
      and not (
        crc.read_through_at is not null
        and (
          scoped.created_at < crc.read_through_at
          or (
            scoped.created_at = crc.read_through_at
            and scoped.message_id::text <= coalesce(crc.read_through_id, scoped.message_id::text)
          )
        )
      )
  ),
  bot_total as (
    select count(*)::integer as value
    from me
    join public.counterparty_bot_groups g
      on g.org_id = me.org_id
     and public.kalam_can_access_bot_group(g.id, g.org_id)
    join public.counterparty_bot_messages m
      on m.bot_group_id = g.id
     and m.org_id = g.org_id
     and m.direction = 'inbound'
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'bot_messages'
     and rs.source_type = 'counterparty_bot_message'
     and rs.source_id = m.id::text
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id
     and crc.user_id = me.user_id
     and crc.channel = 'bot'
     and crc.conversation_key = 'bot:' || g.id::text
    where rs.read_at is null
      and rs.dismissed_at is null
      and not (
        crc.read_through_at is not null
        and (
          m.created_at < crc.read_through_at
          or (
            m.created_at = crc.read_through_at
            and m.id::text <= coalesce(crc.read_through_id, m.id::text)
          )
        )
      )
  )
  select
    coalesce(internal_total.value, 0)::integer,
    coalesce(bot_total.value, 0)::integer,
    (coalesce(internal_total.value, 0) + coalesce(bot_total.value, 0))::integer
  from internal_total
  cross join bot_total;
$$;


--
-- Name: get_communication_badge_summary_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_communication_badge_summary_v2() RETURNS TABLE(internal_unread integer, bot_unread integer, total_unread integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with summary as (
    select section, unread_count
    from public.get_notification_unread_summary_v1('chat')
  )
  select
    coalesce(max(unread_count) filter (where section = 'notes'), 0)::integer as internal_unread,
    coalesce(max(unread_count) filter (where section = 'bot_messages'), 0)::integer as bot_unread,
    coalesce(sum(unread_count), 0)::integer as total_unread
  from summary;
$$;


--
-- Name: get_communication_conversations(text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_communication_conversations(p_channel text DEFAULT 'internal'::text, p_before_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 80) RETURNS TABLE(section text, conversation_key text, kind text, title text, subtitle text, avatar_url text, role_label text, note_count integer, unread_count integer, latest_message_at timestamp with time zone, last_message_preview text, user_id uuid, group_id uuid, bot_group_id uuid, channel_type text, status text, counterparty_label text, bot_chat_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select
      auth.uid() as user_id,
      public.current_org_id() as org_id,
      p.role_id
    from public.profiles p
    where p.id = auth.uid()
      and p.org_id = public.current_org_id()
    limit 1
  ),
  note_raw as (
    select
      'notes'::text as section,
      coalesce(
        nii.conversation_key,
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id,
          n.id,
          n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ) as conversation_key,
      nullif(trim(coalesce(nii.payload->>'chat_group_id', n.metadata->>'chat_group_id')), '') as chat_group_id,
      n.id as note_id,
      n.author_id,
      n.created_at,
      nullif(trim(coalesce(nii.body, '')), '') as preview,
      rs.read_at is not null or rs.dismissed_at is not null or n.author_id = me.user_id as is_read
    from me
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'notes'
     and nii.source_type = 'note'
     and lower(trim(coalesce(nii.category, ''))) <> 'system'
     and (
       nii.is_org_wide = true
       or me.user_id = any(nii.target_user_ids)
       or (me.role_id is not null and me.role_id = any(nii.target_role_ids))
     )
    join public.notes n
      on n.id::text = nii.source_id
     and n.org_id = nii.org_id
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'notes'
     and rs.source_type = 'note'
     and rs.source_id = nii.source_id
    where p_channel = 'internal'
  ),
  note_base as (
    select
      section,
      conversation_key,
      case
        when conversation_key like 'group:%' or chat_group_id is not null then 'group'
        else 'direct'
      end as kind,
      note_id,
      author_id,
      created_at,
      preview,
      is_read
    from note_raw
    where nullif(trim(coalesce(conversation_key, '')), '') is not null
  ),
  note_agg as (
    select
      section,
      conversation_key,
      kind,
      count(*)::integer as note_count,
      count(*) filter (where not is_read)::integer as unread_count,
      max(created_at) as latest_message_at
    from note_base
    group by section, conversation_key, kind
  ),
  note_latest as (
    select distinct on (conversation_key)
      conversation_key,
      preview
    from note_base
    order by conversation_key, created_at desc, note_id desc
  ),
  enriched as (
    select
      na.section,
      na.conversation_key,
      na.kind,
      case
        when na.kind = 'group' then coalesce(cg.name, 'گروه')
        else coalesce(nullif(trim(other_profile.full_name), ''), 'کاربر')
      end as title,
      case
        when na.kind = 'group' then 'گروه داخلی'
        else nullif(trim(other_role.title), '')
      end as subtitle,
      case when na.kind = 'direct' then other_profile.avatar_url else null end as avatar_url,
      case when na.kind = 'direct' then other_role.title else null end as role_label,
      na.note_count,
      na.unread_count,
      na.latest_message_at,
      nl.preview as last_message_preview,
      case
        when na.kind = 'direct' then
          case
            when public.kalam_try_uuid(split_part(na.conversation_key, ':', 2)) = me.user_id
              then public.kalam_try_uuid(split_part(na.conversation_key, ':', 3))
            else public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
          end
        else null
      end as user_id,
      case when na.kind = 'group'
        then public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
        else null
      end as group_id
    from note_agg na
    join me on true
    left join note_latest nl
      on nl.conversation_key = na.conversation_key
    left join public.chat_groups cg
      on na.kind = 'group'
     and cg.id = public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
    left join public.profiles other_profile
      on na.kind = 'direct'
     and other_profile.id = (
       case
         when public.kalam_try_uuid(split_part(na.conversation_key, ':', 2)) = me.user_id
           then public.kalam_try_uuid(split_part(na.conversation_key, ':', 3))
         else public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
       end
     )
     and other_profile.org_id = me.org_id
    left join public.org_roles other_role
      on other_role.id = other_profile.role_id
     and other_role.org_id = me.org_id
  )
  select
    enriched.section,
    enriched.conversation_key,
    enriched.kind,
    enriched.title,
    enriched.subtitle,
    enriched.avatar_url,
    enriched.role_label,
    enriched.note_count,
    enriched.unread_count,
    enriched.latest_message_at,
    enriched.last_message_preview,
    enriched.user_id,
    enriched.group_id,
    null::uuid as bot_group_id,
    null::text as channel_type,
    null::text as status,
    null::text as counterparty_label,
    null::text as bot_chat_id
  from enriched
  where p_before_cursor is null or enriched.latest_message_at < p_before_cursor
  order by enriched.latest_message_at desc nulls last, enriched.title asc
  limit least(greatest(coalesce(p_limit, 80), 1), 100);
$$;


--
-- Name: get_communication_conversations_v2(text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_communication_conversations_v2(p_channel text DEFAULT 'internal'::text, p_before_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 80) RETURNS TABLE(section text, conversation_key text, kind text, title text, subtitle text, avatar_url text, role_label text, note_count integer, unread_count integer, latest_message_at timestamp with time zone, last_message_preview text, user_id uuid, group_id uuid, bot_group_id uuid, channel_type text, status text, counterparty_label text, bot_chat_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select auth.uid() as user_id, public.current_org_id() as org_id, p.role_id
    from public.profiles p
    where p.id = auth.uid()
      and p.org_id = public.current_org_id()
    limit 1
  ),
  internal_raw as (
    select distinct on (n.id)
      'notes'::text as section,
      conv.conversation_key,
      nullif(trim(coalesce(nii.payload->>'chat_group_id', n.metadata->>'chat_group_id')), '') as chat_group_id,
      n.id as message_id,
      n.author_id,
      n.created_at,
      nullif(trim(coalesce(nii.body, n.content, '')), '') as preview,
      (
        n.author_id = me.user_id
        or rs.read_at is not null
        or rs.dismissed_at is not null
        or (
          crc.read_through_at is not null
          and (
            n.created_at < crc.read_through_at
            or (
              n.created_at = crc.read_through_at
              and n.id::text <= coalesce(crc.read_through_id, n.id::text)
            )
          )
        )
      ) as is_read
    from me
    join public.notes n
      on n.org_id = me.org_id
    left join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'notes'
     and nii.source_type = 'note'
     and nii.source_id = n.id::text
    left join public.chat_groups cg
      on cg.org_id = me.org_id
     and cg.id = public.kalam_try_uuid(n.metadata->>'chat_group_id')
    left join lateral (
      select coalesce(
        nullif(trim(nii.conversation_key), ''),
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
        )
      ) as conversation_key
    ) conv on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'notes'
     and rs.source_type = 'note'
     and rs.source_id = n.id::text
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id
     and crc.user_id = me.user_id
     and crc.channel = 'internal'
     and crc.conversation_key = conv.conversation_key
    where p_channel = 'internal'
      and nullif(trim(coalesce(conv.conversation_key, '')), '') is not null
      and (
        (
          nii.id is not null
          and (
            nii.is_org_wide = true
            or me.user_id = any(coalesce(nii.target_user_ids, '{}'::uuid[]))
            or (me.role_id is not null and me.role_id = any(coalesce(nii.target_role_ids, '{}'::uuid[])))
          )
        )
        or n.author_id = me.user_id
        or me.user_id = any(coalesce(n.mention_user_ids, '{}'::uuid[]))
        or (me.role_id is not null and me.role_id = any(coalesce(n.mention_role_ids, '{}'::uuid[])))
        or (
          cg.id is not null
          and (
            me.user_id = any(coalesce(cg.user_ids, '{}'::uuid[]))
            or (me.role_id is not null and me.role_id = any(coalesce(cg.role_ids, '{}'::uuid[])))
          )
        )
      )
    order by n.id, coalesce(nii.last_event_at, nii.created_at, n.created_at) desc
  ),
  internal_base as (
    select
      section,
      conversation_key,
      case
        when conversation_key = 'system' then 'system'
        when conversation_key like 'group:%' or chat_group_id is not null then 'group'
        else 'direct'
      end as kind,
      message_id,
      author_id,
      created_at,
      preview,
      is_read
    from internal_raw
  ),
  internal_agg as (
    select
      section,
      conversation_key,
      kind,
      count(*)::integer as note_count,
      count(*) filter (where not is_read)::integer as unread_count,
      max(created_at) as latest_message_at
    from internal_base
    group by section, conversation_key, kind
  ),
  internal_latest as (
    select distinct on (conversation_key) conversation_key, preview
    from internal_base
    order by conversation_key, created_at desc, message_id desc
  ),
  internal_enriched as (
    select
      ia.section,
      ia.conversation_key,
      ia.kind,
      case
        when ia.kind = 'system' then 'پیام‌های سیستم'
        when ia.kind = 'group' then coalesce(cg.name, 'گروه')
        else coalesce(nullif(trim(other_profile.full_name), ''), 'کاربر')
      end as title,
      case
        when ia.kind = 'system' then 'اعلان‌ها و پیام‌های سیستمی'
        when ia.kind = 'group' then 'گروه داخلی'
        else nullif(trim(other_role.title), '')
      end as subtitle,
      case when ia.kind = 'direct' then other_profile.avatar_url else null end as avatar_url,
      case when ia.kind = 'direct' then other_role.title else null end as role_label,
      ia.note_count,
      ia.unread_count,
      ia.latest_message_at,
      il.preview as last_message_prefix,
      case
        when ia.kind = 'direct' then
          case
            when public.kalam_try_uuid(split_part(ia.conversation_key, ':', 2)) = me.user_id
              then public.kalam_try_uuid(split_part(ia.conversation_key, ':', 3))
            else public.kalam_try_uuid(split_part(ia.conversation_key, ':', 2))
          end
        else null
      end as user_id,
      case when ia.kind = 'group' then public.kalam_try_uuid(split_part(ia.conversation_key, ':', 2)) else null end as group_id,
      null::uuid as bot_group_id,
      null::text as channel_type,
      null::text as status,
      null::text as counterparty_label,
      null::text as bot_chat_id
    from internal_agg ia
    join me on true
    left join internal_latest il on il.conversation_key = ia.conversation_key
    left join public.chat_groups cg
      on ia.kind = 'group'
     and cg.org_id = me.org_id
     and cg.id = public.kalam_try_uuid(split_part(ia.conversation_key, ':', 2))
    left join public.profiles other_profile
      on ia.kind = 'direct'
     and other_profile.id = (
       case
         when public.kalam_try_uuid(split_part(ia.conversation_key, ':', 2)) = me.user_id
           then public.kalam_try_uuid(split_part(ia.conversation_key, ':', 3))
         else public.kalam_try_uuid(split_part(ia.conversation_key, ':', 2))
       end
     )
     and other_profile.org_id = me.org_id
    left join public.org_roles other_role
      on other_role.id = other_profile.role_id
     and other_role.org_id = me.org_id
  ),
  mine_agg as (
    select
      count(*)::integer as note_count,
      max(n.created_at) as latest_message_at
    from me
    join public.notes n
      on n.org_id = me.org_id
     and n.author_id = me.user_id
     and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
     and lower(trim(coalesce(n.metadata->>'saved_message', 'false'))) in ('true', '1', 'yes')
     and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
     and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
    where p_channel = 'internal'
  ),
  mine_latest as (
    select nullif(trim(n.content), '') as preview
    from me
    join public.notes n
      on n.org_id = me.org_id
     and n.author_id = me.user_id
     and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
     and lower(trim(coalesce(n.metadata->>'saved_message', 'false'))) in ('true', '1', 'yes')
     and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
     and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
    where p_channel = 'internal'
    order by n.created_at desc, n.id desc
    limit 1
  ),
  mine_enriched as (
    select
      'notes'::text as section,
      'mine'::text as conversation_key,
      'mine'::text as kind,
      'یادداشت‌های من'::text as title,
      null::text as subtitle,
      null::text as avatar_url,
      null::text as role_label,
      mine_agg.note_count,
      0::integer as unread_count,
      mine_agg.latest_message_at,
      mine_latest.preview as last_message_prefix,
      me.user_id,
      null::uuid as group_id,
      null::uuid as bot_group_id,
      null::text as channel_type,
      null::text as status,
      null::text as counterparty_label,
      null::text as bot_chat_id
    from me
    cross join mine_agg
    left join mine_latest on true
    where p_channel = 'internal'
      and mine_agg.note_count > 0
  ),
  bot_enriched as (
    select
      'bot_messages'::text as section,
      'bot:' || g.id::text as conversation_key,
      'bot'::text as kind,
      coalesce(nullif(trim(g.group_title), ''), coalesce(nullif(trim(c.full_name), ''), nullif(trim(s.full_name), ''), 'مخاطب')) as title,
      coalesce(nullif(trim(c.full_name), ''), nullif(trim(s.full_name), ''), null) as subtitle,
      null::text as avatar_url,
      null::text as role_label,
      coalesce(summary.message_count, 0)::integer as note_count,
      coalesce(unread.unread_count, 0)::integer as unread_count,
      summary.latest_message_at,
      summary.latest_message_preview as last_message_prefix,
      null::uuid as user_id,
      null::uuid as group_id,
      g.id as bot_group_id,
      g.channel_type,
      g.status,
      coalesce(nullif(trim(c.full_name), ''), nullif(trim(s.full_name), ''), null) as counterparty_label,
      g.bot_chat_id
    from me
    join public.counterparty_bot_groups g
      on g.org_id = me.org_id
     and public.kalam_can_access_bot_group(g.id, g.org_id)
    left join public.communication_bot_thread_summaries summary
      on summary.org_id = g.org_id
     and summary.bot_group_id = g.id
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id
     and crc.user_id = me.user_id
     and crc.channel = 'bot'
     and crc.conversation_key = 'bot:' || g.id::text
    left join lateral (
      select count(*)::integer as unread_count
      from public.counterparty_bot_messages m
      left join public.notification_read_states rs
        on rs.org_id = me.org_id
       and rs.user_id = me.user_id
       and rs.section = 'bot_messages'
       and rs.source_type = 'counterparty_bot_message'
       and rs.source_id = m.id::text
      where m.org_id = g.org_id
        and m.bot_group_id = g.id
        and m.direction = 'inbound'
        and rs.read_at is null
        and rs.dismissed_at is null
        and (
          crc.read_through_at is null
          or m.created_at > crc.read_through_at
          or (
            m.created_at = crc.read_through_at
            and m.id::text > coalesce(crc.read_through_id, '')
          )
        )
    ) unread on true
    left join public.customers c on c.id = g.customer_id and c.org_id = me.org_id
    left join public.suppliers s on s.id = g.supplier_id and s.org_id = me.org_id
    where p_channel = 'bot'
      and (
        p_before_cursor is null
        or summary.latest_message_at < p_before_cursor
      )
  )
  select
    e.section,
    e.conversation_key,
    e.kind,
    e.title,
    e.subtitle,
    e.avatar_url,
    e.role_label,
    e.note_count,
    e.unread_count,
    e.latest_message_at,
    e.last_message_prefix as last_message_preview,
    e.user_id,
    e.group_id,
    e.bot_group_id,
    e.channel_type,
    e.status,
    e.counterparty_label,
    e.bot_chat_id
  from (
    select * from mine_enriched
    union all
    select * from internal_enriched
    union all
    select * from bot_enriched
  ) e
  where p_before_cursor is null or e.latest_message_at < p_before_cursor
  order by e.latest_message_at desc nulls last, e.title asc
  limit least(greatest(coalesce(p_limit, 80), 1), 100);
$$;


--
-- Name: get_communication_timeline(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_communication_timeline(p_channel text, p_conversation_key text, p_before_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_key text := nullif(trim(coalesce(p_conversation_key, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_before_ts timestamptz := null;
  v_before_id text := null;
  v_bot_group_id uuid := null;
begin
  if v_user_id is null or v_org_id is null or v_key is null then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  select p.role_id into v_role_id
  from public.profiles p
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if nullif(trim(coalesce(p_before_cursor, '')), '') is not null then
    v_before_ts := nullif(split_part(p_before_cursor, '|', 1), '')::timestamptz;
    v_before_id := nullif(split_part(p_before_cursor, '|', 2), '');
  end if;

  if p_channel = 'internal' and v_key = 'mine' then
    return (
      with page_desc as (
        select
          n.id, n.module_id, n.record_id, n.content,
          n.author_id, n.author_name, n.mention_user_ids, n.mention_role_ids,
          n.created_at, n.reply_to, n.source_type, n.metadata, n.is_edited, n.edited_at
        from public.notes n
        where n.org_id = v_org_id
          and n.author_id = v_user_id
          and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
          and lower(trim(coalesce(n.metadata->>'saved_message', 'false'))) in ('true', '1', 'yes')
          and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
          and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
          and (
            v_before_ts is null
            or n.created_at < v_before_ts
            or (n.created_at = v_before_ts and n.id::text < coalesce(v_before_id, ''))
          )
        order by n.created_at desc, n.id desc
        limit v_limit
      ),
      page as (select * from page_desc order by created_at asc, id asc),
      earliest as (select created_at, id::text as id_text from page order by created_at asc, id asc limit 1)
      select jsonb_build_object(
        'items', coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at asc, page.id asc) from page), '[]'::jsonb),
        'unread_count', 0,
        'first_unread_id', null,
        'has_more_before', exists(
          select 1
          from public.notes n, earliest
          where n.org_id = v_org_id
            and n.author_id = v_user_id
            and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
            and lower(trim(coalesce(n.metadata->>'saved_message', 'false'))) in ('true', '1', 'yes')
            and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
            and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
            and (
              n.created_at < earliest.created_at
              or (n.created_at = earliest.created_at and n.id::text < earliest.id_text)
            )
        ),
        'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
        'read_model', 'cursor'
      )
    );
  end if;

  if p_channel = 'internal' and v_key = 'system' then
    return (
      with visible as (
        select
          n.id, n.module_id, n.record_id, n.content,
          n.author_id, n.author_name, n.mention_user_ids, n.mention_role_ids,
          n.created_at, n.reply_to, n.source_type, n.metadata, n.is_edited, n.edited_at,
          (n.author_id = v_user_id or rs.read_at is not null or rs.dismissed_at is not null) as is_read
        from public.notification_inbox_items nii
        join public.notes n on n.id::text = nii.source_id and n.org_id = nii.org_id
        left join public.notification_read_states rs
          on rs.org_id = v_org_id and rs.user_id = v_user_id
         and rs.section = 'notes' and rs.source_type = 'note' and rs.source_id = nii.source_id
        where nii.org_id = v_org_id
          and nii.section = 'notes'
          and nii.source_type = 'note'
          and (
            nii.conversation_key = 'system'
            or lower(trim(coalesce(nii.category, ''))) in ('system', 'assistant')
            or public.kalam_note_conversation_key(
              n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
              coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
            ) = 'system'
          )
          and (
            nii.is_org_wide = true
            or v_user_id = any(nii.target_user_ids)
            or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
          )
      ),
      page_desc as (
        select *
        from visible
        where v_before_ts is null
           or created_at < v_before_ts
           or (created_at = v_before_ts and id::text < coalesce(v_before_id, ''))
        order by created_at desc, id desc
        limit v_limit
      ),
      page as (select * from page_desc order by created_at asc, id asc),
      earliest as (select created_at, id::text as id_text from page order by created_at asc, id asc limit 1)
      select jsonb_build_object(
        'items', coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at asc, page.id asc) from page), '[]'::jsonb),
        'unread_count', (select count(*)::integer from visible where not is_read),
        'first_unread_id', (select id::text from page where not is_read order by created_at asc, id asc limit 1),
        'has_more_before', exists(
          select 1 from visible, earliest
          where visible.created_at < earliest.created_at
             or (visible.created_at = earliest.created_at and visible.id::text < earliest.id_text)
        ),
        'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
        'read_model', 'item'
      )
    );
  end if;

  if p_channel = 'internal' then
    return (
      with cursor_state as (
        select read_through_at, read_through_id
        from public.communication_read_cursors
        where org_id = v_org_id
          and user_id = v_user_id
          and channel = 'internal'
          and conversation_key = v_key
      ),
      page_desc as (
        select
          n.id, n.module_id, n.record_id, n.content,
          n.author_id, n.author_name, n.mention_user_ids, n.mention_role_ids,
          n.created_at, n.reply_to, n.source_type,
          coalesce(n.metadata, '{}'::jsonb) || jsonb_build_object(
            'read_receipts',
            coalesce((
              select jsonb_object_agg(
                reader.user_id::text,
                jsonb_build_object(
                  'user_id', reader.user_id::text,
                  'user_name', coalesce( nullif(trim(reader_profile.full_name), ''), 'کاربر'),
                  'read_at', reader.updated_at
                )
              )
              from public.communication_read_cursors reader
              left join public.profiles reader_profile on reader_profile.id = reader.user_id
              where reader.org_id = v_org_id
                and reader.channel = 'internal'
                and reader.conversation_key = v_key
                and (n.author_id is null or reader.user_id <> n.author_id)
                and reader.read_through_at is not null
                and (
                  n.created_at < reader.read_through_at
                  or (n.created_at = reader.read_through_at and n.id::text <= coalesce(reader.read_through_id, n.id::text))
                )
            ), '{}'::jsonb)
          ) as metadata,
          n.is_edited, n.edited_at,
          (
            n.author_id = v_user_id
            or rs.read_at is not null
            or rs.dismissed_at is not null
            or (
              crc.read_through_at is not null
              and (
                n.created_at < crc.read_through_at
                or (n.created_at = crc.read_through_at and n.id::text <= coalesce(crc.read_through_id, n.id::text))
              )
            )
          ) as is_read
        from public.notification_inbox_items nii
        join public.notes n on n.id::text = nii.source_id and n.org_id = nii.org_id
        left join public.notification_read_states rs
          on rs.org_id = v_org_id and rs.user_id = v_user_id
         and rs.section = 'notes' and rs.source_type = 'note' and rs.source_id = nii.source_id
        left join cursor_state crc on true
        where nii.org_id = v_org_id
          and nii.section = 'notes'
          and nii.source_type = 'note'
          and lower(trim(coalesce(nii.category, ''))) not in ('system', 'assistant')
          and coalesce(
            nii.conversation_key,
            nullif(trim(nii.payload->>'conversation_key'), ''),
            public.kalam_note_conversation_key(
              n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
              coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
            )
          ) = v_key
          and (
            nii.is_org_wide = true
            or v_user_id = any(nii.target_user_ids)
            or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
          )
          and (
            v_before_ts is null
            or n.created_at < v_before_ts
            or (n.created_at = v_before_ts and n.id::text < coalesce(v_before_id, ''))
          )
        order by n.created_at desc, n.id desc
        limit v_limit
      ),
      page as (select * from page_desc order by created_at asc, id asc),
      earliest as (select created_at, id::text as id_text from page order by created_at asc, id asc limit 1),
      unread_stats as (
        select count(*)::integer as unread_count
        from public.notification_inbox_items nii
        join public.notes n on n.id::text = nii.source_id and n.org_id = nii.org_id
        left join public.notification_read_states rs
          on rs.org_id = v_org_id and rs.user_id = v_user_id
         and rs.section = 'notes' and rs.source_type = 'note' and rs.source_id = nii.source_id
        left join cursor_state crc on true
        where nii.org_id = v_org_id
          and nii.section = 'notes'
          and nii.source_type = 'note'
          and lower(trim(coalesce(nii.category, ''))) not in ('system', 'assistant')
          and coalesce(
            nii.conversation_key,
            nullif(trim(nii.payload->>'conversation_key'), ''),
            public.kalam_note_conversation_key(
              n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
              coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
            )
          ) = v_key
          and (
            nii.is_org_wide = true
            or v_user_id = any(nii.target_user_ids)
            or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
          )
          and n.author_id <> v_user_id
          and rs.read_at is null
          and rs.dismissed_at is null
          and (
            crc.read_through_at is null
            or n.created_at > crc.read_through_at
            or (n.created_at = crc.read_through_at and n.id::text > coalesce(crc.read_through_id, ''))
          )
      )
      select jsonb_build_object(
        'items', coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at asc, page.id asc) from page), '[]'::jsonb),
        'unread_count', coalesce((select unread_count from unread_stats), 0),
        'first_unread_id', (select id::text from page where not is_read order by created_at asc, id asc limit 1),
        'has_more_before', exists(
          select 1
          from public.notification_inbox_items nii
          join public.notes n on n.id::text = nii.source_id and n.org_id = nii.org_id
          join earliest on true
          where nii.org_id = v_org_id
            and nii.section = 'notes'
            and nii.source_type = 'note'
            and lower(trim(coalesce(nii.category, ''))) not in ('system', 'assistant')
            and coalesce(
              nii.conversation_key,
              nullif(trim(nii.payload->>'conversation_key'), ''),
              public.kalam_note_conversation_key(
                n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
                coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
              )
            ) = v_key
            and (
              nii.is_org_wide = true
              or v_user_id = any(nii.target_user_ids)
              or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
            )
            and (
              n.created_at < earliest.created_at
              or (n.created_at = earliest.created_at and n.id::text < earliest.id_text)
            )
        ),
        'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
        'read_model', 'cursor'
      )
    );
  end if;

  if p_channel = 'bot' then
    v_bot_group_id := public.kalam_try_uuid(replace(v_key, 'bot:', ''));
    if v_bot_group_id is null or not public.kalam_can_access_bot_group(v_bot_group_id, v_org_id) then
      return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
    end if;

    return (
      with cursor_state as (
        select read_through_at, read_through_id
        from public.communication_read_cursors
        where org_id = v_org_id
          and user_id = v_user_id
          and channel = 'bot'
          and conversation_key = v_key
      ),
      page_desc as (
        select
          m.id, m.bot_group_id, m.direction, m.message_type, m.chat_id,
          m.provider_message_id, m.content_text, m.file_url, m.file_name, m.mime_type,
          
          coalesce(m.payload, '{}'::jsonb) || jsonb_build_object(
            'read_receipts',
            coalesce((
              select jsonb_object_agg(
                reader.user_id::text,
                jsonb_build_object(
                  'user_id', reader.user_id::text,
                  'user_name', coalesce(nullif(trim(reader_profile.full_name), ''), 'کاربر'),
                  'read_at', reader.updated_at
                )
              )
              from public.communication_read_cursors reader
              left join public.profiles reader_profile
                on reader_profile.id = reader.user_id
               and reader_profile.org_id = reader.org_id
              where reader.org_id = v_org_id
                and reader.channel = 'bot'
                and reader.conversation_key = v_key
                and (m.created_by is null or reader.user_id <> m.created_by)
                and reader.read_through_at is not null
                and (
                  m.created_at < reader.read_through_at
                  or (
                    m.created_at = reader.read_through_at
                    and m.id::text <= coalesce(reader.read_through_id, m.id::text)
                  )
                )
            ), '{}'::jsonb)
          ) as payload,
          m.created_by, m.created_at,
          (
            m.direction <> 'inbound'
            or rs.read_at is not null
            or rs.dismissed_at is not null
            or (
              crc.read_through_at is not null
              and (
                m.created_at < crc.read_through_at
                or (m.created_at = crc.read_through_at and m.id::text <= coalesce(crc.read_through_id, m.id::text))
              )
            )
          ) as is_read
        from public.counterparty_bot_messages m
        left join public.notification_read_states rs
          on rs.org_id = v_org_id and rs.user_id = v_user_id
         and rs.section = 'bot_messages' and rs.source_type = 'counterparty_bot_message' and rs.source_id = m.id::text
        left join cursor_state crc on true
        where m.org_id = v_org_id
          and m.bot_group_id = v_bot_group_id
          and (
            v_before_ts is null
            or m.created_at < v_before_ts
            or (m.created_at = v_before_ts and m.id::text < coalesce(v_before_id, ''))
          )
        order by m.created_at desc, m.id desc
        limit v_limit
      ),
      page as (select * from page_desc order by created_at asc, id asc),
      earliest as (select created_at, id::text as id_text from page order by created_at asc, id asc limit 1),
      unread_stats as (
        select count(*)::integer as unread_count
        from public.counterparty_bot_messages m
        left join public.notification_read_states rs
          on rs.org_id = v_org_id and rs.user_id = v_user_id
         and rs.section = 'bot_messages' and rs.source_type = 'counterparty_bot_message' and rs.source_id = m.id::text
        left join cursor_state crc on true
        where m.org_id = v_org_id
          and m.bot_group_id = v_bot_group_id
          and m.direction = 'inbound'
          and rs.read_at is null
          and rs.dismissed_at is null
          and (
            crc.read_through_at is null
            or m.created_at > crc.read_through_at
            or (m.created_at = crc.read_through_at and m.id::text > coalesce(crc.read_through_id, ''))
          )
      )
      select jsonb_build_object(
        'items', coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at asc, page.id asc) from page), '[]'::jsonb),
        'unread_count', coalesce((select unread_count from unread_stats), 0),
        'first_unread_id', (select id::text from page where not is_read order by created_at asc, id asc limit 1),
        'has_more_before', exists(
          select 1
          from public.counterparty_bot_messages m, earliest
          where m.org_id = v_org_id
            and m.bot_group_id = v_bot_group_id
            and (
              m.created_at < earliest.created_at
              or (m.created_at = earliest.created_at and m.id::text < earliest.id_text)
            )
        ),
        'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
        'read_model', 'cursor'
      )
    );
  end if;

  return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
end;
$$;


--
-- Name: get_current_org_saas_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_org_saas_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare org_id_val uuid := public.current_org_id(); rec record; next_invoice record; is_saas_admin_org boolean := false;
begin
  if auth.uid() is null or org_id_val is null then return null; end if;
  select status, is_demo, is_readonly, billing_readonly, trial_ends_at, plan_code, slug into rec from public.saas_org_settings where org_id = org_id_val limit 1;
  if not found then return null; end if;
  is_saas_admin_org := public.org_is_saas_admin(org_id_val);
  if not is_saas_admin_org then
    select due_at, grace_ends_at, total_irt, status into next_invoice from public.saas_subscription_invoices where org_id = org_id_val and status in ('issued', 'overdue') order by due_at asc limit 1;
  end if;
  return jsonb_build_object(
    'status', rec.status, 'is_demo', rec.is_demo,
    'is_readonly', rec.is_readonly or (not is_saas_admin_org and (rec.billing_readonly or (rec.trial_ends_at is not null and rec.trial_ends_at < now()))),
    'billing_readonly', case when is_saas_admin_org then false else rec.billing_readonly end,
    'trial_ends_at', rec.trial_ends_at, 'plan_code', rec.plan_code, 'slug', rec.slug,
    'next_billing_invoice', case when next_invoice.due_at is null then null else jsonb_build_object('due_at', next_invoice.due_at, 'grace_ends_at', next_invoice.grace_ends_at, 'total_irt', next_invoice.total_irt, 'status', next_invoice.status) end
  );
end; $$;


--
-- Name: get_current_organization_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_organization_context() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('org_id',m.org_id,'org_name',public.organization_display_name(m.org_id),
    'role_id',m.role_id,'role',m.software_role,'is_active',m.is_active,
    'role_name',r.title,'permissions',coalesce(r.permissions,'{}'::jsonb),'settings',m.settings)
  from public.user_organization_memberships m
  left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
  where m.user_id=auth.uid() and m.org_id=public.current_org_id() and m.is_active;
$$;


--
-- Name: get_current_saas_account_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_saas_account_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org_id uuid := public.current_org_id();
begin
  if auth.uid() is null or v_org_id is null then raise exception 'organization_access_denied'; end if;
  return public.saas_account_overview_payload(v_org_id);
end; $$;


--
-- Name: get_current_saas_checkout_discounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_saas_checkout_discounts() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'users', (select coalesce(jsonb_agg(jsonb_build_object('minimum',minimum_quantity,'percent',discount_percent) order by minimum_quantity),'[]'::jsonb) from public.saas_checkout_discount_rules where kind='users'),
    'terms', (select coalesce(jsonb_agg(jsonb_build_object('months',minimum_quantity,'percent',discount_percent) order by minimum_quantity),'[]'::jsonb) from public.saas_checkout_discount_rules where kind='term')
  ) where auth.uid() is not null and public.current_org_id() is not null;
$$;


--
-- Name: get_current_saas_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_saas_context() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  current_org uuid := public.current_org_id();
begin
  if auth.uid() is null or current_org is null then
    return null;
  end if;

  return public.resolve_saas_org_context(current_org, null, null);
end
$$;


--
-- Name: get_current_saas_pending_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_saas_pending_orders() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(order_row) order by order_row.created_at desc), '[]'::jsonb)
  from (select * from public.saas_orders where org_id = public.current_org_id() and status = 'pending_payment' order by created_at desc limit 20) order_row;
$$;


--
-- Name: get_current_saas_storage_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_saas_storage_usage() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org_id uuid:=public.current_org_id(); v_bytes bigint:=0; v_files bigint:=0;
begin
  if v_org_id is null then return jsonb_build_object('bytes',0,'files',0); end if;
  select coalesce(sum(greatest(coalesce(file_size_bytes,0),0)),0),count(*) into v_bytes,v_files
  from public.file_assets where org_id=v_org_id;
  return jsonb_build_object('bytes',v_bytes,'files',v_files,'gb',round(v_bytes/1073741824.0,3));
end;
$$;


--
-- Name: get_current_saas_store_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_saas_store_catalog() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(item order by (item ->> 'sort_order')::int, item ->> 'title'), '[]'::jsonb)
  from (
    select jsonb_build_object('code', code, 'title', title, 'description', description, 'item_kind', item_kind,
      'entitlement_code', entitlement_code, 'quantity', quantity, 'price_irt', price_irt, 'billing_cycle', billing_cycle,
      'sort_order', sort_order, 'metadata', metadata) as item
    from public.saas_catalog_items where is_active and is_public and price_irt > 0
    union all
    select jsonb_build_object('code', 'plan:' || code, 'title', title, 'description', short_description, 'item_kind', 'plan',
      'entitlement_code', code, 'quantity', 1, 'price_irt', coalesce(price_per_user_monthly, price_monthly),
      'billing_cycle', 'monthly', 'sort_order', sort_order,
      'metadata', jsonb_build_object('pricing_model', 'per_user', 'minimum_users', coalesce(minimum_users, 3), 'storage_gb', storage_gb))
    from public.saas_plans where is_active and is_public and coalesce(price_per_user_monthly, price_monthly) > 0
  ) items;
$$;


--
-- Name: get_current_user_organization_accesses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_user_organization_accesses() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'org_id',m.org_id,'org_name',public.organization_display_name(m.org_id),
    'role_name',coalesce(r.title,case m.software_role when 'super_admin' then 'مدیر ارشد'
      when 'admin' then 'مدیر سیستم' when 'manager' then 'مدیر' when 'editor' then 'ویرایشگر' else 'مشاهده‌گر' end),
    'is_owner',m.is_owner,'slug',s.slug,'resolved_host',public.organization_access_host(m.org_id),'is_saas_org',s.org_id is not null
  ) order by m.is_owner desc,public.organization_display_name(m.org_id)),'[]'::jsonb)
  from public.user_organization_memberships m join public.organizations o on o.id=m.org_id and o.is_active
  left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
  left join public.saas_org_settings s on s.org_id=m.org_id
  where m.user_id=auth.uid() and m.is_active;
$$;


--
-- Name: get_customer_club_credit_scope(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_club_credit_scope(p_org_id uuid, p_entity_type text, p_entity_id uuid) RETURNS TABLE(entity_type text, entity_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with recursive nodes as (
    select 'customer'::text as entity_type, c.id as entity_id, c.linked_supplier_id, c.linked_employee_id, null::uuid as linked_customer_id
      from public.customers c where c.org_id = p_org_id
    union all
    select 'supplier', s.id, null::uuid, s.linked_employee_id, s.linked_customer_id
      from public.suppliers s where s.org_id = p_org_id
    union all
    select 'employee', e.id, e.linked_supplier_id, null::uuid, e.linked_customer_id
      from public.employees e where e.org_id = p_org_id
  ), edges as (
    select entity_type as from_type, entity_id as from_id, 'supplier'::text as to_type, linked_supplier_id as to_id from nodes where linked_supplier_id is not null
    union all select 'supplier', linked_supplier_id, entity_type, entity_id from nodes where linked_supplier_id is not null
    union all select entity_type, entity_id, 'employee', linked_employee_id from nodes where linked_employee_id is not null
    union all select 'employee', linked_employee_id, entity_type, entity_id from nodes where linked_employee_id is not null
    union all select entity_type, entity_id, 'customer', linked_customer_id from nodes where linked_customer_id is not null
    union all select 'customer', linked_customer_id, entity_type, entity_id from nodes where linked_customer_id is not null
  ), walk(entity_type, entity_id) as (
    select lower(trim(p_entity_type)), p_entity_id
    union
    select e.to_type, e.to_id from edges e join walk w on w.entity_type = e.from_type and w.entity_id = e.from_id
  )
  select w.entity_type, w.entity_id
  from walk w join nodes n on n.entity_type = w.entity_type and n.entity_id = w.entity_id;
$$;


--
-- Name: get_customer_club_financial_history(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_club_financial_history(p_entity_type text, p_entity_id uuid) RETURNS TABLE(key text, row_type text, source_label text, status text, date date, club_credit_amount numeric, invoice_label text, description text, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with scope as (
    select * from public.get_customer_club_credit_scope(public.current_org_id(), lower(trim(p_entity_type)), p_entity_id)
  )
  select 'legacy:' || l.id::text, 'club_credit', 'باشگاه مشتریان', 'ثبت شده', l.effective_date,
    case when l.entry_type = 'debit' then -l.amount else l.amount end, '-', coalesce(l.description, 'گردش اعتبار باشگاه مشتریان'), l.created_at
  from public.customer_loyalty_ledger l join scope s on s.entity_type = 'customer' and s.entity_id = l.customer_id
  where l.org_id = public.current_org_id()
  union all
  select 'entity:' || e.id::text, 'club_credit', 'باشگاه مشتریان', 'ثبت شده', e.effective_date,
    case when e.entry_type = 'debit' then -e.amount else e.amount end, '-', coalesce(e.description, 'گردش اعتبار باشگاه مشتریان'), e.created_at
  from public.customer_club_entity_credits e join scope s on s.entity_type = e.recipient_module_id and s.entity_id = e.recipient_record_id
  where e.org_id = public.current_org_id();
$$;


--
-- Name: get_customer_operational_financial_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_operational_financial_overview(p_customer_id uuid) RETURNS TABLE(key text, row_type text, source_label text, source_module_id text, source_record_id uuid, payment_type text, status text, cheque_status text, row_date date, debit numeric, credit numeric, balance numeric, invoice_label text, bank_label text, description text, created_at timestamp with time zone)
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  with customer_row as (
    select *
    from public.customers
    where id = p_customer_id
      and org_id = public.current_org_id()
  ),
  opening as (
    select
      'legacy_opening_' || c.id::text as key,
      'opening'::text as row_type,
      'اطلاعات سیستم قبلی'::text as source_label,
      'customers'::text as source_module_id,
      c.id as source_record_id,
      ''::text as payment_type,
      'opening'::text as status,
      ''::text as cheque_status,
      coalesce(c.previous_system_first_purchase_date, c.created_at::date) as row_date,
      coalesce(c.previous_system_invoice_total, 0) as debit,
      coalesce(c.previous_system_paid_total, 0) as credit,
      coalesce(c.full_name, c.business_name, c.system_code, 'مشتری') as invoice_label,
      '-'::text as bank_label,
      ('مانده سیستم قبلی: ' || coalesce(c.previous_system_balance_total, 0)::text)::text as description,
      c.created_at
    from customer_row c
    where coalesce(c.previous_system_invoice_total, 0) <> 0
       or coalesce(c.previous_system_paid_total, 0) <> 0
       or coalesce(c.previous_system_balance_total, 0) <> 0
  ),
  invoices_rows as (
    select
      'invoice_' || i.id::text as key,
      'invoice'::text as row_type,
      'صدور فاکتور فروش'::text as source_label,
      'invoices'::text as source_module_id,
      i.id as source_record_id,
      ''::text as payment_type,
      coalesce(i.status, '')::text as status,
      ''::text as cheque_status,
      coalesce(i.invoice_date, i.created_at::date) as row_date,
      coalesce(i.total_invoice_amount, 0) as debit,
      0::numeric as credit,
      coalesce(i.name, i.system_code, 'فاکتور فروش') as invoice_label,
      '-'::text as bank_label,
      ('فاکتور فروش | مانده: ' || coalesce(i.remaining_balance, 0)::text)::text as description,
      i.created_at
    from public.invoices i
    where i.org_id = public.current_org_id()
      and i.customer_id = p_customer_id
      and public.is_customer_purchase_status(i.status)
  ),
  invoice_payment_rows as (
    select
      'invoice_payment_' || i.id::text || '_' || p.ordinality::text as key,
      'receipt'::text as row_type,
      'دریافت فاکتور فروش'::text as source_label,
      'invoices'::text as source_module_id,
      i.id as source_record_id,
      lower(trim(coalesce(p.value->>'payment_type', '')))::text as payment_type,
      lower(trim(coalesce(p.value->>'status', '')))::text as status,
      coalesce(p.value->>'cheque_status', '')::text as cheque_status,
      coalesce(nullif(p.value->>'date', '')::date, coalesce(i.invoice_date, i.created_at::date)) as row_date,
      0::numeric as debit,
      case
        when lower(trim(coalesce(p.value->>'cheque_status', ''))) not in ('bounced', 'returned')
        then abs(coalesce(nullif(p.value->>'amount', '')::numeric, 0))
        else 0
      end as credit,
      coalesce(i.name, i.system_code, 'فاکتور فروش') as invoice_label,
      '-'::text as bank_label,
      coalesce(p.value->>'description', '')::text as description,
      i.created_at
    from public.invoices i
    cross join lateral jsonb_array_elements(coalesce(i.payments, '[]'::jsonb)) with ordinality p(value, ordinality)
    where i.org_id = public.current_org_id()
      and i.customer_id = p_customer_id
      and public.is_customer_purchase_status(i.status)
      and not (p.value ? '_cash_bank_operation_id' and nullif(p.value->>'_cash_bank_operation_id', '') is not null)
      and (
        not (p.value ? 'status')
        or lower(trim(coalesce(p.value->>'status', ''))) = ''
        or lower(trim(coalesce(p.value->>'status', ''))) in ('received', 'paid', 'approved', 'cleared')
      )
      and abs(coalesce(nullif(p.value->>'amount', '')::numeric, 0)) > 0
  ),
  cash_rows as (
    select
      'cash_' || op.id::text as key,
      case when op.operation_type = 'payment' then 'payment' else 'receipt' end::text as row_type,
      'ثبت نقد و بانک'::text as source_label,
      'cash_bank_operations'::text as source_module_id,
      op.id as source_record_id,
      coalesce(op.payment_type, '')::text as payment_type,
      coalesce(op.status, '')::text as status,
      coalesce(ch.status, '')::text as cheque_status,
      coalesce(op.operation_date, op.created_at::date) as row_date,
      case when op.operation_type = 'payment' then abs(coalesce(op.amount, 0)) else 0 end as debit,
      case
        when op.operation_type <> 'payment'
          and lower(trim(coalesce(ch.status, ''))) not in ('bounced', 'returned')
        then abs(coalesce(op.amount, 0))
        else 0
      end as credit,
      '-'::text as invoice_label,
      '-'::text as bank_label,
      coalesce(op.description, '')::text as description,
      op.created_at
    from public.cash_bank_operations op
    left join public.cheques ch
      on ch.id = op.cheque_id
     and ch.org_id = op.org_id
    where op.org_id = public.current_org_id()
      and op.customer_id = p_customer_id
      and lower(trim(coalesce(op.operation_type, ''))) <> 'transfer'
      and lower(trim(coalesce(op.status, ''))) in ('received', 'approved', 'paid', 'settled', 'cleared')
  ),
  all_rows as (
    select * from opening
    union all select * from invoices_rows
    union all select * from invoice_payment_rows
    union all select * from cash_rows
  ),
  ordered as (
    select
      all_rows.*,
      sum(debit - credit) over (order by row_date nulls first, created_at nulls first, key) as running_balance
    from all_rows
  )
  select
    ordered.key,
    ordered.row_type,
    ordered.source_label,
    ordered.source_module_id,
    ordered.source_record_id,
    ordered.payment_type,
    ordered.status,
    ordered.cheque_status,
    ordered.row_date,
    ordered.debit,
    ordered.credit,
    ordered.running_balance as balance,
    ordered.invoice_label,
    ordered.bank_label,
    ordered.description,
    ordered.created_at
  from ordered
  order by row_date nulls first, created_at nulls first, key;
$$;


--
-- Name: get_dashboard_snapshot_v1(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_snapshot_v1(p_recent_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with current_profile as (
    select id, role_id, org_id
    from public.profiles
    where id = auth.uid()
      and org_id = public.current_org_id()
    limit 1
  ),
  active_tasks as (
    select count(*) as count_all
    from public.tasks t
    cross join current_profile cp
    where t.org_id = public.current_org_id()
      and coalesce(t.status, '') not in ('done', 'completed', 'confirmed', 'final', 'settled')
      and (
        t.assignee_id = cp.id
        or (cp.role_id is not null and t.assignee_role_id = cp.role_id)
      )
  ),
  overdue_tasks as (
    select count(*) as count_all
    from public.tasks t
    cross join current_profile cp
    where t.org_id = public.current_org_id()
      and t.due_date is not null
      and t.due_date::date < now()::date
      and coalesce(t.status, '') not in ('done', 'completed', 'confirmed', 'final', 'settled')
      and (
        t.assignee_id = cp.id
        or (cp.role_id is not null and t.assignee_role_id = cp.role_id)
      )
  ),
  process_runs_recent as (
    select jsonb_agg(
      jsonb_build_object(
        'id', pr.id,
        'module_id', pr.module_id,
        'record_id', pr.record_id,
        'process_name', pr.process_name,
        'status', pr.status,
        'updated_at', pr.updated_at
      )
      order by pr.updated_at desc nulls last
    ) as rows
    from (
      select *
      from public.process_runs
      where org_id = public.current_org_id()
      order by updated_at desc nulls last
      limit greatest(1, least(coalesce(p_recent_limit, 12), 30))
    ) pr
  )
  select jsonb_build_object(
    'metrics', jsonb_build_object(
      'active_task_count', coalesce((select count_all from active_tasks), 0),
      'overdue_task_count', coalesce((select count_all from overdue_tasks), 0),
      'active_process_run_count', (
        select count(*)
        from public.process_runs
        where org_id = public.current_org_id()
          and coalesce(status, '') not in ('done', 'completed', 'canceled', 'cancelled')
      )
    ),
    'recent_process_runs', coalesce((select rows from process_runs_recent), '[]'::jsonb)
  );
$$;


--
-- Name: get_effective_demo_limit(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_demo_limit(p_mobile text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  normalized_mobile text := public.normalize_demo_mobile(p_mobile);
  override_limit integer;
  global_limit integer;
  global_settings jsonb;
begin
  select max_demo_count
    into override_limit
  from public.saas_demo_mobile_overrides
  where mobile = normalized_mobile
    and is_active = true
  limit 1;

  if override_limit is not null then
    return greatest(override_limit, 0);
  end if;

  global_settings := public.get_saas_global_settings();
  global_limit := nullif(global_settings #>> '{demo_policy,default_max_demo_count}', '')::integer;

  return greatest(coalesce(global_limit, 2), 0);
end
$$;


--
-- Name: get_expired_org_stories_for_media_cleanup(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_expired_org_stories_for_media_cleanup(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, org_id uuid, slides jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 200));
begin
  if auth.role() <> 'service_role' then
    raise exception 'دسترسی مجاز نیست' using errcode = 'P0001';
  end if;

  perform public.deactivate_expired_org_stories();

  return query
  select s.id, s.org_id, s.slides
  from public.org_stories s
  where s.delete_media_on_expire = true
    and s.media_cleaned_at is null
    and s.expires_at is not null
    and s.expires_at <= now()
  order by s.expires_at asc
  limit v_limit;
end;
$$;


--
-- Name: get_internal_communication_conversations_v3(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_internal_communication_conversations_v3(p_before_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 80) RETURNS TABLE(section text, conversation_key text, kind text, title text, subtitle text, avatar_url text, role_label text, note_count integer, unread_count integer, latest_message_at timestamp with time zone, last_message_preview text, user_id uuid, group_id uuid, bot_group_id uuid, channel_type text, status text, counterparty_label text, bot_chat_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select profile.id as user_id, profile.org_id, profile.role_id
    from public.profiles profile
    where profile.id = auth.uid()
      and profile.org_id = public.current_org_id()
    limit 1
  ), candidate as materialized (
    select distinct on (note.id, resolved.conversation_key)
      note.id as note_id,
      note.author_id,
      note.created_at,
      nullif(trim(coalesce(inbox.body, note.content, '')), '') as preview,
      resolved.conversation_key,
      resolved.peer_id
    from me
    join public.notification_inbox_items inbox
      on inbox.org_id = me.org_id
     and inbox.section = 'notes'
     and inbox.source_type = 'note'
    join public.notes note
      on note.id::text = inbox.source_id
     and note.org_id = inbox.org_id
    cross join lateral public.kalam_internal_message_conversation_rows_v4(
      note.org_id,
      note.id,
      note.author_id,
      coalesce(note.mention_user_ids, '{}'::uuid[]),
      coalesce(note.mention_role_ids, '{}'::uuid[]),
      note.source_type,
      coalesce(note.metadata, '{}'::jsonb),
      note.reply_to,
      me.user_id,
      me.role_id,
      inbox.category
    ) resolved
    where public.kalam_can_access_internal_message_v2(
      inbox.is_org_wide,
      inbox.target_user_ids,
      inbox.target_role_ids,
      note.author_id,
      note.mention_user_ids,
      note.mention_role_ids,
      note.source_type,
      note.metadata,
      inbox.category,
      me.user_id,
      me.role_id
    )
    order by note.id, resolved.conversation_key, inbox.created_at desc, inbox.id desc
  ), visible as materialized (
    select candidate.*,
      (
        candidate.author_id = me.user_id
        or read_state.read_at is not null
        or read_state.dismissed_at is not null
        or (
          cursor_state.read_through_at is not null
          and (
            candidate.created_at < cursor_state.read_through_at
            or (
              candidate.created_at = cursor_state.read_through_at
              and candidate.note_id::text <= coalesce(cursor_state.read_through_id, candidate.note_id::text)
            )
          )
        )
      ) as is_read
    from candidate
    join me on true
    left join public.notification_read_states read_state
      on read_state.org_id = me.org_id
     and read_state.user_id = me.user_id
     and read_state.section = 'notes'
     and read_state.source_type = 'note'
     and read_state.source_id = candidate.note_id::text
    left join public.communication_read_cursors cursor_state
      on cursor_state.org_id = me.org_id
     and cursor_state.user_id = me.user_id
     and cursor_state.channel = 'internal'
     and cursor_state.conversation_key = candidate.conversation_key
    where nullif(trim(coalesce(candidate.conversation_key, '')), '') is not null
      and (
        candidate.conversation_key not like 'direct:%'
        or candidate.conversation_key like 'direct:' || me.user_id::text || ':%'
        or candidate.conversation_key like 'direct:%:' || me.user_id::text
      )
  ), summary as (
    select
      conversation_key,
      count(*)::integer as note_count,
      count(*) filter (where not is_read)::integer as unread_count,
      max(created_at) as latest_message_at
    from visible
    group by conversation_key
  ), latest as (
    select distinct on (conversation_key) conversation_key, preview
    from visible
    order by conversation_key, created_at desc, note_id desc
  ), enriched as (
    select
      summary.conversation_key,
      case
        when summary.conversation_key like 'agent:%' then 'agent'
        when summary.conversation_key = 'system' then 'system'
        when summary.conversation_key = 'mine' then 'mine'
        when summary.conversation_key like 'group:%' then 'group'
        else 'direct'
      end as kind,
      case
        when summary.conversation_key like 'agent:%'
          then split_part(summary.conversation_key, ':', 2)
        else null
      end as resolved_agent_key,
      summary.note_count,
      summary.unread_count,
      summary.latest_message_at,
      latest.preview,
      case
        when summary.conversation_key like 'direct:%' then
          case
            when public.kalam_try_uuid(split_part(summary.conversation_key, ':', 2)) = me.user_id
              then public.kalam_try_uuid(split_part(summary.conversation_key, ':', 3))
            else public.kalam_try_uuid(split_part(summary.conversation_key, ':', 2))
          end
        else null::uuid
      end as resolved_user_id,
      case
        when summary.conversation_key like 'group:%'
          then public.kalam_try_uuid(split_part(summary.conversation_key, ':', 2))
        else null::uuid
      end as resolved_group_id
    from summary
    join me on true
    left join latest on latest.conversation_key = summary.conversation_key
  )
  select
    'notes'::text,
    enriched.conversation_key,
    enriched.kind,
    case
      when enriched.kind = 'agent' then public.kalam_agent_label_fa_v1(enriched.resolved_agent_key)
      when enriched.kind = 'system' then 'پیام‌های سیستم'
      when enriched.kind = 'mine' then 'یادداشت‌های من'
      when enriched.kind = 'group' then coalesce(nullif(trim(chat_group.name), ''), 'گروه داخلی')
      else coalesce(nullif(trim(other_profile.full_name), ''), 'کاربر')
    end,
    case
      when enriched.kind = 'agent' then public.kalam_agent_subtitle_fa_v1(enriched.resolved_agent_key)
      when enriched.kind = 'system' then 'اعلان‌ها و پیام‌های سیستمی'
      when enriched.kind = 'mine' then 'یادداشت‌های شخصی'
      when enriched.kind = 'group' then 'گروه داخلی'
      else nullif(trim(other_role.title), '')
    end,
    case when enriched.kind = 'direct' then other_profile.avatar_url else null end,
    case when enriched.kind = 'direct' then other_role.title else null end,
    enriched.note_count,
    enriched.unread_count,
    enriched.latest_message_at,
    enriched.preview,
    case when enriched.kind = 'direct' then enriched.resolved_user_id else null::uuid end,
    case when enriched.kind = 'group' then enriched.resolved_group_id else null::uuid end,
    null::uuid,
    null::text,
    null::text,
    case when enriched.kind = 'agent' then enriched.resolved_agent_key else null::text end,
    null::text
  from enriched
  join me on true
  left join public.chat_groups chat_group
    on enriched.kind = 'group'
   and chat_group.id = enriched.resolved_group_id
   and chat_group.org_id = me.org_id
  left join public.profiles other_profile
    on enriched.kind = 'direct'
   and other_profile.id = enriched.resolved_user_id
   and other_profile.org_id = me.org_id
  left join public.org_roles other_role
    on other_role.id = other_profile.role_id
   and other_role.org_id = me.org_id
  where p_before_cursor is null or enriched.latest_message_at < p_before_cursor
  order by enriched.latest_message_at desc nulls last, 4 asc
  limit least(greatest(coalesce(p_limit, 80), 1), 100);
$$;


--
-- Name: get_internal_communication_timeline_v3(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_internal_communication_timeline_v3(p_conversation_key text, p_limit integer DEFAULT 40, p_before_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_key text := nullif(trim(coalesce(p_conversation_key, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 40), 1), 50);
  v_before_ts timestamptz := null;
  v_before_id text := null;
begin
  if v_user_id is null or v_org_id is null or v_key is null then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  select profile.role_id into v_role_id
  from public.profiles profile
  where profile.id = v_user_id and profile.org_id = v_org_id
  limit 1;

  if not found then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  if v_key like 'direct:%'
    and v_key not like 'direct:' || v_user_id::text || ':%'
    and v_key not like 'direct:%:' || v_user_id::text then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  if nullif(trim(coalesce(p_before_cursor, '')), '') is not null then
    v_before_ts := nullif(split_part(p_before_cursor, '|', 1), '')::timestamptz;
    v_before_id := nullif(split_part(p_before_cursor, '|', 2), '');
  end if;

  return (
    with eligible_inbox as materialized (
      select inbox.*
      from public.notification_inbox_items inbox
      join public.notes note
        on note.id::text = inbox.source_id
       and note.org_id = inbox.org_id
      where inbox.org_id = v_org_id
        and inbox.section = 'notes'
        and inbox.source_type = 'note'
        and public.kalam_can_access_internal_message_v2(
          inbox.is_org_wide,
          inbox.target_user_ids,
          inbox.target_role_ids,
          note.author_id,
          note.mention_user_ids,
          note.mention_role_ids,
          note.source_type,
          note.metadata,
          inbox.category,
          v_user_id,
          v_role_id
        )
    ), visible as materialized (
      select distinct on (note.id)
        note.id, note.module_id, note.record_id, note.content, note.author_id, note.author_name,
        note.mention_user_ids, note.mention_role_ids, note.created_at, note.reply_to, note.source_type,
        note.metadata, note.is_edited, note.edited_at,
        (
          note.author_id = v_user_id
          or read_state.read_at is not null
          or read_state.dismissed_at is not null
          or (
            cursor_state.read_through_at is not null and (
              note.created_at < cursor_state.read_through_at
              or (
                note.created_at = cursor_state.read_through_at
                and note.id::text <= coalesce(cursor_state.read_through_id, note.id::text)
              )
            )
          )
        ) as is_read
      from eligible_inbox inbox
      join public.notes note
        on note.id::text = inbox.source_id
       and note.org_id = inbox.org_id
      left join public.notification_read_states read_state
        on read_state.org_id = v_org_id
       and read_state.user_id = v_user_id
       and read_state.section = 'notes'
       and read_state.source_type = 'note'
       and read_state.source_id = inbox.source_id
      left join public.communication_read_cursors cursor_state
        on cursor_state.org_id = v_org_id
       and cursor_state.user_id = v_user_id
       and cursor_state.channel = 'internal'
       and cursor_state.conversation_key = v_key
      where public.kalam_internal_message_matches_conversation_v4(
        note.org_id,
        note.id,
        note.author_id,
        coalesce(note.mention_user_ids, '{}'::uuid[]),
        coalesce(note.mention_role_ids, '{}'::uuid[]),
        note.source_type,
        coalesce(note.metadata, '{}'::jsonb),
        note.reply_to,
        v_user_id,
        v_role_id,
        inbox.category,
        v_key
      )
      order by note.id, inbox.created_at desc, inbox.id desc
    ), unread as (
      select count(*) filter (where not is_read)::integer as unread_count
      from visible
    ), windowed as (
      select *
      from visible
      where v_before_ts is null
         or created_at < v_before_ts
         or (created_at = v_before_ts and id::text < coalesce(v_before_id, ''))
      order by created_at desc, id desc
      limit v_limit + 1
    ), page_desc as (
      select * from windowed order by created_at desc, id desc limit v_limit
    ), page as (
      select * from page_desc order by created_at asc, id asc
    ), earliest as (
      select created_at, id::text as id_text from page order by created_at asc, id asc limit 1
    )
    select jsonb_build_object(
      'items', coalesce((
        select jsonb_agg(
          to_jsonb(page) || jsonb_build_object(
            'metadata',
            coalesce(page.metadata, '{}'::jsonb) || jsonb_build_object(
              'read_receipts',
              public.kalam_message_read_receipts_v1(
                v_org_id,
                'internal',
                v_key,
                page.author_id,
                page.created_at,
                page.id
              )
            )
          )
          order by page.created_at asc, page.id asc
        )
        from page
      ), '[]'::jsonb),
      'unread_count', coalesce((select unread_count from unread), 0),
      'first_unread_id', (select id::text from page where not is_read order by created_at asc, id asc limit 1),
      'has_more_before', (select count(*) > v_limit from windowed),
      'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
      'read_model', 'cursor'
    )
  );
end;
$$;


--
-- Name: get_internal_conversation_timeline(text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_internal_conversation_timeline(p_conversation_key text, p_limit integer DEFAULT 10, p_before_cursor text DEFAULT NULL::text, p_include_unread_window boolean DEFAULT true) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.get_internal_conversation_timeline_legacy_unbounded(
    p_conversation_key,
    least(greatest(coalesce(p_limit, 10), 1), 50),
    p_before_cursor,
    false
  );
$$;


--
-- Name: FUNCTION get_internal_conversation_timeline(p_conversation_key text, p_limit integer, p_before_cursor text, p_include_unread_window boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_internal_conversation_timeline(p_conversation_key text, p_limit integer, p_before_cursor text, p_include_unread_window boolean) IS 'Bounded communication timeline API. Unread count is returned separately; items never use the legacy unbounded unread window.';


--
-- Name: get_internal_conversation_timeline_legacy_unbounded(text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_internal_conversation_timeline_legacy_unbounded(p_conversation_key text, p_limit integer DEFAULT 10, p_before_cursor text DEFAULT NULL::text, p_include_unread_window boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id  uuid := public.current_org_id();
  v_role_id uuid := null;
  v_limit   integer := greatest(coalesce(p_limit, 10), 1);
  v_unread_count     integer := 0;
  v_first_unread_id  text    := null;
  v_has_more_before  boolean := false;
  v_next_before_cursor text  := null;
  v_before_ts timestamptz := null;
  v_before_id text        := null;
  v_items     jsonb       := '[]'::jsonb;
begin
  if v_user_id is null or v_org_id is null
     or nullif(trim(coalesce(p_conversation_key, '')), '') is null then
    return jsonb_build_object(
      'items', '[]'::jsonb,
      'unread_count', 0,
      'first_unread_id', null,
      'has_more_before', false,
      'next_before_cursor', null
    );
  end if;

  -- Fetch caller's role for role-based access check
  select p.role_id into v_role_id
  from public.profiles p
  where p.id = v_user_id
  limit 1;

  if nullif(trim(coalesce(p_before_cursor, '')), '') is not null then
    v_before_ts := nullif(split_part(p_before_cursor, '|', 1), '')::timestamptz;
    v_before_id := nullif(split_part(p_before_cursor, '|', 2), '');
  end if;

  -- ── Unread count (always computed, access-filtered) ──────────────────────
  with base as (
    select
      n.id,
      n.module_id,
      n.record_id,
      n.content,
      n.author_id,
      n.author_name,
      n.mention_user_ids,
      n.mention_role_ids,
      n.created_at,
      n.reply_to,
      n.source_type,
      n.metadata,
      n.is_edited,
      n.edited_at,
      coalesce(
        nii.conversation_key,
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id, n.id, n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ) as conversation_key,
      rs.read_at is not null or rs.dismissed_at is not null or n.author_id = v_user_id as is_read
    from public.notification_inbox_items nii
    join public.notes n
      on n.id::text = nii.source_id
     and n.org_id = nii.org_id
    left join public.notification_read_states rs
      on rs.org_id = v_org_id
     and rs.user_id = v_user_id
     and rs.section = 'notes'
     and rs.source_type = 'note'
     and rs.source_id = nii.source_id
    where nii.org_id = v_org_id
      and nii.section = 'notes'
      and nii.source_type = 'note'
      -- ACCESS FILTER
      and (
        nii.is_org_wide = true
        or v_user_id = any(nii.target_user_ids)
        or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
      )
      and coalesce(
        nii.conversation_key,
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id, n.id, n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ) = p_conversation_key
  )
  select
    count(*) filter (where not is_read)::integer,
    min(id::text) filter (where not is_read)
  into v_unread_count, v_first_unread_id
  from base;

  -- ── Paginated fetch (p_before_cursor path) ───────────────────────────────
  if v_before_ts is not null then
    with base as (
      select
        n.id, n.module_id, n.record_id, n.content,
        n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids,
        n.created_at, n.reply_to,
        n.source_type, n.metadata,
        n.is_edited, n.edited_at
      from public.notification_inbox_items nii
      join public.notes n
        on n.id::text = nii.source_id
       and n.org_id = nii.org_id
      where nii.org_id = v_org_id
        and nii.section = 'notes'
        and nii.source_type = 'note'
        -- ACCESS FILTER
        and (
          nii.is_org_wide = true
          or v_user_id = any(nii.target_user_ids)
          or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
        )
        and coalesce(
          nii.conversation_key,
          nullif(trim(nii.payload->>'conversation_key'), ''),
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id,
            coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'),
            coalesce(n.metadata, '{}'::jsonb),
            n.reply_to
          )
        ) = p_conversation_key
        and (
          n.created_at < v_before_ts
          or (n.created_at = v_before_ts and n.id::text < coalesce(v_before_id, ''))
        )
      order by n.created_at desc, n.id desc
      limit v_limit
    ),
    ordered as (
      select * from base order by created_at asc, id asc
    ),
    earliest as (
      select created_at, id::text as id_text
      from ordered
      order by created_at asc, id asc
      limit 1
    )
    select
      coalesce(jsonb_agg(to_jsonb(ordered.*) order by ordered.created_at asc, ordered.id asc), '[]'::jsonb),
      exists(
        select 1
        from public.notification_inbox_items nii
        join public.notes n
          on n.id::text = nii.source_id
         and n.org_id = nii.org_id
        join earliest e on true
        where nii.org_id = v_org_id
          and nii.section = 'notes'
          and nii.source_type = 'note'
          -- ACCESS FILTER
          and (
            nii.is_org_wide = true
            or v_user_id = any(nii.target_user_ids)
            or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
          )
          and coalesce(
            nii.conversation_key,
            nullif(trim(nii.payload->>'conversation_key'), ''),
            public.kalam_note_conversation_key(
              n.org_id, n.id, n.author_id,
              coalesce(n.mention_user_ids, '{}'::uuid[]),
              coalesce(n.source_type, n.metadata->>'source_type'),
              coalesce(n.metadata, '{}'::jsonb),
              n.reply_to
            )
          ) = p_conversation_key
          and (
            n.created_at < e.created_at
            or (n.created_at = e.created_at and n.id::text < e.id_text)
          )
      ),
      (select public.kalam_cursor_value(created_at, id_text) from earliest)
    into v_items, v_has_more_before, v_next_before_cursor
    from ordered;

    return jsonb_build_object(
      'items', coalesce(v_items, '[]'::jsonb),
      'unread_count', coalesce(v_unread_count, 0),
      'first_unread_id', v_first_unread_id,
      'has_more_before', coalesce(v_has_more_before, false),
      'next_before_cursor', v_next_before_cursor
    );
  end if;

  -- ── Unread-window path (many unreads → show from first unread) ────────────
  if p_include_unread_window and coalesce(v_unread_count, 0) > 10 then
    with unread_rows as (
      select
        n.id, n.module_id, n.record_id, n.content,
        n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids,
        n.created_at, n.reply_to,
        n.source_type, n.metadata,
        n.is_edited, n.edited_at
      from public.notification_inbox_items nii
      join public.notes n
        on n.id::text = nii.source_id
       and n.org_id = nii.org_id
      left join public.notification_read_states rs
        on rs.org_id = v_org_id
       and rs.user_id = v_user_id
       and rs.section = 'notes'
       and rs.source_type = 'note'
       and rs.source_id = nii.source_id
      where nii.org_id = v_org_id
        and nii.section = 'notes'
        and nii.source_type = 'note'
        -- ACCESS FILTER
        and (
          nii.is_org_wide = true
          or v_user_id = any(nii.target_user_ids)
          or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
        )
        and coalesce(
          nii.conversation_key,
          nullif(trim(nii.payload->>'conversation_key'), ''),
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id,
            coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'),
            coalesce(n.metadata, '{}'::jsonb),
            n.reply_to
          )
        ) = p_conversation_key
        and rs.read_at is null
        and rs.dismissed_at is null
        and n.author_id <> v_user_id
      order by n.created_at asc, n.id asc
    ),
    earliest as (
      select created_at, id::text as id_text
      from unread_rows
      order by created_at asc, id asc
      limit 1
    )
    select
      coalesce(jsonb_agg(to_jsonb(unread_rows.*) order by unread_rows.created_at asc, unread_rows.id asc), '[]'::jsonb),
      exists(
        select 1
        from public.notification_inbox_items nii
        join public.notes n
          on n.id::text = nii.source_id
         and n.org_id = nii.org_id
        join earliest e on true
        where nii.org_id = v_org_id
          and nii.section = 'notes'
          and nii.source_type = 'note'
          -- ACCESS FILTER
          and (
            nii.is_org_wide = true
            or v_user_id = any(nii.target_user_ids)
            or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
          )
          and coalesce(
            nii.conversation_key,
            nullif(trim(nii.payload->>'conversation_key'), ''),
            public.kalam_note_conversation_key(
              n.org_id, n.id, n.author_id,
              coalesce(n.mention_user_ids, '{}'::uuid[]),
              coalesce(n.source_type, n.metadata->>'source_type'),
              coalesce(n.metadata, '{}'::jsonb),
              n.reply_to
            )
          ) = p_conversation_key
          and (
            n.created_at < e.created_at
            or (n.created_at = e.created_at and n.id::text < e.id_text)
          )
      ),
      (select public.kalam_cursor_value(created_at, id_text) from earliest)
    into v_items, v_has_more_before, v_next_before_cursor
    from unread_rows;

  -- ── Default path: show latest N messages ─────────────────────────────────
  else
    with latest_rows as (
      select
        n.id, n.module_id, n.record_id, n.content,
        n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids,
        n.created_at, n.reply_to,
        n.source_type, n.metadata,
        n.is_edited, n.edited_at
      from public.notification_inbox_items nii
      join public.notes n
        on n.id::text = nii.source_id
       and n.org_id = nii.org_id
      where nii.org_id = v_org_id
        and nii.section = 'notes'
        and nii.source_type = 'note'
        -- ACCESS FILTER
        and (
          nii.is_org_wide = true
          or v_user_id = any(nii.target_user_ids)
          or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
        )
        and coalesce(
          nii.conversation_key,
          nullif(trim(nii.payload->>'conversation_key'), ''),
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id,
            coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'),
            coalesce(n.metadata, '{}'::jsonb),
            n.reply_to
          )
        ) = p_conversation_key
      order by n.created_at desc, n.id desc
      limit greatest(v_limit, 10)
    ),
    ordered as (
      select * from latest_rows order by created_at asc, id asc
    ),
    earliest as (
      select created_at, id::text as id_text
      from ordered
      order by created_at asc, id asc
      limit 1
    )
    select
      coalesce(jsonb_agg(to_jsonb(ordered.*) order by ordered.created_at asc, ordered.id asc), '[]'::jsonb),
      exists(
        select 1
        from public.notification_inbox_items nii
        join public.notes n
          on n.id::text = nii.source_id
         and n.org_id = nii.org_id
        join earliest e on true
        where nii.org_id = v_org_id
          and nii.section = 'notes'
          and nii.source_type = 'note'
          -- ACCESS FILTER
          and (
            nii.is_org_wide = true
            or v_user_id = any(nii.target_user_ids)
            or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
          )
          and coalesce(
            nii.conversation_key,
            nullif(trim(nii.payload->>'conversation_key'), ''),
            public.kalam_note_conversation_key(
              n.org_id, n.id, n.author_id,
              coalesce(n.mention_user_ids, '{}'::uuid[]),
              coalesce(n.source_type, n.metadata->>'source_type'),
              coalesce(n.metadata, '{}'::jsonb),
              n.reply_to
            )
          ) = p_conversation_key
          and (
            n.created_at < e.created_at
            or (n.created_at = e.created_at and n.id::text < e.id_text)
          )
      ),
      (select public.kalam_cursor_value(created_at, id_text) from earliest)
    into v_items, v_has_more_before, v_next_before_cursor
    from ordered;
  end if;

  return jsonb_build_object(
    'items', coalesce(v_items, '[]'::jsonb),
    'unread_count', coalesce(v_unread_count, 0),
    'first_unread_id', v_first_unread_id,
    'has_more_before', coalesce(v_has_more_before, false),
    'next_before_cursor', v_next_before_cursor
  );
end;
$$;


--
-- Name: get_internal_conversation_timeline_v2(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_internal_conversation_timeline_v2(p_conversation_key text, p_limit integer DEFAULT 20, p_before_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_key text := nullif(trim(coalesce(p_conversation_key, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_before_ts timestamptz := null;
  v_before_id text := null;
  v_direct_left uuid := null;
  v_direct_right uuid := null;
begin
  if v_user_id is null or v_org_id is null or v_key is null then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  select profile.role_id
    into v_role_id
  from public.profiles profile
  where profile.id = v_user_id
    and profile.org_id = v_org_id
  limit 1;

  if v_key like 'direct:%' then
    v_direct_left := public.kalam_try_uuid(split_part(v_key, ':', 2));
    v_direct_right := public.kalam_try_uuid(split_part(v_key, ':', 3));
    if v_direct_left is null
       or v_direct_right is null
       or (v_user_id <> v_direct_left and v_user_id <> v_direct_right) then
      return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
    end if;
  elsif v_key <> 'mine' and v_key <> 'system' and v_key not like 'group:%' then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  if nullif(trim(coalesce(p_before_cursor, '')), '') is not null then
    v_before_ts := nullif(split_part(p_before_cursor, '|', 1), '')::timestamptz;
    v_before_id := nullif(split_part(p_before_cursor, '|', 2), '');
  end if;

  return (
    with source_notes as materialized (
      select n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids, n.created_at, n.reply_to, n.source_type,
        n.metadata, n.is_edited, n.edited_at
      from public.notes n
      where v_key like 'direct:%'
        and n.org_id = v_org_id
        and n.author_id in (v_direct_left, v_direct_right)
        and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
        and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
        and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
        and (
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
          ) = v_key
          or (
            n.author_id = case when v_user_id = v_direct_left then v_direct_right else v_direct_left end
            and (
              v_user_id = any(coalesce(n.mention_user_ids, '{}'::uuid[]))
              or (
                v_role_id is not null
                and v_role_id = any(coalesce(n.mention_role_ids, '{}'::uuid[]))
              )
            )
          )
        )
        and public.kalam_can_access_note(
          n.id, n.author_id, n.org_id, n.mention_user_ids, n.mention_role_ids, n.reply_to, coalesce(n.metadata, '{}'::jsonb)
        )

      union all

      select n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids, n.created_at, n.reply_to, n.source_type,
        n.metadata, n.is_edited, n.edited_at
      from public.notes n
      where v_key = 'mine'
        and n.org_id = v_org_id
        and n.author_id = v_user_id
        and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
        and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
        and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
        and (
          lower(trim(coalesce(n.metadata->>'saved_message', 'false'))) in ('true', '1', 'yes')
          or cardinality(coalesce(n.mention_user_ids, '{}'::uuid[])) = 0
        )

      union all

      (
      select distinct on (n.id)
        n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids, n.created_at, n.reply_to, n.source_type,
        n.metadata, n.is_edited, n.edited_at
      from public.notification_inbox_items inbox
      join public.notes n
        on n.id::text = inbox.source_id
       and n.org_id = inbox.org_id
      where v_key = 'system'
        and inbox.org_id = v_org_id
        and inbox.section = 'notes'
        and inbox.source_type = 'note'
        and lower(trim(coalesce(inbox.category, ''))) in ('system', 'assistant')
        and coalesce(
          inbox.conversation_key,
          nullif(trim(inbox.payload->>'conversation_key'), ''),
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
          )
        ) = v_key
        and (
          inbox.is_org_wide = true
          or v_user_id = any(inbox.target_user_ids)
          or (v_role_id is not null and v_role_id = any(inbox.target_role_ids))
        )
      order by n.id, n.created_at desc
      )

      union all

      (
      select distinct on (n.id)
        n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids, n.created_at, n.reply_to, n.source_type,
        n.metadata, n.is_edited, n.edited_at
      from public.notification_inbox_items inbox
      join public.notes n
        on n.id::text = inbox.source_id
       and n.org_id = inbox.org_id
      where v_key like 'group:%'
        and inbox.org_id = v_org_id
        and inbox.section = 'notes'
        and inbox.source_type = 'note'
        and coalesce(
          inbox.conversation_key,
          nullif(trim(inbox.payload->>'conversation_key'), ''),
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
          )
        ) = v_key
        and (
          inbox.is_org_wide = true
          or v_user_id = any(inbox.target_user_ids)
          or (v_role_id is not null and v_role_id = any(inbox.target_role_ids))
        )
      order by n.id, n.created_at desc
      )
    ),
    visible as materialized (
      select source_notes.*,
        (
          source_notes.author_id = v_user_id
          or read_state.read_at is not null
          or read_state.dismissed_at is not null
          or (
            cursor_state.read_through_at is not null
            and (
              source_notes.created_at < cursor_state.read_through_at
              or (
                source_notes.created_at = cursor_state.read_through_at
                and source_notes.id::text <= coalesce(cursor_state.read_through_id, source_notes.id::text)
              )
            )
          )
        ) as is_read
      from source_notes
      left join public.notification_read_states read_state
        on read_state.org_id = v_org_id
       and read_state.user_id = v_user_id
       and read_state.section = 'notes'
       and read_state.source_type = 'note'
       and read_state.source_id = source_notes.id::text
      left join public.communication_read_cursors cursor_state
        on cursor_state.org_id = v_org_id
       and cursor_state.user_id = v_user_id
       and cursor_state.channel = 'internal'
       and cursor_state.conversation_key = v_key
    ),
    unread as (
      select count(*) filter (where not is_read)::integer as unread_count
      from visible
    ),
    windowed as (
      select *
      from visible
      where v_before_ts is null
         or created_at < v_before_ts
         or (created_at = v_before_ts and id::text < coalesce(v_before_id, ''))
      order by created_at desc, id desc
      limit v_limit + 1
    ),
    page_desc as (
      select * from windowed order by created_at desc, id desc limit v_limit
    ),
    page as (
      select * from page_desc order by created_at asc, id asc
    ),
    earliest as (
      select created_at, id::text as id_text from page order by created_at asc, id asc limit 1
    )
    select jsonb_build_object(
      'items', coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at asc, page.id asc) from page), '[]'::jsonb),
      'unread_count', coalesce((select unread_count from unread), 0),
      'first_unread_id', (select id::text from page where not is_read order by created_at asc, id asc limit 1),
      'has_more_before', (select count(*) > v_limit from windowed),
      'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
      'read_model', 'cursor'
    )
  );
end;
$$;


--
-- Name: get_internal_messaging_unread_total_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_internal_messaging_unread_total_v2() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select p.id as user_id, p.org_id, p.role_id
    from public.profiles p
    where p.id = auth.uid() and p.org_id = public.current_org_id()
    limit 1
  ), candidate as materialized (
    select distinct on (n.id)
      n.id as note_id, n.author_id, n.created_at,
      public.kalam_internal_message_conversation_key_v3(
        n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
        coalesce(n.mention_role_ids, '{}'::uuid[]), n.source_type, coalesce(n.metadata, '{}'::jsonb),
        n.reply_to, me.user_id, me.role_id, nii.category
      ) as conversation_key
    from me
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id and nii.section = 'notes' and nii.source_type = 'note'
    join public.notes n on n.id::text = nii.source_id and n.org_id = nii.org_id
    
where lower(trim(coalesce(nii.category, ''))) not in ('system', 'assistant')
      and public.kalam_can_access_internal_message_v2(
      nii.is_org_wide, nii.target_user_ids, nii.target_role_ids, n.author_id,
      n.mention_user_ids, n.mention_role_ids, n.source_type, n.metadata, nii.category,
      me.user_id, me.role_id
    )
    order by n.id, nii.created_at desc, nii.id desc
  ), visible as materialized (
    select c.note_id, c.author_id, c.created_at, c.conversation_key,
      (c.author_id = me.user_id or rs.read_at is not null or rs.dismissed_at is not null
        or (crc.read_through_at is not null and (
          c.created_at < crc.read_through_at
          or (c.created_at = crc.read_through_at and c.note_id::text <= coalesce(crc.read_through_id, c.note_id::text))
        ))) as is_read
    from candidate c
    join me on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id and rs.user_id = me.user_id
     and rs.section = 'notes' and rs.source_type = 'note' and rs.source_id = c.note_id::text
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id and crc.user_id = me.user_id
     and crc.channel = 'internal' and crc.conversation_key = c.conversation_key
    where nullif(trim(coalesce(c.conversation_key, '')), '') is not null
  )
  select count(*) filter (where not is_read)::integer from visible;
$$;


--
-- Name: get_local_installation_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_local_installation_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.local_deployment_runtime;
begin
 if auth.uid() is null or not exists(select 1 from public.user_organization_memberships
  where org_id=public.current_org_id() and user_id=auth.uid() and is_active and (is_owner or software_role='admin'))
 then raise exception using errcode='42501',message='داشبورد نصب فقط برای مدیر سازمان در دسترس است.'; end if;
 select * into r from public.local_deployment_runtime where org_id=public.current_org_id();
 if not found then raise exception 'این سازمان در نصب اختصاصی نیست.'; end if;
 return jsonb_build_object('code',r.code,'version',r.version,'last_report',r.last_report,'generated_at',r.report_at,'activated',r.activated,'features',r.features,'modules',r.modules);
end $$;


--
-- Name: get_notification_conversations(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_conversations(p_section text DEFAULT 'notes'::text) RETURNS TABLE(section text, conversation_key text, kind text, title text, subtitle text, avatar_url text, role_label text, note_count integer, unread_count integer, latest_message_at timestamp with time zone, last_message_preview text, user_id uuid, group_id uuid, bot_group_id uuid, channel_type text, status text, counterparty_label text, bot_chat_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select
      auth.uid() as user_id,
      public.current_org_id() as org_id,
      p.role_id
    from public.profiles p
    where p.id = auth.uid()
    limit 1
  ),
  note_raw as (
    select
      'notes'::text as section,
      coalesce(
        nii.conversation_key,
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id,
          n.id,
          n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ) as conversation_key,
      lower(trim(coalesce(nii.category, ''))) as inbox_category,
      nullif(trim(coalesce(nii.payload->>'chat_group_id', n.metadata->>'chat_group_id')), '') as chat_group_id,
      n.id as note_id,
      n.author_id,
      n.created_at,
      coalesce(nullif(trim(n.author_name), ''), nullif(trim(p2.full_name), ''), n.author_id::text) as author_name,
      nullif(trim(coalesce(nii.body, '')), '') as preview,
      rs.read_at is not null or rs.dismissed_at is not null or n.author_id = me.user_id as is_read
    from me
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'notes'
     and nii.source_type = 'note'
     -- ACCESS FILTER: only rows this user/role should see
     and (
       nii.is_org_wide = true
       or me.user_id = any(nii.target_user_ids)
       or (me.role_id is not null and me.role_id = any(nii.target_role_ids))
     )
    join public.notes n
      on n.id::text = nii.source_id
     and n.org_id = nii.org_id
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'notes'
     and rs.source_type = 'note'
     and rs.source_id = nii.source_id
    left join public.profiles p2
      on p2.id = n.author_id
    where p_section = 'notes'
  ),
  note_base as (
    select
      section,
      conversation_key,
      case
        when conversation_key like 'group:%' or chat_group_id is not null then 'group'
        when conversation_key = 'system' or inbox_category in ('system', 'assistant') then 'system'
        else 'direct'
      end as kind,
      note_id,
      author_id,
      created_at,
      author_name,
      preview,
      is_read
    from note_raw
  ),
  note_agg as (
    select
      section,
      conversation_key,
      kind,
      count(*)::integer as note_count,
      count(*) filter (where not is_read)::integer as unread_count,
      max(created_at) as latest_message_at
    from note_base
    where nullif(trim(coalesce(conversation_key, '')), '') is not null
    group by section, conversation_key, kind
  ),
  note_latest as (
    select distinct on (conversation_key)
      conversation_key,
      preview
    from note_base
    where nullif(trim(coalesce(conversation_key, '')), '') is not null
    order by conversation_key, created_at desc, note_id desc
  ),
  note_enriched as (
    select
      na.section,
      na.conversation_key,
      na.kind,
      case
        when na.kind = 'system' then 'پیام‌های سیستم'
        when na.kind = 'group' then coalesce(cg.name, 'گروه')
        else coalesce(other_profile.full_name, other_profile.id::text, split_part(na.conversation_key, ':', 3))
      end as title,
      case
        when na.kind = 'group' then 'گروه داخلی'
        when na.kind = 'direct' then coalesce(other_role.title, null)
        else null
      end as subtitle,
      case when na.kind = 'direct' then other_profile.avatar_url else null end as avatar_url,
      case when na.kind = 'direct' then other_role.title else null end as role_label,
      na.note_count,
      na.unread_count,
      na.latest_message_at,
      nl.preview as last_message_preview,
      case
        when na.kind = 'direct' then
          case
            when public.kalam_try_uuid(split_part(na.conversation_key, ':', 2)) = me.user_id
              then public.kalam_try_uuid(split_part(na.conversation_key, ':', 3))
            else public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
          end
        else null
      end as user_id,
      case when na.kind = 'group'
        then public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
        else null
      end as group_id,
      null::uuid as bot_group_id,
      null::text as channel_type,
      null::text as status,
      null::text as counterparty_label,
      null::text as bot_chat_id
    from note_agg na
    join me on true
    left join note_latest nl
      on nl.conversation_key = na.conversation_key
    left join public.chat_groups cg
      on na.kind = 'group'
     and cg.id = public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
    left join public.profiles other_profile
      on na.kind = 'direct'
     and other_profile.id = (
       case
         when public.kalam_try_uuid(split_part(na.conversation_key, ':', 2)) = me.user_id
           then public.kalam_try_uuid(split_part(na.conversation_key, ':', 3))
         else public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
       end
     )
    left join public.org_roles other_role
      on other_role.id = other_profile.role_id
  ),
  bot_base as (
    select
      'bot_messages'::text as section,
      'bot:' || g.id::text as conversation_key,
      'bot'::text as kind,
      g.id as bot_group_id,
      g.group_title,
      g.channel_type,
      g.status,
      g.bot_chat_id,
      g.customer_id,
      g.supplier_id,
      m.id as message_id,
      m.created_at,
      coalesce(nullif(trim(m.content_text), ''), nullif(trim(m.file_name), ''), nullif(trim(m.message_type), '')) as preview,
      m.direction,
      rs.read_at is not null or rs.dismissed_at is not null or m.direction <> 'inbound' as is_read
    from me
    join public.counterparty_bot_groups g
      on g.org_id = me.org_id
    left join public.counterparty_bot_messages m
      on m.bot_group_id = g.id
     and m.org_id = g.org_id
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'bot_messages'
     and rs.source_type = 'counterparty_bot_message'
     and rs.source_id = m.id::text
    where p_section = 'bot_messages'
      and (
        (
          coalesce(jsonb_array_length(g.metadata->'allowed_user_ids'), 0) = 0
          and coalesce(jsonb_array_length(g.metadata->'allowed_role_ids'), 0) = 0
        )
        or me.user_id = any(public.kalam_jsonb_uuid_array(g.metadata->'allowed_user_ids'))
        or (me.role_id is not null and me.role_id = any(public.kalam_jsonb_uuid_array(g.metadata->'allowed_role_ids')))
      )
  ),
  bot_agg as (
    select
      section,
      conversation_key,
      kind,
      bot_group_id,
      min(group_title) as title,
      min(channel_type) as channel_type,
      min(status) as status,
      min(bot_chat_id) as bot_chat_id,
      count(message_id)::integer as note_count,
      count(message_id) filter (where direction = 'inbound' and not is_read)::integer as unread_count,
      max(created_at) as latest_message_at
    from bot_base
    group by section, conversation_key, kind, bot_group_id
  ),
  bot_latest as (
    select distinct on (conversation_key)
      conversation_key,
      preview
    from bot_base
    where message_id is not null
    order by conversation_key, created_at desc, message_id desc
  ),
  bot_enriched as (
    select
      ba.section,
      ba.conversation_key,
      ba.kind,
      coalesce(nullif(trim(ba.title), ''), 'گروه بات') as title,
      case
        when g.customer_id is not null then coalesce(c.full_name, c.business_name, c.legal_name, c.system_code)
        when g.supplier_id is not null then coalesce(s.business_name, s.full_name, s.system_code)
        else null
      end as subtitle,
      null::text as avatar_url,
      null::text as role_label,
      ba.note_count,
      ba.unread_count,
      ba.latest_message_at,
      bl.preview as last_message_preview,
      null::uuid as user_id,
      null::uuid as group_id,
      ba.bot_group_id,
      ba.channel_type,
      ba.status,
      case
        when g.customer_id is not null then coalesce(c.full_name, c.business_name, c.legal_name, c.system_code)
        when g.supplier_id is not null then coalesce(s.business_name, s.full_name, s.system_code)
        else null
      end as counterparty_label,
      ba.bot_chat_id
    from bot_agg ba
    join public.counterparty_bot_groups g
      on g.id = ba.bot_group_id
    left join bot_latest bl
      on bl.conversation_key = ba.conversation_key
    left join public.customers c
      on c.id = g.customer_id
    left join public.suppliers s
      on s.id = g.supplier_id
  )
  select * from note_enriched
  union all
  select * from bot_enriched
  order by latest_message_at desc nulls last, title asc;
$$;


--
-- Name: get_notification_overlay_feed_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_overlay_feed_v1(p_before_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(section text, source_type text, source_id text, title text, body text, created_at timestamp with time zone, module_id text, record_id text, conversation_key text, payload jsonb, feed_cursor text, has_more boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  with me as (
    select
      auth.uid() as user_id,
      public.current_org_id() as org_id,
      p.role_id,
      nullif(trim(coalesce(p.voip_extension, '')), '') as voip_extension,
      (
        coalesce(lower(r.permissions #>> '{__voip,view}') <> 'false', true)
        and coalesce(lower(r.permissions #>> '{__voip,fields,all_call_notifications}') <> 'false', true)
      ) as can_view_all_calls
    from public.profiles p
    left join public.org_roles r
      on r.id = p.role_id
     and r.org_id = p.org_id
    where p.id = auth.uid()
      and p.org_id = public.current_org_id()
    limit 1
  ),
  limits as (
    select
      least(greatest(coalesce(p_limit, 20), 1), 50) as effective_limit,
      least(greatest(least(greatest(coalesce(p_limit, 20), 1), 50) * 20, 200), 2000) as candidate_limit
  ),
  cursor_value as (
    select
      nullif(split_part(coalesce(p_before_cursor, ''), '|', 1), '')::timestamptz as before_at,
      nullif(split_part(coalesce(p_before_cursor, ''), '|', 2), '') as before_key
  ),
  note_candidates as (
    select
      nii.source_type,
      nii.source_id,
      nii.title,
      nii.body,
      nii.last_event_at,
      nii.created_at as inbox_created_at,
      nii.module_id,
      nii.record_id,
      nii.payload,
      nii.category,
      nii.conversation_key
    from me
    cross join limits
    cross join cursor_value c
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'notes'
     and nii.source_type = 'note'
     and (
       nii.is_org_wide = true
       or me.user_id = any(nii.target_user_ids)
       or (me.role_id is not null and me.role_id = any(nii.target_role_ids))
     )
    where c.before_at is null
       or coalesce(nii.last_event_at, nii.created_at) < c.before_at
       or (
         coalesce(nii.last_event_at, nii.created_at) = c.before_at
         and concat_ws(':', 'notes', 'note', nii.source_id) < coalesce(c.before_key, '')
       )
    order by coalesce(nii.last_event_at, nii.created_at) desc, nii.source_id desc
    limit (select candidate_limit from limits)
  ),
  note_rows as (
    select
      'notes'::text as section,
      nc.source_type,
      nc.source_id,
      coalesce(nullif(trim(nc.title), ''), case when nc.category in ('system', 'assistant') then 'پیام سیستم' else 'پیام داخلی' end) as title,
      coalesce(nullif(trim(nc.body), ''), nullif(trim(n.content), ''), 'پیام جدید') as body,
      coalesce(nc.last_event_at, nc.inbox_created_at, n.created_at) as created_at,
      nullif(trim(coalesce(nc.module_id, n.module_id)), '') as module_id,
      nullif(trim(coalesce(nc.record_id, n.record_id)), '') as record_id,
      conv.conversation_key,
      coalesce(nc.payload, '{}'::jsonb)
        || jsonb_build_object(
          'category', nc.category,
          'conversation_key', conv.conversation_key,
          'author_name', coalesce(nullif(trim(n.author_name), ''), nullif(trim(author_profile.full_name), '')),
          'author_avatar_url', nullif(trim(coalesce(author_profile.avatar_url, '')), ''),
          'conversation_title',
            case
              when conv.conversation_key = 'system' then 'پیام‌های سیستم'
              when conv.conversation_key like 'group:%' then coalesce(nullif(trim(chat_group.name), ''), 'گروه')
              else coalesce(nullif(trim(n.author_name), ''), nullif(trim(author_profile.full_name), ''), 'کاربر سیستم')
            end,
          'conversation_avatar_url',
            case
              when conv.conversation_key like 'direct:%' then nullif(trim(coalesce(author_profile.avatar_url, '')), '')
              else null
            end,
          'group_title', nullif(trim(coalesce(chat_group.name, '')), '')
        ) as payload
    from me
    join note_candidates nc on true
    join public.notes n
      on n.org_id = me.org_id
     and n.id::text = nc.source_id
    left join public.profiles author_profile
      on author_profile.org_id = me.org_id
     and author_profile.id = n.author_id
    left join lateral (
      select coalesce(
        nc.conversation_key,
        nullif(trim(nc.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id,
          n.id,
          n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ) as conversation_key
    ) conv on true
    left join public.chat_groups chat_group
      on chat_group.org_id = me.org_id
     and chat_group.id = case
       when conv.conversation_key ~ '^group:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         then substring(conv.conversation_key from 7)::uuid
       else null::uuid
     end
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = nc.source_type
     and rs.source_id = nc.source_id
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id
     and crc.user_id = me.user_id
     and crc.channel = 'internal'
     and crc.conversation_key = conv.conversation_key
    where n.author_id is distinct from me.user_id
      and rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
      and (
        conv.conversation_key = 'system'
        or crc.read_through_at is null
        or n.created_at > crc.read_through_at
        or (
          n.created_at = crc.read_through_at
          and n.id::text > coalesce(crc.read_through_id, '')
        )
      )
  ),
  responsibility_candidates as (
    select
      nii.source_type,
      nii.source_id,
      nii.title,
      nii.body,
      nii.last_event_at,
      nii.created_at,
      nii.module_id,
      nii.record_id,
      nii.payload
    from me
    cross join limits
    cross join cursor_value c
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'responsibilities'
     and (
       nii.is_org_wide = true
       or me.user_id = any(nii.target_user_ids)
       or (me.role_id is not null and me.role_id = any(nii.target_role_ids))
     )
    where c.before_at is null
       or coalesce(nii.last_event_at, nii.created_at) < c.before_at
       or (
         coalesce(nii.last_event_at, nii.created_at) = c.before_at
         and concat_ws(':', 'responsibilities', nii.source_type, nii.source_id) < coalesce(c.before_key, '')
       )
    order by coalesce(nii.last_event_at, nii.created_at) desc, nii.source_type desc, nii.source_id desc
    limit (select candidate_limit from limits)
  ),
  responsibility_rows as (
    select
      'responsibilities'::text as section,
      rc.source_type,
      rc.source_id,
      coalesce(nullif(trim(rc.title), ''), 'مسئولیت جدید') as title,
      coalesce(nullif(trim(rc.body), ''), 'یک رکورد نیاز به رسیدگی دارد.') as body,
      coalesce(rc.last_event_at, rc.created_at) as created_at,
      nullif(trim(rc.module_id), '') as module_id,
      nullif(trim(rc.record_id), '') as record_id,
      null::text as conversation_key,
      coalesce(rc.payload, '{}'::jsonb) as payload
    from me
    join responsibility_candidates rc on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = rc.source_type
     and rs.source_id = rc.source_id
    where public.kalam_notification_source_exists(
        me.org_id,
        rc.source_type,
        coalesce(nullif(trim(rc.source_id), ''), nullif(trim(rc.record_id), '')),
        rc.record_id
      )
      and rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
  ),
  task_candidates as (
    select
      t.id,
      t.name,
      t.status,
      t.priority,
      t.created_at
    from me
    cross join limits
    cross join cursor_value c
    join public.tasks t
      on t.org_id = me.org_id
     and lower(trim(coalesce(t.status, ''))) <> 'canceled'
     and not exists (
       select 1
       from public.recycle_bin_records r
       where r.org_id = me.org_id
         and lower(trim(coalesce(r.source_table, ''))) = 'tasks'
         and trim(coalesce(r.source_record_id::text, '')) = t.id::text
     )
     and (
       (t.assignee_type = 'user' and t.assignee_id = me.user_id)
       or (t.assignee_type = 'role' and me.role_id is not null and (t.assignee_role_id = me.role_id or t.assignee_id = me.role_id))
       or (nullif(trim(coalesce(t.assignee_type, '')), '') is null and (t.assignee_id = me.user_id or t.assignee_id = me.role_id))
     )
    where c.before_at is null
       or t.created_at < c.before_at
       or (
         t.created_at = c.before_at
         and concat_ws(':', 'tasks', 'task', t.id::text) < coalesce(c.before_key, '')
       )
    order by t.created_at desc, t.id desc
    limit (select candidate_limit from limits)
  ),
  task_rows as (
    select
      'tasks'::text as section,
      'task'::text as source_type,
      tc.id::text as source_id,
      coalesce(nullif(trim(tc.name), ''), 'فعالیت جدید') as title,
      'یک فعالیت به شما ارجاع شده است.'::text as body,
      tc.created_at,
      'tasks'::text as module_id,
      tc.id::text as record_id,
      null::text as conversation_key,
      jsonb_build_object('status', tc.status, 'priority', tc.priority) as payload
    from me
    join task_candidates tc on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = 'task'
     and rs.source_id = tc.id::text
    where rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
  ),
  bot_candidates as (
    select
      nii.source_type,
      nii.source_id,
      nii.payload,
      nii.last_event_at,
      nii.created_at as inbox_created_at,
      nii.conversation_key
    from me
    cross join limits
    cross join cursor_value c
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'bot_messages'
     and nii.source_type = 'counterparty_bot_message'
     and (
       nii.is_org_wide = true
       or me.user_id = any(nii.target_user_ids)
       or (me.role_id is not null and me.role_id = any(nii.target_role_ids))
     )
    where c.before_at is null
       or coalesce(nii.last_event_at, nii.created_at) < c.before_at
       or (
         coalesce(nii.last_event_at, nii.created_at) = c.before_at
         and concat_ws(':', 'bot_messages', 'counterparty_bot_message', nii.source_id) < coalesce(c.before_key, '')
       )
    order by coalesce(nii.last_event_at, nii.created_at) desc, nii.source_id desc
    limit (select candidate_limit from limits)
  ),
  bot_rows as (
    select
      'bot_messages'::text as section,
      'counterparty_bot_message'::text as source_type,
      m.id::text as source_id,
      coalesce(nullif(trim(g.group_title), ''), 'پیام جدید بات') as title,
      coalesce(nullif(trim(m.content_text), ''), nullif(trim(m.file_name), ''), 'پیام جدید') as body,
      m.created_at,
      null::text as module_id,
      null::text as record_id,
      coalesce(
        bc.conversation_key,
        nullif(trim(bc.payload->>'conversation_key'), ''),
        'bot:' || g.id::text
      ) as conversation_key,
      coalesce(m.payload, '{}'::jsonb)
        || jsonb_build_object(
          'bot_group_id', g.id::text,
          'group_title', coalesce(nullif(trim(g.group_title), ''), nullif(trim(c.business_name), ''), nullif(trim(c.full_name), ''), nullif(trim(s.business_name), ''), nullif(trim(s.full_name), ''), 'گروه بات'),
          'conversation_title', coalesce(nullif(trim(g.group_title), ''), 'گروه بات'),
          'group_avatar_url', coalesce(nullif(trim(c.image_url), ''), nullif(trim(s.image_url), ''), nullif(trim(g.metadata->>'avatar_url'), '')),
          'counterparty_image_url', coalesce(nullif(trim(c.image_url), ''), nullif(trim(s.image_url), '')),
          'sender_display_name', coalesce(
            nullif(trim(m.payload->>'sender_display_name'), ''),
            nullif(trim(m.payload->>'sender_name'), ''),
            nullif(trim(m.payload->>'username'), ''),
            nullif(trim(m.payload->>'sender_id'), ''),
            nullif(trim(m.payload->>'user_id'), '')
          ),
          'sender_avatar_url', nullif(trim(coalesce(m.payload->>'sender_avatar_url', '')), '')
        ) as payload
    from me
    join bot_candidates bc on true
    join public.counterparty_bot_messages m
      on m.org_id = me.org_id
     and m.id::text = bc.source_id
     and m.direction = 'inbound'
    join public.counterparty_bot_groups g
      on g.org_id = me.org_id
     and g.id = m.bot_group_id
     and public.kalam_can_access_bot_group(g.id, g.org_id)
    left join public.customers c
      on c.org_id = me.org_id
     and c.id = g.customer_id
    left join public.suppliers s
      on s.org_id = me.org_id
     and s.id = g.supplier_id
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = 'counterparty_bot_message'
     and rs.source_id = m.id::text
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id
     and crc.user_id = me.user_id
     and crc.channel = 'bot'
     and crc.conversation_key = coalesce(
       bc.conversation_key,
       nullif(trim(bc.payload->>'conversation_key'), ''),
       'bot:' || g.id::text
     )
    where rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
      and (
        crc.read_through_at is null
        or m.created_at > crc.read_through_at
        or (
          m.created_at = crc.read_through_at
          and m.id::text > coalesce(crc.read_through_id, '')
        )
      )
  ),
  sms_candidates as (
    select
      m.id,
      m.sender,
      m.message_text,
      m.module_id,
      m.record_id,
      m.related_module_id,
      m.related_record_id,
      m.customer_id,
      m.assignee_type,
      m.assignee_id,
      m.assignee_role_id,
      coalesce(m.received_at, m.sent_at, m.created_at) as message_at
    from me
    cross join limits
    cross join cursor_value c
    join public.outbound_messages m
      on m.org_id = me.org_id
     and m.channel_type = 'sms'
     and m.direction = 'inbound'
    where c.before_at is null
       or coalesce(m.received_at, m.sent_at, m.created_at) < c.before_at
       or (
         coalesce(m.received_at, m.sent_at, m.created_at) = c.before_at
         and concat_ws(':', 'sms_messages', 'inbound_sms', m.id::text) < coalesce(c.before_key, '')
       )
    order by coalesce(m.received_at, m.sent_at, m.created_at) desc, m.created_at desc, m.id desc
    limit (select candidate_limit from limits)
  ),
  sms_rows as (
    select
      'sms_messages'::text as section,
      'inbound_sms'::text as source_type,
      sc.id::text as source_id,
      coalesce(nullif(trim(sc.sender), ''), 'پیامک ورودی') as title,
      coalesce(nullif(trim(sc.message_text), ''), 'پیامک جدید') as body,
      sc.message_at as created_at,
      nullif(trim(sc.module_id), '') as module_id,
      nullif(trim(sc.record_id), '') as record_id,
      null::text as conversation_key,
      jsonb_build_object(
        'sender', sc.sender,
        'related_module_id', sc.related_module_id,
        'related_record_id', sc.related_record_id,
        'customer_id', sc.customer_id
      ) as payload
    from me
    join sms_candidates sc on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = 'inbound_sms'
     and rs.source_id = sc.id::text
    where public.kalam_can_view_communication_record(
        'sms',
        me.org_id,
        sc.assignee_type,
        sc.assignee_id,
        sc.assignee_role_id,
        sc.module_id,
        public.kalam_try_uuid(sc.record_id),
        sc.related_module_id,
        public.kalam_try_uuid(sc.related_record_id),
        sc.customer_id
      )
      and rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
  ),
  voip_candidates as (
    select
      c.id,
      c.title,
      c.source_number,
      c.extension,
      c.module_id,
      c.record_id,
      c.related_module_id,
      c.related_record_id,
      c.assignee_type,
      c.assignee_id,
      c.assignee_role_id,
      coalesce(c.started_at, c.created_at) as call_at
    from me
    cross join limits
    cross join cursor_value cv
    join public.voip_call_logs c
      on c.org_id = me.org_id
     and c.direction = 'incoming'
    where cv.before_at is null
       or coalesce(c.started_at, c.created_at) < cv.before_at
       or (
         coalesce(c.started_at, c.created_at) = cv.before_at
         and concat_ws(':', 'voip_calls', 'voip_call', c.id::text) < coalesce(cv.before_key, '')
       )
    order by coalesce(c.started_at, c.created_at) desc, c.created_at desc, c.id desc
    limit (select candidate_limit from limits)
  ),
  voip_rows as (
    select
      'voip_calls'::text as section,
      'voip_call'::text as source_type,
      vc.id::text as source_id,
      coalesce(nullif(trim(vc.title), ''), nullif(trim(vc.source_number), ''), 'تماس ورودی') as title,
      'تماس ورودی پاسخ‌داده‌نشده یا بررسی‌نشده'::text as body,
      vc.call_at as created_at,
      nullif(trim(vc.module_id), '') as module_id,
      nullif(trim(vc.record_id), '') as record_id,
      null::text as conversation_key,
      jsonb_build_object(
        'source_number', vc.source_number,
        'extension', vc.extension,
        'related_module_id', vc.related_module_id,
        'related_record_id', vc.related_record_id
      ) as payload
    from me
    join voip_candidates vc on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = 'voip_call'
     and rs.source_id = vc.id::text
    where public.kalam_can_view_communication_record(
        'voip',
        me.org_id,
        vc.assignee_type,
        vc.assignee_id,
        vc.assignee_role_id,
        vc.module_id,
        public.kalam_try_uuid(vc.record_id),
        vc.related_module_id,
        public.kalam_try_uuid(vc.related_record_id),
        null::uuid
      )
      and rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
  ),
  all_rows as (
    select * from note_rows
    union all select * from responsibility_rows
    union all select * from task_rows
    union all select * from bot_rows
    union all select * from sms_rows
    union all select * from voip_rows
  ),
  page as (
    select *
    from all_rows
    order by created_at desc, section desc, source_type desc, source_id desc
    limit (select effective_limit from limits) + 1
  ),
  visible_page as (
    select *
    from page
    order by created_at desc, section desc, source_type desc, source_id desc
    limit (select effective_limit from limits)
  ),
  page_meta as (
    select count(*) > (select effective_limit from limits) as has_more
    from page
  )
  select
    visible_page.section,
    visible_page.source_type,
    visible_page.source_id,
    visible_page.title,
    visible_page.body,
    visible_page.created_at,
    visible_page.module_id,
    visible_page.record_id,
    visible_page.conversation_key,
    visible_page.payload,
    visible_page.created_at::text || '|' || concat_ws(':', visible_page.section, visible_page.source_type, visible_page.source_id) as feed_cursor,
    page_meta.has_more
  from visible_page
  cross join page_meta
  order by visible_page.created_at desc, visible_page.section desc, visible_page.source_type desc, visible_page.source_id desc;
$_$;


--
-- Name: get_notification_overlay_feed_v2(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_overlay_feed_v2(p_before_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(section text, source_type text, source_id text, title text, body text, created_at timestamp with time zone, module_id text, record_id text, conversation_key text, payload jsonb, feed_cursor text, has_more boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    feed.section,
    feed.source_type,
    feed.source_id,
    feed.title,
    feed.body,
    feed.created_at,
    feed.module_id,
    feed.record_id,
    feed.conversation_key,
    case
      when feed.section = 'responsibilities' then
        coalesce(feed.payload, '{}'::jsonb)
        || jsonb_build_object(
          'action', nullif(trim(coalesce(nii.action, feed.payload->>'action', '')), ''),
          'module_id', nullif(trim(coalesce(feed.module_id, feed.payload->>'module_id', '')), '')
        )
      else coalesce(feed.payload, '{}'::jsonb)
    end as payload,
    feed.feed_cursor,
    feed.has_more
  from public.get_notification_overlay_feed_v1(p_before_cursor, p_limit) feed
  left join public.notification_inbox_items nii
    on nii.org_id = public.current_org_id()
   and nii.section = feed.section
   and nii.source_type = feed.source_type
   and nii.source_id = feed.source_id;
$$;


--
-- Name: get_notification_overlay_feed_v3(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_overlay_feed_v3(p_before_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(section text, source_type text, source_id text, title text, body text, created_at timestamp with time zone, module_id text, record_id text, conversation_key text, payload jsonb, feed_cursor text, has_more boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  with me as (
    select
      auth.uid() as user_id,
      public.current_org_id() as org_id,
      p.role_id
    from public.profiles p
    where p.id = auth.uid()
      and p.org_id = public.current_org_id()
    limit 1
  ),
  limits as (
    select
      least(greatest(coalesce(p_limit, 20), 1), 50) as effective_limit,
      least(greatest(least(greatest(coalesce(p_limit, 20), 1), 50) * 8, 80), 300) as candidate_limit
  ),
  cursor_value as (
    select
      nullif(split_part(coalesce(p_before_cursor, ''), '|', 1), '')::timestamptz as before_at,
      nullif(split_part(coalesce(p_before_cursor, ''), '|', 2), '') as before_key
  ),
  inbox_candidates as (
    select
      nii.section,
      nii.source_type,
      nii.source_id,
      nii.title,
      nii.body,
      nii.module_id,
      nii.record_id,
      nii.category,
      nii.action,
      nii.payload,
      nii.conversation_key,
      coalesce(nii.last_event_at, nii.created_at) as event_at
    from me
    cross join limits
    cross join cursor_value c
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section in ('notes', 'bot_messages', 'responsibilities')
     and (
       nii.is_org_wide = true
       or me.user_id = any(nii.target_user_ids)
       or (me.role_id is not null and me.role_id = any(nii.target_role_ids))
     )
    where c.before_at is null
       or coalesce(nii.last_event_at, nii.created_at) < c.before_at
       or (
         coalesce(nii.last_event_at, nii.created_at) = c.before_at
         and concat_ws(':', nii.section, nii.source_type, nii.source_id) < coalesce(c.before_key, '')
       )
    order by coalesce(nii.last_event_at, nii.created_at) desc, nii.section desc, nii.source_type desc, nii.source_id desc
    limit (select candidate_limit from limits)
  ),
  note_rows as (
    select
      'notes'::text as section,
      ic.source_type,
      ic.source_id,
      coalesce(nullif(trim(ic.title), ''), case when ic.category in ('system', 'assistant') then 'پیام سیستم' else 'پیام داخلی' end) as title,
      coalesce(nullif(trim(ic.body), ''), nullif(trim(n.content), ''), 'پیام جدید') as body,
      coalesce(ic.event_at, n.created_at) as created_at,
      nullif(trim(coalesce(ic.module_id, n.module_id)), '') as module_id,
      nullif(trim(coalesce(ic.record_id, n.record_id)), '') as record_id,
      conv.conversation_key,
      coalesce(ic.payload, '{}'::jsonb)
        || jsonb_build_object(
          'category', ic.category,
          'conversation_key', conv.conversation_key,
          'author_name', coalesce(nullif(trim(n.author_name), ''), nullif(trim(author_profile.full_name), '')),
          'author_avatar_url', nullif(trim(coalesce(author_profile.avatar_url, '')), ''),
          'conversation_title',
            case
              when conv.conversation_key = 'system' then 'پیام‌های سیستم'
              when conv.conversation_key like 'group:%' then coalesce(nullif(trim(chat_group.name), ''), 'گروه')
              else coalesce(nullif(trim(n.author_name), ''), nullif(trim(author_profile.full_name), ''), 'کاربر سیستم')
            end,
          'conversation_avatar_url',
            case
              when conv.conversation_key like 'direct:%' then nullif(trim(coalesce(author_profile.avatar_url, '')), '')
              else null
            end,
          'group_title', nullif(trim(coalesce(chat_group.name, '')), ''),
          'attachment_previews', public.kalam_extract_note_attachment_previews(n.content)
        ) as payload
    from me
    join inbox_candidates ic
      on ic.section = 'notes'
     and ic.source_type = 'note'
    join public.notes n
      on n.org_id = me.org_id
     and n.id = public.kalam_try_uuid(ic.source_id)
    left join public.profiles author_profile
      on author_profile.org_id = me.org_id
     and author_profile.id = n.author_id
    left join lateral (
      select coalesce(
        ic.conversation_key,
        nullif(trim(ic.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id,
          n.id,
          n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ) as conversation_key
    ) conv on true
    left join public.chat_groups chat_group
      on chat_group.org_id = me.org_id
     and chat_group.id = case
       when conv.conversation_key ~ '^group:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
         then substring(conv.conversation_key from 7)::uuid
       else null::uuid
     end
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = ic.source_type
     and rs.source_id = ic.source_id
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id
     and crc.user_id = me.user_id
     and crc.channel = 'internal'
     and crc.conversation_key = conv.conversation_key
    where n.author_id is distinct from me.user_id
      and rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
      and (
        conv.conversation_key = 'system'
        or crc.read_through_at is null
        or n.created_at > crc.read_through_at
        or (
          n.created_at = crc.read_through_at
          and n.id::text > coalesce(crc.read_through_id, '')
        )
      )
  ),
  bot_rows as (
    select
      'bot_messages'::text as section,
      'counterparty_bot_message'::text as source_type,
      m.id::text as source_id,
      coalesce(nullif(trim(g.group_title), ''), 'پیام جدید بات') as title,
      coalesce(nullif(trim(m.content_text), ''), nullif(trim(m.file_name), ''), 'پیام جدید') as body,
      m.created_at,
      null::text as module_id,
      null::text as record_id,
      coalesce(ic.conversation_key, nullif(trim(ic.payload->>'conversation_key'), ''), 'bot:' || g.id::text) as conversation_key,
      coalesce(m.payload, '{}'::jsonb)
        || coalesce(ic.payload, '{}'::jsonb)
        || jsonb_build_object(
          'bot_group_id', g.id::text,
          'group_title', coalesce(nullif(trim(g.group_title), ''), nullif(trim(c.business_name), ''), nullif(trim(c.full_name), ''), nullif(trim(s.business_name), ''), nullif(trim(s.full_name), ''), 'گروه بات'),
          'conversation_title', coalesce(nullif(trim(g.group_title), ''), 'گروه بات'),
          'group_avatar_url', coalesce(nullif(trim(c.image_url), ''), nullif(trim(s.image_url), ''), nullif(trim(g.metadata->>'avatar_url'), '')),
          'counterparty_image_url', coalesce(nullif(trim(c.image_url), ''), nullif(trim(s.image_url), '')),
          'sender_display_name', coalesce(
            nullif(trim(m.payload->>'sender_display_name'), ''),
            nullif(trim(m.payload->>'sender_name'), ''),
            nullif(trim(m.payload->>'username'), ''),
            nullif(trim(m.payload->>'sender_id'), ''),
            nullif(trim(m.payload->>'user_id'), '')
          ),
          'sender_avatar_url', nullif(trim(coalesce(m.payload->>'sender_avatar_url', '')), ''),
          'attachment_previews',
            (
              case
                when jsonb_typeof(coalesce(m.payload, '{}'::jsonb) -> 'attachments') = 'array'
                  then coalesce(m.payload, '{}'::jsonb) -> 'attachments'
                else '[]'::jsonb
              end
            )
            || case
              when nullif(trim(coalesce(m.file_url, '')), '') is not null then
                jsonb_build_array(jsonb_build_object(
                  'name', coalesce(nullif(trim(m.file_name), ''), 'فایل'),
                  'url', nullif(trim(m.file_url), ''),
                  'mime_type', nullif(trim(coalesce(m.mime_type, '')), ''),
                  'file_type', nullif(trim(coalesce(m.message_type, '')), '')
                ))
              else '[]'::jsonb
            end
        ) as payload
    from me
    join inbox_candidates ic
      on ic.section = 'bot_messages'
     and ic.source_type = 'counterparty_bot_message'
    join public.counterparty_bot_messages m
      on m.org_id = me.org_id
     and m.id = public.kalam_try_uuid(ic.source_id)
     and m.direction = 'inbound'
    join public.counterparty_bot_groups g
      on g.org_id = me.org_id
     and g.id = m.bot_group_id
     and public.kalam_can_access_bot_group(g.id, g.org_id)
    left join public.customers c
      on c.org_id = me.org_id
     and c.id = g.customer_id
    left join public.suppliers s
      on s.org_id = me.org_id
     and s.id = g.supplier_id
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = 'counterparty_bot_message'
     and rs.source_id = m.id::text
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id
     and crc.user_id = me.user_id
     and crc.channel = 'bot'
     and crc.conversation_key = coalesce(ic.conversation_key, nullif(trim(ic.payload->>'conversation_key'), ''), 'bot:' || g.id::text)
    where rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
      and (
        crc.read_through_at is null
        or m.created_at > crc.read_through_at
        or (
          m.created_at = crc.read_through_at
          and m.id::text > coalesce(crc.read_through_id, '')
        )
      )
  ),
  responsibility_rows as (
    select
      'responsibilities'::text as section,
      ic.source_type,
      ic.source_id,
      coalesce(nullif(trim(ic.title), ''), 'مسئولیت جدید') as title,
      coalesce(nullif(trim(ic.body), ''), 'یک رکورد نیاز به رسیدگی دارد.') as body,
      ic.event_at as created_at,
      nullif(trim(ic.module_id), '') as module_id,
      nullif(trim(ic.record_id), '') as record_id,
      null::text as conversation_key,
      coalesce(ic.payload, '{}'::jsonb)
        || jsonb_build_object(
          'action', nullif(trim(coalesce(ic.action, ic.payload->>'action', '')), ''),
          'module_id', nullif(trim(coalesce(ic.module_id, ic.payload->>'module_id', '')), '')
        ) as payload
    from me
    join inbox_candidates ic
      on ic.section = 'responsibilities'
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = ic.source_type
     and rs.source_id = ic.source_id
    where public.kalam_notification_source_exists(
        me.org_id,
        ic.source_type,
        coalesce(nullif(trim(ic.source_id), ''), nullif(trim(ic.record_id), '')),
        ic.record_id
      )
      and rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
  ),
  task_candidates as (
    select
      t.id,
      t.name,
      t.status,
      t.priority,
      t.created_at
    from me
    cross join limits
    cross join cursor_value c
    join public.tasks t
      on t.org_id = me.org_id
     and lower(trim(coalesce(t.status, ''))) <> 'canceled'
     and (
       (t.assignee_type = 'user' and t.assignee_id = me.user_id)
       or (t.assignee_type = 'role' and me.role_id is not null and (t.assignee_role_id = me.role_id or t.assignee_id = me.role_id))
       or (nullif(trim(coalesce(t.assignee_type, '')), '') is null and (t.assignee_id = me.user_id or t.assignee_id = me.role_id))
     )
    where c.before_at is null
       or t.created_at < c.before_at
       or (
         t.created_at = c.before_at
         and concat_ws(':', 'tasks', 'task', t.id::text) < coalesce(c.before_key, '')
       )
    order by t.created_at desc, t.id desc
    limit (select candidate_limit from limits)
  ),
  task_rows as (
    select
      'tasks'::text as section,
      'task'::text as source_type,
      tc.id::text as source_id,
      coalesce(nullif(trim(tc.name), ''), 'فعالیت جدید') as title,
      'یک فعالیت به شما ارجاع شده است.'::text as body,
      tc.created_at,
      'tasks'::text as module_id,
      tc.id::text as record_id,
      null::text as conversation_key,
      jsonb_build_object('status', tc.status, 'priority', tc.priority) as payload
    from me
    join task_candidates tc on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = 'task'
     and rs.source_id = tc.id::text
    where rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
      and not exists (
        select 1
        from public.recycle_bin_records r
        where r.org_id = me.org_id
          and lower(trim(coalesce(r.source_table, ''))) = 'tasks'
          and trim(coalesce(r.source_record_id::text, '')) = tc.id::text
      )
  ),
  sms_candidates as (
    select
      m.id,
      m.sender,
      m.message_text,
      m.module_id,
      m.record_id,
      m.related_module_id,
      m.related_record_id,
      m.customer_id,
      m.assignee_type,
      m.assignee_id,
      m.assignee_role_id,
      coalesce(m.received_at, m.sent_at, m.created_at) as message_at
    from me
    cross join limits
    cross join cursor_value c
    join public.outbound_messages m
      on m.org_id = me.org_id
     and m.channel_type = 'sms'
     and m.direction = 'inbound'
    where c.before_at is null
       or coalesce(m.received_at, m.sent_at, m.created_at) < c.before_at
       or (
         coalesce(m.received_at, m.sent_at, m.created_at) = c.before_at
         and concat_ws(':', 'sms_messages', 'inbound_sms', m.id::text) < coalesce(c.before_key, '')
       )
    order by coalesce(m.received_at, m.sent_at, m.created_at) desc, m.id desc
    limit (select candidate_limit from limits)
  ),
  sms_rows as (
    select
      'sms_messages'::text as section,
      'inbound_sms'::text as source_type,
      sc.id::text as source_id,
      coalesce(nullif(trim(sc.sender), ''), 'پیامک ورودی') as title,
      coalesce(nullif(trim(sc.message_text), ''), 'پیامک جدید') as body,
      sc.message_at as created_at,
      nullif(trim(sc.module_id), '') as module_id,
      nullif(trim(sc.record_id), '') as record_id,
      null::text as conversation_key,
      jsonb_build_object(
        'sender', sc.sender,
        'related_module_id', sc.related_module_id,
        'related_record_id', sc.related_record_id,
        'customer_id', sc.customer_id
      ) as payload
    from me
    join sms_candidates sc on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = 'inbound_sms'
     and rs.source_id = sc.id::text
    where public.kalam_can_view_communication_record_v2(
        'sms',
        me.org_id,
        sc.assignee_type,
        sc.assignee_id,
        sc.assignee_role_id,
        sc.module_id,
        public.kalam_try_uuid(sc.record_id),
        sc.related_module_id,
        public.kalam_try_uuid(sc.related_record_id),
        sc.customer_id,
        null::text,
        null::text,
        null::text,
        null::text,
        null::text,
        null::text
      )
      and rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
  ),
  voip_candidates as (
    select
      c.id,
      c.title,
      c.source_number,
      c.extension,
      c.module_id,
      c.record_id,
      c.related_module_id,
      c.related_record_id,
      c.assignee_type,
      c.assignee_id,
      c.assignee_role_id,
      coalesce(c.started_at, c.created_at) as call_at
    from me
    cross join limits
    cross join cursor_value cur
    join public.voip_call_logs c
      on c.org_id = me.org_id
     and c.direction = 'incoming'
    where cur.before_at is null
       or coalesce(c.started_at, c.created_at) < cur.before_at
       or (
         coalesce(c.started_at, c.created_at) = cur.before_at
         and concat_ws(':', 'voip_calls', 'voip_call', c.id::text) < coalesce(cur.before_key, '')
       )
    order by coalesce(c.started_at, c.created_at) desc, c.id desc
    limit (select candidate_limit from limits)
  ),
  voip_rows as (
    select
      'voip_calls'::text as section,
      'voip_call'::text as source_type,
      vc.id::text as source_id,
      coalesce(nullif(trim(vc.title), ''), nullif(trim(vc.source_number), ''), 'تماس ورودی') as title,
      'تماس ورودی پاسخ‌داده‌نشده یا بررسی‌نشده'::text as body,
      vc.call_at as created_at,
      nullif(trim(vc.module_id), '') as module_id,
      nullif(trim(vc.record_id), '') as record_id,
      null::text as conversation_key,
      jsonb_build_object(
        'source_number', vc.source_number,
        'extension', vc.extension,
        'related_module_id', vc.related_module_id,
        'related_record_id', vc.related_record_id
      ) as payload
    from me
    join voip_candidates vc on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.source_type = 'voip_call'
     and rs.source_id = vc.id::text
    where public.kalam_can_view_communication_record_v2(
        'voip',
        me.org_id,
        vc.assignee_type,
        vc.assignee_id,
        vc.assignee_role_id,
        vc.module_id,
        public.kalam_try_uuid(vc.record_id),
        vc.related_module_id,
        public.kalam_try_uuid(vc.related_record_id),
        null::uuid,
        null::text,
        null::text,
        null::text,
        null::text,
        null::text,
        null::text
      )
      and rs.read_at is null
      and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
  ),
  all_rows as (
    select * from note_rows
    union all select * from bot_rows
    union all select * from responsibility_rows
    union all select * from task_rows
    union all select * from sms_rows
    union all select * from voip_rows
  ),
  ranked_rows as (
    select
      all_rows.*,
      concat_ws(':', all_rows.section, all_rows.source_type, all_rows.source_id) as cursor_key,
      row_number() over (
        order by all_rows.created_at desc nulls last, concat_ws(':', all_rows.section, all_rows.source_type, all_rows.source_id) desc
      ) as rn,
      count(*) over () as total_count
    from all_rows
    where all_rows.created_at is not null
  )
  select
    ranked_rows.section,
    ranked_rows.source_type,
    ranked_rows.source_id,
    ranked_rows.title,
    ranked_rows.body,
    ranked_rows.created_at,
    ranked_rows.module_id,
    ranked_rows.record_id,
    ranked_rows.conversation_key,
    ranked_rows.payload,
    ranked_rows.created_at::text || '|' || ranked_rows.cursor_key as feed_cursor,
    ranked_rows.total_count > limits.effective_limit as has_more
  from ranked_rows
  cross join limits
  where ranked_rows.rn <= limits.effective_limit
  order by ranked_rows.created_at desc nulls last, ranked_rows.cursor_key desc;
$_$;


--
-- Name: get_notification_overlay_feed_v4(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_overlay_feed_v4(p_before_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(section text, source_type text, source_id text, title text, body text, created_at timestamp with time zone, module_id text, record_id text, conversation_key text, payload jsonb, feed_cursor text, has_more boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select auth.uid() as user_id, public.current_org_id() as org_id, p.role_id
    from public.profiles p where p.id = auth.uid() and p.org_id = public.current_org_id() limit 1
  ), limits as (
    select least(greatest(coalesce(p_limit, 20), 1), 50) as effective_limit,
      least(greatest(least(greatest(coalesce(p_limit, 20), 1), 50) * 8, 80), 300) as candidate_limit
  ), cursor_value as (
    select nullif(split_part(coalesce(p_before_cursor, ''), '|', 1), '')::timestamptz as before_at,
      nullif(split_part(coalesce(p_before_cursor, ''), '|', 2), '') as before_key
  ), v3_rows as (
    select f.section, f.source_type, f.source_id, f.title, f.body, f.created_at, f.module_id, f.record_id, f.conversation_key, f.payload
    from me
    cross join lateral public.get_notification_overlay_feed_v3(p_before_cursor, (select candidate_limit from limits)) f
    where not (
      f.section = 'notes'
      and (
        coalesce(f.conversation_key, '') = 'system'
        or lower(trim(coalesce(f.payload->>'category', ''))) in ('system', 'assistant')
      )
    )
    or exists (
      select 1
      from public.notification_inbox_items inbox
      where inbox.org_id = me.org_id
        and inbox.section = 'notes'
        and inbox.source_type = 'note'
        and inbox.source_id = f.source_id
        and (
          me.user_id = any(coalesce(inbox.target_user_ids, '{}'::uuid[]))
          or (me.role_id is not null and me.role_id = any(coalesce(inbox.target_role_ids, '{}'::uuid[])))
        )
    )
  ), note_candidates as (
    select distinct on (n.id)
      n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name, n.mention_user_ids, n.mention_role_ids,
      n.source_type, n.metadata, n.reply_to, n.created_at, nii.title as inbox_title, nii.body as inbox_body,
      nii.payload as inbox_payload, coalesce(nii.last_event_at, n.created_at) as event_at,
      conv.conversation_key as resolved_conversation_key
    from me cross join limits cross join cursor_value cur
    join public.notes n on n.org_id = me.org_id
    left join public.notification_inbox_items nii on nii.org_id = me.org_id and nii.section = 'notes'
      and nii.source_type = 'note' and nii.source_id = n.id::text
    left join public.chat_groups cg on cg.org_id = me.org_id and cg.id = public.kalam_try_uuid(n.metadata->>'chat_group_id')
    left join lateral (
      select coalesce(nullif(trim(nii.conversation_key), ''), nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to)) as conversation_key
    ) conv on true
    where (cur.before_at is null or coalesce(nii.last_event_at, n.created_at) < cur.before_at
      or (coalesce(nii.last_event_at, n.created_at) = cur.before_at
        and concat_ws(':', 'notes', 'note', n.id::text) < coalesce(cur.before_key, '')))
      and ((nii.id is not null and (nii.is_org_wide = true or me.user_id = any(coalesce(nii.target_user_ids, '{}'::uuid[]))
          or (me.role_id is not null and me.role_id = any(coalesce(nii.target_role_ids, '{}'::uuid[])))))
        or me.user_id = any(coalesce(n.mention_user_ids, '{}'::uuid[]))
        or (me.role_id is not null and me.role_id = any(coalesce(n.mention_role_ids, '{}'::uuid[])))
        or (cg.id is not null and (me.user_id = any(coalesce(cg.user_ids, '{}'::uuid[]))
          or (me.role_id is not null and me.role_id = any(coalesce(cg.role_ids, '{}'::uuid[]))))))
    order by n.id, coalesce(nii.last_event_at, n.created_at) desc
    limit (select candidate_limit from limits)
  ), extra_note_rows as (
    select 'notes'::text as section, 'note'::text as source_type, nc.id::text as source_id,
      coalesce(nullif(trim(nc.inbox_title), ''), case when nc.resolved_conversation_key = 'system' then 'پیام سیستم' else 'پیام داخلی' end) as title,
      coalesce(nullif(trim(nc.inbox_body), ''), nullif(trim(nc.content), ''), 'پیام جدید') as body,
      nc.event_at as created_at, nullif(trim(nc.module_id), '') as module_id, nullif(trim(nc.record_id), '') as record_id,
      nc.resolved_conversation_key as conversation_key,
      coalesce(nc.inbox_payload, '{}'::jsonb) || jsonb_build_object(
        'category', case when nc.resolved_conversation_key = 'system' and lower(trim(coalesce(nc.source_type, nc.metadata->>'source_type', ''))) = 'ai' then 'assistant'
          when nc.resolved_conversation_key = 'system' then 'system' when nc.resolved_conversation_key like 'group:%' then 'group' else 'internal' end,
        'conversation_key', nc.resolved_conversation_key, 'author_name', nullif(trim(coalesce(nc.author_name, '')), ''),
        'attachment_previews', public.kalam_extract_note_attachment_previews(nc.content)) as payload
    from me join note_candidates nc on true
    left join public.notification_read_states rs on rs.org_id = me.org_id and rs.user_id = me.user_id
      and rs.section = 'notes' and rs.source_type = 'note' and rs.source_id = nc.id::text
    left join public.communication_read_cursors crc on crc.org_id = me.org_id and crc.user_id = me.user_id
      and crc.channel = 'internal' and crc.conversation_key = nc.resolved_conversation_key
    where rs.read_at is null and rs.dismissed_at is null and (rs.snoozed_until is null or rs.snoozed_until <= now())
      and (nc.resolved_conversation_key = 'system' or nc.author_id is distinct from me.user_id)
      and (crc.read_through_at is null or nc.created_at > crc.read_through_at
        or (nc.created_at = crc.read_through_at and nc.id::text > coalesce(crc.read_through_id, '')))
  ), bot_candidates as (
    select m.id, m.bot_group_id, m.content_text, m.file_url, m.file_name, m.mime_type, m.message_type,
      m.payload as message_payload, m.created_at, g.group_title, g.metadata as group_metadata,
      c.business_name as customer_business_name, c.full_name as customer_full_name, c.image_url as customer_image_url,
      s.business_name as supplier_business_name, s.full_name as supplier_full_name, s.image_url as supplier_image_url
    from me cross join limits cross join cursor_value cur
    join public.counterparty_bot_messages m on m.org_id = me.org_id and m.direction = 'inbound'
    join public.counterparty_bot_groups g on g.org_id = me.org_id and g.id = m.bot_group_id and public.kalam_can_access_bot_group(g.id, g.org_id)
    left join public.customers c on c.org_id = me.org_id and c.id = g.customer_id
    left join public.suppliers s on s.org_id = me.org_id and s.id = g.supplier_id
    left join public.notification_read_states rs on rs.org_id = me.org_id and rs.user_id = me.user_id
      and rs.section = 'bot_messages' and rs.source_type = 'counterparty_bot_message' and rs.source_id = m.id::text
    left join public.communication_read_cursors crc on crc.org_id = me.org_id and crc.user_id = me.user_id
      and crc.channel = 'bot' and crc.conversation_key = 'bot:' || g.id::text
    where rs.read_at is null and rs.dismissed_at is null and (rs.snoozed_until is null or rs.snoozed_until <= now())
      and (crc.read_through_at is null or m.created_at > crc.read_through_at
        or (m.created_at = crc.read_through_at and m.id::text > coalesce(crc.read_through_id, '')))
      and (cur.before_at is null or m.created_at < cur.before_at
        or (m.created_at = cur.before_at and concat_ws(':', 'bot_messages', 'counterparty_bot_message', m.id::text) < coalesce(cur.before_key, '')))
    order by m.created_at desc, m.id desc limit (select candidate_limit from limits)
  ), extra_bot_rows as (
    select 'bot_messages'::text as section, 'counterparty_bot_message'::text as source_type, bc.id::text as source_id,
      coalesce(nullif(trim(bc.group_title), ''), 'پیام جدید بات') as title,
      coalesce(nullif(trim(bc.content_text), ''), nullif(trim(bc.file_name), ''), 'پیام جدید') as body, bc.created_at,
      null::text as module_id, null::text as record_id, 'bot:' || bc.bot_group_id::text as conversation_key,
      coalesce(bc.message_payload, '{}'::jsonb) || jsonb_build_object(
        'bot_group_id', bc.bot_group_id::text,
        'group_title', coalesce(nullif(trim(bc.group_title), ''), nullif(trim(bc.customer_business_name), ''), nullif(trim(bc.customer_full_name), ''), nullif(trim(bc.supplier_business_name), ''), nullif(trim(bc.supplier_full_name), ''), 'گروه بات'),
        'conversation_title', coalesce(nullif(trim(bc.group_title), ''), 'گروه بات'),
        'group_avatar_url', coalesce(nullif(trim(bc.customer_image_url), ''), nullif(trim(bc.supplier_image_url), ''), nullif(trim(bc.group_metadata->>'avatar_url'), '')),
        'counterparty_image_url', coalesce(nullif(trim(bc.customer_image_url), ''), nullif(trim(bc.supplier_image_url), '')),
        'sender_display_name', coalesce(nullif(trim(bc.message_payload->>'sender_display_name'), ''), nullif(trim(bc.message_payload->>'sender_name'), ''), nullif(trim(bc.message_payload->>'username'), ''), nullif(trim(bc.message_payload->>'sender_id'), ''), nullif(trim(bc.message_payload->>'user_id'), '')),
        'sender_avatar_url', nullif(trim(coalesce(bc.message_payload->>'sender_avatar_url', '')), ''),
        'attachment_previews', (case when jsonb_typeof(coalesce(bc.message_payload, '{}'::jsonb)->'attachments') = 'array' then coalesce(bc.message_payload, '{}'::jsonb)->'attachments' else '[]'::jsonb end)
          || case when nullif(trim(coalesce(bc.file_url, '')), '') is not null then jsonb_build_array(jsonb_build_object('name', coalesce(nullif(trim(bc.file_name), ''), 'فایل'), 'url', nullif(trim(bc.file_url), ''), 'mime_type', nullif(trim(coalesce(bc.mime_type, '')), ''), 'file_type', nullif(trim(coalesce(bc.message_type, '')), ''))) else '[]'::jsonb end) as payload
    from bot_candidates bc
  ), all_rows as (
    select * from v3_rows union all select * from extra_note_rows union all select * from extra_bot_rows
  ), deduped as (
    select distinct on (section, source_type, source_id) * from all_rows
    order by section, source_type, source_id, created_at desc nulls last
  ), ranked_rows as (
    select d.*, concat_ws(':', d.section, d.source_type, d.source_id) as cursor_key,
      row_number() over (order by d.created_at desc nulls last, concat_ws(':', d.section, d.source_type, d.source_id) desc) as rn,
      count(*) over () as total_count
    from deduped d where d.created_at is not null
  )
  select r.section, r.source_type, r.source_id, r.title, r.body, r.created_at, r.module_id, r.record_id,
    r.conversation_key, r.payload, r.created_at::text || '|' || r.cursor_key as feed_cursor,
    r.total_count > limits.effective_limit as has_more
  from ranked_rows r cross join limits where r.rn <= limits.effective_limit
  order by r.created_at desc nulls last, r.cursor_key desc;
$$;


--
-- Name: get_notification_overlay_feed_v5(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_overlay_feed_v5(p_before_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(section text, source_type text, source_id text, title text, body text, created_at timestamp with time zone, module_id text, record_id text, conversation_key text, payload jsonb, feed_cursor text, has_more boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select auth.uid() as user_id, public.current_org_id() as org_id, p.role_id
    from public.profiles p
    where p.id = auth.uid() and p.org_id = public.current_org_id()
    limit 1
  ), limits as (
    select least(greatest(coalesce(p_limit, 20), 1), 50) as effective_limit,
      least(greatest(least(greatest(coalesce(p_limit, 20), 1), 50) * 8, 80), 300) as candidate_limit
  ), cursor_value as (
    select nullif(split_part(coalesce(p_before_cursor, ''), '|', 1), '')::timestamptz as before_at,
      nullif(split_part(coalesce(p_before_cursor, ''), '|', 2), '') as before_key
  ), central_rows as (
    select f.section, f.source_type, f.source_id, f.title, f.body, f.created_at, f.module_id, f.record_id,
      f.conversation_key, f.payload, coalesce(f.has_more, false) as upstream_has_more
    from me
    cross join limits
    cross join lateral public.get_notification_overlay_feed_v4(p_before_cursor, limits.candidate_limit) f
    left join public.notification_inbox_items inbox
      on f.section = 'notes' and inbox.org_id = me.org_id and inbox.section = 'notes'
     and inbox.source_type = 'note' and inbox.source_id = f.source_id
    left join public.notes note on f.section = 'notes' and note.org_id = me.org_id and note.id::text = f.source_id
    where f.section <> 'notes'
      or public.kalam_can_access_internal_message_v2(
        inbox.is_org_wide, inbox.target_user_ids, inbox.target_role_ids, note.author_id,
        note.mention_user_ids, note.mention_role_ids, note.source_type, note.metadata, inbox.category,
        me.user_id, me.role_id
      )
  ), direct_candidates as (
    select m.id, m.direct_thread_id, m.content_text, m.file_url, m.file_name, m.mime_type, m.message_type,
      m.payload as message_payload, m.created_at, t.channel_type, t.chat_id, t.target_module_id,
      t.target_record_id, t.display_name, t.username, t.phone_number
    from me cross join limits cross join cursor_value cur
    join public.counterparty_bot_direct_threads t
      on t.org_id = me.org_id and public.kalam_can_access_bot_direct_thread(t.id, t.org_id)
    join public.counterparty_bot_direct_messages m
      on m.org_id = me.org_id and m.direct_thread_id = t.id and m.direction = 'inbound'
    left join public.notification_read_states rs
      on rs.org_id = me.org_id and rs.user_id = me.user_id
     and rs.source_type = 'counterparty_bot_direct_message' and rs.source_id = m.id::text
     and rs.section in ('bot_direct_messages', 'bot_messages')
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id and crc.user_id = me.user_id and crc.channel = 'bot'
     and crc.conversation_key = 'bot:direct:' || coalesce(t.channel_type, '') || ':' || coalesce(t.chat_id, '')
    where rs.read_at is null and rs.dismissed_at is null
      and (rs.snoozed_until is null or rs.snoozed_until <= now())
      and (crc.read_through_at is null or m.created_at > crc.read_through_at
        or (m.created_at = crc.read_through_at and m.id::text > coalesce(crc.read_through_id, '')))
      and (cur.before_at is null or m.created_at < cur.before_at
        or (m.created_at = cur.before_at and concat_ws(':', 'bot_direct_messages', 'counterparty_bot_direct_message', m.id::text) < coalesce(cur.before_key, '')))
    order by m.created_at desc, m.id desc
    limit ((select candidate_limit from limits) + 1)
  ), direct_rows as (
    select 'bot_direct_messages'::text as section, 'counterparty_bot_direct_message'::text as source_type,
      dc.id::text as source_id,
      coalesce(nullif(trim(dc.display_name), ''), nullif(trim(dc.message_payload->>'sender_display_name'), ''),
        case when nullif(trim(coalesce(dc.username, dc.message_payload->>'username')), '') is not null then '@' || trim(coalesce(dc.username, dc.message_payload->>'username')) end,
        nullif(trim(dc.chat_id), ''), 'پیام شخصی بات') as title,
      coalesce(nullif(trim(dc.content_text), ''), nullif(trim(dc.file_name), ''), 'پیام جدید') as body,
      dc.created_at, nullif(trim(dc.target_module_id), '') as module_id,
      nullif(trim(dc.target_record_id::text), '') as record_id,
      'bot:direct:' || coalesce(dc.channel_type, '') || ':' || coalesce(dc.chat_id, '') as conversation_key,
      coalesce(dc.message_payload, '{}'::jsonb) || jsonb_build_object(
        'direct_thread_id', dc.direct_thread_id::text, 'channel_type', nullif(trim(dc.channel_type), ''),
        'chat_id', nullif(trim(dc.chat_id), ''),
        'conversation_title', coalesce(nullif(trim(dc.display_name), ''), nullif(trim(dc.message_payload->>'sender_display_name'), ''), nullif(trim(dc.chat_id), ''), 'پیام شخصی بات'),
        'sender_display_name', coalesce(nullif(trim(dc.display_name), ''), nullif(trim(dc.message_payload->>'sender_display_name'), ''), nullif(trim(dc.chat_id), ''), 'پیام شخصی بات'),
        'username', nullif(trim(coalesce(dc.username, dc.message_payload->>'username')), ''),
        'phone_number', nullif(trim(coalesce(dc.phone_number, dc.message_payload->>'phone_number')), ''),
        'attachment_previews',
          (case when jsonb_typeof(coalesce(dc.message_payload, '{}'::jsonb)->'attachments') = 'array' then coalesce(dc.message_payload, '{}'::jsonb)->'attachments' else '[]'::jsonb end)
          || case when nullif(trim(coalesce(dc.file_url, '')), '') is not null then jsonb_build_array(jsonb_build_object(
            'name', coalesce(nullif(trim(dc.file_name), ''), 'فایل'), 'url', nullif(trim(dc.file_url), ''),
            'mime_type', nullif(trim(dc.mime_type), ''), 'file_type', nullif(trim(dc.message_type), '')
          )) else '[]'::jsonb end
      ) as payload,
      false as upstream_has_more
    from direct_candidates dc
  ), candidate_rows as (
    select * from central_rows union all select * from direct_rows
  ), deduped_rows as (
    select distinct on (section, source_type, source_id) *
    from candidate_rows
    order by section, source_type, source_id, created_at desc nulls last
  ), ranked_rows as (
    select dr.*, concat_ws(':', dr.section, dr.source_type, dr.source_id) as cursor_key,
      row_number() over (order by dr.created_at desc nulls last, concat_ws(':', dr.section, dr.source_type, dr.source_id) desc) as row_number,
      count(*) over () as candidate_count,
      bool_or(dr.upstream_has_more) over () as any_upstream_has_more
    from deduped_rows dr
    where dr.created_at is not null
  )
  select rr.section, rr.source_type, rr.source_id, rr.title, rr.body, rr.created_at, rr.module_id, rr.record_id,
    rr.conversation_key, rr.payload, rr.created_at::text || '|' || rr.cursor_key as feed_cursor,
    (rr.candidate_count > limits.effective_limit or rr.any_upstream_has_more) as has_more
  from ranked_rows rr cross join limits
  where rr.row_number <= limits.effective_limit
  order by rr.created_at desc nulls last, rr.cursor_key desc;
$$;


--
-- Name: get_notification_overlay_feed_v6(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_overlay_feed_v6(p_before_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(section text, source_type text, source_id text, title text, body text, created_at timestamp with time zone, module_id text, record_id text, conversation_key text, payload jsonb, feed_cursor text, has_more boolean, priority integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  with limits as (
    select least(greatest(coalesce(p_limit, 20), 1), 50) as effective_limit,
      least(greatest(least(greatest(coalesce(p_limit, 20), 1), 50) * 8, 120), 300) as candidate_limit
  ), cursor_value as (
    select
      case
        when nullif(split_part(coalesce(p_before_cursor, ''), '|', 3), '') is not null
          then coalesce(nullif(split_part(coalesce(p_before_cursor, ''), '|', 1), '')::integer, 0)
        else null::integer
      end as before_priority,
      case
        when nullif(split_part(coalesce(p_before_cursor, ''), '|', 3), '') is not null
          then nullif(split_part(coalesce(p_before_cursor, ''), '|', 2), '')::timestamptz
        else nullif(split_part(coalesce(p_before_cursor, ''), '|', 1), '')::timestamptz
      end as before_at,
      case
        when nullif(split_part(coalesce(p_before_cursor, ''), '|', 3), '') is not null
          then nullif(split_part(coalesce(p_before_cursor, ''), '|', 3), '')
        else nullif(split_part(coalesce(p_before_cursor, ''), '|', 2), '')
      end as before_key
  ), base_rows as (
    select
      f.section,
      f.source_type,
      f.source_id,
      f.title,
      f.body,
      f.created_at,
      f.module_id,
      f.record_id,
      coalesce(
        nullif(trim(coalesce(f.conversation_key, '')), ''),
        nullif(trim(coalesce(f.payload->>'conversation_key', '')), '')
      ) as resolved_conversation_key,
      f.payload,
      coalesce(f.has_more, false) as upstream_has_more
    from limits
    cross join lateral public.get_notification_overlay_feed_v5(null, limits.candidate_limit) f
  ), scored_rows as (
    select
      br.section,
      br.source_type,
      br.source_id,
      br.title,
      br.body,
      br.created_at,
      br.module_id,
      br.record_id,
      br.resolved_conversation_key as conversation_key,
      case
        when br.section = 'notes' and (
          coalesce(br.resolved_conversation_key, '') like 'agent:%'
          or nullif(trim(coalesce(br.payload->>'agent_key', '')), '') is not null
          or nullif(trim(coalesce(br.payload->>'waiting_approval_id', '')), '') is not null
        ) then greatest(
          case
            when coalesce(br.payload->>'priority', '') ~ '^-?\d+$'
              then (br.payload->>'priority')::integer
            else 10
          end,
          10
        )
        else case
          when coalesce(br.payload->>'priority', '') ~ '^-?\d+$'
            then (br.payload->>'priority')::integer
          else 0
        end
      end as resolved_priority,
      br.payload,
      concat_ws(':', br.section, br.source_type, br.source_id) as cursor_key,
      br.upstream_has_more
    from base_rows br
    where br.created_at is not null
  ), filtered_rows as (
    select sr.*
    from scored_rows sr
    cross join cursor_value cur
    where (
      cur.before_at is null
      or (
        cur.before_priority is not null and (
          sr.resolved_priority < cur.before_priority
          or (sr.resolved_priority = cur.before_priority and sr.created_at < cur.before_at)
          or (
            sr.resolved_priority = cur.before_priority
            and sr.created_at = cur.before_at
            and sr.cursor_key < coalesce(cur.before_key, '')
          )
        )
      )
      or (
        cur.before_priority is null and (
          sr.created_at < cur.before_at
          or (sr.created_at = cur.before_at and sr.cursor_key < coalesce(cur.before_key, ''))
        )
      )
    )
  ), ranked_rows as (
    select
      fr.*,
      row_number() over (
        order by fr.resolved_priority desc, fr.created_at desc nulls last, fr.cursor_key desc
      ) as rn,
      count(*) over () as candidate_count,
      bool_or(fr.upstream_has_more) over () as any_upstream_has_more
    from filtered_rows fr
  )
  select
    rr.section,
    rr.source_type,
    rr.source_id,
    rr.title,
    rr.body,
    rr.created_at,
    rr.module_id,
    rr.record_id,
    rr.conversation_key,
    coalesce(rr.payload, '{}'::jsonb) || jsonb_build_object(
      'priority', rr.resolved_priority,
      'conversation_key', rr.conversation_key
    ) as payload,
    rr.resolved_priority::text || '|' || rr.created_at::text || '|' || rr.cursor_key as feed_cursor,
    (rr.candidate_count > limits.effective_limit or rr.any_upstream_has_more) as has_more,
    rr.resolved_priority as priority
  from ranked_rows rr
  cross join limits
  where rr.rn <= limits.effective_limit
  order by rr.resolved_priority desc, rr.created_at desc nulls last, rr.cursor_key desc;
$_$;


--
-- Name: get_notification_unread_summary_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_unread_summary_v1(p_variant text DEFAULT NULL::text) RETURNS TABLE(section text, unread_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select
      auth.uid() as user_id,
      public.current_org_id() as org_id,
      p.role_id,
      lower(trim(coalesce(p_variant, ''))) as requested_variant
    from public.profiles p
    where p.id = auth.uid()
      and p.org_id = public.current_org_id()
    limit 1
  ),
  internal_scoped as (
    select distinct on (n.id)
      me.user_id,
      me.org_id,
      n.id as message_id,
      n.author_id,
      n.created_at,
      conv.conversation_key,
      rs.read_at,
      rs.dismissed_at
    from me
    join public.notes n
      on n.org_id = me.org_id
    left join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'notes'
     and nii.source_type = 'note'
     and nii.source_id = n.id::text
    left join public.chat_groups cg
      on cg.org_id = me.org_id
     and cg.id = public.kalam_try_uuid(n.metadata->>'chat_group_id')
    left join lateral (
      select coalesce(
        nullif(trim(nii.conversation_key), ''),
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id,
          n.id,
          n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ) as conversation_key
    ) conv on true
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'notes'
     and rs.source_type = 'note'
     and rs.source_id = n.id::text
    where nullif(trim(coalesce(conv.conversation_key, '')), '') is not null
      and (
        (
          nii.id is not null
          and (
            nii.is_org_wide = true
            or me.user_id = any(coalesce(nii.target_user_ids, '{}'::uuid[]))
            or (me.role_id is not null and me.role_id = any(coalesce(nii.target_role_ids, '{}'::uuid[])))
          )
        )
        or n.author_id = me.user_id
        or me.user_id = any(coalesce(n.mention_user_ids, '{}'::uuid[]))
        or (me.role_id is not null and me.role_id = any(coalesce(n.mention_role_ids, '{}'::uuid[])))
        or (
          cg.id is not null
          and (
            me.user_id = any(coalesce(cg.user_ids, '{}'::uuid[]))
            or (me.role_id is not null and me.role_id = any(coalesce(cg.role_ids, '{}'::uuid[])))
          )
        )
      )
    order by n.id, coalesce(nii.last_event_at, nii.created_at, n.created_at) desc
  ),
  internal_total as (
    select count(*)::integer as value
    from internal_scoped scoped
    left join public.communication_read_cursors crc
      on crc.org_id = scoped.org_id
     and crc.user_id = scoped.user_id
     and crc.channel = 'internal'
     and crc.conversation_key = scoped.conversation_key
    where scoped.author_id is distinct from scoped.user_id
      and scoped.read_at is null
      and scoped.dismissed_at is null
      and not (
        crc.read_through_at is not null
        and (
          scoped.created_at < crc.read_through_at
          or (
            scoped.created_at = crc.read_through_at
            and scoped.message_id::text <= coalesce(crc.read_through_id, scoped.message_id::text)
          )
        )
      )
  ),
  note_like_total as (
    select count(*)::integer as value
    from me
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'notes'
     and nii.source_type = 'note_like'
     and (
       nii.is_org_wide = true
       or me.user_id = any(coalesce(nii.target_user_ids, '{}'::uuid[]))
       or (me.role_id is not null and me.role_id = any(coalesce(nii.target_role_ids, '{}'::uuid[])))
     )
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'notes'
     and rs.source_type = 'note_like'
     and rs.source_id = nii.source_id
    where rs.read_at is null
      and rs.dismissed_at is null
  ),
  bot_total as (
    select coalesce(sum(unread.unread_count), 0)::integer as value
    from me
    join public.counterparty_bot_groups g
      on g.org_id = me.org_id
     and public.kalam_can_access_bot_group(g.id, g.org_id)
    left join public.communication_read_cursors crc
      on crc.org_id = me.org_id
     and crc.user_id = me.user_id
     and crc.channel = 'bot'
     and crc.conversation_key = 'bot:' || g.id::text
    left join lateral (
      select count(*)::integer as unread_count
      from public.counterparty_bot_messages m
      left join public.notification_read_states rs
        on rs.org_id = me.org_id
       and rs.user_id = me.user_id
       and rs.section = 'bot_messages'
       and rs.source_type = 'counterparty_bot_message'
       and rs.source_id = m.id::text
      where m.org_id = g.org_id
        and m.bot_group_id = g.id
        and m.direction = 'inbound'
        and rs.read_at is null
        and rs.dismissed_at is null
        and (
          crc.read_through_at is null
          or m.created_at > crc.read_through_at
          or (
            m.created_at = crc.read_through_at
            and m.id::text > coalesce(crc.read_through_id, '')
          )
        )
    ) unread on true
  ),
  sms_total as (
    select count(*)::integer as value
    from me
    join public.outbound_messages m
      on m.org_id = me.org_id
     and m.channel_type = 'sms'
     and m.direction = 'inbound'
     and public.kalam_can_view_communication_record(
       'sms',
       m.org_id,
       m.assignee_type,
       m.assignee_id,
       m.assignee_role_id,
       m.module_id,
       public.kalam_try_uuid(m.record_id),
       m.related_module_id,
       public.kalam_try_uuid(m.related_record_id),
       m.customer_id
     )
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section in ('sms', 'sms_messages')
     and rs.source_type = 'inbound_sms'
     and rs.source_id = m.id::text
    where rs.read_at is null
      and rs.dismissed_at is null
  ),
  voip_total as (
    select count(*)::integer as value
    from me
    join public.voip_call_logs c
      on c.org_id = me.org_id
     and c.direction = 'incoming'
     and public.kalam_can_view_communication_record(
       'voip',
       c.org_id,
       c.assignee_type,
       c.assignee_id,
       c.assignee_role_id,
       c.module_id,
       public.kalam_try_uuid(c.record_id),
       c.related_module_id,
       public.kalam_try_uuid(c.related_record_id),
       null::uuid
     )
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'voip_calls'
     and rs.source_type = 'voip_call'
     and rs.source_id = c.id::text
    where rs.read_at is null
      and rs.dismissed_at is null
  ),
  tasks_total as (
    select count(distinct t.id)::integer as value
    from me
    join public.tasks t
      on t.org_id = me.org_id
     and lower(trim(coalesce(t.status, ''))) <> 'canceled'
     and not exists (
       select 1
       from public.recycle_bin_records r
       where r.org_id = me.org_id
         and lower(trim(coalesce(r.source_table, ''))) = 'tasks'
         and trim(coalesce(r.source_record_id::text, '')) = t.id::text
     )
     and (
       (t.assignee_type = 'user' and t.assignee_id = me.user_id)
       or (t.assignee_type = 'role' and me.role_id is not null and t.assignee_role_id = me.role_id)
       or (t.assignee_type = 'role' and me.role_id is not null and t.assignee_id = me.role_id)
       or (nullif(trim(coalesce(t.assignee_type, '')), '') is null and t.assignee_id = me.user_id)
       or (nullif(trim(coalesce(t.assignee_type, '')), '') is null and me.role_id is not null and t.assignee_id = me.role_id)
     )
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'tasks'
     and rs.source_type = 'task'
     and rs.source_id = t.id::text
    where rs.read_at is null
      and rs.dismissed_at is null
  ),
  responsibilities_total as (
    select count(*)::integer as value
    from me
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'responsibilities'
     and public.kalam_notification_source_exists(
       me.org_id,
       nii.source_type,
       coalesce(nullif(trim(nii.source_id), ''), nullif(trim(nii.record_id), '')),
       nii.record_id
     )
     and (
       nii.is_org_wide = true
       or me.user_id = any(coalesce(nii.target_user_ids, '{}'::uuid[]))
       or (me.role_id is not null and me.role_id = any(coalesce(nii.target_role_ids, '{}'::uuid[])))
     )
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'responsibilities'
     and rs.source_type = nii.source_type
     and rs.source_id = nii.source_id
    where rs.read_at is null
      and rs.dismissed_at is null
  ),
  summary as (
    select 'notes'::text as section, (coalesce(internal_total.value, 0) + coalesce(note_like_total.value, 0))::integer as unread_count from internal_total cross join note_like_total
    union all select 'bot_messages', coalesce(value, 0)::integer from bot_total
    union all select 'sms_messages', coalesce(value, 0)::integer from sms_total
    union all select 'voip_calls', coalesce(value, 0)::integer from voip_total
    union all select 'tasks', coalesce(value, 0)::integer from tasks_total
    union all select 'responsibilities', coalesce(value, 0)::integer from responsibilities_total
  )
  select summary.section, summary.unread_count
  from summary
  cross join me
  where me.requested_variant not in ('chat', 'alerts')
     or (me.requested_variant = 'chat' and summary.section in ('notes', 'bot_messages', 'sms_messages', 'voip_calls'))
     or (me.requested_variant = 'alerts' and summary.section in ('tasks', 'responsibilities'))
  order by case summary.section
    when 'notes' then 1
    when 'bot_messages' then 2
    when 'sms_messages' then 3
    when 'voip_calls' then 4
    when 'tasks' then 5
    when 'responsibilities' then 6
    else 99
  end;
$$;


--
-- Name: get_notification_unread_summary_v2(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notification_unread_summary_v2(p_variant text DEFAULT NULL::text) RETURNS TABLE(section text, unread_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with requested_variant as (
    select lower(trim(coalesce(p_variant, ''))) as value
  ), base_summary as (
    select * from public.get_notification_unread_summary_v1(p_variant)
  ), internal_total as (
    select coalesce(public.get_internal_messaging_unread_total_v2(), 0)::integer as value
  ), system_total as (
    select coalesce(public.get_system_messaging_unread_total_v1(), 0)::integer as value
  ), bot_group_total as (
    select coalesce(max(unread_count) filter (where section = 'bot_messages'), 0)::integer as value
    from base_summary
  ), bot_direct_total as (
    select count(*)::integer as value
    from public.profiles me
    join public.counterparty_bot_direct_threads thread
      on thread.org_id = me.org_id
     and public.kalam_can_access_bot_direct_thread(thread.id, thread.org_id)
    join public.counterparty_bot_direct_messages message
      on message.org_id = me.org_id
     and message.direct_thread_id = thread.id
     and message.direction = 'inbound'
    left join public.notification_read_states read_state
      on read_state.org_id = me.org_id
     and read_state.user_id = me.id
     and read_state.source_type = 'counterparty_bot_direct_message'
     and read_state.source_id = message.id::text
     and read_state.section in ('bot_direct_messages', 'bot_messages')
    left join public.communication_read_cursors cursor_state
      on cursor_state.org_id = me.org_id
     and cursor_state.user_id = me.id
     and cursor_state.channel = 'bot'
     and cursor_state.conversation_key = 'bot:direct:' || coalesce(thread.channel_type, '') || ':' || coalesce(thread.chat_id, '')
    where me.id = auth.uid()
      and me.org_id = public.current_org_id()
      and read_state.read_at is null
      and read_state.dismissed_at is null
      and (
        cursor_state.read_through_at is null
        or message.created_at > cursor_state.read_through_at
        or (message.created_at = cursor_state.read_through_at and message.id::text > coalesce(cursor_state.read_through_id, ''))
      )
  ), patched_summary as (
    select section, unread_count
    from base_summary
    where section not in ('notes', 'bot_messages')
    union all select 'notes'::text, value from internal_total
    union all select 'system_messages'::text, value from system_total
    union all select 'bot_group_messages'::text, value from bot_group_total
    union all select 'bot_direct_messages'::text, value from bot_direct_total
    union all
    select 'bot_messages'::text, (bot_group_total.value + bot_direct_total.value)::integer
    from bot_group_total cross join bot_direct_total
  )
  select patched_summary.section, patched_summary.unread_count
  from patched_summary
  cross join requested_variant
  where requested_variant.value not in ('chat', 'alerts')
     or (requested_variant.value = 'chat' and patched_summary.section in ('notes', 'system_messages', 'bot_messages', 'bot_group_messages', 'bot_direct_messages', 'sms_messages', 'voip_calls'))
     or (requested_variant.value = 'alerts' and patched_summary.section in ('tasks', 'responsibilities'))
  order by case patched_summary.section
    when 'notes' then 1
    when 'system_messages' then 2
    when 'bot_messages' then 3
    when 'bot_group_messages' then 4
    when 'bot_direct_messages' then 5
    when 'sms_messages' then 6
    when 'voip_calls' then 7
    when 'tasks' then 8
    when 'responsibilities' then 9
    else 99
  end;
$$;


--
-- Name: get_online_invoice_payment_customer_club_benefits(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_online_invoice_payment_customer_club_benefits(p_transaction_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tx public.payment_transactions%rowtype;
  v_customer_id uuid;
  v_customer_name text := 'مشتری عزیز';
  v_result jsonb := '[]'::jsonb;
begin
  select * into v_tx
  from public.payment_transactions
  where id = p_transaction_id
    and purpose = 'online_invoice'
    and module_id = 'invoices'
    and status in ('verified', 'paid');
  if not found or coalesce((v_tx.metadata ->> 'invoice_payment_appended')::boolean, false) is not true then
    return v_result;
  end if;

  select i.customer_id,
         coalesce(nullif(btrim(c.full_name), ''), nullif(btrim(c.business_name), ''), 'مشتری عزیز')
  into v_customer_id, v_customer_name
  from public.invoices i
  left join public.customers c on c.id = i.customer_id and c.org_id = i.org_id
  where i.id = v_tx.record_id and i.org_id = v_tx.org_id;
  if v_customer_id is null then
    return v_result;
  end if;

  select coalesce(jsonb_agg(item order by item ->> 'title'), '[]'::jsonb)
  into v_result
  from (
    select jsonb_strip_nulls(jsonb_build_object(
      'kind', 'reward',
      'title', coalesce(nullif(btrim(rule.name), ''), ledger.description, 'مزیت باشگاه مشتریان'),
      'message_template', nullif(btrim(coalesce(rule.config ->> 'online_payment_success_message', '')), ''),
      'amount', ledger.amount,
      'currency', v_tx.currency,
      'customer_name', v_customer_name,
      'rule_name', rule.name,
      'source_type', ledger.source_type
    )) as item
    from public.customer_loyalty_ledger ledger
    left join public.customer_loyalty_rules rule
      on rule.id = ledger.rule_id and rule.org_id = ledger.org_id
    where ledger.org_id = v_tx.org_id
      and ledger.customer_id = v_customer_id
      and ledger.entry_type = 'credit'
      and ledger.source_table = 'invoices'
      and ledger.source_record_id = v_tx.record_id

    union all

    select jsonb_strip_nulls(jsonb_build_object(
      'kind', 'discount_code',
      'title', coalesce(nullif(btrim(code.title), ''), 'کد تخفیف باشگاه مشتریان'),
      'message_template', nullif(btrim(coalesce(code.metadata ->> 'online_payment_success_message', '')), ''),
      'discount_code', code.code,
      'customer_name', v_customer_name
    )) as item
    from public.customer_discount_codes code
    where code.org_id = v_tx.org_id
      and code.customer_id = v_customer_id
      and code.is_active = true
      and (code.starts_at is null or code.starts_at <= coalesce(v_tx.paid_at, v_tx.verified_at, now()))
      and (code.ends_at is null or code.ends_at >= coalesce(v_tx.paid_at, v_tx.verified_at, now()))
      and (
        code.metadata ->> 'source_invoice_id' = v_tx.record_id::text
        or code.metadata ->> 'source_record_id' = v_tx.record_id::text
      )
  ) benefits;

  return v_result;
end;
$$;


--
-- Name: get_operational_financial_history(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_operational_financial_history(p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_entity_type text := lower(trim(coalesce(p_entity_type, '')));
  v_exists boolean := false;
  v_history jsonb;
  v_club_rows jsonb := '[]'::jsonb;
begin
  if v_org_id is null or p_entity_id is null or v_entity_type not in ('customer', 'supplier', 'employee') then
    return jsonb_build_object(
      'rows', '[]'::jsonb,
      'summary', jsonb_build_object('total_debit', 0, 'total_credit', 0, 'final_balance', 0, 'source', 'central_financial_history')
    );
  end if;

  if v_entity_type = 'customer' then
    select exists(select 1 from public.customers where id = p_entity_id and org_id = v_org_id) into v_exists;
  elsif v_entity_type = 'supplier' then
    select exists(select 1 from public.suppliers where id = p_entity_id and org_id = v_org_id) into v_exists;
  else
    select exists(select 1 from public.employees where id = p_entity_id and org_id = v_org_id) into v_exists;
  end if;
  if not v_exists then
    return jsonb_build_object(
      'rows', '[]'::jsonb,
      'summary', jsonb_build_object('total_debit', 0, 'total_credit', 0, 'final_balance', 0, 'source', 'central_financial_history')
    );
  end if;

  v_history := public._get_operational_financial_history(v_org_id, v_entity_type, p_entity_id);
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', history.key,
    'row_type', 'club_credit',
    'source_label', history.source_label,
    'source_module_id', 'customer_club',
    'source_record_id', null,
    'payment_type', '',
    'status', history.status,
    'cheque_status', '',
    'date', history.date,
    'debit', 0,
    'credit', 0,
    'club_credit_amount', history.club_credit_amount,
    'balance', 0,
    'invoice_label', history.invoice_label,
    'bank_label', '-',
    'description', history.description,
    'created_at', history.created_at,
    'bank_module_id', null,
    'bank_record_id', null
  ) order by history.date, history.created_at, history.key), '[]'::jsonb)
  into v_club_rows
  from public.get_customer_club_financial_history(v_entity_type, p_entity_id) history;

  return jsonb_set(
    coalesce(v_history, '{}'::jsonb),
    '{rows}',
    coalesce(v_history -> 'rows', '[]'::jsonb) || v_club_rows,
    true
  );
end;
$$;


--
-- Name: get_org_plan_access_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_plan_access_context(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
 s public.saas_org_settings%rowtype; p public.saas_plans%rowtype;
 f jsonb := '{}'::jsonb; m jsonb := '{}'::jsonb; inherited_f jsonb; inherited_m jsonb; entitlement_f jsonb:='{}'; entitlement_m jsonb:='{}';
 e record; internal_org boolean; available boolean; local_policy record;
begin
 if p_org_id is null then return jsonb_build_object('available',false,'features','{}'::jsonb,'enabledModules','{}'::jsonb); end if;
 select * into s from public.saas_org_settings where org_id=p_org_id;
 internal_org := public.org_is_saas_admin(p_org_id);
 select * into p from public.saas_plans where lower(code)=lower(s.plan_code) and is_active limit 1;
 -- Keep the expiry rule explicit: paid accounts do not expire from an old trial date.
 available := (p.id is not null or internal_org) and (s.org_id is not null or internal_org)
   and coalesce(s.status,'active') not in ('suspended','failed','draft')
   and not ((coalesce(s.is_demo,false) or coalesce(s.status,'') in ('trial','demo'))
     and (s.trial_ends_at is null or s.trial_ends_at <= now()));
 if internal_org then
   select coalesce(jsonb_object_agg(value,true),'{}') into f from jsonb_array_elements_text(public.saas_offering_keys()->'features');
   select coalesce(jsonb_object_agg(value,true),'{}') into m from jsonb_array_elements_text(public.saas_offering_keys()->'modules');
 end if;
 f := f || coalesce(p.enabled_features,'{}'); m := m || coalesce(p.enabled_modules,'{}');
 for e in select key,value from jsonb_each_text(public.saas_offering_keys()->'moduleParents') loop
  if not m?e.key then m:=m||jsonb_build_object(e.key,coalesce(m->e.value,'false'::jsonb)); end if;
 end loop;
 for e in select key,value from jsonb_each_text(public.saas_offering_keys()->'moduleFeatures') loop
  if not m?e.key then m:=m||jsonb_build_object(e.key,coalesce(f->e.value,'false'::jsonb)); end if;
 end loop;
 if not m?'instructions' then m:=m||'{"instructions":true}'::jsonb; end if;
 -- Legacy plans allow agents subject to module dependencies. An organization
 -- switching just one agent off must not switch every other legacy agent off.
 if not exists(select 1 from jsonb_object_keys(f) k where k like 'ai_agent:%') then
  select f||coalesce(jsonb_object_agg(value,true),'{}') into f
  from jsonb_array_elements_text(public.saas_offering_keys()->'features') where value like 'ai_agent:%';
 end if;
 for e in select item_kind,entitlement_code,bool_and(state='enabled') as enabled
   from public.saas_org_entitlements where org_id=p_org_id and item_kind in ('feature','module')
   and (expires_at is null or expires_at>now()) group by item_kind,entitlement_code loop
   if e.item_kind='feature' then f:=f||jsonb_build_object(e.entitlement_code,e.enabled); entitlement_f:=entitlement_f||jsonb_build_object(e.entitlement_code,e.enabled);
   else m:=m||jsonb_build_object(e.entitlement_code,e.enabled); entitlement_m:=entitlement_m||jsonb_build_object(e.entitlement_code,e.enabled); end if;
 end loop;
 inherited_f:=f; inherited_m:=m;
 f:=f||coalesce(s.feature_overrides,'{}'); m:=m||coalesce(s.module_overrides,'{}');
 -- Offline installations use their signed per-org availability contract.
 if to_regclass('public.local_deployment_runtime') is not null then
  execute 'select features,modules from public.local_deployment_runtime where org_id=$1' into local_policy using p_org_id;
  if local_policy.features is not null then f:=local_policy.features; m:=local_policy.modules; inherited_f:=f; inherited_m:=m; available:=true; end if;
 end if;
 -- Normalize legacy representations once, retain unknown keys for forward compatibility.
 select coalesce(jsonb_object_agg(key, coalesce(value='true'::jsonb or lower(value#>>'{}') in ('true','1','yes','on','enabled','full','limited') or value->'enabled'='true'::jsonb or value->'available'='true'::jsonb,false)),'{}') into f from jsonb_each(f);
 select coalesce(jsonb_object_agg(key, coalesce(value='true'::jsonb or lower(value#>>'{}') in ('true','1','yes','on','enabled'),false)),'{}') into m from jsonb_each(m);
 return jsonb_build_object('available',coalesce(available,false),'planCode',s.plan_code,
   'features',f,'enabledModules',m,'moduleOverrides',coalesce(s.module_overrides,'{}'),
   'featureEntitlements',entitlement_f,'moduleEntitlements',entitlement_m,'strictModules',true,'featureOverrides',coalesce(s.feature_overrides,'{}'),'inheritedFeatures',inherited_f,'inheritedModules',inherited_m,
   'status',s.status,'isReadonly',coalesce(s.is_readonly,false),
   'reason',case when internal_org then 'internal_organization' when not available then 'plan_unavailable' else null end);
end; $_$;


--
-- Name: get_own_expired_org_stories_for_media_cleanup(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_own_expired_org_stories_for_media_cleanup(p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, org_id uuid, slides jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 50));
begin
  if v_user_id is null or v_org_id is null then
    return;
  end if;

  update public.org_stories s
  set is_active = false,
      updated_at = now()
  where s.org_id = v_org_id
    and s.is_active = true
    and s.expires_at is not null
    and s.expires_at <= now();

  return query
  select s.id, s.org_id, s.slides
  from public.org_stories s
  where s.org_id = v_org_id
    and s.delete_media_on_expire = true
    and s.media_cleaned_at is null
    and s.expires_at is not null
    and s.expires_at <= now()
    and (
      s.creator_id = v_user_id
      or public.current_user_can_delete_story(s.creator_id)
    )
  order by s.expires_at asc
  limit v_limit;
end;
$$;


--
-- Name: get_process_runtime_batch_for_records(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_runtime_batch_for_records(p_module_id text, p_record_ids uuid[]) RETURNS TABLE(record_id uuid, runs jsonb, stages jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with requested_records as (
    select distinct unnest(coalesce(p_record_ids, '{}'::uuid[])) as record_id
  ),
  matching_run_ids as (
    select rr.record_id, r.id as process_run_id
    from requested_records rr
    join public.process_runs r
      on r.org_id = public.current_org_id()
     and r.module_id = p_module_id
     and r.record_id = rr.record_id

    union

    select rr.record_id, l.process_run_id
    from requested_records rr
    join public.process_run_links l
      on l.org_id = public.current_org_id()
     and l.module_id = p_module_id
     and l.record_id = rr.record_id

    union

    select rr.record_id, t.process_run_id
    from requested_records rr
    join public.tasks t
      on t.org_id = public.current_org_id()
     and t.process_run_id is not null
     and (t.recurrence_info -> 'process_links') @> jsonb_build_object(p_module_id, rr.record_id::text)

    union

    select rr.record_id, s.process_run_id
    from requested_records rr
    join public.process_run_stages s
      on (s.metadata -> 'process_link_map') @> jsonb_build_object(p_module_id, rr.record_id::text)
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = public.current_org_id()

    union

    select rr.record_id, s.process_run_id
    from requested_records rr
    join public.process_run_stages s
      on (s.metadata -> 'process_links') @> jsonb_build_object(p_module_id, rr.record_id::text)
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = public.current_org_id()
  ),
  matching_runs as (
    select matched.record_id as requested_record_id, r.*
    from matching_run_ids matched
    join public.process_runs r
      on r.id = matched.process_run_id
     and r.org_id = public.current_org_id()
  ),
  run_rows as (
    select
      r.requested_record_id,
      jsonb_build_object(
        'id', r.id,
        'template_id', r.template_id,
        'process_group_id', r.process_group_id,
        'process_name', r.process_name,
        'status', r.status,
        'module_id', r.module_id,
        'record_id', r.record_id,
        'started_at', r.started_at,
        'completed_at', r.completed_at,
        'created_at', r.created_at,
        'updated_at', r.updated_at,
        'created_by_name', creator.full_name,
        'updated_by_name', updater.full_name
      ) as row_json,
      r.created_at
    from matching_runs r
    left join public.profiles creator on creator.id = r.created_by and creator.org_id = r.org_id
    left join public.profiles updater on updater.id = r.updated_by and updater.org_id = r.org_id
  ),
  stage_rows as (
    select
      r.requested_record_id,
      jsonb_build_object(
        'id', s.id,
        'process_run_id', s.process_run_id,
        'template_stage_id', s.template_stage_id,
        'stage_name', s.stage_name,
        'sort_order', s.sort_order,
        'status', s.status,
        'task_id', s.task_id,
        'assignee_user_id', s.assignee_user_id,
        'assignee_role_id', s.assignee_role_id,
        'wage', s.wage,
        'metadata', s.metadata,
        'process_node_key', coalesce(to_jsonb(s) -> 'process_node_key', s.metadata -> 'process_node_key'),
        'process_lane_key', coalesce(to_jsonb(s) -> 'process_lane_key', s.metadata -> 'process_lane_key'),
        'created_at', s.created_at,
        'updated_at', s.updated_at
      ) as row_json,
      s.process_run_id,
      s.sort_order
    from public.process_run_stages s
    join matching_runs r on r.id = s.process_run_id
  )
  select
    rr.record_id,
    coalesce((
      select jsonb_agg(r.row_json order by r.created_at desc)
      from run_rows r
      where r.requested_record_id = rr.record_id
    ), '[]'::jsonb) as runs,
    coalesce((
      select jsonb_agg(s.row_json order by s.process_run_id, s.sort_order)
      from stage_rows s
      where s.requested_record_id = rr.record_id
    ), '[]'::jsonb) as stages
  from requested_records rr;
$$;


--
-- Name: get_process_runtime_for_record(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_runtime_for_record(p_module_id text, p_record_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with matching_run_ids as (
    select r.id as process_run_id
    from public.process_runs r
    where r.org_id = public.current_org_id()
      and r.module_id = p_module_id
      and r.record_id = p_record_id

    union

    select l.process_run_id
    from public.process_run_links l
    where l.org_id = public.current_org_id()
      and l.module_id = p_module_id
      and l.record_id = p_record_id

    union

    select t.process_run_id
    from public.tasks t
    where t.org_id = public.current_org_id()
      and t.process_run_id is not null
      and (t.recurrence_info -> 'process_links') @> jsonb_build_object(p_module_id, p_record_id::text)

    union

    select s.process_run_id
    from public.process_run_stages s
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = public.current_org_id()
    where (s.metadata -> 'process_link_map') @> jsonb_build_object(p_module_id, p_record_id::text)

    union

    select s.process_run_id
    from public.process_run_stages s
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = public.current_org_id()
    where (s.metadata -> 'process_links') @> jsonb_build_object(p_module_id, p_record_id::text)
  ),
  matching_runs as (
    select r.*
    from matching_run_ids matched
    join public.process_runs r
      on r.id = matched.process_run_id
     and r.org_id = public.current_org_id()
  ),
  run_rows as (
    select
      r.id,
      r.template_id,
      r.process_group_id,
      r.process_name,
      r.status,
      r.module_id,
      r.record_id,
      r.started_at,
      r.completed_at,
      r.created_at,
      r.updated_at,
      creator.full_name as created_by_name,
      updater.full_name as updated_by_name
    from matching_runs r
    left join public.profiles creator on creator.id = r.created_by and creator.org_id = r.org_id
    left join public.profiles updater on updater.id = r.updated_by and updater.org_id = r.org_id
  ),
  stage_rows as (
    select
      s.id,
      s.process_run_id,
      s.template_stage_id,
      s.stage_name,
      s.sort_order,
      s.status,
      s.task_id,
      s.assignee_user_id,
      s.assignee_role_id,
      s.wage,
      s.metadata,
      s.created_at,
      s.updated_at
    from public.process_run_stages s
    join matching_runs r on r.id = s.process_run_id
  )
  select jsonb_build_object(
    'runs', coalesce((select jsonb_agg(to_jsonb(rr) order by rr.created_at desc) from run_rows rr), '[]'::jsonb),
    'stages', coalesce((select jsonb_agg(to_jsonb(sr) order by sr.process_run_id, sr.sort_order) from stage_rows sr), '[]'::jsonb)
  );
$$;


--
-- Name: get_process_runtime_summary_batch_for_records(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_runtime_summary_batch_for_records(p_module_id text, p_record_ids uuid[]) RETURNS TABLE(record_id uuid, runs jsonb, stages jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with requested_records as (
    select distinct unnest(coalesce(p_record_ids, '{}'::uuid[])) as record_id
  ),
  matching_run_ids as (
    select rr.record_id, r.id as process_run_id
    from requested_records rr
    join public.process_runs r
      on r.org_id = public.current_org_id()
     and r.module_id = p_module_id
     and r.record_id = rr.record_id

    union

    select rr.record_id, l.process_run_id
    from requested_records rr
    join public.process_run_links l
      on l.org_id = public.current_org_id()
     and l.module_id = p_module_id
     and l.record_id = rr.record_id

    union

    select rr.record_id, t.process_run_id
    from requested_records rr
    join public.tasks t
      on t.org_id = public.current_org_id()
     and t.process_run_id is not null
     and (t.recurrence_info -> 'process_links') @> jsonb_build_object(p_module_id, rr.record_id::text)

    union

    select rr.record_id, s.process_run_id
    from requested_records rr
    join public.process_run_stages s
      on (s.metadata -> 'process_link_map') @> jsonb_build_object(p_module_id, rr.record_id::text)
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = public.current_org_id()

    union

    select rr.record_id, s.process_run_id
    from requested_records rr
    join public.process_run_stages s
      on (s.metadata -> 'process_links') @> jsonb_build_object(p_module_id, rr.record_id::text)
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = public.current_org_id()
  ),
  matching_runs as (
    select matched.record_id as requested_record_id, r.*
    from matching_run_ids matched
    join public.process_runs r
      on r.id = matched.process_run_id
     and r.org_id = public.current_org_id()
  ),
  run_rows as (
    select
      r.requested_record_id,
      jsonb_build_object(
        'id', r.id,
        'template_id', r.template_id,
        'process_group_id', r.process_group_id,
        'process_name', r.process_name,
        'status', r.status,
        'module_id', r.module_id,
        'record_id', r.record_id,
        'started_at', r.started_at,
        'completed_at', r.completed_at,
        'created_at', r.created_at,
        'updated_at', r.updated_at
      ) as row_json,
      r.created_at
    from matching_runs r
  ),
  stage_rows as (
    select
      r.requested_record_id,
      jsonb_build_object(
        'id', s.id,
        'process_run_id', s.process_run_id,
        'template_stage_id', s.template_stage_id,
        'stage_name', s.stage_name,
        'sort_order', s.sort_order,
        'status', coalesce(task.status, s.status),
        'task_id', coalesce(s.task_id, task.id),
        'assignee_user_id', s.assignee_user_id,
        'assignee_role_id', s.assignee_role_id,
        'wage', s.wage,
        'process_node_key', coalesce(to_jsonb(s) -> 'process_node_key', s.metadata -> 'process_node_key'),
        'process_lane_key', coalesce(to_jsonb(s) -> 'process_lane_key', s.metadata -> 'process_lane_key'),
        'created_at', s.created_at,
        'updated_at', s.updated_at
      ) as row_json,
      s.process_run_id,
      s.sort_order
    from public.process_run_stages s
    join matching_runs r on r.id = s.process_run_id
    left join lateral (
      select t.id, t.status
      from public.tasks t
      where t.org_id = r.org_id
        and (t.id = s.task_id or t.process_run_stage_id = s.id)
      order by t.updated_at desc nulls last, t.id
      limit 1
    ) task on true
    where not exists (
      select 1
      from public.process_v2_deleted_stage_marks mark
      where mark.org_id = r.org_id
        and mark.process_run_stage_id = s.id
    )
  )
  select
    rr.record_id,
    coalesce((
      select jsonb_agg(r.row_json order by r.created_at desc)
      from run_rows r
      where r.requested_record_id = rr.record_id
    ), '[]'::jsonb) as runs,
    coalesce((
      select jsonb_agg(s.row_json order by s.process_run_id, s.sort_order)
      from stage_rows s
      where s.requested_record_id = rr.record_id
    ), '[]'::jsonb) as stages
  from requested_records rr;
$$;


--
-- Name: get_process_runtime_tasks_batch_for_records(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_runtime_tasks_batch_for_records(p_module_id text, p_record_ids uuid[]) RETURNS TABLE(record_id uuid, tasks jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with requested_records as (
    select distinct unnest(coalesce(p_record_ids, '{}'::uuid[])) as record_id
  ),
  matching_run_ids as (
    select rr.record_id, r.id as process_run_id
    from requested_records rr
    join public.process_runs r
      on r.org_id = public.current_org_id()
     and r.module_id = p_module_id
     and r.record_id = rr.record_id

    union

    select rr.record_id, l.process_run_id
    from requested_records rr
    join public.process_run_links l
      on l.org_id = public.current_org_id()
     and l.module_id = p_module_id
     and l.record_id = rr.record_id

    union

    select rr.record_id, s.process_run_id
    from requested_records rr
    join public.process_run_stages s
      on (s.metadata -> 'process_link_map') @> jsonb_build_object(p_module_id, rr.record_id::text)
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = public.current_org_id()

    union

    select rr.record_id, s.process_run_id
    from requested_records rr
    join public.process_run_stages s
      on (s.metadata -> 'process_links') @> jsonb_build_object(p_module_id, rr.record_id::text)
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = public.current_org_id()
  ),
  matched_task_ids as (
    select rr.record_id, t.id as task_id
    from requested_records rr
    join public.tasks t
      on t.org_id = public.current_org_id()
     and t.source_module_id = p_module_id
     and t.source_record_id = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on t.org_id = public.current_org_id()
     and (t.recurrence_info -> 'process_links') @> jsonb_build_object(p_module_id, rr.record_id::text)

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'process_runs'
     and t.org_id = public.current_org_id()
     and t.process_run_id = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'projects'
     and t.org_id = public.current_org_id()
     and t.project_id = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'marketing_leads'
     and t.org_id = public.current_org_id()
     and t.marketing_lead_id = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'products'
     and t.org_id = public.current_org_id()
     and t.related_product = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'customers'
     and t.org_id = public.current_org_id()
     and t.related_customer = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'suppliers'
     and t.org_id = public.current_org_id()
     and t.related_supplier = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'production_orders'
     and t.org_id = public.current_org_id()
     and t.related_production_order = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'invoices'
     and t.org_id = public.current_org_id()
     and t.related_invoice = rr.record_id

    union

    select rr.record_id, t.id
    from requested_records rr
    join public.tasks t
      on p_module_id = 'purchase_invoices'
     and t.org_id = public.current_org_id()
     and t.purchase_invoice_id = rr.record_id

    union

    select mr.record_id, t.id
    from matching_run_ids mr
    join public.tasks t
      on t.org_id = public.current_org_id()
     and t.process_run_id = mr.process_run_id

    union

    select mr.record_id, t.id
    from matching_run_ids mr
    join public.process_run_stages s
      on s.process_run_id = mr.process_run_id
    join public.tasks t
      on t.org_id = public.current_org_id()
     and (t.id = s.task_id or t.process_run_stage_id = s.id)
  ),
  task_rows as (
    select
      matched.record_id,
      t.id,
      t.sort_order,
      t.source_stage_sort_order,
      t.due_date,
      jsonb_build_object(
        'id', t.id,
        'name', t.name,
        'status', t.status,
        'task_type', t.task_type,
        'assignee_id', t.assignee_id,
        'assignee_role_id', t.assignee_role_id,
        'assignee_type', t.assignee_type,
        'sort_order', t.sort_order,
        'process_group_id', t.process_group_id,
        'process_run_id', t.process_run_id,
        'process_run_stage_id', t.process_run_stage_id,
        'recurrence_info', t.recurrence_info,
        'source_module_id', t.source_module_id,
        'source_record_id', t.source_record_id,
        'source_template_id', t.source_template_id,
        'source_stage_sort_order', t.source_stage_sort_order,
        'process_node_key', t.process_node_key,
        'process_lane_key', t.process_lane_key,
        'due_date', t.due_date,
        'created_at', t.created_at,
        'updated_at', t.updated_at
      ) as row_json
    from matched_task_ids matched
    join public.tasks t
      on t.id = matched.task_id
     and t.org_id = public.current_org_id()
  )
  select
    rr.record_id,
    coalesce((
      select jsonb_agg(tr.row_json order by tr.sort_order nulls last, tr.source_stage_sort_order nulls last, tr.due_date nulls last, tr.id)
      from task_rows tr
      where tr.record_id = rr.record_id
    ), '[]'::jsonb) as tasks
  from requested_records rr;
$$;


--
-- Name: get_process_runtime_tasks_for_context(uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_runtime_tasks_for_context(p_task_ids uuid[] DEFAULT '{}'::uuid[], p_process_run_ids uuid[] DEFAULT '{}'::uuid[], p_process_run_stage_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(task_rows) order by task_rows.sort_order nulls last, task_rows.due_date nulls last, task_rows.id), '[]'::jsonb)
  from (
    select distinct on (t.id)
      t.id,
      t.name,
      t.status,
      t.task_type,
      t.assignee_id,
      t.assignee_role_id,
      t.assignee_type,
      t.sort_order,
      t.process_group_id,
      t.process_run_id,
      t.process_run_stage_id,
      t.recurrence_info,
      t.source_module_id,
      t.source_record_id,
      t.source_template_id,
      t.source_stage_sort_order,
      t.due_date
    from public.tasks t
    where t.org_id = public.current_org_id()
      and (
        t.id = any(coalesce(p_task_ids, '{}'::uuid[]))
        or t.process_run_id = any(coalesce(p_process_run_ids, '{}'::uuid[]))
        or t.process_run_stage_id = any(coalesce(p_process_run_stage_ids, '{}'::uuid[]))
      )
    order by t.id, t.sort_order nulls last, t.due_date nulls last
  ) task_rows;
$$;


--
-- Name: get_process_runtime_tasks_for_record(text, uuid, uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_runtime_tasks_for_record(p_module_id text, p_record_id uuid, p_task_ids uuid[] DEFAULT '{}'::uuid[], p_process_run_ids uuid[] DEFAULT '{}'::uuid[], p_process_run_stage_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(task_rows) order by task_rows.sort_order nulls last, task_rows.source_stage_sort_order nulls last, task_rows.due_date nulls last, task_rows.id), '[]'::jsonb)
  from (
    select distinct on (t.id)
      t.id,
      t.name,
      t.status,
      t.task_type,
      t.assignee_id,
      t.assignee_role_id,
      t.assignee_type,
      t.sort_order,
      t.process_group_id,
      t.process_run_id,
      t.process_run_stage_id,
      t.recurrence_info,
      t.source_module_id,
      t.source_record_id,
      t.source_template_id,
      t.source_stage_sort_order,
      t.process_node_key,
      t.process_lane_key,
      t.due_date,
      t.created_at,
      t.updated_at
    from public.tasks t
    where t.org_id = public.current_org_id()
      and (
        t.id = any(coalesce(p_task_ids, '{}'::uuid[]))
        or t.process_run_id = any(coalesce(p_process_run_ids, '{}'::uuid[]))
        or t.process_run_stage_id = any(coalesce(p_process_run_stage_ids, '{}'::uuid[]))
        or (t.source_module_id = p_module_id and t.source_record_id = p_record_id)
        or coalesce(t.recurrence_info -> 'process_links' ->> p_module_id, '') = p_record_id::text
        or (
          p_module_id = 'projects'
          and t.project_id = p_record_id
        )
        or (
          p_module_id = 'marketing_leads'
          and t.marketing_lead_id = p_record_id
        )
        or (
          p_module_id = 'products'
          and t.related_product = p_record_id
        )
        or (
          p_module_id = 'customers'
          and t.related_customer = p_record_id
        )
        or (
          p_module_id = 'suppliers'
          and t.related_supplier = p_record_id
        )
        or (
          p_module_id = 'production_orders'
          and t.related_production_order = p_record_id
        )
        or (
          p_module_id = 'invoices'
          and t.related_invoice = p_record_id
        )
        or (
          p_module_id = 'purchase_invoices'
          and t.purchase_invoice_id = p_record_id
        )
      )
    order by t.id, t.sort_order nulls last, t.source_stage_sort_order nulls last, t.due_date nulls last
  ) task_rows;
$$;


--
-- Name: get_process_work_items_v1(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_work_items_v1(p_module_specs jsonb DEFAULT '[]'::jsonb, p_limit integer DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_role_id uuid;
  v_permissions jsonb := '{}'::jsonb;
  v_allowed_role_ids uuid[] := '{}'::uuid[];
  v_allowed_role_texts text[] := '{}'::text[];
  v_allowed_user_ids uuid[] := '{}'::uuid[];
  v_allowed_user_texts text[] := '{}'::text[];
  v_limit integer := greatest(1, least(coalesce(p_limit, 15), 80));
  v_items jsonb := '[]'::jsonb;
  v_task_items jsonb := '[]'::jsonb;
  v_stage_items jsonb := '[]'::jsonb;
  v_module_items jsonb := '[]'::jsonb;
  v_spec jsonb;
  v_module_id text;
  v_table_name text;
  v_draft_field text;
  v_table_regclass regclass;
  v_module_perm jsonb;
  v_record_scope text;
  v_scope_user_texts text[] := '{}'::text[];
  v_scope_role_texts text[] := '{}'::text[];
  v_has_process_template_id boolean;
  v_has_updated_at boolean;
  v_has_created_at boolean;
  v_has_assignee_id boolean;
  v_has_assignee_role_id boolean;
  v_has_assignee_type boolean;
  v_record_assignee_condition text := 'false';
  v_sql text;
begin
  if v_org_id is null or v_user_id is null then
    return '[]'::jsonb;
  end if;

  select p.role_id, coalesce(r.permissions, '{}'::jsonb)
    into v_role_id, v_permissions
  from public.profiles p
  left join public.org_roles r
    on r.id = p.role_id
   and r.org_id = p.org_id
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if not found then
    return '[]'::jsonb;
  end if;

  v_allowed_role_ids := array_remove(array[v_role_id], null);
  if v_role_id is not null then
    select array(
      select distinct role_id
      from (
        select v_role_id as role_id
        union all
        select r.id
        from public.org_roles r
        where r.org_id = v_org_id
          and r.parent_id = v_role_id
      ) roles
      where role_id is not null
    )
    into v_allowed_role_ids;
  end if;

  select array(
    select distinct p.id
    from public.profiles p
    where p.org_id = v_org_id
      and (
        p.id = v_user_id
        or (p.role_id is not null and p.role_id = any(v_allowed_role_ids))
      )
  )
  into v_allowed_user_ids;

  v_allowed_role_texts := array(select item::text from unnest(coalesce(v_allowed_role_ids, '{}'::uuid[])) item);
  v_allowed_user_texts := array(select item::text from unnest(coalesce(v_allowed_user_ids, '{}'::uuid[])) item);

  with task_rows as (
    select
      t.id,
      t.production_line_id,
      t.source_template_id,
      t.process_group_id,
      t.recurrence_info,
      t.updated_at,
      t.created_at,
      coalesce(
        nullif(t.source_module_id, ''),
        case when t.project_id is not null then 'projects' end,
        case when t.marketing_lead_id is not null then 'marketing_leads' end,
        case when t.related_customer is not null then 'customers' end,
        case when t.related_supplier is not null then 'suppliers' end,
        case when t.related_invoice is not null then 'invoices' end,
        case when t.purchase_invoice_id is not null then 'purchase_invoices' end,
        case when t.related_production_order is not null then 'production_orders' end,
        nullif(t.related_to_module, '')
      ) as module_id,
      coalesce(
        t.source_record_id,
        t.project_id,
        t.marketing_lead_id,
        t.related_customer,
        t.related_supplier,
        t.related_invoice,
        t.purchase_invoice_id,
        t.related_production_order
      ) as record_id
    from public.tasks t
    where t.org_id = v_org_id
      and lower(coalesce(t.status, '')) not in ('done', 'completed', 'confirmed', 'final', 'settled', 'canceled')
      and (
        (t.assignee_type = 'user' and t.assignee_id = any(v_allowed_user_ids))
        or (t.assignee_type = 'role' and t.assignee_role_id = any(v_allowed_role_ids))
        or (t.assignee_type is null and t.assignee_id = any(v_allowed_user_ids))
        or (t.assignee_type is null and t.assignee_id = any(v_allowed_role_ids))
      )
    order by t.updated_at desc nulls last, t.created_at desc nulls last
    limit greatest(120, v_limit * 12)
  ),
  permitted_task_rows as (
    select tr.*
    from task_rows tr
    where tr.module_id is not null
      and tr.record_id is not null
      and lower(coalesce(v_permissions -> tr.module_id ->> 'view', 'true')) not in ('false', '0', 'no', 'off')
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'key', module_id || ':' || record_id::text || ':' || coalesce(nullif(process_group_id::text, ''), nullif(source_template_id::text, ''), 'default_process_group'),
        'moduleId', module_id,
        'recordId', record_id,
        'lineId', production_line_id,
        'groupId', process_group_id,
        'templateId', coalesce(source_template_id::text, recurrence_info -> 'process_group' ->> 'template_id'),
        'templateName', recurrence_info -> 'process_group' ->> 'template_name',
        'updatedAt', coalesce(updated_at, created_at),
        'reason', 'task'
      )
    ),
    '[]'::jsonb
  )
  into v_task_items
  from permitted_task_rows;

  v_items := v_items || coalesce(v_task_items, '[]'::jsonb);

  with stage_rows as (
    select
      r.module_id,
      r.record_id,
      r.template_id,
      r.process_group_id,
      r.process_name,
      coalesce(s.process_lane_key, s.metadata ->> 'process_lane_key') as line_id,
      coalesce(s.updated_at, r.updated_at, r.created_at) as updated_at
    from public.process_run_stages s
    join public.process_runs r
      on r.id = s.process_run_id
     and r.org_id = v_org_id
    where lower(coalesce(s.status, '')) not in ('done', 'completed', 'confirmed', 'final', 'settled', 'canceled')
      and (
        (s.assignee_user_id is not null and s.assignee_user_id = any(v_allowed_user_ids))
        or (s.assignee_role_id is not null and s.assignee_role_id = any(v_allowed_role_ids))
      )
    order by coalesce(s.updated_at, r.updated_at, r.created_at) desc nulls last
    limit greatest(120, v_limit * 12)
  ),
  permitted_stage_rows as (
    select sr.*
    from stage_rows sr
    where sr.module_id is not null
      and sr.record_id is not null
      and lower(coalesce(v_permissions -> sr.module_id ->> 'view', 'true')) not in ('false', '0', 'no', 'off')
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'key', module_id || ':' || record_id::text || ':' || coalesce(nullif(process_group_id::text, ''), nullif(template_id::text, ''), 'default_process_group'),
        'moduleId', module_id,
        'recordId', record_id,
        'lineId', null,
        'groupId', process_group_id,
        'templateId', template_id,
        'templateName', process_name,
        'updatedAt', updated_at,
        'reason', 'draft_stage'
      )
    ),
    '[]'::jsonb
  )
  into v_stage_items
  from permitted_stage_rows;

  v_items := v_items || coalesce(v_stage_items, '[]'::jsonb);

  for v_spec in
    select value
    from jsonb_array_elements(case when jsonb_typeof(p_module_specs) = 'array' then p_module_specs else '[]'::jsonb end)
  loop
    v_module_id := btrim(coalesce(v_spec ->> 'moduleId', ''));
    v_table_name := btrim(coalesce(v_spec ->> 'tableName', ''));
    v_draft_field := btrim(coalesce(v_spec ->> 'draftField', ''));

    if v_module_id !~ '^[a-zA-Z0-9_]+$'
       or v_table_name !~ '^[a-zA-Z0-9_]+$'
       or v_draft_field !~ '^[a-zA-Z0-9_]+$' then
      continue;
    end if;

    v_module_perm := coalesce(v_permissions -> v_module_id, '{}'::jsonb);
    if lower(coalesce(v_module_perm ->> 'view', 'true')) in ('false', '0', 'no', 'off') then
      continue;
    end if;
    v_record_scope := lower(coalesce(v_module_perm ->> 'record_scope', 'all'));
    if v_record_scope = 'own' then
      v_scope_user_texts := array[v_user_id::text];
      v_scope_role_texts := '{}'::text[];
    elsif v_record_scope = 'team' then
      v_scope_user_texts := array[v_user_id::text];
      v_scope_role_texts := case when v_role_id is null then '{}'::text[] else array[v_role_id::text] end;
    else
      v_scope_user_texts := v_allowed_user_texts;
      v_scope_role_texts := v_allowed_role_texts;
    end if;

    v_table_regclass := to_regclass(format('public.%I', v_table_name));
    if v_table_regclass is null then
      continue;
    end if;

    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = v_table_name and column_name = 'process_template_id'
    ) into v_has_process_template_id;
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = v_table_name and column_name = 'updated_at'
    ) into v_has_updated_at;
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = v_table_name and column_name = 'created_at'
    ) into v_has_created_at;
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = v_table_name and column_name = 'assignee_id'
    ) into v_has_assignee_id;
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = v_table_name and column_name = 'assignee_role_id'
    ) into v_has_assignee_role_id;
    select exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = v_table_name and column_name = 'assignee_type'
    ) into v_has_assignee_type;

    if not exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = v_table_name and column_name in ('id', 'org_id', v_draft_field)
      group by table_name
      having count(distinct column_name) = 3
    ) then
      continue;
    end if;

    v_record_assignee_condition := 'false';
    if v_has_assignee_type and v_has_assignee_id then
      v_record_assignee_condition := v_record_assignee_condition || format(
        ' or (%1$I = ''user'' and %2$I::text = any($2)) or (%1$I is null and %2$I::text = any($2))',
        'assignee_type',
        'assignee_id'
      );
    elsif v_has_assignee_id then
      v_record_assignee_condition := v_record_assignee_condition || format(' or (%I::text = any($2))', 'assignee_id');
    end if;

    if v_has_assignee_type and v_has_assignee_role_id then
      v_record_assignee_condition := v_record_assignee_condition || format(
        ' or (%1$I = ''role'' and %2$I::text = any($3))',
        'assignee_type',
        'assignee_role_id'
      );
    elsif v_has_assignee_role_id then
      v_record_assignee_condition := v_record_assignee_condition || format(' or (%I::text = any($3))', 'assignee_role_id');
    end if;

    v_sql := format($fmt$
      with record_rows as (
        select
          id,
          %1$s as template_id,
          %2$s as updated_at,
          %3$I as draft_rows
        from %4$s
        where org_id = $1
          and %3$I is not null
          and jsonb_typeof(%3$I) = 'array'
          and jsonb_array_length(%3$I) > 0
          and (
            $4 = 'all'
            or (%5$s)
            or exists (
              select 1
              from jsonb_array_elements(%3$I) stage
              where coalesce(stage ->> 'default_assignee_id', stage ->> 'assignee_id', stage -> 'metadata' ->> 'default_assignee_id') = any($2)
                 or coalesce(stage ->> 'default_assignee_role_id', stage ->> 'assignee_role_id', stage -> 'metadata' ->> 'default_assignee_role_id') = any($3)
            )
          )
        order by %2$s desc nulls last
        limit $5
      ),
      expanded as (
        select
          id,
          template_id,
          updated_at,
          stage,
          coalesce(
            nullif(stage ->> 'process_group_id', ''),
            nullif(stage ->> 'source_template_id', ''),
            nullif(template_id::text, ''),
            'default_process_group'
          ) as group_key
        from record_rows
        cross join lateral jsonb_array_elements(draft_rows) stage
      ),
      grouped as (
        select
          id,
          max(template_id::text) as template_id,
          max(updated_at) as updated_at,
          group_key,
          max(nullif(stage ->> 'process_group_id', '')) as group_id,
          max(nullif(stage ->> 'source_template_id', '')) as stage_template_id,
          max(nullif(stage ->> 'source_template_name', '')) as template_name
        from expanded
        group by id, group_key
      )
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'key', $6 || ':' || id::text || ':' || group_key,
            'moduleId', $6,
            'recordId', id,
            'lineId', null,
            'groupId', group_id,
            'templateId', coalesce(stage_template_id, template_id),
            'templateName', template_name,
            'updatedAt', updated_at,
            'reason', 'record'
          )
        ),
        '[]'::jsonb
      )
      from grouped
    $fmt$,
      case when v_has_process_template_id then 'process_template_id' else 'null::uuid' end,
      case
        when v_has_updated_at then 'updated_at'
        when v_has_created_at then 'created_at'
        else 'now()'
      end,
      v_draft_field,
      v_table_regclass,
      v_record_assignee_condition
    );

    execute v_sql
      into v_module_items
      using v_org_id, v_scope_user_texts, v_scope_role_texts, v_record_scope, greatest(40, v_limit * 4), v_module_id;

    v_items := v_items || coalesce(v_module_items, '[]'::jsonb);
  end loop;

  return coalesce((
    with raw_items as (
      select value as item
      from jsonb_array_elements(v_items)
    ),
    normalized as (
      select
        item,
        item ->> 'key' as key,
        case
          when nullif(item ->> 'templateId', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            then nullif(item ->> 'templateId', '')::uuid
          else null
        end as template_id,
        nullif(item ->> 'updatedAt', '')::timestamptz as updated_at
      from raw_items
      where nullif(item ->> 'moduleId', '') is not null
        and nullif(item ->> 'recordId', '') is not null
        and nullif(item ->> 'key', '') is not null
    ),
    deduped as (
      select distinct on (key)
        item,
        template_id,
        updated_at
      from normalized
      order by key, updated_at desc nulls last
    ),
    sorted as (
      select
        d.item,
        d.updated_at,
        pt.name as template_name
      from deduped d
      left join public.process_templates pt
        on pt.id = d.template_id
       and pt.org_id = v_org_id
      order by d.updated_at desc nulls last
      limit v_limit + 1
    )
    select jsonb_agg(
      jsonb_set(
        item,
        '{templateName}',
        coalesce(to_jsonb(coalesce(nullif(item ->> 'templateName', ''), template_name)), 'null'::jsonb)
      )
      order by updated_at desc nulls last
    )
    from sorted
  ), '[]'::jsonb);
end;
$_$;


--
-- Name: get_process_work_items_v2(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_work_items_v2(p_module_specs jsonb DEFAULT '[]'::jsonb, p_limit integer DEFAULT 15) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_limit integer := greatest(1, least(coalesce(p_limit, 15), 80));
begin
  if v_org_id is null or auth.uid() is null then
    return '[]'::jsonb;
  end if;

  return coalesce((
    with raw_items as (
      select value as item
      from jsonb_array_elements(
        public.get_process_work_items_v1(
          p_module_specs,
          least(greatest(v_limit * 6, 30), 80)
        )
      )
    ),
    linked_tasks as (
      select
        t.process_group_id::text as process_group_id,
        coalesce(
          nullif(t.source_module_id, ''),
          case when t.project_id is not null then 'projects' end,
          case when t.marketing_lead_id is not null then 'marketing_leads' end,
          case when t.related_customer is not null then 'customers' end,
          case when t.related_supplier is not null then 'suppliers' end,
          case when t.related_invoice is not null then 'invoices' end,
          case when t.purchase_invoice_id is not null then 'purchase_invoices' end,
          case when t.related_production_order is not null then 'production_orders' end,
          nullif(t.related_to_module, '')
        ) as source_module_id,
        coalesce(
          t.source_record_id,
          t.project_id,
          t.marketing_lead_id,
          t.related_customer,
          t.related_supplier,
          t.related_invoice,
          t.purchase_invoice_id,
          t.related_production_order
        )::text as source_record_id,
        t.recurrence_info
      from public.tasks t
      where t.org_id = v_org_id
        and t.process_group_id is not null
    ),
    item_links as (
      select
        raw.item ->> 'key' as item_key,
        coalesce(jsonb_object_agg(link.module_id, link.record_id) filter (where link.module_id is not null and link.record_id is not null), '{}'::jsonb) as links
      from raw_items raw
      left join linked_tasks task
        on task.process_group_id = nullif(raw.item ->> 'groupId', '')
       and nullif(raw.item ->> 'groupId', '') <> nullif(raw.item ->> 'templateId', '')
      left join lateral jsonb_each_text(
        (
          case
            when jsonb_typeof(task.recurrence_info -> 'process_links') = 'object'
              then task.recurrence_info -> 'process_links'
            else '{}'::jsonb
          end
        ) || case
          when task.source_module_id is not null and task.source_record_id is not null
            then jsonb_build_object(task.source_module_id, task.source_record_id)
          else '{}'::jsonb
        end
      ) as link(module_id, record_id) on true
      group by raw.item ->> 'key'
    ),
    enriched as (
      select
        jsonb_set(
          jsonb_set(
            raw.item,
            '{processLinks}',
            coalesce(item_links.links, '{}'::jsonb)
              || jsonb_build_object(raw.item ->> 'moduleId', raw.item ->> 'recordId'),
            true
          ),
          '{key}',
          to_jsonb(
            case
              when nullif(raw.item ->> 'groupId', '') is not null
               and nullif(raw.item ->> 'groupId', '') <> nullif(raw.item ->> 'templateId', '')
                then 'group:' || (raw.item ->> 'groupId')
              else raw.item ->> 'key'
            end
          ),
          true
        ) as item,
        case
          when nullif(raw.item ->> 'groupId', '') is not null
           and nullif(raw.item ->> 'groupId', '') <> nullif(raw.item ->> 'templateId', '')
            then 'group:' || (raw.item ->> 'groupId')
          else raw.item ->> 'key'
        end as process_identity,
        nullif(raw.item ->> 'updatedAt', '')::timestamptz as updated_at
      from raw_items raw
      left join item_links on item_links.item_key = raw.item ->> 'key'
    ),
    deduped as (
      select distinct on (process_identity) item, updated_at
      from enriched
      where process_identity is not null
      order by process_identity, updated_at desc nulls last
    )
    select jsonb_agg(item order by updated_at desc nulls last)
    from (
      select item, updated_at
      from deduped
      order by updated_at desc nulls last
      limit v_limit + 1
    ) limited
  ), '[]'::jsonb);
end;
$$;


--
-- Name: get_process_work_items_v3(jsonb, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_process_work_items_v3(p_module_specs jsonb DEFAULT '[]'::jsonb, p_limit integer DEFAULT 15, p_status text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_role_id uuid;
  v_limit integer := greatest(1, least(coalesce(p_limit, 15), 80));
  v_status text := case lower(btrim(coalesce(p_status, 'all')))
    when 'in_progress' then 'in_progress'
    when 'completed' then 'completed'
    else 'all'
  end;
  v_module_specs jsonb := case
    when jsonb_typeof(p_module_specs) = 'array' then p_module_specs
    else '[]'::jsonb
  end;
  v_spec jsonb;
  v_module_id text;
  v_table_name text;
  v_draft_field text;
  v_table_regclass regclass;
  v_has_draft_field boolean;
  v_has_org_id boolean;
  v_has_organization_id boolean;
  v_has_updated_at boolean;
  v_has_created_at boolean;
  v_has_process_template_id boolean;
  v_org_filter_expression text;
  v_updated_at_expression text;
  v_template_id_expression text;
  v_items jsonb := '[]'::jsonb;
  v_module_items jsonb := '[]'::jsonb;
  v_sql text;
begin
  if v_org_id is null or v_user_id is null then
    return '[]'::jsonb;
  end if;

  select p.role_id
  into v_role_id
  from public.profiles p
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if not found then
    return '[]'::jsonb;
  end if;

  with matched_runs as (
    select
      r.id,
      r.module_id,
      r.record_id,
      r.process_group_id,
      r.template_id,
      r.process_name,
      coalesce(max(s.updated_at), r.updated_at, r.created_at) as updated_at,
      case
        when lower(coalesce(r.status, '')) in ('done', 'completed', 'confirmed', 'final', 'settled')
          or (
            count(s.id) > 0
            and bool_and(lower(coalesce(s.status, 'todo')) in ('done', 'completed', 'confirmed', 'final', 'settled'))
          )
          then 'completed'
        else 'in_progress'
      end as process_status
    from public.process_runs r
    join public.process_run_stages s
      on s.process_run_id = r.id
    left join public.tasks stage_task
      on stage_task.id = s.task_id
     and stage_task.org_id = v_org_id
    where r.org_id = v_org_id
      and exists (
        select 1
        from jsonb_array_elements(v_module_specs) spec
        where spec ->> 'moduleId' = r.module_id
      )
      and (
        s.assignee_user_id = v_user_id
        or (v_role_id is not null and s.assignee_role_id = v_role_id)
        or s.created_by = v_user_id
        or stage_task.created_by = v_user_id
      )
    group by r.id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', 'group:' || id::text,
    'moduleId', module_id,
    'recordId', record_id,
    'lineId', null,
    'groupId', coalesce(process_group_id::text, id::text),
    'templateId', template_id,
    'templateName', process_name,
    'updatedAt', updated_at,
    'processStatus', process_status,
    'reason', 'draft_stage',
    'processLinks', jsonb_build_object(module_id, record_id)
  )), '[]'::jsonb)
  into v_items
  from matched_runs
  where v_status = 'all' or process_status = v_status;

  with matched_task_groups as (
    select
      coalesce(
        nullif(t.source_module_id, ''),
        case when t.project_id is not null then 'projects' end,
        case when t.marketing_lead_id is not null then 'marketing_leads' end,
        case when t.related_customer is not null then 'customers' end,
        case when t.related_supplier is not null then 'suppliers' end,
        case when t.related_invoice is not null then 'invoices' end,
        case when t.purchase_invoice_id is not null then 'purchase_invoices' end,
        case when t.related_production_order is not null then 'production_orders' end,
        nullif(t.related_to_module, '')
      ) as module_id,
      coalesce(
        t.source_record_id,
        t.project_id,
        t.marketing_lead_id,
        t.related_customer,
        t.related_supplier,
        t.related_invoice,
        t.purchase_invoice_id,
        t.related_production_order
      ) as record_id,
      coalesce(nullif(t.process_group_id::text, ''), nullif(t.source_template_id::text, '')) as group_id,
      max(t.source_template_id::text) as template_id,
      max(t.recurrence_info -> 'process_group' ->> 'template_name') as template_name,
      max(coalesce(t.updated_at, t.created_at)) as updated_at,
      case
        when bool_and(lower(coalesce(t.status, 'todo')) in ('done', 'completed', 'confirmed', 'final', 'settled'))
          then 'completed'
        else 'in_progress'
      end as process_status,
      bool_or(
        (t.assignee_type = 'user' and t.assignee_id = v_user_id)
        or (t.assignee_type = 'role' and v_role_id is not null and t.assignee_role_id = v_role_id)
        or (t.assignee_type is null and t.assignee_id = v_user_id)
        or t.created_by = v_user_id
      ) as has_matching_stage
    from public.tasks t
    where t.org_id = v_org_id
      and (t.process_group_id is not null or t.source_template_id is not null)
    group by 1, 2, 3
  ), task_items as (
    select *
    from matched_task_groups
    where module_id is not null
      and record_id is not null
      and group_id is not null
      and has_matching_stage
      and exists (
        select 1
        from jsonb_array_elements(v_module_specs) spec
        where spec ->> 'moduleId' = module_id
      )
  )
  select v_items || coalesce(jsonb_agg(jsonb_build_object(
    'key', 'group:' || group_id,
    'moduleId', module_id,
    'recordId', record_id,
    'lineId', null,
    'groupId', group_id,
    'templateId', template_id,
    'templateName', template_name,
    'updatedAt', updated_at,
    'processStatus', process_status,
    'reason', 'task',
    'processLinks', jsonb_build_object(module_id, record_id)
  )), '[]'::jsonb)
  into v_items
  from task_items
  where v_status = 'all' or process_status = v_status;

  for v_spec in select value from jsonb_array_elements(v_module_specs)
  loop
    v_module_id := btrim(coalesce(v_spec ->> 'moduleId', ''));
    v_table_name := btrim(coalesce(v_spec ->> 'tableName', ''));
    v_draft_field := btrim(coalesce(v_spec ->> 'draftField', ''));

    if v_module_id !~ '^[a-zA-Z0-9_]+$'
      or v_table_name !~ '^[a-zA-Z0-9_]+$'
      or v_draft_field !~ '^[a-zA-Z0-9_]+$' then
      continue;
    end if;

    v_table_regclass := to_regclass(format('public.%I', v_table_name));
    if v_table_regclass is null then
      continue;
    end if;

    select
      bool_or(column_name = v_draft_field),
      bool_or(column_name = 'org_id'),
      bool_or(column_name = 'organization_id'),
      bool_or(column_name = 'updated_at'),
      bool_or(column_name = 'created_at'),
      bool_or(column_name = 'process_template_id')
    into
      v_has_draft_field,
      v_has_org_id,
      v_has_organization_id,
      v_has_updated_at,
      v_has_created_at,
      v_has_process_template_id
    from information_schema.columns
    where table_schema = 'public'
      and table_name = v_table_name;

    if not coalesce(v_has_draft_field, false) then
      continue;
    end if;

    if coalesce(v_has_org_id, false) then
      v_org_filter_expression := 'r.org_id = $1';
    elsif coalesce(v_has_organization_id, false) then
      v_org_filter_expression := 'r.organization_id = $1';
    else
      continue;
    end if;

    v_updated_at_expression := case
      when coalesce(v_has_updated_at, false) and coalesce(v_has_created_at, false) then 'coalesce(r.updated_at, r.created_at)'
      when coalesce(v_has_updated_at, false) then 'r.updated_at'
      when coalesce(v_has_created_at, false) then 'r.created_at'
      else 'now()'
    end;

    v_template_id_expression := case
      when coalesce(v_has_process_template_id, false) then 'r.process_template_id::text'
      else 'null::text'
    end;

    v_sql := format($query$
      with expanded as (
        select
          r.id as record_id,
          %3$s as template_id,
          %4$s as updated_at,
          stage,
          coalesce(
            nullif(stage ->> 'process_group_id', ''),
            nullif(stage ->> 'source_template_id', ''),
            nullif(%3$s, ''),
            'default_process_group'
          ) as group_id
        from %1$s r
        cross join lateral jsonb_array_elements(to_jsonb(r.%2$I)) stage
        where %5$s
          and r.%2$I is not null
          and jsonb_typeof(to_jsonb(r.%2$I)) = 'array'
      ), grouped as (
        select
          record_id,
          group_id,
          max(template_id) as template_id,
          max(nullif(stage ->> 'source_template_name', '')) as template_name,
          max(updated_at) as updated_at,
          case
            when bool_and(lower(coalesce(stage ->> 'status', 'todo')) in ('done', 'completed', 'confirmed', 'final', 'settled'))
              then 'completed'
            else 'in_progress'
          end as process_status,
          bool_or(
            coalesce(
              stage ->> 'default_assignee_id',
              stage ->> 'assignee_id',
              stage ->> 'assignee_user_id',
              stage -> 'metadata' ->> 'default_assignee_id',
              stage -> 'metadata' ->> 'assignee_id',
              stage -> 'metadata' ->> 'assignee_user_id'
            ) = $2
            or (
              $3 is not null
              and coalesce(
                stage ->> 'default_assignee_role_id',
                stage ->> 'assignee_role_id',
                stage -> 'metadata' ->> 'default_assignee_role_id',
                stage -> 'metadata' ->> 'assignee_role_id'
              ) = $3
            )
            or coalesce(
              stage ->> 'created_by',
              stage ->> 'creator_id',
              stage -> 'metadata' ->> 'created_by',
              stage -> 'metadata' ->> 'creator_id'
            ) = $2
          ) as has_matching_stage
        from expanded
        group by record_id, group_id
      )
      select coalesce(jsonb_agg(jsonb_build_object(
        'key', 'record:' || $4 || ':' || record_id::text || ':' || group_id,
        'moduleId', $4,
        'recordId', record_id,
        'lineId', null,
        'groupId', group_id,
        'templateId', template_id,
        'templateName', template_name,
        'updatedAt', updated_at,
        'processStatus', process_status,
        'reason', 'draft_stage',
        'processLinks', jsonb_build_object($4, record_id)
      )), '[]'::jsonb)
      from grouped
      where has_matching_stage
        and ($5 = 'all' or process_status = $5)
    $query$, v_table_regclass, v_draft_field, v_template_id_expression, v_updated_at_expression, v_org_filter_expression);

    execute v_sql
      into v_module_items
      using v_org_id, v_user_id::text, v_role_id::text, v_module_id, v_status;
    v_items := v_items || coalesce(v_module_items, '[]'::jsonb);
  end loop;

  return coalesce((
    with raw_items as (
      select value as item
      from jsonb_array_elements(v_items)
    ), normalized as (
      select
        item,
        coalesce(nullif(item ->> 'groupId', ''), item ->> 'key') as identity,
        nullif(item ->> 'updatedAt', '')::timestamptz as updated_at,
        case when item ->> 'reason' = 'draft_stage' and item ->> 'key' like 'group:%' then 0
             when item ->> 'reason' = 'task' then 1
             else 2 end as source_priority
      from raw_items
      where nullif(item ->> 'moduleId', '') is not null
        and nullif(item ->> 'recordId', '') is not null
    ), deduped as (
      select distinct on (identity) item, updated_at
      from normalized
      order by identity, source_priority, updated_at desc nulls last
    )
    select jsonb_agg(item order by updated_at desc nulls last)
    from (
      select item, updated_at
      from deduped
      order by updated_at desc nulls last
      limit v_limit + 1
    ) limited
  ), '[]'::jsonb);
end;
$_$;


--
-- Name: get_product_sales_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_sales_summary(p_org_id uuid, p_product_id uuid) RETURNS TABLE(invoice_count bigint, total_sold_quantity numeric, total_sold_amount numeric, invoice_revision text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  with matching_invoices as (
    select i.id, i.status, i.updated_at, i."invoiceItems"
    from public.invoices i
    where i.org_id = public.current_org_id() and i.org_id = p_org_id
      and public.current_user_can_module_field('products', 'view')
      and public.current_user_can_module_field('invoices', 'view', 'invoiceItems')
      and i."invoiceItems" @> jsonb_build_array(jsonb_build_object('product_id', p_product_id))
  ), sales_lines as (
    select i.id, item.value
    from matching_invoices i
    cross join lateral jsonb_array_elements(i."invoiceItems") item(value)
    -- Matches the sales statuses used by the operational financial overview.
    where i.status in ('confirmed', 'final', 'settled', 'completed')
      and item.value->>'product_id' = p_product_id::text
  )
  select case when public.current_user_can_module_field('products', 'view', 'invoice_count')
      then count(distinct id) end,
    case when public.current_user_can_module_field('products', 'view', 'total_sold_quantity') then
      coalesce(sum(case when value->>'quantity' ~ '^-?[0-9]+(\.[0-9]+)?$' then (value->>'quantity')::numeric end), 0) end,
    case when public.current_user_can_module_field('products', 'view', 'total_sold_amount') then
      coalesce(sum(case when value->>'total_price' ~ '^-?[0-9]+(\.[0-9]+)?$' then (value->>'total_price')::numeric end), 0) end,
    (select concat(count(*), ':', max(updated_at)) from matching_invoices)
  from sales_lines
  having p_org_id = public.current_org_id()
    and public.current_user_can_module_field('products', 'view')
    and public.current_user_can_module_field('invoices', 'view', 'invoiceItems');
$_$;


--
-- Name: get_public_branding(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_branding(p_hostname text DEFAULT NULL::text) RETURNS TABLE(org_id uuid, company_settings jsonb, branding_settings jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_hostname text := lower(trim(coalesce(p_hostname, '')));
  v_org_id uuid;
  v_tenant_context jsonb;
  v_internal_candidate_count integer := 0;
  v_is_shared_host boolean := v_hostname in (
    'tazesystem.ir',
    'www.tazesystem.ir',
    'app.tazesystem.ir',
    'kalam.tazesystem.ir',
    'kalamapp.ir',
    'www.kalamapp.ir'
  );
begin
  if v_hostname <> '' then
    if v_hostname in ('kalam.tazesystem.ir', 'kalamapp.ir', 'www.kalamapp.ir') then
      -- Resolve the internal organization without relying on an org ID or on
      -- admin permission alone, which the SaaS provider also has.
      select count(*), (array_agg(candidate.org_id))[1]
        into v_internal_candidate_count, v_org_id
      from (
        select distinct cs.org_id
        from public.company_settings cs
        join public.org_roles r
          on r.org_id = cs.org_id
        left join public.saas_org_settings s on s.org_id = cs.org_id
        where cs.org_id is not null
          and coalesce(s.is_billing_provider, false) = false
          and nullif(trim(coalesce(s.resolved_host, '')), '') is null
          and (
            lower(coalesce(r.permissions->'__saas_admin'->>'view', 'false')) = 'true'
            or lower(coalesce(r.permissions->'__saas_admin'->>'edit', 'false')) = 'true'
          )
      ) candidate;

      if v_internal_candidate_count <> 1 then
        return;
      end if;
    else
      v_tenant_context := public.resolve_saas_org_context(null, null, v_hostname);
      if v_tenant_context is not null and coalesce(v_tenant_context->>'org_id', '') <> '' then
        v_org_id := (v_tenant_context->>'org_id')::uuid;
      end if;
    end if;
  end if;

  if v_org_id is null and not v_is_shared_host then
    return;
  end if;

  return query
  with company_row as (
    -- Public branding and contact details only. Internal company identifiers,
    -- signatory images and operational settings must not reach anonymous users.
    select jsonb_build_object(
      'company_name', cs.company_name,
      'company_full_name', cs.company_full_name,
      'company_name_en', cs.company_name_en,
      'trade_name', cs.trade_name,
      'brand_palette_key', cs.brand_palette_key,
      'logo_url', cs.logo_url,
      'icon_url', cs.icon_url,
      'currency_code', cs.currency_code,
      'currency_label', cs.currency_label,
      'slogan', cs.slogan,
      'website', cs.website,
      'email', cs.email,
      'mobile', cs.mobile,
      'phone', cs.phone,
      'address', cs.address,
      'instagram_id', cs.instagram_id,
      'telegram_id', cs.telegram_id,
      'youtube_url', cs.youtube_url,
      'whatsapp_number', cs.whatsapp_number,
      'eitaa_id', cs.eitaa_id,
      'rubika_id', cs.rubika_id,
      'bale_id', cs.bale_id
    ) as payload
    from public.company_settings cs
    where (
      (v_org_id is null and cs.org_id is null)
      or cs.org_id = v_org_id
    )
    order by cs.updated_at desc nulls last, cs.created_at desc nulls last
    limit 1
  ),
  branding_row as (
    select coalesce(to_jsonb(i.settings), '{}'::jsonb) as payload
    from public.integration_settings i
    where i.connection_type = 'ui_theme'
      and coalesce(i.provider, '') = 'branding'
      and (
        (v_org_id is null and i.org_id is null)
        or i.org_id = v_org_id
      )
    order by i.updated_at desc nulls last, i.created_at desc nulls last
    limit 1
  )
  select
    v_org_id,
    coalesce(
      (select payload from company_row),
      (select jsonb_build_object('company_full_name', o.name) from public.organizations o where o.id = v_org_id),
      '{}'::jsonb
    ),
    coalesce((select payload from branding_row), '{}'::jsonb);
end;
$$;


--
-- Name: get_public_content_calendar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_content_calendar(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_calendar public.content_calendars%rowtype;
  v_company jsonb;
  v_projects jsonb;
  v_tasks jsonb;
begin
  select *
    into v_calendar
    from public.content_calendars
   where public_slug = btrim(p_token)
     and is_public = true
     and status <> 'archived'
   limit 1;

  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;

  select to_jsonb(cs)
    into v_company
    from public.company_settings cs
   where cs.org_id = v_calendar.org_id
   limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', p.id,
    'name', p.name,
    'status', p.status,
    'start_date', p.start_date,
    'due_date', p.due_date
  ) order by p.due_date), '[]'::jsonb)
    into v_projects
    from public.projects p
   where p.org_id = v_calendar.org_id
     and p.content_calendar_id = v_calendar.id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', t.id,
    'name', t.name,
    'status', t.status,
    'priority', t.priority,
    'start_date', t.start_date,
    'due_date', t.due_date,
    'completed_at', t.completed_at,
    'project_id', t.project_id,
    'content_type', t.content_type,
    'status_presentation', (
      select jsonb_build_object('label', status_option->>'label', 'color', status_option->>'color')
      from jsonb_array_elements(case
        when jsonb_typeof(t.recurrence_info->'process_task_status_options') = 'array'
          then t.recurrence_info->'process_task_status_options'
        else '[]'::jsonb end) as status_option
      where status_option->>'value' = t.status::text
        and nullif(btrim(status_option->>'label'), '') is not null
      limit 1
    ),
    'public_fields', coalesce((
      select jsonb_agg(jsonb_build_object(
        'label', coalesce(field_definition->'labels'->>'fa', field_definition->>'labelFa', field_definition->>'key', 'فیلد فعالیت'),
        'value', case jsonb_typeof(field_value)
          when 'object' then to_jsonb(coalesce(field_value->>'label', field_value->>'name', field_value->>'title', '—'))
          else field_value
        end
      ) order by field_position)
      from jsonb_array_elements(coalesce(t.recurrence_info->'process_task_custom_fields', '[]'::jsonb)) with ordinality as custom_field(field_definition, field_position)
      cross join lateral (select coalesce(t.recurrence_info->'process_task_custom_field_values'->(field_definition->>'key'), 'null'::jsonb) as field_value) value_source
      where coalesce(field_definition->>'show_in_content_calendar', field_definition->>'showInContentCalendar', 'false') in ('true', '1')
    ), '[]'::jsonb)
  ) order by t.due_date), '[]'::jsonb)
    into v_tasks
    from public.tasks t
   where t.org_id = v_calendar.org_id
     and (
       t.content_calendar_id = v_calendar.id
       or t.project_id in (
         select id
           from public.projects
          where org_id = v_calendar.org_id
            and content_calendar_id = v_calendar.id
       )
     );

  return jsonb_build_object(
    'calendar', jsonb_build_object(
      'name', v_calendar.name,
      'description', v_calendar.description,
      'image_url', v_calendar.image_url,
      'start_date', v_calendar.start_date,
      'end_date', v_calendar.end_date,
      'public_link', v_calendar.public_link
    ),
    'company', jsonb_build_object('company_settings', coalesce(v_company, '{}'::jsonb)),
    'projects', v_projects,
    'tasks', v_tasks
  );
end;
$$;


--
-- Name: get_public_delivery_form(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_delivery_form(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_delivery_id uuid;
  v_delivery jsonb := '{}'::jsonb;
  v_items jsonb := '[]'::jsonb;
  v_files jsonb := '[]'::jsonb;
  v_branding jsonb := '{}'::jsonb;
  v_delivered_phones jsonb := '[]'::jsonb;
  v_received_phones jsonb := '[]'::jsonb;
begin
  v_org_id := public._resolve_org_for_public_delivery(p_code);
  if v_org_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  select
    d.id,
    jsonb_strip_nulls(jsonb_build_object(
      'system_code', d.system_code,
      'public_link', d.public_link,
      'name', d.name,
      'form_type', d.form_type,
      'status', d.status,
      'delivery_date', d.delivery_date,
      'location_text', d.location_text,
      'notes', d.notes,
      'delivered_by_name', case d.delivered_by_type
        when 'customer' then coalesce(nullif(c_del.full_name, ''), nullif(c_del.business_name, ''), nullif(c_del.legal_name, ''))
        when 'supplier' then coalesce(nullif(s_del.business_name, ''), nullif(trim(concat_ws(' ', s_del.first_name, s_del.last_name)), ''))
        when 'other' then nullif(d.external_delivered_by, '')
        else coalesce(nullif(e_del.full_name, ''), nullif(trim(concat_ws(' ', e_del.first_name, e_del.last_name)), ''), nullif(p_del.full_name, ''))
      end,
      'received_by_name', case d.received_by_type
        when 'customer' then coalesce(nullif(c_rec.full_name, ''), nullif(c_rec.business_name, ''), nullif(c_rec.legal_name, ''))
        when 'supplier' then coalesce(nullif(s_rec.business_name, ''), nullif(trim(concat_ws(' ', s_rec.first_name, s_rec.last_name)), ''))
        when 'other' then nullif(d.external_received_by, '')
        else coalesce(nullif(e_rec.full_name, ''), nullif(trim(concat_ws(' ', e_rec.first_name, e_rec.last_name)), ''), nullif(p_rec.full_name, ''))
      end,
      'delivered_by_confirmed_at', d.delivered_by_confirmed_at,
      'received_by_confirmed_at', d.received_by_confirmed_at,
      'delivered_by_confirmer_name', d.delivered_by_confirmer_name,
      'received_by_confirmer_name', d.received_by_confirmer_name
    )),
    coalesce(d.items, '[]'::jsonb),
    case d.delivered_by_type
      when 'customer' then public._delivery_public_phone_options(c_del.mobile_1, c_del.mobile_2, c_del.assistant_phone)
      when 'supplier' then public._delivery_public_phone_options(s_del.mobile_1, s_del.mobile_2, null)
      when 'other' then public._delivery_public_phone_options(d.external_delivered_by_phone, null, null)
      else public._delivery_public_phone_options(e_del.mobile_1, e_del.mobile_2, p_del.mobile)
    end,
    case d.received_by_type
      when 'customer' then public._delivery_public_phone_options(c_rec.mobile_1, c_rec.mobile_2, c_rec.assistant_phone)
      when 'supplier' then public._delivery_public_phone_options(s_rec.mobile_1, s_rec.mobile_2, null)
      when 'other' then public._delivery_public_phone_options(d.external_received_by_phone, null, null)
      else public._delivery_public_phone_options(e_rec.mobile_1, e_rec.mobile_2, p_rec.mobile)
    end
  into v_delivery_id, v_delivery, v_items, v_delivered_phones, v_received_phones
  from public.delivery_forms d
  left join public.employees e_del on e_del.id = d.delivered_by_employee_id and e_del.org_id = d.org_id
  left join public.employees e_rec on e_rec.id = d.received_by_employee_id and e_rec.org_id = d.org_id
  left join public.profiles p_del on p_del.id = d.delivered_by_id and p_del.org_id = d.org_id
  left join public.profiles p_rec on p_rec.id = d.received_by_id and p_rec.org_id = d.org_id
  left join public.customers c_del on c_del.id = d.delivered_by_customer_id and c_del.org_id = d.org_id
  left join public.customers c_rec on c_rec.id = d.received_by_customer_id and c_rec.org_id = d.org_id
  left join public.suppliers s_del on s_del.id = d.delivered_by_supplier_id and s_del.org_id = d.org_id
  left join public.suppliers s_rec on s_rec.id = d.received_by_supplier_id and s_rec.org_id = d.org_id
  where d.org_id = v_org_id
    and (d.public_slug = p_code or d.public_token = p_code)
  limit 1;

  if v_delivery_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', f.id,
        'url', f.url,
        'name', f.name,
        'file_type', f.file_type,
        'mime_type', f.mime_type,
        'sort_order', f.sort_order
      )
      order by f.sort_order, f.created_at
    ),
    '[]'::jsonb
  )
  into v_files
  from (
    select
      rf.id::text as id,
      rf.file_url as url,
      coalesce(nullif(rf.file_name, ''), 'فایل تحویل') as name,
      coalesce(nullif(rf.file_type, ''), 'file') as file_type,
      rf.mime_type,
      coalesce(rf.sort_order, 0) as sort_order,
      rf.created_at
    from public.record_files rf
    where rf.org_id = v_org_id
      and rf.module_id = 'delivery_forms'
      and rf.record_id::text = v_delivery_id::text
      and nullif(btrim(coalesce(rf.file_url, '')), '') is not null

    union all

    select
      fe.id::text,
      coalesce(nullif(fa.target_url, ''), fa.metadata->>'publicUrl', fa.metadata->>'public_url'),
      coalesce(nullif(fe.entry_name, ''), nullif(fa.display_name, ''), 'فایل تحویل'),
      coalesce(nullif(fa.file_type, ''), 'file'),
      fa.mime_type,
      coalesce(fe.sort_order, 0),
      fe.created_at
    from public.file_entries fe
    join public.file_assets fa on fa.id = fe.asset_id and fa.org_id = fe.org_id
    where fe.org_id = v_org_id
      and fe.module_id = 'delivery_forms'
      and fe.record_id = v_delivery_id
      and coalesce(fe.is_deleted, false) = false
      and nullif(btrim(coalesce(fa.target_url, fa.metadata->>'publicUrl', fa.metadata->>'public_url', '')), '') is not null
  ) f;

  with company_row as (
    select jsonb_strip_nulls(jsonb_build_object(
      'company_full_name', cs.company_full_name,
      'trade_name', cs.trade_name,
      'logo_url', cs.logo_url,
      'brand_palette_key', cs.brand_palette_key
    )) as payload
    from public.company_settings cs
    where cs.org_id = v_org_id
    order by cs.updated_at desc nulls last, cs.created_at desc nulls last
    limit 1
  ),
  branding_row as (
    select jsonb_strip_nulls(jsonb_build_object(
      'brand_name', i.settings->>'brand_name',
      'brandName', i.settings->>'brandName',
      'short_name', i.settings->>'short_name',
      'shortName', i.settings->>'shortName',
      'primary_color', i.settings->>'primary_color',
      'palette_key', i.settings->>'palette_key'
    )) as payload
    from public.integration_settings i
    where i.org_id = v_org_id
      and i.connection_type = 'ui_theme'
      and coalesce(i.provider, '') = 'branding'
      and i.is_active = true
    order by i.updated_at desc nulls last, i.created_at desc nulls last
    limit 1
  )
  select jsonb_build_object(
    'branding_settings', coalesce((select payload from branding_row), '{}'::jsonb),
    'company_settings', coalesce((select payload from company_row), '{}'::jsonb)
  )
  into v_branding;

  return jsonb_build_object(
    'delivery', v_delivery,
    'items', coalesce(v_items, '[]'::jsonb),
    'files', coalesce(v_files, '[]'::jsonb),
    'branding', coalesce(v_branding, '{}'::jsonb),
    'phone_options', jsonb_build_object(
      'delivered_by', coalesce(v_delivered_phones, '[]'::jsonb),
      'received_by', coalesce(v_received_phones, '[]'::jsonb)
    )
  );
end;
$$;


--
-- Name: get_public_demo_wizard_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_demo_wizard_context() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  global_settings jsonb := public.get_saas_global_settings();
  demo_plan record;
begin
  select *
    into demo_plan
  from public.saas_plans
  where is_active = true
    and (is_demo_default = true or lower(code) = 'public_demo_full')
  order by is_demo_default desc, sort_order asc, created_at asc
  limit 1;

  return jsonb_build_object(
    'default_demo_limit', public.get_effective_demo_limit(null),
    'public_demo_plan', case
      when demo_plan.id is null then null
      else jsonb_build_object(
        'code', demo_plan.code,
        'title', demo_plan.title,
        'description', demo_plan.description,
        'trial_days', demo_plan.trial_days
      )
    end,
    'global_settings', global_settings
  );
end
$$;


--
-- Name: get_public_invoice(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_invoice(p_system_code text, p_module text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid;
  v_invoice_id uuid;
  v_invoice jsonb;
  v_items jsonb := '[]'::jsonb;
  v_payments jsonb := '[]'::jsonb;
  v_notes jsonb := '[]'::jsonb;
  v_branding jsonb := '{}'::jsonb;
  v_online_cfg jsonb := '{}'::jsonb;
begin
  v_org_id := public._resolve_org_for_public_invoice(p_system_code, p_module);
  if v_org_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  if p_module = 'invoices' then
    select
      i.id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'system_code', i.system_code,
          'public_link', i.public_link,
          'name', i.name,
          'status', i.status,
          'invoice_date', i.invoice_date,
          'description', i.description,
          'customer_name', c.full_name,
          'customer_mobile', c.mobile_1,
          'customer_mobile2', c.mobile_2,
          'customer_assistant_mobile', c.assistant_phone,
          'sale_source', i.sale_source,
          'province', i.province,
          'city', i.city,
          'postal_code', i.postal_code,
          'address', i.address,
          'total_invoice_amount', i.total_invoice_amount,
          'total_received_amount', i.total_received_amount,
          'remaining_balance', i.remaining_balance,
          'global_discount_type', i.global_discount_type,
          'global_discount_value', i.global_discount_value,
          'target_account', i.target_account,
          'payment_account_module', case when bank_account.id is not null then 'bank_accounts' else null end,
          'payment_account', case
            when bank_account.id is null then null
            else jsonb_strip_nulls(
              jsonb_build_object(
                'id', bank_account.id,
                'bank_name', bank_account.bank_name,
                'account_holder_name', bank_account.account_holder_name,
                'account_number', bank_account.account_number,
                'card_number', bank_account.card_number,
                'shaba', bank_account.shaba
              )
            )
          end,
          'customer_confirmed_at', i.customer_confirmed_at,
          'customer_confirmer_name', i.customer_confirmer_name
        )
      )
    into v_invoice_id, v_invoice
    from public.invoices i
    left join public.customers c
      on c.id = i.customer_id
     and c.org_id = i.org_id
    left join public.bank_accounts bank_account
      on bank_account.org_id = i.org_id
     and bank_account.id::text = nullif(i.target_account, '')
    where i.org_id = v_org_id
      and (i.public_slug = p_system_code or i.public_token = p_system_code)
    limit 1;

    select coalesce(
      jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'product_name', coalesce(
              p.name,
              nullif(item_rows.item->>'product_name', ''),
              nullif(item_rows.item->>'name', '')
            ),
            'quantity', item_rows.item->'quantity',
            'main_unit', item_rows.item->'main_unit',
            'unit_price', item_rows.item->'unit_price',
            'discount', item_rows.item->'discount',
            'discount_type', item_rows.item->'discount_type',
            'vat', item_rows.item->'vat',
            'vat_type', item_rows.item->'vat_type',
            'total_price', item_rows.item->'total_price',
            'description', item_rows.item->'description',
            'length', item_rows.item->'length',
            'width', item_rows.item->'width',
            'start_date', item_rows.item->'start_date',
            'end_date', item_rows.item->'end_date',
            'secondary_quantity', item_rows.item->'secondary_quantity',
            'secondary_unit', item_rows.item->'secondary_unit',
            'image_url', coalesce(
              nullif(item_rows.item->>'image_url', ''),
              nullif(p.image_url, '')
            )
          )
        )
        order by
          case
            when coalesce(item_rows.item->>'order_index', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              then (item_rows.item->>'order_index')::numeric
            else item_rows.ordinality::numeric
          end
      ) filter (where item_rows.item is not null),
      '[]'::jsonb
    )
    into v_items
    from public.invoices i
    left join lateral jsonb_array_elements(coalesce(i."invoiceItems", '[]'::jsonb))
      with ordinality as item_rows(item, ordinality) on true
    left join public.products p
      on p.org_id = i.org_id
     and p.id::text = nullif(item_rows.item->>'product_id', '')
    where i.id = v_invoice_id
      and i.org_id = v_org_id;

    select coalesce(
      jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'date', payment_row.item->'date',
            'amount', payment_row.item->'amount',
            'payment_type', payment_row.item->'payment_type',
            'description', payment_row.item->'description',
            'status', payment_row.item->'status'
          )
        )
        order by payment_row.ordinality
      ) filter (where payment_row.item is not null),
      '[]'::jsonb
    )
    into v_payments
    from public.invoices i
    left join lateral jsonb_array_elements(coalesce(i.payments, '[]'::jsonb))
      with ordinality as payment_row(item, ordinality) on true
    where i.id = v_invoice_id
      and i.org_id = v_org_id;
  else
    select
      i.id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'system_code', i.system_code,
          'public_link', i.public_link,
          'name', i.name,
          'status', i.status,
          'invoice_date', i.invoice_date,
          'description', i.description,
          'supplier_name', s.business_name,
          'supplier_mobile', s.mobile_1,
          'supplier_mobile2', s.mobile_2,
          'purchase_source', i.purchase_source,
          'total_invoice_amount', i.total_invoice_amount,
          'total_received_amount', i.total_received_amount,
          'remaining_balance', i.remaining_balance,
          'global_discount_type', i.global_discount_type,
          'global_discount_value', i.global_discount_value,
          'source_account', i.source_account,
          'payment_account_module', case when bank_account.id is not null then 'bank_accounts' else null end,
          'payment_account', case
            when bank_account.id is null then null
            else jsonb_strip_nulls(
              jsonb_build_object(
                'id', bank_account.id,
                'bank_name', bank_account.bank_name,
                'account_holder_name', bank_account.account_holder_name,
                'account_number', bank_account.account_number,
                'card_number', bank_account.card_number,
                'shaba', bank_account.shaba
              )
            )
          end,
          'supplier_confirmed_at', i.supplier_confirmed_at,
          'supplier_confirmer_name', i.supplier_confirmer_name
        )
      )
    into v_invoice_id, v_invoice
    from public.purchase_invoices i
    left join public.suppliers s
      on s.id = i.supplier_id
     and s.org_id = i.org_id
    left join public.bank_accounts bank_account
      on bank_account.org_id = i.org_id
     and bank_account.id::text = nullif(i.source_account, '')
    where i.org_id = v_org_id
      and (i.public_slug = p_system_code or i.public_token = p_system_code)
    limit 1;

    select coalesce(
      jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'product_name', coalesce(
              p.name,
              nullif(item_rows.item->>'product_name', ''),
              nullif(item_rows.item->>'name', '')
            ),
            'quantity', item_rows.item->'quantity',
            'main_unit', item_rows.item->'main_unit',
            'unit_price', item_rows.item->'unit_price',
            'discount', item_rows.item->'discount',
            'discount_type', item_rows.item->'discount_type',
            'vat', item_rows.item->'vat',
            'vat_type', item_rows.item->'vat_type',
            'total_price', item_rows.item->'total_price',
            'description', item_rows.item->'description',
            'length', item_rows.item->'length',
            'width', item_rows.item->'width',
            'start_date', item_rows.item->'start_date',
            'end_date', item_rows.item->'end_date',
            'secondary_quantity', item_rows.item->'secondary_quantity',
            'secondary_unit', item_rows.item->'secondary_unit',
            'image_url', coalesce(
              nullif(item_rows.item->>'image_url', ''),
              nullif(p.image_url, '')
            )
          )
        )
        order by
          case
            when coalesce(item_rows.item->>'order_index', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              then (item_rows.item->>'order_index')::numeric
            else item_rows.ordinality::numeric
          end
      ) filter (where item_rows.item is not null),
      '[]'::jsonb
    )
    into v_items
    from public.purchase_invoices i
    left join lateral jsonb_array_elements(coalesce(i."invoiceItems", '[]'::jsonb))
      with ordinality as item_rows(item, ordinality) on true
    left join public.products p
      on p.org_id = i.org_id
     and p.id::text = nullif(item_rows.item->>'product_id', '')
    where i.id = v_invoice_id
      and i.org_id = v_org_id;

    select coalesce(
      jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'date', payment_row.item->'date',
            'amount', payment_row.item->'amount',
            'payment_type', payment_row.item->'payment_type',
            'description', payment_row.item->'description',
            'status', payment_row.item->'status'
          )
        )
        order by payment_row.ordinality
      ) filter (where payment_row.item is not null),
      '[]'::jsonb
    )
    into v_payments
    from public.purchase_invoices i
    left join lateral jsonb_array_elements(coalesce(i.payments, '[]'::jsonb))
      with ordinality as payment_row(item, ordinality) on true
    where i.id = v_invoice_id
      and i.org_id = v_org_id;
  end if;

  if v_invoice is null or v_invoice_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', n.id,
        'content', n.content,
        'author_name', n.author_name,
        'created_at', n.created_at,
        'metadata', jsonb_build_object('source', n.metadata->>'source')
      )
      order by n.created_at asc
    ),
    '[]'::jsonb
  )
  into v_notes
  from public.notes n
  where n.org_id = v_org_id
    and n.module_id = p_module
    and n.record_id = v_invoice_id::text
    and n.is_public = true;

  with company_row as (
    select jsonb_strip_nulls(
      jsonb_build_object(
        'company_full_name', cs.company_full_name,
        'trade_name', cs.trade_name,
        'logo_url', cs.logo_url,
        'brand_palette_key', cs.brand_palette_key,
        'address', cs.address,
        'phone', cs.phone,
        'mobile', cs.mobile,
        'currency_label', cs.currency_label
      )
    ) as payload
    from public.company_settings cs
    where cs.org_id = v_org_id
    order by cs.updated_at desc nulls last, cs.created_at desc nulls last
    limit 1
  ),
  branding_row as (
    select jsonb_strip_nulls(
      jsonb_build_object(
        'brand_name', i.settings->>'brand_name',
        'brandName', i.settings->>'brandName',
        'short_name', i.settings->>'short_name',
        'shortName', i.settings->>'shortName',
        'primary_color', i.settings->>'primary_color',
        'palette_key', i.settings->>'palette_key'
      )
    ) as payload
    from public.integration_settings i
    where i.org_id = v_org_id
      and i.connection_type = 'ui_theme'
      and coalesce(i.provider, '') = 'branding'
      and i.is_active = true
    order by i.updated_at desc nulls last, i.created_at desc nulls last
    limit 1
  )
  select jsonb_build_object(
    'company_settings', coalesce((select payload from company_row), '{}'::jsonb),
    'branding_settings', coalesce((select payload from branding_row), '{}'::jsonb)
  )
  into v_branding;

  select coalesce(s.settings->'modules'->p_module->'onlineInvoice', '{}'::jsonb)
  into v_online_cfg
  from public.integration_settings s
  where s.org_id = v_org_id
    and s.connection_type = 'module_settings'
    and s.is_active = true
  order by s.updated_at desc
  limit 1;

  return jsonb_build_object(
    'invoice', v_invoice,
    'items', v_items,
    'payments', v_payments,
    'notes', v_notes,
    'branding', v_branding,
    'online_config', v_online_cfg
  );
end;
$_$;


--
-- Name: get_public_invoice_billboard_titles(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_invoice_billboard_titles(p_system_code text, p_module text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid;
  v_items jsonb := '[]'::jsonb;
begin
  if p_module not in ('invoices', 'purchase_invoices') then
    return v_items;
  end if;

  v_org_id := public._resolve_org_for_public_invoice(p_system_code, p_module);
  if v_org_id is null then
    return v_items;
  end if;

  if p_module = 'invoices' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'title', case when b.id is null then null else concat_ws(' ',
        'اجاره تابلوی تبلیغاتی',
        nullif(btrim(b.category), ''),
        coalesce(
          nullif(btrim(b.address), ''),
          nullif(concat_ws(' ', nullif(btrim(b.city_name), ''), nullif(btrim(b.name), '')), '')
        )
      ) end
    )) order by case
      when coalesce(item_rows.item ->> 'order_index', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
        then (item_rows.item ->> 'order_index')::numeric
      else item_rows.ordinality::numeric
    end), '[]'::jsonb)
    into v_items
    from public.invoices i
    left join lateral jsonb_array_elements(coalesce(i."invoiceItems", '[]'::jsonb)) with ordinality as item_rows(item, ordinality) on true
    left join public.billboards b
      on b.org_id = i.org_id
     and b.id::text = nullif(item_rows.item ->> 'product_id', '')
    where i.org_id = v_org_id
      and (i.public_slug = p_system_code or i.public_token = p_system_code);
  else
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'title', case when b.id is null then null else concat_ws(' ',
        'اجاره تابلوی تبلیغاتی',
        nullif(btrim(b.category), ''),
        coalesce(
          nullif(btrim(b.address), ''),
          nullif(concat_ws(' ', nullif(btrim(b.city_name), ''), nullif(btrim(b.name), '')), '')
        )
      ) end
    )) order by case
      when coalesce(item_rows.item ->> 'order_index', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
        then (item_rows.item ->> 'order_index')::numeric
      else item_rows.ordinality::numeric
    end), '[]'::jsonb)
    into v_items
    from public.purchase_invoices i
    left join lateral jsonb_array_elements(coalesce(i."invoiceItems", '[]'::jsonb)) with ordinality as item_rows(item, ordinality) on true
    left join public.billboards b
      on b.org_id = i.org_id
     and b.id::text = nullif(item_rows.item ->> 'product_id', '')
    where i.org_id = v_org_id
      and (i.public_slug = p_system_code or i.public_token = p_system_code);
  end if;

  return v_items;
end;
$_$;


--
-- Name: get_public_invoice_online_payment_options(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_invoice_online_payment_options(p_system_code text, p_module text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid;
  v_invoice_id uuid;
begin
  if p_module <> 'invoices' then
    return '[]'::jsonb;
  end if;

  v_org_id := public._resolve_org_for_public_invoice(p_system_code, p_module);
  if v_org_id is null then
    return '[]'::jsonb;
  end if;

  select i.id
  into v_invoice_id
  from public.invoices i
  where i.org_id = v_org_id
    and (i.public_slug = p_system_code or i.public_token = p_system_code)
  limit 1;

  if v_invoice_id is null then
    return '[]'::jsonb;
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'key', coalesce(nullif(btrim(payment.item ->> 'row_key'), ''), nullif(btrim(payment.item ->> 'payment_id'), ''), nullif(btrim(payment.item ->> 'id'), '')),
        'title', nullif(btrim(coalesce(payment.item ->> 'description', '')), ''),
        'amount', payment.item -> 'amount'
      ))
      order by payment.ordinality
    )
    from public.invoices i
    cross join lateral jsonb_array_elements(coalesce(i.payments, '[]'::jsonb)) with ordinality as payment(item, ordinality)
    where i.id = v_invoice_id
      and i.org_id = v_org_id
      and lower(coalesce(payment.item ->> 'status', '')) = 'pending'
      and lower(coalesce(payment.item ->> 'payment_type', '')) = 'online'
      and coalesce(nullif(payment.item ->> 'amount', ''), '0') ~ '^-?[0-9]+(\.[0-9]+)?$'
      and (payment.item ->> 'amount')::numeric > 0
      and coalesce(nullif(btrim(payment.item ->> 'row_key'), ''), nullif(btrim(payment.item ->> 'payment_id'), ''), nullif(btrim(payment.item ->> 'id'), '')) is not null
  ), '[]'::jsonb);
end;
$_$;


--
-- Name: get_public_invoice_payment_state(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_invoice_payment_state(p_system_code text, p_module text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_invoice_id uuid;
  v_remaining numeric := 0;
  v_currency text := 'IRR';
  v_settings jsonb := '{}'::jsonb;
  v_gateway_active boolean := false;
  v_gateway_scope text := 'system';
  v_payment_domain text := '';
  v_callback_path text := '/payment/callback';
  v_is_saas_admin_org boolean := false;
  v_has_custom_domain_payment boolean := false;
  v_org_gateway_merchant_configured boolean := false;
  v_available boolean := false;
begin
  if p_module <> 'invoices' then
    return jsonb_build_object(
      'available', false,
      'reason', 'unsupported_module'
    );
  end if;

  v_org_id := public._resolve_org_for_public_invoice(p_system_code, p_module);
  if v_org_id is null then
    return jsonb_build_object(
      'available', false,
      'reason', 'not_found'
    );
  end if;

  select i.id, greatest(coalesce(i.remaining_balance, 0), 0)
  into v_invoice_id, v_remaining
  from public.invoices i
  where i.org_id = v_org_id
    and (i.public_slug = p_system_code or i.public_token = p_system_code)
  limit 1;

  if v_invoice_id is null then
    return jsonb_build_object(
      'available', false,
      'reason', 'not_found'
    );
  end if;

  select
    coalesce(s.settings, '{}'::jsonb),
    s.is_active = true
  into v_settings, v_gateway_active
  from public.integration_settings s
  where s.org_id = v_org_id
    and s.connection_type = 'payment_gateway'
    and coalesce(s.provider, '') = 'zarinpal'
  order by s.is_active desc, s.updated_at desc nulls last, s.created_at desc nulls last
  limit 1;

  v_gateway_scope := case
    when coalesce(v_settings ->> 'gateway_scope', 'system') = 'org' then 'org'
    else 'system'
  end;
  v_currency := case
    when coalesce(v_settings ->> 'currency', 'IRR') = 'IRT' then 'IRT'
    else 'IRR'
  end;
  v_payment_domain := btrim(coalesce(v_settings ->> 'payment_domain', ''));
  v_callback_path := coalesce(nullif(btrim(v_settings ->> 'callback_path'), ''), '/payment/callback');

  v_gateway_active := coalesce(v_gateway_active, false)
    and coalesce((v_settings ->> 'online_invoice_payments_enabled')::boolean, false)
    and v_payment_domain <> '';

  v_is_saas_admin_org := public.org_has_saas_admin_payment_access(v_org_id);

  v_has_custom_domain_payment :=
    public.org_has_plan_feature(v_org_id, 'custom_domain', false)
    and public.org_has_plan_feature(v_org_id, 'own_payment_gateway', false)
    and public.org_has_plan_feature(v_org_id, 'online_invoice_payment', false);
  v_org_gateway_merchant_configured := btrim(coalesce(v_settings ->> 'merchant_id', '')) <> '';

  v_available := v_gateway_active
    and v_remaining > 0
    and (
      (v_gateway_scope = 'system' and v_is_saas_admin_org)
      or (v_gateway_scope = 'org' and v_has_custom_domain_payment and v_org_gateway_merchant_configured)
    );

  return jsonb_build_object(
    'available', v_available,
    'reason', case
      when v_remaining <= 0 then 'already_paid'
      when not v_gateway_active then 'gateway_inactive'
      when v_gateway_scope = 'system' and not v_is_saas_admin_org then 'system_gateway_not_allowed_for_org'
      when v_gateway_scope = 'org' and not v_has_custom_domain_payment then 'org_gateway_feature_not_enabled'
      when v_gateway_scope = 'org' and not v_org_gateway_merchant_configured then 'org_gateway_merchant_missing'
      else 'available'
    end,
    'provider', 'zarinpal',
    'gateway_scope', v_gateway_scope,
    'amount', v_remaining,
    'currency', v_currency,
    'payment_domain', v_payment_domain,
    'callback_path', v_callback_path,
    'mode', case when coalesce(v_settings ->> 'mode', 'production') = 'sandbox' then 'sandbox' else 'production' end,
    'title', coalesce(v_settings ->> 'title', ''),
    'default_description', coalesce(v_settings ->> 'default_description', '')
  );
end;
$$;


--
-- Name: get_public_online_account_card(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_online_account_card(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_card public.online_account_cards%rowtype;
  v_entity jsonb := '{}'::jsonb;
  v_name text := '';
  v_company jsonb := '{}'::jsonb;
  v_history jsonb := '{}'::jsonb;
begin
  if p_token is null or p_token !~ '^[0-9A-Za-z]{8,64}$' then
    return jsonb_build_object('error', 'not_found');
  end if;

  select * into v_card
  from public.online_account_cards
  where (public_slug = p_token or public_token = p_token) and is_active = true
  limit 1;
  if not found or not public.org_has_plan_feature(v_card.org_id, 'online_catalog', false) then
    return jsonb_build_object('error', 'not_found');
  end if;

  if v_card.entity_type = 'customer' then
    select to_jsonb(entity) into v_entity from public.customers entity where entity.id = v_card.entity_id and entity.org_id = v_card.org_id;
  elsif v_card.entity_type = 'supplier' then
    select to_jsonb(entity) into v_entity from public.suppliers entity where entity.id = v_card.entity_id and entity.org_id = v_card.org_id;
  else
    select to_jsonb(entity) into v_entity from public.employees entity where entity.id = v_card.entity_id and entity.org_id = v_card.org_id;
  end if;
  if v_entity is null then return jsonb_build_object('error', 'not_found'); end if;

  v_name := coalesce(
    nullif(btrim(v_entity ->> 'full_name'), ''),
    nullif(btrim(v_entity ->> 'business_name'), ''),
    nullif(btrim(v_entity ->> 'legal_name'), ''),
    nullif(btrim(concat_ws(' ', v_entity ->> 'first_name', v_entity ->> 'last_name')), ''),
    nullif(btrim(v_entity ->> 'system_code'), ''),
    case v_card.entity_type when 'customer' then 'مشتری' when 'supplier' then 'تامین‌کننده' else 'کارمند' end
  );
  select jsonb_strip_nulls(jsonb_build_object(
    'company_name', coalesce(company_full_name, company_name, trade_name),
    'trade_name', trade_name,
    'logo_url', logo_url,
    'currency_label', currency_label
  )) into v_company
  from public.company_settings
  where org_id = v_card.org_id
  order by updated_at desc
  limit 1;

  v_history := public._get_operational_financial_history(v_card.org_id, v_card.entity_type, v_card.entity_id);
  return jsonb_build_object(
    'card', jsonb_build_object(
      'title', v_card.title,
      'entity_type', v_card.entity_type,
      'entity_name', v_name,
      'public_link', v_card.public_link
    ),
    'company', coalesce(v_company, '{}'::jsonb),
    'rows', coalesce(v_history -> 'rows', '[]'::jsonb),
    'summary', coalesce(v_history -> 'summary', '{}'::jsonb)
  );
end;
$_$;


--
-- Name: get_public_online_account_card_payment_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_online_account_card_payment_state(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_card public.online_account_cards%rowtype;
  v_history jsonb := '{}'::jsonb;
  v_amount numeric := 0;
  v_settings jsonb := '{}'::jsonb;
  v_gateway_active boolean := false;
  v_scope text := 'system';
  v_currency text := 'IRR';
  v_allowed boolean := false;
begin
  if p_token is null or p_token !~ '^[0-9A-Za-z]{8,64}$' then
    return jsonb_build_object('available', false, 'reason', 'not_found');
  end if;

  select * into v_card
  from public.online_account_cards
  where (public_slug = p_token or public_token = p_token)
    and is_active = true
  limit 1;

  if not found
    or v_card.entity_type <> 'customer'
    or not public.org_has_plan_feature(v_card.org_id, 'online_catalog', false)
  then
    return jsonb_build_object('available', false, 'reason', 'not_found');
  end if;

  -- این همان منبعی است که جمع‌ها و ماندهٔ کارت عمومی را تولید می‌کند.
  v_history := public._get_operational_financial_history(
    v_card.org_id,
    'customer',
    v_card.entity_id
  );
  v_amount := greatest(
    public.financial_history_safe_numeric(v_history -> 'summary' ->> 'final_balance'),
    0
  );

  select coalesce(settings, '{}'::jsonb), is_active = true
  into v_settings, v_gateway_active
  from public.integration_settings
  where org_id = v_card.org_id
    and connection_type = 'payment_gateway'
    and coalesce(provider, '') = 'zarinpal'
  order by is_active desc, updated_at desc nulls last, created_at desc nulls last
  limit 1;

  v_scope := case when coalesce(v_settings ->> 'gateway_scope', 'system') = 'org' then 'org' else 'system' end;
  v_currency := case when coalesce(v_settings ->> 'currency', 'IRR') = 'IRT' then 'IRT' else 'IRR' end;
  v_gateway_active := coalesce(v_gateway_active, false)
    and coalesce((v_settings ->> 'online_invoice_payments_enabled')::boolean, false)
    and nullif(btrim(coalesce(v_settings ->> 'payment_domain', '')), '') is not null;

  v_allowed := v_gateway_active
    and v_amount > 0
    and (
      (v_scope = 'system' and public.org_has_saas_admin_payment_access(v_card.org_id))
      or (
        v_scope = 'org'
        and public.org_has_plan_feature(v_card.org_id, 'custom_domain', false)
        and public.org_has_plan_feature(v_card.org_id, 'own_payment_gateway', false)
        and public.org_has_plan_feature(v_card.org_id, 'online_invoice_payment', false)
        and nullif(btrim(coalesce(v_settings ->> 'merchant_id', '')), '') is not null
      )
    );

  return jsonb_build_object(
    'available', v_allowed,
    'amount', v_amount,
    'currency', v_currency,
    'gateway_scope', v_scope,
    'balance_source', 'central_financial_history'
  );
end;
$_$;


--
-- Name: get_public_online_account_card_v426(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_online_account_card_v426(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_card public.online_account_cards%rowtype;
  v_entity jsonb := '{}'::jsonb;
  v_name text := '';
  v_company jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  if p_token is null or p_token !~ '^[0-9A-Za-z]{8,64}$' then
    return jsonb_build_object('error', 'not_found');
  end if;

  select * into v_card
  from public.online_account_cards
  where (public_slug = p_token or public_token = p_token)
    and is_active = true
  limit 1;
  if not found or not public.org_has_plan_feature(v_card.org_id, 'online_catalog', false) then
    return jsonb_build_object('error', 'not_found');
  end if;

  if v_card.entity_type = 'customer' then
    select to_jsonb(entity) into v_entity from public.customers entity where id = v_card.entity_id and org_id = v_card.org_id;
  elsif v_card.entity_type = 'supplier' then
    select to_jsonb(entity) into v_entity from public.suppliers entity where id = v_card.entity_id and org_id = v_card.org_id;
  else
    select to_jsonb(entity) into v_entity from public.employees entity where id = v_card.entity_id and org_id = v_card.org_id;
  end if;
  if v_entity is null then return jsonb_build_object('error', 'not_found'); end if;

  v_name := coalesce(
    nullif(btrim(v_entity ->> 'full_name'), ''),
    nullif(btrim(v_entity ->> 'business_name'), ''),
    nullif(btrim(v_entity ->> 'legal_name'), ''),
    nullif(btrim(concat_ws(' ', v_entity ->> 'first_name', v_entity ->> 'last_name')), ''),
    nullif(btrim(v_entity ->> 'system_code'), ''),
    case v_card.entity_type when 'customer' then 'مشتری' when 'supplier' then 'تامین‌کننده' else 'کارمند' end
  );
  select jsonb_strip_nulls(jsonb_build_object(
    'company_name', coalesce(company_full_name, company_name, trade_name),
    'trade_name', trade_name,
    'logo_url', logo_url,
    'currency_label', currency_label
  )) into v_company
  from public.company_settings
  where org_id = v_card.org_id
  order by updated_at desc
  limit 1;

  with raw_rows as (
    select
      'opening'::text row_type,
      'مانده اول دوره'::text source_label,
      null::text status,
      null::text payment_type,
      c.created_at::date row_date,
      case when (v_card.entity_type = 'customer' and c.previous_system_balance_total >= 0) or (v_card.entity_type <> 'customer' and c.previous_system_balance_total < 0) then abs(c.previous_system_balance_total) else 0 end debit,
      case when (v_card.entity_type = 'customer' and c.previous_system_balance_total < 0) or (v_card.entity_type <> 'customer' and c.previous_system_balance_total >= 0) then abs(c.previous_system_balance_total) else 0 end credit,
      'مانده اول دوره سیستم قبلی'::text description,
      c.created_at,
      'opening_' || c.id::text key
    from (
      select id, created_at, previous_system_balance_total from public.customers where v_card.entity_type = 'customer' and id = v_card.entity_id and org_id = v_card.org_id
      union all
      select id, created_at, previous_system_balance_total from public.suppliers where v_card.entity_type = 'supplier' and id = v_card.entity_id and org_id = v_card.org_id
      union all
      select id, created_at, previous_system_balance_total from public.employees where v_card.entity_type = 'employee' and id = v_card.entity_id and org_id = v_card.org_id
    ) c
    where coalesce(c.previous_system_balance_total, 0) <> 0

    union all

    select
      'invoice',
      case when v_card.entity_type = 'customer' then 'صدور فاکتور فروش' else 'ثبت فاکتور خرید' end,
      i.status,
      null,
      i.invoice_date,
      case when v_card.entity_type = 'customer' then i.total_invoice_amount else 0 end,
      case when v_card.entity_type = 'supplier' then i.total_invoice_amount else 0 end,
      concat(case when v_card.entity_type = 'customer' then 'فاکتور فروش' else 'فاکتور خرید' end, case when coalesce(i.remaining_balance, 0) <> 0 then ' | مانده: ' || i.remaining_balance else '' end),
      i.created_at,
      'invoice_' || i.id::text
    from (
      select id, invoice_date, status, total_invoice_amount, remaining_balance, created_at from public.invoices where v_card.entity_type = 'customer' and customer_id = v_card.entity_id and org_id = v_card.org_id and status in ('confirmed', 'final', 'settled', 'completed')
      union all
      select id, invoice_date, status, total_invoice_amount, remaining_balance, created_at from public.purchase_invoices where v_card.entity_type = 'supplier' and supplier_id = v_card.entity_id and org_id = v_card.org_id and status in ('confirmed', 'final', 'settled', 'completed')
    ) i

    union all

    select
      case when o.operation_type = 'payment' then 'payment' else 'receipt' end,
      'عملیات نقد و بانک',
      o.status,
      o.payment_type,
      o.operation_date,
      case when v_card.entity_type = 'customer' and o.operation_type = 'receipt' then abs(o.amount) when v_card.entity_type <> 'customer' and o.operation_type = 'payment' then abs(o.amount) else 0 end,
      case when v_card.entity_type = 'customer' and o.operation_type = 'payment' then abs(o.amount) when v_card.entity_type <> 'customer' and o.operation_type = 'receipt' then abs(o.amount) else 0 end,
      coalesce(o.description, ''),
      o.created_at,
      'operation_' || o.id::text
    from public.cash_bank_operations o
    where o.org_id = v_card.org_id
      and o.status in ('received', 'approved', 'paid', 'settled', 'cleared')
      and o.operation_type <> 'transfer'
      and ((v_card.entity_type = 'customer' and o.customer_id = v_card.entity_id) or (v_card.entity_type = 'supplier' and o.supplier_id = v_card.entity_id) or (v_card.entity_type = 'employee' and o.employee_id = v_card.entity_id))

    union all

    select
      case when v_card.entity_type = 'customer' then 'receipt' else 'payment' end,
      case when v_card.entity_type = 'customer' then 'دریافت فاکتور فروش' else 'پرداخت فاکتور خرید' end,
      coalesce(p.item ->> 'status', 'received'),
      coalesce(p.item ->> 'payment_type', ''),
      coalesce(nullif(p.item ->> 'date', '')::date, i.invoice_date),
      case when v_card.entity_type = 'customer' then abs((p.item ->> 'amount')::numeric) else 0 end,
      case when v_card.entity_type = 'supplier' then abs((p.item ->> 'amount')::numeric) else 0 end,
      coalesce(p.item ->> 'description', ''),
      i.created_at,
      'legacy_payment_' || i.id::text || '_' || p.ordinality::text
    from (
      select id, invoice_date, created_at, payments from public.invoices where v_card.entity_type = 'customer' and customer_id = v_card.entity_id and org_id = v_card.org_id
      union all
      select id, invoice_date, created_at, payments from public.purchase_invoices where v_card.entity_type = 'supplier' and supplier_id = v_card.entity_id and org_id = v_card.org_id
    ) i
    cross join lateral jsonb_array_elements(coalesce(i.payments, '[]'::jsonb)) with ordinality p(item, ordinality)
    where lower(coalesce(p.item ->> 'status', 'received')) in ('received', 'paid', 'approved', 'cleared')
      and coalesce(p.item ->> 'amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
      and not (p.item ? '_cash_bank_operation_id' and nullif(p.item ->> '_cash_bank_operation_id', '') is not null)

    union all

    select 'payroll_slip', 'فیش حقوقی', p.status, null, p.period_end, 0, p.net_amount, 'تعهد پرداخت حقوق', p.created_at, 'payroll_' || p.id::text
    from public.payroll_slips p
    where v_card.entity_type = 'employee' and p.org_id = v_card.org_id and p.employee_id = v_card.entity_id and p.status in ('approved', 'paid', 'posted') and coalesce(p.net_amount, 0) > 0

    union all

    select 'advance', 'درخواست مساعده', a.status, null, a.request_date, 0, a.amount, concat('مساعده', case when coalesce(a.remaining_amount, 0) <> 0 then ' | مانده: ' || a.remaining_amount else '' end), a.created_at, 'advance_' || a.id::text
    from public.employee_advances a
    where v_card.entity_type = 'employee' and a.org_id = v_card.org_id and a.employee_id = v_card.entity_id and a.status in ('requested', 'approved', 'paid', 'settled', 'posted') and coalesce(a.amount, 0) > 0

    union all

    select 'expense', 'ثبت هزینه', e.status, null, e.expense_date, 0, e.total_amount, concat('هزینه', case when coalesce(e.remaining_amount, 0) <> 0 then ' | مانده: ' || e.remaining_amount else '' end), e.created_at, 'expense_' || e.id::text
    from public.expense_documents e
    where e.org_id = v_card.org_id and e.status in ('approved', 'paid', 'posted', 'settled', 'completed') and coalesce(e.total_amount, 0) > 0
      and ((v_card.entity_type = 'customer' and e.customer_id = v_card.entity_id) or (v_card.entity_type = 'supplier' and e.supplier_id = v_card.entity_id) or (v_card.entity_type = 'employee' and e.employee_id = v_card.entity_id))

    union all

    select 'barter', 'تهاتر', b.status, 'barter', b.barter_date, case when b.barter_type = 'outgoing' then abs(b.initial_amount) else 0 end, case when b.barter_type = 'incoming' then abs(b.initial_amount) else 0 end, coalesce(b.notes, ''), b.created_at, 'barter_' || b.id::text
    from public.barters b
    where b.org_id = v_card.org_id and b.status <> 'canceled'
      and ((v_card.entity_type = 'customer' and b.customer_id = v_card.entity_id) or (v_card.entity_type = 'supplier' and b.supplier_id = v_card.entity_id) or (v_card.entity_type = 'employee' and b.employee_id = v_card.entity_id))
  ), ranked as (
    select *, sum(coalesce(debit, 0) - coalesce(credit, 0)) over (order by (row_type = 'opening') desc, coalesce(row_date, created_at::date), key rows between unbounded preceding and current row) balance
    from raw_rows
  )
  select
    coalesce(jsonb_agg(jsonb_build_object('key', key, 'row_type', row_type, 'source_label', source_label, 'status', status, 'payment_type', payment_type, 'date', row_date, 'debit', debit, 'credit', credit, 'balance', balance, 'description', description) order by (row_type = 'opening') desc, coalesce(row_date, created_at::date), key), '[]'::jsonb),
    jsonb_build_object(
      'total_debit', coalesce(sum(debit), 0),
      'total_credit', coalesce(sum(credit), 0),
      'final_balance', coalesce((array_agg(balance order by (row_type = 'opening') asc, coalesce(row_date, created_at::date) desc, key desc))[1], 0)
    )
  into v_rows, v_summary
  from ranked;

  -- آمار مشتری تنها از ستون‌های محاسبه‌شدهٔ خود پرونده می‌آید؛ این ستون‌ها
  -- توسط trigger فاکتور همواره با مبلغ، پرداخت و ماندهٔ واقعی هماهنگ می‌شوند.
  if v_card.entity_type = 'customer' then
    v_summary := jsonb_build_object(
      'total_debit', coalesce(nullif(v_entity ->> 'total_spend', '')::numeric, 0),
      'total_credit', coalesce(nullif(v_entity ->> 'total_paid_amount', '')::numeric, 0),
      'final_balance', coalesce(nullif(v_entity ->> 'total_balance', '')::numeric, 0),
      'source', 'customer_financial_stats'
    );
  end if;

  return jsonb_build_object(
    'card', jsonb_build_object('title', v_card.title, 'entity_type', v_card.entity_type, 'entity_name', v_name, 'public_link', v_card.public_link),
    'company', coalesce(v_company, '{}'::jsonb),
    'rows', v_rows,
    'summary', v_summary
  );
end;
$_$;


--
-- Name: get_public_online_catalog(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_online_catalog(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_catalog public.online_catalogs%rowtype;
  v_company jsonb := '{}'::jsonb;
  v_items jsonb := '[]'::jsonb;
  v_ids uuid[];
begin
  if p_token is null or p_token !~ '^[0-9a-f]{48}$' then return jsonb_build_object('error', 'not_found'); end if;
  select * into v_catalog from public.online_catalogs where public_token = p_token and is_active = true limit 1;
  if not found then return jsonb_build_object('error', 'not_found'); end if;

  select jsonb_strip_nulls(jsonb_build_object(
    'company_name', coalesce(company_full_name, company_name, trade_name), 'trade_name', trade_name,
    'company_name_en', company_name_en, 'slogan', slogan, 'logo_url', logo_url, 'phone', phone,
    'mobile', mobile, 'email', email, 'website', website, 'address', address, 'instagram_id', instagram_id,
    'whatsapp_number', whatsapp_number, 'telegram_id', telegram_id, 'palette_key', brand_palette_key, 'currency_label', currency_label
  )) into v_company from public.company_settings where org_id = v_catalog.org_id order by updated_at desc limit 1;

  select coalesce(array_agg(value::uuid), '{}'::uuid[]) into v_ids
  from jsonb_array_elements_text(v_catalog.source_record_ids)
  where value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

  if v_catalog.module_id = 'products' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'title', p.name, 'image_url', p.image_url, 'status', p.status,
      'fields', public.online_catalog_filter_fields(to_jsonb(p), v_catalog.display_field_keys)
    )) order by p.updated_at desc), '[]'::jsonb) into v_items
    from public.products p where p.org_id = v_catalog.org_id and p.id = any(v_ids);
  elsif v_catalog.module_id = 'billboards' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'title', coalesce(b.name, b.address), 'image_url', b.image_url, 'status', b.status, 'location', b.location,
      'fields', public.online_catalog_filter_fields(to_jsonb(b), v_catalog.display_field_keys)
    )) order by b.updated_at desc), '[]'::jsonb) into v_items
    from public.billboards b where b.org_id = v_catalog.org_id and b.id = any(v_ids);
  elsif v_catalog.module_id = 'price_lists' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'title', coalesce(p.name, b.name, item.value->>'product_name', item.value->>'name'),
      'image_url', coalesce(p.image_url, b.image_url), 'status', coalesce(p.status, b.status), 'location', b.location,
      'catalog_details', jsonb_strip_nulls(jsonb_build_object(
        'price', item.value->'price', 'currency_label', nullif(item.value->>'currency_label', ''),
        'unit_name', coalesce(nullif(item.value->>'unit_name', ''), nullif(p.main_unit, '')),
        'description', nullif(item.value->>'description', '')
      )),
      'fields', public.online_catalog_filter_fields(item.value, v_catalog.display_field_keys)
    ))), '[]'::jsonb) into v_items
    from public.price_lists pl
    cross join lateral jsonb_array_elements(coalesce(pl.items, '[]'::jsonb)) item(value)
    left join public.products p on p.id::text = item.value->>'product_id' and p.org_id = pl.org_id
    left join public.billboards b on b.id::text = item.value->>'product_id' and b.org_id = pl.org_id
    where pl.org_id = v_catalog.org_id and pl.id = any(v_ids);
  elsif v_catalog.module_id = 'product_bundles' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'title', pb.name, 'image_url', pb.image_url, 'status', pb.status,
      'catalog_details', jsonb_build_object(
        'gross_price', pricing.gross_price,
        'discount_amount', greatest(pricing.gross_price - pricing.final_price, 0),
        'discount_percent', case when pricing.gross_price > 0 then round((greatest(pricing.gross_price - pricing.final_price, 0) * 100 / pricing.gross_price), 2) else 0 end,
        'final_price', pricing.final_price
      ),
      'items', pricing.items
    )) order by pb.updated_at desc), '[]'::jsonb) into v_items
    from public.product_bundles pb
    cross join lateral (
      select
        coalesce(sum(row_pricing.gross_price), 0) as gross_price,
        coalesce(sum(row_pricing.final_price), 0) as final_price,
        coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
          'title', coalesce(p.name, b.name, row_pricing.item->>'product_name', row_pricing.item->>'name'),
          'image_url', coalesce(p.image_url, b.image_url), 'status', coalesce(p.status, b.status), 'location', b.location,
          'catalog_details', jsonb_strip_nulls(jsonb_build_object(
            'quantity', row_pricing.quantity,
            'unit_name', coalesce(nullif(row_pricing.item->>'main_unit', ''), nullif(p.main_unit, '')),
            'unit_price', row_pricing.unit_price,
            'gross_price', row_pricing.gross_price,
            'discount_amount', greatest(row_pricing.gross_price - row_pricing.final_price, 0),
            'discount_percent', case when row_pricing.gross_price > 0 then round((greatest(row_pricing.gross_price - row_pricing.final_price, 0) * 100 / row_pricing.gross_price), 2) else 0 end,
            'total_price', row_pricing.final_price,
            'description', nullif(row_pricing.item->>'description', '')
          )),
          'fields', public.online_catalog_filter_fields(row_pricing.item, v_catalog.display_field_keys)
        )) order by row_pricing.ordinality), '[]'::jsonb) as items
      from (
        select
          item.value as item,
          item.ordinality,
          case when coalesce(item.value->>'quantity', '') ~ '^-?[0-9]+([.][0-9]+)?$' then abs((item.value->>'quantity')::numeric) else 0 end as quantity,
          case when coalesce(item.value->>'unit_price', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (item.value->>'unit_price')::numeric else 0 end as unit_price,
          (case when coalesce(item.value->>'quantity', '') ~ '^-?[0-9]+([.][0-9]+)?$' then abs((item.value->>'quantity')::numeric) else 0 end)
            * (case when coalesce(item.value->>'unit_price', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (item.value->>'unit_price')::numeric else 0 end) as gross_price,
          case
            when coalesce(item.value->>'total_price', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (item.value->>'total_price')::numeric
            else
              (case when coalesce(item.value->>'quantity', '') ~ '^-?[0-9]+([.][0-9]+)?$' then abs((item.value->>'quantity')::numeric) else 0 end)
              * (case when coalesce(item.value->>'unit_price', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (item.value->>'unit_price')::numeric else 0 end)
              - case
                  when lower(coalesce(item.value->>'discount_type', 'amount')) = 'percent' then
                    ((case when coalesce(item.value->>'quantity', '') ~ '^-?[0-9]+([.][0-9]+)?$' then abs((item.value->>'quantity')::numeric) else 0 end)
                      * (case when coalesce(item.value->>'unit_price', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (item.value->>'unit_price')::numeric else 0 end))
                      * (case when coalesce(item.value->>'discount', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (item.value->>'discount')::numeric else 0 end) / 100
                  else (case when coalesce(item.value->>'discount', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (item.value->>'discount')::numeric else 0 end)
                end
          end as final_price
        from jsonb_array_elements(coalesce(pb.products, '[]'::jsonb)) with ordinality item(value, ordinality)
      ) row_pricing
      left join public.products p on p.id::text = row_pricing.item->>'product_id' and p.org_id = pb.org_id
      left join public.billboards b on b.id::text = row_pricing.item->>'product_id' and b.org_id = pb.org_id
    ) pricing
    where pb.org_id = v_catalog.org_id and pb.id = any(v_ids);
  end if;

  return jsonb_build_object(
    'catalog', jsonb_build_object('title', v_catalog.title, 'description', v_catalog.public_description,
      'template_id', v_catalog.template_id, 'presentation', v_catalog.presentation, 'record_count', jsonb_array_length(v_items),
      'last_refreshed_at', v_catalog.last_refreshed_at, 'module_id', v_catalog.module_id, 'display_field_keys', v_catalog.display_field_keys, 'tags', v_catalog.tags),
    'company', coalesce(v_company, '{}'::jsonb), 'items', v_items
  );
end;
$_$;


--
-- Name: get_public_plans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_plans() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'code', code,
    'title', title,
    'short_description', short_description,
    'price_monthly', coalesce(price_per_user_monthly, price_monthly),
    'price_yearly', coalesce(price_per_user_yearly, price_yearly),
    'included_users', coalesce(minimum_users, 3),
    'minimum_users', coalesce(minimum_users, 3),
    'extra_user_price', 0,
    'max_users', max_users,
    'storage_gb', storage_gb,
    'highlight_tag', highlight_tag,
    'display_features', display_features,
    'enabled_modules', coalesce(enabled_modules, '{}'::jsonb),
    'enabled_features', coalesce(enabled_features, '{}'::jsonb),
    'custom_price_label', custom_price_label,
    'trial_days', trial_days
  ) order by sort_order asc), '[]'::jsonb)
  from public.saas_plans
  where is_active = true and is_public = true;
$$;


--
-- Name: get_public_tenant_host_context(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_tenant_host_context(p_hostname text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  hostname text := lower(trim(coalesce(p_hostname, '')));
begin
  if hostname = '' then
    return jsonb_build_object('found', false, 'reason', 'empty_hostname');
  end if;

  return coalesce(
    (
      select jsonb_build_object('found', true, 'context', public.resolve_saas_org_context(null, null, hostname))
    ),
    jsonb_build_object('found', false, 'reason', 'tenant_not_found')
  );
end
$$;


--
-- Name: get_public_web_form(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_web_form(p_slug text DEFAULT 'inquiry'::text, p_hostname text DEFAULT NULL::text) RETURNS TABLE(org_id uuid, form_id uuid, web_form jsonb, fields jsonb, company_settings jsonb, branding_settings jsonb, conditional_display jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_slug text := lower(trim(coalesce(p_slug, 'inquiry')));
  v_org_id uuid;
  v_company_settings jsonb := '{}'::jsonb;
  v_branding_settings jsonb := '{}'::jsonb;
begin
  select
    b.org_id,
    coalesce(b.company_settings, '{}'::jsonb),
    coalesce(b.branding_settings, '{}'::jsonb)
  into
    v_org_id,
    v_company_settings,
    v_branding_settings
  from public.get_public_branding(p_hostname) b
  limit 1;

  -- Anonymous visitors receive only what the sign-in screen needs.
  if (select wf.access_scope from public.web_forms wf
      where wf.org_id = v_org_id and wf.is_active and lower(wf.route_slug) = v_slug
      order by wf.updated_at desc nulls last, wf.created_at desc nulls last limit 1) = 'internal'
    and not exists (
      select 1 from public.user_organization_memberships m
      join public.organizations o on o.id = m.org_id and o.is_active
      where m.org_id = v_org_id and m.user_id = auth.uid() and m.is_active
    ) then
    if auth.uid() is not null then
      raise exception 'WEB_FORM_ORG_ACCESS_DENIED' using errcode = '42501';
    end if;
    return query
      select v_org_id, wf.id, jsonb_build_object('access_scope', 'internal'),
        '[]'::jsonb, '{}'::jsonb, '{}'::jsonb, '{"rules":[]}'::jsonb
      from public.web_forms wf
      where wf.org_id = v_org_id and wf.is_active and lower(wf.route_slug) = v_slug
      order by wf.updated_at desc nulls last, wf.created_at desc nulls last limit 1;
    return;
  end if;

  return query
  select
    v_org_id,
    wf.id,
    to_jsonb(wf.*),
    coalesce(
      (
        select jsonb_agg(to_jsonb(wff.*) order by wff.sort_order asc, wff.created_at asc)
        from public.web_form_fields wff
        where wff.web_form_id = wf.id
          and wff.is_active = true
      ),
      '[]'::jsonb
    ),
    v_company_settings,
    v_branding_settings,
    coalesce(
      (
        select i.settings #> array['modules', coalesce(wf.target_module_id, ''), 'conditionalDisplay']
        from public.integration_settings i
        where i.org_id = v_org_id
          and i.connection_type = 'module_settings'
          and i.is_active = true
        order by i.updated_at desc nulls last, i.created_at desc nulls last
        limit 1
      ),
      '{"rules":[]}'::jsonb
    )
  from public.web_forms wf
  where wf.org_id = v_org_id
    and wf.is_active = true
    and lower(wf.route_slug) = v_slug
  order by wf.updated_at desc nulls last, wf.created_at desc nulls last
  limit 1;
end;
$$;


--
-- Name: get_public_web_form(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_web_form(p_slug text, p_hostname text, p_access_token text) RETURNS TABLE(org_id uuid, form_id uuid, web_form jsonb, fields jsonb, company_settings jsonb, branding_settings jsonb, conditional_display jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row record;
  v_token_context jsonb := '{}'::jsonb;
  v_token_form_id uuid;
begin
  if nullif(trim(coalesce(p_access_token, '')), '') is not null then
    v_token_context := public._resolve_web_form_link_context(p_access_token, null, null);
    if nullif(coalesce(v_token_context->>'web_form_id', ''), '') is not null then
      v_token_form_id := (v_token_context->>'web_form_id')::uuid;
    end if;
  end if;

  select *
    into v_row
  from public.get_public_web_form(p_slug, p_hostname)
  limit 1;

  if v_row.form_id is null then
    return;
  end if;

  if v_token_form_id is not null and v_row.form_id is distinct from v_token_form_id then
    raise exception 'WEB_FORM_TOKEN_MISMATCH';
  end if;

  org_id := v_row.org_id;
  form_id := v_row.form_id;
  web_form := v_row.web_form;
  fields := v_row.fields;
  company_settings := v_row.company_settings;
  branding_settings := v_row.branding_settings;
  conditional_display := v_row.conditional_display;
  return next;
end;
$$;


--
-- Name: get_published_site_page(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_published_site_page(p_org_slug text, p_page_slug text) RETURNS TABLE(title text, slug text, blocks jsonb, published_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.title, v.slug, v.blocks, p.published_at
  from public.site_pages p
  join public.site_page_versions v on v.id = p.published_version_id and v.page_id = p.id and v.org_id = p.org_id
  join public.saas_org_settings s on s.org_id = p.org_id
  where lower(s.slug) = lower(trim(p_org_slug))
    and v.slug = lower(trim(p_page_slug))
    and p.published_version_id is not null and p.published_at is not null
    and coalesce(s.status, 'active') not in ('suspended', 'disabled', 'closed')
    and public.is_valid_tenant_site_blocks(v.blocks)
  limit 1;
$$;


--
-- Name: get_recent_internal_notes_for_current_user(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recent_internal_notes_for_current_user(p_conversation_key text DEFAULT NULL::text, p_limit integer DEFAULT 120) RETURNS TABLE(id uuid, org_id uuid, module_id text, record_id uuid, content text, author_id uuid, author_name text, mention_user_ids uuid[], mention_role_ids uuid[], created_at timestamp with time zone, updated_at timestamp with time zone, reply_to uuid, source_type text, metadata jsonb, is_edited boolean, edited_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_key text := nullif(trim(coalesce(p_conversation_key, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 120), 1), 240);
  v_other_user_id uuid := null;
  v_group_id text := null;
begin
  if v_user_id is null or v_org_id is null then
    return;
  end if;

  select p.role_id
    into v_role_id
  from public.profiles p
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if v_key like 'direct:%' then
    v_other_user_id := case
      when public.kalam_try_uuid(split_part(v_key, ':', 2)) = v_user_id
        then public.kalam_try_uuid(split_part(v_key, ':', 3))
      else public.kalam_try_uuid(split_part(v_key, ':', 2))
    end;
  elsif v_key like 'group:%' then
    v_group_id := nullif(trim(substr(v_key, length('group:') + 1)), '');
  end if;

  return query
  with author_rows as (
    select n.*
    from public.notes n
    where n.org_id = v_org_id
      and n.author_id = v_user_id
      and (
        v_key is null
        or (
          v_key = 'mine'
          and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
          and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
          and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
          and (
            lower(trim(coalesce(n.metadata->>'saved_message', 'false'))) in ('true', '1', 'yes')
            or coalesce(array_length(n.mention_user_ids, 1), 0) = 0
          )
        )
        or (
          v_key like 'direct:%'
          and v_other_user_id is not null
          and v_other_user_id = any(coalesce(n.mention_user_ids, '{}'::uuid[]))
          and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
        )
        or (
          v_key like 'group:%'
          and v_group_id is not null
          and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') = v_group_id
        )
      )
    order by n.created_at desc, n.id desc
    limit v_limit
  ),
  mention_rows as (
    select n.*
    from public.notes n
    where n.org_id = v_org_id
      and v_user_id = any(coalesce(n.mention_user_ids, '{}'::uuid[]))
      and (
        v_key is null
        or (
          v_key like 'direct:%'
          and v_other_user_id is not null
          and n.author_id = v_other_user_id
          and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
        )
        or (
          v_key like 'group:%'
          and v_group_id is not null
          and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') = v_group_id
        )
      )
    order by n.created_at desc, n.id desc
    limit v_limit
  ),
  system_rows as (
    select n.*
    from public.notification_inbox_items nii
    join public.notes n
      on n.org_id = nii.org_id
     and n.id::text = nii.source_id
    where nii.org_id = v_org_id
      and nii.section = 'notes'
      and nii.source_type = 'note'
      and (v_key is null or v_key = 'system')
      and (
        nii.conversation_key = 'system'
        or lower(trim(coalesce(nii.category, ''))) in ('system', 'assistant')
      )
      and (
        nii.is_org_wide = true
        or v_user_id = any(coalesce(nii.target_user_ids, '{}'::uuid[]))
        or (v_role_id is not null and v_role_id = any(coalesce(nii.target_role_ids, '{}'::uuid[])))
      )
    order by nii.created_at desc, nii.source_id desc
    limit v_limit
  ),
  combined as (
    select * from author_rows
    union
    select * from mention_rows
    union
    select * from system_rows
  )
  select
    c.id,
    c.org_id,
    c.module_id,
    c.record_id,
    c.content,
    c.author_id,
    c.author_name,
    c.mention_user_ids,
    c.mention_role_ids,
    c.created_at,
    c.updated_at,
    c.reply_to,
    c.source_type,
    coalesce(c.metadata, '{}'::jsonb) as metadata,
    coalesce(c.is_edited, false) as is_edited,
    c.edited_at
  from combined c
  order by c.created_at desc, c.id desc
  limit v_limit;
exception when others then
  raise warning 'get_recent_internal_notes_for_current_user failed: %', sqlerrm;
  return;
end;
$$;


--
-- Name: get_record_lock_map(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_record_lock_map(p_module_id text, p_record_ids uuid[]) RETURNS TABLE(record_id uuid, module_id text, locked_at timestamp with time zone, locked_by uuid, lock_reason text, source_type text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    rl.record_id,
    rl.module_id,
    rl.locked_at,
    rl.locked_by,
    rl.lock_reason,
    rl.source_type
  from public.record_locks rl
  where rl.org_id = public.current_org_id()
    and rl.record_id = any(coalesce(p_record_ids, '{}'::uuid[]))
    and (
      rl.module_id = btrim(coalesce(p_module_id, ''))
      or rl.metadata ->> 'table_name' = public.resolve_record_lock_table_name(p_module_id)
    );
$$;


--
-- Name: get_record_tag_id_map(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_record_tag_id_map(p_module_id text, p_tag_ids text[] DEFAULT NULL::text[]) RETURNS TABLE(record_id text, tag_ids text[])
    LANGUAGE sql STABLE
    AS $$
  SELECT
    rt.record_id,
    array_agg(DISTINCT rt.tag_id::text ORDER BY rt.tag_id::text) AS tag_ids
  FROM public.record_tags rt
  WHERE NULLIF(trim(p_module_id), '') IS NOT NULL
    AND rt.module_id = trim(p_module_id)
    AND (
      COALESCE(cardinality(p_tag_ids), 0) = 0
      OR rt.tag_id::text = ANY(p_tag_ids)
    )
  GROUP BY rt.record_id;
$$;


--
-- Name: get_record_tags_map(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_record_tags_map(p_module_id text, p_record_ids text[]) RETURNS TABLE(record_id text, tags jsonb)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    rt.record_id,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', t.id,
          'title', t.title,
          'color', t.color
        )
        ORDER BY t.title, t.id
      ) FILTER (WHERE t.id IS NOT NULL),
      '[]'::jsonb
    ) AS tags
  FROM public.record_tags rt
  JOIN public.tags t
    ON t.id = rt.tag_id
  WHERE NULLIF(trim(p_module_id), '') IS NOT NULL
    AND rt.module_id = trim(p_module_id)
    AND p_record_ids IS NOT NULL
    AND cardinality(p_record_ids) > 0
    AND rt.record_id = ANY(p_record_ids)
  GROUP BY rt.record_id;
$$;


--
-- Name: get_saas_admin_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_saas_admin_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  -- فقط saas admin می‌تواند این را صدا بزند
  if not public.current_user_has_saas_admin_permission() then
    raise exception 'permission denied';
  end if;

  select jsonb_build_object(
    'total_orgs',         (select count(*) from public.saas_org_settings),
    'active_orgs',        (select count(*) from public.saas_org_settings where status = 'active'),
    'demo_orgs',          (select count(*) from public.saas_org_settings where is_demo = true),
    'trial_orgs',         (select count(*) from public.saas_org_settings where status = 'trial'),
    'pending_dns',        (select count(*) from public.saas_org_settings where dns_status = 'pending'),
    'failed_dns',         (select count(*) from public.saas_org_settings where dns_status = 'failed'),
    'total_requests',     (select count(*) from public.saas_onboarding_requests),
    'pending_requests',   (select count(*) from public.saas_onboarding_requests where status in ('draft','started')),
    'provisioned_today',  (
      select count(*) from public.saas_onboarding_requests
      where status = 'provisioned'
        and created_at >= current_date
    ),
    'total_plans',        (select count(*) from public.saas_plans where is_active = true)
  ) into v_result;

  return v_result;
end;
$$;


--
-- Name: get_saas_global_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_saas_global_settings() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  settings_value jsonb := '{}'::jsonb;
begin
  select coalesce(settings, '{}'::jsonb)
    into settings_value
  from public.integration_settings
  where org_id is null
    and connection_type = 'saas'
  order by updated_at desc nulls last, created_at desc nulls last
  limit 1;

  if settings_value is null then
    settings_value := '{}'::jsonb;
  end if;

  if not (settings_value ? 'demo_policy') then
    settings_value := jsonb_set(
      settings_value,
      '{demo_policy}',
      jsonb_build_object('default_max_demo_count', 2),
      true
    );
  end if;

  return settings_value;
end
$$;


--
-- Name: get_site_footer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_site_footer() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(lp.footer, '{}'::jsonb)
  FROM public.cms_landing_pages lp
  WHERE lp.slug = 'home'
  LIMIT 1;
$$;


--
-- Name: get_system_communication_timeline_v1(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_communication_timeline_v1(p_limit integer DEFAULT 40, p_before_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_limit integer := least(greatest(coalesce(p_limit, 40), 1), 50);
  v_before_ts timestamptz := null;
  v_before_id text := null;
begin
  if v_user_id is null or v_org_id is null then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  select profile.role_id into v_role_id
  from public.profiles profile
  where profile.id = v_user_id and profile.org_id = v_org_id
  limit 1;
  if not found then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  if nullif(trim(coalesce(p_before_cursor, '')), '') is not null then
    v_before_ts := nullif(split_part(p_before_cursor, '|', 1), '')::timestamptz;
    v_before_id := nullif(split_part(p_before_cursor, '|', 2), '');
  end if;

  return (
    with visible as materialized (
      select
        note.id, note.module_id, note.record_id, note.content, note.author_id, note.author_name,
        note.mention_user_ids, note.mention_role_ids, note.created_at, note.reply_to, note.source_type,
        note.metadata, note.is_edited, note.edited_at,
        (
          note.author_id = v_user_id
          or read_state.read_at is not null
          or read_state.dismissed_at is not null
          or (
            cursor_state.read_through_at is not null and (
              note.created_at < cursor_state.read_through_at
              or (note.created_at = cursor_state.read_through_at and note.id::text <= coalesce(cursor_state.read_through_id, note.id::text))
            )
          )
        ) as is_read
      from public.notes note
      left join lateral (
        select inbox.category, inbox.target_user_ids, inbox.target_role_ids
        from public.notification_inbox_items inbox
        where inbox.org_id = v_org_id
          and inbox.section = 'notes'
          and inbox.source_type = 'note'
          and inbox.source_id = note.id::text
        order by inbox.last_event_at desc, inbox.created_at desc, inbox.id desc
        limit 1
      ) inbox on true
      left join public.notification_read_states read_state
        on read_state.org_id = v_org_id
       and read_state.user_id = v_user_id
       and read_state.section = 'notes'
       and read_state.source_type = 'note'
       and read_state.source_id = note.id::text
      left join public.communication_read_cursors cursor_state
        on cursor_state.org_id = v_org_id
       and cursor_state.user_id = v_user_id
       and cursor_state.channel = 'internal'
       and cursor_state.conversation_key = 'system'
      where note.org_id = v_org_id
        and public.kalam_resolve_agent_conversation_key_v1(note.metadata) is null
        and public.kalam_internal_message_is_system_v2(note.source_type, note.metadata, inbox.category)
        and public.kalam_can_access_internal_message_v2(
          false,
          coalesce(inbox.target_user_ids, '{}'::uuid[]),
          coalesce(inbox.target_role_ids, '{}'::uuid[]),
          note.author_id,
          note.mention_user_ids,
          note.mention_role_ids,
          note.source_type,
          note.metadata,
          coalesce(inbox.category, 'system'),
          v_user_id,
          v_role_id
        )
    ), unread as (
      select count(*) filter (where not is_read)::integer as unread_count from visible
    ), windowed as (
      select * from visible
      where v_before_ts is null
         or created_at < v_before_ts
         or (created_at = v_before_ts and id::text < coalesce(v_before_id, ''))
      order by created_at desc, id desc
      limit v_limit + 1
    ), page_desc as (
      select * from windowed order by created_at desc, id desc limit v_limit
    ), page as (
      select * from page_desc order by created_at asc, id asc
    ), earliest as (
      select created_at, id::text as id_text from page order by created_at asc, id asc limit 1
    )
    select jsonb_build_object(
      'items', coalesce((
        select jsonb_agg(
          to_jsonb(page) || jsonb_build_object(
            'metadata',
            coalesce(page.metadata, '{}'::jsonb) || jsonb_build_object(
              'read_receipts',
              public.kalam_message_read_receipts_v1(
                v_org_id,
                'internal',
                'system',
                page.author_id,
                page.created_at,
                page.id
              )
            )
          )
          order by page.created_at asc, page.id asc
        )
        from page
      ), '[]'::jsonb),
      'unread_count', coalesce((select unread_count from unread), 0),
      'first_unread_id', (select id::text from page where not is_read order by created_at asc, id asc limit 1),
      'has_more_before', (select count(*) > v_limit from windowed),
      'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
      'read_model', 'cursor'
    )
  );
end;
$$;


--
-- Name: get_system_messaging_unread_total_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_system_messaging_unread_total_v1() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  with me as (
    select profile.id as user_id, profile.org_id, profile.role_id
    from public.profiles profile
    where profile.id = auth.uid()
      and profile.org_id = public.current_org_id()
    limit 1
  ), system_candidates as (
    select
      note.id,
      note.author_id,
      note.created_at,
      me.user_id,
      me.org_id
    from me
    join public.notification_inbox_items inbox
      on inbox.org_id = me.org_id
     and inbox.section = 'notes'
     and inbox.source_type = 'note'
    join public.notes note
      on note.org_id = inbox.org_id
     and note.id = case
       when inbox.source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         then inbox.source_id::uuid
       else null
     end
    where (
      lower(trim(coalesce(inbox.category, ''))) in ('system', 'assistant')
      or lower(trim(coalesce(
        nullif(note.source_type, ''),
        coalesce(note.metadata, '{}'::jsonb)->>'source_type',
        ''
      ))) in ('system', 'ai', 'assistant')
      or coalesce(note.metadata, '{}'::jsonb) ?| array[
        'workflow_id',
        'automation_rule_id',
        'process_automation_rule_id',
        'workflow_action_type',
        'scheduled_report_id'
      ]
    )
      and (
        me.user_id = any(coalesce(inbox.target_user_ids, '{}'::uuid[]))
        or me.user_id = any(coalesce(note.mention_user_ids, '{}'::uuid[]))
        or (
          me.role_id is not null
          and (
            me.role_id = any(coalesce(inbox.target_role_ids, '{}'::uuid[]))
            or me.role_id = any(coalesce(note.mention_role_ids, '{}'::uuid[]))
          )
        )
      )

    union all

    -- Legacy rows without an inbox item remain visible only to their explicit recipients.
    select
      note.id,
      note.author_id,
      note.created_at,
      me.user_id,
      me.org_id
    from me
    join public.notes note
      on note.org_id = me.org_id
    where (
      lower(trim(coalesce(
        nullif(note.source_type, ''),
        coalesce(note.metadata, '{}'::jsonb)->>'source_type',
        ''
      ))) in ('system', 'ai', 'assistant')
      or coalesce(note.metadata, '{}'::jsonb) ?| array[
        'workflow_id',
        'automation_rule_id',
        'process_automation_rule_id',
        'workflow_action_type',
        'scheduled_report_id'
      ]
    )
      and not exists (
        select 1
        from public.notification_inbox_items inbox
        where inbox.org_id = me.org_id
          and inbox.section = 'notes'
          and inbox.source_type = 'note'
          and inbox.source_id = note.id::text
      )
      and (
        me.user_id = any(coalesce(note.mention_user_ids, '{}'::uuid[]))
        or (
          me.role_id is not null
          and me.role_id = any(coalesce(note.mention_role_ids, '{}'::uuid[]))
        )
      )
  )
  select count(*) filter (
    where candidate.author_id is distinct from candidate.user_id
      and read_state.read_at is null
      and read_state.dismissed_at is null
      and (
        cursor_state.read_through_at is null
        or candidate.created_at > cursor_state.read_through_at
        or (
          candidate.created_at = cursor_state.read_through_at
          and candidate.id::text > coalesce(cursor_state.read_through_id, '')
        )
      )
  )::integer
  from system_candidates candidate
  left join public.notification_read_states read_state
    on read_state.org_id = candidate.org_id
   and read_state.user_id = candidate.user_id
   and read_state.section = 'notes'
   and read_state.source_type = 'note'
   and read_state.source_id = candidate.id::text
  left join public.communication_read_cursors cursor_state
    on cursor_state.org_id = candidate.org_id
   and cursor_state.user_id = candidate.user_id
   and cursor_state.channel = 'internal'
   and cursor_state.conversation_key = 'system';
$_$;


--
-- Name: global_search_build_index_document(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_build_index_document(p_module text, p_payload jsonb) RETURNS TABLE(title text, subtitle text, search_text text, phone_digits text, matched_keys text[], assignee_user_id text, assignee_role_id text, assignee_type text)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_available_keys text[] := array[]::text[];
  v_config_keys text[] := array[]::text[];
  v_generic_keys text[] := array[]::text[];
  v_candidate_keys text[] := array[]::text[];
  v_keys text[] := array[]::text[];
  v_phone_keys text[] := array[]::text[];
  v_value text;
  v_assignee_id text;
  v_assignee_role_id text;
  v_assignee_type text;
begin
  select coalesce(array_agg(key), array[]::text[])
    into v_available_keys
  from jsonb_object_keys(v_payload) key;

  v_config_keys := case p_module
    when 'customers' then array[
      'full_name', 'first_name', 'last_name', 'business_name', 'legal_name', 'mobile_1',
      'mobile_2', 'phone', 'assistant_phone', 'system_code', 'legacy_contact_code',
      'accounting_code', 'email', 'national_code', 'national_id', 'city', 'address', 'notes'
    ]
    when 'suppliers' then array[
      'business_name', 'first_name', 'last_name', 'mobile_1', 'mobile_2', 'phone',
      'system_code', 'email', 'city', 'address'
    ]
    when 'employees' then array[
      'full_name', 'first_name', 'last_name', 'legacy_system_code', 'system_code',
      'national_code', 'mobile_1', 'phone', 'job_title'
    ]
    when 'products' then array[
      'name', 'system_code', 'manual_code', 'accounting_code', 'product_identifier',
      'category', 'product_type', 'description'
    ]
    when 'invoices' then array[
      'name', 'system_code', 'legacy_invoice_number', 'status', 'legacy_status', 'sale_source'
    ]
    when 'purchase_invoices' then array[
      'name', 'system_code', 'legacy_invoice_number', 'status', 'legacy_status'
    ]
    when 'tasks' then array['name', 'title', 'system_code', 'status', 'description']
    when 'projects' then array['name', 'title', 'system_code', 'status', 'description', 'customer_name']
    else array[]::text[]
  end;

  select coalesce(array_agg(key order by key), array[]::text[])
    into v_generic_keys
  from jsonb_each_text(v_payload) fields(key, value)
  where key ~* '(name|title|code|number|phone|mobile|email|subject|description|notes|status|city|address|category|type|identifier|external|indicator|department|goal|body|position|group|catalog|manual|legacy|accounting|national)'
    and nullif(trim(value), '') is not null;

  v_candidate_keys := case
    when cardinality(v_config_keys) > 0 then v_config_keys
    else v_generic_keys
  end;

  select coalesce(array_agg(key order by ord), array[]::text[])
    into v_keys
  from unnest(v_candidate_keys) with ordinality item(key, ord)
  where key = any(v_available_keys)
    and key <> 'id'
    and nullif(trim(v_payload ->> key), '') is not null;

  select coalesce(array_agg(key order by ord), array[]::text[])
    into v_phone_keys
  from unnest(v_keys) with ordinality item(key, ord)
  where key ~* '(phone|mobile|tel|sender|recipient|source_number|destination_number|respondent_phone)';

  title := '[بدون عنوان]';
  foreach v_value in array array['full_name', 'business_name', 'legal_name', 'name', 'title', 'first_name', 'last_name', 'system_code']
  loop
    if v_value = any(v_available_keys) and nullif(trim(v_payload ->> v_value), '') is not null then
      title := trim(v_payload ->> v_value);
      exit;
    end if;
  end loop;

  subtitle := '';
  foreach v_value in array array['system_code', 'manual_code', 'legacy_contact_code', 'legacy_system_code', 'legacy_invoice_number', 'accounting_code', 'catalog_code', 'external_number', 'indicator_number', 'mobile_1', 'phone']
  loop
    if v_value = any(v_available_keys) and nullif(trim(v_payload ->> v_value), '') is not null then
      subtitle := trim(v_payload ->> v_value);
      exit;
    end if;
  end loop;

  select coalesce(string_agg(trim(v_payload ->> key), ' ' order by ord), '')
    into search_text
  from unnest(v_keys) with ordinality item(key, ord);

  select coalesce(string_agg(public.global_search_phone_digits(coalesce(v_payload ->> key, '')), ' ' order by ord), '')
    into phone_digits
  from unnest(v_phone_keys) with ordinality item(key, ord)
  where nullif(trim(v_payload ->> key), '') is not null;

  matched_keys := coalesce(v_keys, array[]::text[]);

  v_assignee_id := nullif(trim(coalesce(v_payload ->> 'assignee_id', '')), '');
  v_assignee_role_id := nullif(trim(coalesce(v_payload ->> 'assignee_role_id', '')), '');
  v_assignee_type := lower(nullif(trim(coalesce(v_payload ->> 'assignee_type', '')), ''));
  if v_assignee_type is null then
    v_assignee_type := case when v_assignee_role_id is not null then 'role' else 'user' end;
  end if;

  assignee_type := v_assignee_type;
  assignee_role_id := coalesce(v_assignee_role_id, case when v_assignee_type = 'role' then v_assignee_id else null end);
  assignee_user_id := case when v_assignee_type = 'role' then null else v_assignee_id end;

  return next;
end;
$$;


--
-- Name: global_search_delete_document(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_delete_document(p_module_id text, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.kalam_try_uuid(coalesce(p_record, '{}'::jsonb) ->> 'org_id');
  v_record_id text := nullif(trim(coalesce(coalesce(p_record, '{}'::jsonb) ->> 'id', '')), '');
begin
  if v_org_id is null or v_record_id is null then
    return;
  end if;

  delete from public.global_search_documents
  where org_id = v_org_id
    and module_id = lower(trim(coalesce(p_module_id, '')))
    and record_id = v_record_id;
end;
$$;


--
-- Name: global_search_normalize_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_normalize_text(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select regexp_replace(
    replace(
      replace(
        replace(
          replace(
            replace(
              replace(
                translate(coalesce(value, ''), '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789'),
                chr(8204),
                ' '
              ),
              'ك',
              'ک'
            ),
            'ي',
            'ی'
          ),
          'ى',
          'ی'
        ),
        'ۀ',
        'ه'
      ),
      'ة',
      'ه'
    ),
    '\s+',
    ' ',
    'g'
  );
$$;


--
-- Name: global_search_phone_digits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_phone_digits(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select regexp_replace(public.global_search_normalize_text(value), '\D', '', 'g');
$$;


--
-- Name: global_search_phone_variants(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_phone_variants(value text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  digits text := public.global_search_phone_digits(value);
  variants text[] := array[]::text[];
begin
  if digits = '' then
    return variants;
  end if;

  variants := variants || digits;

  if digits like '0098%' then
    variants := variants || substr(digits, 3);
    variants := variants || ('0' || substr(digits, 5));
    variants := variants || substr(digits, 5);
  elsif digits like '98%' then
    variants := variants || ('0' || substr(digits, 3));
    variants := variants || substr(digits, 3);
  elsif digits like '0%' then
    variants := variants || ('98' || substr(digits, 2));
    variants := variants || substr(digits, 2);
  else
    variants := variants || ('0' || digits);
    variants := variants || ('98' || digits);
  end if;

  return array(select distinct item from unnest(variants) item where item <> '');
end;
$$;


--
-- Name: global_search_records(text, text[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_records(p_query text, p_modules text[] DEFAULT NULL::text[], p_limit_per_module integer DEFAULT 5, p_offset integer DEFAULT 0) RETURNS TABLE(module_id text, record_id text, title text, subtitle text, matched_fields jsonb, payload jsonb, score numeric, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_query text := lower(public.global_search_normalize_text(p_query));
  v_phone_variants text[] := public.global_search_phone_variants(p_query);
  v_limit integer := greatest(1, least(coalesce(p_limit_per_module, 5), 30));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid;
  v_permissions jsonb := '{}'::jsonb;
  v_allowed_role_ids text[] := array[]::text[];
  v_allowed_user_ids text[] := array[]::text[];
begin
  if v_user_id is null or v_org_id is null or length(v_query) < 2 then
    return;
  end if;

  select profile.role_id, coalesce(role.permissions, '{}'::jsonb)
    into v_role_id, v_permissions
  from public.profiles profile
  left join public.org_roles role
    on role.id = profile.role_id
   and role.org_id = profile.org_id
  where profile.id = v_user_id
    and profile.org_id = v_org_id
  limit 1;

  if not found then
    return;
  end if;

  select coalesce(array_agg(role.id::text), array[]::text[])
    into v_allowed_role_ids
  from public.org_roles role
  where role.org_id = v_org_id
    and (role.id = v_role_id or role.parent_id = v_role_id);

  select coalesce(array_agg(profile.id::text), array[]::text[])
    into v_allowed_user_ids
  from public.profiles profile
  where profile.org_id = v_org_id
    and (profile.id = v_user_id or profile.role_id::text = any(v_allowed_role_ids));

  return query execute $search$
    with requested_modules as (
      select distinct requested.module_id
      from unnest($1::text[]) as requested(module_id)
      join public.global_search_module_registry registry
        on registry.module_id = requested.module_id
       and registry.is_enabled
      where requested.module_id ~ '^[a-zA-Z_][a-zA-Z0-9_]*$'
    ),
    permitted_modules as (
      select
        requested.module_id,
        coalesce($2::jsonb -> requested.module_id, '{}'::jsonb) as module_permissions,
        coalesce(
          nullif(($2::jsonb -> requested.module_id ->> 'record_scope'), ''),
          case when coalesce(($2::jsonb -> requested.module_id ->> 'view')::boolean, true) then 'all' else 'own' end
        ) as record_scope
      from requested_modules requested
      where not (
        coalesce(($2::jsonb -> requested.module_id ->> 'view')::boolean, true) = false
        and coalesce(
          nullif(($2::jsonb -> requested.module_id ->> 'record_scope'), ''),
          case when coalesce(($2::jsonb -> requested.module_id ->> 'view')::boolean, true) then 'all' else 'own' end
        ) = 'all'
      )
    ),
    candidate_rows as materialized (
      select
        indexed.module_id,
        indexed.record_id,
        indexed.title,
        indexed.subtitle,
        indexed.payload,
        indexed.matched_keys,
        indexed.phone_digits,
        indexed.created_at,
        permitted.module_permissions
      from public.global_search_documents indexed
      join permitted_modules permitted on permitted.module_id = indexed.module_id
      where indexed.org_id = $3::uuid
        and (
          lower(public.global_search_normalize_text(indexed.search_text)) like '%' || $8 || '%'
          or exists (
            select 1
            from unnest($9::text[]) as phone_variant(value)
            where phone_variant.value <> ''
              and indexed.phone_digits like '%' || phone_variant.value || '%'
          )
        )
        and (
          permitted.record_scope = 'all'
          or (
            permitted.record_scope = 'own'
            and coalesce(indexed.assignee_type, 'user') <> 'role'
            and indexed.assignee_user_id = $4::text
          )
          or (
            permitted.record_scope = 'team'
            and (
              (coalesce(indexed.assignee_type, 'user') <> 'role' and indexed.assignee_user_id = $4::text)
              or (coalesce(indexed.assignee_type, 'user') = 'role' and indexed.assignee_role_id = $5::text)
            )
          )
          or (
            permitted.record_scope = 'subtree'
            and (
              (coalesce(indexed.assignee_type, 'user') <> 'role' and indexed.assignee_user_id = any($6::text[]))
              or (coalesce(indexed.assignee_type, 'user') = 'role' and indexed.assignee_role_id = any($7::text[]))
            )
          )
        )
    ),
    matched_rows as materialized (
      select
        candidate.module_id,
        candidate.record_id,
        candidate.title,
        candidate.subtitle,
        candidate.created_at,
        fields.matched_fields,
        (
          case
            when lower(public.global_search_normalize_text(candidate.title)) = $8 then 80
            when lower(public.global_search_normalize_text(candidate.title)) like $8 || '%' then 28
            when lower(public.global_search_normalize_text(candidate.title)) like '%' || $8 || '%' then 10
            else 0
          end
          + case
              when lower(public.global_search_normalize_text(candidate.subtitle)) = $8 then 24
              when lower(public.global_search_normalize_text(candidate.subtitle)) like $8 || '%' then 10
              when lower(public.global_search_normalize_text(candidate.subtitle)) like '%' || $8 || '%' then 4
              else 0
            end
          + case when exists (
              select 1
              from unnest($9::text[]) as phone_variant(value)
              where phone_variant.value <> ''
                and candidate.phone_digits like '%' || phone_variant.value || '%'
            ) then 24 else 0 end
          + coalesce(array_length(candidate.matched_keys, 1), 0)
        )::numeric as score
      from candidate_rows candidate
      cross join lateral (
        select coalesce(jsonb_agg(match_key), '[]'::jsonb) as matched_fields
        from unnest(candidate.matched_keys) as matched(match_key)
        where coalesce((candidate.module_permissions -> 'fields' ->> match_key)::boolean, true)
          and (
            lower(public.global_search_normalize_text(coalesce(candidate.payload ->> match_key, ''))) like '%' || $8 || '%'
            or exists (
              select 1
              from unnest($9::text[]) as phone_variant(value)
              where phone_variant.value <> ''
                and public.global_search_phone_digits(coalesce(candidate.payload ->> match_key, '')) like '%' || phone_variant.value || '%'
            )
          )
      ) fields
      where jsonb_array_length(fields.matched_fields) > 0
    ),
    ranked_rows as (
      select
        matched.*,
        row_number() over (
          partition by matched.module_id
          order by matched.score desc, matched.created_at desc nulls last, matched.record_id
        ) as module_rank
      from matched_rows matched
    )
    select
      ranked.module_id,
      ranked.record_id,
      ranked.title,
      ranked.subtitle,
      ranked.matched_fields,
      jsonb_build_object('id', ranked.record_id, 'created_at', ranked.created_at) as payload,
      ranked.score,
      ranked.created_at
    from ranked_rows ranked
    where ranked.module_rank > $10::integer
      and ranked.module_rank <= ($10::integer + $11::integer)
  $search$
  using coalesce(p_modules, array[]::text[]), v_permissions, v_org_id, v_user_id, v_role_id,
    v_allowed_user_ids, v_allowed_role_ids, v_query, v_phone_variants, v_offset, v_limit;
end;
$_$;


--
-- Name: global_search_records_live(text, text[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_records_live(p_query text, p_modules text[] DEFAULT NULL::text[], p_limit_per_module integer DEFAULT 5, p_offset integer DEFAULT 0) RETURNS TABLE(module_id text, record_id text, title text, subtitle text, matched_fields jsonb, payload jsonb, score numeric, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_query text := lower(public.global_search_normalize_text(p_query));
  v_phone_variants text[] := public.global_search_phone_variants(p_query);
  v_limit integer := greatest(1, least(coalesce(p_limit_per_module, 5), 30));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid;
  v_permissions jsonb := '{}'::jsonb;
  v_module_permissions jsonb;
  v_record_scope text;
  v_allowed_role_ids text[] := array[]::text[];
  v_allowed_user_ids text[] := array[]::text[];
  v_module text;
  v_columns text[];
  v_config_keys text[] := array[]::text[];
  v_generic_keys text[];
  v_candidate_keys text[];
  v_keys text[];
  v_title_keys text[];
  v_subtitle_keys text[];
  v_payload_keys text[];
  v_concat_expr text;
  v_match_expr text;
  v_title_expr text;
  v_subtitle_expr text;
  v_payload_fields text;
  v_payload_expr text;
  v_phone_condition text;
  v_created_expr text;
  v_scope_condition text;
  v_assignee_type_expr text;
  v_user_assignee_expr text;
  v_role_assignee_expr text;
  v_rank_expr text;
  v_sql text;
begin
  if v_user_id is null or v_org_id is null or length(v_query) < 2 then
    return;
  end if;

  select p.role_id, coalesce(r.permissions, '{}'::jsonb)
    into v_role_id, v_permissions
  from public.profiles p
  left join public.org_roles r
    on r.id = p.role_id
   and r.org_id = p.org_id
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if not found then
    return;
  end if;

  select coalesce(array_agg(r.id::text), array[]::text[])
    into v_allowed_role_ids
  from public.org_roles r
  where r.org_id = v_org_id
    and (r.id = v_role_id or r.parent_id = v_role_id);

  select coalesce(array_agg(p.id::text), array[]::text[])
    into v_allowed_user_ids
  from public.profiles p
  where p.org_id = v_org_id
    and (p.id = v_user_id or p.role_id::text = any(v_allowed_role_ids));

  foreach v_module in array coalesce(p_modules, array[]::text[])
  loop
    if v_module !~ '^[a-zA-Z_][a-zA-Z0-9_]*$'
      or to_regclass(format('public.%I', v_module)) is null then
      continue;
    end if;

    v_module_permissions := coalesce(v_permissions -> v_module, '{}'::jsonb);
    v_record_scope := coalesce(
      nullif(v_module_permissions ->> 'record_scope', ''),
      case when coalesce((v_module_permissions ->> 'view')::boolean, true) then 'all' else 'own' end
    );

    if coalesce((v_module_permissions ->> 'view')::boolean, true) = false
      and v_record_scope = 'all' then
      continue;
    end if;

    select array_agg(a.attname::text order by a.attnum)
      into v_columns
    from pg_catalog.pg_attribute a
    where a.attrelid = to_regclass(format('public.%I', v_module))
      and a.attnum > 0
      and not a.attisdropped;

    if v_columns is null or not ('id' = any(v_columns)) then
      continue;
    end if;

    v_config_keys := case v_module
      when 'customers' then array[
        'full_name', 'first_name', 'last_name', 'business_name', 'legal_name', 'mobile_1',
        'mobile_2', 'phone', 'assistant_phone', 'system_code', 'legacy_contact_code',
        'accounting_code', 'email', 'national_code', 'national_id', 'city', 'address', 'notes'
      ]
      when 'suppliers' then array[
        'business_name', 'first_name', 'last_name', 'mobile_1', 'mobile_2', 'phone',
        'system_code', 'email', 'city', 'address'
      ]
      when 'employees' then array[
        'full_name', 'first_name', 'last_name', 'legacy_system_code', 'system_code',
        'national_code', 'mobile_1', 'phone', 'job_title'
      ]
      when 'products' then array[
        'name', 'system_code', 'manual_code', 'accounting_code', 'product_identifier',
        'category', 'product_type', 'description'
      ]
      when 'invoices' then array[
        'name', 'system_code', 'legacy_invoice_number', 'status', 'legacy_status', 'sale_source'
      ]
      when 'purchase_invoices' then array[
        'name', 'system_code', 'legacy_invoice_number', 'status', 'legacy_status'
      ]
      when 'tasks' then array['name', 'title', 'system_code', 'status', 'description']
      when 'projects' then array['name', 'title', 'system_code', 'status', 'description', 'customer_name']
      else array[]::text[]
    end;

    select array_agg(a.attname::text order by a.attnum)
      into v_generic_keys
    from pg_catalog.pg_attribute a
    where a.attrelid = to_regclass(format('public.%I', v_module))
      and a.attnum > 0
      and not a.attisdropped
      and a.atttypid in ('text'::regtype, 'character varying'::regtype)
      and a.attname ~* '(name|title|code|number|phone|mobile|email|subject|description|notes|status|city|address|category|type|identifier|external|indicator|department|goal|body|position|group|catalog|manual|legacy|accounting|national)';

    v_candidate_keys := case
      when cardinality(v_config_keys) > 0 then v_config_keys
      else coalesce(v_generic_keys, array[]::text[])
    end;

    select array_agg(key order by ord)
      into v_keys
    from unnest(v_candidate_keys) with ordinality item(key, ord)
    where key = any(v_columns)
      and key <> 'id'
      and coalesce((v_module_permissions -> 'fields' ->> key)::boolean, true);

    if v_keys is null or cardinality(v_keys) = 0 then
      continue;
    end if;

    select array_agg(key order by ord)
      into v_title_keys
    from unnest(array['full_name', 'business_name', 'legal_name', 'name', 'title', 'first_name', 'last_name', 'system_code']) with ordinality item(key, ord)
    where key = any(v_columns)
      and coalesce((v_module_permissions -> 'fields' ->> key)::boolean, true);

    select array_agg(key order by ord)
      into v_subtitle_keys
    from unnest(array['system_code', 'manual_code', 'legacy_contact_code', 'legacy_system_code', 'legacy_invoice_number', 'accounting_code', 'catalog_code', 'external_number', 'indicator_number', 'mobile_1', 'phone']) with ordinality item(key, ord)
    where key = any(v_columns)
      and coalesce((v_module_permissions -> 'fields' ->> key)::boolean, true);

    select array_agg(key order by first_ord)
      into v_payload_keys
    from (
      select key, min(ord) as first_ord
      from unnest(coalesce(v_title_keys, array[]::text[]) || coalesce(v_subtitle_keys, array[]::text[])) with ordinality item(key, ord)
      group by key
    ) payload_fields;

    select string_agg(format('coalesce(t.%I::text, '''')', key), ' || '' '' || ' order by ord)
      into v_concat_expr
    from unnest(v_keys) with ordinality item(key, ord);

    select 'coalesce(' || string_agg(format('nullif(t.%I::text, '''')', key), ', ' order by ord) || ', ''[بدون عنوان]'')'
      into v_title_expr
    from unnest(coalesce(v_title_keys, array[]::text[])) with ordinality item(key, ord);

    if v_title_expr is null then
      v_title_expr := '''[بدون عنوان]''';
    end if;

    select 'coalesce(' || string_agg(format('nullif(t.%I::text, '''')', key), ', ' order by ord) || ', '''')'
      into v_subtitle_expr
    from unnest(coalesce(v_subtitle_keys, array[]::text[])) with ordinality item(key, ord);

    if v_subtitle_expr is null then
      v_subtitle_expr := '''''';
    end if;

    select string_agg(format(', %L, t.%I', key, key), '' order by ord)
      into v_payload_fields
    from unnest(coalesce(v_payload_keys, array[]::text[])) with ordinality item(key, ord);

    v_created_expr := case when 'created_at' = any(v_columns) then 't.created_at' else 'null::timestamptz' end;
    v_payload_expr := 'jsonb_strip_nulls(jsonb_build_object(''id'', t.id::text, ''created_at'', ' ||
      v_created_expr || coalesce(v_payload_fields, '') || '))';

    select '(select coalesce(jsonb_agg(key), ''[]''::jsonb) from (values ' ||
      string_agg(
        format(
          '(%L, (lower(public.global_search_normalize_text(coalesce(t.%I::text, ''''))) like ''%%'' || $1 || ''%%''%s))',
          key,
          key,
          case
            when key ~* '(phone|mobile|tel|sender|recipient|source_number|destination_number|respondent_phone)' then
              format(' or exists (select 1 from unnest($2::text[]) q where q <> '''' and public.global_search_phone_digits(coalesce(t.%I::text, '''')) like ''%%'' || q || ''%%'')', key)
            else ''
          end
        ),
        ', ' order by ord
      ) ||
      ') matches(key, matched) where matched)'
      into v_match_expr
    from unnest(v_keys) with ordinality item(key, ord);

    select string_agg(
      format('exists (select 1 from unnest($2::text[]) q where q <> '''' and public.global_search_phone_digits(coalesce(t.%I::text, '''')) like ''%%'' || q || ''%%'')', key),
      ' or ' order by ord
    )
      into v_phone_condition
    from unnest(v_keys) with ordinality item(key, ord)
    where key ~* '(phone|mobile|tel|sender|recipient|source_number|destination_number|respondent_phone)';

    if v_phone_condition is null then
      v_phone_condition := 'false';
    end if;

    v_scope_condition := 'true';
    if v_record_scope <> 'all' then
      if not ('assignee_id' = any(v_columns)) and not ('assignee_role_id' = any(v_columns)) then
        continue;
      end if;

      v_user_assignee_expr := case
        when 'assignee_id' = any(v_columns) then 't.assignee_id::text'
        else 'null::text'
      end;
      v_role_assignee_expr := case
        when 'assignee_role_id' = any(v_columns) and 'assignee_id' = any(v_columns) and 'assignee_type' = any(v_columns) then
          'coalesce(t.assignee_role_id::text, case when lower(coalesce(t.assignee_type::text, '''')) = ''role'' then t.assignee_id::text end)'
        when 'assignee_role_id' = any(v_columns) then 't.assignee_role_id::text'
        when 'assignee_id' = any(v_columns) and 'assignee_type' = any(v_columns) then
          'case when lower(coalesce(t.assignee_type::text, '''')) = ''role'' then t.assignee_id::text end'
        else 'null::text'
      end;
      v_assignee_type_expr := case
        when 'assignee_type' = any(v_columns) and 'assignee_role_id' = any(v_columns) then
          'lower(coalesce(nullif(t.assignee_type::text, ''''), case when t.assignee_role_id is not null then ''role'' else ''user'' end))'
        when 'assignee_type' = any(v_columns) then 'lower(coalesce(nullif(t.assignee_type::text, ''''), ''user''))'
        when 'assignee_role_id' = any(v_columns) then 'case when t.assignee_role_id is not null then ''role'' else ''user'' end'
        else '''user'''
      end;

      v_scope_condition := case v_record_scope
        when 'own' then format('(%s <> ''role'' and %s = $5::text)', v_assignee_type_expr, v_user_assignee_expr)
        when 'team' then format('((%s <> ''role'' and %s = $5::text) or (%s = ''role'' and %s = $6::text))', v_assignee_type_expr, v_user_assignee_expr, v_assignee_type_expr, v_role_assignee_expr)
        when 'subtree' then format('((%s <> ''role'' and %s = any($7::text[])) or (%s = ''role'' and %s = any($8::text[])))', v_assignee_type_expr, v_user_assignee_expr, v_assignee_type_expr, v_role_assignee_expr)
        else 'false'
      end;
    end if;

    v_rank_expr := format(
      'jsonb_array_length(match_data.matched_fields)::numeric
       + case
           when lower(public.global_search_normalize_text(%1$s)) = $1 then 80
           when lower(public.global_search_normalize_text(%1$s)) like $1 || ''%%'' then 28
           when lower(public.global_search_normalize_text(%1$s)) like ''%%'' || $1 || ''%%'' then 10
           else 0
         end
       + case when %2$s then 24 else 0 end',
      v_title_expr,
      v_phone_condition
    );

    v_sql := format(
      'select %L::text as module_id,
              t.id::text as record_id,
              %s::text as title,
              %s::text as subtitle,
              match_data.matched_fields,
              %s as payload,
              %s as score,
              %s as created_at
       from public.%I t
       cross join lateral (select (%s) as matched_fields) match_data
       where (%s)
         and (lower(public.global_search_normalize_text(%s)) like ''%%'' || $1 || ''%%'' or %s)
       order by score desc, %s desc nulls last, t.id
       limit $3 offset $4',
      v_module,
      v_title_expr,
      v_subtitle_expr,
      v_payload_expr,
      v_rank_expr,
      v_created_expr,
      v_module,
      v_match_expr,
      v_scope_condition,
      v_concat_expr,
      v_phone_condition,
      v_created_expr
    );

    return query execute v_sql
      using v_query, v_phone_variants, v_limit, v_offset, v_user_id, v_role_id, v_allowed_user_ids, v_allowed_role_ids;
  end loop;
end;
$_$;


--
-- Name: global_search_sync_index_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_sync_index_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if TG_TABLE_SCHEMA <> 'public'
    or TG_TABLE_NAME in ('global_search_index', 'global_search_documents') then
    return coalesce(NEW, OLD);
  end if;

  if TG_OP = 'DELETE' then
    perform public.global_search_delete_document(TG_TABLE_NAME, to_jsonb(OLD));
    return OLD;
  end if;

  perform public.global_search_upsert_document(TG_TABLE_NAME, to_jsonb(NEW));
  return NEW;
end;
$$;


--
-- Name: global_search_upsert_document(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_upsert_document(p_module_id text, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_module_id text := lower(trim(coalesce(p_module_id, '')));
  v_record jsonb := jsonb_strip_nulls(coalesce(p_record, '{}'::jsonb));
  v_org_id uuid := public.kalam_try_uuid(v_record ->> 'org_id');
  v_record_id text := nullif(trim(coalesce(v_record ->> 'id', '')), '');
  v_document record;
  v_search_payload jsonb := '{}'::jsonb;
  v_created_at timestamptz;
begin
  if v_module_id = '' or v_org_id is null or v_record_id is null then
    return;
  end if;

  if not exists (
    select 1
    from public.global_search_module_registry registry
    where registry.module_id = v_module_id
      and registry.is_enabled
  ) then
    delete from public.global_search_documents
    where org_id = v_org_id
      and module_id = v_module_id
      and record_id = v_record_id;
    return;
  end if;

  select *
    into v_document
  from public.global_search_build_index_document(v_module_id, v_record);

  if coalesce(array_length(v_document.matched_keys, 1), 0) = 0 then
    delete from public.global_search_documents
    where org_id = v_org_id
      and module_id = v_module_id
      and record_id = v_record_id;
    return;
  end if;

  select coalesce(jsonb_object_agg(field_key, v_record -> field_key), '{}'::jsonb)
    into v_search_payload
  from unnest(v_document.matched_keys) as matched(field_key)
  where v_record ? field_key;

  begin
    v_created_at := nullif(trim(coalesce(v_record ->> 'created_at', '')), '')::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      v_created_at := null;
  end;

  insert into public.global_search_documents (
    org_id, module_id, record_id, title, subtitle, search_text, phone_digits,
    matched_keys, payload, assignee_user_id, assignee_role_id, assignee_type,
    created_at, updated_at
  )
  values (
    v_org_id,
    v_module_id,
    v_record_id,
    coalesce(v_document.title, '[بدون عنوان]'),
    coalesce(v_document.subtitle, ''),
    coalesce(v_document.search_text, ''),
    coalesce(v_document.phone_digits, ''),
    coalesce(v_document.matched_keys, array[]::text[]),
    v_search_payload,
    v_document.assignee_user_id,
    v_document.assignee_role_id,
    v_document.assignee_type,
    v_created_at,
    now()
  )
  on conflict (org_id, module_id, record_id) do update
  set title = excluded.title,
      subtitle = excluded.subtitle,
      search_text = excluded.search_text,
      phone_digits = excluded.phone_digits,
      matched_keys = excluded.matched_keys,
      payload = excluded.payload,
      assignee_user_id = excluded.assignee_user_id,
      assignee_role_id = excluded.assignee_role_id,
      assignee_type = excluded.assignee_type,
      created_at = excluded.created_at,
      updated_at = excluded.updated_at;
end;
$$;


--
-- Name: grant_saas_consumption_welcome_credit(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_saas_consumption_welcome_credit(p_org_id uuid, p_gift_kind text, p_plan_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ai numeric:=0; v_sms numeric:=0; previous_ai numeric:=0; previous_sms numeric:=0; sms_balance numeric;
begin
 if p_org_id is null or coalesce(p_gift_kind,'') not in ('demo','first_paid_plan') then return jsonb_build_object('success',false); end if;
 -- Serialize before checking the receipt, so retries/concurrent provisioning cannot double-credit.
 perform pg_advisory_xact_lock(hashtextextended(p_org_id::text,585));
 select ai_amount_irt,sms_amount_irt into previous_ai,previous_sms from public.saas_consumption_credit_gifts where org_id=p_org_id and gift_kind=p_gift_kind;
 previous_ai:=coalesce(previous_ai,0); previous_sms:=coalesce(previous_sms,0);
 if p_gift_kind='demo' then
   v_ai:=greatest(0,100000-previous_ai); v_sms:=greatest(0,100000-previous_sms);
 else
   if found then return jsonb_build_object('success',true,'already_granted',true); end if;
   case lower(coalesce(p_plan_code,'')) when 'cloud_starter' then v_ai:=120000; v_sms:=120000;
    when 'cloud_growth' then v_ai:=250000; v_sms:=250000;
    when 'cloud_enterprise' then v_ai:=500000; v_sms:=500000;
    else return jsonb_build_object('success',false,'reason','not_paid_plan'); end case;
   select coalesce(sum(ai_amount_irt),0),coalesce(sum(sms_amount_irt),0) into previous_ai,previous_sms from public.saas_consumption_credit_gifts where org_id=p_org_id;
   v_ai:=greatest(0,v_ai-previous_ai); v_sms:=greatest(0,v_sms-previous_sms);
   previous_ai:=0; previous_sms:=0;
 end if;
 if v_ai=0 and v_sms=0 then return jsonb_build_object('success',true,'already_granted',true); end if;
 insert into public.org_ai_wallets(org_id,status) values(p_org_id,'active') on conflict(org_id) do nothing;
 insert into public.org_sms_wallets(org_id,status) values(p_org_id,'active') on conflict(org_id) do nothing;
 update public.org_ai_wallets set included_quota_irt=included_quota_irt+v_ai,updated_at=now() where org_id=p_org_id;
 update public.org_sms_wallets set included_quota_irt=included_quota_irt+v_sms,updated_at=now() where org_id=p_org_id returning balance_irt into sms_balance;
 insert into public.saas_consumption_credit_gifts(org_id,gift_kind,ai_amount_irt,sms_amount_irt) values(p_org_id,p_gift_kind,previous_ai+v_ai,previous_sms+v_sms)
 on conflict(org_id,gift_kind) do update set ai_amount_irt=excluded.ai_amount_irt,sms_amount_irt=excluded.sms_amount_irt;
 if v_sms>0 then insert into public.org_sms_wallet_transactions(org_id,kind,amount_irt,balance_after_irt,description,metadata) values(p_org_id,'gift',v_sms,sms_balance,'هدیه اعتبار پیامک',jsonb_build_object('gift_kind',p_gift_kind)); end if;
 if v_ai>0 then insert into public.org_ai_credit_grants(org_id,amount_irt,reason,metadata) values(p_org_id,v_ai,'هدیه اعتبار هوش مصنوعی',jsonb_build_object('gift_kind',p_gift_kind)); end if;
 return jsonb_build_object('success',true,'ai_amount_irt',v_ai,'sms_amount_irt',v_sms);
end; $$;


--
-- Name: guard_advertising_campaign_child_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_advertising_campaign_child_org() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_org uuid; v_campaign uuid;
begin
  if to_jsonb(new) ? 'campaign_id' then
    select org_id into v_org from public.advertising_campaigns where id = new.campaign_id;
    if v_org is null or new.org_id is distinct from v_org then
      raise exception 'سازمان رکورد با کمپین همخوان نیست.' using errcode = '23514';
    end if;
  end if;
  if to_jsonb(new) ? 'tool_id' and nullif(to_jsonb(new)->>'tool_id','') is not null then
    select org_id, campaign_id into v_org, v_campaign
    from public.advertising_campaign_tools where id = (to_jsonb(new)->>'tool_id')::uuid;
    if v_org is null or new.org_id is distinct from v_org
       or (to_jsonb(new) ? 'campaign_id' and new.campaign_id is distinct from v_campaign) then
      raise exception 'ابزار با کمپین و سازمان همخوان نیست.' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_advertising_campaign_dispatch_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_advertising_campaign_dispatch_message() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_channel text:=lower(btrim(coalesce(new.channel_type,'')));
  v_raw_message text;
  v_plain_message text;
begin
  if v_channel not in ('sms','email','bot_group','bot_private') then
    return new;
  end if;

  v_raw_message:=coalesce(
    nullif(btrim(new.message_snapshot->>'text'),''),
    nullif(btrim(new.message_snapshot->>'message'),''),
    ''
  );
  v_plain_message:=regexp_replace(v_raw_message,'<[^>]*>','','gi');
  v_plain_message:=regexp_replace(
    v_plain_message,
    '&(nbsp|#160|#xa0);',
    '',
    'gi'
  );
  v_plain_message:=regexp_replace(v_plain_message,'&(amp|apos|quot|lt|gt|#x[0-9a-f]+|#[0-9]+);','x','gi');
  v_plain_message:=replace(replace(replace(v_plain_message,U&'\200E',''),U&'\200F',''),U&'\FEFF','');
  v_plain_message:=regexp_replace(v_plain_message,'[[:space:]]','','g');

  if coalesce(v_plain_message,'')='' then
    raise exception '%', case v_channel
      when 'sms' then 'متن پیامک خالی است؛ پیش از ارسال، متن پیامک را تکمیل کنید.'
      when 'email' then 'متن ایمیل خالی است؛ پیش از ارسال، متن ایمیل را تکمیل کنید.'
      else 'متن پیام بات خالی است؛ پیش از ارسال، متن پیام را تکمیل کنید.'
    end using errcode='22023';
  end if;
  return new;
end;
$$;


--
-- Name: guard_advertising_campaign_recipient_exclusion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_advertising_campaign_recipient_exclusion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_exclusions jsonb;
begin
  if new.source_type <> 'internal' or new.source_module_id is null or new.source_record_id is null then return new; end if;
  select coalesce(config->'excluded_audience_refs','[]'::jsonb) into v_exclusions
  from public.advertising_campaign_tools where id=new.tool_id and org_id=new.org_id;
  if v_exclusions ? (new.source_module_id || ':' || new.source_record_id::text) then return null; end if;
  return new;
end;
$$;


--
-- Name: guard_advertising_campaign_tool_plan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_advertising_campaign_tool_plan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_feature text;
begin
  v_feature := case new.tool_type
    when 'sms' then 'campaign_sms'
    when 'email' then 'campaign_email'
    when 'bot_group' then 'campaign_bot_group'
    when 'bot_private' then 'campaign_bot_private'
    when 'instagram_post' then 'campaign_instagram_post'
    when 'voice_call' then 'campaign_voice_call'
    else null end;
  if new.enabled = true
     and v_feature is not null
     and not public.org_has_plan_feature(new.org_id,v_feature,false) then
    raise exception 'ابزار انتخاب‌شده در پلن سازمان فعال نیست.' using errcode='42501';
  end if;
  return new;
end;
$$;


--
-- Name: guard_ai_agent_task_workflow(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_ai_agent_task_workflow() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(auth.role(), '') = 'service_role' then return new; end if;
  if tg_op = 'INSERT' then
    if new.agent_task_config is not null or new.agent_task_next_run_at is not null
       or new.agent_task_revision <> 0 or new.agent_task_origin_action_id is not null then
      raise exception 'تعریف کار خودکار ایجنت باید از مسیر تأییدشده انجام شود.' using errcode = '42501';
    end if;
    return new;
  end if;
  if old.agent_task_config is null and new.agent_task_config is null
     and old.agent_task_next_run_at is null and new.agent_task_next_run_at is null
     and old.agent_task_revision = new.agent_task_revision
     and old.agent_task_origin_action_id is not distinct from new.agent_task_origin_action_id then return new; end if;
  if new.org_id = public.current_org_id()
     and new.is_active = false
     and (to_jsonb(new) - array['is_active','updated_at','updated_by'])
         = (to_jsonb(old) - array['is_active','updated_at','updated_by']) then return new; end if;
  raise exception 'ویرایش یا فعال‌سازی کار خودکار ایجنت باید دوباره بررسی و تأیید شود.' using errcode = '42501';
end;
$$;


--
-- Name: guard_billboard_operational_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_billboard_operational_status_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if current_setting('app.billboard_status_change_authorized', true) = 'on' then return new; end if;
  if new.status is distinct from old.status or new.related_customer is distinct from old.related_customer
     or new.related_invoice is distinct from old.related_invoice or new.marketing_lead_id is distinct from old.marketing_lead_id
     or new.start_date is distinct from old.start_date or new.end_date is distinct from old.end_date then
    raise exception 'تغییر وضعیت و اطلاعات رزرو تابلو فقط از طریق درخواست تغییر وضعیت مجاز است.';
  end if;
  return new;
end;
$$;


--
-- Name: guard_commission_calculation_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_commission_calculation_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_snapshot jsonb;
begin
  if new.source_type is distinct from 'commission'
    and (tg_op = 'INSERT' or old.source_type is distinct from 'commission') then return new; end if;
  if new.org_id is null or new.org_id is distinct from public.current_org_id() then
    raise exception 'commission_calculation_not_allowed';
  end if;
  if tg_op = 'UPDATE' and (new.org_id is distinct from old.org_id
    or new.employee_id is distinct from old.employee_id or new.source_type is distinct from old.source_type) then
    raise exception 'commission_calculation_scope_immutable';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('commission-employee:' || new.org_id::text || ':' || new.employee_id::text, 0));
  -- Existing payroll functions authorize their lifecycle updates separately.
  -- Release included -> draft with payroll_slip_id cleared must remain possible.
  -- No financial field/period/source may change through this lifecycle exception.
  if tg_op = 'UPDATE'
    and (to_jsonb(new) - array['status','updated_at','payroll_slip_id'])
      is not distinct from (to_jsonb(old) - array['status','updated_at','payroll_slip_id'])
    and (new.status = old.status
      or (old.status <> 'voided' and new.status in ('included_in_payroll','voided'))
      or (old.status = 'included_in_payroll' and new.status in ('proposed','draft') and new.payroll_slip_id is null)) then
    return new;
  end if;
  if public.current_user_has_role_permission_entry('payroll_slips', 'edit', null, true) is not true then
    raise exception 'commission_calculation_not_allowed';
  end if;
  if not exists(select 1 from public.employees where id = new.employee_id and org_id = new.org_id) then
    raise exception 'commission_employee_not_found';
  end if;
  if tg_op = 'UPDATE' and old.status = 'included_in_payroll' then
    raise exception 'commission_already_in_payroll';
  end if;
  if tg_op = 'UPDATE' and old.status = 'voided' then
    raise exception 'commission_voided_history_immutable';
  end if;
  v_snapshot := new.details->'ledger_snapshot';
  if jsonb_typeof(v_snapshot) is distinct from 'array' then
    raise exception 'commission_preview_stale';
  end if;
  if exists (
    with expected as (
      select (x->>'id')::uuid id, (x->>'updated_at')::timestamptz updated_at
      from jsonb_array_elements(v_snapshot) x
    ), actual as (
      select id, updated_at from public.payroll_calculation_entries
      where org_id = new.org_id and employee_id = new.employee_id
        and source_type = 'commission' and status <> 'voided'
    )
    select 1 from expected full join actual using (id)
    where expected.id is null or actual.id is null
      or expected.updated_at is distinct from actual.updated_at
  ) or exists (
    select 1 from jsonb_array_elements(v_snapshot) x group by x->>'id' having count(*) > 1
  ) then raise exception 'commission_preview_stale'; end if;
  -- A cheque changed after the preview: require a fresh calculation, even in another period.
  if jsonb_typeof(new.details->'cheque_snapshot') is distinct from 'array' then
    raise exception 'commission_preview_stale';
  end if;
  -- Serialize a cheque reversal with posting, so its AFTER trigger sees the
  -- committed ledger entry and can retain a review case instead of missing it.
  perform c.id from public.cheques c
  where c.org_id = new.org_id and exists (
    select 1 from jsonb_array_elements(new.details->'cheque_snapshot') x where x->>'id' = c.id::text)
  order by c.id for share;
  if exists (
    select 1 from jsonb_array_elements(new.details->'cheque_snapshot') x
    left join public.cheques c on c.id::text = x->>'id' and c.org_id = new.org_id
    where c.id is null or c.status is distinct from x->>'status'
      or c.cleared_at is distinct from nullif(x->>'cleared_at','')::timestamptz
      or c.spent_date is distinct from nullif(x->>'spent_date','')::date
  ) then raise exception 'commission_receipts_changed'; end if;
  return new;
end;
$$;


--
-- Name: guard_module_field_actions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_module_field_actions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare module_key text:=tg_argv[0]; row_new jsonb; row_old jsonb; permission jsonb;
  action text; field_key text; field_rules jsonb; value_new jsonb; value_old jsonb;
  default_expr text; default_type text; default_value jsonb; pair record; root_key text; column_key text;
begin
  if auth.uid() is null then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op<>'DELETE' then row_new:=to_jsonb(new); end if;
  if tg_op<>'INSERT' then row_old:=to_jsonb(old); end if;
  if public.current_org_id() is null
    or (tg_op<>'DELETE' and nullif(row_new->>'org_id','')::uuid is distinct from public.current_org_id())
    or (tg_op<>'INSERT' and nullif(row_old->>'org_id','')::uuid is distinct from public.current_org_id()) then
    raise exception 'سازمان رکورد با سازمان جاری همخوانی ندارد.' using errcode='42501';
  end if;
  -- Reviewed database triggers maintain derived stock, accounting and process
  -- values on behalf of the authorized parent write. Do not require users to
  -- acquire direct editing rights to those dependent modules.
  if pg_trigger_depth()>1 then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  action:=case tg_op when 'INSERT' then 'create' when 'UPDATE' then 'edit' else 'delete' end;
  if not public.current_user_can_module_field(module_key,action) then
    raise exception 'دسترسی انجام این عملیات در ماژول را ندارید.' using errcode='42501';
  end if;
  if tg_op='DELETE' then return old; end if;
  select r.permissions->module_key into permission from public.user_organization_memberships m
    join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
    where m.user_id=auth.uid() and m.org_id=public.current_org_id() and m.is_active limit 1;
  for field_key,field_rules in select key,value from jsonb_each(coalesce(permission->'field_actions','{}')) loop
    if field_key in ('id','org_id','system_code','created_at','created_by','updated_at','updated_by') then continue; end if;
    if field_key like '\_\_%' escape '\' then continue; end if;
    if position('.' in field_key)>0 then
      root_key:=split_part(field_key,'.',1); column_key:=split_part(field_key,'.',2);
      if jsonb_typeof(row_new->root_key)<>'array' and jsonb_typeof(row_old->root_key)<>'array' then continue; end if;
      -- Stable row identities preserve permissions when table rows are reordered.
      for pair in
        with n as (select coalesce(value->>'id',value->>'key',ordinality::text) id,value from jsonb_array_elements(case when jsonb_typeof(row_new->root_key)='array' then row_new->root_key else '[]'::jsonb end) with ordinality),
             o as (select coalesce(value->>'id',value->>'key',ordinality::text) id,value from jsonb_array_elements(case when jsonb_typeof(row_old->root_key)='array' then row_old->root_key else '[]'::jsonb end) with ordinality)
        select coalesce(n.value->column_key,n.value->'specs'->column_key) nv,coalesce(o.value->column_key,o.value->'specs'->column_key) ov,
          o.id is null added from n full join o using(id)
      loop
        if pair.nv is not distinct from pair.ov then continue; end if;
        if coalesce(pair.nv,'null') not in ('null'::jsonb,'""'::jsonb,'[]'::jsonb) and not public.current_user_can_module_field(module_key,case when pair.added then 'create' else 'edit' end,field_key)
          or not pair.added and not public.current_user_can_module_field(module_key,'edit',field_key)
          or not pair.added and coalesce(pair.nv,'null') in ('null'::jsonb,'""'::jsonb,'[]'::jsonb) and not public.current_user_can_module_field(module_key,'delete',field_key) then
          raise exception 'دسترسی تغییر این ستون جدول را ندارید.' using errcode='42501';
        end if;
      end loop;
      continue;
    end if;
    if not(row_new?field_key) then continue; end if;
    value_new:=row_new->field_key; value_old:=row_old->field_key;
    if tg_op='UPDATE' and value_new is not distinct from value_old then continue; end if;
    if tg_op='INSERT' and coalesce(value_new,'null') in ('null'::jsonb,'""'::jsonb,'[]'::jsonb) then continue; end if;
    if not public.current_user_can_module_field(module_key,action,field_key) then
      -- Omitting a denied field may still produce a database default. Allow
      -- exactly that default; clients cannot use this to choose another value.
      if tg_op='INSERT' then
        select pg_get_expr(d.adbin,d.adrelid),format_type(a.atttypid,a.atttypmod) into default_expr,default_type
          from pg_attribute a join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
          where a.attrelid=tg_relid and a.attname=field_key;
        if default_expr is not null then
          execute format('select to_jsonb((%s)::%s)',default_expr,default_type) into default_value;
          if value_new is not distinct from default_value then continue; end if;
        end if;
      end if;
      raise exception 'دسترسی تغییر این فیلد را ندارید.' using errcode='42501';
    end if;
    if tg_op='UPDATE' and coalesce(value_new,'null') in ('null'::jsonb,'""'::jsonb,'[]'::jsonb)
      and not public.current_user_can_module_field(module_key,'delete',field_key) then
      raise exception 'دسترسی پاک‌کردن مقدار این فیلد را ندارید.' using errcode='42501';
    end if;
  end loop;
  return new;
end $$;


--
-- Name: guard_process_run_stage_assignee_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_process_run_stage_assignee_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  if tg_op = 'UPDATE'
    and new.assignee_user_id is not distinct from old.assignee_user_id
    and new.assignee_role_id is not distinct from old.assignee_role_id
    and new.process_run_id is not distinct from old.process_run_id then
    return new;
  end if;

  select r.org_id into v_org_id
  from public.process_runs r
  where r.id = new.process_run_id;

  perform public.assert_process_assignee_org(
    v_org_id,
    new.assignee_user_id,
    new.assignee_role_id
  );
  return new;
end;
$$;


--
-- Name: guard_process_template_stage_assignee_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_process_template_stage_assignee_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  if tg_op = 'UPDATE'
    and new.default_assignee_id is not distinct from old.default_assignee_id
    and new.default_assignee_role_id is not distinct from old.default_assignee_role_id
    and new.template_id is not distinct from old.template_id then
    return new;
  end if;

  select t.org_id into v_org_id
  from public.process_templates t
  where t.id = new.template_id;

  perform public.assert_process_assignee_org(
    v_org_id,
    new.default_assignee_id,
    new.default_assignee_role_id
  );
  return new;
end;
$$;


--
-- Name: guard_profile_membership_identity_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_membership_identity_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.role()='authenticated' then
    if (new.org_id,new.role_id,new.role,new.is_active) is distinct from (old.org_id,old.role_id,old.role,old.is_active) then
      raise exception 'نقش و وضعیت عضویت را از بخش اعضای سازمان تغییر دهید.' using errcode='42501'; end if;
    if old.id<>auth.uid() and exists(select 1 from public.user_organization_memberships where user_id=old.id and org_id<>old.org_id)
      and (new.full_name,new.email,new.mobile_1,new.avatar_url) is distinct from (old.full_name,old.email,old.mobile_1,old.avatar_url) then
      raise exception 'اطلاعات شخصی مشترک را خود شخص باید ویرایش کند.' using errcode='42501'; end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_saas_lifecycle_workflow_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_saas_lifecycle_workflow_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_row public.workflows%rowtype;
  v_modules text[] := array['saas_orgs','saas_users','saas_demo_requests'];
begin
  if tg_op = 'DELETE' then v_row := old; else v_row := new; end if;
  if v_row.module_id = any(v_modules)
    or coalesce(v_row.module_ids, '{}'::text[]) && v_modules
    or (tg_op = 'UPDATE' and
      (old.module_id = any(v_modules) or coalesce(old.module_ids, '{}'::text[]) && v_modules)) then
    if v_row.org_id is distinct from public.support_provider_org_id()
      or not (auth.role() = 'service_role' or public.saas_lifecycle_workflows_allowed()) then
      raise exception 'saas_workflow_access_denied' using errcode = '42501';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: guard_support_workflow_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_support_workflow_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target_row public.workflows%rowtype;
begin
  if tg_op='DELETE' then target_row:=old; else target_row:=new; end if;
  if target_row.module_id='saas_support_tickets'
    or 'saas_support_tickets'=any(coalesce(target_row.module_ids,'{}'::text[]))
    or (tg_op='UPDATE' and (old.module_id='saas_support_tickets'
      or 'saas_support_tickets'=any(coalesce(old.module_ids,'{}'::text[])))) then
    if target_row.org_id is distinct from public.support_provider_org_id()
      or not (auth.role()='service_role' or
        (public.support_is_operator('support_view') and public.support_is_operator('support_workflows'))) then
      raise exception 'support_workflow_access_denied' using errcode='42501';
    end if;
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end $$;


--
-- Name: guard_task_assignee_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_task_assignee_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE'
    and new.assignee_id is not distinct from old.assignee_id
    and new.assignee_role_id is not distinct from old.assignee_role_id
    and new.org_id is not distinct from old.org_id then
    return new;
  end if;

  perform public.assert_process_assignee_org(
    new.org_id,
    new.assignee_id,
    new.assignee_role_id
  );
  return new;
end;
$$;


--
-- Name: import_woocommerce_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_woocommerce_order(p_connection_id uuid, p_external_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_connection public.external_connections%rowtype;
  v_order public.external_order_inbox%rowtype;
  v_invoice_id uuid;
  v_customer_id uuid;
  v_product_id uuid;
  v_customer_external text;
  v_line jsonb;
  v_items jsonb := '[]'::jsonb;
  v_currency text;
  v_local_currency text;
  v_factor numeric := 1;
  v_name text;
  v_sku text;
  v_qty numeric;
  v_match_count integer;
  v_existing_paid numeric;
  v_existing_payments jsonb;
  v_subtotal numeric := 0;
  v_origin_code text;
begin
  select * into v_connection from public.external_connections
  where id = p_connection_id and provider = 'woocommerce' and is_active = true;
  if not found then raise exception 'Connection unavailable'; end if;
  select * into v_order from public.external_order_inbox
  where connection_id = p_connection_id and org_id = v_connection.org_id and external_id = p_external_id
  for update;
  if not found then raise exception 'Order unavailable'; end if;
  select local_id into v_invoice_id from public.external_record_links
  where connection_id = p_connection_id and module_key = 'invoices' and external_id = p_external_id;
  if v_invoice_id is null then
    select value->>'value' into v_origin_code
    from jsonb_array_elements(coalesce(v_order.payload->'meta_data', '[]'::jsonb))
    where value->>'key' = '_tazesystem_invoice_code' limit 1;
    if nullif(trim(coalesce(v_origin_code, '')), '') is not null then
      select id into v_invoice_id from public.invoices
      where org_id = v_connection.org_id and system_code = v_origin_code limit 1;
      if v_invoice_id is not null then
        insert into public.external_record_links(org_id, connection_id, module_key, local_id, external_id)
        values (v_connection.org_id, p_connection_id, 'invoices', v_invoice_id, p_external_id);
        update public.external_order_inbox set processing_status = 'processed' where id = v_order.id;
        return v_invoice_id;
      end if;
    end if;
  end if;
  if v_invoice_id is not null and coalesce(v_connection.sync_policy->>'invoices', 'manual') <> 'woocommerce' then
    return v_invoice_id;
  end if;

  select upper(coalesce(currency_code, 'IRT')) into v_local_currency
  from public.company_settings where org_id = v_connection.org_id limit 1;
  v_local_currency := coalesce(v_local_currency, 'IRT');
  v_currency := upper(coalesce(v_order.payload->>'currency', ''));
  if v_currency not in ('IRR', 'IRT') or v_local_currency not in ('IRR', 'IRT') then
    raise exception 'WooCommerce order currency cannot be mapped safely';
  end if;
  if v_currency = 'IRR' and v_local_currency = 'IRT' then v_factor := 0.1; end if;
  if v_currency = 'IRT' and v_local_currency = 'IRR' then v_factor := 10; end if;

  if nullif(trim(v_order.payload#>>'{billing,email}'), '') is not null then
    perform pg_advisory_xact_lock(hashtextextended(
      v_connection.org_id::text || ':woo-customer:' || lower(v_order.payload#>>'{billing,email}'), 0));
  end if;
  v_customer_external := nullif(nullif(trim(coalesce(v_order.payload->>'customer_id', '')), ''), '0');
  if v_customer_external is not null then
    select local_id into v_customer_id from public.external_record_links
    where connection_id = p_connection_id and module_key = 'customers' and external_id = v_customer_external;
  end if;
  if v_customer_id is null and nullif(trim(v_order.payload#>>'{billing,email}'), '') is not null then
    select count(*), (array_agg(id))[1] into v_match_count, v_customer_id from public.customers
    where org_id = v_connection.org_id and lower(email) = lower(v_order.payload#>>'{billing,email}');
    if v_match_count > 1 then raise exception 'Ambiguous customer email'; end if;
  end if;
  if v_customer_id is null and v_invoice_id is not null then
    select customer_id into v_customer_id from public.invoices
    where id = v_invoice_id and org_id = v_connection.org_id;
  end if;
  if v_customer_id is null then
    v_name := trim(concat_ws(' ', nullif(v_order.payload#>>'{billing,first_name}', ''), nullif(v_order.payload#>>'{billing,last_name}', '')));
    insert into public.customers(org_id, full_name, first_name, last_name, email, mobile_1)
    values (v_connection.org_id, coalesce(nullif(v_name, ''), 'مشتری فروشگاه'),
      nullif(v_order.payload#>>'{billing,first_name}', ''), nullif(v_order.payload#>>'{billing,last_name}', ''),
      nullif(v_order.payload#>>'{billing,email}', ''), nullif(v_order.payload#>>'{billing,phone}', ''))
    returning id into v_customer_id;
  end if;
  if v_customer_external is not null then
    insert into public.external_record_links(org_id, connection_id, module_key, local_id, external_id)
    values (v_connection.org_id, p_connection_id, 'customers', v_customer_id, v_customer_external)
    on conflict do nothing;
  end if;

  for v_line in select value from jsonb_array_elements(coalesce(v_order.payload->'line_items', '[]'::jsonb)) loop
    v_product_id := null;
    v_sku := nullif(trim(coalesce(v_line->>'sku', '')), '');
    if nullif(nullif(trim(coalesce(v_line->>'product_id', '')), ''), '0') is not null then
      perform pg_advisory_xact_lock(hashtextextended(
        v_connection.org_id::text || ':woo-product:' || (v_line->>'product_id'), 0));
    end if;
    if nullif(nullif(trim(coalesce(v_line->>'product_id', '')), ''), '0') is not null then
      select local_id into v_product_id from public.external_record_links
      where connection_id = p_connection_id and module_key = 'products'
        and external_id = v_line->>'product_id';
    end if;
    if v_product_id is null and v_sku is not null then
      select count(*), (array_agg(id))[1] into v_match_count, v_product_id from public.products
      where org_id = v_connection.org_id and (lower(manual_code) = lower(v_sku) or lower(system_code) = lower(v_sku));
      if v_match_count > 1 then raise exception 'Ambiguous product SKU'; end if;
    end if;
    if v_product_id is null then
      insert into public.products(org_id, name, manual_code, product_type, sell_price)
      values (v_connection.org_id, coalesce(nullif(v_line->>'name', ''), 'کالای فروشگاه'),
        v_sku, 'goods', coalesce(nullif(v_line->>'price', '')::numeric, 0) * v_factor)
      returning id into v_product_id;
    end if;
    if nullif(nullif(trim(coalesce(v_line->>'product_id', '')), ''), '0') is not null then
      insert into public.external_record_links(org_id, connection_id, module_key, local_id, external_id)
      values (v_connection.org_id, p_connection_id, 'products', v_product_id, v_line->>'product_id')
      on conflict do nothing;
    end if;
    v_qty := greatest(coalesce(nullif(v_line->>'quantity', '')::numeric, 1), 0);
    v_subtotal := v_subtotal + coalesce(nullif(v_line->>'subtotal', '')::numeric, 0) * v_factor;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'product_id', v_product_id, 'quantity', v_qty,
      'unit_price', case when v_qty > 0 then round(coalesce(nullif(v_line->>'subtotal', '')::numeric, 0) * v_factor / v_qty, 2) else 0 end,
      'total_price', round(coalesce(nullif(v_line->>'total', '')::numeric, 0) * v_factor, 2),
      'vat', round(coalesce(nullif(v_line->>'total_tax', '')::numeric, 0) * v_factor, 2)
    ));
  end loop;

  if v_invoice_id is null then
    insert into public.invoices(org_id, name, invoice_date, status, customer_id, sale_source,
      "invoiceItems", subtotal_before_tax, shipping_amount, invoice_discount_amount,
      total_invoice_amount, total_received_amount, remaining_balance)
    values (v_connection.org_id,
      'سفارش فروشگاه شماره ' || coalesce(nullif(v_order.payload->>'number', ''), p_external_id),
      coalesce(nullif(left(v_order.payload->>'date_created', 10), '')::date, current_date),
      'created', v_customer_id, 'woocommerce', v_items,
      round(v_subtotal, 2),
      round(coalesce(nullif(v_order.payload->>'shipping_total', '')::numeric, 0) * v_factor, 2),
      round(coalesce(nullif(v_order.payload->>'discount_total', '')::numeric, 0) * v_factor, 2),
      round(coalesce(nullif(v_order.payload->>'total', '')::numeric, 0) * v_factor, 2), 0,
      round(coalesce(nullif(v_order.payload->>'total', '')::numeric, 0) * v_factor, 2))
    returning id into v_invoice_id;
    insert into public.external_record_links(org_id, connection_id, module_key, local_id, external_id)
    values (v_connection.org_id, p_connection_id, 'invoices', v_invoice_id, p_external_id);
  else
    select total_received_amount, payments into v_existing_paid, v_existing_payments
    from public.invoices where id = v_invoice_id and org_id = v_connection.org_id for update;
    if not found or coalesce(v_existing_paid, 0) <> 0
      or jsonb_array_length(coalesce(v_existing_payments, '[]'::jsonb)) > 0 then
      raise exception 'Paid or missing invoice cannot be overwritten';
    end if;
    update public.invoices set
      name = 'سفارش فروشگاه شماره ' || coalesce(nullif(v_order.payload->>'number', ''), p_external_id),
      customer_id = v_customer_id, "invoiceItems" = v_items,
      subtotal_before_tax = round(v_subtotal, 2),
      shipping_amount = round(coalesce(nullif(v_order.payload->>'shipping_total', '')::numeric, 0) * v_factor, 2),
      invoice_discount_amount = round(coalesce(nullif(v_order.payload->>'discount_total', '')::numeric, 0) * v_factor, 2),
      total_invoice_amount = round(coalesce(nullif(v_order.payload->>'total', '')::numeric, 0) * v_factor, 2),
      remaining_balance = round(coalesce(nullif(v_order.payload->>'total', '')::numeric, 0) * v_factor, 2),
      updated_at = now()
    where id = v_invoice_id and org_id = v_connection.org_id;
    update public.external_record_links set synced_at = now(), external_updated_at = v_order.source_updated_at
    where connection_id = p_connection_id and module_key = 'invoices' and external_id = p_external_id;
  end if;
  update public.external_order_inbox set processing_status = 'processed'
  where id = v_order.id;
  return v_invoice_id;
end;
$$;


--
-- Name: import_woocommerce_order_with_outcome(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_woocommerce_order_with_outcome(p_connection_id uuid, p_external_id text) RETURNS TABLE(invoice_id uuid, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_connection public.external_connections%rowtype;
  v_order public.external_order_inbox%rowtype;
  v_invoice public.invoices%rowtype;
  v_before_id uuid;
  v_invoice_id uuid;
  v_origin_code text;
  v_outcome text;
  v_woo_authoritative boolean;
  v_last_imported_at timestamptz;
  v_last_content_hash text;
  v_content_hash text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Service role required';
  end if;
  select * into v_connection from public.external_connections
  where id = p_connection_id and provider = 'woocommerce' and is_active;
  if not found then raise exception 'Connection unavailable'; end if;

  select * into v_order from public.external_order_inbox
  where org_id = v_connection.org_id and connection_id = p_connection_id and external_id = p_external_id
  for update;
  if not found then raise exception 'Order unavailable'; end if;

  select l.local_id, l.local_updated_at, l.order_invoice_content_hash
    into v_before_id, v_last_imported_at, v_last_content_hash
  from public.external_record_links l
  where l.org_id = v_connection.org_id and l.connection_id = p_connection_id
    and l.module_key = 'invoices' and l.external_id = p_external_id;
  select nullif(trim(meta.value->>'value'), '') into v_origin_code
  from jsonb_array_elements(coalesce(v_order.payload->'meta_data', '[]'::jsonb)) as meta(value)
  where meta.value->>'key' = '_tazesystem_invoice_code' limit 1;

  v_content_hash := md5(jsonb_build_array(
    v_order.payload->'currency', v_order.payload->'total', v_order.payload->'shipping_total',
    v_order.payload->'discount_total', (
      select jsonb_agg(jsonb_build_array(line->'product_id', line->'variation_id', line->'sku',
        line->'quantity', line->'subtotal', line->'total', line->'total_tax') order by ordinal)
      from jsonb_array_elements(coalesce(v_order.payload->'line_items', '[]'::jsonb)) with ordinality lines(line, ordinal)
    )
  )::text);
  v_woo_authoritative := coalesce(v_connection.sync_policy->>'invoices', 'manual') = 'woocommerce';
  if v_before_id is not null then
    select * into v_invoice from public.invoices where org_id = v_connection.org_id and id = v_before_id for update;
    if not found then raise exception 'Linked invoice unavailable'; end if;
    if v_order.processing_status = 'processed' and (
      v_order.external_status is distinct from 'completed' or v_invoice.status is distinct from 'created'
      or v_origin_code is not null or v_invoice.sale_source is distinct from 'woocommerce'
      or not v_woo_authoritative
    ) then
      return query select v_before_id, 'skipped'::text;
      return;
    end if;
    if v_origin_code is not null then
      update public.external_order_inbox set processing_status = 'processed'
      where id = v_order.id and org_id = v_connection.org_id;
      return query select v_before_id, 'skipped'::text;
      return;
    end if;
    if v_order.external_status = 'completed' and v_invoice.sale_source = 'woocommerce'
      and v_invoice.status = 'created' and (coalesce(v_invoice.total_received_amount, 0) <> 0
        or jsonb_array_length(coalesce(v_invoice.payments, '[]'::jsonb)) > 0) then
      raise exception 'Invoice with recorded payments cannot be changed by checkout';
    end if;
    if not v_woo_authoritative then
      -- A newly imported, untouched Woo invoice can be recognized on completion.
      -- Other changes to existing invoices still require a Woo-authoritative policy.
      if coalesce(v_connection.sync_policy->>'invoices', 'manual') <> 'manual'
        or v_order.external_status is distinct from 'completed'
        or v_invoice.status is distinct from 'created'
        or v_invoice.sale_source is distinct from 'woocommerce' or v_last_imported_at is null then
        update public.external_order_inbox set processing_status = 'processed'
        where id = v_order.id and org_id = v_connection.org_id;
        return query select v_before_id, 'skipped'::text;
        return;
      end if;
      if v_invoice.updated_at is distinct from v_last_imported_at then
        raise exception 'Local invoice changed before WooCommerce order completion';
      end if;
      if v_content_hash is distinct from v_last_content_hash then
        raise exception 'WooCommerce order items or total changed before completion';
      end if;
      v_invoice_id := v_before_id;
      v_outcome := 'updated';
    elsif v_order.external_status = 'refunded' then
      raise exception 'The refunded order requires review in the sales return module';
    else
      v_invoice_id := public.import_woocommerce_order(p_connection_id, p_external_id);
      v_outcome := 'updated';
    end if;
  else
    v_invoice_id := public.import_woocommerce_order(p_connection_id, p_external_id);
    v_outcome := case when v_origin_code is not null and exists (
      select 1 from public.invoices i where i.org_id = v_connection.org_id
        and i.id = v_invoice_id and i.system_code = v_origin_code
    ) then 'linked' else 'created' end;
  end if;

  if v_outcome in ('created', 'updated') and v_order.external_status = 'completed' then
    update public.invoices i set status = 'completed', updated_at = now()
    where i.org_id = v_connection.org_id and i.id = v_invoice_id
      and i.sale_source = 'woocommerce' and i.status = 'created'
      and coalesce(i.total_received_amount, 0) = 0
      and jsonb_array_length(coalesce(i.payments, '[]'::jsonb)) = 0;
  end if;
  if v_outcome in ('created', 'updated') and v_order.external_status = 'cancelled' then
    update public.invoices i set status = 'canceled', updated_at = now()
    where i.org_id = v_connection.org_id and i.id = v_invoice_id
      and i.sale_source = 'woocommerce' and i.status in ('created', 'completed')
      and coalesce(i.total_received_amount, 0) = 0
      and jsonb_array_length(coalesce(i.payments, '[]'::jsonb)) = 0;
  end if;
  if v_outcome in ('created', 'updated') then
    update public.external_record_links l set
      synced_at = now(), local_updated_at = i.updated_at, external_updated_at = v_order.source_updated_at,
      order_invoice_content_hash = v_content_hash
    from public.invoices i
    where l.org_id = v_connection.org_id and l.connection_id = p_connection_id and l.module_key = 'invoices'
      and l.external_id = p_external_id and i.org_id = l.org_id and i.id = v_invoice_id;
  end if;
  update public.external_order_inbox set processing_status = 'processed'
  where id = v_order.id and org_id = v_connection.org_id;
  return query select v_invoice_id, v_outcome;
end;
$$;


--
-- Name: insert_demo_seed_rows(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_demo_seed_rows(p_batch_id uuid, p_table_name text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare batch_org uuid; row_data jsonb; inserted jsonb; result jsonb := '[]'; cols text; vals text; has_org boolean;
begin
  select org_id into batch_org from public.demo_seed_batches where id=p_batch_id and status='seeding' for update;
  if batch_org is null then raise exception 'نوبت ساخت داده نمونه معتبر نیست.'; end if;
  if p_table_name <> all(array[
    'org_roles','warehouses','shelves','suppliers','products','price_lists','product_bundles','bundle_items',
    'customers','marketing_leads','process_templates','process_template_stages','projects','project_members',
    'process_runs','process_run_stages','tasks','invoices','purchase_invoices','secretariat_documents',
    'delivery_forms','stock_transfers','work_schedules','employees','attendance_logs','leave_requests',
    'overtime_requests','mission_requests','recruitment_applicants','employee_contracts','payroll_slips',
    'employee_bonus_requests','employee_penalty_requests','surveys','goals','expense_documents',
    'reservation_resources','reservations','workflows'
  ]) then raise exception 'بخش داده نمونه مجاز نیست.'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 100 then raise exception 'داده نمونه معتبر نیست.'; end if;
  select exists(select 1 from information_schema.columns where table_schema='public' and table_name=p_table_name and column_name='org_id') into has_org;
  perform set_config('app.demo_seed_batch_id',p_batch_id::text,true);
  for row_data in select value from jsonb_array_elements(p_rows) loop
    row_data := row_data || jsonb_build_object('id',gen_random_uuid());
    if has_org then row_data := row_data || jsonb_build_object('org_id',batch_org); end if;
    select string_agg(format('%I',key),',' order by key), string_agg(format('r.%I',key),',' order by key)
      into cols,vals from jsonb_object_keys(row_data) key;
    execute format('insert into public.%1$I (%2$s) select %3$s from jsonb_populate_record(null::public.%1$I,$1) r returning to_jsonb(%1$I.*)',p_table_name,cols,vals)
      into inserted using row_data;
    -- Child tables without org_id are tracked explicitly; access is restricted to service_role.
    insert into public.demo_seed_records(batch_id,org_id,table_name,record_id,label)
    values(p_batch_id,batch_org,p_table_name,(inserted->>'id')::uuid,coalesce(inserted->>'name',inserted->>'title','داده نمونه'))
    on conflict(batch_id,table_name,record_id) do nothing;
    result := result || jsonb_build_array(inserted);
  end loop;
  perform set_config('app.demo_seed_batch_id','',true);
  update public.demo_seed_batches set updated_at=now(), seeded_records_count=(select count(*) from public.demo_seed_records where batch_id=p_batch_id) where id=p_batch_id;
  return result;
end; $_$;


--
-- Name: insert_public_invoice_note(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_public_invoice_note(p_system_code text, p_module text, p_content text, p_author_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return public.insert_public_invoice_note(
    p_system_code,
    p_module,
    p_content,
    p_author_name,
    '[]'::jsonb
  );
end;
$$;


--
-- Name: insert_public_invoice_note(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_public_invoice_note(p_system_code text, p_module text, p_content text, p_author_name text, p_attachments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_invoice_id uuid;
  v_assignee_id uuid;
  v_actual_system_code text;
  v_note_id uuid;
  v_text text := left(btrim(coalesce(p_content, '')), 4000);
  v_attachments jsonb := case
    when jsonb_typeof(coalesce(p_attachments, '[]'::jsonb)) = 'array' then coalesce(p_attachments, '[]'::jsonb)
    else '[]'::jsonb
  end;
  v_has_attachments boolean := jsonb_array_length(case
    when jsonb_typeof(coalesce(p_attachments, '[]'::jsonb)) = 'array' then coalesce(p_attachments, '[]'::jsonb)
    else '[]'::jsonb
  end) > 0;
  v_content_to_store text;
begin
  if v_text = '' and not v_has_attachments then
    return jsonb_build_object('error', 'invalid_content');
  end if;

  v_org_id := public._resolve_org_for_public_invoice(p_system_code, p_module);
  if v_org_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  if p_module = 'invoices' then
    select id, assignee_id, system_code
    into v_invoice_id, v_assignee_id, v_actual_system_code
    from public.invoices
    where org_id = v_org_id
      and (public_slug = p_system_code or public_token = p_system_code)
    limit 1;
  else
    select id, assignee_id, system_code
    into v_invoice_id, v_assignee_id, v_actual_system_code
    from public.purchase_invoices
    where org_id = v_org_id
      and (public_slug = p_system_code or public_token = p_system_code)
    limit 1;
  end if;

  if v_invoice_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  v_content_to_store := case
    when v_has_attachments
      then jsonb_build_object('text', v_text, 'attachments', v_attachments)::text
    else v_text
  end;

  insert into public.notes (
    org_id,
    module_id,
    record_id,
    content,
    author_name,
    is_public,
    mention_user_ids,
    metadata
  )
  values (
    v_org_id,
    p_module,
    v_invoice_id::text,
    v_content_to_store,
    left(btrim(coalesce(p_author_name, 'مخاطب')), 160),
    true,
    case when v_assignee_id is not null then array[v_assignee_id] else array[]::uuid[] end,
    jsonb_build_object('source', 'online_invoice', 'system_code', v_actual_system_code)
  )
  returning id into v_note_id;

  return jsonb_build_object('success', true, 'id', v_note_id);
end;
$$;


--
-- Name: is_customer_purchase_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_customer_purchase_status(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select coalesce(lower(trim(p_status)), '') not in ('', 'created', 'proforma', 'canceled', 'cancelled')
$$;


--
-- Name: is_record_locked(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_record_locked(p_module_id text, p_record_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.record_locks rl
    where rl.org_id = public.current_org_id()
      and rl.record_id = p_record_id
      and (
        rl.module_id = btrim(coalesce(p_module_id, ''))
        or rl.metadata ->> 'table_name' = public.resolve_record_lock_table_name(p_module_id)
      )
  );
$$;


--
-- Name: is_valid_tenant_site_blocks(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_tenant_site_blocks(p_blocks jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_block jsonb;
  v_href text;
  v_level integer;
begin
  if p_blocks is null or jsonb_typeof(p_blocks) is distinct from 'array' or jsonb_array_length(p_blocks) > 100 then return false; end if;
  for v_block in select value from jsonb_array_elements(p_blocks) loop
    if jsonb_typeof(v_block) <> 'object'
      or coalesce(v_block->>'type', '') not in ('heading', 'paragraph', 'button')
      or jsonb_typeof(v_block->'text') is distinct from 'string'
      or length(coalesce(v_block->>'text', '')) > 10000 then return false; end if;
    if v_block->>'type' = 'heading' and v_block ? 'level' then
      begin v_level := (v_block->>'level')::integer; exception when others then return false; end;
      if v_level < 1 or v_level > 4 then return false; end if;
    end if;
    if v_block->>'type' = 'button' then
      v_href := coalesce(v_block->>'href', '');
      if length(v_href) > 2048 or v_href ~ '[[:cntrl:]]' or position(chr(92) in v_href) > 0
        or not (v_href ~* '^https://[^[:space:]]+$' or (left(v_href, 1) = '/' and left(v_href, 2) <> '//')) then return false; end if;
    end if;
  end loop;
  return true;
end;
$_$;


--
-- Name: kalam_agent_label_fa_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_agent_label_fa_v1(p_agent_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case lower(trim(coalesce(p_agent_key, '')))
    when 'lead_orchestrator' then 'ایجنت راهبر'
    when 'sales_leads' then 'ایجنت فروش و لید'
    when 'purchase_supply' then 'ایجنت خرید و تأمین'
    when 'customer_response' then 'ایجنت پاسخگویی مشتری'
    when 'hr_manager' then 'ایجنت منابع انسانی'
    when 'reservation' then 'ایجنت رزرواسیون'
    when 'project_process' then 'ایجنت پروژه و فرآیند'
    when 'instagrammer' then 'ایجنت اینستاگرامر'
    when 'system_guide' then 'ایجنت راهنمای تازه‌سیستم'
    else 'ایجنت هوشمند'
  end;
$$;


--
-- Name: kalam_agent_subtitle_fa_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_agent_subtitle_fa_v1(p_agent_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case lower(trim(coalesce(p_agent_key, '')))
    when 'lead_orchestrator' then 'هماهنگی و تخصیص هوشمند اولویت‌ها'
    when 'sales_leads' then 'کمپین‌ها، سرنخ‌ها، پیش‌فاکتور، فاکتور، تسویه و تبدیل فروش'
    when 'purchase_supply' then 'استعلام، پیش‌فاکتور خرید، سفارش، فاکتور خرید و کسری انبار'
    when 'customer_response' then 'وضعیت پروژه‌ها، فرآیندها، وظایف کارکنان و پاسخگویی چندکاناله'
    when 'hr_manager' then 'قرارداد، فرمول کارکرد، فیش، مرخصی، مأموریت و اضافه‌کار'
    when 'reservation' then 'تقویم رزرو، بافر، بیعانه و فاکتور فروش مرتبط'
    when 'project_process' then 'ویزارد الگوهای فرآیند، تسک‌ها، پیشرفت و اتوماسیون'
    when 'instagrammer' then 'تقویم محتوایی، پست‌ها، استوری‌ها، ویترین و پاسخ خودکار اینستاگرام'
    when 'system_guide' then 'راهنمای کاربری، گردش‌کارها و آموزش‌های تازه‌سیستم'
    else 'دستیار هوشمند سازمانی'
  end;
$$;


--
-- Name: kalam_agent_title_fa_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

