    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case lower(trim(coalesce(p_agent_key, '')))
    when 'lead_orchestrator' then 'ایجنت راهبر'
    when 'sales_leads' then 'ایجنت بازاریابی و فروش'
    when 'purchase_supply' then 'ایجنت خرید و تأمین'
    when 'customer_response' then 'ایجنت پاسخگویی مشتری'
    when 'hr_manager' then 'ایجنت منابع انسانی'
    when 'reservation' then 'ایجنت رزرواسیون'
    when 'project_process' then 'ایجنت پروژه و فرآیند'
    when 'instagrammer' then 'ایجنت اینستاگرامر'
    when 'system_guide' then 'ایجنت راهنمای تازه‌سیستم'
    else 'ایجنت هوشمند'
  end;
$$;


--
-- Name: kalam_broadcast_module_list_invalidation(uuid, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_broadcast_module_list_invalidation(p_org_id uuid, p_module_id text, p_record_id text DEFAULT NULL::text, p_action text DEFAULT 'update'::text, p_updated_at timestamp with time zone DEFAULT now(), p_scope_hint jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_topic text;
  v_payload jsonb;
  v_module_id text := nullif(trim(coalesce(p_module_id, '')), '');
begin
  if p_org_id is null or v_module_id is null then
    return;
  end if;

  v_topic := public.kalam_realtime_module_list_topic(p_org_id, v_module_id);
  if v_topic is null then
    return;
  end if;

  v_payload := jsonb_build_object(
    'module_id', v_module_id,
    'record_id', nullif(trim(coalesce(p_record_id, '')), ''),
    'action', coalesce(nullif(trim(coalesce(p_action, '')), ''), 'update'),
    'updated_at', coalesce(p_updated_at, now()),
    'scope_hint', coalesce(p_scope_hint, '{}'::jsonb)
  );

  perform public.kalam_broadcast_notification(v_topic, 'module_list_invalidation', v_payload);
end;
$$;


--
-- Name: kalam_broadcast_notification(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_broadcast_notification(p_topic text, p_event text, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
begin
  if p_topic is null or p_event is null then
    return;
  end if;

  if to_regnamespace('realtime') is null or to_regprocedure('realtime.send(jsonb,text,text,boolean)') is null then
    return;
  end if;

  execute 'select realtime.send($1, $2, $3, true)'
    using coalesce(p_payload, '{}'::jsonb), p_event, p_topic;
exception
  when invalid_schema_name or undefined_function then
    return;
  when others then
    raise notice 'notification broadcast skipped: %', sqlerrm;
end;
$_$;


--
-- Name: kalam_can_access_bot_direct_thread(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_access_bot_direct_thread(p_thread_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid;
  v_thread record;
  v_allowed_users uuid[];
  v_allowed_roles uuid[];
begin
  if v_user_id is null or v_org_id is null or p_thread_id is null then
    return false;
  end if;

  if p_org_id is not null and p_org_id is distinct from v_org_id then
    return false;
  end if;

  select p.role_id
  into v_role_id
  from public.profiles p
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  select
    t.created_by,
    t.profile_id,
    coalesce(t.metadata, '{}'::jsonb) as metadata
  into v_thread
  from public.counterparty_bot_direct_threads t
  where t.id = p_thread_id
    and t.org_id = v_org_id
  limit 1;

  if not found then
    return false;
  end if;

  v_allowed_users := public.kalam_jsonb_uuid_array(v_thread.metadata -> 'allowed_user_ids');
  v_allowed_roles := public.kalam_jsonb_uuid_array(v_thread.metadata -> 'allowed_role_ids');

  if coalesce(v_thread.created_by = v_user_id, false)
     or coalesce(v_thread.profile_id = v_user_id, false) then
    return true;
  end if;

  if coalesce(array_length(v_allowed_users, 1), 0) = 0
     and coalesce(array_length(v_allowed_roles, 1), 0) = 0 then
    return false;
  end if;

  return v_user_id = any(v_allowed_users)
    or (v_role_id is not null and v_role_id = any(v_allowed_roles));
end;
$$;


--
-- Name: kalam_can_access_bot_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_access_bot_group(p_group_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := coalesce(p_org_id, public.current_org_id());
  v_role_id uuid;
  v_permissions jsonb := '{}'::jsonb;
  v_bot_group_access text := 'inherited';
  v_group record;
  v_allowed_user_ids text[] := array[]::text[];
  v_allowed_role_ids text[] := array[]::text[];
begin
  if v_user_id is null or v_org_id is null or p_group_id is null then
    return false;
  end if;

  select p.role_id, coalesce(r.permissions, '{}'::jsonb)
  into v_role_id, v_permissions
  from public.profiles p
  left join public.org_roles r
    on r.id = p.role_id
   and r.org_id = p.org_id
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if not found
    or coalesce(v_permissions -> '__communications' ->> 'view', 'true') = 'false' then
    return false;
  end if;

  v_bot_group_access := lower(trim(coalesce(
    v_permissions -> '__communications' -> 'fields' ->> 'bot_group_access',
    'inherited'
  )));

  select g.created_by, coalesce(g.metadata, '{}'::jsonb) as metadata
  into v_group
  from public.counterparty_bot_groups g
  where g.id = p_group_id
    and g.org_id = v_org_id
  limit 1;

  if not found then
    return false;
  end if;

  if v_bot_group_access = 'all'
    or coalesce(v_group.created_by = v_user_id, false) then
    return true;
  end if;

  -- کلیدهای اصلی توسط مودال بات نوشته می‌شوند؛ کلیدهای قدیمی فقط برای
  -- حفظ دسترسی داده‌های قبلی خوانده می‌شوند.
  select coalesce(array_agg(distinct value), array[]::text[])
  into v_allowed_user_ids
  from jsonb_array_elements_text(
    (case when jsonb_typeof(v_group.metadata -> 'allowed_user_ids') = 'array' then v_group.metadata -> 'allowed_user_ids' else '[]'::jsonb end)
    || (case when jsonb_typeof(v_group.metadata -> 'allowed_profile_ids') = 'array' then v_group.metadata -> 'allowed_profile_ids' else '[]'::jsonb end)
    || (case when jsonb_typeof(v_group.metadata -> 'user_ids') = 'array' then v_group.metadata -> 'user_ids' else '[]'::jsonb end)
  ) as access_user(value)
  where nullif(trim(value), '') is not null;

  select coalesce(array_agg(distinct value), array[]::text[])
  into v_allowed_role_ids
  from jsonb_array_elements_text(
    (case when jsonb_typeof(v_group.metadata -> 'allowed_role_ids') = 'array' then v_group.metadata -> 'allowed_role_ids' else '[]'::jsonb end)
    || (case when jsonb_typeof(v_group.metadata -> 'role_ids') = 'array' then v_group.metadata -> 'role_ids' else '[]'::jsonb end)
  ) as access_role(value)
  where nullif(trim(value), '') is not null;

  if v_user_id::text = any(v_allowed_user_ids) then
    return true;
  end if;

  -- انتخاب یک نقش بالادستی در مودال، کاربران نقش‌های فرزند آن را نیز پوشش می‌دهد.
  return exists (
    with recursive role_lineage(id, parent_id, path) as (
      select r.id, r.parent_id, array[r.id]
      from public.org_roles r
      where r.id = v_role_id
        and r.org_id = v_org_id
      union all
      select parent_role.id, parent_role.parent_id, child_role.path || parent_role.id
      from public.org_roles parent_role
      join role_lineage child_role on child_role.parent_id = parent_role.id
      where parent_role.org_id = v_org_id
        and not parent_role.id = any(child_role.path)
    )
    select 1
    from role_lineage
    where id::text = any(v_allowed_role_ids)
  );
end;
$$;


--
-- Name: kalam_can_access_chat_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_access_chat_group(p_group_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_role_id uuid;
  v_group record;
begin
  if v_user_id is null or p_group_id is null then
    return false;
  end if;

  select public.kalam_current_profile_role_id(p_org_id) into v_role_id;

  select
    cg.created_by,
    coalesce(cg.user_ids, '{}'::uuid[]) as user_ids,
    coalesce(cg.role_ids, '{}'::uuid[]) as role_ids
  into v_group
  from public.chat_groups cg
  where cg.id = p_group_id
    and (p_org_id is null or cg.org_id = p_org_id)
  limit 1;

  if not found then
    return false;
  end if;

  return coalesce(v_group.created_by = v_user_id, false)
    or v_user_id = any(v_group.user_ids)
    or (v_role_id is not null and v_role_id = any(v_group.role_ids));
end;
$$;


--
-- Name: kalam_can_access_instagram_conversation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_access_instagram_conversation(p_conversation_id uuid, p_org_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := coalesce(p_org_id, public.current_org_id());
  v_role_id uuid;
  v_permissions jsonb := '{}'::jsonb;
  v_permission jsonb := '{}'::jsonb;
  v_scope text := 'all';
  v_conversation record;
  v_scope_allowed boolean := false;
  v_conditions jsonb := '[]'::jsonb;
  v_conditions_any jsonb := '[]'::jsonb;
  v_conditions_any_match boolean := true;
  v_condition jsonb;
  v_condition_mode text := 'all';
  v_condition_match boolean;
  v_match_count integer := 0;
  v_condition_count integer := 0;
  v_field text;
  v_operator text;
  v_expected jsonb;
  v_actual text;
begin
  if v_user_id is null or v_org_id is null or p_conversation_id is null then return false; end if;
  select p.role_id, coalesce(r.permissions, '{}'::jsonb)
    into v_role_id, v_permissions
  from public.profiles p left join public.org_roles r on r.id = p.role_id and r.org_id = p.org_id
  where p.id = v_user_id and p.org_id = v_org_id limit 1;
  if not found then return false; end if;
  v_permission := coalesce(v_permissions -> 'instagram_conversations', '{}'::jsonb);
  select * into v_conversation from public.instagram_conversations
   where id = p_conversation_id and org_id = v_org_id limit 1;
  if not found then return false; end if;
  if lower(coalesce(v_permissions -> '__saas_admin' ->> 'view', 'false')) = 'true'
    or lower(coalesce(v_permissions -> '__saas_admin' ->> 'edit', 'false')) = 'true' then return true; end if;
  if lower(coalesce(v_permission ->> 'view', 'false')) <> 'true' then return false; end if;

  if exists (
    select 1 from public.instagram_conversation_access_grants grant_row
    where grant_row.conversation_id = p_conversation_id and grant_row.org_id = v_org_id
      and ((grant_row.grantee_type = 'user' and grant_row.grantee_id = v_user_id)
        or (grant_row.grantee_type = 'role' and grant_row.grantee_id = v_role_id))
  ) then
    v_scope_allowed := true;
  else
    v_scope := lower(coalesce(nullif(v_permission ->> 'record_scope', ''), 'all'));
    if v_scope = 'all' then v_scope_allowed := true; end if;
    if v_scope = 'own' then v_scope_allowed := v_conversation.assignee_user_id = v_user_id; end if;
    if v_scope = 'team' then v_scope_allowed := v_conversation.assignee_role_id = v_role_id; end if;
    if v_scope = 'subtree' then
      v_scope_allowed := v_conversation.assignee_role_id in (
      with recursive role_tree as (
        select id from public.org_roles where id = v_role_id and org_id = v_org_id
        union all
        select child.id from public.org_roles child join role_tree parent on child.parent_id = parent.id where child.org_id = v_org_id
      ) select id from role_tree
      );
    end if;
  end if;
  if not v_scope_allowed then return false; end if;

  -- شرط‌های نقش علاوه بر محدودهٔ رکورد اعمال می‌شوند و برچسب‌ها را نیز پشتیبانی می‌کنند.
  v_conditions := coalesce(v_permission -> 'view_conditions' -> 'conditions_all', v_permission -> 'view_conditions' -> 'conditions', '[]'::jsonb);
  v_conditions_any := coalesce(v_permission -> 'view_conditions' -> 'conditions_any', '[]'::jsonb);
  if jsonb_typeof(v_conditions_any) = 'array' and jsonb_array_length(v_conditions_any) > 0 then
    select coalesce(bool_or(public.kalam_matches_instagram_conversation_condition(p_conversation_id, value)), false)
      into v_conditions_any_match from jsonb_array_elements(v_conditions_any);
    if not v_conditions_any_match then return false; end if;
  end if;
  if jsonb_typeof(v_conditions) <> 'array' or jsonb_array_length(v_conditions) = 0 then return true; end if;
  v_condition_mode := lower(coalesce(v_permission -> 'view_conditions' ->> 'mode', 'all'));
  for v_condition in select value from jsonb_array_elements(v_conditions) loop
    v_condition_count := v_condition_count + 1;
    v_field := lower(coalesce(v_condition ->> 'field', v_condition ->> 'field_key', ''));
    v_operator := lower(coalesce(v_condition ->> 'operator', 'equals'));
    v_expected := coalesce(v_condition -> 'value', 'null'::jsonb);
    v_condition_match := false;
    if v_field in ('tag', 'tags') then
      if v_operator in ('contains', 'has', 'equals', 'in') then
        v_condition_match := case when jsonb_typeof(v_expected) = 'array'
          then v_conversation.tags ?| array(select jsonb_array_elements_text(v_expected))
          else v_conversation.tags ? trim(both '"' from v_expected::text) end;
      elsif v_operator in ('not_contains', 'not_has', 'not_equals', 'not_in') then
        v_condition_match := case when jsonb_typeof(v_expected) = 'array'
          then not (v_conversation.tags ?| array(select jsonb_array_elements_text(v_expected)))
          else not (v_conversation.tags ? trim(both '"' from v_expected::text)) end;
      end if;
    else
      v_actual := case v_field
        when 'account_id' then v_conversation.account_id::text
        when 'status' then coalesce(v_conversation.status, '')
        when 'priority' then coalesce(v_conversation.priority, '')
        when 'assignee_user_id' then coalesce(v_conversation.assignee_user_id::text, '')
        when 'assignee_role_id' then coalesce(v_conversation.assignee_role_id::text, '')
        else '' end;
      if v_operator in ('equals', 'eq') then v_condition_match := v_actual = trim(both '"' from v_expected::text); end if;
      if v_operator in ('not_equals', 'neq') then v_condition_match := v_actual <> trim(both '"' from v_expected::text); end if;
      if v_operator in ('in', 'one_of') and jsonb_typeof(v_expected) = 'array' then v_condition_match := v_actual = any(array(select jsonb_array_elements_text(v_expected))); end if;
      if v_operator in ('not_in', 'not_one_of') and jsonb_typeof(v_expected) = 'array' then v_condition_match := not (v_actual = any(array(select jsonb_array_elements_text(v_expected)))); end if;
    end if;
    if v_condition_match then v_match_count := v_match_count + 1; end if;
  end loop;
  return case when v_condition_mode = 'any' then v_match_count > 0 else v_match_count = v_condition_count end;
end;
$$;


--
-- Name: kalam_can_access_internal_message_v2(boolean, uuid[], uuid[], uuid, uuid[], uuid[], text, jsonb, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_access_internal_message_v2(p_inbox_is_org_wide boolean, p_target_user_ids uuid[], p_target_role_ids uuid[], p_author_id uuid, p_note_mention_user_ids uuid[], p_note_mention_role_ids uuid[], p_source_type text, p_metadata jsonb, p_inbox_category text, p_viewer_id uuid, p_viewer_role_id uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when p_viewer_id is null then false
    when public.kalam_internal_message_is_system_v2(p_source_type, p_metadata, p_inbox_category) then
      p_viewer_id = any(coalesce(p_target_user_ids, '{}'::uuid[]))
      or p_viewer_id = any(coalesce(p_note_mention_user_ids, '{}'::uuid[]))
      or (p_viewer_role_id is not null and (
        p_viewer_role_id = any(coalesce(p_target_role_ids, '{}'::uuid[]))
        or p_viewer_role_id = any(coalesce(p_note_mention_role_ids, '{}'::uuid[]))
      ))
    else coalesce(p_inbox_is_org_wide, false)
      or p_viewer_id = any(coalesce(p_target_user_ids, '{}'::uuid[]))
      or p_viewer_id = any(coalesce(p_note_mention_user_ids, '{}'::uuid[]))
      or (p_viewer_role_id is not null and (
        p_viewer_role_id = any(coalesce(p_target_role_ids, '{}'::uuid[]))
        or p_viewer_role_id = any(coalesce(p_note_mention_role_ids, '{}'::uuid[]))
      ))
      or p_author_id = p_viewer_id
  end;
$$;


--
-- Name: kalam_can_access_note(uuid, uuid, uuid, uuid[], uuid[], uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_access_note(p_note_id uuid, p_author_id uuid, p_org_id uuid, p_mention_user_ids uuid[], p_mention_role_ids uuid[], p_reply_to uuid, p_metadata jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_role_id uuid;
  v_group_id uuid;
  v_reply record;
  v_reply_group_id uuid;
begin
  if v_user_id is null or p_note_id is null then
    return false;
  end if;

  if p_org_id is not null and public.current_org_id() is not null and p_org_id <> public.current_org_id() then
    return false;
  end if;

  select public.kalam_current_profile_role_id(p_org_id) into v_role_id;

  if p_author_id = v_user_id then
    return true;
  end if;

  if v_user_id = any(coalesce(p_mention_user_ids, '{}'::uuid[])) then
    return true;
  end if;

  if v_role_id is not null and v_role_id = any(coalesce(p_mention_role_ids, '{}'::uuid[])) then
    return true;
  end if;

  v_group_id := public.kalam_try_uuid(coalesce(p_metadata ->> 'chat_group_id', ''));
  if v_group_id is not null and public.kalam_can_access_chat_group(v_group_id, p_org_id) then
    return true;
  end if;

  if p_reply_to is not null then
    select
      n.author_id,
      coalesce(n.mention_user_ids, '{}'::uuid[]) as mention_user_ids,
      coalesce(n.mention_role_ids, '{}'::uuid[]) as mention_role_ids,
      coalesce(n.metadata, '{}'::jsonb) as metadata
    into v_reply
    from public.notes n
    where n.id = p_reply_to
      and (p_org_id is null or n.org_id = p_org_id)
    limit 1;

    if found then
      if v_reply.author_id = v_user_id then
        return true;
      end if;

      if v_user_id = any(v_reply.mention_user_ids) then
        return true;
      end if;

      if v_role_id is not null and v_role_id = any(v_reply.mention_role_ids) then
        return true;
      end if;

      v_reply_group_id := public.kalam_try_uuid(coalesce(v_reply.metadata ->> 'chat_group_id', ''));
      if v_reply_group_id is not null and public.kalam_can_access_chat_group(v_reply_group_id, p_org_id) then
        return true;
      end if;
    end if;
  end if;

  return false;
end;
$$;


--
-- Name: kalam_can_view_communication_record(text, uuid, text, uuid, uuid, text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_view_communication_record(p_channel text, p_row_org_id uuid, p_assignee_type text DEFAULT NULL::text, p_assignee_id uuid DEFAULT NULL::uuid, p_assignee_role_id uuid DEFAULT NULL::uuid, p_module_id text DEFAULT NULL::text, p_record_id uuid DEFAULT NULL::uuid, p_related_module_id text DEFAULT NULL::text, p_related_record_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_channel text := lower(trim(coalesce(p_channel, '')));
  v_direct_module text;
  v_module_id text := lower(trim(coalesce(p_module_id, '')));
  v_related_module_id text := lower(trim(coalesce(p_related_module_id, '')));
begin
  if auth.uid() is null or public.current_org_id() is null or p_row_org_id is distinct from public.current_org_id() then
    return false;
  end if;

  v_direct_module := case v_channel
    when 'sms' then 'sms_delivery_reports'
    when 'voip' then 'voip_call_reports'
    else null
  end;

  if v_direct_module is not null and public.kalam_can_view_module_record_by_assignee(
    v_direct_module,
    p_row_org_id,
    p_assignee_type,
    p_assignee_id,
    p_assignee_role_id
  ) then
    return true;
  end if;

  if v_module_id in ('customers', 'suppliers', 'employees')
    and public.kalam_can_view_related_communication_target(v_module_id, p_record_id, p_row_org_id) then
    return true;
  end if;

  if v_related_module_id in ('customers', 'suppliers', 'employees')
    and public.kalam_can_view_related_communication_target(v_related_module_id, p_related_record_id, p_row_org_id) then
    return true;
  end if;

  if p_customer_id is not null
    and public.kalam_can_view_related_communication_target('customers', p_customer_id, p_row_org_id) then
    return true;
  end if;

  return false;
end;
$$;


--
-- Name: kalam_can_view_communication_record_v2(text, uuid, text, uuid, uuid, text, uuid, text, uuid, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_view_communication_record_v2(p_channel text, p_row_org_id uuid, p_assignee_type text DEFAULT NULL::text, p_assignee_id uuid DEFAULT NULL::uuid, p_assignee_role_id uuid DEFAULT NULL::uuid, p_module_id text DEFAULT NULL::text, p_record_id uuid DEFAULT NULL::uuid, p_related_module_id text DEFAULT NULL::text, p_related_record_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_sender text DEFAULT NULL::text, p_recipient text DEFAULT NULL::text, p_phone_number text DEFAULT NULL::text, p_source_number text DEFAULT NULL::text, p_destination_number text DEFAULT NULL::text, p_extension text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_channel text := lower(trim(coalesce(p_channel, '')));
  v_direct_module text;
  v_module_id text := lower(trim(coalesce(p_module_id, '')));
  v_related_module_id text := lower(trim(coalesce(p_related_module_id, '')));
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_profile_mobile_1 text;
  v_profile_mobile text;
  v_profile_voip_extension text;
  v_profile_phone text;
  v_profile_phone_tail text;
  v_sender text := public.kalam_normalize_phone_digits(p_sender);
  v_recipient text := public.kalam_normalize_phone_digits(p_recipient);
  v_phone_number text := public.kalam_normalize_phone_digits(p_phone_number);
  v_source_number text := public.kalam_normalize_phone_digits(p_source_number);
  v_destination_number text := public.kalam_normalize_phone_digits(p_destination_number);
begin
  if v_user_id is null or v_org_id is null or p_row_org_id is distinct from v_org_id then
    return false;
  end if;

  select
    p.mobile_1,
    p.mobile,
    p.voip_extension
  into v_profile_mobile_1, v_profile_mobile, v_profile_voip_extension
  from public.profiles p
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if not found then
    return false;
  end if;

  v_profile_phone := public.kalam_normalize_phone_digits(coalesce(v_profile_mobile_1, v_profile_mobile, ''));
  v_profile_phone_tail := case when length(v_profile_phone) >= 10 then right(v_profile_phone, 10) else v_profile_phone end;

  v_direct_module := case v_channel
    when 'sms' then 'sms_delivery_reports'
    when 'voip' then 'voip_call_reports'
    else null
  end;

  if v_direct_module is not null and public.kalam_can_view_module_record_by_assignee(
    v_direct_module,
    p_row_org_id,
    p_assignee_type,
    p_assignee_id,
    p_assignee_role_id
  ) then
    return true;
  end if;

  if v_channel = 'sms'
     and v_profile_phone <> ''
     and (
       v_sender like '%' || v_profile_phone
       or v_recipient like '%' || v_profile_phone
       or v_phone_number like '%' || v_profile_phone
       or (v_profile_phone_tail <> '' and (
         right(v_sender, 10) = v_profile_phone_tail
         or right(v_recipient, 10) = v_profile_phone_tail
         or right(v_phone_number, 10) = v_profile_phone_tail
       ))
     ) then
    return true;
  end if;

  if v_channel = 'voip'
     and nullif(trim(coalesce(v_profile_voip_extension, '')), '') is not null
     and nullif(trim(coalesce(p_extension, '')), '') = nullif(trim(coalesce(v_profile_voip_extension, '')), '') then
    return true;
  end if;

  if v_channel = 'voip'
     and v_profile_phone <> ''
     and (
       v_source_number like '%' || v_profile_phone
       or v_destination_number like '%' || v_profile_phone
       or v_phone_number like '%' || v_profile_phone
       or (v_profile_phone_tail <> '' and (
         right(v_source_number, 10) = v_profile_phone_tail
         or right(v_destination_number, 10) = v_profile_phone_tail
         or right(v_phone_number, 10) = v_profile_phone_tail
       ))
     ) then
    return true;
  end if;

  if v_module_id = 'profiles' and p_record_id = v_user_id then
    return true;
  end if;

  if v_related_module_id = 'profiles' and p_related_record_id = v_user_id then
    return true;
  end if;

  if v_module_id in ('customers', 'suppliers', 'employees')
    and public.kalam_can_view_related_communication_target(v_module_id, p_record_id, p_row_org_id) then
    return true;
  end if;

  if v_related_module_id in ('customers', 'suppliers', 'employees')
    and public.kalam_can_view_related_communication_target(v_related_module_id, p_related_record_id, p_row_org_id) then
    return true;
  end if;

  if p_customer_id is not null
    and public.kalam_can_view_related_communication_target('customers', p_customer_id, p_row_org_id) then
    return true;
  end if;

  return false;
end;
$$;


--
-- Name: kalam_can_view_communication_record_v3(text, uuid, text, uuid, uuid, text, uuid, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_view_communication_record_v3(p_channel text, p_row_org_id uuid, p_assignee_type text DEFAULT NULL::text, p_assignee_id uuid DEFAULT NULL::uuid, p_assignee_role_id uuid DEFAULT NULL::uuid, p_module_id text DEFAULT NULL::text, p_record_id uuid DEFAULT NULL::uuid, p_related_module_id text DEFAULT NULL::text, p_related_record_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_source_number text DEFAULT NULL::text, p_destination_number text DEFAULT NULL::text, p_extension text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_channel text := lower(trim(coalesce(p_channel, '')));
  v_module_id text := lower(trim(coalesce(p_module_id, '')));
  v_related_module_id text := lower(trim(coalesce(p_related_module_id, '')));
begin
  if auth.uid() is null or public.current_org_id() is null or p_row_org_id is distinct from public.current_org_id() then
    return false;
  end if;

  if v_channel = 'voip' and public.kalam_can_view_voip_call(
    p_row_org_id, p_assignee_type, p_assignee_id, p_assignee_role_id, p_extension
  ) then
    return true;
  end if;

  if v_module_id in ('customers', 'suppliers', 'employees')
    and public.kalam_can_view_related_communication_target(v_module_id, p_record_id, p_row_org_id) then
    return true;
  end if;

  if v_related_module_id in ('customers', 'suppliers', 'employees')
    and public.kalam_can_view_related_communication_target(v_related_module_id, p_related_record_id, p_row_org_id) then
    return true;
  end if;

  if p_customer_id is not null
    and public.kalam_can_view_related_communication_target('customers', p_customer_id, p_row_org_id) then
    return true;
  end if;

  return false;
end;
$$;


--
-- Name: kalam_can_view_instagram_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_view_instagram_org(p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_permissions jsonb := '{}'::jsonb;
begin
  if auth.uid() is null or p_org_id is null or p_org_id <> public.current_org_id() then return false; end if;
  select coalesce(role_row.permissions, '{}'::jsonb) into v_permissions
  from public.profiles profile_row
  left join public.org_roles role_row on role_row.id = profile_row.role_id and role_row.org_id = profile_row.org_id
  where profile_row.id = auth.uid() and profile_row.org_id = p_org_id
  limit 1;
  if not found then return false; end if;
  return lower(coalesce(v_permissions -> '__saas_admin' ->> 'view', 'false')) = 'true'
    or lower(coalesce(v_permissions -> '__saas_admin' ->> 'edit', 'false')) = 'true'
    or lower(coalesce(v_permissions -> 'instagram_conversations' ->> 'view', 'false')) = 'true';
end;
$$;


--
-- Name: kalam_can_view_module_record_by_assignee(text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_view_module_record_by_assignee(p_module_id text, p_record_org_id uuid, p_assignee_type text DEFAULT NULL::text, p_assignee_id uuid DEFAULT NULL::uuid, p_assignee_role_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid;
  v_permissions jsonb := '{}'::jsonb;
  v_module_perm jsonb := '{}'::jsonb;
  v_scope text;
  v_assignee_type text := lower(trim(coalesce(p_assignee_type, '')));
  v_row_user_id uuid;
  v_row_role_id uuid;
begin
  if v_user_id is null or v_org_id is null or p_record_org_id is distinct from v_org_id then
    return false;
  end if;

  select p.role_id, coalesce(r.permissions, '{}'::jsonb)
  into v_role_id, v_permissions
  from public.profiles p
  left join public.org_roles r
    on r.id = p.role_id
   and r.org_id = p.org_id
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if not found then
    return false;
  end if;

  v_module_perm := coalesce(v_permissions -> nullif(trim(coalesce(p_module_id, '')), ''), '{}'::jsonb);
  if lower(trim(coalesce(v_module_perm ->> 'view', 'true'))) = 'false' then
    return false;
  end if;

  v_scope := lower(trim(coalesce(v_module_perm ->> 'record_scope', 'all')));
  if v_scope = '' then
    v_scope := 'all';
  end if;

  if v_scope = 'all' then
    return true;
  end if;

  if v_assignee_type = 'role' then
    v_row_role_id := coalesce(p_assignee_role_id, p_assignee_id);
  elsif v_assignee_type = 'user' then
    v_row_user_id := p_assignee_id;
  else
    v_row_user_id := p_assignee_id;
    v_row_role_id := p_assignee_role_id;
  end if;

  if v_scope = 'own' then
    return v_row_user_id = v_user_id;
  end if;

  if v_scope = 'team' then
    return v_row_user_id = v_user_id or (v_role_id is not null and v_row_role_id = v_role_id);
  end if;

  if v_scope = 'subtree' then
    return v_row_user_id = v_user_id
      or (
        v_role_id is not null
        and v_row_role_id in (
          with recursive role_tree as (
            select id
            from public.org_roles
            where id = v_role_id
              and org_id = v_org_id
            union all
            select child.id
            from public.org_roles child
            join role_tree parent on child.parent_id = parent.id
            where child.org_id = v_org_id
          )
          select id from role_tree
        )
      )
      or (
        v_row_user_id is not null
        and exists (
          with recursive role_tree as (
            select id
            from public.org_roles
            where id = v_role_id
              and org_id = v_org_id
            union all
            select child.id
            from public.org_roles child
            join role_tree parent on child.parent_id = parent.id
            where child.org_id = v_org_id
          )
          select 1
          from public.profiles p
          where p.id = v_row_user_id
            and p.org_id = v_org_id
            and p.role_id in (select id from role_tree)
        )
      );
  end if;

  return false;
end;
$$;


--
-- Name: kalam_can_view_module_record_from_context(jsonb, uuid, uuid, uuid[], uuid[], text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_view_module_record_from_context(p_permissions jsonb, p_user_id uuid, p_role_id uuid, p_allowed_user_ids uuid[], p_allowed_role_ids uuid[], p_module_id text, p_assignee_type text DEFAULT NULL::text, p_assignee_id uuid DEFAULT NULL::uuid, p_assignee_role_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  with module_context as (
    select
      coalesce(p_permissions -> lower(trim(coalesce(p_module_id, ''))), '{}'::jsonb) as module_permissions
  ), scope_context as (
    select
      module_permissions,
      coalesce(nullif(lower(trim(coalesce(module_permissions ->> 'record_scope', ''))), ''), 'all') as record_scope,
      lower(trim(coalesce(p_assignee_type, ''))) as assignee_type
    from module_context
  ), assignment_context as (
    select
      module_permissions,
      record_scope,
      case
        when assignee_type = 'role' then null::uuid
        else p_assignee_id
      end as row_user_id,
      case
        when assignee_type = 'role' then coalesce(p_assignee_role_id, p_assignee_id)
        when assignee_type = 'user' then null::uuid
        else p_assignee_role_id
      end as row_role_id
    from scope_context
  )
  select case
    when lower(trim(coalesce(module_permissions ->> 'view', 'true'))) = 'false'
      and record_scope = 'all' then false
    when record_scope = 'all' then true
    when record_scope = 'own' then row_user_id = p_user_id
    when record_scope = 'team' then row_user_id = p_user_id or row_role_id = p_role_id
    when record_scope = 'subtree' then
      row_user_id = any(coalesce(p_allowed_user_ids, array[]::uuid[]))
      or row_role_id = any(coalesce(p_allowed_role_ids, array[]::uuid[]))
    else false
  end
  from assignment_context;
$$;


--
-- Name: kalam_can_view_related_communication_target(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_view_related_communication_target(p_module_id text, p_record_id uuid, p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_module_id text := lower(trim(coalesce(p_module_id, '')));
  v_table_name text;
  v_has_assignee_type boolean;
  v_has_assignee_id boolean;
  v_has_assignee_role_id boolean;
  v_org_id uuid;
  v_assignee_type text;
  v_assignee_id uuid;
  v_assignee_role_id uuid;
  v_sql text;
begin
  if p_org_id is null or p_record_id is null then
    return false;
  end if;

  v_table_name := case v_module_id
    when 'customers' then 'customers'
    when 'suppliers' then 'suppliers'
    when 'employees' then 'employees'
    else null
  end;

  if v_table_name is null then
    return false;
  end if;

  select exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = v_table_name and column_name = 'assignee_type'
  ) into v_has_assignee_type;
  select exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = v_table_name and column_name = 'assignee_id'
  ) into v_has_assignee_id;
  select exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = v_table_name and column_name = 'assignee_role_id'
  ) into v_has_assignee_role_id;

  v_sql := format(
    'select org_id, %s, %s, %s from public.%I where id = $1 and org_id = $2 limit 1',
    case when v_has_assignee_type then 'assignee_type::text' else 'null::text' end,
    case when v_has_assignee_id then 'assignee_id::uuid' else 'null::uuid' end,
    case when v_has_assignee_role_id then 'assignee_role_id::uuid' else 'null::uuid' end,
    v_table_name
  );

  execute v_sql
  into v_org_id, v_assignee_type, v_assignee_id, v_assignee_role_id
  using p_record_id, p_org_id;

  if v_org_id is null then
    return false;
  end if;

  return public.kalam_can_view_module_record_by_assignee(
    v_module_id,
    v_org_id,
    v_assignee_type,
    v_assignee_id,
    v_assignee_role_id
  );
exception
  when undefined_table or undefined_column or invalid_text_representation then
    return false;
end;
$_$;


--
-- Name: kalam_can_view_voip_call(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_can_view_voip_call(p_row_org_id uuid, p_assignee_type text DEFAULT NULL::text, p_assignee_id uuid DEFAULT NULL::uuid, p_assignee_role_id uuid DEFAULT NULL::uuid, p_extension text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid;
  v_user_extension text;
  v_permissions jsonb := '{}'::jsonb;
  v_module_perm jsonb := '{}'::jsonb;
  v_scope text;
  v_assignee_type text := lower(trim(coalesce(p_assignee_type, '')));
  v_row_user_id uuid;
  v_row_role_id uuid;
  v_extension text := nullif(trim(coalesce(p_extension, '')), '');
begin
  if v_user_id is null or v_org_id is null or p_row_org_id is distinct from v_org_id then
    return false;
  end if;

  select p.role_id, p.voip_extension, coalesce(r.permissions, '{}'::jsonb)
    into v_role_id, v_user_extension, v_permissions
  from public.profiles p
  left join public.org_roles r
    on r.id = p.role_id
   and r.org_id = p.org_id
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if not found then
    return false;
  end if;

  v_module_perm := coalesce(v_permissions -> 'voip_call_reports', '{}'::jsonb);
  if (
    not (v_permissions ? 'voip_call_reports')
    and lower(coalesce(v_permissions -> '__voip' ->> 'view', 'true')) = 'false'
  )
  or lower(coalesce(v_module_perm ->> 'view', 'true')) = 'false' then
    return false;
  end if;

  v_scope := lower(trim(coalesce(
    nullif(v_module_perm ->> 'record_scope', ''),
    case
      when lower(coalesce(v_permissions -> '__voip' -> 'fields' ->> 'all_call_notifications', 'true')) = 'true' then 'all'
      else 'own'
    end
  )));

  if v_scope = 'all' then
    return true;
  end if;

  if v_assignee_type = 'role' then
    v_row_role_id := coalesce(p_assignee_role_id, p_assignee_id);
  elsif v_assignee_type = 'user' then
    v_row_user_id := p_assignee_id;
  else
    v_row_user_id := p_assignee_id;
    v_row_role_id := p_assignee_role_id;
  end if;

  if v_scope = 'own' then
    return v_row_user_id = v_user_id
      or (
        nullif(trim(coalesce(v_user_extension, '')), '') is not null
        and v_extension = nullif(trim(coalesce(v_user_extension, '')), '')
      );
  end if;

  if v_scope in ('team', 'subtree') then
    return (
      v_row_role_id is not null
      and v_role_id is not null
      and (
        (v_scope = 'team' and v_row_role_id = v_role_id)
        or (
          v_scope = 'subtree'
          and v_row_role_id in (
            with recursive role_tree as (
              select id
              from public.org_roles
              where id = v_role_id and org_id = v_org_id
              union all
              select child.id
              from public.org_roles child
              join role_tree parent on child.parent_id = parent.id
              where child.org_id = v_org_id
            )
            select id from role_tree
          )
        )
      )
    )
    or (
      v_row_user_id is not null
      and exists (
        select 1
        from public.profiles row_profile
        where row_profile.id = v_row_user_id
          and row_profile.org_id = v_org_id
          and (
            (v_scope = 'team' and row_profile.role_id = v_role_id)
            or (
              v_scope = 'subtree'
              and row_profile.role_id in (
                with recursive role_tree as (
                  select id
                  from public.org_roles
                  where id = v_role_id and org_id = v_org_id
                  union all
                  select child.id
                  from public.org_roles child
                  join role_tree parent on child.parent_id = parent.id
                  where child.org_id = v_org_id
                )
                select id from role_tree
              )
            )
          )
      )
    )
    or (
      v_extension is not null
      and exists (
        select 1
        from public.profiles extension_profile
        where extension_profile.org_id = v_org_id
          and nullif(trim(coalesce(extension_profile.voip_extension, '')), '') = v_extension
          and (
            (v_scope = 'team' and extension_profile.role_id = v_role_id)
            or (
              v_scope = 'subtree'
              and extension_profile.role_id in (
                with recursive role_tree as (
                  select id
                  from public.org_roles
                  where id = v_role_id and org_id = v_org_id
                  union all
                  select child.id
                  from public.org_roles child
                  join role_tree parent on child.parent_id = parent.id
                  where child.org_id = v_org_id
                )
                select id from role_tree
              )
            )
          )
      )
    );
  end if;

  return false;
end;
$$;


--
-- Name: kalam_counterparty_bot_group_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_counterparty_bot_group_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_is_org_wide boolean := true;
begin
  if new.org_id is null then
    return new;
  end if;

  v_target_users := public.kalam_jsonb_uuid_array(new.metadata->'allowed_user_ids');
  v_target_roles := public.kalam_jsonb_uuid_array(new.metadata->'allowed_role_ids');
  if new.created_by is not null then
    v_target_users := public.kalam_distinct_uuid_array(v_target_users || array[new.created_by]);
  end if;
  v_is_org_wide := cardinality(v_target_users) = 0 and cardinality(v_target_roles) = 0;

  perform public.kalam_upsert_notification_item(
    new.org_id,
    'counterparty_bot_group',
    new.id::text,
    'bot_messages',
    coalesce(nullif(trim(new.channel_type), ''), 'bot'),
    lower(tg_op),
    coalesce(nullif(trim(new.group_title), ''), nullif(trim(new.group_platform_id), ''), 'گروه بات'),
    nullif(trim(new.status), ''),
    case when new.customer_id is not null then 'customers' when new.supplier_id is not null then 'suppliers' else null end,
    coalesce(new.customer_id::text, new.supplier_id::text, null),
    v_target_users,
    v_target_roles,
    v_is_org_wide,
    jsonb_build_object('status', new.status, 'target_type', new.target_type),
    coalesce(new.updated_at, new.created_at, now())
  );

  return new;
end;
$$;


--
-- Name: kalam_counterparty_bot_message_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_counterparty_bot_message_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_group record;
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_is_org_wide boolean := true;
  v_conversation_key text := null;
begin
  if new.org_id is null then
    return new;
  end if;

  if new.bot_group_id is not null then
    select *
    into v_group
    from public.counterparty_bot_groups g
    where g.id = new.bot_group_id
      and g.org_id = new.org_id
    limit 1;

    if found then
      v_target_users := public.kalam_jsonb_uuid_array(v_group.metadata->'allowed_user_ids');
      v_target_roles := public.kalam_jsonb_uuid_array(v_group.metadata->'allowed_role_ids');
      v_conversation_key := 'bot:' || new.bot_group_id::text;
    end if;
  end if;

  if new.created_by is not null then
    v_target_users := public.kalam_distinct_uuid_array(v_target_users || array[new.created_by]);
  end if;
  v_is_org_wide := cardinality(v_target_users) = 0 and cardinality(v_target_roles) = 0;

  perform public.kalam_upsert_notification_item(
    new.org_id,
    'counterparty_bot_message',
    new.id::text,
    'bot_messages',
    coalesce(nullif(trim(new.channel_type), ''), 'bot'),
    lower(tg_op),
    coalesce(nullif(trim(new.channel_type), ''), 'Bot message'),
    nullif(left(coalesce(new.content_text, ''), 240), ''),
    case when new.customer_id is not null then 'customers' when new.supplier_id is not null then 'suppliers' else null end,
    coalesce(new.customer_id::text, new.supplier_id::text, null),
    v_target_users,
    v_target_roles,
    v_is_org_wide,
    jsonb_build_object(
      'bot_group_id', new.bot_group_id,
      'direction', new.direction,
      'message_type', new.message_type,
      'conversation_key', v_conversation_key
    ),
    coalesce(new.created_at, now())
  );

  update public.notification_inbox_items
  set conversation_key = v_conversation_key
  where org_id = new.org_id
    and source_type = 'counterparty_bot_message'
    and source_id = new.id::text
    and coalesce(conversation_key, '') <> coalesce(v_conversation_key, '');

  return new;
end;
$$;


--
-- Name: kalam_current_profile_role_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_current_profile_role_id(p_org_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 select m.role_id from public.user_organization_memberships m
 where m.user_id=auth.uid() and m.org_id=public.current_org_id() and m.is_active
 and (p_org_id is null or m.org_id=p_org_id) limit 1;
$$;


--
-- Name: kalam_cursor_value(timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_cursor_value(p_created_at timestamp with time zone, p_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_created_at is null or nullif(trim(coalesce(p_id, '')), '') is null then null
    else to_char(p_created_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') || '|' || trim(p_id)
  end
$$;


--
-- Name: kalam_direct_conversation_key(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_direct_conversation_key(p_user_a uuid, p_user_b uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_user_a is null or p_user_b is null then null
    when p_user_a::text <= p_user_b::text then 'direct:' || p_user_a::text || ':' || p_user_b::text
    else 'direct:' || p_user_b::text || ':' || p_user_a::text
  end
$$;


--
-- Name: kalam_distinct_uuid_array(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_distinct_uuid_array(p_ids uuid[]) RETURNS uuid[]
    LANGUAGE sql IMMUTABLE
    AS $$
  select coalesce(array_agg(distinct item order by item), '{}'::uuid[])
  from unnest(coalesce(p_ids, '{}'::uuid[])) as item
  where item is not null
$$;


--
-- Name: kalam_emit_module_list_invalidation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_emit_module_list_invalidation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_module_id text := nullif(trim(coalesce(tg_argv[0], '')), '');
  v_row jsonb;
  v_org_id uuid;
  v_record_id text;
  v_action text := lower(tg_op);
  v_updated_at timestamptz;
  v_scope_hint jsonb;
begin
  if v_module_id is null then
    return coalesce(new, old);
  end if;

  v_row := case
    when tg_op = 'DELETE' then to_jsonb(old)
    else to_jsonb(new)
  end;

  v_org_id := nullif(v_row ->> 'org_id', '')::uuid;
  if v_org_id is null then
    return coalesce(new, old);
  end if;

  v_record_id := nullif(v_row ->> 'id', '');
  v_updated_at := coalesce(
    nullif(v_row ->> 'updated_at', '')::timestamptz,
    nullif(v_row ->> 'created_at', '')::timestamptz,
    now()
  );
  v_scope_hint := jsonb_strip_nulls(jsonb_build_object(
    'assignee_user_id', nullif(v_row ->> 'assignee_id', ''),
    'assignee_role_id', nullif(v_row ->> 'assignee_role_id', '')
  ));

  perform public.kalam_broadcast_module_list_invalidation(
    v_org_id,
    v_module_id,
    v_record_id,
    v_action,
    v_updated_at,
    coalesce(v_scope_hint, '{}'::jsonb)
  );

  return coalesce(new, old);
end;
$$;


--
-- Name: kalam_emit_notification_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_emit_notification_item() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_payload jsonb;
  v_user_id uuid;
  v_role_id uuid;
begin
  v_payload := jsonb_build_object(
    'id', new.id,
    'org_id', new.org_id,
    'source_type', new.source_type,
    'source_id', new.source_id,
    'section', new.section,
    'category', new.category,
    'action', new.action,
    'module_id', new.module_id,
    'record_id', new.record_id,
    'last_event_at', new.last_event_at,
    'targeted', not new.is_org_wide
  );

  if new.is_org_wide then
    perform public.kalam_broadcast_notification(public.kalam_realtime_org_topic(new.org_id), 'notification', v_payload);
  end if;

  foreach v_user_id in array public.kalam_distinct_uuid_array(new.target_user_ids) loop
    perform public.kalam_broadcast_notification(public.kalam_realtime_user_topic(new.org_id, v_user_id), 'notification', v_payload);
  end loop;

  foreach v_role_id in array public.kalam_distinct_uuid_array(new.target_role_ids) loop
    perform public.kalam_broadcast_notification(public.kalam_realtime_role_topic(new.org_id, v_role_id), 'notification', v_payload);
  end loop;

  return new;
end;
$$;


--
-- Name: kalam_emit_process_parent_module_list_invalidation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_emit_process_parent_module_list_invalidation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row jsonb;
  v_action text := lower(tg_op);
  v_updated_at timestamptz;
  v_org_id uuid;
  v_module_id text;
  v_record_id text;
  v_process_run_id text;
  v_process_run_stage_id text;
  v_task_id text;
  v_scope_hint jsonb;
begin
  v_row := case
    when tg_op = 'DELETE' then to_jsonb(old)
    else to_jsonb(new)
  end;

  v_updated_at := coalesce(
    nullif(v_row ->> 'updated_at', '')::timestamptz,
    nullif(v_row ->> 'created_at', '')::timestamptz,
    now()
  );

  if tg_table_name = 'process_runs' then
    v_org_id := public.kalam_try_uuid(v_row ->> 'org_id');
    v_module_id := nullif(btrim(coalesce(v_row ->> 'module_id', '')), '');
    v_record_id := nullif(btrim(coalesce(v_row ->> 'record_id', '')), '');
    v_process_run_id := nullif(btrim(coalesce(v_row ->> 'id', '')), '');
  elsif tg_table_name = 'process_run_stages' then
    v_process_run_stage_id := nullif(btrim(coalesce(v_row ->> 'id', '')), '');
    v_process_run_id := nullif(btrim(coalesce(v_row ->> 'process_run_id', '')), '');
    if public.kalam_try_uuid(v_process_run_id) is not null then
      select pr.org_id,
             nullif(btrim(coalesce(pr.module_id, '')), ''),
             pr.record_id::text
      into v_org_id, v_module_id, v_record_id
      from public.process_runs pr
      where pr.id = public.kalam_try_uuid(v_process_run_id)
      limit 1;
    end if;
  elsif tg_table_name = 'tasks' then
    v_task_id := nullif(btrim(coalesce(v_row ->> 'id', '')), '');
    v_process_run_id := nullif(btrim(coalesce(v_row ->> 'process_run_id', '')), '');
    v_process_run_stage_id := nullif(btrim(coalesce(v_row ->> 'process_run_stage_id', '')), '');
    if public.kalam_try_uuid(v_process_run_id) is null and public.kalam_try_uuid(v_process_run_stage_id) is not null then
      select prs.process_run_id::text
      into v_process_run_id
      from public.process_run_stages prs
      where prs.id = public.kalam_try_uuid(v_process_run_stage_id)
      limit 1;
    end if;
    if public.kalam_try_uuid(v_process_run_id) is not null then
      select pr.org_id,
             nullif(btrim(coalesce(pr.module_id, '')), ''),
             pr.record_id::text
      into v_org_id, v_module_id, v_record_id
      from public.process_runs pr
      where pr.id = public.kalam_try_uuid(v_process_run_id)
      limit 1;
    end if;
  end if;

  v_scope_hint := jsonb_strip_nulls(jsonb_build_object(
    'source', 'process_v2',
    'process_run_id', nullif(btrim(coalesce(v_process_run_id, '')), ''),
    'process_run_stage_id', nullif(btrim(coalesce(v_process_run_stage_id, '')), ''),
    'task_id', nullif(btrim(coalesce(v_task_id, '')), ''),
    'assignee_user_id', nullif(btrim(coalesce(v_row ->> 'assignee_id', '')), ''),
    'assignee_role_id', nullif(btrim(coalesce(v_row ->> 'assignee_role_id', '')), '')
  ));

  if v_org_id is not null and v_module_id is not null and v_record_id is not null then
    perform public.kalam_broadcast_module_list_invalidation(
      v_org_id,
      v_module_id,
      v_record_id,
      v_action,
      v_updated_at,
      coalesce(v_scope_hint, '{}'::jsonb)
    );
  end if;

  if v_org_id is not null and v_process_run_id is not null then
    perform public.kalam_broadcast_module_list_invalidation(
      v_org_id,
      'process_runs',
      v_process_run_id,
      v_action,
      v_updated_at,
      coalesce(v_scope_hint, '{}'::jsonb)
    );
  end if;

  return coalesce(new, old);
end;
$$;


--
-- Name: kalam_enrich_sms_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_enrich_sms_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lookup jsonb;
  v_counterparty_phone text;
begin
  if new.channel_type <> 'sms' or new.org_id is null then
    return new;
  end if;

  new.direction := coalesce(nullif(trim(new.direction), ''), 'outbound');
  new.sender := nullif(trim(coalesce(new.sender, '')), '');
  new.recipient := nullif(trim(coalesce(new.recipient, '')), '');
  if new.direction = 'inbound' and new.received_at is null then
    new.received_at := coalesce(new.sent_at, new.created_at, now());
  end if;

  -- A non-contact module is the source of the message, never its counterparty.
  if new.module_id is not null
    and new.record_id is not null
    and new.module_id not in ('customers', 'suppliers', 'employees', 'profiles') then
    new.related_module_id := coalesce(nullif(trim(new.related_module_id), ''), new.module_id);
    new.related_record_id := coalesce(nullif(trim(new.related_record_id), ''), new.record_id);
    new.module_id := null;
    new.record_id := null;
    new.customer_id := null;
  end if;

  v_counterparty_phone := case when new.direction = 'inbound' then new.sender else new.recipient end;
  new.phone_number_id := coalesce(new.phone_number_id, public.kalam_upsert_phone_number(new.org_id, v_counterparty_phone));
  v_lookup := public.kalam_find_phone_target(new.org_id, v_counterparty_phone);

  if v_lookup is not null then
    new.phone_match_status := coalesce(nullif(v_lookup->>'match_status', ''), 'unknown');
    if new.phone_number_id is null and public.kalam_try_uuid(v_lookup->>'phone_number_id') is not null then
      new.phone_number_id := public.kalam_try_uuid(v_lookup->>'phone_number_id');
    end if;
    if new.phone_match_status in ('matched', 'manual') then
      new.module_id := nullif(v_lookup->>'module_id', '');
      new.record_id := nullif(v_lookup->>'record_id', '');
      new.customer_id := public.kalam_try_uuid(v_lookup->>'customer_id');
      new.title := coalesce(nullif(v_lookup->>'title', ''), new.title);
    elsif new.module_id not in ('customers', 'suppliers', 'employees', 'profiles') then
      new.module_id := null;
      new.record_id := null;
      new.customer_id := null;
    end if;
  else
    new.phone_match_status := 'unknown';
  end if;

  new.assignee_type := case
    when new.assignee_role_id is not null then 'role'
    when lower(nullif(new.assignee_type, '')) = 'role' and new.assignee_id is not null then 'role'
    when new.assignee_id is not null then coalesce(nullif(new.assignee_type, ''), 'user')
    else nullif(new.assignee_type, '')
  end;
  if new.assignee_role_id is not null then new.assignee_id := null; end if;
  if nullif(trim(coalesce(new.title, '')), '') is null then
    new.title := case when new.direction = 'inbound' then coalesce(new.sender, new.recipient, 'پیامک ورودی') else coalesce(new.recipient, new.sender, 'پیامک') end;
  end if;
  return new;
end;
$$;


--
-- Name: kalam_enrich_voip_call_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_enrich_voip_call_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lookup jsonb;
  v_phone text;
  v_assignee_id uuid;
  v_assignee_count integer := 0;
  v_assignee_name text;
  v_assignee_avatar text;
  v_binding_profile_id uuid;
  v_provider_operator_id text;
begin
  if new.org_id is null then return new; end if;

  new.extension := nullif(trim(coalesce(new.extension, '')), '');
  new.operator_code := nullif(trim(coalesce(new.operator_code, '')), '');
  new.source_number := nullif(trim(coalesce(new.source_number, '')), '');
  new.destination_number := nullif(trim(coalesce(new.destination_number, '')), '');
  new.metadata := coalesce(new.metadata, '{}'::jsonb);
  v_provider_operator_id := nullif(trim(coalesce(new.metadata->>'provider_operator_id', '')), '');

  -- A confirmed tenant binding wins over heuristic matching.
  select b.profile_id into v_binding_profile_id
  from public.voip_operator_identity_bindings b
  where b.org_id = new.org_id
    and b.provider = coalesce(nullif(trim(new.provider), ''), 'telefonchy')
    and (b.service_id is null or b.service_id = new.service_id)
    and (
      (new.extension is not null and b.extension = new.extension)
      or (new.operator_code is not null and b.operator_code = new.operator_code)
      or (v_provider_operator_id is not null and b.provider_operator_id = v_provider_operator_id)
    )
  order by case when v_provider_operator_id is not null and b.provider_operator_id = v_provider_operator_id then 0 else 1 end,
           updated_at desc
  limit 1;

  if v_binding_profile_id is not null then
    new.assignee_id := v_binding_profile_id;
  elsif new.assignee_id is null and (new.extension is not null or new.operator_code is not null) then
    select count(*), (array_agg(p.id order by p.id))[1]
      into v_assignee_count, v_assignee_id
    from public.profiles p
    where p.org_id = new.org_id
      and p.voip_enabled = true
      and (
        (new.extension is not null and nullif(trim(coalesce(p.voip_extension, '')), '') = new.extension)
        or (new.operator_code is not null and nullif(trim(coalesce(p.voip_operator_code, '')), '') = new.operator_code)
      );
    if v_assignee_count = 1 then new.assignee_id := v_assignee_id; end if;
  end if;

  if new.assignee_id is not null then
    select nullif(trim(coalesce(p.full_name, '')), ''), p.avatar_url
      into v_assignee_name, v_assignee_avatar
    from public.profiles p
    where p.id = new.assignee_id and p.org_id = new.org_id
    limit 1;
  end if;

  v_phone := case
    when coalesce(new.direction, '') = 'incoming' then new.source_number
    when coalesce(new.direction, '') = 'outgoing' then new.destination_number
    else coalesce(new.source_number, new.destination_number)
  end;
  new.phone_number_id := coalesce(new.phone_number_id, public.kalam_upsert_phone_number(new.org_id, v_phone));
  v_lookup := public.kalam_find_phone_target(new.org_id, v_phone);
  if v_lookup is not null then
    new.phone_match_status := coalesce(nullif(v_lookup->>'match_status', ''), 'unknown');
    if new.phone_number_id is null and public.kalam_try_uuid(v_lookup->>'phone_number_id') is not null then
      new.phone_number_id := public.kalam_try_uuid(v_lookup->>'phone_number_id');
    end if;
    if new.phone_match_status in ('matched', 'manual') then
      new.module_id := nullif(v_lookup->>'module_id', '');
      new.record_id := nullif(v_lookup->>'record_id', '');
      new.title := coalesce(nullif(v_lookup->>'title', ''), new.title);
    end if;
  else
    new.phone_match_status := 'unknown';
  end if;

  new.assignee_type := case
    when new.assignee_role_id is not null then 'role'
    when lower(nullif(new.assignee_type, '')) = 'role' and new.assignee_id is not null then 'role'
    when new.assignee_id is not null then coalesce(nullif(new.assignee_type, ''), 'user')
    else nullif(new.assignee_type, '')
  end;
  if new.assignee_role_id is not null then new.assignee_id := null; end if;

  new.metadata := new.metadata || jsonb_strip_nulls(jsonb_build_object(
    'operator_display_name', coalesce(v_assignee_name, nullif(trim(coalesce(new.metadata->>'provider_operator_name', '')), '')),
    'operator_avatar_url', v_assignee_avatar,
    'operator_extension', new.extension,
    'operator_code', new.operator_code,
    'operator_resolution', case
      when v_binding_profile_id is not null then 'manual'
      when new.assignee_id is not null then 'matched'
      when v_assignee_count > 1 then 'ambiguous'
      else 'unknown'
    end
  ));
  if nullif(trim(coalesce(new.title, '')), '') is null then new.title := coalesce(v_phone, 'تماس VoIP'); end if;
  return new;
end;
$$;


--
-- Name: kalam_extract_note_attachment_previews(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_extract_note_attachment_previews(p_content text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_payload jsonb;
begin
  if nullif(trim(coalesce(p_content, '')), '') is null then
    return '[]'::jsonb;
  end if;

  begin
    v_payload := p_content::jsonb;
  exception when others then
    return '[]'::jsonb;
  end;

  if jsonb_typeof(v_payload) <> 'object'
     or jsonb_typeof(v_payload -> 'attachments') <> 'array' then
    return '[]'::jsonb;
  end if;

  return (
    select coalesce(jsonb_agg(
      jsonb_build_object(
        'name', coalesce(nullif(trim(item ->> 'name'), ''), nullif(trim(item ->> 'file_name'), ''), 'فایل'),
        'url', nullif(trim(coalesce(item ->> 'url', item ->> 'file_url', '')), ''),
        'mime_type', nullif(trim(coalesce(item ->> 'mimeType', item ->> 'mime_type', '')), ''),
        'file_type', nullif(trim(coalesce(item ->> 'fileType', item ->> 'file_type', '')), '')
      )
    ) filter (where nullif(trim(coalesce(item ->> 'url', item ->> 'file_url', '')), '') is not null), '[]'::jsonb)
    from jsonb_array_elements(v_payload -> 'attachments') item
  );
end;
$$;


--
-- Name: kalam_find_phone_target(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_find_phone_target(p_org_id uuid, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_key text := public.kalam_phone_lookup_key(p_phone);
  v_phone_number_id uuid;
  v_count integer;
  v_result jsonb;
begin
  if p_org_id is null or v_key = '' then
    return null;
  end if;

  select id
  into v_phone_number_id
  from public.phone_numbers
  where org_id = p_org_id
    and lookup_key = v_key
  limit 1;

  if v_phone_number_id is null then
    return jsonb_build_object('match_status', 'unknown');
  end if;

  with candidate_links as (
    select
      l.*,
      case
        when l.entity_type = 'profiles' and employee.id is not null then 'employees'
        else l.entity_type
      end as resolved_entity_type,
      coalesce(employee.id, l.entity_id) as resolved_entity_id,
      coalesce(
        nullif(trim(coalesce(employee.full_name, '')), ''),
        nullif(trim(coalesce(employee.system_code, '')), ''),
        nullif(trim(coalesce(l.display_title, '')), ''),
        p_phone
      ) as resolved_title,
      case
        when l.source_table = 'manual_phone_binding' and l.source_field = 'identity' then 0
        when l.entity_type = 'employees' then 1
        when l.entity_type = 'customers' then 2
        when l.entity_type = 'suppliers' then 3
        -- A converted lead should resolve as its customer/supplier first.
        when l.entity_type = 'marketing_leads' then 4
        when l.entity_type = 'profiles' and employee.id is not null then 1
        when l.entity_type = 'profiles' then 5
        else 99
      end as entity_priority,
      case
        when l.source_table = 'manual_phone_binding' and l.source_field = 'identity' then 0
        when l.label in ('mobile', 'primary_mobile') then 1
        when l.label = 'secondary_mobile' then 2
        when l.label = 'phone' then 3
        when l.label = 'assistant_phone' then 4
        else 9
      end as field_priority
    from public.phone_number_links l
    left join public.employees employee
      on l.entity_type = 'profiles'
     and employee.org_id = l.org_id
     and employee.related_profile_id = l.entity_id
    where l.org_id = p_org_id
      and l.phone_number_id = v_phone_number_id
      and l.entity_type in ('customers', 'suppliers', 'employees', 'marketing_leads', 'profiles')
  ),
  priority_bucket as (
    select *
    from candidate_links
    where entity_priority = (select min(entity_priority) from candidate_links)
  )
  select count(*) into v_count
  from (
    select distinct resolved_entity_type, resolved_entity_id
    from priority_bucket
  ) distinct_entities;

  if coalesce(v_count, 0) = 0 then
    return jsonb_build_object('match_status', 'unknown', 'phone_number_id', v_phone_number_id);
  end if;

  if v_count > 1 then
    return jsonb_build_object(
      'match_status', 'ambiguous',
      'phone_number_id', v_phone_number_id,
      'match_count', v_count
    );
  end if;

  with candidate_links as (
    select
      l.*,
      case
        when l.entity_type = 'profiles' and employee.id is not null then 'employees'
        else l.entity_type
      end as resolved_entity_type,
      coalesce(employee.id, l.entity_id) as resolved_entity_id,
      coalesce(
        nullif(trim(coalesce(employee.full_name, '')), ''),
        nullif(trim(coalesce(employee.system_code, '')), ''),
        nullif(trim(coalesce(l.display_title, '')), ''),
        p_phone
      ) as resolved_title,
      case
        when l.source_table = 'manual_phone_binding' and l.source_field = 'identity' then 0
        when l.entity_type = 'employees' then 1
        when l.entity_type = 'customers' then 2
        when l.entity_type = 'suppliers' then 3
        when l.entity_type = 'marketing_leads' then 4
        when l.entity_type = 'profiles' and employee.id is not null then 1
        when l.entity_type = 'profiles' then 5
        else 99
      end as entity_priority,
      case
        when l.source_table = 'manual_phone_binding' and l.source_field = 'identity' then 0
        when l.label in ('mobile', 'primary_mobile') then 1
        when l.label = 'secondary_mobile' then 2
        when l.label = 'phone' then 3
        when l.label = 'assistant_phone' then 4
        else 9
      end as field_priority
    from public.phone_number_links l
    left join public.employees employee
      on l.entity_type = 'profiles'
     and employee.org_id = l.org_id
     and employee.related_profile_id = l.entity_id
    where l.org_id = p_org_id
      and l.phone_number_id = v_phone_number_id
      and l.entity_type in ('customers', 'suppliers', 'employees', 'marketing_leads', 'profiles')
  )
  select jsonb_build_object(
    'match_status', case when source_table = 'manual_phone_binding' and source_field = 'identity' then 'manual' else 'matched' end,
    'phone_number_id', v_phone_number_id,
    'module_id', resolved_entity_type,
    'record_id', resolved_entity_id::text,
    'customer_id', case when resolved_entity_type = 'customers' then resolved_entity_id::text else null end,
    'title', resolved_title,
    'label', label,
    'source_table', source_table,
    'source_field', source_field
  )
  into v_result
  from candidate_links
  order by entity_priority asc, is_primary desc, field_priority asc, updated_at desc nulls last, id desc
  limit 1;

  return v_result;
end;
$$;


--
-- Name: kalam_internal_message_conversation_key_v3(uuid, uuid, uuid, uuid[], uuid[], text, jsonb, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_internal_message_conversation_key_v3(p_org_id uuid, p_note_id uuid, p_author_id uuid, p_mention_user_ids uuid[], p_mention_role_ids uuid[], p_source_type text, p_metadata jsonb, p_reply_to uuid, p_viewer_id uuid, p_viewer_role_id uuid, p_inbox_category text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_source text := lower(trim(coalesce(nullif(p_source_type, ''), nullif(v_metadata->>'source_type', ''), '')));
  v_group_id text := nullif(trim(coalesce(v_metadata->>'chat_group_id', '')), '');
  v_agent_conv_key text := public.kalam_resolve_agent_conversation_key_v1(v_metadata);
  v_user_mentions uuid[] := coalesce(p_mention_user_ids, '{}'::uuid[]);
  v_role_mentions uuid[] := coalesce(p_mention_role_ids, '{}'::uuid[]);
begin
  if v_group_id is not null then
    return 'group:' || v_group_id;
  end if;

  if v_agent_conv_key is not null then
    return v_agent_conv_key;
  end if;

  if public.kalam_internal_message_is_system_v2(v_source, v_metadata, p_inbox_category) then
    return 'system';
  end if;

  if p_author_id is null then
    return null;
  end if;

  if p_viewer_id is not null
    and p_author_id <> p_viewer_id
    and (
      p_viewer_id = any(v_user_mentions)
      or (p_viewer_role_id is not null and p_viewer_role_id = any(v_role_mentions))
    ) then
    return public.kalam_direct_conversation_key(p_viewer_id, p_author_id);
  end if;

  if p_author_id = p_viewer_id and cardinality(v_user_mentions) = 0 then
    return 'mine';
  end if;

  return public.kalam_note_conversation_key(
    p_org_id, p_note_id, p_author_id, v_user_mentions, v_source, v_metadata, p_reply_to
  );
end;
$$;


--
-- Name: kalam_internal_message_conversation_rows_v4(uuid, uuid, uuid, uuid[], uuid[], text, jsonb, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_internal_message_conversation_rows_v4(p_org_id uuid, p_note_id uuid, p_author_id uuid, p_mention_user_ids uuid[], p_mention_role_ids uuid[], p_source_type text, p_metadata jsonb, p_reply_to uuid, p_viewer_id uuid, p_viewer_role_id uuid, p_inbox_category text DEFAULT NULL::text) RETURNS TABLE(conversation_key text, peer_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_group_id uuid := public.kalam_try_uuid(v_metadata->>'chat_group_id');
  v_agent_conv_key text := public.kalam_resolve_agent_conversation_key_v1(v_metadata);
  v_fallback_key text;
begin
  if p_viewer_id is null then
    return;
  end if;

  if v_group_id is not null then
    return query select 'group:' || v_group_id::text, null::uuid;
    return;
  end if;

  if v_agent_conv_key is not null then
    return query select v_agent_conv_key, null::uuid;
    return;
  end if;

  if public.kalam_internal_message_is_system_v2(
    p_source_type,
    v_metadata,
    p_inbox_category
  ) then
    return query select 'system'::text, null::uuid;
    return;
  end if;

  if p_author_id is null then
    return;
  end if;

  if p_author_id = p_viewer_id then
    if exists (
      select 1
      from public.kalam_internal_message_direct_peers_v4(
        p_org_id,
        p_author_id,
        p_mention_user_ids,
        p_mention_role_ids
      )
    ) then
      return query
      select public.kalam_direct_conversation_key(p_author_id, peer.peer_id), peer.peer_id
      from public.kalam_internal_message_direct_peers_v4(
        p_org_id,
        p_author_id,
        p_mention_user_ids,
        p_mention_role_ids
      ) peer;
      return;
    end if;

    return query select 'mine'::text, null::uuid;
    return;
  end if;

  if p_viewer_id = any(coalesce(p_mention_user_ids, '{}'::uuid[]))
    or (
      p_viewer_role_id is not null
      and p_viewer_role_id = any(coalesce(p_mention_role_ids, '{}'::uuid[]))
    ) then
    return query select public.kalam_direct_conversation_key(p_viewer_id, p_author_id), p_author_id;
    return;
  end if;

  v_fallback_key := public.kalam_internal_message_conversation_key_v3(
    p_org_id,
    p_note_id,
    p_author_id,
    coalesce(p_mention_user_ids, '{}'::uuid[]),
    coalesce(p_mention_role_ids, '{}'::uuid[]),
    p_source_type,
    v_metadata,
    p_reply_to,
    p_viewer_id,
    p_viewer_role_id,
    p_inbox_category
  );
  if nullif(trim(coalesce(v_fallback_key, '')), '') is not null then
    return query select v_fallback_key, null::uuid;
  end if;
end;
$$;


--
-- Name: kalam_internal_message_direct_peers_v4(uuid, uuid, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_internal_message_direct_peers_v4(p_org_id uuid, p_author_id uuid, p_mention_user_ids uuid[] DEFAULT '{}'::uuid[], p_mention_role_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS TABLE(peer_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct candidate.peer_id
  from (
    select mentioned_user_id as peer_id
    from unnest(coalesce(p_mention_user_ids, '{}'::uuid[])) as mentioned_user_id
    where mentioned_user_id is not null
      and mentioned_user_id is distinct from p_author_id

    union

    select profile.id as peer_id
    from public.profiles profile
    where profile.org_id = p_org_id
      and profile.role_id = any(coalesce(p_mention_role_ids, '{}'::uuid[]))
      and profile.id is distinct from p_author_id
  ) candidate
  where candidate.peer_id is not null;
$$;


--
-- Name: kalam_internal_message_is_system_v2(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_internal_message_is_system_v2(p_source_type text, p_metadata jsonb, p_inbox_category text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select lower(trim(coalesce(p_inbox_category, ''))) in ('system', 'assistant')
    or lower(trim(coalesce(nullif(p_source_type, ''), coalesce(p_metadata, '{}'::jsonb)->>'source_type', ''))) in ('system', 'ai', 'assistant')
    or coalesce(p_metadata, '{}'::jsonb) ?| array[
      'workflow_id', 'automation_rule_id', 'process_automation_rule_id',
      'workflow_action_type', 'scheduled_report_id'
    ];
$$;


--
-- Name: kalam_internal_message_matches_conversation_v4(uuid, uuid, uuid, uuid[], uuid[], text, jsonb, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_internal_message_matches_conversation_v4(p_org_id uuid, p_note_id uuid, p_author_id uuid, p_mention_user_ids uuid[], p_mention_role_ids uuid[], p_source_type text, p_metadata jsonb, p_reply_to uuid, p_viewer_id uuid, p_viewer_role_id uuid, p_inbox_category text, p_conversation_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.kalam_internal_message_conversation_rows_v4(
      p_org_id,
      p_note_id,
      p_author_id,
      p_mention_user_ids,
      p_mention_role_ids,
      p_source_type,
      p_metadata,
      p_reply_to,
      p_viewer_id,
      p_viewer_role_id,
      p_inbox_category
    ) resolved
    where resolved.conversation_key = nullif(trim(coalesce(p_conversation_key, '')), '')
  );
$$;


--
-- Name: kalam_internal_message_peer_id_v3(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_internal_message_peer_id_v3(p_conversation_key text, p_viewer_id uuid) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
  v_left_text text := nullif(split_part(coalesce(p_conversation_key, ''), ':', 2), '');
  v_right_text text := nullif(split_part(coalesce(p_conversation_key, ''), ':', 3), '');
  v_left uuid;
  v_right uuid;
begin
  if coalesce(p_conversation_key, '') not like 'direct:%' then
    return null;
  end if;
  if v_left_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or v_right_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return null;
  end if;
  v_left := v_left_text::uuid;
  v_right := v_right_text::uuid;
  return case when v_left = p_viewer_id then v_right else v_left end;
end;
$_$;


--
-- Name: kalam_jsonb_uuid_array(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_jsonb_uuid_array(p_value jsonb) RETURNS uuid[]
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_item text;
  v_ids uuid[] := '{}'::uuid[];
begin
  if p_value is null or jsonb_typeof(p_value) <> 'array' then
    return v_ids;
  end if;

  for v_item in select jsonb_array_elements_text(p_value) loop
    if public.kalam_try_uuid(v_item) is not null then
      v_ids := array_append(v_ids, public.kalam_try_uuid(v_item));
    end if;
  end loop;

  return public.kalam_distinct_uuid_array(v_ids);
end;
$$;


--
-- Name: kalam_matches_instagram_conversation_condition(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_matches_instagram_conversation_condition(p_conversation_id uuid, p_condition jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_conversation record;
  v_field text := lower(coalesce(p_condition ->> 'field', p_condition ->> 'field_key', ''));
  v_operator text := lower(coalesce(p_condition ->> 'operator', 'eq'));
  v_expected jsonb := coalesce(p_condition -> 'value', 'null'::jsonb);
  v_expected_text text := trim(both '"' from coalesce(p_condition -> 'value', '""'::jsonb)::text);
  v_actual text := '';
begin
  select * into v_conversation from public.instagram_conversations where id = p_conversation_id limit 1;
  if not found then return false; end if;
  if v_field in ('tag', 'tags') then
    if v_operator in ('contains', 'has', 'equals', 'eq', 'in') then
      return case when jsonb_typeof(v_expected) = 'array'
        then coalesce(v_conversation.tags, '[]'::jsonb) ?| array(select jsonb_array_elements_text(v_expected))
        else coalesce(v_conversation.tags, '[]'::jsonb) ? v_expected_text end;
    end if;
    if v_operator in ('not_contains', 'not_has', 'not_equals', 'neq', 'not_in') then
      return case when jsonb_typeof(v_expected) = 'array'
        then not (coalesce(v_conversation.tags, '[]'::jsonb) ?| array(select jsonb_array_elements_text(v_expected)))
        else not (coalesce(v_conversation.tags, '[]'::jsonb) ? v_expected_text) end;
    end if;
    return false;
  end if;
  v_actual := case v_field
    when 'account_id' then v_conversation.account_id::text
    when 'status' then coalesce(v_conversation.status, '')
    when 'priority' then coalesce(v_conversation.priority, '')
    when 'assignee_user_id' then coalesce(v_conversation.assignee_user_id::text, '')
    when 'assignee_role_id' then coalesce(v_conversation.assignee_role_id::text, '')
    else '' end;
  if v_operator in ('eq', 'equals') then return v_actual = v_expected_text; end if;
  if v_operator in ('neq', 'not_equals') then return v_actual <> v_expected_text; end if;
  if v_operator = 'contains' then return position(v_expected_text in v_actual) > 0; end if;
  if v_operator = 'not_contains' then return position(v_expected_text in v_actual) = 0; end if;
  if v_operator in ('in', 'one_of') and jsonb_typeof(v_expected) = 'array' then return v_actual = any(array(select jsonb_array_elements_text(v_expected))); end if;
  if v_operator in ('not_in', 'not_one_of') and jsonb_typeof(v_expected) = 'array' then return not (v_actual = any(array(select jsonb_array_elements_text(v_expected)))); end if;
  if v_operator = 'is_null' then return v_actual = ''; end if;
  if v_operator = 'not_null' then return v_actual <> ''; end if;
  return false;
end;
$$;


--
-- Name: kalam_message_read_receipts_v1(uuid, text, text, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_message_read_receipts_v1(p_org_id uuid, p_channel text, p_conversation_key text, p_author_id uuid, p_created_at timestamp with time zone, p_message_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    jsonb_object_agg(
      reader.user_id::text,
      jsonb_build_object(
        'user_id', reader.user_id::text,
        'user_name', coalesce(nullif(trim(reader_profile.full_name), ''), 'کاربر'),
        'read_at', reader.updated_at
      )
    ),
    '{}'::jsonb
  )
  from public.communication_read_cursors reader
  left join public.profiles reader_profile
    on reader_profile.id = reader.user_id
   and reader_profile.org_id = reader.org_id
  where reader.org_id = p_org_id
    and reader.channel = p_channel
    and reader.conversation_key = p_conversation_key
    and (p_author_id is null or reader.user_id <> p_author_id)
    and reader.read_through_at is not null
    and (
      p_created_at < reader.read_through_at
      or (
        p_created_at = reader.read_through_at
        and p_message_id::text <= coalesce(reader.read_through_id, p_message_id::text)
      )
    );
$$;


--
-- Name: kalam_normalize_phone_digits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_normalize_phone_digits(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select regexp_replace(
    translate(
      coalesce(p_value, ''),
      '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩',
      '01234567890123456789'
    ),
    '\D',
    '',
    'g'
  );
$$;


--
-- Name: kalam_normalize_voip_call_outcome(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_normalize_voip_call_outcome() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  -- تماس صفرثانیه‌ای در گزارش provider به‌معنی مکالمهٔ برقرارشده نیست.
  if new.direction in ('incoming', 'outgoing')
    and new.talk_seconds = 0
    and new.status in ('answered', 'completed') then
    new.status := 'missed';
  end if;
  return new;
end;
$$;


--
-- Name: kalam_note_conversation_key(uuid, uuid, uuid, uuid[], text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_note_conversation_key(p_org_id uuid, p_note_id uuid, p_author_id uuid, p_mention_user_ids uuid[], p_source_type text, p_metadata jsonb, p_reply_to uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_note_source text := lower(trim(coalesce(p_source_type, p_metadata->>'source_type', '')));
  v_group_id uuid := public.kalam_try_uuid(p_metadata->>'chat_group_id');
  v_agent_conv_key text := public.kalam_resolve_agent_conversation_key_v1(p_metadata);
  v_peer_id uuid := null;
  v_reply_author_id uuid := null;
  v_reply_mention_user_ids uuid[] := '{}'::uuid[];
  v_item uuid;
begin
  if v_group_id is not null then
    return 'group:' || v_group_id::text;
  end if;

  if v_agent_conv_key is not null then
    return v_agent_conv_key;
  end if;

  if v_note_source in ('system', 'ai', 'assistant')
    or (p_metadata ? 'workflow_id')
    or (p_metadata ? 'automation_rule_id')
    or (p_metadata ? 'process_automation_rule_id') then
    return 'system';
  end if;

  foreach v_item in array coalesce(p_mention_user_ids, '{}'::uuid[]) loop
    if v_item is not null and v_item <> p_author_id then
      v_peer_id := v_item;
      exit;
    end if;
  end loop;

  if v_peer_id is null and p_reply_to is not null then
    select n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[])
    into v_reply_author_id, v_reply_mention_user_ids
    from public.notes n
    where n.id = p_reply_to
      and (p_org_id is null or n.org_id = p_org_id)
    limit 1;

    if v_reply_author_id is not null and v_reply_author_id <> p_author_id then
      v_peer_id := v_reply_author_id;
    end if;

    if v_peer_id is null then
      foreach v_item in array coalesce(v_reply_mention_user_ids, '{}'::uuid[]) loop
        if v_item is not null and v_item <> p_author_id then
          v_peer_id := v_item;
          exit;
        end if;
      end loop;
    end if;
  end if;

  if p_author_id is null or v_peer_id is null then
    return null;
  end if;

  return public.kalam_direct_conversation_key(p_author_id, v_peer_id);
end;
$$;


--
-- Name: kalam_note_like_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_note_like_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old_likes jsonb := coalesce(old.metadata->'likes', '{}'::jsonb);
  v_new_likes jsonb := coalesce(new.metadata->'likes', '{}'::jsonb);
  v_liker record;
  v_liker_id uuid;
  v_liker_name text;
  v_note_source text := coalesce(nullif(trim(coalesce(new.source_type, '')), ''), nullif(trim(coalesce(new.metadata->>'source_type', '')), ''), 'user');
begin
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  if new.org_id is null or new.author_id is null then
    return new;
  end if;

  if v_note_source = 'system' then
    return new;
  end if;

  if v_new_likes = v_old_likes or jsonb_typeof(v_new_likes) <> 'object' then
    return new;
  end if;

  for v_liker in
    select key, value
    from jsonb_each(v_new_likes)
  loop
    if v_old_likes ? v_liker.key then
      continue;
    end if;

    v_liker_id := public.kalam_try_uuid(coalesce(v_liker.value->>'user_id', v_liker.key));
    if v_liker_id is null or v_liker_id = new.author_id then
      continue;
    end if;

    v_liker_name := nullif(trim(coalesce(v_liker.value->>'user_name', '')), '');

    perform public.kalam_upsert_notification_item(
      new.org_id,
      'note_like',
      new.id::text || ':' || v_liker_id::text,
      'notes',
      'internal_like',
      'upsert',
      'پسندیدن پیام',
      coalesce(v_liker_name, 'یک کاربر') || ' پیام شما را پسندید.',
      nullif(new.module_id, ''),
      nullif(new.record_id, ''),
      array[new.author_id],
      '{}'::uuid[],
      false,
      jsonb_build_object(
        'note_id', new.id,
        'liker_user_id', v_liker_id,
        'liker_name', v_liker_name,
        'chat_group_id', new.metadata->>'chat_group_id'
      ),
      now()
    );
  end loop;

  return new;
end;
$$;


--
-- Name: kalam_notes_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_notes_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_row jsonb := to_jsonb(new);
  v_metadata jsonb := coalesce(v_row->'metadata', '{}'::jsonb);
  v_org_id uuid := public.kalam_try_uuid(v_row->>'org_id');
  v_note_id text := nullif(v_row->>'id', '');
  v_author_id uuid := public.kalam_try_uuid(v_row->>'author_id');
  v_channel_type text := lower(trim(coalesce(v_row->>'channel_type', '')));
  v_group_id uuid;
  v_group_users uuid[] := '{}'::uuid[];
  v_group_roles uuid[] := '{}'::uuid[];
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_note_source text;
  v_category text;
  v_agent_key text := nullif(lower(trim(coalesce(v_metadata->>'agent_key', ''))), '');
  v_agent_conv_key text := public.kalam_resolve_agent_conversation_key_v1(v_metadata);
  v_conversation_key text;
  v_is_system boolean := false;
  v_is_org_wide boolean := false;
  v_priority integer := 0;
begin
  if v_org_id is null or v_note_id is null or v_channel_type = 'sms' then
    return new;
  end if;

  v_note_source := lower(trim(coalesce(
    nullif(v_row->>'source_type', ''),
    nullif(v_metadata->>'source_type', ''),
    'user'
  )));
  v_is_system := v_note_source in ('system', 'ai', 'assistant')
    or v_metadata ?| array[
      'workflow_id', 'automation_rule_id', 'process_automation_rule_id',
      'workflow_action_type', 'scheduled_report_id'
    ];
  v_group_id := public.kalam_try_uuid(v_metadata->>'chat_group_id');
  v_category := case
    when v_group_id is not null then 'group'
    when v_note_source in ('ai', 'assistant') or v_agent_key is not null then 'assistant'
    when v_is_system then 'system'
    else 'internal'
  end;

  if v_group_id is not null then
    select coalesce(group_row.user_ids, '{}'::uuid[]), coalesce(group_row.role_ids, '{}'::uuid[])
      into v_group_users, v_group_roles
    from public.chat_groups group_row
    where group_row.id = v_group_id and group_row.org_id = v_org_id
    limit 1;
  end if;

  -- Strictly recipient-scoped for system/AI/agent notes: sender is never implicitly added
  v_target_users := public.kalam_distinct_uuid_array(
    public.kalam_jsonb_uuid_array(v_row->'mention_user_ids')
    || coalesce(v_group_users, '{}'::uuid[])
    || case when v_is_system or v_author_id is null then '{}'::uuid[] else array[v_author_id] end
  );
  v_target_roles := public.kalam_distinct_uuid_array(
    public.kalam_jsonb_uuid_array(v_row->'mention_role_ids') || coalesce(v_group_roles, '{}'::uuid[])
  );
  v_is_org_wide := not v_is_system and (
    lower(trim(coalesce(v_metadata->>'is_org_wide', 'false'))) in ('true', '1', 'yes')
    or lower(trim(coalesce(v_metadata->>'org_wide', 'false'))) in ('true', '1', 'yes')
  );

  v_conversation_key := case
    when v_group_id is not null then 'group:' || v_group_id::text
    when v_agent_conv_key is not null then v_agent_conv_key
    when v_is_system then 'system'
    when lower(trim(coalesce(v_metadata->>'saved_message', 'false'))) in ('true', '1', 'yes') then 'mine'
    when nullif(trim(v_metadata->>'conversation_key'), '') is not null then trim(v_metadata->>'conversation_key')
    when v_author_id is not null
      and cardinality(public.kalam_jsonb_uuid_array(v_row->'mention_user_ids')) = 1
      then public.kalam_direct_conversation_key(v_author_id, (public.kalam_jsonb_uuid_array(v_row->'mention_user_ids'))[1])
    when v_author_id is not null then 'mine'
    else null
  end;

  v_priority := case
    when coalesce(v_metadata->>'priority', '') ~ '^-?\d+$' then (v_metadata->>'priority')::integer
    when v_agent_conv_key is not null then 10
    else 0
  end;

  perform public.kalam_upsert_notification_item(
    v_org_id,
    'note',
    v_note_id,
    'notes',
    v_category,
    lower(tg_op),
    case
      when v_agent_key is not null then public.kalam_agent_label_fa_v1(v_agent_key)
      when v_category = 'assistant' then 'پیام هوش مصنوعی'
      when v_category = 'system' then 'پیام سیستم'
      else 'پیام داخلی'
    end,
    nullif(left(coalesce(v_row->>'content', ''), 240), ''),
    nullif(v_row->>'module_id', ''),
    nullif(v_row->>'record_id', ''),
    v_target_users,
    v_target_roles,
    v_is_org_wide,
    jsonb_build_object(
      'note_source', v_note_source,
      'chat_group_id', v_group_id,
      'reply_to', nullif(v_row->>'reply_to', ''),
      'conversation_key', v_conversation_key,
      'agent_key', v_agent_key,
      'priority', v_priority
    ),
    coalesce(nullif(v_row->>'updated_at', '')::timestamptz, nullif(v_row->>'created_at', '')::timestamptz, now())
  );

  return new;
end;
$_$;


--
-- Name: kalam_notification_read_section_v2(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_notification_read_section_v2(p_section text, p_source_type text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when lower(trim(coalesce(p_section, ''))) in ('sms', 'sms_messages') then 'sms_messages'
    when lower(trim(coalesce(p_section, ''))) in ('bot_direct', 'bot_direct_messages')
      or lower(trim(coalesce(p_source_type, ''))) = 'counterparty_bot_direct_message'
      then 'bot_direct_messages'
    when lower(trim(coalesce(p_section, ''))) in ('bot', 'bot_group', 'bot_group_messages', 'bot_messages') then 'bot_messages'
    else lower(trim(coalesce(p_section, '')))
  end;
$$;


--
-- Name: kalam_notification_source_exists(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_notification_source_exists(p_org_id uuid, p_source_table text, p_source_id text, p_record_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_source_table text := lower(trim(coalesce(p_source_table, '')));
  v_source_id text := nullif(trim(coalesce(p_source_id, p_record_id, '')), '');
  v_is_uuid boolean := false;
  v_exists boolean := false;
begin
  if p_org_id is null or v_source_table = '' or v_source_id is null then
    return false;
  end if;

  v_is_uuid := v_source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  if v_is_uuid then
    -- Current recycle-bin data uses normalized table names and UUID identifiers.
    -- This exact lookup uses its existing unique/indexed key.
    if exists (
      select 1
      from public.recycle_bin_records record_row
      where record_row.org_id = p_org_id
        and record_row.source_table = v_source_table
        and record_row.source_record_id = v_source_id::uuid
    ) then
      return false;
    end if;
  elsif exists (
    -- Preserve support for historical non-UUID identifiers without broadening access.
    select 1
    from public.recycle_bin_records record_row
    where record_row.org_id = p_org_id
      and lower(trim(coalesce(record_row.source_table, ''))) = v_source_table
      and trim(coalesce(record_row.source_record_id::text, '')) = v_source_id
  ) then
    return false;
  end if;

  if to_regclass(format('public.%I', v_source_table)) is null then
    return false;
  end if;

  if v_is_uuid then
    execute format(
      'select exists (
        select 1
        from public.%I source_row
        where source_row.org_id = $1
          and source_row.id = $2::uuid
      )',
      v_source_table
    )
    into v_exists
    using p_org_id, v_source_id;
  else
    execute format(
      'select exists (
        select 1
        from public.%I source_row
        where source_row.org_id = $1
          and source_row.id::text = $2
      )',
      v_source_table
    )
    into v_exists
    using p_org_id, v_source_id;
  end if;

  return coalesce(v_exists, false);
exception
  when undefined_table or undefined_column or invalid_text_representation then
    return false;
end;
$_$;


--
-- Name: kalam_outbound_message_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_outbound_message_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_section text;
  v_assignee_type text;
begin
  if new.org_id is null then
    return new;
  end if;

  if lower(trim(coalesce(new.channel_type, ''))) = 'sms' then
    return new;
  end if;

  v_assignee_type := lower(trim(coalesce(new.assignee_type, '')));
  if v_assignee_type = 'role' then
    v_target_roles := public.kalam_distinct_uuid_array(
      case
        when new.assignee_role_id is not null then array[new.assignee_role_id]
        when new.assignee_id is not null then array[new.assignee_id]
        else '{}'::uuid[]
      end
    );
  elsif new.assignee_id is not null then
    v_target_users := array[new.assignee_id];
  elsif new.created_by is not null then
    v_target_users := array[new.created_by];
  end if;

  if cardinality(v_target_users) = 0 and cardinality(v_target_roles) = 0 then
    return new;
  end if;

  v_section := 'bot_messages';

  perform public.kalam_upsert_notification_item(
    new.org_id,
    'outbound_message',
    new.id::text,
    v_section,
    coalesce(nullif(trim(new.channel_type), ''), 'message'),
    lower(tg_op),
    coalesce(nullif(trim(new.title), ''), nullif(trim(new.recipient), ''), 'پیام خروجی'),
    nullif(left(coalesce(new.message_text, ''), 240), ''),
    new.module_id,
    new.record_id,
    v_target_users,
    v_target_roles,
    false,
    jsonb_build_object('status', new.status, 'provider', new.provider, 'related_task_id', new.related_task_id),
    coalesce(new.updated_at, new.sent_at, new.created_at, now())
  );

  return new;
end;
$$;


--
-- Name: kalam_phone_directory_row_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_phone_directory_row_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row jsonb;
  v_org_id uuid;
  v_entity_id uuid;
  v_entity_type text;
  v_title text;
  v_field text;
  v_phone text;
begin
  if tg_op = 'DELETE' then
    delete from public.phone_number_links
    where source_table = tg_table_name
      and entity_id = old.id;
    return old;
  end if;

  v_row := to_jsonb(new);
  v_org_id := public.kalam_try_uuid(v_row->>'org_id');
  v_entity_id := public.kalam_try_uuid(v_row->>'id');
  v_entity_type := tg_table_name;

  if v_org_id is null or v_entity_id is null then
    return new;
  end if;

  v_title := coalesce(
    nullif(v_row->>'business_name', ''),
    nullif(v_row->>'full_name', ''),
    nullif(v_row->>'name', ''),
    nullif(concat_ws(' ', nullif(v_row->>'first_name', ''), nullif(v_row->>'last_name', '')), ''),
    nullif(v_row->>'system_code', ''),
    v_entity_id::text
  );

  delete from public.phone_number_links
  where source_table = tg_table_name
    and entity_id = v_entity_id;

  foreach v_field in array array['mobile', 'mobile_1', 'mobile_2', 'phone', 'assistant_phone']
  loop
    if v_row ? v_field then
      v_phone := nullif(trim(coalesce(v_row->>v_field, '')), '');
      if v_phone is not null then
        perform public.kalam_sync_phone_link(
          v_org_id,
          v_entity_type,
          v_entity_id,
          v_title,
          tg_table_name,
          v_field,
          v_phone,
          public.kalam_phone_link_label(v_field),
          v_field in ('mobile', 'mobile_1')
        );
      end if;
    end if;
  end loop;

  return new;
end;
$$;


--
-- Name: kalam_phone_link_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_phone_link_label(p_field text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_field
    when 'mobile' then 'mobile'
    when 'mobile_1' then 'primary_mobile'
    when 'mobile_2' then 'secondary_mobile'
    when 'phone' then 'phone'
    when 'assistant_phone' then 'assistant_phone'
    else p_field
  end
$$;


--
-- Name: kalam_phone_lookup_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_phone_lookup_key(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  mobile text := public.normalize_iran_mobile_e164(p_value);
  digits text;
begin
  if mobile is not null then return substr(mobile,4); end if;
  digits := regexp_replace(translate(coalesce(p_value,''), '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789'), '[^0-9]', '', 'g');
  if digits like '0098%' then digits := substr(digits,5);
  elsif digits like '98%' and length(digits)>=12 then digits := substr(digits,3); end if;
  if length(digits)>10 and left(digits,1)='0' then digits := substr(digits,2); end if;
  return digits;
end;
$$;


--
-- Name: kalam_realtime_allowed_topic(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_realtime_allowed_topic(p_topic text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid;
  v_role_id uuid;
begin
  if p_topic is null or v_user_id is null then
    return false;
  end if;

  select p.org_id, p.role_id
  into v_org_id, v_role_id
  from public.profiles p
  where p.id = v_user_id
  limit 1;

  if v_org_id is null then
    return false;
  end if;

  if p_topic = public.kalam_realtime_org_topic(v_org_id) then
    return true;
  end if;

  if p_topic = public.kalam_realtime_user_topic(v_org_id, v_user_id) then
    return true;
  end if;

  if v_role_id is not null and p_topic = public.kalam_realtime_role_topic(v_org_id, v_role_id) then
    return true;
  end if;

  return p_topic = public.kalam_realtime_module_list_topic(v_org_id, split_part(split_part(p_topic, ':module:', 2), ':list', 1));
end;
$$;


--
-- Name: kalam_realtime_module_list_topic(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_realtime_module_list_topic(p_org_id uuid, p_module_id text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select case
    when p_org_id is null or nullif(trim(coalesce(p_module_id, '')), '') is null then null
    else 'org:' || p_org_id::text || ':module:' || trim(p_module_id) || ':list'
  end
$$;


--
-- Name: kalam_realtime_org_topic(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_realtime_org_topic(p_org_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select case when p_org_id is null then null else 'org:' || p_org_id::text || ':notifications' end
$$;


--
-- Name: kalam_realtime_role_topic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_realtime_role_topic(p_org_id uuid, p_role_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select case
    when p_org_id is null or p_role_id is null then null
    else 'org:' || p_org_id::text || ':role:' || p_role_id::text || ':notifications'
  end
$$;


--
-- Name: kalam_realtime_user_topic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_realtime_user_topic(p_org_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select case
    when p_org_id is null or p_user_id is null then null
    else 'org:' || p_org_id::text || ':user:' || p_user_id::text || ':notifications'
  end
$$;


--
-- Name: kalam_record_activity_action(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_action(field_name text, old_value jsonb, new_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select case
    when field_name = 'process_template_id' then 'process_template_applied'
    when field_name ~* '(^|_)process(_|$)|process_draft|execution_process_draft|marketing_process_draft|sub_process_draft' then 'process_updated'
    else 'update'
  end;
$_$;


--
-- Name: kalam_record_activity_after(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_after() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else '{}'::jsonb end;
  v_new jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else '{}'::jsonb end;
  v_row jsonb := case when tg_op = 'DELETE' then v_old else v_new end;
  v_org_id uuid := public.kalam_safe_uuid(v_row ->> 'org_id');
  v_record_id text := nullif(v_row ->> 'id', '');
  v_actor uuid := coalesce(public.kalam_safe_uuid(v_new ->> 'updated_by'), public.kalam_safe_uuid(v_new ->> 'created_by'), public.kalam_safe_uuid(v_old ->> 'updated_by'), public.kalam_safe_uuid(v_old ->> 'created_by'), auth.uid());
  v_title text := public.kalam_record_audit_title(v_row);
  v_key text;
  v_old_value jsonb;
  v_new_value jsonb;
  v_field_label text;
  v_is_table boolean;
  v_has_custom_task_changes boolean := false;
  v_parent_org_id uuid;
  v_parent_module_id text;
  v_parent_record_id text;
  v_stage_name text;
  v_stage_kind text;
  v_assignee_label text;
  v_deleted_by uuid;
  v_deleted_title text;
  v_excluded_fields text[] := array['id','org_id','created_at','updated_at','created_by','updated_by','created_by_name','updated_by_name','created_by_label','updated_by_label'];
begin
  if tg_table_name = any(array['changelogs','notes','record_files','record_tags','sidebar_unread','workflow_logs','user_login_events','notification_inbox_items','notification_read_states','outbound_messages','ai_action_logs','ai_messages','ai_threads','org_ai_usage_ledger','recycle_bin_records']) then
    return null;
  end if;
  if tg_table_name = 'process_run_stages' and v_org_id is null then
    select r.org_id into v_org_id
    from public.process_runs r
    where r.id = public.kalam_safe_uuid(v_row ->> 'process_run_id');
  end if;
  if tg_table_name = 'process_template_stages' and v_org_id is null then
    select t.org_id into v_org_id
    from public.process_templates t
    where t.id = public.kalam_safe_uuid(v_row ->> 'template_id');
  end if;
  if v_org_id is null or v_record_id is null then return null; end if;

  -- A restore inserts the original row while the recycle-bin entry is still present.
  if tg_op = 'INSERT' and exists (
    select 1 from public.recycle_bin_records rb
    where rb.org_id = v_org_id and rb.source_table = tg_table_name and rb.source_record_id::text = v_record_id
  ) then
    perform public.kalam_record_activity_emit(v_org_id, tg_table_name, v_record_id, 'restore', auth.uid(), v_title, null, null, null, null,
      jsonb_build_object('source', 'db_trigger', 'summary', 'رکورد از سطل بازیافت بازگردانی شد', 'table_name', tg_table_name));
  elsif tg_op = 'INSERT' then
    perform public.kalam_record_activity_emit(v_org_id, tg_table_name, v_record_id, 'create', v_actor, v_title, null, null, null, null,
      jsonb_build_object('source', 'db_trigger', 'summary', 'رکورد ایجاد شد', 'table_name', tg_table_name));
  elsif tg_op = 'DELETE' then
    select rb.deleted_by, rb.record_title into v_deleted_by, v_deleted_title
    from public.recycle_bin_records rb
    where rb.org_id = v_org_id and rb.source_table = tg_table_name and rb.source_record_id::text = v_record_id
    order by rb.deleted_at desc limit 1;
    perform public.kalam_record_activity_emit(v_org_id, tg_table_name, v_record_id, 'delete', coalesce(v_deleted_by, v_actor), coalesce(v_deleted_title, v_title), null, null, null, null,
      jsonb_build_object('source', 'db_trigger', 'summary', 'رکورد حذف شد', 'table_name', tg_table_name));
  end if;

  -- Process operations are logged against the business record, not only against internal tables.
  if tg_table_name = 'process_runs' then
    if tg_op = 'INSERT' then
      perform public.kalam_record_activity_emit(v_org_id, coalesce(v_new ->> 'module_id', 'process_runs'), coalesce(v_new ->> 'record_id', v_record_id),
        case when nullif(v_new ->> 'template_id', '') is null then 'process_run_created' else 'process_template_applied' end,
        v_actor, v_title, null, null, null, null,
        jsonb_build_object('source','db_trigger','summary', case when nullif(v_new ->> 'template_id','') is null then 'یک ردیف جدید فرآیند اضافه شد' else 'یک فرآیند از الگو اضافه شد' end, 'processName', v_new ->> 'process_name', 'processRunId', v_record_id));
    end if;
    return null;
  end if;

  if tg_table_name = 'process_run_stages' then
    select r.org_id, r.module_id, r.record_id::text into v_parent_org_id, v_parent_module_id, v_parent_record_id
    from public.process_runs r where r.id = public.kalam_safe_uuid(v_row ->> 'process_run_id') and r.org_id = v_org_id;
    if v_parent_org_id is not null and v_parent_module_id is not null and v_parent_record_id is not null then
      v_stage_name := coalesce(nullif(v_row ->> 'stage_name',''), 'مرحله بدون عنوان');
      v_stage_kind := case when nullif(v_row ->> 'task_id','') is null then 'مرحله پیش‌نویس' else 'فعالیت' end;
      if tg_op = 'INSERT' then
        perform public.kalam_record_activity_emit(v_parent_org_id, v_parent_module_id, v_parent_record_id, 'process_stage_added', v_actor, v_title, null, null, null, null,
          jsonb_build_object('source','db_trigger','summary',format('%s «%s» اضافه شد',v_stage_kind,v_stage_name),'stageName',v_stage_name,'stageKind',v_stage_kind,'processRunStageId',v_record_id));
      elsif tg_op = 'DELETE' then
        perform public.kalam_record_activity_emit(v_parent_org_id, v_parent_module_id, v_parent_record_id, 'process_stage_removed', v_actor, v_title, null, null, null, null,
          jsonb_build_object('source','db_trigger','summary',format('%s «%s» حذف شد',v_stage_kind,v_stage_name),'stageName',v_stage_name,'stageKind',v_stage_kind,'processRunStageId',v_record_id));
      elsif (v_old ->> 'task_id') is null and (v_new ->> 'task_id') is not null then
        select p.full_name into v_assignee_label from public.profiles p where p.id = public.kalam_safe_uuid(v_new ->> 'assignee_user_id') and p.org_id = v_parent_org_id;
        perform public.kalam_record_activity_emit(v_parent_org_id, v_parent_module_id, v_parent_record_id, 'process_stage_activated', v_actor, v_title, null, null, null, null,
          jsonb_strip_nulls(jsonb_build_object('source','db_trigger','summary',format('مرحله پیش‌نویس «%s» به فعالیت تبدیل شد%s',v_stage_name,case when v_assignee_label is null then '' else ' و به «'||v_assignee_label||'» ارجاع شد' end),'stageName',v_stage_name,'stageKind','فعالیت','assigneeLabel',v_assignee_label,'processRunStageId',v_record_id)));
      elsif (v_old ->> 'sort_order') is distinct from (v_new ->> 'sort_order') then
        perform public.kalam_record_activity_emit(v_parent_org_id, v_parent_module_id, v_parent_record_id, 'process_stage_reordered', v_actor, v_title, null, null, null, null,
          jsonb_build_object('source','db_trigger','summary',format('ترتیب %s «%s» تغییر کرد',v_stage_kind,v_stage_name),'stageName',v_stage_name,'stageKind',v_stage_kind,'oldPosition',v_old ->> 'sort_order','newPosition',v_new ->> 'sort_order','processRunStageId',v_record_id));
      end if;
    end if;
    return null;
  end if;

  if tg_table_name = 'process_template_stages' then
    select t.org_id, 'process_templates', t.id::text, public.kalam_record_audit_title(to_jsonb(t))
    into v_parent_org_id, v_parent_module_id, v_parent_record_id, v_title
    from public.process_templates t
    where t.id = public.kalam_safe_uuid(v_row ->> 'template_id') and t.org_id = v_org_id;
    if v_parent_org_id is not null then
      v_stage_name := coalesce(nullif(v_row ->> 'stage_name',''), nullif(v_row ->> 'name',''), 'مرحله بدون عنوان');
      if tg_op = 'INSERT' then
        perform public.kalam_record_activity_emit(v_parent_org_id, v_parent_module_id, v_parent_record_id, 'process_stage_added', v_actor, v_title, null, null, null, null,
          jsonb_build_object('source','db_trigger','summary',format('مرحله پیش‌نویس «%s» به الگو اضافه شد',v_stage_name),'stageName',v_stage_name,'stageKind','مرحله پیش‌نویس'));
      elsif tg_op = 'DELETE' then
        perform public.kalam_record_activity_emit(v_parent_org_id, v_parent_module_id, v_parent_record_id, 'process_stage_removed', v_actor, v_title, null, null, null, null,
          jsonb_build_object('source','db_trigger','summary',format('مرحله پیش‌نویس «%s» از الگو حذف شد',v_stage_name),'stageName',v_stage_name,'stageKind','مرحله پیش‌نویس'));
      elsif (v_old ->> 'sort_order') is distinct from (v_new ->> 'sort_order') then
        perform public.kalam_record_activity_emit(v_parent_org_id, v_parent_module_id, v_parent_record_id, 'process_stage_reordered', v_actor, v_title, null, null, null, null,
          jsonb_build_object('source','db_trigger','summary',format('ترتیب مرحله پیش‌نویس «%s» تغییر کرد',v_stage_name),'stageName',v_stage_name,'stageKind','مرحله پیش‌نویس','oldPosition',v_old ->> 'sort_order','newPosition',v_new ->> 'sort_order'));
      end if;
    end if;
    return null;
  end if;

  if tg_op <> 'UPDATE' then return null; end if;
  if tg_table_name = 'tasks' then
    v_has_custom_task_changes := public.kalam_record_activity_custom_task_changes(v_org_id, v_record_id, v_actor, v_title, coalesce(v_old -> 'recurrence_info','{}'::jsonb), coalesce(v_new -> 'recurrence_info','{}'::jsonb));
  end if;

  for v_key, v_new_value in select key, value from jsonb_each(v_new) loop
    if v_key = any(v_excluded_fields) then continue; end if;
    v_old_value := v_old -> v_key;
    if v_old_value is not distinct from v_new_value then continue; end if;
    if v_key = 'recurrence_info' and v_has_custom_task_changes then continue; end if;
    v_field_label := public.kalam_record_activity_field_label(v_org_id, tg_table_name, v_key);
    v_is_table := jsonb_typeof(v_old_value) = 'array' and jsonb_typeof(v_new_value) = 'array';
    if v_is_table and public.kalam_record_activity_table_changes(v_org_id, tg_table_name, v_record_id, v_actor, v_title, v_key, v_field_label, v_old_value, v_new_value) then continue; end if;
    if jsonb_typeof(v_old_value) in ('object','array') or jsonb_typeof(v_new_value) in ('object','array') then continue; end if;
    perform public.kalam_record_activity_emit(v_org_id, tg_table_name, v_record_id, 'update', v_actor, v_title, v_key, v_field_label,
      case when v_old_value is null or v_old_value = 'null'::jsonb then null else v_old_value #>> '{}' end,
      case when v_new_value is null or v_new_value = 'null'::jsonb then null else v_new_value #>> '{}' end,
      jsonb_build_object('source','db_trigger','summary',format('«%s» تغییر کرد',coalesce(v_field_label,'فیلد ثبت‌شده')),'table_name',tg_table_name,'fieldKey',v_key)
      || case when tg_table_name = 'tasks' and v_key = 'status' then jsonb_build_object('options', coalesce(v_new -> 'recurrence_info' -> 'process_task_status_options', '[]'::jsonb)) else '{}'::jsonb end);
  end loop;
  return null;
end;
$$;


--
-- Name: kalam_record_activity_after_changelog_move(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_after_changelog_move() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.record_id is distinct from new.record_id
    and old.module_id = new.module_id
    and old.org_id = new.org_id
    and not exists (
      select 1 from public.changelogs c
      where c.org_id = new.org_id and c.module_id = new.module_id and c.record_id = new.record_id
        and c.action = 'records_merged'
        and c.metadata ->> 'mergedRecordId' = old.record_id
    ) then
    perform public.kalam_record_activity_emit(new.org_id, new.module_id, new.record_id, 'records_merged', auth.uid(), new.record_title, null, null, null, null,
      jsonb_build_object('source','db_trigger','summary','یک رکورد تکراری با این رکورد ادغام شد','mergedRecordId',old.record_id));
  end if;
  return new;
end;
$$;


--
-- Name: kalam_record_activity_after_process_auto_referral(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_after_process_auto_referral() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_module_id text;
  v_record_id text;
  v_count integer;
  v_stage_names text;
  v_record_title text;
begin
  if old.task_id is not null or new.task_id is null then return new; end if;
  if current_setting('kalam.activity.process_auto_referral_emitted', true) = '1' then return new; end if;

  select r.org_id, r.module_id, r.record_id::text, public.kalam_record_audit_title(to_jsonb(r))
  into v_org_id, v_module_id, v_record_id, v_record_title
  from public.process_runs r
  where r.id = new.process_run_id;
  if v_org_id is null or v_module_id is null or v_record_id is null then return new; end if;

  select count(*), string_agg(s.stage_name, '، ' order by s.sort_order)
  into v_count, v_stage_names
  from public.process_run_stages s
  where s.process_run_id = new.process_run_id
    and s.task_id is not null
    and s.updated_at = transaction_timestamp();
  if coalesce(v_count, 0) = 0 then return new; end if;

  perform set_config('kalam.activity.process_auto_referral_emitted', '1', true);
  perform public.kalam_record_activity_emit(
    v_org_id, v_module_id, v_record_id, 'process_stages_auto_referred', auth.uid(), v_record_title,
    null, null, null, null,
    jsonb_build_object(
      'source', 'db_trigger',
      'summary', case when v_count = 1
        then format('مرحله «%s» به‌صورت خودکار ارجاع شد', coalesce(v_stage_names, 'فرآیند'))
        else format('%s مرحله به‌صورت خودکار ارجاع شد', v_count) end,
      'stageCount', v_count,
      'stageNames', coalesce(v_stage_names, '')
    )
  );
  return new;
end;
$$;


--
-- Name: kalam_record_activity_custom_task_changes(uuid, text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_custom_task_changes(p_org_id uuid, p_task_id text, p_actor uuid, p_title text, p_old_recurrence jsonb, p_new_recurrence jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old_values jsonb := coalesce(p_old_recurrence -> 'process_task_custom_field_values', '{}'::jsonb);
  v_new_values jsonb := coalesce(p_new_recurrence -> 'process_task_custom_field_values', '{}'::jsonb);
  v_fields jsonb := coalesce(p_new_recurrence -> 'process_task_custom_fields', p_old_recurrence -> 'process_task_custom_fields', '[]'::jsonb);
  v_key text;
  v_old jsonb;
  v_new jsonb;
  v_field jsonb;
  v_label text;
begin
  if jsonb_typeof(v_old_values) <> 'object' then v_old_values := '{}'::jsonb; end if;
  if jsonb_typeof(v_new_values) <> 'object' then v_new_values := '{}'::jsonb; end if;
  if jsonb_typeof(v_fields) <> 'array' then v_fields := '[]'::jsonb; end if;

  if v_old_values = v_new_values then
    return false;
  end if;

  for v_key in
    select key from jsonb_object_keys(v_old_values || v_new_values) key
  loop
    v_old := v_old_values -> v_key;
    v_new := v_new_values -> v_key;
    if v_old is not distinct from v_new then continue; end if;

    select item into v_field
    from jsonb_array_elements(v_fields) item
    where item ->> 'key' = v_key
    limit 1;
    v_label := nullif(btrim(coalesce(v_field #>> '{labels,fa}', v_field ->> 'labelFa', '')), '');

    perform public.kalam_record_activity_emit(
      p_org_id, 'tasks', p_task_id, 'update', p_actor, p_title,
      v_key, v_label,
      case when v_old is null or v_old = 'null'::jsonb then null when jsonb_typeof(v_old) = 'string' then v_old #>> '{}' else v_old::text end,
      case when v_new is null or v_new = 'null'::jsonb then null when jsonb_typeof(v_new) = 'string' then v_new #>> '{}' else v_new::text end,
      jsonb_strip_nulls(jsonb_build_object(
        'source', 'db_trigger',
        'changeKind', 'process_task_custom_field',
        'summary', format('«%s» تغییر کرد', coalesce(v_label, 'فیلد اختصاصی فعالیت')),
        'fieldKey', v_key,
        'fieldLabel', v_label,
        'fieldType', v_field ->> 'type',
        'processTaskCustomField', v_field
      ))
    );
  end loop;
  return true;
end;
$$;


--
-- Name: kalam_record_activity_emit(uuid, text, text, text, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_emit(p_org_id uuid, p_module_id text, p_record_id text, p_action text, p_actor uuid, p_record_title text, p_field_name text DEFAULT NULL::text, p_field_label text DEFAULT NULL::text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_org_id is null
    or nullif(btrim(coalesce(p_module_id, '')), '') is null
    or nullif(btrim(coalesce(p_record_id, '')), '') is null then
    return;
  end if;

  insert into public.changelogs (
    org_id, module_id, record_id, action, field_name, field_label,
    old_value, new_value, user_id, record_title, metadata
  ) values (
    p_org_id,
    btrim(p_module_id),
    btrim(p_record_id),
    coalesce(nullif(btrim(p_action), ''), 'update'),
    nullif(btrim(coalesce(p_field_name, '')), ''),
    nullif(btrim(coalesce(p_field_label, '')), ''),
    p_old_value,
    p_new_value,
    p_actor,
    nullif(btrim(coalesce(p_record_title, '')), ''),
    coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;


--
-- Name: kalam_record_activity_field_label(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_field_label(p_org_id uuid, p_module_id text, p_field_name text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select nullif(btrim(coalesce((
    select field_item #>> '{labels,fa}'
    from public.integration_settings settings_row
    cross join lateral jsonb_array_elements(
      coalesce(settings_row.settings #> array['modules', p_module_id, 'schema', 'fields'], '[]'::jsonb)
    ) field_item
    where settings_row.org_id = p_org_id
      and settings_row.connection_type = 'module_settings'
      and field_item ->> 'key' = p_field_name
    limit 1
  ), '')), '');
$$;


--
-- Name: kalam_record_activity_summary(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_summary(action_name text, field_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case action_name
    when 'create' then 'رکورد ایجاد شد'
    when 'delete' then 'رکورد حذف شد'
    when 'task_created' then 'فعالیت مرتبط ایجاد شد'
    when 'process_template_applied' then 'الگوی فرآیند رکورد تغییر کرد'
    when 'process_updated' then 'فرآیند رکورد تغییر کرد'
    else 'یکی از فیلدهای رکورد تغییر کرد'
  end;
$$;


--
-- Name: kalam_record_activity_table_changes(uuid, text, text, uuid, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_activity_table_changes(p_org_id uuid, p_module_id text, p_record_id text, p_actor uuid, p_title text, p_block_id text, p_block_label text, p_old_rows jsonb, p_new_rows jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old_row jsonb;
  v_new_row jsonb;
  v_index integer;
  v_column text;
  v_old_value jsonb;
  v_new_value jsonb;
  v_has_changes boolean := false;
begin
  if jsonb_typeof(p_old_rows) <> 'array' or jsonb_typeof(p_new_rows) <> 'array' then
    return false;
  end if;
  if exists (select 1 from jsonb_array_elements(p_old_rows || p_new_rows) item where jsonb_typeof(item) <> 'object') then
    return false;
  end if;

  for v_index in 0..greatest(jsonb_array_length(p_old_rows), jsonb_array_length(p_new_rows)) - 1 loop
    v_old_row := p_old_rows -> v_index;
    v_new_row := p_new_rows -> v_index;
    if v_old_row is not null and v_old_row = 'null'::jsonb then v_old_row := null; end if;
    if v_new_row is not null and v_new_row = 'null'::jsonb then v_new_row := null; end if;

    for v_column in
      select key from jsonb_object_keys(coalesce(v_old_row, '{}'::jsonb) || coalesce(v_new_row, '{}'::jsonb)) key
    loop
      if v_column in ('id', 'row_id', 'key', 'created_at', 'updated_at') or v_column like '\_%' then continue; end if;
      v_old_value := v_old_row -> v_column;
      v_new_value := v_new_row -> v_column;
      if v_old_value is not distinct from v_new_value then continue; end if;
      v_has_changes := true;
      perform public.kalam_record_activity_emit(
        p_org_id, p_module_id, p_record_id, 'table_cell_updated', p_actor, p_title,
        p_block_id, p_block_label,
        case when v_old_value is null or v_old_value = 'null'::jsonb then null when jsonb_typeof(v_old_value) = 'string' then v_old_value #>> '{}' else v_old_value::text end,
        case when v_new_value is null or v_new_value = 'null'::jsonb then null when jsonb_typeof(v_new_value) = 'string' then v_new_value #>> '{}' else v_new_value::text end,
        jsonb_build_object(
          'source', 'db_trigger',
          'changeKind', case when v_old_row is null then 'row_added' when v_new_row is null then 'row_removed' else 'cell_updated' end,
          'summary', format('«%s» در جدول «%s» تغییر کرد', v_column, coalesce(p_block_label, 'جدول')),
          'blockId', p_block_id,
          'blockLabel', p_block_label,
          'rowIndex', v_index + 1,
          'columnKey', v_column
        )
      );
    end loop;
  end loop;
  return v_has_changes;
end;
$$;


--
-- Name: kalam_record_audit_fields_before(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_record_audit_fields_before() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  v_new jsonb := to_jsonb(new);
  v_actor uuid;
  v_patch jsonb := '{}'::jsonb;
begin
  if tg_op = 'INSERT' then
    v_actor := coalesce(
      public.kalam_safe_uuid(v_new ->> 'created_by'),
      public.kalam_safe_uuid(v_new ->> 'updated_by'),
      auth.uid()
    );
    if v_actor is not null and nullif(coalesce(v_new ->> 'created_by', ''), '') is null then
      v_patch := v_patch || jsonb_build_object('created_by', v_actor);
    end if;
    if v_actor is not null and nullif(coalesce(v_new ->> 'updated_by', ''), '') is null then
      v_patch := v_patch || jsonb_build_object('updated_by', v_actor);
    end if;
    if nullif(coalesce(v_new ->> 'created_at', ''), '') is null then
      v_patch := v_patch || jsonb_build_object('created_at', now());
    end if;
    if nullif(coalesce(v_new ->> 'updated_at', ''), '') is null then
      v_patch := v_patch || jsonb_build_object('updated_at', now());
    end if;
  elsif tg_op = 'UPDATE' then
    v_actor := case
      when (v_new ->> 'updated_by') is distinct from (v_old ->> 'updated_by')
        then public.kalam_safe_uuid(v_new ->> 'updated_by')
      else auth.uid()
    end;
    v_patch := v_patch || jsonb_build_object('updated_at', now());
    if v_actor is not null then
      v_patch := v_patch || jsonb_build_object('updated_by', v_actor);
    end if;
  end if;

  if v_patch <> '{}'::jsonb then
    new := jsonb_populate_record(new, v_patch);
  end if;
  return new;
end;
$$;


--
-- Name: kalam_record_audit_title(jsonb); Type: FUNCTION; Schema: public; Owner: -
