      row_data ->> 'title',
      '[بدون عنوان]'
    )),
    ''
  );
$$;


--
-- Name: kalam_refresh_phone_directory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_refresh_phone_directory(p_org_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from public.phone_number_links
  where source_table in ('customers', 'suppliers', 'profiles', 'employees', 'marketing_leads')
    and (p_org_id is null or org_id = p_org_id);

  insert into public.phone_number_links(org_id, phone_number_id, entity_type, entity_id, label, is_primary, source_table, source_field, display_title)
  select src.org_id,
         public.kalam_upsert_phone_number(src.org_id, src.phone_value),
         src.entity_type,
         src.entity_id,
         src.label,
         src.is_primary,
         src.source_table,
         src.source_field,
         src.display_title
  from (
    select org_id, 'customers'::text entity_type, id entity_id, coalesce(nullif(business_name, ''), nullif(full_name, ''), concat_ws(' ', nullif(first_name, ''), nullif(last_name, '')), system_code, id::text) display_title, 'customers'::text source_table, 'mobile_1'::text source_field, mobile_1 phone_value, 'primary_mobile'::text label, true is_primary from public.customers where mobile_1 is not null
    union all select org_id, 'customers', id, coalesce(nullif(business_name, ''), nullif(full_name, ''), concat_ws(' ', nullif(first_name, ''), nullif(last_name, '')), system_code, id::text), 'customers', 'mobile_2', mobile_2, 'secondary_mobile', false from public.customers where mobile_2 is not null
    union all select org_id, 'customers', id, coalesce(nullif(business_name, ''), nullif(full_name, ''), concat_ws(' ', nullif(first_name, ''), nullif(last_name, '')), system_code, id::text), 'customers', 'phone', phone, 'phone', false from public.customers where phone is not null
    union all select org_id, 'customers', id, coalesce(nullif(business_name, ''), nullif(full_name, ''), concat_ws(' ', nullif(first_name, ''), nullif(last_name, '')), system_code, id::text), 'customers', 'assistant_phone', assistant_phone, 'assistant_phone', false from public.customers where assistant_phone is not null
    union all select org_id, 'suppliers', id, coalesce(nullif(business_name, ''), concat_ws(' ', nullif(first_name, ''), nullif(last_name, '')), system_code, id::text), 'suppliers', 'mobile_1', mobile_1, 'primary_mobile', true from public.suppliers where mobile_1 is not null
    union all select org_id, 'suppliers', id, coalesce(nullif(business_name, ''), concat_ws(' ', nullif(first_name, ''), nullif(last_name, '')), system_code, id::text), 'suppliers', 'mobile_2', mobile_2, 'secondary_mobile', false from public.suppliers where mobile_2 is not null
    union all select org_id, 'suppliers', id, coalesce(nullif(business_name, ''), concat_ws(' ', nullif(first_name, ''), nullif(last_name, '')), system_code, id::text), 'suppliers', 'phone', phone, 'phone', false from public.suppliers where phone is not null
    union all select org_id, 'profiles', id, coalesce(nullif(full_name, ''), mobile, mobile_1, id::text), 'profiles', 'mobile', mobile, 'mobile', true from public.profiles where mobile is not null
    union all select org_id, 'profiles', id, coalesce(nullif(full_name, ''), mobile, mobile_1, id::text), 'profiles', 'mobile_1', mobile_1, 'primary_mobile', true from public.profiles where mobile_1 is not null
    union all select org_id, 'employees', id, coalesce(nullif(full_name, ''), system_code, id::text), 'employees', 'mobile_1', mobile_1, 'primary_mobile', true from public.employees where mobile_1 is not null
    union all select org_id, 'employees', id, coalesce(nullif(full_name, ''), system_code, id::text), 'employees', 'mobile_2', mobile_2, 'secondary_mobile', false from public.employees where mobile_2 is not null
    union all select org_id, 'employees', id, coalesce(nullif(full_name, ''), system_code, id::text), 'employees', 'phone', phone, 'phone', false from public.employees where phone is not null
    union all select org_id, 'marketing_leads', id, coalesce(nullif(business_name, ''), nullif(name, ''), id::text), 'marketing_leads', 'mobile', mobile, 'mobile', true from public.marketing_leads where mobile is not null
  ) src
  where src.org_id is not null
    and public.kalam_phone_lookup_key(src.phone_value) <> ''
    and (p_org_id is null or src.org_id = p_org_id)
  on conflict (org_id, source_table, entity_id, source_field) where source_table is not null and source_field is not null
  do update set
    phone_number_id = excluded.phone_number_id,
    entity_type = excluded.entity_type,
    label = excluded.label,
    is_primary = excluded.is_primary,
    display_title = excluded.display_title,
    updated_at = now();
end;
$$;


--
-- Name: kalam_resolve_agent_conversation_key_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_resolve_agent_conversation_key_v1(p_metadata jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_meta jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_explicit text := nullif(trim(coalesce(v_meta->>'conversation_key', '')), '');
  v_agent_key text := lower(trim(coalesce(v_meta->>'agent_key', '')));
begin
  if v_explicit is not null and v_explicit like 'agent:%' then
    return v_explicit;
  end if;
  if v_agent_key <> '' then
    return 'agent:' || v_agent_key;
  end if;
  return null;
end;
$$;


--
-- Name: kalam_resolve_notification_module_id(name, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_resolve_notification_module_id(p_module_id name, p_record jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select public.kalam_resolve_notification_module_id(p_module_id::text, p_record);
$$;


--
-- Name: kalam_resolve_notification_module_id(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_resolve_notification_module_id(p_module_id text, p_record jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when nullif(trim(coalesce(p_module_id, '')), '') = 'invoices'
      and nullif(trim(coalesce(p_record->>'taxpayer_invoice_pattern', '')), '') = '2'
      then 'sales_return_invoices'
    when nullif(trim(coalesce(p_module_id, '')), '') = 'purchase_invoices'
      and nullif(trim(coalesce(p_record->>'taxpayer_invoice_pattern', '')), '') = '2'
      then 'purchase_return_invoices'
    else nullif(trim(coalesce(p_module_id, '')), '')
  end;
$$;


--
-- Name: kalam_responsibility_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_responsibility_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_org_id uuid := public.kalam_try_uuid(v_row->>'org_id');
  v_record_id text := nullif(v_row->>'id', '');
  v_assignee_id uuid := public.kalam_try_uuid(v_row->>'assignee_id');
  v_assignee_role_id uuid := public.kalam_try_uuid(v_row->>'assignee_role_id');
  v_assignee_type text := lower(trim(coalesce(v_row->>'assignee_type', '')));
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_title text;
  v_module_id text;
  v_table_name text := tg_table_name::text;
begin
  if v_org_id is null or v_record_id is null then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    delete from public.notification_inbox_items
    where org_id = v_org_id
      and section = 'responsibilities'
      and source_type = v_table_name
      and source_id = v_record_id;
    return old;
  end if;

  if v_assignee_type = 'role' then
    v_target_roles := public.kalam_distinct_uuid_array(
      case
        when v_assignee_role_id is not null then array[v_assignee_role_id]
        when v_assignee_id is not null then array[v_assignee_id]
        else '{}'::uuid[]
      end
    );
  else
    if v_assignee_id is not null then
      v_target_users := array[v_assignee_id];
    end if;
    if v_assignee_role_id is not null then
      v_target_roles := array[v_assignee_role_id];
    end if;
  end if;

  if cardinality(v_target_users) = 0 and cardinality(v_target_roles) = 0 then
    delete from public.notification_inbox_items
    where org_id = v_org_id
      and section = 'responsibilities'
      and source_type = v_table_name
      and source_id = v_record_id;
    return new;
  end if;

  v_title := coalesce(
    nullif(v_row->>'name', ''),
    nullif(v_row->>'title', ''),
    nullif(v_row->>'full_name', ''),
    nullif(v_row->>'system_code', ''),
    v_table_name || ':' || v_record_id
  );

  v_module_id := public.kalam_resolve_notification_module_id(v_table_name, v_row);

  perform public.kalam_upsert_notification_item(
    v_org_id,
    v_table_name,
    v_record_id,
    'responsibilities',
    v_table_name,
    lower(tg_op),
    v_title,
    nullif(left(coalesce(v_row->>'description', v_row->>'summary', ''), 240), ''),
    v_module_id,
    v_record_id,
    v_target_users,
    v_target_roles,
    false,
    jsonb_build_object(
      'table', v_table_name,
      'module_id', v_module_id
    ),
    now()
  );

  return new;
end;
$$;


--
-- Name: kalam_safe_uuid(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_safe_uuid(value text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
begin
  if value is null or btrim(value) = '' then
    return null;
  end if;
  if value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return null;
  end if;
  return value::uuid;
exception when others then
  return null;
end;
$_$;


--
-- Name: kalam_sms_message_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_sms_message_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_is_org_wide boolean := false;
  v_assignee_type text;
begin
  if new.org_id is null or new.channel_type <> 'sms' then
    return new;
  end if;

  v_assignee_type := lower(trim(coalesce(new.assignee_type, '')));
  if v_assignee_type = 'role' then
    v_target_roles := public.kalam_distinct_uuid_array(
      case
        when new.assignee_role_id is not null then array[new.assignee_role_id]
        when new.assignee_id is not null then array[new.assignee_id]
        else '{}'::uuid[]
      end
    );
  elsif new.assignee_id is not null then
    v_target_users := array[new.assignee_id];
  end if;

  if new.direction = 'inbound' and cardinality(v_target_users) = 0 and cardinality(v_target_roles) = 0 then
    v_is_org_wide := true;
  end if;

  if to_regprocedure('public.kalam_upsert_notification_item(uuid,text,text,text,text,text,text,text,text,text,uuid[],uuid[],boolean,jsonb,timestamptz)') is not null then
    perform public.kalam_upsert_notification_item(
      new.org_id,
      case when new.direction = 'inbound' then 'inbound_sms' else 'outbound_message' end,
      new.id::text,
      'sms',
      coalesce(nullif(trim(new.direction), ''), 'outbound'),
      lower(tg_op),
      coalesce(nullif(trim(new.title), ''), nullif(trim(new.sender), ''), nullif(trim(new.recipient), ''), 'پیامک'),
      nullif(left(coalesce(new.message_text, ''), 240), ''),
      new.module_id,
      new.record_id,
      v_target_users,
      v_target_roles,
      v_is_org_wide,
      jsonb_build_object(
        'direction', new.direction,
        'sender', new.sender,
        'recipient', new.recipient,
        'provider', new.provider,
        'status', new.status
      ),
      coalesce(new.received_at, new.sent_at, new.updated_at, new.created_at, now())
    );
  end if;

  return new;
end;
$$;


--
-- Name: kalam_sync_phone_link(uuid, text, uuid, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_sync_phone_link(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_display_title text, p_source_table text, p_source_field text, p_phone text, p_label text, p_is_primary boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_phone_number_id uuid;
begin
  if p_org_id is null or p_entity_id is null or public.kalam_phone_lookup_key(p_phone) = '' then
    return;
  end if;

  v_phone_number_id := public.kalam_upsert_phone_number(p_org_id, p_phone);
  if v_phone_number_id is null then
    return;
  end if;

  insert into public.phone_number_links(
    org_id,
    phone_number_id,
    entity_type,
    entity_id,
    label,
    is_primary,
    source_table,
    source_field,
    display_title
  )
  values (
    p_org_id,
    v_phone_number_id,
    nullif(trim(coalesce(p_entity_type, '')), ''),
    p_entity_id,
    nullif(trim(coalesce(p_label, '')), ''),
    coalesce(p_is_primary, false),
    nullif(trim(coalesce(p_source_table, '')), ''),
    nullif(trim(coalesce(p_source_field, '')), ''),
    nullif(trim(coalesce(p_display_title, '')), '')
  )
  on conflict (org_id, source_table, entity_id, source_field) where source_table is not null and source_field is not null
  do update set
    phone_number_id = excluded.phone_number_id,
    entity_type = excluded.entity_type,
    label = excluded.label,
    is_primary = excluded.is_primary,
    display_title = excluded.display_title,
    updated_at = now();
end;
$$;


--
-- Name: kalam_system_inbox_recipient_guard_v1(uuid, text, text, text, text, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_system_inbox_recipient_guard_v1(p_org_id uuid, p_section text, p_source_type text, p_source_id text, p_category text, p_users uuid[], p_roles uuid[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  viewer uuid := auth.uid();
  viewer_org uuid := public.current_org_id();
  viewer_role uuid;
  note_source text;
  note_metadata jsonb;
  note_users uuid[];
  note_roles uuid[];
begin
  if viewer is null or viewer_org is null or p_org_id is distinct from viewer_org then return false; end if;
  select profile.role_id into viewer_role from public.profiles profile
    where profile.id = viewer and profile.org_id = viewer_org limit 1;
  if not found then return false; end if;
  if p_section = 'notes' and p_source_type = 'note' then
    select note.source_type, note.metadata, note.mention_user_ids, note.mention_role_ids
      into note_source, note_metadata, note_users, note_roles from public.notes note
      where note.org_id = viewer_org and note.id = public.kalam_try_uuid(p_source_id);
  end if;
  if not public.kalam_internal_message_is_system_v2(note_source, note_metadata, p_category) then return true; end if;
  return viewer = any(coalesce(p_users,'{}'::uuid[]) || coalesce(note_users,'{}'::uuid[]))
    or (viewer_role is not null and viewer_role = any(coalesce(p_roles,'{}'::uuid[]) || coalesce(note_roles,'{}'::uuid[])));
end;
$$;


--
-- Name: kalam_system_note_recipient_guard_v1(uuid, uuid, text, jsonb, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_system_note_recipient_guard_v1(p_note_id uuid, p_org_id uuid, p_source_type text, p_metadata jsonb, p_user_ids uuid[], p_role_ids uuid[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  viewer_id uuid := auth.uid();
  viewer_org uuid := public.current_org_id();
  viewer_role uuid;
  inbox_category text;
  inbox_users uuid[];
  inbox_roles uuid[];
begin
  if viewer_id is null or viewer_org is null or p_org_id is distinct from viewer_org then return false; end if;
  select profile.role_id into viewer_role from public.profiles profile
    where profile.id = viewer_id and profile.org_id = viewer_org limit 1;
  if not found then return false; end if;
  select inbox.category, inbox.target_user_ids, inbox.target_role_ids
    into inbox_category, inbox_users, inbox_roles
    from public.notification_inbox_items inbox
    where inbox.org_id = viewer_org and inbox.section = 'notes'
      and inbox.source_type = 'note' and inbox.source_id = p_note_id::text
    order by inbox.last_event_at desc, inbox.created_at desc, inbox.id desc limit 1;
  if not public.kalam_internal_message_is_system_v2(p_source_type, p_metadata, inbox_category) then return true; end if;
  return viewer_id = any(coalesce(p_user_ids, '{}'::uuid[]) || coalesce(inbox_users, '{}'::uuid[]))
    or (viewer_role is not null and viewer_role = any(coalesce(p_role_ids, '{}'::uuid[]) || coalesce(inbox_roles, '{}'::uuid[])));
end;
$$;


--
-- Name: kalam_tasks_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_tasks_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_assignee_type text;
begin
  if new.org_id is null then
    return new;
  end if;

  v_assignee_type := lower(trim(coalesce(new.assignee_type, '')));
  if v_assignee_type = 'role' then
    v_target_roles := public.kalam_distinct_uuid_array(
      case
        when new.assignee_role_id is not null then array[new.assignee_role_id]
        when new.assignee_id is not null then array[new.assignee_id]
        else '{}'::uuid[]
      end
    );
  else
    v_target_users := public.kalam_distinct_uuid_array(
      case when new.assignee_id is null then '{}'::uuid[] else array[new.assignee_id] end
    );
    if new.assignee_role_id is not null then
      v_target_roles := array[new.assignee_role_id];
    end if;
  end if;

  perform public.kalam_upsert_notification_item(
    new.org_id,
    'task',
    new.id::text,
    'tasks',
    coalesce(nullif(trim(new.status), ''), 'task'),
    lower(tg_op),
    nullif(new.name, ''),
    nullif(left(coalesce(new.description, ''), 240), ''),
    'tasks',
    new.id::text,
    v_target_users,
    v_target_roles,
    false,
    jsonb_build_object('status', new.status, 'priority', new.priority, 'due_date', new.due_date),
    coalesce(new.updated_at, new.created_at, now())
  );

  return new;
end;
$$;


--
-- Name: kalam_try_uuid(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_try_uuid(p_value text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_normalized text := nullif(btrim(coalesce(p_value, '')), '');
begin
  if v_normalized is null then
    return null;
  end if;

  v_normalized := regexp_replace(
    v_normalized,
    '^(process_run_stage|process_run|process_template_stage|process_template|task|user|role)[_:]',
    '',
    'i'
  );

  if v_normalized !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return null;
  end if;

  return cast(v_normalized as uuid);
exception
  when others then
    return null;
end;
$_$;


--
-- Name: kalam_upsert_notification_item(uuid, text, text, text, text, text, text, text, text, text, uuid[], uuid[], boolean, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_upsert_notification_item(p_org_id uuid, p_source_type text, p_source_id text, p_section text, p_category text, p_action text, p_title text, p_body text, p_module_id text, p_record_id text, p_target_user_ids uuid[], p_target_role_ids uuid[], p_is_org_wide boolean, p_payload jsonb, p_last_event_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_conversation_key text := nullif(trim(coalesce(p_payload->>'conversation_key', '')), '');
begin
  if p_org_id is null
    or nullif(trim(coalesce(p_source_type, '')), '') is null
    or nullif(trim(coalesce(p_source_id, '')), '') is null then
    return null;
  end if;

  insert into public.notification_inbox_items (
    org_id, source_type, source_id, section, category, action, title, body,
    module_id, record_id, target_user_ids, target_role_ids, is_org_wide,
    payload, conversation_key, last_event_at
  )
  values (
    p_org_id, trim(p_source_type), trim(p_source_id),
    coalesce(nullif(trim(p_section), ''), 'notes'),
    coalesce(nullif(trim(p_category), ''), 'general'),
    coalesce(nullif(trim(p_action), ''), 'upsert'),
    nullif(trim(coalesce(p_title, '')), ''),
    nullif(trim(coalesce(p_body, '')), ''),
    nullif(trim(coalesce(p_module_id, '')), ''),
    nullif(trim(coalesce(p_record_id, '')), ''),
    public.kalam_distinct_uuid_array(p_target_user_ids),
    public.kalam_distinct_uuid_array(p_target_role_ids),
    coalesce(p_is_org_wide, false),
    coalesce(p_payload, '{}'::jsonb),
    v_conversation_key,
    coalesce(p_last_event_at, now())
  )
  on conflict (org_id, source_type, source_id)
  do update set
    section = excluded.section,
    category = excluded.category,
    action = excluded.action,
    title = coalesce(excluded.title, public.notification_inbox_items.title),
    body = coalesce(excluded.body, public.notification_inbox_items.body),
    module_id = excluded.module_id,
    record_id = excluded.record_id,
    target_user_ids = excluded.target_user_ids,
    target_role_ids = excluded.target_role_ids,
    is_org_wide = excluded.is_org_wide,
    payload = public.notification_inbox_items.payload || excluded.payload,
    conversation_key = coalesce(excluded.conversation_key, public.notification_inbox_items.conversation_key),
    last_event_at = greatest(public.notification_inbox_items.last_event_at, excluded.last_event_at),
    updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: kalam_upsert_phone_number(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_upsert_phone_number(p_org_id uuid, p_phone text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_key text := public.kalam_phone_lookup_key(p_phone);
  v_id uuid;
begin
  if p_org_id is null or v_key = '' then
    return null;
  end if;

  insert into public.phone_numbers(org_id, lookup_key, display_number)
  values (p_org_id, v_key, nullif(trim(coalesce(p_phone, '')), ''))
  on conflict (org_id, lookup_key) do update
    set display_number = coalesce(nullif(trim(coalesce(excluded.display_number, '')), ''), public.phone_numbers.display_number),
        updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


--
-- Name: kalam_voip_call_notification_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kalam_voip_call_notification_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_profile_ids uuid[];
  v_title text;
  v_assignee_type text;
begin
  if new.org_id is null then
    return new;
  end if;

  v_assignee_type := lower(trim(coalesce(new.assignee_type, '')));
  if v_assignee_type = 'role' then
    v_target_roles := public.kalam_distinct_uuid_array(
      case
        when new.assignee_role_id is not null then array[new.assignee_role_id]
        when new.assignee_id is not null then array[new.assignee_id]
        else '{}'::uuid[]
      end
    );
  elsif new.assignee_id is not null then
    v_target_users := array[new.assignee_id];
  end if;

  if nullif(trim(coalesce(new.extension, '')), '') is not null then
    select coalesce(array_agg(p.id), '{}'::uuid[])
    into v_profile_ids
    from public.profiles p
    where p.org_id = new.org_id
      and nullif(trim(coalesce(p.voip_extension, '')), '') = nullif(trim(coalesce(new.extension, '')), '')
      and coalesce(p.voip_enabled, false);

    v_target_users := public.kalam_distinct_uuid_array(v_target_users || coalesce(v_profile_ids, '{}'::uuid[]));
  end if;

  v_title := coalesce(nullif(trim(new.title), ''), nullif(trim(new.source_number), ''), 'تماس VoIP');

  perform public.kalam_upsert_notification_item(
    new.org_id,
    'voip_call',
    new.id::text,
    'voip_calls',
    coalesce(nullif(trim(new.status), ''), 'call'),
    lower(tg_op),
    v_title,
    nullif(trim(new.destination_number), ''),
    'voip_call_reports',
    new.id::text,
    v_target_users,
    v_target_roles,
    false,
    jsonb_build_object(
      'direction', new.direction,
      'status', new.status,
      'extension', new.extension,
      'module_id', new.module_id,
      'record_id', new.record_id
    ),
    coalesce(new.updated_at, new.started_at, new.created_at, now())
  );

  return new;
end;
$$;


--
-- Name: list_online_catalog_live_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_online_catalog_live_counts() RETURNS TABLE(catalog_id uuid, live_count integer)
    LANGUAGE sql
    SET search_path TO 'public'
    AS $_$
  select c.id,
    case c.module_id
      when 'products' then (select count(*)::integer from public.products p where p.org_id = c.org_id and p.id = any(array(select value::uuid from jsonb_array_elements_text(c.source_record_ids) where value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')))
      when 'billboards' then (select count(*)::integer from public.billboards b where b.org_id = c.org_id and b.id = any(array(select value::uuid from jsonb_array_elements_text(c.source_record_ids) where value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')))
      when 'price_lists' then (select count(*)::integer from public.price_lists p where p.org_id = c.org_id and p.id = any(array(select value::uuid from jsonb_array_elements_text(c.source_record_ids) where value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')))
      when 'product_bundles' then (select count(*)::integer from public.product_bundles p where p.org_id = c.org_id and p.id = any(array(select value::uuid from jsonb_array_elements_text(c.source_record_ids) where value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')))
      else 0
    end as live_count
  from public.online_catalogs c
  where c.org_id = public.current_org_id();
$_$;


--
-- Name: list_organization_members(uuid, integer, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_organization_members(p_org_id uuid, p_limit integer DEFAULT 300, p_offset integer DEFAULT 0, p_active_only boolean DEFAULT false, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_result jsonb; v_manage boolean:=public.can_manage_organization_members();
begin
  if p_org_id is null or p_org_id is distinct from public.current_org_id() then
    raise exception 'دسترسی به اعضای این سازمان مجاز نیست.' using errcode='42501'; end if;
  select coalesce(jsonb_agg(item order by item->>'full_name',item->>'id'),'[]'::jsonb) into v_result from (
    select jsonb_build_object('id',p.id,'org_id',m.org_id,'role_id',m.role_id,'role',m.software_role,
      'full_name',p.full_name,'avatar_url',p.avatar_url,'job_title',p.job_title,
      'email',case when v_manage or p.id=auth.uid() then p.email end,
      'mobile_1',case when v_manage or p.id=auth.uid() then p.mobile_1 end,
      'is_active',m.is_active,'created_at',m.created_at,'org_roles',jsonb_build_object('title',r.title),
      'can_edit_identity',p.id=auth.uid() or (v_manage and not exists(
        select 1 from public.user_organization_memberships other where other.user_id=p.id and other.org_id<>m.org_id)),
      'voip_enabled',m.settings->'voip_enabled','voip_operator_code',m.settings->'voip_operator_code',
      'voip_extension',m.settings->'voip_extension','voip_service_id',m.settings->'voip_service_id',
      'voip_dial_mode',m.settings->'voip_dial_mode') as item
    from public.user_organization_memberships m join public.profiles p on p.id=m.user_id
    left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
    where m.org_id=p_org_id and (not p_active_only or m.is_active) and (p_user_id is null or m.user_id=p_user_id)
    order by p.full_name,p.id limit least(greatest(p_limit,1),1000) offset greatest(p_offset,0)
  ) rows;
  return v_result;
end;
$$;


--
-- Name: local_installation_assert_writable(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.local_installation_assert_writable(p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 if exists(select 1 from public.saas_local_transfer_locks where org_id=p_org_id) then
  raise exception using errcode='55000',message='این سازمان برای انتقال به نسخهٔ اختصاصی فقط‌خواندنی است.';
 end if;
end $$;


--
-- Name: local_installation_can(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.local_installation_can(p_action text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p jsonb;
begin
 if auth.uid() is null or public.current_org_id() is null or not public.org_is_saas_admin(public.current_org_id()) then return false; end if;
 select r.permissions->'__saas_admin' into p from public.user_organization_memberships m
 join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
 where m.user_id=auth.uid() and m.org_id=public.current_org_id() and m.is_active limit 1;
 if p is null or not coalesce((p->>'view')::boolean,false) then return false; end if;
 return coalesce((p->'fields'->>('local_'||p_action))::boolean,false);
end $$;


--
-- Name: local_installation_safe_report(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.local_installation_safe_report(p_report jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare s jsonb; services jsonb:='[]';
begin
 if jsonb_typeof(p_report) is distinct from 'object' or pg_column_size(p_report)>65536 or p_report->>'format' is distinct from 'kalamapp-diagnostics-v1'
 or coalesce(p_report->>'generated_at','') !~ '^\d{4}-\d\d-\d\dT' then raise exception 'گزارش نصب معتبر نیست.'; end if;
 if (p_report->>'generated_at')::timestamptz>now()+interval '5 minutes' then raise exception 'زمان گزارش نصب معتبر نیست.'; end if;
 if jsonb_typeof(p_report->'services')='array' then
 for s in select value from jsonb_array_elements(p_report->'services') limit 32 loop
  if coalesce(s->>'name','') !~ '^[a-z][a-z0-9_-]{0,48}$' or coalesce(s->>'status','') not in ('healthy','unhealthy','running','stopped','unknown') then raise exception 'وضعیت سرویس معتبر نیست.'; end if;
  services:=services||jsonb_build_array(jsonb_build_object('name',s->>'name','status',s->>'status'));
 end loop; end if;
 return jsonb_build_object('format','kalamapp-diagnostics-v1','generated_at',(p_report->>'generated_at')::timestamptz,
 'version',left(regexp_replace(coalesce(p_report->>'version',''), '[^0-9.]','','g'),40),
 'services',services,'disk_free_bytes',greatest(0,least(coalesce((p_report->>'disk_free_bytes')::numeric,0),1e18)),
 'last_backup_at',case when p_report->>'last_backup_at' ~ '^\d{4}-\d\d-\d\dT' then (p_report->>'last_backup_at')::timestamptz else null end);
end $_$;


--
-- Name: local_installation_write_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.local_installation_write_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 if TG_OP<>'INSERT' then perform public.local_installation_assert_writable((to_jsonb(old)->>'org_id')::uuid); end if;
 if TG_OP<>'DELETE' then perform public.local_installation_assert_writable((to_jsonb(new)->>'org_id')::uuid); return new; end if;
 return old;
end $$;


--
-- Name: record_locks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.record_locks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.current_org_id() NOT NULL,
    module_id text NOT NULL,
    record_id uuid NOT NULL,
    locked_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_by uuid,
    lock_reason text,
    source_type text DEFAULT 'manual'::text NOT NULL,
    source_id text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT record_locks_module_id_check CHECK ((btrim(module_id) <> ''::text)),
    CONSTRAINT record_locks_source_type_check CHECK ((source_type = ANY (ARRAY['manual'::text, 'workflow'::text, 'process_automation'::text, 'system'::text])))
);


--
-- Name: lock_record(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_record(p_module_id text, p_record_id uuid, p_reason text DEFAULT NULL::text, p_source_type text DEFAULT 'manual'::text, p_source_id text DEFAULT NULL::text) RETURNS public.record_locks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_module_id text := btrim(coalesce(p_module_id, ''));
  v_source_type text := btrim(coalesce(p_source_type, 'manual'));
  v_table_name text := public.resolve_record_lock_table_name(p_module_id);
  v_row public.record_locks;
begin
  if v_org_id is null or auth.uid() is null then
    raise exception 'دسترسی سازمانی معتبر برای قفل کردن رکورد پیدا نشد.';
  end if;
  if v_module_id = '' or p_record_id is null then
    raise exception 'رکورد انتخاب‌شده برای قفل کردن معتبر نیست.';
  end if;
  if not public.record_lock_user_can(v_module_id, 'lock') then
    raise exception 'دسترسی قفل کردن این رکورد را ندارید.';
  end if;
  if not public.record_lock_target_exists(v_module_id, p_record_id, v_org_id) then
    raise exception 'رکورد انتخاب‌شده در این سازمان پیدا نشد.';
  end if;

  insert into public.record_locks(org_id, module_id, record_id, locked_by, lock_reason, source_type, source_id, metadata)
  values (
    v_org_id,
    v_module_id,
    p_record_id,
    auth.uid(),
    nullif(p_reason, ''),
    case when v_source_type in ('manual', 'workflow', 'process_automation', 'system') then v_source_type else 'manual' end,
    nullif(p_source_id, ''),
    jsonb_build_object('table_name', v_table_name)
  )
  on conflict (org_id, module_id, record_id)
  do update set
    locked_at = public.record_locks.locked_at,
    locked_by = public.record_locks.locked_by,
    lock_reason = coalesce(public.record_locks.lock_reason, excluded.lock_reason),
    source_type = public.record_locks.source_type,
    source_id = coalesce(public.record_locks.source_id, excluded.source_id),
    metadata = public.record_locks.metadata || excluded.metadata
  returning * into v_row;

  return v_row;
end;
$$;


--
-- Name: log_customer_club_discount_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_customer_club_discount_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform public.log_customer_club_event(
    case when tg_op = 'INSERT' then 'discount_created' else 'discount_updated' end,
    case when tg_op = 'INSERT' then 'ایجاد کد تخفیف' else 'ویرایش کد تخفیف' end,
    new.customer_id, null, new.id, null, 'customer_discount_codes', new.id,
    jsonb_build_object('title', new.title, 'code', new.code, 'is_active', new.is_active)
  );
  if tg_op = 'INSERT' or (old.is_active is distinct from new.is_active and new.is_active) then
    perform public.enqueue_customer_club_notifications(coalesce(new.metadata->'notifications', '{}'::jsonb), 'activation', new.customer_id, jsonb_build_object('discount_code_id', new.id, 'discount_code', new.code));
  end if;
  return new;
end; $$;


