--
-- Name: log_customer_club_event(text, text, uuid, uuid, uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_customer_club_event(p_event_type text, p_title text, p_customer_id uuid DEFAULT NULL::uuid, p_rule_id uuid DEFAULT NULL::uuid, p_discount_code_id uuid DEFAULT NULL::uuid, p_ledger_id uuid DEFAULT NULL::uuid, p_source_table text DEFAULT NULL::text, p_source_record_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql
