$$;


--
-- Name: log_customer_club_ledger_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_customer_club_ledger_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform public.log_customer_club_event(
    case when new.entry_type = 'debit' then 'credit_redeemed' else 'credit_added' end,
    case when new.entry_type = 'debit' then 'مصرف اعتبار مشتری' else 'افزودن اعتبار مشتری' end,
    new.customer_id, new.rule_id, null, new.id, new.source_table, new.source_record_id,
    jsonb_build_object('amount', new.amount, 'entry_type', new.entry_type, 'source_type', new.source_type)
  );
  if new.entry_type = 'debit' then
    perform public.enqueue_customer_club_notifications(coalesce(new.metadata->'notifications', '{}'::jsonb), 'redemption', new.customer_id, jsonb_build_object('ledger_id', new.id, 'amount', new.amount));
  elsif new.rule_id is not null then
    perform public.enqueue_customer_club_notifications(coalesce((select config->'notifications' from public.customer_loyalty_rules where id = new.rule_id and org_id = public.current_org_id()), '{}'::jsonb), 'condition_met', new.customer_id, jsonb_build_object('ledger_id', new.id, 'rule_id', new.rule_id, 'amount', new.amount));
  else
    perform public.enqueue_customer_club_notifications(coalesce(new.metadata->'notifications', '{}'::jsonb), 'activation', new.customer_id, jsonb_build_object('ledger_id', new.id, 'amount', new.amount));
  end if;
  return new;
end; $$;


--
-- Name: log_customer_club_rule_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_customer_club_rule_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform public.log_customer_club_event(
    case when tg_op = 'INSERT' then 'rule_created' else 'rule_updated' end,
    case when tg_op = 'INSERT' then 'ایجاد طرح باشگاه' else 'ویرایش طرح باشگاه' end,
    null, new.id, null, null, 'customer_loyalty_rules', new.id,
    jsonb_build_object('name', new.name, 'is_active', new.is_active)
  );
  if tg_op = 'INSERT' or (old.is_active is distinct from new.is_active and new.is_active) then
    perform public.enqueue_customer_club_notifications(coalesce(new.config->'notifications', '{}'::jsonb), 'activation', null, jsonb_build_object('rule_id', new.id, 'rule_name', new.name));
  end if;
  return new;
end; $$;


--
-- Name: log_module_record_merge(text, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_module_record_merge(p_module_id text, p_survivor_id uuid, p_duplicate_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_module_id text := nullif(btrim(coalesce(p_module_id, '')), '');
  v_duplicate_id uuid;
begin
  if auth.uid() is null or v_org_id is null or v_module_id is null or p_survivor_id is null then
    raise exception using errcode = '42501', message = 'دسترسی ثبت تاریخچهٔ ادغام وجود ندارد.';
  end if;

  foreach v_duplicate_id in array coalesce(p_duplicate_ids, '{}'::uuid[]) loop
    if v_duplicate_id is null or v_duplicate_id = p_survivor_id then continue; end if;
    if exists (
      select 1 from public.changelogs c
      where c.org_id = v_org_id and c.module_id = v_module_id and c.record_id = p_survivor_id::text
        and c.action = 'records_merged' and c.metadata ->> 'mergedRecordId' = v_duplicate_id::text
    ) then continue; end if;
    perform public.kalam_record_activity_emit(
      v_org_id, v_module_id, p_survivor_id::text, 'records_merged', auth.uid(), null,
      null, null, null, null,
      jsonb_build_object('source','merge_rpc','summary','یک رکورد تکراری با این رکورد ادغام شد','mergedRecordId',v_duplicate_id::text)
    );
  end loop;
end;
$$;


--
-- Name: lookup_phone_signup_invite(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_phone_signup_invite(p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  normalized_phone text := public.normalize_iran_mobile_e164(p_phone);
  invite_row public.phone_signup_invites%rowtype;
begin
  if normalized_phone is null then
    return jsonb_build_object(
      'normalized_phone', null,
      'exists', false,
      'is_active', false
    );
  end if;

  select *
    into invite_row
  from public.phone_signup_invites
  where phone_e164 = normalized_phone
    and consumed_at is null
  order by created_at desc
  limit 1;

  if not found then
    return jsonb_build_object(
      'normalized_phone', normalized_phone,
      'exists', false,
      'is_active', false
    );
  end if;

  return jsonb_build_object(
    'id', invite_row.id,
    'normalized_phone', normalized_phone,
    'exists', true,
    'org_id', invite_row.org_id,
    'full_name', invite_row.full_name,
    'email', invite_row.email,
    'role_id', invite_row.role_id,
    'role', invite_row.role,
    'is_active', invite_row.is_active
  );
end;
$$;


--
-- Name: manage_organization_member(uuid, jsonb, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_organization_member(p_user_id uuid, p_patch jsonb DEFAULT '{}'::jsonb, p_remove boolean DEFAULT false, p_validate_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org uuid:=public.current_org_id(); v_old public.user_organization_memberships%rowtype;
  v_new public.user_organization_memberships%rowtype; v_caller_role text; v_role uuid; v_software text;
begin
  if v_org is null or not public.can_manage_organization_members() then
    raise exception 'دسترسی کافی برای مدیریت اعضای این سازمان ندارید.' using errcode='42501'; end if;
  -- Serialize edits/removals and prevent losing the last administrator through concurrent requests.
  perform 1 from public.organizations where id=v_org for update;
  select * into v_old from public.user_organization_memberships where user_id=p_user_id and org_id=v_org for update;
  if not found then raise exception 'عضویت کاربر در این سازمان پیدا نشد.' using errcode='P0002'; end if;
  if jsonb_typeof(p_patch)<>'object' or jsonb_typeof(coalesce(p_patch->'settings','{}'::jsonb))<>'object'
    or exists(select 1 from jsonb_object_keys(coalesce(p_patch->'settings','{}'::jsonb)) key
      where key not in ('voip_enabled','voip_operator_code','voip_extension','voip_service_id','voip_dial_mode')) then
    raise exception 'تنظیمات عضویت معتبر نیست.'; end if;
  select software_role into v_caller_role from public.user_organization_memberships
    where user_id=auth.uid() and org_id=v_org and is_active;
  v_role:=case when p_patch ? 'role_id' then nullif(p_patch->>'role_id','')::uuid else v_old.role_id end;
  v_software:=coalesce(p_patch->>'role',v_old.software_role);
  if v_software not in ('super_admin','admin','manager','editor','viewer') then
    raise exception 'نقش انتخاب‌شده معتبر نیست.'; end if;
  if (v_old.software_role='super_admin' or v_software='super_admin') and v_caller_role<>'super_admin' then
    raise exception 'فقط مدیر ارشد می‌تواند این نقش را مدیریت کند.' using errcode='42501'; end if;
  if v_role is not null and not exists(select 1 from public.org_roles where id=v_role and org_id=v_org) then
    raise exception 'جایگاه انتخاب‌شده متعلق به این سازمان نیست.' using errcode='42501'; end if;
  if p_user_id=auth.uid() and (p_remove or coalesce((p_patch->>'is_active')::boolean,true)=false) then
    raise exception 'نمی‌توانید عضویت خودتان را حذف یا غیرفعال کنید.'; end if;
  if v_old.is_owner and (p_remove or coalesce((p_patch->>'is_active')::boolean,true)=false) then
    raise exception 'ابتدا مالکیت سازمان را از بخش مدیریت حساب منتقل کنید.'; end if;
  if v_old.is_active and v_old.software_role in ('admin','super_admin','manager')
    and (p_remove or coalesce((p_patch->>'is_active')::boolean,v_old.is_active)=false or v_software not in ('admin','super_admin','manager'))
    and not exists(select 1 from public.user_organization_memberships where org_id=v_org
      and user_id<>p_user_id and is_active and software_role in ('admin','super_admin','manager')) then
    raise exception 'سازمان باید حداقل یک مدیر فعال داشته باشد.'; end if;
  if p_validate_only then return jsonb_build_object('success',true); end if;
  if p_remove then
    delete from public.user_organization_memberships where user_id=p_user_id and org_id=v_org;
  else
    update public.user_organization_memberships set role_id=v_role,software_role=v_software,
      is_active=coalesce((p_patch->>'is_active')::boolean,is_active),
      settings=settings || coalesce(p_patch->'settings','{}'::jsonb),updated_at=now()
    where user_id=p_user_id and org_id=v_org returning * into v_new;
  end if;
  insert into public.changelogs(org_id,module_id,record_id,action,user_id,record_title,metadata)
    values(v_org,'profiles',p_user_id::text,case when p_remove then 'delete' else 'update' end,
      auth.uid(),(select full_name from public.profiles where id=p_user_id),
      jsonb_build_object('scope','organization_membership','previous',to_jsonb(v_old),'current',to_jsonb(v_new)));
  return jsonb_build_object('success',true,'org_id',v_org);
end;
$$;


--
-- Name: mark_ai_conversation_read_v1(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_ai_conversation_read_v1(p_conversation_key text, p_source_type text, p_source_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org uuid:=public.current_org_id();v_user uuid:=auth.uid();v_created timestamptz;v_channel text;
begin
 if v_org is null or v_user is null then return false;end if;
 -- The view has explicit active membership/owner/shared/recipient predicates, also under definer execution.
 select e.created_at into v_created from public.ai_notification_events e
  where e.org_id=v_org and e.user_id=v_user and e.conversation_key=p_conversation_key
    and e.source_type=p_source_type and e.source_id=p_source_id limit 1;
 if not found then return false;end if;
 v_channel:=case when p_source_type='note' then 'internal' else 'ai' end;
 insert into public.communication_read_cursors as existing(org_id,user_id,channel,conversation_key,read_through_at,read_through_id)
 values(v_org,v_user,v_channel,p_conversation_key,v_created,p_source_id)
 on conflict(org_id,user_id,channel,conversation_key) do update set
  read_through_at=excluded.read_through_at,read_through_id=excluded.read_through_id,updated_at=now()
 where (existing.read_through_at,coalesce(existing.read_through_id,''))<(excluded.read_through_at,excluded.read_through_id);
 return true;
end $$;


--
-- Name: mark_communication_read(text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_communication_read(p_channel text, p_conversation_key text, p_read_through_at timestamp with time zone, p_read_through_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_channel text := trim(coalesce(p_channel, ''));
  v_key text := nullif(trim(coalesce(p_conversation_key, '')), '');
  v_message_id uuid := public.kalam_try_uuid(p_read_through_id);
  v_bot_group_id uuid := null;
  v_read_at timestamptz := null;
  v_read_id text := null;
begin
  if v_user_id is null or v_org_id is null or v_key is null or v_message_id is null or p_read_through_at is null then
    return false;
  end if;

  select p.role_id into v_role_id
  from public.profiles p
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if v_channel = 'internal' then
    select n.created_at, n.id::text
    into v_read_at, v_read_id
    from public.notification_inbox_items nii
    join public.notes n
      on n.id::text = nii.source_id
     and n.org_id = nii.org_id
    where nii.org_id = v_org_id
      and nii.section = 'notes'
      and nii.source_type = 'note'
      and lower(trim(coalesce(nii.category, ''))) not in ('system', 'assistant')
      and n.id = v_message_id
      and n.created_at = p_read_through_at
      and (
        nii.is_org_wide = true
        or v_user_id = any(nii.target_user_ids)
        or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
      )
      and v_key <> 'system'
      and coalesce(
        nii.conversation_key,
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
        )
      ) = v_key
    limit 1;
  elsif v_channel = 'bot' then
    v_bot_group_id := public.kalam_try_uuid(replace(v_key, 'bot:', ''));
    if v_bot_group_id is null or not public.kalam_can_access_bot_group(v_bot_group_id, v_org_id) then
      return false;
    end if;
    select m.created_at, m.id::text
    into v_read_at, v_read_id
    from public.counterparty_bot_messages m
    where m.org_id = v_org_id
      and m.bot_group_id = v_bot_group_id
      and m.id = v_message_id
      and m.created_at = p_read_through_at
    limit 1;
  else
    return false;
  end if;

  if v_read_at is null or v_read_id is null then
    return false;
  end if;

  insert into public.communication_read_cursors (
    org_id,
    user_id,
    channel,
    conversation_key,
    read_through_at,
    read_through_id,
    updated_at
  )
  values (v_org_id, v_user_id, v_channel, v_key, v_read_at, v_read_id, now())
  on conflict (org_id, user_id, channel, conversation_key) do update
  set read_through_at = greatest(public.communication_read_cursors.read_through_at, excluded.read_through_at),
      read_through_id = case
        when excluded.read_through_at > public.communication_read_cursors.read_through_at
          then excluded.read_through_id
        when excluded.read_through_at = public.communication_read_cursors.read_through_at
          and coalesce(excluded.read_through_id, '') > coalesce(public.communication_read_cursors.read_through_id, '')
          then excluded.read_through_id
        else public.communication_read_cursors.read_through_id
      end,
      updated_at = now();

  return true;
end;
$$;


--
-- Name: mark_demo_organization_owner_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_demo_organization_owner_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.user_organization_memberships
  set is_owner = true,
      updated_at = now()
  where user_id = new.auth_user_id
    and org_id = new.org_id;
  return new;
end;
$$;


--
-- Name: mark_instruction_ai_index_stale(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_instruction_ai_index_stale() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and (
    old.name is distinct from new.name
    or old.status is distinct from new.status
    or old.department is distinct from new.department
    or old.module_ids is distinct from new.module_ids
    or old.visible_to_user_ids is distinct from new.visible_to_user_ids
    or old.visible_to_role_ids is distinct from new.visible_to_role_ids
    or old.goal is distinct from new.goal
    or old.body is distinct from new.body
    or old.tags is distinct from new.tags
    or old.use_for_ai is distinct from new.use_for_ai
  ) then
    new.ai_index_status := case
      when coalesce(new.use_for_ai, false) = false then 'skipped'
      else 'stale'
    end;
    new.ai_index_error := null;
  end if;
  return new;
end;
$$;


--
-- Name: mark_messaging_read_v2(text, text, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_messaging_read_v2(p_channel text DEFAULT NULL::text, p_conversation_key text DEFAULT NULL::text, p_read_through_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_read_through_id text DEFAULT NULL::text, p_entries jsonb DEFAULT '[]'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_channel text := lower(trim(coalesce(p_channel, '')));
  v_conversation_key text := trim(coalesce(p_conversation_key, ''));
  v_read_through_id text := trim(coalesce(p_read_through_id, ''));
  v_entry jsonb;
  v_section text;
  v_source_type text;
  v_source_id text;
  v_read_at timestamptz := now();
begin
  if v_user_id is null or v_org_id is null then
    return false;
  end if;

  if v_channel <> '' and v_conversation_key <> '' and p_read_through_at is not null then
    insert into public.communication_read_cursors (
      org_id,
      user_id,
      channel,
      conversation_key,
      read_through_at,
      read_through_id,
      updated_at
    )
    values (
      v_org_id,
      v_user_id,
      v_channel,
      v_conversation_key,
      p_read_through_at,
      nullif(v_read_through_id, ''),
      now()
    )
    on conflict (org_id, user_id, channel, conversation_key) do update
    set read_through_at = greatest(public.communication_read_cursors.read_through_at, excluded.read_through_at),
        read_through_id = case
          when excluded.read_through_at > public.communication_read_cursors.read_through_at then excluded.read_through_id
          when excluded.read_through_at = public.communication_read_cursors.read_through_at
            and coalesce(excluded.read_through_id, '') > coalesce(public.communication_read_cursors.read_through_id, '')
            then excluded.read_through_id
          else public.communication_read_cursors.read_through_id
        end,
        updated_at = now();
  end if;

  if jsonb_typeof(coalesce(p_entries, '[]'::jsonb)) = 'array' then
    for v_entry in select value from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb))
    loop
      v_source_type := trim(coalesce(v_entry->>'source_type', v_entry->>'sourceType', ''));
      v_source_id := trim(coalesce(v_entry->>'source_id', v_entry->>'sourceId', ''));
      v_section := public.kalam_notification_read_section_v2(
        coalesce(v_entry->>'section', ''),
        v_source_type
      );

      if v_section <> '' and v_source_type <> '' and v_source_id <> '' then
        insert into public.notification_read_states (
          org_id,
          user_id,
          section,
          source_type,
          source_id,
          read_at,
          snoozed_until,
          updated_at
        )
        values (
          v_org_id,
          v_user_id,
          v_section,
          v_source_type,
          v_source_id,
          v_read_at,
          null,
          now()
        )
        on conflict (org_id, user_id, source_type, source_id) do update
        set section = excluded.section,
            read_at = coalesce(public.notification_read_states.read_at, excluded.read_at),
            snoozed_until = null,
            updated_at = now();
      end if;
    end loop;
  end if;

  return true;
end;
$$;


--
-- Name: mark_notification_overlay_read_v1(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notification_overlay_read_v1(p_section text, p_source_type text, p_source_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_section text := lower(trim(coalesce(p_section, '')));
  v_source_type text := trim(coalesce(p_source_type, ''));
  v_source_id text := trim(coalesce(p_source_id, ''));
  v_allowed boolean := false;
  v_conversation_key text := null;
  v_category text := null;
  v_created_at timestamptz := null;
  v_voip_extension text := null;
  v_can_view_all_calls boolean := false;
begin
  if v_user_id is null
     or v_org_id is null
     or v_source_type = ''
     or v_source_id = '' then
    return false;
  end if;

  if v_section = 'sms_messages' then
    v_section := 'sms';
  end if;

  select
    p.role_id,
    nullif(trim(coalesce(p.voip_extension, '')), ''),
    (
      coalesce(lower(r.permissions #>> '{__voip,view}') <> 'false', true)
      and coalesce(lower(r.permissions #>> '{__voip,fields,all_call_notifications}') <> 'false', true)
    )
  into v_role_id, v_voip_extension, v_can_view_all_calls
  from public.profiles p
  left join public.org_roles r
    on r.id = p.role_id
   and r.org_id = p.org_id
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if v_section = 'notes' and v_source_type = 'note' then
    select
      true,
      lower(trim(coalesce(nii.category, ''))),
      coalesce(
        nii.conversation_key,
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id,
          n.id,
          n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ),
      n.created_at
    into v_allowed, v_category, v_conversation_key, v_created_at
    from public.notification_inbox_items nii
    join public.notes n
      on n.org_id = nii.org_id
     and n.id::text = nii.source_id
    where nii.org_id = v_org_id
      and nii.section = 'notes'
      and nii.source_type = v_source_type
      and nii.source_id = v_source_id
      and (
        nii.is_org_wide = true
        or v_user_id = any(nii.target_user_ids)
        or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
      )
    limit 1;
  elsif v_section = 'responsibilities' then
    select exists (
      select 1
      from public.notification_inbox_items nii
      where nii.org_id = v_org_id
        and nii.section = 'responsibilities'
        and nii.source_type = v_source_type
        and nii.source_id = v_source_id
        and (
          nii.is_org_wide = true
          or v_user_id = any(nii.target_user_ids)
          or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
        )
    ) into v_allowed;
  elsif v_section = 'tasks' and v_source_type = 'task' then
    select exists (
      select 1
      from public.tasks t
      where t.org_id = v_org_id
        and t.id::text = v_source_id
        and lower(trim(coalesce(t.status, ''))) <> 'canceled'
        and (
          (t.assignee_type = 'user' and t.assignee_id = v_user_id)
          or (
            t.assignee_type = 'role'
            and v_role_id is not null
            and (t.assignee_role_id = v_role_id or t.assignee_id = v_role_id)
          )
          or (
            nullif(trim(coalesce(t.assignee_type, '')), '') is null
            and (t.assignee_id = v_user_id or t.assignee_id = v_role_id)
          )
        )
    ) into v_allowed;
  elsif v_section = 'bot_messages' and v_source_type = 'counterparty_bot_message' then
    select
      true,
      'bot:' || m.bot_group_id::text,
      m.created_at
    into v_allowed, v_conversation_key, v_created_at
    from public.counterparty_bot_messages m
    where m.org_id = v_org_id
      and m.id::text = v_source_id
      and m.direction = 'inbound'
      and public.kalam_can_access_bot_group(m.bot_group_id, m.org_id)
    limit 1;
  elsif v_section = 'sms' and v_source_type = 'inbound_sms' then
    select exists (
      select 1
      from public.outbound_messages m
      where m.org_id = v_org_id
        and m.id::text = v_source_id
        and m.channel_type = 'sms'
        and m.direction = 'inbound'
    ) into v_allowed;
  elsif v_section = 'voip_calls' and v_source_type = 'voip_call' then
    select exists (
      select 1
      from public.voip_call_logs c
      where c.org_id = v_org_id
        and c.id::text = v_source_id
        and c.direction = 'incoming'
        and (
          v_can_view_all_calls
          or (v_voip_extension is not null and c.extension = v_voip_extension)
        )
    ) into v_allowed;
  end if;

  if not coalesce(v_allowed, false) then
    return false;
  end if;

  insert into public.notification_read_states (
    org_id,
    user_id,
    section,
    source_type,
    source_id,
    read_at,
    dismissed_at,
    snoozed_until,
    updated_at
  )
  values (
    v_org_id,
    v_user_id,
    v_section,
    v_source_type,
    v_source_id,
    now(),
    null,
    null,
    now()
  )
  on conflict (org_id, user_id, source_type, source_id) do update
  set section = excluded.section,
      read_at = coalesce(public.notification_read_states.read_at, excluded.read_at),
      snoozed_until = null,
      updated_at = now();

  if v_section = 'notes'
     and v_category not in ('system', 'assistant')
     and v_conversation_key is not null
     and v_conversation_key <> 'system'
     and v_created_at is not null then
    perform public.mark_communication_read(
      'internal',
      v_conversation_key,
      v_created_at,
      v_source_id
    );
  elsif v_section = 'bot_messages'
     and v_conversation_key is not null
     and v_created_at is not null then
    perform public.mark_communication_read(
      'bot',
      v_conversation_key,
      v_created_at,
      v_source_id
    );
  end if;

  return true;
end;
$$;


--
-- Name: mark_org_story_media_cleaned(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_org_story_media_cleaned(p_story_id uuid, p_cleaned_slides jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.role() <> 'service_role' then
    raise exception 'دسترسی مجاز نیست' using errcode = 'P0001';
  end if;

  if p_story_id is null then
    return;
  end if;

  update public.org_stories
  set
    is_active = false,
    media_cleaned_at = coalesce(media_cleaned_at, now()),
    slides = coalesce(p_cleaned_slides, slides),
    updated_at = now()
  where id = p_story_id;
end;
$$;


--
-- Name: mark_own_org_story_media_cleaned(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_own_org_story_media_cleaned(p_story_id uuid, p_cleaned_slides jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id  uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null or v_org_id is null or p_story_id is null then
    return;
  end if;

  update public.org_stories s
  set
    is_active = false,
    media_cleaned_at = coalesce(s.media_cleaned_at, now()),
    slides = coalesce(p_cleaned_slides, s.slides),
    updated_at = now()
  where s.id = p_story_id
    and s.org_id = v_org_id
    and s.delete_media_on_expire = true
    and s.expires_at is not null
    and s.expires_at <= now()
    and (
      s.creator_id = v_user_id
      or public.current_user_can_delete_story(s.creator_id)
    );
end;
$$;


--
-- Name: mark_payment_cheque_as_spent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_payment_cheque_as_spent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.operation_type = 'payment'
     and new.cheque_id is not null
     and lower(trim(coalesce(new.status, ''))) in ('received', 'approved')
     and new.org_id is not null then
    update public.cheques
    set status = 'paid',
        spent_date = coalesce(spent_date, new.operation_date, current_date),
        updated_at = now()
    where id = new.cheque_id
      and org_id = new.org_id;
  end if;

  return new;
end;
$$;


--
-- Name: match_ai_document_chunks(uuid, uuid, uuid, public.vector, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_ai_document_chunks(p_org_id uuid, p_user_id uuid, p_role_id uuid, p_query_embedding public.vector, p_match_count integer DEFAULT 6) RETURNS TABLE(id uuid, document_id uuid, chunk_index integer, content text, metadata jsonb, updated_at timestamp with time zone, similarity double precision)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    c.id,
    c.document_id,
    c.chunk_index,
    c.content,
    c.metadata,
    c.updated_at,
    1 - (c.embedding <=> p_query_embedding) as similarity
  from public.document_chunks c
  where c.org_id = p_org_id
    and c.status = 'active'
    and c.embedding_status = 'ready'
    and c.embedding is not null
    and (
      (
        coalesce(array_length(c.allowed_user_ids, 1), 0) = 0
        and coalesce(array_length(c.allowed_role_ids, 1), 0) = 0
      )
      or p_user_id = any(c.allowed_user_ids)
      or p_role_id = any(c.allowed_role_ids)
    )
  order by c.embedding <=> p_query_embedding
  limit greatest(1, least(coalesce(p_match_count, 6), 20));
$$;


--
-- Name: match_ai_document_chunks_hybrid(uuid, uuid, uuid, text, public.vector, integer, double precision, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_ai_document_chunks_hybrid(p_org_id uuid, p_user_id uuid, p_role_id uuid, p_query_text text, p_query_embedding public.vector, p_match_count integer DEFAULT 6, p_match_threshold double precision DEFAULT 0.52, p_full_text_weight double precision DEFAULT 1, p_semantic_weight double precision DEFAULT 1, p_rrf_k integer DEFAULT 50) RETURNS TABLE(id uuid, document_id uuid, chunk_index integer, content text, metadata jsonb, updated_at timestamp with time zone, similarity double precision, hybrid_score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with visible as (
    select
      c.id,
      c.document_id,
      c.chunk_index,
      c.content,
      c.metadata,
      c.updated_at,
      c.embedding,
      c.fts
    from public.document_chunks c
    where c.org_id = p_org_id
      and c.status = 'active'
      and c.embedding_status = 'ready'
      and c.embedding is not null
      and (
        (
          coalesce(array_length(c.allowed_user_ids, 1), 0) = 0
          and coalesce(array_length(c.allowed_role_ids, 1), 0) = 0
        )
        or p_user_id = any(c.allowed_user_ids)
        or p_role_id = any(c.allowed_role_ids)
      )
  ),
  full_text as (
    select
      v.id,
      row_number() over (
        order by ts_rank_cd(v.fts, websearch_to_tsquery('simple'::regconfig, p_query_text)) desc
      ) as rank_ix
    from visible v
    where nullif(btrim(coalesce(p_query_text, '')), '') is not null
      and v.fts @@ websearch_to_tsquery('simple'::regconfig, p_query_text)
    order by ts_rank_cd(v.fts, websearch_to_tsquery('simple'::regconfig, p_query_text)) desc
    limit greatest(1, least(coalesce(p_match_count, 6), 20)) * 2
  ),
  semantic as (
    select
      v.id,
      1 - (v.embedding <=> p_query_embedding) as similarity,
      row_number() over (order by v.embedding <=> p_query_embedding) as rank_ix
    from visible v
    where 1 - (v.embedding <=> p_query_embedding)
      >= greatest(-1, least(1, coalesce(p_match_threshold, 0.52)))
    order by v.embedding <=> p_query_embedding
    limit greatest(1, least(coalesce(p_match_count, 6), 20)) * 2
  ),
  ranked as (
    select
      coalesce(f.id, s.id) as id,
      s.similarity,
      (
        coalesce(1.0 / (greatest(1, coalesce(p_rrf_k, 50)) + f.rank_ix), 0.0)
          * greatest(0, coalesce(p_full_text_weight, 1))
        +
        coalesce(1.0 / (greatest(1, coalesce(p_rrf_k, 50)) + s.rank_ix), 0.0)
          * greatest(0, coalesce(p_semantic_weight, 1))
      )::double precision as hybrid_score
    from full_text f
    full outer join semantic s on s.id = f.id
  )
  select
    v.id,
    v.document_id,
    v.chunk_index,
    v.content,
    v.metadata,
    v.updated_at,
    coalesce(r.similarity, 0)::double precision as similarity,
    r.hybrid_score
  from ranked r
  join visible v on v.id = r.id
  order by r.hybrid_score desc, coalesce(r.similarity, 0) desc
  limit greatest(1, least(coalesce(p_match_count, 6), 20));
$$;


--
-- Name: merge_module_record_references(text, uuid, uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_module_record_references(p_module_id text, p_survivor_id uuid, p_duplicate_ids uuid[], p_relation_fields jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_module_id text := nullif(btrim(coalesce(p_module_id, '')), '');
  v_duplicate_ids uuid[] := coalesce(p_duplicate_ids, array[]::uuid[]);
  v_field jsonb;
  v_table text;
  v_column text;
  v_is_array boolean;
  v_data_type text;
  v_has_org_id boolean;
  v_updated integer;
  v_total integer := 0;
begin
  if v_org_id is null then
    raise exception 'سازمان جاری شناسایی نشد.';
  end if;

  if p_survivor_id is null or v_module_id is null then
    return jsonb_build_object('updated', 0);
  end if;

  -- defensive cleanup: drop nulls and the survivor id itself from the duplicate list
  select coalesce(array_agg(distinct d), array[]::uuid[])
  into v_duplicate_ids
  from unnest(v_duplicate_ids) as d
  where d is not null and d <> p_survivor_id;

  if coalesce(array_length(v_duplicate_ids, 1), 0) = 0 then
    return jsonb_build_object('updated', 0);
  end if;

  -- ---------------------------------------------------------------
  -- Part 1: typed RELATION / MULTI_RELATION fields discovered from
  -- the module registry on the client. Each entry is validated
  -- against information_schema before any dynamic SQL runs.
  -- ---------------------------------------------------------------
  for v_field in select * from jsonb_array_elements(coalesce(p_relation_fields, '[]'::jsonb))
  loop
    v_table := nullif(btrim(coalesce(v_field->>'table', '')), '');
    v_column := nullif(btrim(coalesce(v_field->>'column', '')), '');
    v_is_array := coalesce((v_field->>'isArray')::boolean, false);

    if v_table is null or v_column is null then
      continue;
    end if;

    select c.data_type into v_data_type
    from information_schema.columns c
    where c.table_schema = 'public' and c.table_name = v_table and c.column_name = v_column;

    select exists(
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = v_table and column_name = 'org_id'
    ) into v_has_org_id;

    if v_data_type is null or not v_has_org_id then
      continue;
    end if;

    if v_is_array then
      if v_data_type <> 'ARRAY' then
        continue;
      end if;

      execute format(
        $f$update public.%I t set %I = (
          select array_agg(distinct elem)
          from (
            select case when e = any($1) then $2 else e end as elem
            from unnest(t.%I) as e
          ) x
        )
        where t.org_id = $3 and t.%I && $1$f$,
        v_table, v_column, v_column, v_column
      ) using v_duplicate_ids, p_survivor_id, v_org_id;
    else
      if v_data_type <> 'uuid' then
        continue;
      end if;

      execute format(
        'update public.%I set %I = $2 where org_id = $3 and %I = any($1)',
        v_table, v_column, v_column
      ) using v_duplicate_ids, p_survivor_id, v_org_id;
    end if;

    get diagnostics v_updated = row_count;
    v_total := v_total + coalesce(v_updated, 0);
  end loop;

  -- ---------------------------------------------------------------
  -- Part 2: generic polymorphic module_id/record_id references that
  -- exist for every module regardless of its field configuration.
  -- ---------------------------------------------------------------

  -- module_relations (generic linked records, both directions)
  delete from public.module_relations d
  where d.org_id = v_org_id
    and d.from_module = v_module_id
    and d.from_record_id = any(v_duplicate_ids)
    and exists (
      select 1 from public.module_relations s
      where s.org_id = d.org_id
        and s.from_module = v_module_id
        and s.from_record_id = p_survivor_id
        and s.to_module = d.to_module
        and s.to_record_id is not distinct from d.to_record_id
        and s.relation_type = d.relation_type
    );

  update public.module_relations
  set from_record_id = p_survivor_id
  where org_id = v_org_id
    and from_module = v_module_id
    and from_record_id = any(v_duplicate_ids);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  delete from public.module_relations d
  where d.org_id = v_org_id
    and d.to_module = v_module_id
    and d.to_record_id = any(v_duplicate_ids)
    and exists (
      select 1 from public.module_relations s
      where s.org_id = d.org_id
        and s.to_module = v_module_id
        and s.to_record_id = p_survivor_id
        and s.from_module = d.from_module
        and s.from_record_id is not distinct from d.from_record_id
        and s.relation_type = d.relation_type
    );

  update public.module_relations
  set to_record_id = p_survivor_id
  where org_id = v_org_id
    and to_module = v_module_id
    and to_record_id = any(v_duplicate_ids);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  -- record_tags (tag assignments) - drop conflicting duplicates first
  delete from public.record_tags d
  where d.org_id = v_org_id
    and d.module_id = v_module_id
    and d.record_id = any(v_duplicate_ids::text[])
    and exists (
      select 1 from public.record_tags s
      where s.org_id = d.org_id
        and s.module_id = v_module_id
        and s.record_id = p_survivor_id::text
        and s.tag_id = d.tag_id
    );

  update public.record_tags
  set record_id = p_survivor_id::text
  where org_id = v_org_id
    and module_id = v_module_id
    and record_id = any(v_duplicate_ids::text[]);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  -- notes (mentions/timeline) attached to the merged record
  update public.notes
  set record_id = p_survivor_id::text
  where org_id = v_org_id
    and module_id = v_module_id
    and record_id = any(v_duplicate_ids::text[]);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  -- record_files: files attached directly to the merged record
  update public.record_files
  set record_id = p_survivor_id::text
  where org_id = v_org_id
    and module_id = v_module_id
    and record_id = any(v_duplicate_ids::text[]);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  -- record_files: files inherited via a "source" record reference
  update public.record_files
  set source_record_id = p_survivor_id::text
  where org_id = v_org_id
    and source_module_id = v_module_id
    and source_record_id = any(v_duplicate_ids::text[]);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  -- changelogs: keep activity history attached to the surviving record
  update public.changelogs
  set record_id = p_survivor_id::text
  where org_id = v_org_id
    and module_id = v_module_id
    and record_id = any(v_duplicate_ids::text[]);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  -- notification_inbox_items: keep deep-links pointing at the surviving record
  update public.notification_inbox_items
  set record_id = p_survivor_id::text
  where org_id = v_org_id
    and module_id = v_module_id
    and record_id = any(v_duplicate_ids::text[]);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  -- journal_entries: accounting vouchers generated from the merged record
  update public.journal_entries
  set source_record_id = p_survivor_id
  where org_id = v_org_id
    and source_module = v_module_id
    and source_record_id = any(v_duplicate_ids);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  -- journal_entry_links: idempotency keys for accounting auto-posting
  delete from public.journal_entry_links d
  where d.org_id = v_org_id
    and d.source_table = v_module_id
    and d.source_record_id = any(v_duplicate_ids)
    and exists (
      select 1 from public.journal_entry_links s
      where s.org_id = d.org_id
        and s.event_key = d.event_key
        and s.source_table = v_module_id
        and s.source_record_id = p_survivor_id
    );

  update public.journal_entry_links
  set source_record_id = p_survivor_id
  where org_id = v_org_id
    and source_table = v_module_id
    and source_record_id = any(v_duplicate_ids);
  get diagnostics v_updated = row_count;
  v_total := v_total + coalesce(v_updated, 0);

  return jsonb_build_object('updated', v_total, 'duplicate_ids', v_duplicate_ids);
end;
$_$;


--
-- Name: move_process_run_stage(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_process_run_stage(p_process_run_stage_id uuid, p_lane_key text, p_sort_order integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_task_id uuid;
  v_lane_key text;
  v_sort_order integer;
begin
  select r.org_id, s.task_id
  into v_org_id, v_task_id
  from public.process_run_stages s
  join public.process_runs r on r.id = s.process_run_id
  where s.id = p_process_run_stage_id;

  if auth.uid() is null
    or v_org_id is null
    or public.current_org_id() is null
    or v_org_id <> public.current_org_id() then
    raise exception 'دسترسی جابه‌جایی مرحله فرآیند وجود ندارد.' using errcode = '42501';
  end if;

  v_lane_key := coalesce(nullif(btrim(coalesce(p_lane_key, '')), ''), 'lane_1');
  v_sort_order := greatest(1, coalesce(p_sort_order, 10));

  update public.process_run_stages
  set process_lane_key = v_lane_key,
      sort_order = v_sort_order,
      metadata = coalesce(metadata, '{}'::jsonb)
        || jsonb_build_object('process_lane_key', v_lane_key),
      updated_at = now()
  where id = p_process_run_stage_id;

  if v_task_id is not null then
    update public.tasks
    set process_lane_key = v_lane_key,
        sort_order = v_sort_order,
        source_stage_sort_order = v_sort_order,
        recurrence_info = coalesce(recurrence_info, '{}'::jsonb)
          || jsonb_build_object('process_lane_key', v_lane_key),
        updated_by = auth.uid(),
        updated_at = now()
    where id = v_task_id
      and org_id = v_org_id;
  end if;
end;
$$;


--
-- Name: move_records_to_recycle_bin(text, text, uuid[], uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_records_to_recycle_bin(p_module_id text, p_source_table text, p_record_ids uuid[], p_deleted_by uuid DEFAULT auth.uid(), p_deleted_by_name text DEFAULT NULL::text, p_org_id uuid DEFAULT public.current_org_id()) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_source_table text;
  v_record_id uuid;
  v_snapshot jsonb;
  v_child_snapshot jsonb;
  v_effective_org_id uuid;
  v_count integer := 0;
begin
  v_source_table := public.resolve_recycle_bin_source_table(p_source_table);
  if v_source_table is null then
    raise exception 'منبع سطل بازیافت معتبر نیست: %', p_source_table;
  end if;

  foreach v_record_id in array coalesce(p_record_ids, array[]::uuid[])
  loop
    execute format(
      'select to_jsonb(t) from public.%I t where t.id = $1',
      v_source_table
    )
    into v_snapshot
    using v_record_id;

    if v_snapshot is null then
      raise exception 'رکورد % در ماژول % پیدا نشد یا قبلا حذف شده است.', v_record_id, p_module_id;
    end if;

    v_effective_org_id := coalesce(
      p_org_id,
      nullif(v_snapshot->>'org_id', '')::uuid,
      public.current_org_id()
    );

    if v_source_table = 'process_templates' then
      for v_child_snapshot in
        select to_jsonb(s)
        from public.process_template_stages s
        where s.template_id = v_record_id
      loop
        delete from public.recycle_bin_records
        where source_table = 'process_template_stages'
          and source_record_id = (v_child_snapshot->>'id')::uuid;

        insert into public.recycle_bin_records (
          org_id,
          module_id,
          source_table,
          source_record_id,
          record_title,
          snapshot,
          deleted_by,
          deleted_by_name
        )
        values (
          v_effective_org_id,
          'process_template_stages',
          'process_template_stages',
          (v_child_snapshot->>'id')::uuid,
          public.recycle_bin_record_title(v_child_snapshot),
          v_child_snapshot,
          p_deleted_by,
          nullif(trim(coalesce(p_deleted_by_name, '')), '')
        );

        v_count := v_count + 1;
      end loop;

      for v_child_snapshot in
        select to_jsonb(w)
        from public.workflows w
        where w.process_template_id = v_record_id
          and w.scope_type = 'process_activator'
      loop
        delete from public.recycle_bin_records
        where source_table = 'workflows'
          and source_record_id = (v_child_snapshot->>'id')::uuid;

        insert into public.recycle_bin_records (
          org_id,
          module_id,
          source_table,
          source_record_id,
          record_title,
          snapshot,
          deleted_by,
          deleted_by_name
        )
        values (
          coalesce(nullif(v_child_snapshot->>'org_id', '')::uuid, v_effective_org_id),
          'workflows',
          'workflows',
          (v_child_snapshot->>'id')::uuid,
          public.recycle_bin_record_title(v_child_snapshot),
          v_child_snapshot,
          p_deleted_by,
          nullif(trim(coalesce(p_deleted_by_name, '')), '')
        );

        v_count := v_count + 1;
      end loop;
    end if;

    delete from public.recycle_bin_records
    where source_table = v_source_table
      and source_record_id = v_record_id;

    insert into public.recycle_bin_records (
      org_id,
      module_id,
      source_table,
      source_record_id,
      record_title,
      snapshot,
      deleted_by,
      deleted_by_name
    )
    values (
      v_effective_org_id,
      trim(coalesce(p_module_id, '')),
      v_source_table,
      v_record_id,
      public.recycle_bin_record_title(v_snapshot),
      v_snapshot,
      p_deleted_by,
      nullif(trim(coalesce(p_deleted_by_name, '')), '')
    );

    execute format(
      'delete from public.%I where id = $1',
      v_source_table
    )
    using v_record_id;

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$_$;


--
-- Name: normalize_announcement_surface(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_announcement_surface(p_surface text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  v_surface text := lower(trim(coalesce(p_surface, '')));
begin
  if v_surface = 'public' then
    return 'public_site';
  end if;
  if v_surface = 'panel' then
    return 'user_panel';
  end if;
  if v_surface = 'login' then
    return 'login_page';
  end if;
  return v_surface;
end
$$;


--
-- Name: normalize_billboard_status_change_record(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_billboard_status_change_record() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_billboard_name text;
  v_action_title text;
begin
  select coalesce(nullif(trim(name), ''), 'تابلو')
    into v_billboard_name
  from public.billboards
  where id = new.billboard_id and org_id = new.org_id;

  new.application_mode := case
    when lower(trim(coalesce(new.application_mode, ''))) = 'add_tag' then 'add_tag'
    else 'main_status'
  end;
  new.execution_source := case
    when lower(trim(coalesce(new.execution_source, ''))) = 'workflow' then 'workflow'
    else 'manual'
  end;
  v_action_title := case when new.application_mode = 'add_tag' then 'افزودن برچسب' else 'تغییر وضعیت' end;
  new.title := concat(v_action_title, ' ', coalesce(v_billboard_name, 'تابلو'), ' به ', public.billboard_operational_status_label(new.target_status));
  if tg_op = 'INSERT' then
    new.created_by := coalesce(new.created_by, new.requested_by, auth.uid());
  end if;
  new.assignee_id := coalesce(new.assignee_id, new.created_by, new.requested_by, auth.uid());
  new.assignee_type := case when new.assignee_id is null then null else 'user' end;
  new.updated_by := coalesce(auth.uid(), new.updated_by, new.requested_by);
  return new;
end;
$$;


--
-- Name: normalize_demo_mobile(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_demo_mobile(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when regexp_replace(coalesce(value, ''), '\D+', '', 'g') = '' then null
    when left(regexp_replace(coalesce(value, ''), '\D+', '', 'g'), 2) = '98'
      then '+' || regexp_replace(coalesce(value, ''), '\D+', '', 'g')
    when left(regexp_replace(coalesce(value, ''), '\D+', '', 'g'), 1) = '0'
      then '+98' || substr(regexp_replace(coalesce(value, ''), '\D+', '', 'g'), 2)
    when left(regexp_replace(coalesce(value, ''), '\D+', '', 'g'), 1) = '9'
      then '+98' || regexp_replace(coalesce(value, ''), '\D+', '', 'g')
    else '+' || regexp_replace(coalesce(value, ''), '\D+', '', 'g')
  end
$$;


--
-- Name: normalize_iran_mobile_e164(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_iran_mobile_e164(value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  raw text := translate(trim(coalesce(value, '')), '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789');
  digits text;
begin
  -- Keep validation consistent with the shared browser/Edge helper.
  raw := regexp_replace(raw, '[‌-‏‪-‮⁦-⁩]', '', 'g');
  if raw = '' or raw ~ '[^+0-9[:space:]().-]' then return null; end if;
  digits := regexp_replace(raw, '[^0-9]', '', 'g');
  if digits like '0098%' then digits := substr(digits,5);
  elsif digits like '098%' and length(digits)>=13 then digits := substr(digits,4);
  elsif digits like '98%' and length(digits)>=12 then digits := substr(digits,3); end if;
  if left(digits,1)='0' then digits := substr(digits,2); end if;
  if digits ~ '^9[0-9]{9}$' then return '+98'||digits; end if;
  return null;
end;
$_$;


--
-- Name: normalize_mbti_assessment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_mbti_assessment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_questions_changed boolean := tg_op = 'INSERT';
  v_complete boolean;
begin
  if tg_op = 'UPDATE' then
    v_questions_changed := old.ei_01 is distinct from new.ei_01 or old.ei_02 is distinct from new.ei_02
      or old.ei_03 is distinct from new.ei_03 or old.ei_04 is distinct from new.ei_04
      or old.ei_05 is distinct from new.ei_05 or old.ei_06 is distinct from new.ei_06
      or old.ei_07 is distinct from new.ei_07 or old.ei_08 is distinct from new.ei_08
      or old.sn_01 is distinct from new.sn_01 or old.sn_02 is distinct from new.sn_02
      or old.sn_03 is distinct from new.sn_03 or old.sn_04 is distinct from new.sn_04
      or old.sn_05 is distinct from new.sn_05 or old.sn_06 is distinct from new.sn_06
      or old.sn_07 is distinct from new.sn_07 or old.sn_08 is distinct from new.sn_08
      or old.tf_01 is distinct from new.tf_01 or old.tf_02 is distinct from new.tf_02
      or old.tf_03 is distinct from new.tf_03 or old.tf_04 is distinct from new.tf_04
      or old.tf_05 is distinct from new.tf_05 or old.tf_06 is distinct from new.tf_06
      or old.tf_07 is distinct from new.tf_07 or old.tf_08 is distinct from new.tf_08
      or old.jp_01 is distinct from new.jp_01 or old.jp_02 is distinct from new.jp_02
      or old.jp_03 is distinct from new.jp_03 or old.jp_04 is distinct from new.jp_04
      or old.jp_05 is distinct from new.jp_05 or old.jp_06 is distinct from new.jp_06
      or old.jp_07 is distinct from new.jp_07 or old.jp_08 is distinct from new.jp_08;
  end if;
  if new.org_id is null then
    new.org_id := public.current_org_id();
  end if;
  if new.org_id is null then
    raise exception 'MBTI_ASSESSMENT_ORG_REQUIRED';
  end if;

  if new.related_employee_id is not null and not exists (
    select 1 from public.employees where id = new.related_employee_id and org_id = new.org_id
  ) then
    raise exception 'MBTI_ASSESSMENT_EMPLOYEE_ORG_MISMATCH';
  end if;
  if new.related_applicant_id is not null and not exists (
    select 1 from public.recruitment_applicants where id = new.related_applicant_id and org_id = new.org_id
  ) then
    raise exception 'MBTI_ASSESSMENT_APPLICANT_ORG_MISMATCH';
  end if;
  if new.related_job_description_id is not null and not exists (
    select 1 from public.job_descriptions where id = new.related_job_description_id and org_id = new.org_id
  ) then
    raise exception 'MBTI_ASSESSMENT_JOB_ORG_MISMATCH';
  end if;

  new.ei_01 := lower(nullif(trim(new.ei_01), '')); new.ei_02 := lower(nullif(trim(new.ei_02), ''));
  new.ei_03 := lower(nullif(trim(new.ei_03), '')); new.ei_04 := lower(nullif(trim(new.ei_04), ''));
  new.ei_05 := lower(nullif(trim(new.ei_05), '')); new.ei_06 := lower(nullif(trim(new.ei_06), ''));
  new.ei_07 := lower(nullif(trim(new.ei_07), '')); new.ei_08 := lower(nullif(trim(new.ei_08), ''));
  new.sn_01 := lower(nullif(trim(new.sn_01), '')); new.sn_02 := lower(nullif(trim(new.sn_02), ''));
  new.sn_03 := lower(nullif(trim(new.sn_03), '')); new.sn_04 := lower(nullif(trim(new.sn_04), ''));
  new.sn_05 := lower(nullif(trim(new.sn_05), '')); new.sn_06 := lower(nullif(trim(new.sn_06), ''));
  new.sn_07 := lower(nullif(trim(new.sn_07), '')); new.sn_08 := lower(nullif(trim(new.sn_08), ''));
  new.tf_01 := lower(nullif(trim(new.tf_01), '')); new.tf_02 := lower(nullif(trim(new.tf_02), ''));
  new.tf_03 := lower(nullif(trim(new.tf_03), '')); new.tf_04 := lower(nullif(trim(new.tf_04), ''));
  new.tf_05 := lower(nullif(trim(new.tf_05), '')); new.tf_06 := lower(nullif(trim(new.tf_06), ''));
  new.tf_07 := lower(nullif(trim(new.tf_07), '')); new.tf_08 := lower(nullif(trim(new.tf_08), ''));
  new.jp_01 := lower(nullif(trim(new.jp_01), '')); new.jp_02 := lower(nullif(trim(new.jp_02), ''));
  new.jp_03 := lower(nullif(trim(new.jp_03), '')); new.jp_04 := lower(nullif(trim(new.jp_04), ''));
  new.jp_05 := lower(nullif(trim(new.jp_05), '')); new.jp_06 := lower(nullif(trim(new.jp_06), ''));
  new.jp_07 := lower(nullif(trim(new.jp_07), '')); new.jp_08 := lower(nullif(trim(new.jp_08), ''));

  new.ei_score_e := coalesce((new.ei_01 = 'e')::int, 0) + coalesce((new.ei_02 = 'e')::int, 0) + coalesce((new.ei_03 = 'e')::int, 0) + coalesce((new.ei_04 = 'e')::int, 0) + coalesce((new.ei_05 = 'e')::int, 0) + coalesce((new.ei_06 = 'e')::int, 0) + coalesce((new.ei_07 = 'e')::int, 0) + coalesce((new.ei_08 = 'e')::int, 0);
  new.ei_score_i := coalesce((new.ei_01 = 'i')::int, 0) + coalesce((new.ei_02 = 'i')::int, 0) + coalesce((new.ei_03 = 'i')::int, 0) + coalesce((new.ei_04 = 'i')::int, 0) + coalesce((new.ei_05 = 'i')::int, 0) + coalesce((new.ei_06 = 'i')::int, 0) + coalesce((new.ei_07 = 'i')::int, 0) + coalesce((new.ei_08 = 'i')::int, 0);
  new.sn_score_s := coalesce((new.sn_01 = 's')::int, 0) + coalesce((new.sn_02 = 's')::int, 0) + coalesce((new.sn_03 = 's')::int, 0) + coalesce((new.sn_04 = 's')::int, 0) + coalesce((new.sn_05 = 's')::int, 0) + coalesce((new.sn_06 = 's')::int, 0) + coalesce((new.sn_07 = 's')::int, 0) + coalesce((new.sn_08 = 's')::int, 0);
  new.sn_score_n := coalesce((new.sn_01 = 'n')::int, 0) + coalesce((new.sn_02 = 'n')::int, 0) + coalesce((new.sn_03 = 'n')::int, 0) + coalesce((new.sn_04 = 'n')::int, 0) + coalesce((new.sn_05 = 'n')::int, 0) + coalesce((new.sn_06 = 'n')::int, 0) + coalesce((new.sn_07 = 'n')::int, 0) + coalesce((new.sn_08 = 'n')::int, 0);
  new.tf_score_t := coalesce((new.tf_01 = 't')::int, 0) + coalesce((new.tf_02 = 't')::int, 0) + coalesce((new.tf_03 = 't')::int, 0) + coalesce((new.tf_04 = 't')::int, 0) + coalesce((new.tf_05 = 't')::int, 0) + coalesce((new.tf_06 = 't')::int, 0) + coalesce((new.tf_07 = 't')::int, 0) + coalesce((new.tf_08 = 't')::int, 0);
  new.tf_score_f := coalesce((new.tf_01 = 'f')::int, 0) + coalesce((new.tf_02 = 'f')::int, 0) + coalesce((new.tf_03 = 'f')::int, 0) + coalesce((new.tf_04 = 'f')::int, 0) + coalesce((new.tf_05 = 'f')::int, 0) + coalesce((new.tf_06 = 'f')::int, 0) + coalesce((new.tf_07 = 'f')::int, 0) + coalesce((new.tf_08 = 'f')::int, 0);
  new.jp_score_j := coalesce((new.jp_01 = 'j')::int, 0) + coalesce((new.jp_02 = 'j')::int, 0) + coalesce((new.jp_03 = 'j')::int, 0) + coalesce((new.jp_04 = 'j')::int, 0) + coalesce((new.jp_05 = 'j')::int, 0) + coalesce((new.jp_06 = 'j')::int, 0) + coalesce((new.jp_07 = 'j')::int, 0) + coalesce((new.jp_08 = 'j')::int, 0);
  new.jp_score_p := coalesce((new.jp_01 = 'p')::int, 0) + coalesce((new.jp_02 = 'p')::int, 0) + coalesce((new.jp_03 = 'p')::int, 0) + coalesce((new.jp_04 = 'p')::int, 0) + coalesce((new.jp_05 = 'p')::int, 0) + coalesce((new.jp_06 = 'p')::int, 0) + coalesce((new.jp_07 = 'p')::int, 0) + coalesce((new.jp_08 = 'p')::int, 0);

  v_complete := new.ei_01 is not null and new.ei_02 is not null and new.ei_03 is not null and new.ei_04 is not null and new.ei_05 is not null and new.ei_06 is not null and new.ei_07 is not null and new.ei_08 is not null
    and new.sn_01 is not null and new.sn_02 is not null and new.sn_03 is not null and new.sn_04 is not null and new.sn_05 is not null and new.sn_06 is not null and new.sn_07 is not null and new.sn_08 is not null
    and new.tf_01 is not null and new.tf_02 is not null and new.tf_03 is not null and new.tf_04 is not null and new.tf_05 is not null and new.tf_06 is not null and new.tf_07 is not null and new.tf_08 is not null
    and new.jp_01 is not null and new.jp_02 is not null and new.jp_03 is not null and new.jp_04 is not null and new.jp_05 is not null and new.jp_06 is not null and new.jp_07 is not null and new.jp_08 is not null;

  new.result_status := case when v_complete then 'ready' else 'incomplete' end;
  new.mbti_type := case
    when not v_complete or new.ei_score_e = new.ei_score_i or new.sn_score_s = new.sn_score_n or new.tf_score_t = new.tf_score_f or new.jp_score_j = new.jp_score_p then null
    else concat(case when new.ei_score_e > new.ei_score_i then 'E' else 'I' end, case when new.sn_score_s > new.sn_score_n then 'S' else 'N' end, case when new.tf_score_t > new.tf_score_f then 'T' else 'F' end, case when new.jp_score_j > new.jp_score_p then 'J' else 'P' end)
  end;
  if new.consent_given and new.consent_at is null then new.consent_at := now(); end if;
  if not new.consent_given then new.consent_at := null; end if;
  if tg_op = 'INSERT' or nullif(trim(coalesce(new.title, '')), '') is null then new.title := 'تست شخصیت‌شناسی - ' || coalesce(nullif(trim(new.respondent_name), ''), 'بدون نام'); end if;
  if v_questions_changed then
    new.ai_analysis := null;
    new.ai_analysis_status := 'not_requested';
    new.ai_analysis_error := null;
    new.ai_analysis_at := null;
    new.ai_analysis_model := null;
  end if;
  new.updated_at := now();
  return new;
end;
$$;


