--
-- Name: normalize_saas_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_saas_slug(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  select nullif(
    regexp_replace(
      regexp_replace(lower(coalesce(value, '')), '[^a-z0-9\-]+', '-', 'g'),
      '(^-+)|(-+$)',
      '',
      'g'
    ),
    ''
  )
$_$;


