--
-- Name: online_catalog_filter_fields(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.online_catalog_filter_fields(payload jsonb, requested jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select coalesce(jsonb_object_agg(entry.key, entry.value), '{}'::jsonb)
  from jsonb_each(coalesce(payload, '{}'::jsonb)) entry
  where jsonb_exists(coalesce(requested, '[]'::jsonb), entry.key)
    and entry.key !~* '(^id$|_id$|uuid|org|token|secret|password|created_by|updated_by)';
$_$;


--
-- Name: online_catalogs_set_derived_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.online_catalogs_set_derived_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
begin
  if new.public_token is null or new.public_token !~ '^[0-9a-f]{48}$' then
    new.public_token := substr(encode(sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text as bytea)), 'hex'), 1, 48);
  end if;
  new.record_count := jsonb_array_length(coalesce(new.source_record_ids, '[]'::jsonb));
  new.updated_at := now();
  if tg_op = 'INSERT' then
    new.last_refreshed_at := now();
  elsif new.source_record_ids is distinct from old.source_record_ids
     or new.display_field_keys is distinct from old.display_field_keys
     or new.presentation is distinct from old.presentation
     or new.content_snapshot is distinct from old.content_snapshot
     or new.content_update_mode is distinct from old.content_update_mode then
    new.last_refreshed_at := now();
  end if;
  return new;
end;
$_$;


--
-- Name: org_has_plan_feature(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_has_plan_feature(p_org_id uuid, p_feature_key text, p_default_enabled boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare policy jsonb;
begin
  if p_org_id is null or nullif(trim(p_feature_key), '') is null then return false; end if;
  -- Non-admin authenticated callers can only query their active organization
  if auth.role() = 'authenticated' and p_org_id is distinct from public.current_org_id() and not public.org_is_saas_admin(p_org_id) and not public.current_user_has_saas_admin_permission() then
    return false;
  end if;
  if to_regclass('public.local_deployment_runtime') is not null then
    execute 'select features from public.local_deployment_runtime where org_id=$1' into policy using p_org_id;
    if policy is not null then return coalesce(policy->p_feature_key, 'false'::jsonb) = 'true'::jsonb; end if;
  end if;
  return public.cloud_org_has_plan_feature(p_org_id, p_feature_key, p_default_enabled);
end;
$_$;


