--
-- Name: org_is_saas_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_is_saas_admin(p_org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p_org_id is not null
    and exists (
      select 1
      from public.org_roles role_row
      where role_row.org_id = p_org_id
        and (
          lower(coalesce(role_row.permissions -> '__saas_admin' ->> 'view', 'false')) = 'true'
          or lower(coalesce(role_row.permissions -> '__saas_admin' ->> 'edit', 'false')) = 'true'
        )
    );
$$;


--
-- Name: organization_access_host(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_access_host(p_org_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select nullif(trim(s.resolved_host),'') from public.saas_org_settings s where s.org_id=p_org_id),
    case when exists(select 1 from public.get_public_branding('kalam.tazesystem.ir') b where b.org_id=p_org_id)
      then 'kalam.tazesystem.ir' end);
$$;


--
-- Name: organization_display_name(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_display_name(p_org_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select coalesce(nullif(trim(cs.company_full_name),''),nullif(trim(cs.company_name),''),nullif(trim(cs.trade_name),''))
       from public.company_settings cs where cs.org_id=p_org_id
       order by cs.updated_at desc nulls last,cs.created_at desc nulls last limit 1),
    nullif(trim(o.name),''),'سازمان')
  from public.organizations o where o.id=p_org_id;
$$;


--
-- Name: organization_identity_profiles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_identity_profiles() RETURNS TABLE(id uuid, org_id uuid, full_name text, email text, mobile_1 text, job_title text, avatar_url text, role_id uuid, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 select p.id,m.org_id,p.full_name,
 case when public.can_manage_organization_members() or p.id=auth.uid() then p.email end,
 case when public.can_manage_organization_members() or p.id=auth.uid() then p.mobile_1 end,
 p.job_title,p.avatar_url,m.role_id,m.is_active
 from public.user_organization_memberships m join public.profiles p on p.id=m.user_id
 where m.org_id=public.current_org_id();
$$;


--
-- Name: patch_process_task_v2_custom_field_values(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.patch_process_task_v2_custom_field_values(p_task_id uuid, p_field_values jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_task public.tasks%rowtype;
begin
  if auth.uid() is null or v_org_id is null then
    raise exception using errcode = '42501', message = 'دسترسی سازمانی معتبر برای ذخیره فعالیت پیدا نشد.';
  end if;
  if p_task_id is null or p_field_values is null or jsonb_typeof(p_field_values) <> 'object' then
    raise exception using errcode = '22023', message = 'مقادیر فیلدهای اختصاصی معتبر نیست.';
  end if;

  update public.tasks t
  set
    recurrence_info = jsonb_set(
      case
        when jsonb_typeof(t.recurrence_info) = 'object' then t.recurrence_info
        else '{}'::jsonb
      end,
      '{process_task_custom_field_values}',
      case
        when jsonb_typeof(t.recurrence_info -> 'process_task_custom_field_values') = 'object'
          then t.recurrence_info -> 'process_task_custom_field_values'
        else '{}'::jsonb
      end || p_field_values,
      true
    ),
    updated_at = now()
  where t.id = p_task_id
    and t.org_id = v_org_id
  returning t.* into v_task;

  if not found then
    raise exception using errcode = 'P0002', message = 'فعالیت موردنظر برای ذخیره پیدا نشد یا دسترسی آن وجود ندارد.';
  end if;

  return jsonb_build_object(
    'id', v_task.id,
    'status', v_task.status,
    'recurrence_info', v_task.recurrence_info,
    'process_run_id', v_task.process_run_id,
    'process_run_stage_id', v_task.process_run_stage_id,
    'updated_at', v_task.updated_at
  );
end;
$$;


--
-- Name: pay_current_saas_order_from_billing_wallet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_current_saas_order_from_billing_wallet(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org_id uuid := public.current_org_id(); order_row public.saas_orders%rowtype; wallet public.org_billing_wallets%rowtype; applied jsonb;
begin
  if auth.uid() is null or v_org_id is null then raise exception 'organization_access_denied'; end if;
  if not exists (select 1 from public.user_organization_memberships m where m.user_id = auth.uid() and m.org_id = v_org_id and m.is_active and (m.is_owner or m.software_role = 'admin')) then raise exception 'organization_admin_required'; end if;
  select * into order_row from public.saas_orders where id = p_order_id and org_id = v_org_id for update;
  if order_row.id is null then raise exception 'saas_order_not_found'; end if;
  if order_row.status = 'paid' then return jsonb_build_object('success', true, 'already_applied', true); end if;
  if order_row.status <> 'pending_payment' then raise exception 'saas_order_not_payable'; end if;
  insert into public.org_billing_wallets(org_id) values (v_org_id) on conflict (org_id) do nothing;
  select * into wallet from public.org_billing_wallets where org_id = v_org_id for update;
  if wallet.status <> 'active' or wallet.balance_irt < order_row.total_irt then raise exception 'billing_wallet_insufficient'; end if;
  update public.org_billing_wallets set balance_irt = balance_irt - order_row.total_irt, updated_at = now() where org_id = v_org_id returning * into wallet;
  insert into public.org_billing_wallet_transactions(org_id, kind, amount_irt, balance_after_irt, order_id, description, created_by)
  values (v_org_id, 'order_payment', -order_row.total_irt, wallet.balance_irt, order_row.id, 'پرداخت سفارش حساب از کیف پول', auth.uid());
  applied := public.activate_saas_order_items(order_row.id, null, 'billing_wallet');
  return applied || jsonb_build_object('balance_irt', wallet.balance_irt);
end; $$;


--
-- Name: pay_current_saas_subscription_invoice_from_billing_wallet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_current_saas_subscription_invoice_from_billing_wallet(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org_id uuid := public.current_org_id();
begin
  if auth.uid() is null or v_org_id is null then raise exception 'organization_access_denied'; end if;
  if not exists (select 1 from public.user_organization_memberships m where m.user_id = auth.uid() and m.org_id = v_org_id and m.is_active and (m.is_owner or m.software_role = 'admin')) then raise exception 'organization_admin_required'; end if;
  if not exists (select 1 from public.saas_subscription_invoices where id = p_invoice_id and org_id = v_org_id) then raise exception 'saas_subscription_invoice_not_found'; end if;
  return public.pay_saas_subscription_invoice_from_wallet_internal(p_invoice_id);
end; $$;


--
-- Name: pay_saas_subscription_invoice_from_wallet_internal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pay_saas_subscription_invoice_from_wallet_internal(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare invoice_row public.saas_subscription_invoices%rowtype; wallet public.org_billing_wallets%rowtype; applied jsonb;
begin
  select * into invoice_row from public.saas_subscription_invoices where id = p_invoice_id for update;
  if invoice_row.id is null then raise exception 'saas_subscription_invoice_not_found'; end if;
  if invoice_row.status = 'paid' then return jsonb_build_object('success', true, 'already_applied', true); end if;
  insert into public.org_billing_wallets(org_id) values (invoice_row.org_id) on conflict (org_id) do nothing;
  select * into wallet from public.org_billing_wallets where org_id = invoice_row.org_id for update;
  update public.saas_subscription_invoices set last_payment_attempt_at = now(), updated_at = now() where id = invoice_row.id;
  if wallet.status <> 'active' or wallet.balance_irt < invoice_row.total_irt then return jsonb_build_object('success', false, 'reason', 'billing_wallet_insufficient'); end if;
  update public.org_billing_wallets set balance_irt = balance_irt - invoice_row.total_irt, updated_at = now() where org_id = invoice_row.org_id returning * into wallet;
  insert into public.org_billing_wallet_transactions(org_id, kind, amount_irt, balance_after_irt, description, metadata)
  values (invoice_row.org_id, 'order_payment', -invoice_row.total_irt, wallet.balance_irt, 'پرداخت صورت‌حساب اشتراک از کیف پول', jsonb_build_object('subscription_invoice_id', invoice_row.id));
  applied := public.activate_saas_subscription_invoice(invoice_row.id, null, 'billing_wallet');
  return applied || jsonb_build_object('balance_irt', wallet.balance_irt);
end; $$;


--
-- Name: payroll_safe_numeric(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_safe_numeric(p_value text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_value text := replace(replace(replace(trim(coalesce(p_value, '')), ',', ''), '٬', ''), '،', '');
begin
  if v_value !~ '^[+-]?([0-9]+([.][0-9]+)?|[.][0-9]+)$' then
    return 0;
  end if;
  return v_value::numeric;
end;
$_$;


--
-- Name: payroll_slip_line_amount(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payroll_slip_line_amount(p_line jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_amount numeric := public.payroll_safe_numeric(p_line->>'amount');
  v_total_price numeric := public.payroll_safe_numeric(p_line->>'total_price');
  v_quantity numeric := public.payroll_safe_numeric(p_line->>'quantity');
  v_unit_price numeric := public.payroll_safe_numeric(p_line->>'unit_price');
begin
  if v_amount <> 0 then return abs(v_amount); end if;
  if v_total_price <> 0 then return abs(v_total_price); end if;
  if v_quantity > 0 and v_unit_price > 0 then return v_quantity * v_unit_price; end if;
  return 0;
end;
$$;


--
-- Name: prepare_current_saas_billing_wallet_topup(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_current_saas_billing_wallet_topup(p_amount_irt numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org_id uuid := public.current_org_id(); amount numeric := greatest(0, coalesce(p_amount_irt, 0));
begin
  if auth.uid() is null or v_org_id is null then raise exception 'organization_access_denied'; end if;
  if amount < 10000 or amount > 100000000 then raise exception 'wallet_topup_amount_invalid'; end if;
  if not exists (select 1 from public.user_organization_memberships m where m.user_id = auth.uid() and m.org_id = v_org_id and m.is_active and (m.is_owner or m.software_role = 'admin')) then raise exception 'organization_admin_required'; end if;
  if not exists (select 1 from public.saas_org_settings where org_id = v_org_id) then raise exception 'saas_org_not_found'; end if;
  return jsonb_build_object('success', true, 'org_id', v_org_id, 'amount_irt', amount);
end; $$;


--
-- Name: prepare_current_saas_order_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_current_saas_order_payment(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare order_row public.saas_orders%rowtype;
begin
  if auth.uid() is null or public.current_org_id() is null then raise exception 'organization_access_denied'; end if;
  select * into order_row from public.saas_orders where id = p_order_id and org_id = public.current_org_id() for update;
  if order_row.id is null then raise exception 'saas_order_not_found'; end if;
  if order_row.status <> 'pending_payment' then raise exception 'saas_order_not_payable'; end if;
  if not exists (select 1 from public.user_organization_memberships where user_id = auth.uid() and org_id = order_row.org_id and is_active and (is_owner or software_role = 'admin')) then raise exception 'organization_admin_required'; end if;
  return jsonb_build_object('success', true, 'order_id', order_row.id, 'total_irt', order_row.total_irt, 'items', order_row.items);
end;
$$;


--
-- Name: prepare_current_saas_subscription_invoice_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_current_saas_subscription_invoice_payment(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_org_id uuid := public.current_org_id(); invoice_row public.saas_subscription_invoices%rowtype;
begin
  if auth.uid() is null or v_org_id is null then raise exception 'organization_access_denied'; end if;
  if not exists (select 1 from public.user_organization_memberships m where m.user_id = auth.uid() and m.org_id = v_org_id and m.is_active and (m.is_owner or m.software_role = 'admin')) then raise exception 'organization_admin_required'; end if;
  select * into invoice_row from public.saas_subscription_invoices where id = p_invoice_id and org_id = v_org_id for update;
  if invoice_row.id is null then raise exception 'saas_subscription_invoice_not_found'; end if;
  if invoice_row.status = 'paid' then raise exception 'saas_subscription_invoice_already_paid'; end if;
  if invoice_row.status not in ('issued', 'overdue') or invoice_row.total_irt <= 0 then raise exception 'saas_subscription_invoice_not_payable'; end if;
  return jsonb_build_object('success', true, 'invoice_id', invoice_row.id, 'amount_irt', invoice_row.total_irt);
end; $$;


--
-- Name: prepare_voip_provider_bridge(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_voip_provider_bridge(p_org_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.voip_external_accounts%rowtype; b public.voip_provider_bridges%rowtype;
 settings jsonb; v_revision text;
begin
 if p_org_id is null or p_user_id is null then raise exception 'voip_bridge_scope_required';end if;
 if not public.org_has_plan_feature(p_org_id,'voip_webphone',true) then raise exception 'voip_bridge_plan_disabled';end if;
 if not exists(select 1 from public.user_organization_memberships m where m.org_id=p_org_id and m.user_id=p_user_id
   and m.is_active and coalesce((m.settings->>'voip_enabled')::boolean,false)) then raise exception 'voip_bridge_member_disabled';end if;
 select i.settings into settings from public.integration_settings i where i.org_id=p_org_id and i.connection_type='voip' and i.is_active order by i.id limit 1;
 if coalesce(settings->>'usage_mode',case when settings->>'default_dial_mode'='webphone_webrtc' then 'browser' else 'reports' end)<>'browser'
   or coalesce(settings->>'browser_source','external')<>'external' then raise exception 'voip_bridge_mode_disabled';end if;
 select * into a from public.voip_external_accounts where org_id=p_org_id and assignee_profile_id=p_user_id and is_active;
 if not found then raise exception 'voip_bridge_account_missing';end if;
 if coalesce(a.metadata->>'connection_strategy','auto')='direct' then raise exception 'voip_bridge_route_disabled';end if;
 v_revision:=md5(a.extension||a.sip_secret||a.metadata::text);
 insert into public.voip_provider_bridges(org_id,account_id,revision,lease_until)
 values(p_org_id,a.id,v_revision,now()+interval '5 minutes')
 on conflict(org_id,account_id) do update set revision=excluded.revision,lease_until=excluded.lease_until,updated_at=now()
 returning * into b;
 return jsonb_build_object('id',b.id,'browser_username','b_'||replace(b.id::text,'-','')||'_browser',
   'browser_secret',b.browser_secret,'registration_status',case when b.revision=b.synced_revision and b.last_checked_at>now()-interval '30 seconds' then b.registration_status else 'pending' end,
   'failure_code',b.failure_code,'lease_until',b.lease_until);
end;$$;


--
-- Name: prevent_locked_record_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_locked_record_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_locked boolean := false;
  v_scoped_payroll_source_sync boolean := false;
  v_allowed_payroll_change boolean := false;
  v_allowed_payroll_recalculation boolean := false;
  v_allowed_financial_summary_sync boolean := false;
begin
  if tg_op not in ('UPDATE', 'DELETE') then return coalesce(new, old); end if;

  if tg_op = 'UPDATE' then
    select exists (
      select 1 from public.payroll_source_mutation_scopes scope
      where scope.org_id = old.org_id and scope.table_name = tg_table_name and scope.record_id = old.id
    ) into v_scoped_payroll_source_sync;

    if v_scoped_payroll_source_sync then
      v_allowed_payroll_change := case tg_table_name
        when 'payroll_calculation_entries' then
          (to_jsonb(new) - array['status', 'payroll_slip_id', 'updated_at', 'updated_by']) is not distinct from
          (to_jsonb(old) - array['status', 'payroll_slip_id', 'updated_at', 'updated_by'])
        when 'employee_bonus_requests' then
          (to_jsonb(new) - array['related_payroll_slip_id', 'updated_at', 'updated_by']) is not distinct from
          (to_jsonb(old) - array['related_payroll_slip_id', 'updated_at', 'updated_by'])
        when 'employee_penalty_requests' then
          (to_jsonb(new) - array['related_payroll_slip_id', 'updated_at', 'updated_by']) is not distinct from
          (to_jsonb(old) - array['related_payroll_slip_id', 'updated_at', 'updated_by'])
        when 'employee_advances' then
          (to_jsonb(new) - array['related_payroll_slip_id', 'paid_amount', 'remaining_amount', 'updated_at', 'updated_by']) is not distinct from
          (to_jsonb(old) - array['related_payroll_slip_id', 'paid_amount', 'remaining_amount', 'updated_at', 'updated_by'])
        when 'commission_drafts' then
          (to_jsonb(new) - array['posted_amount', 'remaining_amount', 'draft_status', 'updated_at', 'updated_by']) is not distinct from
          (to_jsonb(old) - array['posted_amount', 'remaining_amount', 'draft_status', 'updated_at', 'updated_by'])
        else false
      end;
      if v_allowed_payroll_change then return new; end if;
    end if;

    if tg_table_name = 'payroll_slips' and current_setting('app.payroll_source_sync', true) = 'active' then
      v_allowed_payroll_recalculation :=
        (to_jsonb(new) - array['base_salary', 'task_wage_total', 'bonus_total', 'earnings_total', 'deduction_total', 'insurance_employee_amount', 'insurance_employer_amount', 'gross_amount', 'net_amount', 'updated_at', 'updated_by'])
          is not distinct from
        (to_jsonb(old) - array['base_salary', 'task_wage_total', 'bonus_total', 'earnings_total', 'deduction_total', 'insurance_employee_amount', 'insurance_employer_amount', 'gross_amount', 'net_amount', 'updated_at', 'updated_by']);
      if v_allowed_payroll_recalculation then return new; end if;
    end if;

    if tg_table_name = 'customers' and current_setting('app.financial_summary_sync', true) = 'active' then
      v_allowed_financial_summary_sync :=
        (to_jsonb(new) - array['first_purchase_date', 'last_purchase_date', 'purchase_count', 'loyalty_total_spend', 'total_spend', 'total_paid_amount', 'total_balance', 'acquaintance_days', 'cooperation_days', 'updated_at', 'updated_by'])
          is not distinct from
        (to_jsonb(old) - array['first_purchase_date', 'last_purchase_date', 'purchase_count', 'loyalty_total_spend', 'total_spend', 'total_paid_amount', 'total_balance', 'acquaintance_days', 'cooperation_days', 'updated_at', 'updated_by']);
      if v_allowed_financial_summary_sync then return new; end if;
    end if;
  end if;

  select exists (
    select 1 from public.record_locks lock_row
    where lock_row.org_id = old.org_id and lock_row.record_id = old.id
      and (lock_row.module_id = tg_table_name or lock_row.metadata ->> 'table_name' = tg_table_name)
  ) into v_locked;
  if v_locked then raise exception 'این رکورد قفل شده و قابل تغییر یا حذف نیست.'; end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: prevent_org_role_cycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_org_role_cycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_parent_id uuid;
begin
  if new.parent_id is null then
    return new;
  end if;

  if new.parent_id = new.id then
    raise exception 'جایگاه سازمانی نمی‌تواند زیرمجموعه خودش باشد.';
  end if;

  v_parent_id := new.parent_id;
  while v_parent_id is not null loop
    if v_parent_id = new.id then
      raise exception 'ساختار جایگاه‌های سازمانی چرخه دارد و معتبر نیست.';
    end if;

    select parent_id
      into v_parent_id
    from public.org_roles
    where id = v_parent_id;
  end loop;

  return new;
end;
$$;


--
-- Name: preview_advertising_campaign_audience(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_advertising_campaign_audience(p_campaign_id uuid, p_limit integer DEFAULT 200, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_campaign public.advertising_campaigns%rowtype;
  v_rule record;
  v_row jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_seen text[] := '{}'::text[];
  v_key text;
  v_contact_key text;
  v_customer_key text;
  v_ref text;
  v_title text;
  v_contact text;
  v_is_duplicate boolean;
  v_match_count integer := 0;
  v_limit integer := least(greatest(coalesce(p_limit,200),1),500);
  v_offset integer := greatest(coalesce(p_offset,0),0);
begin
  select * into v_campaign from public.advertising_campaigns
  where id=p_campaign_id and org_id=public.current_org_id();
  if v_campaign.id is null or not public.can_edit_advertising_campaign(p_campaign_id) then
    raise exception 'اجازه مشاهده مخاطبان این کمپین را ندارید.' using errcode='42501';
  end if;

  for v_rule in select * from public.advertising_campaign_audience_rules
    where campaign_id=p_campaign_id and org_id=v_campaign.org_id and enabled=true
  loop
    for v_row in execute format('select to_jsonb(t) from public.%I t where t.org_id=$1 order by t.id',v_rule.target_module_id)
      using v_campaign.org_id
    loop
      if not public.advertising_campaign_conditions_match(v_row,v_rule.conditions_all,v_rule.conditions_any) then continue; end if;
      v_match_count := v_match_count + 1;
      v_ref := v_rule.target_module_id || ':' || coalesce(v_row->>'id','');
      v_contact := coalesce(nullif(v_row->>'mobile',''),nullif(v_row->>'mobile_1',''),nullif(v_row->>'phone',''),nullif(v_row->>'email',''));
      v_contact_key := case when position('@' in coalesce(v_contact,'')) > 0
          then 'email:' || public.advertising_campaign_contact_key('email',v_contact)
          when nullif(v_contact,'') is not null
          then 'phone:' || public.advertising_campaign_contact_key('sms',v_contact)
          else null end;
      v_customer_key := case when v_rule.target_module_id='customers' then 'customer:' || coalesce(v_row->>'id','')
          when nullif(v_row->>'customer_id','') is not null then 'customer:' || (v_row->>'customer_id')
          else null end;
      v_key := coalesce(v_contact_key,v_customer_key,v_ref);
      v_is_duplicate := coalesce(v_contact_key=any(v_seen),false)
        or coalesce(v_customer_key=any(v_seen),false)
        or (v_contact_key is null and v_customer_key is null and v_ref=any(v_seen));
      if v_contact_key is not null and not v_contact_key=any(v_seen) then v_seen := array_append(v_seen,v_contact_key); end if;
      if v_customer_key is not null and not v_customer_key=any(v_seen) then v_seen := array_append(v_seen,v_customer_key); end if;
      if v_contact_key is null and v_customer_key is null and not v_ref=any(v_seen) then v_seen := array_append(v_seen,v_ref); end if;
      if v_match_count <= v_offset or jsonb_array_length(v_rows) >= v_limit then continue; end if;
      v_title := coalesce(nullif(v_row->>'name',''),nullif(v_row->>'full_name',''),nullif(v_row->>'business_name',''),nullif(v_row->>'system_code',''),'[بدون عنوان]');
      v_rows := v_rows || jsonb_build_array(jsonb_build_object(
        'ref',v_ref,'source_module_id',v_rule.target_module_id,'title',v_title,
        'system_code',v_row->>'system_code','contact',v_contact,
        'is_duplicate',v_is_duplicate
      ));
    end loop;
  end loop;
  return jsonb_build_object('rows',v_rows,'total',v_match_count,'limit',v_limit,'offset',v_offset);
end;
$_$;


--
-- Name: process_v2_delete_task_stage(uuid, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_v2_delete_task_stage(p_org_id uuid, p_task_id uuid, p_stage_id uuid, p_mode text, p_deleted_by uuid DEFAULT auth.uid(), p_deleted_by_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_current_org_id uuid := public.current_org_id();
  v_mode text := lower(btrim(coalesce(p_mode, '')));
  v_task public.tasks%rowtype;
  v_stage public.process_run_stages%rowtype;
  v_run public.process_runs%rowtype;
  v_task_snapshot jsonb;
  v_deleted_task boolean := false;
  v_unlinked_task boolean := false;
  v_stage_tombstoned boolean := false;
begin
  if auth.uid() is null
    or p_org_id is null
    or v_current_org_id is null
    or p_org_id <> v_current_org_id then
    raise exception 'دسترسی حذف فعالیت فرآیند برای این سازمان وجود ندارد.' using errcode = '42501';
  end if;

  if v_mode not in ('unlink', 'delete_task_keep_draft', 'delete_all') then
    raise exception 'نوع حذف فعالیت فرآیند معتبر نیست.' using errcode = '22023';
  end if;

  if p_task_id is not null then
    select *
    into v_task
    from public.tasks
    where id = p_task_id
      and org_id = p_org_id
    for update;
  end if;

  if p_stage_id is not null then
    select s.*
    into v_stage
    from public.process_run_stages s
    join public.process_runs r on r.id = s.process_run_id
    where s.id = p_stage_id
      and r.org_id = p_org_id
    for update;
  end if;

  if v_stage.id is null and v_task.process_run_stage_id is not null then
    select s.*
    into v_stage
    from public.process_run_stages s
    join public.process_runs r on r.id = s.process_run_id
    where s.id = v_task.process_run_stage_id
      and r.org_id = p_org_id
    for update;
  end if;

  if v_task.id is null and v_stage.task_id is not null then
    select *
    into v_task
    from public.tasks
    where id = v_stage.task_id
      and org_id = p_org_id
    for update;
  end if;

  if v_stage.id is not null then
    select *
    into v_run
    from public.process_runs
    where id = v_stage.process_run_id
      and org_id = p_org_id;
  end if;

  if v_task.id is null and v_mode in ('unlink', 'delete_task_keep_draft') then
    raise exception 'فعالیت مرتبط پیدا نشد.' using errcode = 'P0001';
  end if;

  if v_mode = 'unlink' and v_task.id is not null then
    update public.tasks
    set related_to_module = null,
        source_module_id = null,
        source_record_id = null,
        source_template_id = null,
        process_group_id = null,
        process_run_id = null,
        process_run_stage_id = null,
        process_node_key = null,
        process_lane_key = null,
        recurrence_info = coalesce(recurrence_info, '{}'::jsonb)
          - 'process_group'
          - 'process_links'
          - 'process_graph'
          - 'process_run_id'
          - 'process_run_stage_id'
          - 'process_node_key'
          - 'process_lane_key',
        updated_at = now()
    where id = v_task.id
      and org_id = p_org_id;
    v_unlinked_task := true;
  elsif v_task.id is not null then
    v_task_snapshot := to_jsonb(v_task);

    delete from public.recycle_bin_records
    where source_table = 'tasks'
      and source_record_id = v_task.id;

    insert into public.recycle_bin_records (
      org_id,
      module_id,
      source_table,
      source_record_id,
      record_title,
      snapshot,
      deleted_by,
      deleted_by_name
    )
    values (
      p_org_id,
      'tasks',
      'tasks',
      v_task.id,
      public.recycle_bin_record_title(v_task_snapshot),
      v_task_snapshot,
      p_deleted_by,
      nullif(btrim(coalesce(p_deleted_by_name, '')), '')
    );

    delete from public.tasks
    where id = v_task.id
      and org_id = p_org_id;
    v_deleted_task := true;
  end if;

  if v_stage.id is not null then
    if v_mode = 'delete_all' then
      insert into public.process_v2_deleted_stage_marks (
        org_id,
        process_run_stage_id,
        process_run_id,
        process_group_id,
        template_stage_id,
        draft_stage_key,
        process_node_key,
        process_lane_key,
        deleted_by,
        deleted_by_name,
        deleted_at
      )
      values (
        p_org_id,
        v_stage.id,
        v_stage.process_run_id,
        nullif(btrim(coalesce(v_run.process_group_id, '')), ''),
        v_stage.template_stage_id,
        coalesce(
          nullif(btrim(coalesce(v_stage.metadata ->> 'draft_stage_key', '')), ''),
          nullif(btrim(coalesce(v_stage.metadata ->> 'draft_stage_id', '')), '')
        ),
        coalesce(
          nullif(btrim(coalesce(v_stage.process_node_key, '')), ''),
          nullif(btrim(coalesce(v_stage.metadata ->> 'process_node_key', '')), '')
        ),
        coalesce(
          nullif(btrim(coalesce(v_stage.process_lane_key, '')), ''),
          nullif(btrim(coalesce(v_stage.metadata ->> 'process_lane_key', '')), '')
        ),
        p_deleted_by,
        nullif(btrim(coalesce(p_deleted_by_name, '')), ''),
        now()
      )
      on conflict (org_id, process_run_stage_id) do update
      set process_run_id = excluded.process_run_id,
          process_group_id = excluded.process_group_id,
          template_stage_id = excluded.template_stage_id,
          draft_stage_key = excluded.draft_stage_key,
          process_node_key = excluded.process_node_key,
          process_lane_key = excluded.process_lane_key,
          deleted_by = excluded.deleted_by,
          deleted_by_name = excluded.deleted_by_name,
          deleted_at = excluded.deleted_at;
      v_stage_tombstoned := true;
    else
      update public.process_run_stages
      set task_id = null,
          status = 'todo',
          started_at = null,
          completed_at = null,
          updated_at = now()
      where id = v_stage.id;
    end if;
  end if;

  return jsonb_build_object(
    'deleted_task', v_deleted_task,
    'unlinked_task', v_unlinked_task,
    'stage_tombstoned', v_stage_tombstoned,
    'task_id', case when v_task.id is null then null else v_task.id end,
    'stage_id', case when v_stage.id is null then null else v_stage.id end
  );
end;
$$;


--
-- Name: process_v2_save_draft_stage(uuid, uuid, text, uuid, uuid, numeric, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_v2_save_draft_stage(p_org_id uuid, p_stage_id uuid, p_stage_name text, p_assignee_user_id uuid DEFAULT NULL::uuid, p_assignee_role_id uuid DEFAULT NULL::uuid, p_wage numeric DEFAULT NULL::numeric, p_planned_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_planned_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_current_org_id uuid := public.current_org_id();
  v_stage public.process_run_stages%rowtype;
  v_next_name text := coalesce(nullif(btrim(coalesce(p_stage_name, '')), ''), 'مرحله');
  v_next_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
begin
  if auth.uid() is null
    or p_org_id is null
    or p_stage_id is null
    or v_current_org_id is null
    or p_org_id <> v_current_org_id then
    raise exception 'دسترسی ذخیره پیش‌نویس مرحله فرآیند وجود ندارد.' using errcode = '42501';
  end if;

  perform public.assert_process_assignee_org(
    p_org_id,
    case when p_assignee_role_id is not null then null else p_assignee_user_id end,
    p_assignee_role_id
  );

  update public.process_run_stages s
  set stage_name = v_next_name,
      assignee_user_id = case when p_assignee_role_id is not null then null else p_assignee_user_id end,
      assignee_role_id = p_assignee_role_id,
      wage = coalesce(p_wage, s.wage, 0),
      planned_start_at = p_planned_start_at,
      planned_due_at = p_planned_due_at,
      metadata = coalesce(s.metadata, '{}'::jsonb)
        || v_next_metadata
        || jsonb_build_object(
          'name', v_next_name,
          'stage_name', v_next_name,
          'assignee_user_id', case when p_assignee_role_id is not null then null else p_assignee_user_id end,
          'assignee_role_id', p_assignee_role_id,
          'wage', coalesce(p_wage, s.wage, 0),
          'planned_start_at', p_planned_start_at,
          'planned_due_at', p_planned_due_at
        ),
      updated_at = now()
  from public.process_runs r
  where s.id = p_stage_id
    and r.id = s.process_run_id
    and r.org_id = p_org_id
  returning s.* into v_stage;

  if v_stage.id is null then
    raise exception 'مرحله پیش‌نویس فرآیند پیدا نشد.' using errcode = 'P0001';
  end if;

  return jsonb_build_object('stage', to_jsonb(v_stage));
end;
$$;


--
-- Name: provision_self_service_demo(text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_self_service_demo(p_full_name text, p_mobile text, p_business_name text, p_employee_count_band text, p_discovery_source text, p_requested_slug text, p_owner_email text DEFAULT NULL::text, p_industry text DEFAULT NULL::text, p_brand_palette_key text DEFAULT 'kalam_sky'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  normalized_mobile text := public.normalize_demo_mobile(p_mobile);
  normalized_slug text := public.normalize_saas_slug(p_requested_slug);
  normalized_owner_email text := lower(nullif(trim(coalesce(p_owner_email, '')), ''));
  normalized_industry text := nullif(trim(coalesce(p_industry, '')), '');
  normalized_palette_key text := lower(nullif(trim(coalesce(p_brand_palette_key, '')), ''));
  current_user_id uuid := auth.uid();
  request_row public.saas_onboarding_requests%rowtype;
  current_profile public.profiles%rowtype;
  conflicting_profile public.profiles%rowtype;
  target_plan public.saas_plans%rowtype;
  admin_role_id uuid;
  target_org_id uuid;
  existing_issuance_count integer := 0;
  effective_demo_limit integer := 0;
  target_trial_days integer := 15;
  target_redirect_host text;
  display_business_name text;
  optional_warnings jsonb := '[]'::jsonb;
begin
  if current_user_id is null then
    raise exception 'demo_auth_required';
  end if;

  if coalesce(trim(p_full_name), '') = '' then
    raise exception 'demo_full_name_required';
  end if;

  if normalized_mobile is null then
    raise exception 'demo_mobile_invalid';
  end if;

  if normalized_slug is null or length(normalized_slug) < 3 then
    raise exception 'demo_slug_invalid';
  end if;

  if normalized_owner_email is null or normalized_owner_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'demo_owner_email_invalid';
  end if;

  if normalized_palette_key is null or normalized_palette_key not in (
    'executive_indigo', 'corporate_blue', 'deep_ocean',
    'ruby_red', 'amber_navy', 'kalam_sky'
  ) then
    normalized_palette_key := 'kalam_sky';
  end if;

  display_business_name := coalesce(nullif(trim(coalesce(p_business_name, '')), ''), trim(p_full_name));

  insert into public.saas_onboarding_requests (
    auth_user_id, full_name, mobile, business_name,
    employee_count_band, discovery_source, requested_slug,
    owner_email, industry, brand_palette_key, status, is_demo_request
  )
  values (
    current_user_id,
    trim(p_full_name),
    normalized_mobile,
    nullif(trim(coalesce(p_business_name, '')), ''),
    nullif(trim(coalesce(p_employee_count_band, '')), ''),
    nullif(trim(coalesce(p_discovery_source, '')), ''),
    normalized_slug,
    normalized_owner_email,
    normalized_industry,
    normalized_palette_key,
    'started',
    true
  )
  returning * into request_row;

  select * into current_profile
  from public.profiles
  where id = current_user_id
  limit 1;

  if current_profile.id is not null
     and (current_profile.org_id is not null or current_profile.role_id is not null) then
    update public.saas_onboarding_requests
      set status = 'needs_admin_review',
          failure_code = case
            when current_profile.org_id is not null then 'profile_already_attached'
            else 'profile_role_without_org'
          end,
          failure_message = 'needs_admin_review',
          updated_at = now()
    where id = request_row.id;

    return jsonb_build_object(
      'success', false,
      'status', 'needs_admin_review',
      'request_id', request_row.id,
      'message', 'needs_admin_review'
    );
  end if;

  if (public.check_saas_slug_availability(normalized_slug) ->> 'available')::boolean is false then
    update public.saas_onboarding_requests
      set status = 'failed',
          failure_code = 'slug_taken',
          failure_message = 'slug_taken',
          updated_at = now()
    where id = request_row.id;
    raise exception 'slug_taken';
  end if;

  select * into conflicting_profile
  from public.profiles p
  where p.id <> current_user_id
    and public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) = normalized_mobile
  limit 1;

  if conflicting_profile.id is not null then
    update public.saas_onboarding_requests
      set status = 'needs_admin_review',
          failure_code = 'mobile_profile_conflict',
          failure_message = 'mobile_profile_conflict',
          updated_at = now()
    where id = request_row.id;

    return jsonb_build_object(
      'success', false,
      'status', 'needs_admin_review',
      'request_id', request_row.id,
      'message', 'mobile_profile_conflict'
    );
  end if;

  select count(*) into existing_issuance_count
  from public.saas_demo_issuance
  where mobile = normalized_mobile;

  effective_demo_limit := public.get_effective_demo_limit(normalized_mobile);

  if existing_issuance_count >= effective_demo_limit then
    update public.saas_onboarding_requests
      set status = 'failed',
          approved_demo_count_snapshot = existing_issuance_count,
          failure_code = 'demo_limit_reached',
          failure_message = 'demo_limit_reached',
          updated_at = now()
    where id = request_row.id;
    raise exception 'demo_limit_reached';
  end if;

  select * into target_plan
  from public.saas_plans
  where is_active = true
    and (is_demo_default = true or lower(code) = 'public_demo_full')
  order by is_demo_default desc, sort_order asc, created_at asc
  limit 1;

  if target_plan.id is null then
    update public.saas_onboarding_requests
      set status = 'failed',
          failure_code = 'demo_plan_missing',
          failure_message = 'demo_plan_missing',
          updated_at = now()
    where id = request_row.id;
    raise exception 'demo_plan_missing';
  end if;

  target_trial_days := greatest(coalesce(target_plan.trial_days, 15), 1);

  insert into public.organizations (name, slug, is_active)
  values (display_business_name, normalized_slug, true)
  returning id into target_org_id;

  insert into public.org_roles (org_id, title, permissions, is_system)
  values (target_org_id, 'ادمین', '{}'::jsonb, true)
  returning id into admin_role_id;

  insert into public.profiles (
    id, org_id, role_id, role,
    full_name, email, mobile_1, is_active
  )
  values (
    current_user_id,
    target_org_id,
    admin_role_id,
    'admin',
    trim(p_full_name),
    normalized_owner_email,
    regexp_replace(normalized_mobile, '^\+98', '0'),
    true
  )
  on conflict (id) do update
    set org_id = excluded.org_id,
        role_id = excluded.role_id,
        role = excluded.role,
        full_name = excluded.full_name,
        email = excluded.email,
        mobile_1 = excluded.mobile_1,
        is_active = true,
        updated_at = now()
    where public.profiles.org_id is null
      and public.profiles.role_id is null;

  if not exists (
    select 1
    from public.profiles p
    where p.id = current_user_id
      and p.org_id = target_org_id
      and p.role_id = admin_role_id
  ) then
    raise exception 'demo_profile_attach_failed';
  end if;

  target_redirect_host := normalized_slug || '.tazesystem.ir';

  insert into public.saas_org_settings (
    org_id, slug, status, plan_code, trial_ends_at,
    is_demo, is_readonly, requested_subdomain, resolved_host,
    provisioning_source, dns_status, primary_contact_mobile,
    created_by, updated_by
  )
  values (
    target_org_id, normalized_slug, 'demo', target_plan.code,
    now() + make_interval(days => target_trial_days),
    true, false, normalized_slug, target_redirect_host,
    'self_service', 'active', normalized_mobile,
    current_user_id, current_user_id
  );

  insert into public.saas_demo_issuance (
    mobile, auth_user_id, org_id, request_id, issued_by, issuance_mode
  )
  values (
    normalized_mobile, current_user_id, target_org_id,
    request_row.id, current_user_id, 'self_service'
  );

  begin
    insert into public.company_settings (
      org_id, company_name, company_full_name, trade_name,
      brand_palette_key, ceo_name, mobile, email, updated_by
    )
    values (
      target_org_id, display_business_name, display_business_name, display_business_name,
      normalized_palette_key, trim(p_full_name),
      regexp_replace(normalized_mobile, '^\+98', '0'), normalized_owner_email, current_user_id
    );
  exception when others then
    optional_warnings := optional_warnings || jsonb_build_array(jsonb_build_object('step', 'company_settings', 'message', SQLERRM));
  end;

  begin
    insert into public.integration_settings (
      org_id, connection_type, provider, settings, is_active, created_by, updated_by
    )
    values (
      target_org_id, 'ui_theme', 'branding',
      jsonb_build_object('branding', jsonb_build_object(
        'brand_name', display_business_name,
        'short_name', display_business_name,
        'app_title', display_business_name,
        'palette_key', normalized_palette_key
      )),
      true, current_user_id, current_user_id
    );
  exception when others then
    optional_warnings := optional_warnings || jsonb_build_array(jsonb_build_object('step', 'integration_settings', 'message', SQLERRM));
  end;

  begin
    insert into public.marketing_leads (
      org_id, name, business_name, first_name, mobile,
      source, status, lead_type, description
    )
    values (
      target_org_id,
      'درخواست دمو تازه سیستم - ' || display_business_name,
      nullif(trim(coalesce(p_business_name, '')), ''),
      trim(p_full_name),
      normalized_mobile,
      'saas_wizard', 'new', 'new_lead',
      concat_ws(E'\n',
        'Industry: ' || coalesce(normalized_industry, '-'),
        'Employee band: ' || coalesce(nullif(trim(coalesce(p_employee_count_band, '')), ''), '-'),
        'Discovery source: ' || coalesce(nullif(trim(coalesce(p_discovery_source, '')), ''), '-'),
        'Owner email: ' || normalized_owner_email
      )
    );
  exception when others then
    optional_warnings := optional_warnings || jsonb_build_array(jsonb_build_object('step', 'marketing_leads', 'message', SQLERRM));
  end;

  update public.saas_onboarding_requests
    set org_id = target_org_id,
        status = 'provisioned',
        approved_demo_count_snapshot = existing_issuance_count + 1,
        notes = case
          when jsonb_array_length(optional_warnings) = 0 then notes
          else concat_ws(E'\n', nullif(notes, ''), 'optional_warnings=' || optional_warnings::text)
        end,
        updated_at = now()
  where id = request_row.id;

  return jsonb_build_object(
    'success', true,
    'status', 'provisioned',
    'request_id', request_row.id,
    'org_id', target_org_id,
    'slug', normalized_slug,
    'redirect_host', target_redirect_host,
    'plan_code', target_plan.code,
    'trial_days', target_trial_days,
    'optional_warnings', optional_warnings
  );

exception
  when unique_violation then
    if request_row.id is not null then
      update public.saas_onboarding_requests
        set status = 'failed',
            provision_attempts = provision_attempts + 1,
            failure_code = 'unique_conflict',
            failure_message = SQLERRM,
            updated_at = now()
      where id = request_row.id;
    end if;
    raise exception 'unique_conflict: %', SQLERRM;
  when others then
    if request_row.id is not null then
      update public.saas_onboarding_requests
        set status = case
              when coalesce(status, '') in ('', 'draft', 'started') then 'failed'
              else status
            end,
            provision_attempts = provision_attempts + 1,
            failure_code = coalesce(failure_code, 'provision_error'),
            failure_message = SQLERRM,
            updated_at = now()
      where id = request_row.id;
    end if;
    raise;
end
$_$;


--
-- Name: provision_self_service_demo_for_existing_member(text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_self_service_demo_for_existing_member(p_full_name text, p_mobile text, p_business_name text, p_employee_count_band text, p_discovery_source text, p_requested_slug text, p_owner_email text DEFAULT NULL::text, p_industry text DEFAULT NULL::text, p_brand_palette_key text DEFAULT 'kalam_sky'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  normalized_mobile text := public.normalize_demo_mobile(p_mobile);
  normalized_slug text := public.normalize_saas_slug(p_requested_slug);
  normalized_owner_email text := lower(nullif(trim(coalesce(p_owner_email, '')), ''));
  current_user_id uuid := auth.uid(); current_auth_mobile text;
  request_row public.saas_onboarding_requests%rowtype; target_plan public.saas_plans%rowtype;
  target_org_id uuid; admin_role_id uuid; existing_issuance_count integer := 0;
  effective_demo_limit integer := 0; target_trial_days integer := 15; display_business_name text;
begin
  if current_user_id is null then raise exception 'demo_auth_required'; end if;
  if coalesce(trim(p_full_name), '') = '' then raise exception 'demo_full_name_required'; end if;
  if normalized_mobile is null then raise exception 'demo_mobile_invalid'; end if;
  if normalized_slug is null or length(normalized_slug) < 3 then raise exception 'demo_slug_invalid'; end if;
  if normalized_owner_email is null or normalized_owner_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'demo_owner_email_invalid'; end if;
  select public.normalize_demo_mobile(u.phone) into current_auth_mobile from auth.users u where u.id = current_user_id;
  if current_auth_mobile is distinct from normalized_mobile then raise exception 'demo_phone_session_mismatch'; end if;
  if not exists (select 1 from public.profiles p where p.id = current_user_id and coalesce(p.is_active, true)) then raise exception 'demo_member_profile_invalid'; end if;
  if not exists (select 1 from public.user_organization_memberships m where m.user_id = current_user_id and m.is_active) then raise exception 'demo_member_access_missing'; end if;
  if exists (select 1 from public.user_organization_memberships m where m.user_id = current_user_id and m.is_active and m.is_owner) then raise exception 'demo_owner_already_exists'; end if;
  if (public.check_saas_slug_availability(normalized_slug) ->> 'available')::boolean is false then raise exception 'slug_taken'; end if;

  insert into public.saas_onboarding_requests (auth_user_id, full_name, mobile, business_name, employee_count_band, discovery_source, requested_slug, owner_email, industry, brand_palette_key, status, is_demo_request)
  values (current_user_id, trim(p_full_name), normalized_mobile, nullif(trim(coalesce(p_business_name, '')), ''), nullif(trim(coalesce(p_employee_count_band, '')), ''), nullif(trim(coalesce(p_discovery_source, '')), ''), normalized_slug, normalized_owner_email, nullif(trim(coalesce(p_industry, '')), ''), coalesce(nullif(trim(p_brand_palette_key), ''), 'kalam_sky'), 'started', true)
  returning * into request_row;
  select count(*) into existing_issuance_count from public.saas_demo_issuance where mobile = normalized_mobile;
  effective_demo_limit := public.get_effective_demo_limit(normalized_mobile);
  if existing_issuance_count >= effective_demo_limit then raise exception 'demo_limit_reached'; end if;
  select * into target_plan from public.saas_plans where is_active and (is_demo_default or lower(code) = 'public_demo_full') order by is_demo_default desc, sort_order asc, created_at asc limit 1;
  if target_plan.id is null then raise exception 'demo_plan_missing'; end if;
  target_trial_days := greatest(coalesce(target_plan.trial_days, 15), 1);
  display_business_name := coalesce(nullif(trim(coalesce(p_business_name, '')), ''), trim(p_full_name));
  insert into public.organizations (name, slug, is_active) values (display_business_name, normalized_slug, true) returning id into target_org_id;
  insert into public.org_roles (org_id, title, permissions, is_system) values (target_org_id, 'ادمین', '{}'::jsonb, true) returning id into admin_role_id;
  insert into public.user_organization_memberships (user_id, org_id, role_id, software_role, is_owner, is_active) values (current_user_id, target_org_id, admin_role_id, 'admin', true, true);
  insert into public.saas_org_settings (org_id, slug, status, plan_code, trial_ends_at, is_demo, is_readonly, requested_subdomain, resolved_host, provisioning_source, dns_status, primary_contact_mobile, owner_name, owner_email, request_id, created_by, updated_by)
  values (target_org_id, normalized_slug, 'demo', target_plan.code, now() + make_interval(days => target_trial_days), true, false, normalized_slug, normalized_slug || '.tazesystem.ir', 'self_service', 'active', normalized_mobile, trim(p_full_name), normalized_owner_email, request_row.id, current_user_id, current_user_id);
  insert into public.saas_demo_issuance (mobile, auth_user_id, org_id, request_id, issued_by, issuance_mode) values (normalized_mobile, current_user_id, target_org_id, request_row.id, current_user_id, 'self_service');
  update public.company_settings set company_name = display_business_name, company_full_name = display_business_name, trade_name = display_business_name, ceo_name = trim(p_full_name), mobile = regexp_replace(normalized_mobile, '^\+98', '0'), email = normalized_owner_email, updated_by = current_user_id where org_id = target_org_id;
  if not found then
    insert into public.company_settings (org_id, company_name, company_full_name, trade_name, brand_palette_key, ceo_name, mobile, email, updated_by)
    values (target_org_id, display_business_name, display_business_name, display_business_name, coalesce(nullif(trim(p_brand_palette_key), ''), 'kalam_sky'), trim(p_full_name), regexp_replace(normalized_mobile, '^\+98', '0'), normalized_owner_email, current_user_id);
  end if;
  update public.saas_onboarding_requests set org_id = target_org_id, status = 'provisioned', approved_demo_count_snapshot = existing_issuance_count + 1, updated_at = now() where id = request_row.id;
  return jsonb_build_object('success', true, 'status', 'provisioned', 'request_id', request_row.id, 'org_id', target_org_id, 'slug', normalized_slug, 'redirect_host', normalized_slug || '.tazesystem.ir', 'plan_code', target_plan.code, 'trial_days', target_trial_days);
exception when others then
  if request_row.id is not null then update public.saas_onboarding_requests set status = 'failed', provision_attempts = provision_attempts + 1, failure_code = coalesce(failure_code, 'provision_error'), failure_message = SQLERRM, updated_at = now() where id = request_row.id; end if;
  raise;
end;
$_$;


--
-- Name: publish_tenant_site_page(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_tenant_site_page(p_page_id uuid) RETURNS TABLE(page_id uuid, published_version_id uuid, published_at timestamp with time zone, title text, slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_page public.site_pages%rowtype;
  v_version public.site_page_versions%rowtype;
  v_published_at timestamptz := now();
begin
  if auth.uid() is null or not public.can_manage_tenant_site_pages(public.current_org_id()) then
    raise exception 'Not authorized to publish site pages';
  end if;
  select p.* into v_page from public.site_pages p
    where p.id = p_page_id and p.org_id = public.current_org_id() for update;
  if not found or v_page.draft_version_id is null then raise exception 'Saved draft not found'; end if;
  select v.* into v_version from public.site_page_versions v
    where v.id = v_page.draft_version_id and v.page_id = v_page.id and v.org_id = v_page.org_id;
  if not found or not public.is_valid_tenant_site_blocks(v_version.blocks) then raise exception 'Draft version is invalid'; end if;
  update public.site_pages set published_version_id = v_version.id, published_at = v_published_at,
    published_by = auth.uid(), updated_by = auth.uid(), updated_at = v_published_at
    where id = v_page.id and org_id = v_page.org_id;
  return query select v_page.id, v_version.id, v_published_at, v_version.title, v_version.slug;
end;
$$;


--
-- Name: purge_expired_recycle_bin_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_recycle_bin_records() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_count integer := 0;
begin
  delete from public.recycle_bin_records
  where expires_at < now();

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: queue_customer_club_credit_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_customer_club_credit_reminders() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.entry_type <> 'debit' then
    perform public.enqueue_customer_club_reminder_actions(coalesce(new.metadata->'notifications', '{}'::jsonb), new.customer_id,
      jsonb_build_object('ledger_id', new.id, 'amount', new.amount, 'credit_added_at', coalesce(new.effective_date, now())));
  end if;
  return new;
end; $$;


--
-- Name: queue_customer_club_discount_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_customer_club_discount_reminders() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' or (old.is_active is distinct from new.is_active and new.is_active) then
    perform public.enqueue_customer_club_reminder_actions(coalesce(new.metadata->'notifications', '{}'::jsonb), new.customer_id,
      jsonb_build_object('discount_code_id', new.id, 'discount_code', new.code, 'discount_expires_at', new.ends_at));
  end if;
  return new;
end; $$;


--
-- Name: queue_customer_club_rule_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_customer_club_rule_reminders() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' or (old.is_active is distinct from new.is_active and new.is_active) then
    perform public.enqueue_customer_club_reminder_actions(coalesce(new.config->'notifications', '{}'::jsonb), null,
      jsonb_build_object('rule_id', new.id, 'rule_name', new.name, 'plan_expires_at', new.ends_at));
  end if;
  return new;
end; $$;


--
-- Name: queue_due_interval_workflows(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_due_interval_workflows() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_now timestamptz := now();
  v_tehran timestamp := v_now at time zone 'Asia/Tehran';
  v_hour integer := extract(hour from v_tehran)::integer;
begin
  update public.workflows w
  set server_queued_at = v_now
  where w.is_active = true
    and w.trigger_type = 'interval'
    and w.agent_task_config is null
    and w.server_queued_at is null
    and public.workflow_interval_scheduled_due_at(w.last_run_at, w.interval_value::integer, w.interval_unit, w.interval_at, w.interval_first_run_at, w.interval_minute, w.interval_day_of_month, v_now) is not null
    and (
      (w.interval_allowed_from_hour is null and w.interval_allowed_to_hour is null)
      or (w.interval_allowed_from_hour is not null and w.interval_allowed_to_hour is not null and ((w.interval_allowed_from_hour <= w.interval_allowed_to_hour and v_hour between w.interval_allowed_from_hour and w.interval_allowed_to_hour) or (w.interval_allowed_from_hour > w.interval_allowed_to_hour and (v_hour >= w.interval_allowed_from_hour or v_hour <= w.interval_allowed_to_hour))))
      or (w.interval_allowed_from_hour is not null and w.interval_allowed_to_hour is null and v_hour >= w.interval_allowed_from_hour)
      or (w.interval_allowed_from_hour is null and w.interval_allowed_to_hour is not null and v_hour <= w.interval_allowed_to_hour)
    );

  update public.report_definitions r
  set server_queued_at = v_now
  where r.is_active = true
    and r.server_queued_at is null
    and lower(coalesce(r.config->'schedule'->>'enabled', 'false')) = 'true'
    and (
      (jsonb_typeof(coalesce(r.config->'schedule'->'recipient_user_ids', '[]'::jsonb)) = 'array' and jsonb_array_length(coalesce(r.config->'schedule'->'recipient_user_ids', '[]'::jsonb)) > 0)
      or (jsonb_typeof(coalesce(r.config->'schedule'->'bot_group_ids', '[]'::jsonb)) = 'array' and jsonb_array_length(coalesce(r.config->'schedule'->'bot_group_ids', '[]'::jsonb)) > 0)
    )
    and public.workflow_interval_scheduled_due_at(r.last_run_at, case when coalesce(r.config->'schedule'->>'interval_value', '') ~ '^[0-9]+$' then greatest(1, (r.config->'schedule'->>'interval_value')::integer) else 1 end, coalesce(nullif(r.config->'schedule'->>'interval_unit', ''), 'day'), null, null, null, null, v_now) is not null;

  update public.work_schedules s
  set notification_server_queued_at = v_now
  where s.is_active = true
    and s.status = 'active'
    and s.notification_server_queued_at is null
    and lower(coalesce(s.notification_schedule->>'enabled', 'false')) = 'true'
    and (
      (jsonb_typeof(coalesce(s.notification_schedule->'recipient_user_ids', '[]'::jsonb)) = 'array' and jsonb_array_length(coalesce(s.notification_schedule->'recipient_user_ids', '[]'::jsonb)) > 0)
      or (jsonb_typeof(coalesce(s.notification_schedule->'bot_group_ids', '[]'::jsonb)) = 'array' and jsonb_array_length(coalesce(s.notification_schedule->'bot_group_ids', '[]'::jsonb)) > 0)
    )
    and (s.effective_from is null or s.effective_from <= v_tehran::date)
    and (s.effective_to is null or s.effective_to >= v_tehran::date)
    and public.workflow_interval_scheduled_due_at(
      s.notification_last_run_at,
      case when coalesce(s.notification_schedule->>'interval_value', '') ~ '^[0-9]+$' then greatest(1, (s.notification_schedule->>'interval_value')::integer) else 1 end,
      case when lower(coalesce(s.notification_schedule->>'interval_unit', '')) = 'hour' then 'hour' else 'day' end,
      nullif(s.notification_schedule->>'interval_at', ''),
      nullif(s.notification_schedule->>'first_run_at', '')::timestamptz,
      case when lower(coalesce(s.notification_schedule->>'interval_unit', '')) = 'hour' and coalesce(s.notification_schedule->>'interval_at', '') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then split_part(s.notification_schedule->>'interval_at', ':', 2)::integer else null end,
      null,
      v_now
    ) is not null;
end;
$_$;


--
-- Name: read_call_contact_history(text, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_call_contact_history(p_module_id text, p_record_id uuid, p_section text, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
 v_org uuid:=public.current_org_id();v_context jsonb;v_contact jsonb;v_table text;v_module text;
 v_columns text[];v_where text;v_party_fk text;v_task_fk text;v_projects text;v_result jsonb;v_permissions jsonb;v_profile uuid;v_projection text;v_activity text;v_scope_sql text;
begin
 if v_org is null or p_module_id not in ('customers','suppliers','employees') or p_record_id is null then raise exception 'contact_scope_required';end if;
 v_context:=public.get_current_organization_context();v_permissions:=coalesce(v_context->'permissions','{}');
 if not(v_permissions?p_module_id) or coalesce((v_permissions->p_module_id->>'view')::boolean,true)=false then raise exception 'contact_access_denied';end if;
 execute format('select to_jsonb(c) from public.%I c where c.org_id=$1 and c.id=$2',p_module_id) into v_contact using v_org,p_record_id;
 if v_contact is null then raise exception 'contact_not_available';end if;
 if not public.call_contact_scope_visible(v_context,p_module_id,v_contact) then raise exception 'contact_scope_denied';end if;
 v_party_fk:=case p_module_id when 'customers' then 'customer_id' when 'suppliers' then 'supplier_id' else 'employee_id' end;
 v_task_fk:=case p_module_id when 'customers' then 'related_customer' when 'suppliers' then 'related_supplier' else 'assignee_id' end;
 v_profile:=nullif(v_contact->>'related_profile_id','')::uuid;
 v_projects:=case p_module_id
  when 'customers' then format('select p.id from public.projects p where p.org_id=%L and p.customer_id=%L',v_org,p_record_id)
  when 'suppliers' then format('select p.id from public.projects p where p.org_id=%L and (p.source_purchase_invoice_id in(select i.id from public.purchase_invoices i where i.org_id=%L and i.supplier_id=%L) or p.id in(select i.project_id from public.purchase_invoices i where i.org_id=%L and i.supplier_id=%L))',v_org,v_org,p_record_id,v_org,p_record_id)
  else format('select p.id from public.projects p where p.org_id=%L and p.owner_id=%L',v_org,v_profile) end;
 case p_section
 when 'invoices' then
  v_module:='invoices';v_table:='invoices';v_columns:=array['id','name','system_code','status','invoice_date','total_invoice_amount','total_received_amount','remaining_balance','payments','created_at','updated_at'];
  v_where:=case when p_module_id='customers' then format('t.customer_id=%L and not coalesce(t.is_deleted,false)',p_record_id) else 'false' end;
 when 'purchases' then
  v_module:='purchase_invoices';v_table:=v_module;v_columns:=array['id','name','system_code','status','invoice_date','total_invoice_amount','total_received_amount','remaining_balance','payments','created_at','updated_at'];
  v_where:=case when p_module_id='suppliers' then format('t.supplier_id=%L',p_record_id) else 'false' end;
 when 'projects' then
  v_module:='projects';v_table:=v_module;v_columns:=array['id','name','system_code','status','start_date','due_date','progress_percent','created_at','updated_at'];v_where:=format('t.id in(%s)',v_projects);
 when 'tasks' then
  v_module:='tasks';v_table:=v_module;v_columns:=array['id','name','system_code','status','due_date','assignee_id','project_id','created_at','updated_at'];
  v_where:=format('(t.%I=%L or (t.source_module_id=%L and t.source_record_id=%L))',v_task_fk,case when p_module_id='employees' then v_profile else p_record_id end,p_module_id,p_record_id);
  if v_permissions?'projects' and coalesce((v_permissions->'projects'->>'view')::boolean,true) then v_where:=v_where||format(' or t.project_id in(%s)',v_projects);end if;
 when 'processes' then
  v_module:='process_runs';v_table:=v_module;v_columns:=array['id','process_name','system_code','status','started_at','completed_at','module_id','record_id','created_at','updated_at'];v_where:=format('(t.module_id=%L and t.record_id=%L)',p_module_id,p_record_id);
  if v_permissions?'projects' and coalesce((v_permissions->'projects'->>'view')::boolean,true) then v_where:=v_where||format(' or (t.module_id=''projects'' and t.record_id in(%s))',v_projects);end if;
 when 'groups' then
  v_module:='counterparty_bot_groups';v_table:=v_module;v_columns:=array['id','group_title','channel_type','status','last_inbound_at','created_at','updated_at'];v_where:=format('t.%I=%L',v_party_fk,p_record_id);
 when 'sms' then
  v_module:='sms_delivery_reports';v_table:=v_module;v_columns:=array['id','title','message_text','status','direction','sent_at','created_at','updated_at'];
  v_where:=format('(t.related_module_id=%L and t.related_record_id=%L)',p_module_id,p_record_id);
  if p_module_id='customers' then v_where:=v_where||format(' or t.customer_id=%L',p_record_id);end if;
  v_where:=v_where||format(' or t.phone_number_id in(select l.phone_number_id from public.phone_number_links l where l.org_id=%L and l.entity_type=%L and l.entity_id=%L)',v_org,p_module_id,p_record_id);
 when 'calls' then
  v_module:='voip_call_reports';v_table:='voip_call_logs';v_columns:=array['id','title','direction','status','started_at','talk_seconds','created_at','updated_at'];
  v_where:=format('(t.related_module_id=%L and t.related_record_id=%L) or (t.module_id=%L and t.record_id=%L) or t.phone_number_id in(select l.phone_number_id from public.phone_number_links l where l.org_id=%L and l.entity_type=%L and l.entity_id=%L)',p_module_id,p_record_id,p_module_id,p_record_id,v_org,p_module_id,p_record_id);
 when 'email' then
  v_module:='email_delivery_reports';v_table:='email_messages';v_columns:=array['id','subject','status','direction','message_at','created_at'];v_where:=format('(t.related_module_id=%L and t.related_record_id=%L)',p_module_id,p_record_id);
 else raise exception 'invalid_contact_section';end case;
 if not(v_permissions?v_module) or coalesce((v_permissions->v_module->>'view')::boolean,true)=false then raise exception 'section_access_denied';end if;
 if not public.current_org_has_plan_module(p_module_id,false) or not public.current_org_has_plan_module(v_module,false) then raise exception 'call_context_plan_denied';end if;
 -- Field restrictions are applied before projection; no credentials/full row leaves this function.
 select array_agg(c) into v_columns from unnest(v_columns)c where c='id' or
  (coalesce(v_permissions->v_module->'fields'->c,'true'::jsonb)<>'false'::jsonb and coalesce(v_permissions->v_module->'fields'->c->>'view','true')<>'false');
 select 'jsonb_build_object('||string_agg(format('%L,t.%I',c,c),',')||')' into v_projection from unnest(v_columns)c;
 v_activity:=case when p_section='email' then 't.created_at' else 'greatest(t.updated_at,t.created_at)' end;
 v_scope_sql:=case when coalesce(nullif(v_permissions->v_module->>'record_scope',''),'all')='all'
  and coalesce(v_permissions->v_module->'view_conditions','{}'::jsonb) in ('{}'::jsonb,'null'::jsonb)
  then 'true' else 'public.call_contact_scope_visible($5,$6,to_jsonb(t))' end;
 execute format($q$
  with scoped as not materialized(select %s value,%s activity_at
    from public.%I t where t.org_id=$1 and (%s) and (%s)),
  page as(select value,activity_at from scoped order by activity_at desc nulls last,value->>'id' desc limit 20 offset $2)
  select jsonb_build_object('count',(select count(*) from scoped),'offset',$2,'hasMore',(select count(*) from scoped)>$2+20,
   'rows',coalesce((select jsonb_agg((select jsonb_object_agg(key,val) from jsonb_each(page.value)kv(key,val) where key=any($3)) order by activity_at desc nulls last,value->>'id' desc) from page),'[]'::jsonb),
   'summary',case when $4 then (select jsonb_build_object('total',count(*),'proforma',count(*) filter(where value->>'status'='proforma'),
     'settled',count(*) filter(where value->>'status'='settled'),
     'completedAndSettled',count(*) filter(where value->>'status'='completed' and (value->>'remaining_balance')::numeric=0),
     'outstanding',count(*) filter(where coalesce((value->>'remaining_balance')::numeric,0)>0 and value->>'status'<>'canceled')) from scoped) else null end)
 $q$,v_projection,v_activity,v_table,v_where,v_scope_sql) into v_result using v_org,greatest(coalesce(p_offset,0),0),v_columns,
 (p_section in('invoices','purchases') and 'status'=any(v_columns) and 'remaining_balance'=any(v_columns)),v_context,v_module;
 return v_result;
end;$_$;


--
-- Name: FUNCTION read_call_contact_history(p_module_id text, p_record_id uuid, p_section text, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.read_call_contact_history(p_module_id text, p_record_id uuid, p_section text, p_offset integer) IS 'Invoker/RLS scoped call-contact history; public caller ID is not authentication.';


--
-- Name: rebuild_communication_bot_thread_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_communication_bot_thread_summary(p_org_id uuid, p_bot_group_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_summary record;
begin
  if p_org_id is null or p_bot_group_id is null then
    return;
  end if;

  select
    count(*)::integer as message_count,
    (
      select m.id
      from public.counterparty_bot_messages m
      where m.org_id = p_org_id
        and m.bot_group_id = p_bot_group_id
      order by m.created_at desc, m.id desc
      limit 1
    ) as latest_message_id,
    (
      select m.created_at
      from public.counterparty_bot_messages m
      where m.org_id = p_org_id
        and m.bot_group_id = p_bot_group_id
      order by m.created_at desc, m.id desc
      limit 1
    ) as latest_message_at,
    (
      select coalesce(nullif(trim(m.content_text), ''), nullif(trim(m.file_name), ''), nullif(trim(m.message_type), ''))
      from public.counterparty_bot_messages m
      where m.org_id = p_org_id
        and m.bot_group_id = p_bot_group_id
      order by m.created_at desc, m.id desc
      limit 1
    ) as latest_message_preview,
    (
      select m.direction
      from public.counterparty_bot_messages m
      where m.org_id = p_org_id
        and m.bot_group_id = p_bot_group_id
      order by m.created_at desc, m.id desc
      limit 1
    ) as latest_message_direction,
    max(created_at) filter (where direction = 'inbound') as latest_inbound_at,
    max(created_at) filter (where direction = 'outbound') as latest_outbound_at
  into v_summary
  from public.counterparty_bot_messages
  where org_id = p_org_id
    and bot_group_id = p_bot_group_id;

  if coalesce(v_summary.message_count, 0) = 0 then
    delete from public.communication_bot_thread_summaries
    where org_id = p_org_id
      and bot_group_id = p_bot_group_id;
    return;
  end if;

  insert into public.communication_bot_thread_summaries (
    org_id,
    bot_group_id,
    message_count,
    latest_message_id,
    latest_message_at,
    latest_message_preview,
    latest_message_direction,
    latest_inbound_at,
    latest_outbound_at,
    updated_at
  )
  values (
    p_org_id,
    p_bot_group_id,
    coalesce(v_summary.message_count, 0),
    v_summary.latest_message_id,
    v_summary.latest_message_at,
    v_summary.latest_message_preview,
    v_summary.latest_message_direction,
    v_summary.latest_inbound_at,
    v_summary.latest_outbound_at,
    now()
  )
  on conflict (org_id, bot_group_id) do update
  set message_count = excluded.message_count,
      latest_message_id = excluded.latest_message_id,
      latest_message_at = excluded.latest_message_at,
      latest_message_preview = excluded.latest_message_preview,
      latest_message_direction = excluded.latest_message_direction,
      latest_inbound_at = excluded.latest_inbound_at,
      latest_outbound_at = excluded.latest_outbound_at,
      updated_at = now();
end;
$$;


--
-- Name: recalculate_attendance_daily_presence(uuid, uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_attendance_daily_presence(p_org_id uuid, p_employee_id uuid, p_related_profile_id uuid, p_assignee_id uuid, p_attendance_date date) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_presence_minutes integer;
  v_presence_hours numeric(10, 2);
  v_final_check_out_id uuid;
begin
  if p_attendance_date is null or p_org_id is null then
    return;
  end if;

  with scoped_logs as (
    select
      id,
      coalesce(log_type, 'check_in') as normalized_log_type,
      attendance_date,
      check_in_time,
      check_out_time,
      manual_check_in_time,
      manual_check_out_time,
      actual_check_in_time,
      actual_check_out_time,
      occurred_at
    from public.attendance_logs
    where attendance_date = p_attendance_date
      and org_id is not distinct from p_org_id
      and (
        (p_employee_id is not null and employee_id is not distinct from p_employee_id)
        or (
          p_employee_id is null
          and p_related_profile_id is not null
          and employee_id is null
          and related_profile_id is not distinct from p_related_profile_id
        )
        or (
          p_employee_id is null
          and p_related_profile_id is null
          and p_assignee_id is not null
          and employee_id is null
          and related_profile_id is null
          and assignee_id is not distinct from p_assignee_id
        )
        or (
          p_employee_id is null
          and p_related_profile_id is null
          and p_assignee_id is null
          and employee_id is null
          and related_profile_id is null
          and assignee_id is null
        )
      )
  ),
  normalized_events as (
    select
      id,
      normalized_log_type,
      case
        when normalized_log_type = 'check_in' then coalesce(
          manual_check_in_time,
          actual_check_in_time,
          public.combine_attendance_date_time(attendance_date, check_in_time),
          occurred_at
        )
        when normalized_log_type = 'check_out' then coalesce(
          manual_check_out_time,
          actual_check_out_time,
          public.combine_attendance_date_time(attendance_date, check_out_time),
          occurred_at
        )
        else null
      end as occurred_at
    from scoped_logs
  ),
  ordered_events as (
    select
      id,
      normalized_log_type,
      occurred_at,
      lead(id) over (order by occurred_at asc, id asc) as next_id,
      lead(normalized_log_type) over (order by occurred_at asc, id asc) as next_log_type,
      lead(occurred_at) over (order by occurred_at asc, id asc) as next_occurred_at
    from normalized_events
    where occurred_at is not null
  ),
  paired_intervals as (
    select
      id as check_in_id,
      next_id as check_out_id,
      occurred_at as check_in_at,
      next_occurred_at as check_out_at
    from ordered_events
    where normalized_log_type = 'check_in'
      and next_log_type = 'check_out'
      and next_occurred_at > occurred_at
      and next_occurred_at - occurred_at < interval '1 day'
  )
  select
    coalesce(sum(floor(extract(epoch from (check_out_at - check_in_at)) / 60)::integer), 0),
    (array_agg(check_out_id order by check_out_at desc, check_out_id desc))[1]
  into v_presence_minutes, v_final_check_out_id
  from paired_intervals;

  if v_final_check_out_id is null then
    v_presence_minutes := null;
    v_presence_hours := null;
  else
    v_presence_hours := round((v_presence_minutes::numeric / 60), 2);
  end if;

  -- مجموع روز فقط روی خروجِ پایانی نگهداری می‌شود تا در فهرست ترددها دوباره شمرده نشود.
  update public.attendance_logs
  set
    presence_minutes = case when id = v_final_check_out_id then v_presence_minutes else null end,
    presence_hours = case when id = v_final_check_out_id then v_presence_hours else null end,
    updated_at = now()
  where attendance_date = p_attendance_date
    and org_id is not distinct from p_org_id
    and (
      (p_employee_id is not null and employee_id is not distinct from p_employee_id)
      or (
        p_employee_id is null
        and p_related_profile_id is not null
        and employee_id is null
        and related_profile_id is not distinct from p_related_profile_id
      )
      or (
        p_employee_id is null
        and p_related_profile_id is null
        and p_assignee_id is not null
        and employee_id is null
        and related_profile_id is null
        and assignee_id is not distinct from p_assignee_id
      )
      or (
        p_employee_id is null
        and p_related_profile_id is null
        and p_assignee_id is null
        and employee_id is null
        and related_profile_id is null
        and assignee_id is null
      )
    )
    and (
      presence_minutes is distinct from case when id = v_final_check_out_id then v_presence_minutes else null end
      or presence_hours is distinct from case when id = v_final_check_out_id then v_presence_hours else null end
    );
end;
$$;


--
-- Name: recalculate_attendance_daily_presence_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_attendance_daily_presence_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if pg_trigger_depth() > 1 then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    perform public.recalculate_attendance_daily_presence(
      old.org_id,
      old.employee_id,
      old.related_profile_id,
      old.assignee_id,
      old.attendance_date
    );
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    perform public.recalculate_attendance_daily_presence(
      new.org_id,
      new.employee_id,
      new.related_profile_id,
      new.assignee_id,
      new.attendance_date
    );
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: recalculate_invoice_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_invoice_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_total numeric(18,2) := 0;
  v_paid numeric(18,2) := 0;
  v_item jsonb;
  v_amount numeric;
  v_status text;
  v_discount_type text;
  v_discount_value numeric(18,2);
  v_discount_amount numeric(18,2) := 0;
begin
  for v_item in select jsonb_array_elements(coalesce(new."invoiceItems", '[]'::jsonb)) loop
    begin
      v_amount := (v_item->>'total_price')::numeric;
      if v_amount is not null then
        v_total := v_total + v_amount;
      end if;
    exception when others then
      null;
    end;
  end loop;

  v_discount_type := lower(trim(coalesce(new.global_discount_type, 'amount')));
  v_discount_value := greatest(0, coalesce(new.global_discount_value, 0));
  if v_discount_type = 'percent' then
    v_discount_amount := least(v_total, round(v_total * v_discount_value / 100, 2));
  else
    v_discount_amount := least(v_total, v_discount_value);
  end if;
  v_total := greatest(0, v_total - v_discount_amount);

  for v_item in select jsonb_array_elements(coalesce(new.payments, '[]'::jsonb)) loop
    begin
      v_status := lower(trim(coalesce(v_item->>'status', '')));
      if (v_item ? 'status')
         and v_status <> ''
         and v_status not in ('received', 'paid', 'approved', 'cleared')
      then
        continue;
      end if;
      v_amount := abs((v_item->>'amount')::numeric);
      if v_amount is not null then
        v_paid := v_paid + v_amount;
      end if;
    exception when others then
      null;
    end;
  end loop;

  new.total_invoice_amount := v_total;
  new.total_received_amount := v_paid;
  new.remaining_balance := v_total - v_paid;
  return new;
end;
$$;


--
-- Name: recalculate_process_run_schedules(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_process_run_schedules(p_org_id uuid, p_process_run_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_current_org_id uuid;
  v_run public.process_runs%rowtype;
  v_stage public.process_run_stages%rowtype;
  v_reference_stage public.process_run_stages%rowtype;
  v_metadata jsonb;
  v_graph jsonb;
  v_anchor_type text;
  v_anchor_node_key text;
  v_reference_node_key text;
  v_parent_trigger_key text;
  v_anchor_at timestamptz;
  v_due_at timestamptz;
  v_duration_value numeric;
  v_duration_unit text;
  v_pass integer;
  v_stage_count integer;
  v_pass_changes integer;
  v_total_changes integer := 0;
begin
  v_current_org_id := public.current_org_id();
  if coalesce(auth.role(), '') <> 'service_role' then
    if auth.uid() is null
      or p_org_id is null
      or v_current_org_id is null
      or p_org_id <> v_current_org_id then
      raise exception 'دسترسی محاسبه موعدهای فرآیند وجود ندارد.' using errcode = '42501';
    end if;
  end if;

  -- Updates belonging to the same process run are serialized, while different
  -- organizations/runs can still be recalculated concurrently.
  perform pg_advisory_xact_lock(hashtextextended(p_process_run_id::text, 0));

  select *
  into v_run
  from public.process_runs r
  where r.id = p_process_run_id
    and r.org_id = p_org_id;

  if v_run.id is null then
    return 0;
  end if;

  select count(*)::integer
  into v_stage_count
  from public.process_run_stages s
  where s.process_run_id = p_process_run_id;

  -- Repeated passes cover reverse and cross-lane dependencies as well as
  -- ordinary forward chains. Stable values stop the loop immediately.
  for v_pass in 1..greatest(v_stage_count, 1) loop
    v_pass_changes := 0;

    for v_stage in
      select s.*
      from public.process_run_stages s
      where s.process_run_id = p_process_run_id
      order by coalesce(s.process_lane_key, s.metadata ->> 'process_lane_key', 'lane_1'),
               s.sort_order,
               s.created_at
    loop
      v_metadata := coalesce(v_stage.metadata, '{}'::jsonb);
      -- موعد دستی متعلق به کاربر است و نباید توسط dependency engine بازنویسی شود.
      if coalesce(v_metadata ->> 'due_schedule_mode', 'system') = 'manual' then
        continue;
      end if;
      v_graph := coalesce(v_metadata -> 'process_graph', '{}'::jsonb);
      v_anchor_type := coalesce(
        nullif(v_metadata ->> 'due_anchor_type', ''),
        case coalesce(v_metadata ->> 'duration_from', '')
          when 'project_start' then 'process_start'
          when 'previous_stage_end' then 'previous_stage_due'
          else null
        end,
        'process_start'
      );
      v_anchor_node_key := nullif(v_metadata ->> 'due_anchor_stage_node_key', '');
      v_reference_node_key := null;
      v_parent_trigger_key := null;
      v_anchor_at := null;

      if v_anchor_type like 'specific_stage_%' then
        v_reference_node_key := v_anchor_node_key;
      elsif v_anchor_type like 'previous_stage_%' then
        select coalesce(s.process_node_key, s.metadata ->> 'process_node_key')
        into v_reference_node_key
        from public.process_run_stages s
        where s.process_run_id = p_process_run_id
          and coalesce(s.process_lane_key, s.metadata ->> 'process_lane_key', 'lane_1')
            = coalesce(v_stage.process_lane_key, v_metadata ->> 'process_lane_key', 'lane_1')
          and s.sort_order < v_stage.sort_order
        order by s.sort_order desc, s.created_at desc
        limit 1;

        if v_reference_node_key is null and jsonb_typeof(v_graph -> 'lanes') = 'array' then
          select nullif(lane ->> 'parentTriggerKey', '')
          into v_parent_trigger_key
          from jsonb_array_elements(v_graph -> 'lanes') lane
          where lane ->> 'key' = coalesce(v_stage.process_lane_key, v_metadata ->> 'process_lane_key', 'lane_1')
          limit 1;

          if v_parent_trigger_key is not null and jsonb_typeof(v_graph -> 'triggers') = 'array' then
            select nullif(trigger_row ->> 'sourceNodeKey', '')
            into v_reference_node_key
            from jsonb_array_elements(v_graph -> 'triggers') trigger_row
            where trigger_row ->> 'key' = v_parent_trigger_key
            limit 1;
          end if;
        end if;
      elsif v_anchor_type like 'next_stage_%' then
        select coalesce(s.process_node_key, s.metadata ->> 'process_node_key')
        into v_reference_node_key
        from public.process_run_stages s
        where s.process_run_id = p_process_run_id
          and coalesce(s.process_lane_key, s.metadata ->> 'process_lane_key', 'lane_1')
            = coalesce(v_stage.process_lane_key, v_metadata ->> 'process_lane_key', 'lane_1')
          and s.sort_order > v_stage.sort_order
        order by s.sort_order, s.created_at
        limit 1;

        if v_reference_node_key is null and jsonb_typeof(v_graph -> 'triggers') = 'array' then
          select coalesce(target_stage.process_node_key, target_stage.metadata ->> 'process_node_key')
          into v_reference_node_key
          from jsonb_array_elements(v_graph -> 'triggers') trigger_row
          cross join lateral jsonb_array_elements_text(
            case when jsonb_typeof(trigger_row -> 'targetLaneKeys') = 'array'
              then trigger_row -> 'targetLaneKeys'
              else '[]'::jsonb
            end
          ) target_lane(lane_key)
          join lateral (
            select candidate.*
            from public.process_run_stages candidate
            where candidate.process_run_id = p_process_run_id
              and coalesce(candidate.process_lane_key, candidate.metadata ->> 'process_lane_key', 'lane_1') = target_lane.lane_key
            order by candidate.sort_order, candidate.created_at
            limit 1
          ) target_stage on true
          where trigger_row ->> 'sourceNodeKey' = coalesce(v_stage.process_node_key, v_metadata ->> 'process_node_key')
          limit 1;
        end if;
      end if;

      -- SELECT INTO clears every field when no reference exists; this prevents
      -- a reference from the previous loop iteration leaking into this stage.
      select s.*
      into v_reference_stage
      from public.process_run_stages s
      where s.process_run_id = p_process_run_id
        and coalesce(s.process_node_key, s.metadata ->> 'process_node_key') = v_reference_node_key
      limit 1;

      if v_anchor_type = 'process_start' then
        v_anchor_at := coalesce(v_run.started_at, v_run.created_at);
      elsif v_anchor_type = 'current_stage_created' then
        select coalesce(t.created_at, v_stage.created_at)
        into v_anchor_at
        from (select 1) seed
        left join public.tasks t on t.id = v_stage.task_id;
      elsif v_anchor_type in ('previous_stage_created', 'next_stage_created', 'specific_stage_created') then
        select coalesce(t.created_at, v_reference_stage.created_at)
        into v_anchor_at
        from (select 1) seed
        left join public.tasks t on t.id = v_reference_stage.task_id;
      elsif v_anchor_type in ('previous_stage_start', 'next_stage_start', 'specific_stage_start') then
        select coalesce(t.actual_start_at, t.start_date, v_reference_stage.started_at)
        into v_anchor_at
        from (select 1) seed
        left join public.tasks t on t.id = v_reference_stage.task_id;
      elsif v_anchor_type in ('previous_stage_due', 'next_stage_due', 'specific_stage_due') then
        select coalesce(t.due_date, v_reference_stage.planned_due_at)
        into v_anchor_at
        from (select 1) seed
        left join public.tasks t on t.id = v_reference_stage.task_id;
      elsif v_anchor_type in ('previous_stage_completed', 'next_stage_completed', 'specific_stage_completed') then
        select coalesce(t.actual_end_at, t.completed_at, v_reference_stage.completed_at)
        into v_anchor_at
        from (select 1) seed
        left join public.tasks t on t.id = v_reference_stage.task_id;
      end if;

      v_duration_value := case
        when coalesce(v_metadata ->> 'duration_value', '') ~ '^\s*\d+(\.\d+)?\s*$'
          then greatest(0, (v_metadata ->> 'duration_value')::numeric)
        else 0
      end;
      v_duration_unit := case when v_metadata ->> 'duration_unit' = 'hour' then 'hour' else 'day' end;
      v_due_at := case
        when v_anchor_at is null then null
        when v_duration_value <= 0 then v_anchor_at
        when v_duration_unit = 'hour' then v_anchor_at + make_interval(secs => (v_duration_value * 3600)::double precision)
        else v_anchor_at + make_interval(secs => (v_duration_value * 86400)::double precision)
      end;

      if v_stage.planned_due_at is distinct from v_due_at then
        update public.process_run_stages
        set planned_due_at = v_due_at,
            updated_at = now()
        where id = v_stage.id;
        v_pass_changes := v_pass_changes + 1;
        v_total_changes := v_total_changes + 1;
      end if;

      if v_stage.task_id is not null then
        update public.tasks t
        set due_date = v_due_at,
            schedule_variance_hours = case
              when coalesce(t.actual_end_at, t.completed_at) is null or v_due_at is null then null
              else extract(epoch from (coalesce(t.actual_end_at, t.completed_at) - v_due_at)) / 3600
            end,
            updated_at = now()
        where t.id = v_stage.task_id
          and t.org_id = p_org_id
          and t.due_date is distinct from v_due_at;
        if found then
          v_pass_changes := v_pass_changes + 1;
          v_total_changes := v_total_changes + 1;
        end if;
      end if;
    end loop;

    exit when v_pass_changes = 0;
  end loop;

  return v_total_changes;
end;
$_$;


--
-- Name: recalculate_process_schedule_from_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_process_schedule_from_run() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if pg_trigger_depth() > 1 or new.started_at is not distinct from old.started_at then
    return new;
  end if;
  perform public.recalculate_process_run_schedules(new.org_id, new.id);
  return new;
end;
$$;


--
-- Name: recalculate_process_schedule_from_stage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_process_schedule_from_stage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;
  if tg_op = 'UPDATE' and
     new.metadata is not distinct from old.metadata and
     new.sort_order is not distinct from old.sort_order and
     new.process_node_key is not distinct from old.process_node_key and
     new.process_lane_key is not distinct from old.process_lane_key and
     new.task_id is not distinct from old.task_id then
    return new;
  end if;
  select r.org_id into v_org_id from public.process_runs r where r.id = new.process_run_id;
  if v_org_id is not null then
    perform public.recalculate_process_run_schedules(v_org_id, new.process_run_id);
  end if;
  return new;
end;
$$;


--
-- Name: recalculate_process_schedule_from_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_process_schedule_from_task() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if pg_trigger_depth() > 1 or new.process_run_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and
     new.due_date is not distinct from old.due_date and
     new.start_date is not distinct from old.start_date and
     new.actual_start_at is not distinct from old.actual_start_at and
     new.completed_at is not distinct from old.completed_at and
     new.actual_end_at is not distinct from old.actual_end_at and
     new.process_node_key is not distinct from old.process_node_key and
     new.process_lane_key is not distinct from old.process_lane_key and
     new.sort_order is not distinct from old.sort_order then
    return new;
  end if;
  perform public.recalculate_process_run_schedules(new.org_id, new.process_run_id);
  return new;
end;
$$;


--
-- Name: receive_local_installation_report(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_local_installation_report(p_id uuid, p_token text, p_report jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare i public.saas_local_installations; safe jsonb;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception using errcode='42501',message='Service access required'; end if;
 select * into i from public.saas_local_installations where id=p_id for update;
 if not found or not i.telemetry_enabled or not exists(select 1 from public.saas_local_credentials
  where installation_id=i.id and telemetry_token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') and (expires_at is null or expires_at>now())) then
  raise exception using errcode='42501',message='Report credential is not valid'; end if;
 if exists(select 1 from public.saas_local_reports where installation_id=i.id and source='telemetry' and received_at>now()-interval '1 minute') then return; end if;
 safe:=public.local_installation_safe_report(p_report);
 insert into public.saas_local_reports(org_id,installation_id,report,source) values(i.org_id,i.id,safe,'telemetry');
 update public.saas_local_installations set last_report_at=now() where id=i.id;
end $$;


--
-- Name: reconcile_customer_club_credit(text, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_customer_club_credit(p_entity_type text, p_entity_id uuid, p_target_amount numeric) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_current numeric(18,2) := 0;
  v_delta numeric(18,2);
  v_module text := lower(trim(coalesce(p_entity_type, '')));
begin
  if v_org_id is null or v_module not in ('customer', 'supplier', 'employee') or p_entity_id is null or p_target_amount is null then
    raise exception 'مقدار نهایی اعتبار نامعتبر است';
  end if;
  select coalesce(sum(case when l.entry_type = 'debit' then -l.amount else l.amount end), 0)
    into v_current from public.customer_loyalty_ledger l
    join public.get_customer_club_credit_scope(v_org_id, v_module, p_entity_id) s on s.entity_type = 'customer' and s.entity_id = l.customer_id
    where l.org_id = v_org_id;
  select v_current + coalesce(sum(case when e.entry_type = 'debit' then -e.amount else e.amount end), 0)
    into v_current from public.customer_club_entity_credits e
    join public.get_customer_club_credit_scope(v_org_id, v_module, p_entity_id) s on s.entity_type = e.recipient_module_id and s.entity_id = e.recipient_record_id
    where e.org_id = v_org_id;
  v_delta := p_target_amount - v_current;
  if v_delta <> 0 then
    perform public.record_customer_club_entity_credit(
      case v_module when 'customer' then 'customers' when 'supplier' then 'suppliers' else 'employees' end,
      p_entity_id, null, case when v_delta < 0 then 'debit' else 'adjustment' end,
      'link_reconciliation', null, null, abs(v_delta), current_date,
      'link_reconciliation:' || gen_random_uuid()::text, 'هماهنگ‌سازی اعتبار باشگاه مشتریان',
      jsonb_build_object('target_amount', p_target_amount)
    );
  else
    perform public.sync_customer_club_credit_group(v_module, p_entity_id);
  end if;
  return public.sync_customer_club_credit_group(v_module, p_entity_id);
end;
$$;


--
-- Name: reconcile_workflow_interval_execution_reports(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_workflow_interval_execution_reports(p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_reconciled_count integer := 0;
begin
  with candidate_runs as (
    select
      j.workflow_id,
      j.org_id,
      j.module_id,
      j.record_id,
      j.scheduled_due_at,
      min(j.created_at) as created_at,
      max(j.completed_at) as completed_at
    from public.workflow_interval_jobs j
    where j.job_kind = 'workflow_action'
      and j.workflow_id is not null
      and j.module_id is not null
      and j.record_id is not null
      and j.report_logged_at is null
      and j.status in ('succeeded', 'failed', 'skipped')
      and exists (
        select 1
        from public.workflow_interval_jobs terminal_job
        where terminal_job.job_kind = 'workflow_action'
          and terminal_job.workflow_id = j.workflow_id
          and terminal_job.module_id = j.module_id
          and terminal_job.record_id = j.record_id
          and terminal_job.scheduled_due_at = j.scheduled_due_at
          and terminal_job.is_terminal_action = true
          and terminal_job.status in ('succeeded', 'failed', 'skipped')
      )
      and not exists (
        select 1
        from public.workflow_interval_jobs pending_job
        where pending_job.job_kind = 'workflow_action'
          and pending_job.workflow_id = j.workflow_id
          and pending_job.module_id = j.module_id
          and pending_job.record_id = j.record_id
          and pending_job.scheduled_due_at = j.scheduled_due_at
          and pending_job.status in ('pending', 'running')
      )
    group by j.workflow_id, j.org_id, j.module_id, j.record_id, j.scheduled_due_at
    order by max(j.completed_at) asc nulls last
    limit least(greatest(coalesce(p_limit, 500), 1), 5000)
  ), run_details as (
    select
      c.*,
      ('report|' || c.workflow_id::text || '|' || c.scheduled_due_at::text || '|' || c.module_id || '|' || c.record_id::text) as execution_run_key,
      coalesce(w.name, nullif(sample.payload #>> '{workflow,name}', ''), 'گردش کار') as workflow_name,
      coalesce(
        nullif(sample.payload #>> '{record,system_code}', ''),
        nullif(sample.payload #>> '{record,name}', ''),
        nullif(sample.payload #>> '{record,title}', ''),
        nullif(sample.payload #>> '{record,full_name}', ''),
        nullif(sample.payload #>> '{record,business_name}', ''),
        '[بدون عنوان]'
      ) as record_title,
      coalesce(nullif(sample.payload #>> '{workflow,execution_mode}', ''), 'first_match') as execution_mode,
      coalesce(jsonb_agg(
        jsonb_build_object(
          'type', coalesce(nullif(j.payload #>> '{action,type}', ''), ''),
          'status', coalesce(nullif(j.result #>> '{action_result,status}', ''), j.status),
          'message', coalesce(nullif(j.result #>> '{action_result,message}', ''), nullif(j.last_error, ''))
        ) order by j.action_index
      ) filter (where j.id is not null), '[]'::jsonb) as action_results,
      count(j.id)::integer as action_count,
      coalesce(bool_or(coalesce(nullif(j.result #>> '{action_result,status}', ''), j.status) = 'failed'), false) as has_failed_action,
      coalesce(bool_or(coalesce(nullif(j.result #>> '{action_result,status}', ''), j.status) = 'success'), false) as has_successful_action,
      string_agg(
        coalesce(nullif(j.result #>> '{action_result,message}', ''), nullif(j.last_error, '')),
        ' | ' order by j.action_index
      ) filter (where coalesce(nullif(j.result #>> '{action_result,status}', ''), j.status) = 'failed') as error_message,
      coalesce(max(j.payload ->> 'actor_user_id') filter (where j.payload ? 'actor_user_id'), null) as actor_id
    from candidate_runs c
    join public.workflow_interval_jobs j
      on j.job_kind = 'workflow_action'
     and j.workflow_id = c.workflow_id
     and j.module_id = c.module_id
     and j.record_id = c.record_id
     and j.scheduled_due_at = c.scheduled_due_at
    left join public.workflows w on w.id = c.workflow_id and w.org_id = c.org_id
    left join lateral (
      select first_job.payload
      from public.workflow_interval_jobs first_job
      where first_job.job_kind = 'workflow_action'
        and first_job.workflow_id = c.workflow_id
        and first_job.module_id = c.module_id
        and first_job.record_id = c.record_id
        and first_job.scheduled_due_at = c.scheduled_due_at
      order by first_job.action_index asc nulls last, first_job.created_at asc
      limit 1
    ) sample on true
    group by c.workflow_id, c.org_id, c.module_id, c.record_id, c.scheduled_due_at,
      c.created_at, c.completed_at, w.name, sample.payload
  ), inserted_logs as (
    insert into public.workflow_logs (
      workflow_id, org_id, module_id, record_id, run_type, status, message,
      details, execution_run_key, created_at
    )
    select
      d.workflow_id,
      d.org_id,
      d.module_id,
      d.record_id,
      'scheduled',
      case when d.has_failed_action then 'failed' when d.has_successful_action then 'success' else 'skipped' end,
      d.error_message,
      jsonb_build_object(
        'workflow_name', d.workflow_name,
        'record_title', d.record_title,
        'execution_mode', d.execution_mode,
        'scheduled_due_at', d.scheduled_due_at,
        'action_count', d.action_count,
        'action_results', d.action_results,
        'execution_run_key', d.execution_run_key,
        'execution_queue', 'v2',
        'queue_reconciled', true,
        'actor_id', d.actor_id,
        'runner_build', 'database-report-reconciliation'
      ),
      d.execution_run_key,
      coalesce(d.completed_at, d.created_at, now())
    from run_details d
    on conflict (execution_run_key) where execution_run_key is not null do nothing
    returning execution_run_key
  ), marked_jobs as (
    update public.workflow_interval_jobs j
    set report_logged_at = now(), updated_at = now()
    from run_details d
    where j.job_kind = 'workflow_action'
      and j.workflow_id = d.workflow_id
      and j.module_id = d.module_id
      and j.record_id = d.record_id
      and j.scheduled_due_at = d.scheduled_due_at
      and exists (
        select 1
        from public.workflow_logs l
        where l.execution_run_key = d.execution_run_key
      )
    returning j.id
  )
  select count(*) into v_reconciled_count from inserted_logs;

  return v_reconciled_count;
end;
$$;


--
-- Name: record_customer_club_entity_credit(text, uuid, uuid, text, text, text, uuid, numeric, date, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_customer_club_entity_credit(p_recipient_module_id text, p_recipient_record_id uuid, p_rule_id uuid, p_entry_type text, p_source_type text, p_source_table text, p_source_record_id uuid, p_amount numeric, p_effective_date date, p_idempotency_key text, p_description text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_id uuid;
  v_module text := lower(trim(coalesce(p_recipient_module_id, '')));
  v_exists boolean := false;
begin
  if v_org_id is null or v_module not in ('customers', 'suppliers', 'employees') or p_recipient_record_id is null
    or coalesce(p_amount, 0) < 0 or nullif(trim(coalesce(p_idempotency_key, '')), '') is null then
    raise exception 'اعتبار باشگاه مشتریان نامعتبر است';
  end if;
  if v_module = 'customers' then select exists(select 1 from public.customers where id = p_recipient_record_id and org_id = v_org_id) into v_exists;
  elsif v_module = 'suppliers' then select exists(select 1 from public.suppliers where id = p_recipient_record_id and org_id = v_org_id) into v_exists;
  else select exists(select 1 from public.employees where id = p_recipient_record_id and org_id = v_org_id) into v_exists;
  end if;
  if not v_exists then raise exception 'رکورد دریافت‌کنندهٔ اعتبار یافت نشد'; end if;

  insert into public.customer_club_entity_credits (
    org_id, recipient_module_id, recipient_record_id, rule_id, entry_type, source_type, source_table,
    source_record_id, amount, effective_date, idempotency_key, description, metadata, created_by
  ) values (
    v_org_id, v_module, p_recipient_record_id, p_rule_id, coalesce(nullif(trim(p_entry_type), ''), 'credit'),
    p_source_type, p_source_table, p_source_record_id, p_amount, coalesce(p_effective_date, current_date),
    trim(p_idempotency_key), p_description, coalesce(p_metadata, '{}'::jsonb), auth.uid()
  ) on conflict (org_id, idempotency_key) do update set
    amount = excluded.amount, effective_date = excluded.effective_date, description = excluded.description,
    metadata = excluded.metadata, updated_at = now()
  returning id into v_id;
  perform public.sync_customer_club_credit_group(case v_module when 'customers' then 'customer' when 'suppliers' then 'supplier' else 'employee' end, p_recipient_record_id);
  return v_id;
end;
$$;


--
-- Name: record_lock_target_exists(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_lock_target_exists(p_module_id text, p_record_id uuid, p_org_id uuid DEFAULT public.current_org_id()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_table_name text := public.resolve_record_lock_table_name(p_module_id);
  v_table_regclass regclass;
  v_exists boolean := false;
begin
  if p_org_id is null or p_record_id is null or btrim(coalesce(v_table_name, '')) = '' then
    return false;
  end if;

  select to_regclass(format('public.%I', v_table_name)) into v_table_regclass;
  if v_table_regclass is null then
    return false;
  end if;

  execute format('select exists (select 1 from public.%I where id = $1 and org_id = $2)', v_table_name)
    into v_exists
    using p_record_id, p_org_id;

  return coalesce(v_exists, false);
exception
  when undefined_column then
    execute format('select exists (select 1 from public.%I where id = $1)', v_table_name)
      into v_exists
      using p_record_id;
    return coalesce(v_exists, false);
  when others then
    return false;
end;
$_$;


--
-- Name: record_lock_user_can(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_lock_user_can(p_module_id text, p_action text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_module_id text := btrim(coalesce(p_module_id, ''));
  v_action text := btrim(coalesce(p_action, ''));
  v_permission_key text;
  v_role text;
  v_permissions jsonb := '{}'::jsonb;
begin
  if v_org_id is null or v_user_id is null or v_module_id = '' then
    return false;
  end if;

  v_permission_key := case v_action
    when 'unlock' then '__record_unlock'
    else '__record_lock'
  end;

  select p.role, coalesce(r.permissions, '{}'::jsonb)
    into v_role, v_permissions
  from public.profiles p
  left join public.org_roles r
    on r.id = p.role_id
   and r.org_id = p.org_id
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if lower(coalesce(v_role, '')) in ('super_admin', 'admin') then
    return true;
  end if;

  return coalesce((v_permissions -> v_module_id ->> 'view')::boolean, true) = true
    and coalesce((v_permissions -> v_module_id -> 'fields' ->> v_permission_key)::boolean, false) = true;
exception
  when others then
    return false;
end;
$$;


--
-- Name: record_story_view(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_story_view(p_story_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id     uuid := auth.uid();
  v_current_org uuid := public.current_org_id();
  v_role_id     uuid;
  v_story       record;
begin
  if v_user_id is null or v_current_org is null or p_story_id is null then
    return;
  end if;

  select p.role_id
    into v_role_id
  from public.profiles p
  where p.id = v_user_id
    and p.org_id = v_current_org
  limit 1;

  select s.id, s.org_id, s.is_saas_wide
    into v_story
  from public.org_stories s
  where s.id = p_story_id
    and s.is_active = true
    and s.published_at <= now()
    and (s.expires_at is null or s.expires_at > now())
    and (
      (
        s.org_id = v_current_org
        and (
          s.creator_id = v_user_id
          or s.is_org_wide = true
          or v_user_id = any(s.viewer_user_ids)
          or (v_role_id is not null and v_role_id = any(s.viewer_role_ids))
        )
      )
      or (
        s.is_saas_wide = true
        and (
          s.is_saas_admins_only = false
          or public.current_user_is_saas_org_admin()
        )
      )
    )
  limit 1;

  if v_story.id is null then
    return;
  end if;

  insert into public.org_story_views (org_id, story_id, user_id)
  values (v_current_org, p_story_id, v_user_id)
  on conflict (story_id, user_id) do nothing;

  if found then
    update public.org_stories
    set view_count = view_count + 1, updated_at = now()
    where id = p_story_id;
  end if;
end;
$$;


--
-- Name: recycle_bin_record_title(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recycle_bin_record_title(p_snapshot jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select nullif(
    trim(
      coalesce(
        p_snapshot->>'name',
        p_snapshot->>'stage_name',
        p_snapshot->>'title',
        p_snapshot->>'business_name',
        p_snapshot->>'full_name',
        concat_ws(' ', p_snapshot->>'first_name', p_snapshot->>'last_name'),
        p_snapshot->>'subject',
        p_snapshot->>'system_code',
        p_snapshot->>'manual_code',
        p_snapshot->>'code',
        p_snapshot->>'id'
      )
    ),
    ''
  );
$$;


--
-- Name: recycle_bin_strip_payments(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recycle_bin_strip_payments(p_module_id text, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  v_module_id text := trim(coalesce(p_module_id, ''));
  v_snapshot jsonb := coalesce(p_snapshot, '{}'::jsonb);
  v_total numeric := coalesce(nullif(v_snapshot->>'total_invoice_amount', '')::numeric, 0);
  v_amount numeric := coalesce(nullif(v_snapshot->>'amount', '')::numeric, 0);
  v_net_amount numeric := coalesce(nullif(v_snapshot->>'net_amount', '')::numeric, 0);
begin
  v_snapshot := v_snapshot || jsonb_build_object('payments', '[]'::jsonb);

  if v_module_id in ('invoices', 'purchase_invoices', 'sales_return_invoices', 'purchase_return_invoices') then
    v_snapshot := v_snapshot
      || jsonb_build_object(
        'total_received_amount', 0,
        'remaining_balance', case when v_total > 0 then v_total else 0 end
      );
  elsif v_module_id = 'expense_documents' then
    v_snapshot := v_snapshot
      || jsonb_build_object(
        'paid_amount', 0,
        'remaining_amount', case when v_total > 0 then v_total else coalesce(nullif(v_snapshot->>'total_amount', '')::numeric, 0) end
      );
  elsif v_module_id = 'employee_advances' then
    v_snapshot := v_snapshot
      || jsonb_build_object(
        'paid_amount', 0,
        'remaining_amount', case when v_amount > 0 then v_amount else 0 end
      );
  elsif v_module_id = 'payroll_slips' then
    v_snapshot := v_snapshot
      || jsonb_build_object(
        'paid_amount', 0,
        'remaining_amount', case when v_net_amount > 0 then v_net_amount else 0 end
      );
  end if;

  return v_snapshot;
end;
$$;


--
-- Name: recycle_bin_strip_process_fields(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recycle_bin_strip_process_fields(p_snapshot jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  select coalesce(p_snapshot, '{}'::jsonb)
    || jsonb_build_object(
      'execution_process_draft', '[]'::jsonb,
      'marketing_process_draft', '[]'::jsonb,
      'production_stages_draft', '[]'::jsonb,
      'process_draft', '[]'::jsonb,
      'sub_process_draft', '[]'::jsonb,
      'process_template_id', null
    );
$$;


--
-- Name: recycle_cash_bank_operations_before_financial_source_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recycle_cash_bank_operations_before_financial_source_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_operation_ids uuid[];
begin
  select coalesce(array_agg(operation.id), array[]::uuid[])
  into v_operation_ids
  from public.cash_bank_operations operation
  where operation.org_id = old.org_id
    and (
      (tg_table_name = 'invoices' and operation.sales_invoice_id = old.id)
      or (tg_table_name = 'purchase_invoices' and operation.purchase_invoice_id = old.id)
      or (tg_table_name = 'expense_documents' and operation.expense_document_id = old.id)
      or (tg_table_name = 'employee_advances' and operation.employee_advance_id = old.id)
      or (tg_table_name = 'payroll_slips' and operation.payroll_slip_id = old.id)
      or (
        case tg_table_name
          when 'invoices' then operation.sales_invoice_id is null
          when 'purchase_invoices' then operation.purchase_invoice_id is null
          when 'expense_documents' then operation.expense_document_id is null
          when 'employee_advances' then operation.employee_advance_id is null
          when 'payroll_slips' then operation.payroll_slip_id is null
          else false
        end
        and trim(coalesce(operation.metadata ->> 'source_table', '')) = tg_table_name
        and trim(coalesce(operation.metadata ->> 'source_record_id', '')) = old.id::text
      )
    );

  if coalesce(array_length(v_operation_ids, 1), 0) > 0 then
    perform public.move_records_to_recycle_bin(
      'cash_bank_operations',
      'cash_bank_operations',
      v_operation_ids,
      null,
      null,
      old.org_id
    );
  end if;

  return old;
end;
$$;


--
-- Name: refresh_global_search_index(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_global_search_index(p_modules text[] DEFAULT NULL::text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_module text;
  v_inserted integer := 0;
  v_row_count integer := 0;
begin
  if v_org_id is null then
    return 0;
  end if;

  for v_module in
    select registry.module_id
    from public.global_search_module_registry registry
    where registry.is_enabled
      and (p_modules is null or registry.module_id = any(p_modules))
      and to_regclass(format('public.%I', registry.module_id)) is not null
      and exists (
        select 1 from information_schema.columns columns
        where columns.table_schema = 'public' and columns.table_name = registry.module_id and columns.column_name = 'org_id'
      )
  loop
    delete from public.global_search_documents
    where org_id = v_org_id
      and module_id = v_module;

    execute format(
      'select public.global_search_upsert_document(%L, to_jsonb(source_row)) from public.%I source_row where source_row.org_id = $1',
      v_module,
      v_module
    ) using v_org_id;
    get diagnostics v_row_count = row_count;
    v_inserted := v_inserted + coalesce(v_row_count, 0);
  end loop;

  return v_inserted;
end;
$_$;


--
-- Name: refresh_journal_entry_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_journal_entry_totals(p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_total_debit numeric(18,2);
  v_total_credit numeric(18,2);
begin
  select
    coalesce(sum(l.debit), 0)::numeric(18,2),
    coalesce(sum(l.credit), 0)::numeric(18,2)
  into v_total_debit, v_total_credit
  from public.journal_lines l
  where l.entry_id = p_entry_id;

  update public.journal_entries e
  set total_debit = v_total_debit,
      total_credit = v_total_credit,
      updated_at = now()
  where e.id = p_entry_id;
end;
$$;


--
-- Name: refresh_saas_subscription_entitlement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_saas_subscription_entitlement(p_subscription_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare subscription_row public.saas_recurring_subscriptions%rowtype; entry record; item_state text;
begin
  select * into subscription_row from public.saas_recurring_subscriptions where id = p_subscription_id;
  if subscription_row.id is null or subscription_row.item_kind = 'plan' then return; end if;
  item_state := case when subscription_row.status in ('active', 'grace') then 'enabled' else 'expired' end;
  if subscription_row.item_kind = 'bundle' then
    for entry in select value from jsonb_array_elements(coalesce(subscription_row.metadata -> 'included_items', '[]'::jsonb)) loop
      update public.saas_org_entitlements set state=item_state, quantity=coalesce((entry.value ->> 'quantity')::numeric,1), expires_at=subscription_row.current_period_ends_at, metadata=metadata || jsonb_build_object('subscription_id',subscription_row.id), updated_at=now()
      where org_id=subscription_row.org_id and source='subscription' and item_kind=entry.value ->> 'item_kind' and entitlement_code=entry.value ->> 'entitlement_code'
        and metadata ->> 'subscription_id' = subscription_row.id::text;
      if not found then
        insert into public.saas_org_entitlements(org_id,item_kind,entitlement_code,quantity,state,source,expires_at,metadata)
        values(subscription_row.org_id,entry.value ->> 'item_kind',entry.value ->> 'entitlement_code',coalesce((entry.value ->> 'quantity')::numeric,1),item_state,'subscription',subscription_row.current_period_ends_at,jsonb_build_object('subscription_id',subscription_row.id));
      end if;
    end loop;
    return;
  end if;
  update public.saas_org_entitlements set state=item_state, quantity=subscription_row.quantity, expires_at=subscription_row.current_period_ends_at, metadata=metadata || jsonb_build_object('subscription_id',subscription_row.id), updated_at=now()
  where org_id=subscription_row.org_id and source='subscription' and item_kind=subscription_row.item_kind and entitlement_code=subscription_row.entitlement_code
    and metadata ->> 'subscription_id' = subscription_row.id::text;
  if not found then insert into public.saas_org_entitlements(org_id,item_kind,entitlement_code,quantity,state,source,expires_at,metadata) values(subscription_row.org_id,subscription_row.item_kind,subscription_row.entitlement_code,subscription_row.quantity,item_state,'subscription',subscription_row.current_period_ends_at,jsonb_build_object('subscription_id',subscription_row.id)); end if;
end; $$;


--
-- Name: refresh_seniority_service_rates_after_annual_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_seniority_service_rates_after_annual_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_year integer;
begin
  for v_year in
    select rate.persian_year
    from public.saas_seniority_annual_rates rate
    where rate.persian_year >= new.persian_year
    order by rate.persian_year
  loop
    perform public.refresh_seniority_service_rates_for_year(v_year);
  end loop;
  return new;
end;
$$;


--
-- Name: refresh_seniority_service_rates_for_year(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_seniority_service_rates_for_year(p_persian_year integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_daily_rate numeric;
  v_prior_multiplier numeric;
begin
  select daily_rate_rials, 1 + (prior_base_increase_percent / 100)
  into v_daily_rate, v_prior_multiplier
  from public.saas_seniority_annual_rates
  where persian_year = p_persian_year;

  if v_daily_rate is null or v_daily_rate <= 0 then
    raise exception 'seniority_annual_rate_not_found';
  end if;

  insert into public.saas_seniority_service_rates (
    persian_year, completed_service_years, daily_rate_rials, source_notes
  )
  values (p_persian_year, 1, round(v_daily_rate), 'محاسبه‌شده از نرخ مصوب سال و ضریب افزایش پایه‌های قبل')
  on conflict (persian_year, completed_service_years) do update
  set daily_rate_rials = excluded.daily_rate_rials,
      source_notes = excluded.source_notes,
      updated_at = now();

  insert into public.saas_seniority_service_rates (
    persian_year, completed_service_years, daily_rate_rials, source_notes
  )
  select
    p_persian_year,
    previous.completed_service_years + 1,
    round((previous.daily_rate_rials * v_prior_multiplier) + v_daily_rate),
    'محاسبه‌شده از نرخ مصوب سال و ضریب افزایش پایه‌های قبل'
  from public.saas_seniority_service_rates previous
  where previous.persian_year = p_persian_year - 1
    and previous.completed_service_years < 60
  on conflict (persian_year, completed_service_years) do update
  set daily_rate_rials = excluded.daily_rate_rials,
      source_notes = excluded.source_notes,
      updated_at = now();
end;
$$;


