--
-- Name: release_orphaned_payroll_sources(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_orphaned_payroll_sources(p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_org_id is null then
    return;
  end if;

  perform set_config('app.payroll_source_sync', 'active', true);

  -- ابتدا پیش‌نویس‌های پورسانت را آزاد می‌کنیم تا محاسبهٔ همان ماه بتواند
  -- دوباره با همان کلید منبع ذخیره شود.
  with orphaned_commission_entries as (
    select entry.*
    from public.payroll_calculation_entries entry
    left join public.payroll_slips slip
      on slip.id = entry.payroll_slip_id
     and slip.org_id = entry.org_id
    where entry.org_id = p_org_id
      and entry.source_type = 'commission'
      and entry.status = 'included_in_payroll'
      and slip.id is null
  ), orphaned_commission_keys as (
    select distinct nullif(trim(payroll_line.value->>'source_key'), '') as source_key
    from orphaned_commission_entries entry
    cross join lateral jsonb_array_elements(coalesce(entry.details->'rows', '[]'::jsonb)) as invoice_row(value)
    cross join lateral jsonb_array_elements(coalesce(invoice_row.value->'lines', '[]'::jsonb)) as payroll_line(value)
  ), orphaned_commission_scopes as (
    select distinct
      entry.employee_id,
      entry.period_start,
      entry.period_end,
      nullif(trim(entry.details->>'basis'), '') as source_basis,
      nullif(trim(entry.details->>'percent_mode'), '') as percent_mode
    from orphaned_commission_entries entry
  )
  update public.commission_drafts draft
  set
    posted_amount = 0,
    remaining_amount = greatest(0, coalesce(draft.entitled_amount, 0)),
    draft_status = 'draft',
    updated_at = now()
  where draft.org_id = p_org_id
    and (
      draft.source_key in (select source_key from orphaned_commission_keys where source_key is not null)
      or exists (
        select 1
        from orphaned_commission_scopes scope
        where scope.employee_id = draft.employee_id
          and scope.period_start = draft.period_start
          and scope.period_end = draft.period_end
          and scope.source_basis is not distinct from draft.source_basis
          and scope.percent_mode is not distinct from draft.percent_mode
      )
    );

  -- همهٔ اقلام محاسباتیِ وصل به فیش حذف‌شده، دوباره قابل انتخاب می‌شوند.
  update public.payroll_calculation_entries entry
  set
    status = 'draft',
    payroll_slip_id = null,
    updated_at = now()
  where entry.org_id = p_org_id
    and entry.status = 'included_in_payroll'
    and not exists (
      select 1
      from public.payroll_slips slip
      where slip.id = entry.payroll_slip_id
        and slip.org_id = entry.org_id
    );

  -- پاداش، جریمه و مساعده فقط تا وقتی فیش مرجع موجود است، مصرف‌شده محسوب می‌شوند.
  update public.employee_bonus_requests request
  set related_payroll_slip_id = null, updated_at = now()
  where request.org_id = p_org_id
    and request.related_payroll_slip_id is not null
    and not exists (
      select 1 from public.payroll_slips slip
      where slip.id = request.related_payroll_slip_id
        and slip.org_id = request.org_id
    );

  update public.employee_penalty_requests request
  set related_payroll_slip_id = null, updated_at = now()
  where request.org_id = p_org_id
    and request.related_payroll_slip_id is not null
    and not exists (
      select 1 from public.payroll_slips slip
      where slip.id = request.related_payroll_slip_id
        and slip.org_id = request.org_id
    );

  update public.employee_advances advance
  set related_payroll_slip_id = null, updated_at = now()
  where advance.org_id = p_org_id
    and advance.related_payroll_slip_id is not null
    and not exists (
      select 1 from public.payroll_slips slip
      where slip.id = advance.related_payroll_slip_id
        and slip.org_id = advance.org_id
    );
end;
$$;


--
-- Name: release_payroll_sources(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_payroll_sources(p_org_id uuid, p_payroll_slip_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_scope_token uuid := gen_random_uuid();
  v_snapshot jsonb := '{}'::jsonb;
begin
  if p_org_id is null or p_payroll_slip_id is null then
    return;
  end if;

  select coalesce(performance_snapshot, '{}'::jsonb)
    into v_snapshot
  from public.payroll_slips
  where id = p_payroll_slip_id
    and org_id = p_org_id;

  insert into public.payroll_source_mutation_scopes (scope_token, org_id, table_name, record_id)
  select v_scope_token, p_org_id, source.table_name, source.record_id
  from (
    select 'payroll_calculation_entries'::text as table_name, entry.id as record_id
    from public.payroll_calculation_entries entry
    where entry.org_id = p_org_id
      and (
        entry.payroll_slip_id = p_payroll_slip_id
        or entry.id in (
          select item.value::uuid
          from jsonb_array_elements_text(coalesce(v_snapshot->'payroll_ledger_entry_ids', '[]'::jsonb)) as item(value)
          where item.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        )
      )
    union all
    select 'employee_bonus_requests'::text, request.id
    from public.employee_bonus_requests request
    where request.org_id = p_org_id
      and request.related_payroll_slip_id = p_payroll_slip_id
    union all
    select 'employee_penalty_requests'::text, request.id
    from public.employee_penalty_requests request
    where request.org_id = p_org_id
      and request.related_payroll_slip_id = p_payroll_slip_id
    union all
    select 'employee_advances'::text, advance.id
    from public.employee_advances advance
    where advance.org_id = p_org_id
      and (
        advance.related_payroll_slip_id = p_payroll_slip_id
        or advance.id in (
          select item.value::uuid
          from jsonb_array_elements_text(coalesce(v_snapshot->'employee_advance_ids', '[]'::jsonb)) as item(value)
          where item.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        )
      )
    union all
    select 'commission_drafts'::text, draft.id
    from public.commission_drafts draft
    where draft.org_id = p_org_id
      and exists (
        select 1
        from public.payroll_calculation_entries entry
        where entry.org_id = p_org_id
          and entry.source_type = 'commission'
          and entry.employee_id = draft.employee_id
          and entry.period_start = draft.period_start
          and entry.period_end = draft.period_end
          and (
            entry.payroll_slip_id = p_payroll_slip_id
            or entry.id in (
              select item.value::uuid
              from jsonb_array_elements_text(coalesce(v_snapshot->'payroll_ledger_entry_ids', '[]'::jsonb)) as item(value)
              where item.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            )
          )
      )
  ) as source
  on conflict do nothing;

  perform public._release_payroll_sources_internal(p_org_id, p_payroll_slip_id);

  delete from public.payroll_source_mutation_scopes
  where scope_token = v_scope_token;
end;
$_$;


--
-- Name: release_payroll_sources_before_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_payroll_sources_before_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- هر ردیف محاسباتی که فقط به‌خاطر این فیش نهایی شده بود، دوباره برای فیش بعدی آماده می‌شود.
  update public.payroll_calculation_entries
  set
    status = case when status = 'included_in_payroll' then 'proposed' else status end,
    payroll_slip_id = null,
    updated_at = now()
  where org_id = old.org_id
    and payroll_slip_id = old.id;

  -- اتصال‌های سطح درخواست نیز باید آزاد شوند؛ در غیر این صورت در ویزارد بعدی نادیده گرفته می‌شوند.
  update public.employee_bonus_requests
  set related_payroll_slip_id = null, updated_at = now()
  where org_id = old.org_id
    and related_payroll_slip_id = old.id;

  update public.employee_penalty_requests
  set related_payroll_slip_id = null, updated_at = now()
  where org_id = old.org_id
    and related_payroll_slip_id = old.id;

  update public.employee_advances
  set related_payroll_slip_id = null, updated_at = now()
  where org_id = old.org_id
    and related_payroll_slip_id = old.id;

  return old;
end;
$$;


--
-- Name: release_payroll_sources_on_remove(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_payroll_sources_on_remove() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  v_payroll_slip_id uuid := case when tg_op = 'DELETE' then old.id else new.id end;
begin
  perform public.release_payroll_sources(v_org_id, v_payroll_slip_id);
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: release_public_confirmation_otp_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_public_confirmation_otp_request(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_request_id is null then
    return;
  end if;

  -- فقط یک تلاش تازه‌ای که هنوز پیامکی از آن ارسال نشده حذف می‌شود؛ این مسیر
  -- هنگام خطای داخلی Edge استفاده خواهد شد تا retry معتبر بی‌دلیل مسدود نشود.
  delete from public.public_confirmation_otp_request_limits
  where id = p_request_id
    and requested_at > now() - interval '5 minutes';
end;
$$;


--
-- Name: release_record_locks_for_deleted_record(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_record_locks_for_deleted_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from public.record_locks rl
  where rl.org_id = old.org_id
    and rl.record_id = old.id
    and (
      rl.module_id = tg_table_name
      or coalesce(rl.metadata ->> 'table_name', '') = tg_table_name
      or public.resolve_record_lock_table_name(rl.module_id) = tg_table_name
    );

  return old;
end;
$$;


