end;
$$;


--
-- Name: request_billboard_status_change(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_billboard_status_change(p_input jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_billboard public.billboards%rowtype;
  v_id uuid;
  v_billboard_id uuid := nullif(trim(coalesce(p_input ->> 'billboard_id', '')), '')::uuid;
  v_target_status text := nullif(trim(coalesce(p_input ->> 'target_status', '')), '');
  v_application_mode text := lower(coalesce(nullif(trim(p_input ->> 'application_mode'), ''), 'main_status'));
  v_customer_id uuid := nullif(trim(coalesce(p_input ->> 'customer_id', '')), '')::uuid;
  v_invoice_id uuid := nullif(trim(coalesce(p_input ->> 'invoice_id', '')), '')::uuid;
  v_lead_id uuid := nullif(trim(coalesce(p_input ->> 'marketing_lead_id', '')), '')::uuid;
  v_template_id uuid := nullif(trim(coalesce(p_input ->> 'process_template_id', '')), '')::uuid;
  v_batch_id uuid := nullif(trim(coalesce(p_input ->> 'batch_id', '')), '')::uuid;
  v_template_snapshot jsonb := '{}'::jsonb;
begin
  if v_org_id is null or auth.uid() is null then raise exception 'سازمان یا کاربر جاری معتبر نیست.'; end if;
  if not public.current_org_has_plan_module('billboards', false) then raise exception 'ماژول تبلیغات محیطی برای سازمان جاری فعال نیست.' using errcode = '42501'; end if;
  if not public.current_org_has_plan_feature('billboard_status_management', true) or not public.can_manage_billboard_status_change('request') then raise exception 'اجازه ثبت درخواست تغییر وضعیت ندارید.'; end if;
  if v_target_status not in ('free','oral_reserve','final_reserve','in_line','opening','near_finish','opening_deadline_ended','pickup_queue','inactive','blocked') then raise exception 'وضعیت مقصد معتبر نیست.'; end if;
  if v_application_mode not in ('main_status', 'add_tag') then raise exception 'نحوه اعمال وضعیت معتبر نیست.'; end if;
  if v_application_mode = 'add_tag' and v_target_status not in ('oral_reserve','final_reserve','in_line') then raise exception 'برای این وضعیت فقط تغییر وضعیت اصلی تابلو مجاز است.'; end if;
  if v_target_status = 'blocked' and nullif(trim(coalesce(p_input ->> 'block_reason', '')), '') is null then raise exception 'دلیل مسدودسازی الزامی است.'; end if;
  if v_target_status = 'opening' and (nullif(trim(coalesce(p_input ->> 'start_date', '')), '') is null or nullif(trim(coalesce(p_input ->> 'end_date', '')), '') is null) then raise exception 'برای وضعیت در حال اکران، تاریخ شروع و پایان اکران الزامی است.'; end if;
  select * into v_billboard from public.billboards where id = v_billboard_id and org_id = v_org_id for share;
  if not found then raise exception 'تابلوی انتخاب‌شده در سازمان جاری پیدا نشد.'; end if;
  if v_customer_id is not null and not exists (select 1 from public.customers where id = v_customer_id and org_id = v_org_id) then raise exception 'مشتری انتخاب‌شده معتبر نیست.'; end if;
  if v_invoice_id is not null and not exists (select 1 from public.invoices where id = v_invoice_id and org_id = v_org_id) then raise exception 'فاکتور انتخاب‌شده معتبر نیست.'; end if;
  if v_lead_id is not null and not exists (select 1 from public.marketing_leads where id = v_lead_id and org_id = v_org_id) then raise exception 'لید انتخاب‌شده معتبر نیست.'; end if;
  if v_template_id is not null then
    if not exists (select 1 from public.process_templates where id = v_template_id and org_id = v_org_id and ('billboard_status_changes' = module_id or 'billboard_status_changes' = any(coalesce(module_ids, '{}'::text[])))) then raise exception 'الگوی فرآیند انتخاب‌شده برای درخواست تغییر وضعیت تابلو سازگار نیست.'; end if;
    select jsonb_build_object('template', to_jsonb(t), 'stages', coalesce((select jsonb_agg(to_jsonb(s) order by s.sort_order) from public.process_template_stages s where s.template_id = t.id), '[]'::jsonb)) into v_template_snapshot from public.process_templates t where t.id = v_template_id and t.org_id = v_org_id;
  end if;
  insert into public.billboard_status_changes (org_id, billboard_id, source_status, target_status, application_mode, customer_id, invoice_id, marketing_lead_id, start_date, end_date, block_reason, description, requested_by, batch_id, process_template_id, process_template_snapshot)
  values (v_org_id, v_billboard.id, v_billboard.status, v_target_status, v_application_mode, v_customer_id, v_invoice_id, v_lead_id, nullif(trim(coalesce(p_input ->> 'start_date', '')), '')::date, nullif(trim(coalesce(p_input ->> 'end_date', '')), '')::date, nullif(trim(coalesce(p_input ->> 'block_reason', '')), ''), nullif(trim(coalesce(p_input ->> 'description', '')), ''), auth.uid(), v_batch_id, v_template_id, v_template_snapshot)
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: request_billboard_status_changes_bulk(uuid[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_billboard_status_changes_bulk(p_billboard_ids uuid[], p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_billboard_id uuid;
  v_batch_id uuid := gen_random_uuid();
  v_created_ids uuid[] := array[]::uuid[];
begin
  if coalesce(array_length(p_billboard_ids, 1), 0) = 0 then raise exception 'حداقل یک تابلو انتخاب کنید.'; end if;
  for v_billboard_id in select distinct unnest(p_billboard_ids) loop
    v_created_ids := array_append(v_created_ids, public.request_billboard_status_change(coalesce(p_input, '{}'::jsonb) || jsonb_build_object('billboard_id', v_billboard_id, 'batch_id', v_batch_id)));
  end loop;
  return jsonb_build_object('batch_id', v_batch_id, 'request_ids', to_jsonb(v_created_ids), 'created_count', coalesce(array_length(v_created_ids, 1), 0));
end;
$$;


--
-- Name: requeue_stale_workflow_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requeue_stale_workflow_events() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer := 0;
begin
  update public.workflow_event_queue
  set status = 'pending', claimed_at = null, available_at = now()
  where status = 'processing'
    and claimed_at < now() - interval '10 minutes'
    and attempts < 5;
  get diagnostics v_count = row_count;

  update public.workflow_event_queue
  set status = 'failed', completed_at = now(), last_error = coalesce(last_error, 'حداکثر تلاش برای اجرای رویداد انجام شد.')
  where status = 'processing'
    and claimed_at < now() - interval '10 minutes'
    and attempts >= 5;
  return v_count;
end;
$$;


--
-- Name: requeue_stale_workflow_interval_jobs(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requeue_stale_workflow_interval_jobs(p_stale_after interval DEFAULT '00:05:00'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer := 0;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'دسترسی بازیابی صف اجرا وجود ندارد.' using errcode = '42501';
  end if;

  update public.workflow_interval_jobs
  set status = case when attempts >= max_attempts then 'failed' else 'pending' end,
      available_at = case when attempts >= max_attempts then available_at else now() end,
      completed_at = case when attempts >= max_attempts then now() else null end,
      locked_at = null,
      last_error = coalesce(last_error, 'اجرای قبلی ناتمام ماند و بازیابی شد.'),
      updated_at = now()
  where status = 'running'
    and locked_at < now() - coalesce(p_stale_after, interval '5 minutes');
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


--
-- Name: reserve_taxpayer_invoice_serial(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_taxpayer_invoice_serial(p_org_id uuid, p_fiscal_id text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_serial bigint;
  v_fiscal_id text := upper(nullif(btrim(coalesce(p_fiscal_id, '')), ''));
begin
  if p_org_id is null then
    raise exception 'org_id is required';
  end if;

  if v_fiscal_id is null then
    raise exception 'fiscal_id is required';
  end if;

  insert into public.taxpayer_invoice_sequences (org_id, fiscal_id, last_serial)
  values (p_org_id, v_fiscal_id, 1)
  on conflict (org_id, fiscal_id)
  do update set
    last_serial = public.taxpayer_invoice_sequences.last_serial + 1,
    updated_at = now()
  returning last_serial into v_serial;

  return v_serial;
end;
$$;


--
-- Name: reserve_taxpayer_invoice_serial(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_taxpayer_invoice_serial(p_org_id uuid, p_fiscal_id text, p_min_last_serial bigint DEFAULT 0) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_serial bigint;
  v_fiscal_id text := upper(nullif(btrim(coalesce(p_fiscal_id, '')), ''));
  v_min_last_serial bigint := greatest(coalesce(p_min_last_serial, 0), 0);
begin
  if p_org_id is null then
    raise exception 'شناسه سازمان الزامی است.';
  end if;

  if v_fiscal_id is null then
    raise exception 'شناسه مالیاتی الزامی است.';
  end if;

  insert into public.taxpayer_invoice_sequences (org_id, fiscal_id, last_serial)
  values (p_org_id, v_fiscal_id, v_min_last_serial + 1)
  on conflict (org_id, fiscal_id)
  do update set
    last_serial = greatest(public.taxpayer_invoice_sequences.last_serial, v_min_last_serial) + 1,
    updated_at = now()
  returning last_serial into v_serial;

  return v_serial;
end;
$$;


--
-- Name: reset_payroll_for_recalculation(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_payroll_for_recalculation(p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_canceled_slips integer := 0;
  v_released_entries integer := 0;
begin
  if v_org_id is null then
    raise exception 'organization_context_required';
  end if;

  if not public.current_user_has_role_permission_entry('payroll_slips', 'edit', null, true) then
    raise exception 'payroll_recalculation_not_allowed';
  end if;

  -- ابطال، trigger آزادسازی منابع فیش را اجرا می‌کند و اتصال پاداش، جریمه، مساعده و پورسانت را برمی‌دارد.
  update public.payroll_slips
  set status = 'canceled', updated_at = now()
  where org_id = v_org_id
    and coalesce(status, 'draft') <> 'canceled'
    and (p_period_start is null or period_end >= p_period_start)
    and (p_period_end is null or period_start <= p_period_end);
  get diagnostics v_canceled_slips = row_count;

  -- هر قلمی که پیش‌تر به فیش متصل بوده، دوباره در وضعیت قابل محاسبه قرار می‌گیرد.
  update public.payroll_calculation_entries
  set status = 'draft', payroll_slip_id = null, updated_at = now()
  where org_id = v_org_id
    and status = 'included_in_payroll'
    and (p_period_start is null or period_end >= p_period_start)
    and (p_period_end is null or period_start <= p_period_end);
  get diagnostics v_released_entries = row_count;

  return jsonb_build_object(
    'canceled_slips', v_canceled_slips,
    'released_entries', v_released_entries
  );
end;
$$;


--
-- Name: resolve_record_lock_table_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_record_lock_table_name(p_module_id text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_module_id text := btrim(coalesce(p_module_id, ''));
begin
  return case v_module_id
    when 'sales_return_invoices' then 'invoices'
    when 'purchase_return_invoices' then 'purchase_invoices'
    when 'saas_orgs' then 'saas_admin_org_candidates_view'
    when 'saas_demo_requests' then 'saas_onboarding_requests'
    when 'saas_users' then 'saas_admin_users_view'
    else v_module_id
  end;
end;
$$;


--
-- Name: resolve_recycle_bin_source_table(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_recycle_bin_source_table(p_source_table text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_table text := trim(coalesce(p_source_table, ''));
  v_has_table boolean := false;
  v_has_id_column boolean := false;
begin
  if v_table = '' then
    return null;
  end if;

  select exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = v_table
  )
  into v_has_table;

  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = v_table
      and column_name = 'id'
  )
  into v_has_id_column;

  if not v_has_table or not v_has_id_column then
    return null;
  end if;

  return v_table;
end;
$$;


--
-- Name: resolve_saas_org_context(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_saas_org_context(p_org_id uuid, p_org_slug text DEFAULT NULL::text, p_hostname text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target record;
  plan_settings record;
  effective_modules jsonb := '{}'::jsonb;
  effective_features jsonb := '{}'::jsonb;
begin
  select s.*, o.name as org_name, o.is_active as org_is_active
    into target
  from public.saas_org_settings s
  join public.organizations o on o.id = s.org_id
  where (p_org_id is not null and s.org_id = p_org_id)
     or (p_org_slug is not null and lower(s.slug) = lower(p_org_slug))
     or (
       p_hostname is not null
       and lower(s.resolved_host) = lower(p_hostname)
     )
  order by s.updated_at desc nulls last
  limit 1;

  if target.org_id is null then
    return null;
  end if;

  select *
    into plan_settings
  from public.saas_plans
  where lower(code) = lower(coalesce(target.plan_code, ''))
  limit 1;

  effective_modules := coalesce(plan_settings.enabled_modules, '{}'::jsonb) || coalesce(target.module_overrides, '{}'::jsonb);
  effective_features := coalesce(plan_settings.enabled_features, '{}'::jsonb) || coalesce(target.feature_overrides, '{}'::jsonb);

  return jsonb_build_object(
    'org_id', target.org_id,
    'org_name', target.org_name,
    'slug', target.slug,
    'status', target.status,
    'plan_code', target.plan_code,
    'trial_ends_at', target.trial_ends_at,
    'is_demo', target.is_demo,
    'is_readonly', target.is_readonly or (target.trial_ends_at is not null and target.trial_ends_at < now()),
    'resolved_host', target.resolved_host,
    'dns_status', target.dns_status,
    'effective_modules', effective_modules,
    'effective_features', effective_features
  );
end
$$;


--
-- Name: resolve_shared_short_link(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_shared_short_link(p_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_link public.short_links%rowtype;
  v_target text;
begin
  if p_code is null or length(p_code) < 4 or length(p_code) > 32 then
    return null;
  end if;
  select * into v_link from public.short_links
  where code = p_code and is_active = true
    and (expires_at is null or expires_at > now())
  limit 1;
  if not found then return null; end if;

  v_target := nullif(v_link.target_url, '');
  if v_target is null and v_link.target_asset_id is not null then
    select target_url into v_target from public.file_assets
    where id = v_link.target_asset_id and org_id = v_link.org_id;
  end if;
  if v_target is null and v_link.target_entry_id is not null then
    select a.target_url into v_target
    from public.file_entries e
    join public.file_assets a on a.id = e.asset_id and a.org_id = e.org_id
    where e.id = v_link.target_entry_id and e.org_id = v_link.org_id;
  end if;
  if v_target is null then return null; end if;
  return jsonb_build_object(
    'link_type', v_link.link_type,
    'target_url', v_target,
    'metadata', v_link.metadata
  );
end;
$$;


--
-- Name: restore_record_file_bundle(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_record_file_bundle(p_bundle jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item jsonb;
  v_inserted integer := 0;
  v_round_inserted integer := 0;
  v_parent_id uuid;
  v_folder_id uuid;
  v_entry_id uuid;
  v_record_file_id text;
begin
  if p_bundle is null or jsonb_typeof(p_bundle) <> 'object' then
    return 0;
  end if;

  if jsonb_typeof(coalesce(p_bundle->'folders', '[]'::jsonb)) = 'array' then
    loop
      v_round_inserted := 0;
      for v_item in
        select value
        from jsonb_array_elements(coalesce(p_bundle->'folders', '[]'::jsonb))
      loop
        v_folder_id := nullif(v_item->>'id', '')::uuid;
        if v_folder_id is null or exists(select 1 from public.file_folders where id = v_folder_id) then
          continue;
        end if;

        v_parent_id := nullif(v_item->>'parent_id', '')::uuid;
        if v_parent_id is not null and not exists(select 1 from public.file_folders where id = v_parent_id) then
          continue;
        end if;

        insert into public.file_folders
        select *
        from jsonb_populate_record(null::public.file_folders, v_item);
        v_inserted := v_inserted + 1;
        v_round_inserted := v_round_inserted + 1;
      end loop;
      exit when v_round_inserted = 0;
    end loop;
  end if;

  if jsonb_typeof(coalesce(p_bundle->'entries', '[]'::jsonb)) = 'array' then
    for v_item in
      select value
      from jsonb_array_elements(coalesce(p_bundle->'entries', '[]'::jsonb))
    loop
      v_entry_id := nullif(v_item->>'id', '')::uuid;
      if v_entry_id is null or exists(select 1 from public.file_entries where id = v_entry_id) then
        continue;
      end if;
      insert into public.file_entries
      select *
      from jsonb_populate_record(null::public.file_entries, v_item);
      v_inserted := v_inserted + 1;
    end loop;
  end if;

  if to_regclass('public.record_files') is not null
     and jsonb_typeof(coalesce(p_bundle->'record_files', '[]'::jsonb)) = 'array' then
    for v_item in
      select value
      from jsonb_array_elements(coalesce(p_bundle->'record_files', '[]'::jsonb))
    loop
      v_record_file_id := trim(coalesce(v_item->>'id', ''));
      if v_record_file_id = '' or exists(select 1 from public.record_files where id = v_record_file_id) then
        continue;
      end if;
      insert into public.record_files
      select *
      from jsonb_populate_record(null::public.record_files, v_item);
      v_inserted := v_inserted + 1;
    end loop;
  end if;

  return v_inserted;
end;
$$;


--
-- Name: restore_recycle_bin_records(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_recycle_bin_records(p_recycle_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_recycle_id uuid;
  v_row public.recycle_bin_records%rowtype;
  v_columns text;
  v_count integer := 0;
  v_target_exists boolean := false;
  v_parent_id uuid;
  v_delete_bundle jsonb;
begin
  create temporary table if not exists recycle_restore_queue (
    id uuid primary key
  ) on commit drop;

  truncate table recycle_restore_queue;

  foreach v_recycle_id in array coalesce(p_recycle_ids, array[]::uuid[])
  loop
    insert into recycle_restore_queue (id)
    values (v_recycle_id)
    on conflict do nothing;

    select *
    into v_row
    from public.recycle_bin_records
    where id = v_recycle_id;

    if not found then
      raise exception 'رکورد سطل بازیافت % پیدا نشد.', v_recycle_id;
    end if;

    v_delete_bundle := case
      when jsonb_typeof(coalesce(v_row.snapshot->'__delete_bundle', '{}'::jsonb)) = 'object'
        then coalesce(v_row.snapshot->'__delete_bundle', '{}'::jsonb)
      else '{}'::jsonb
    end;

    if jsonb_typeof(coalesce(v_delete_bundle->'deleted_process_run_ids', '[]'::jsonb)) = 'array' then
      insert into recycle_restore_queue (id)
      select r.id
      from public.recycle_bin_records r
      where r.source_table = 'process_runs'
        and r.source_record_id in (
          select nullif(value::text, '')::uuid
          from jsonb_array_elements_text(coalesce(v_delete_bundle->'deleted_process_run_ids', '[]'::jsonb)) value
        )
      on conflict do nothing;
    end if;

    if jsonb_typeof(coalesce(v_delete_bundle->'deleted_task_ids', '[]'::jsonb)) = 'array' then
      insert into recycle_restore_queue (id)
      select r.id
      from public.recycle_bin_records r
      where r.source_table = 'tasks'
        and r.source_record_id in (
          select nullif(value::text, '')::uuid
          from jsonb_array_elements_text(coalesce(v_delete_bundle->'deleted_task_ids', '[]'::jsonb)) value
        )
      on conflict do nothing;
    end if;

    if jsonb_typeof(coalesce(v_delete_bundle->'deleted_payment_operation_ids', '[]'::jsonb)) = 'array' then
      insert into recycle_restore_queue (id)
      select r.id
      from public.recycle_bin_records r
      where r.source_table = 'cash_bank_operations'
        and r.source_record_id in (
          select nullif(value::text, '')::uuid
          from jsonb_array_elements_text(coalesce(v_delete_bundle->'deleted_payment_operation_ids', '[]'::jsonb)) value
        )
      on conflict do nothing;
    end if;

    if v_row.source_table = 'process_templates' then
      insert into recycle_restore_queue (id)
      select r.id
      from public.recycle_bin_records r
      where (
        r.source_table = 'process_template_stages'
        and r.snapshot->>'template_id' = v_row.source_record_id::text
      ) or (
        r.source_table = 'workflows'
        and r.snapshot->>'process_template_id' = v_row.source_record_id::text
        and coalesce(r.snapshot->>'scope_type', '') = 'process_activator'
      )
      on conflict do nothing;
    elsif v_row.source_table = 'process_runs' then
      insert into recycle_restore_queue (id)
      select r.id
      from public.recycle_bin_records r
      where (
        r.source_table = 'process_run_stages'
        and r.snapshot->>'process_run_id' = v_row.source_record_id::text
      ) or (
        r.source_table = 'tasks'
        and (
          r.snapshot->>'process_run_id' = v_row.source_record_id::text
          or r.snapshot->>'process_run_stage_id' in (
            select cr.source_record_id::text
            from public.recycle_bin_records cr
            where cr.source_table = 'process_run_stages'
              and cr.snapshot->>'process_run_id' = v_row.source_record_id::text
          )
        )
      )
      on conflict do nothing;
    elsif v_row.source_table = 'process_template_stages' then
      v_parent_id := nullif(v_row.snapshot->>'template_id', '')::uuid;
      if v_parent_id is not null then
        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where r.source_table = 'process_templates'
          and r.source_record_id = v_parent_id
        on conflict do nothing;

        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where (
          r.source_table = 'process_template_stages'
          and r.snapshot->>'template_id' = v_parent_id::text
        ) or (
          r.source_table = 'workflows'
          and r.snapshot->>'process_template_id' = v_parent_id::text
          and coalesce(r.snapshot->>'scope_type', '') = 'process_activator'
        )
        on conflict do nothing;
      end if;
    elsif v_row.source_table = 'process_run_stages' then
      v_parent_id := nullif(v_row.snapshot->>'process_run_id', '')::uuid;
      if v_parent_id is not null then
        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where r.source_table = 'process_runs'
          and r.source_record_id = v_parent_id
        on conflict do nothing;

        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where (
          r.source_table = 'process_run_stages'
          and r.snapshot->>'process_run_id' = v_parent_id::text
        ) or (
          r.source_table = 'tasks'
          and (
            r.snapshot->>'process_run_id' = v_parent_id::text
            or r.snapshot->>'process_run_stage_id' in (
              select cr.source_record_id::text
              from public.recycle_bin_records cr
              where cr.source_table = 'process_run_stages'
                and cr.snapshot->>'process_run_id' = v_parent_id::text
            )
          )
        )
        on conflict do nothing;
      end if;

      insert into recycle_restore_queue (id)
      select r.id
      from public.recycle_bin_records r
      where r.source_table = 'tasks'
        and r.snapshot->>'process_run_stage_id' = v_row.source_record_id::text
      on conflict do nothing;
    elsif v_row.source_table = 'tasks' then
      v_parent_id := nullif(v_row.snapshot->>'process_run_id', '')::uuid;
      if v_parent_id is not null then
        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where r.source_table = 'process_runs'
          and r.source_record_id = v_parent_id
        on conflict do nothing;

        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where (
          r.source_table = 'process_run_stages'
          and r.snapshot->>'process_run_id' = v_parent_id::text
        ) or (
          r.source_table = 'tasks'
          and (
            r.snapshot->>'process_run_id' = v_parent_id::text
            or r.snapshot->>'process_run_stage_id' in (
              select cr.source_record_id::text
              from public.recycle_bin_records cr
              where cr.source_table = 'process_run_stages'
                and cr.snapshot->>'process_run_id' = v_parent_id::text
            )
          )
        )
        on conflict do nothing;
      end if;

      v_parent_id := nullif(v_row.snapshot->>'process_run_stage_id', '')::uuid;
      if v_parent_id is not null then
        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where r.source_table = 'process_run_stages'
          and r.source_record_id = v_parent_id
        on conflict do nothing;
      end if;
    elsif v_row.source_table = 'workflows' then
      v_parent_id := nullif(v_row.snapshot->>'process_template_id', '')::uuid;
      if v_parent_id is not null then
        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where r.source_table = 'process_templates'
          and r.source_record_id = v_parent_id
        on conflict do nothing;

        insert into recycle_restore_queue (id)
        select r.id
        from public.recycle_bin_records r
        where (
          r.source_table = 'process_template_stages'
          and r.snapshot->>'template_id' = v_parent_id::text
        ) or (
          r.source_table = 'workflows'
          and r.snapshot->>'process_template_id' = v_parent_id::text
          and coalesce(r.snapshot->>'scope_type', '') = 'process_activator'
        )
        on conflict do nothing;
      end if;
    end if;
  end loop;

  for v_recycle_id in
    select q.id
    from recycle_restore_queue q
    join public.recycle_bin_records r on r.id = q.id
    order by
      case r.source_table
        when 'process_templates' then 0
        when 'process_template_stages' then 1
        when 'workflows' then 2
        when 'process_runs' then 3
        when 'process_run_stages' then 4
        when 'tasks' then 5
        when 'cash_bank_operations' then 6
        else 7
      end,
      r.deleted_at,
      r.id
  loop
    select *
    into v_row
    from public.recycle_bin_records
    where id = v_recycle_id;

    if not found then
      raise exception 'رکورد سطل بازیافت % پیدا نشد.', v_recycle_id;
    end if;

    if v_row.expires_at < now() then
      delete from public.recycle_bin_records where id = v_recycle_id;
      raise exception 'مهلت بازگردانی رکورد سطل بازیافت % تمام شده است.', v_recycle_id;
    end if;

    select string_agg(format('%I', c.column_name), ', ' order by c.ordinal_position)
    into v_columns
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = v_row.source_table
      and v_row.snapshot ? c.column_name;

    if v_columns is null then
      raise exception 'ستون‌های لازم برای جدول % پیدا نشد.', v_row.source_table;
    end if;

    execute format(
      'select exists (select 1 from public.%I where id = $1)',
      v_row.source_table
    )
    into v_target_exists
    using v_row.source_record_id;

    if not coalesce(v_target_exists, false) then
      execute format(
        'insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I, $1)',
        v_row.source_table,
        v_columns,
        v_columns,
        v_row.source_table
      )
      using v_row.snapshot;
    end if;

    v_delete_bundle := case
      when jsonb_typeof(coalesce(v_row.snapshot->'__delete_bundle', '{}'::jsonb)) = 'object'
        then coalesce(v_row.snapshot->'__delete_bundle', '{}'::jsonb)
      else '{}'::jsonb
    end;

    if jsonb_typeof(coalesce(v_delete_bundle->'record_file_bundle', '{}'::jsonb)) = 'object' then
      perform public.restore_record_file_bundle(v_delete_bundle->'record_file_bundle');
    end if;

    delete from public.recycle_bin_records where id = v_recycle_id;
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$_$;


--
-- Name: run_due_workflow_intervals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_due_workflow_intervals() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.queue_due_interval_workflows();
  perform public.trigger_workflow_interval_runner();
end;
$$;


--
-- Name: run_saas_billing_cycle(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_saas_billing_cycle(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare subscription_row record; invoice_row record; created_count integer := 0; paid_count integer := 0; expired_count integer := 0; payment_result jsonb; refreshed_amount numeric;
begin
  if auth.role() <> 'service_role' then raise exception 'service_role_required'; end if;
  for subscription_row in
    select * from public.saas_recurring_subscriptions
    where status in ('active', 'grace') and next_invoice_at <= now()
      and not public.org_is_saas_admin(org_id)
    order by next_invoice_at asc limit greatest(1, least(coalesce(p_limit, 100), 500))
    for update skip locked
  loop
    if subscription_row.item_kind = 'plan' then
      refreshed_amount := public.saas_plan_monthly_total(subscription_row.entitlement_code, subscription_row.org_id);
      update public.saas_recurring_subscriptions set amount_irt = coalesce(refreshed_amount, amount_irt), updated_at = now() where id = subscription_row.id;
      subscription_row.amount_irt := coalesce(refreshed_amount, subscription_row.amount_irt);
    end if;
    insert into public.saas_subscription_invoices(org_id, subscription_id, status, period_starts_at, period_ends_at, due_at, grace_ends_at, total_irt, metadata)
    values (subscription_row.org_id, subscription_row.id, 'issued', subscription_row.current_period_ends_at, subscription_row.current_period_ends_at + interval '30 days', subscription_row.current_period_ends_at, subscription_row.current_period_ends_at + interval '3 days', subscription_row.amount_irt, jsonb_build_object('source', 'recurring_billing', 'pricing_model', case when subscription_row.item_kind = 'plan' then 'per_user' else 'catalog' end))
    on conflict (subscription_id, period_starts_at) do nothing;
    if found then created_count := created_count + 1; end if;
    update public.saas_recurring_subscriptions set next_invoice_at = current_period_ends_at + interval '1 year', updated_at = now() where id = subscription_row.id;
  end loop;
  for invoice_row in
    select id from public.saas_subscription_invoices
    where status = 'issued' and total_irt > 0 and (last_payment_attempt_at is null or last_payment_attempt_at < now() - interval '1 hour')
      and not public.org_is_saas_admin(org_id)
    order by due_at asc limit greatest(1, least(coalesce(p_limit, 100), 500))
    for update skip locked
  loop
    payment_result := public.pay_saas_subscription_invoice_from_wallet_internal(invoice_row.id);
    if coalesce((payment_result ->> 'success')::boolean, false) then paid_count := paid_count + 1; end if;
  end loop;
  update public.saas_subscription_invoices set status = 'overdue', updated_at = now() where status = 'issued' and grace_ends_at < now() and not public.org_is_saas_admin(org_id);
  update public.saas_recurring_subscriptions subscription set status = 'expired', updated_at = now()
  from public.saas_subscription_invoices invoice where invoice.subscription_id = subscription.id and invoice.status = 'overdue' and subscription.status in ('active', 'grace') and not public.org_is_saas_admin(subscription.org_id);
  get diagnostics expired_count = row_count;
  update public.saas_org_settings settings set billing_readonly = true, billing_readonly_at = now(), updated_at = now()
  where exists (select 1 from public.saas_recurring_subscriptions subscription where subscription.org_id = settings.org_id and subscription.item_kind = 'plan' and subscription.status = 'expired') and not settings.is_billing_provider and not public.org_is_saas_admin(settings.org_id);
  for subscription_row in select id from public.saas_recurring_subscriptions where status = 'expired' and item_kind <> 'plan' and not public.org_is_saas_admin(org_id) loop perform public.refresh_saas_subscription_entitlement(subscription_row.id); end loop;
  return jsonb_build_object('success', true, 'invoices_created', created_count, 'invoices_paid_from_wallet', paid_count, 'subscriptions_expired', expired_count);
end; $$;


--
-- Name: saas_account_overview_payload(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_account_overview_payload(p_org_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  settings_row public.saas_org_settings%rowtype;
  plan_row public.saas_plans%rowtype;
  enabled_modules jsonb; enabled_features jsonb; quotas jsonb; plan_quotas jsonb := '{}'::jsonb;
  member_count integer; ai_wallet jsonb; billing_wallet jsonb; instagram_count integer;
  is_saas_admin_org boolean := false; history_rows jsonb; billable_users integer; monthly_total numeric;
begin
  select * into settings_row from public.saas_org_settings where org_id = p_org_id;
  if settings_row.org_id is null then return jsonb_build_object('is_saas_org', false); end if;
  is_saas_admin_org := public.org_is_saas_admin(p_org_id);
  select * into plan_row from public.saas_plans where lower(code) = lower(coalesce(settings_row.plan_code, '')) limit 1;
  plan_quotas := coalesce(plan_row.included_quotas, '{}'::jsonb);
  select coalesce(jsonb_object_agg(code, enabled), '{}'::jsonb) into enabled_modules from (
    select key as code, lower(value #>> '{}') in ('true','1','yes','on') as enabled from jsonb_each(coalesce(plan_row.enabled_modules, '{}'::jsonb))
    union all select entitlement_code, state = 'enabled' from public.saas_org_entitlements where org_id = p_org_id and item_kind = 'module' and state <> 'expired' and (expires_at is null or expires_at > now())
  ) source;
  enabled_modules := enabled_modules || coalesce(settings_row.module_overrides, '{}'::jsonb);
  select coalesce(jsonb_object_agg(code, enabled), '{}'::jsonb) into enabled_features from (
    select key as code, lower(value #>> '{}') in ('true','1','yes','on') as enabled from jsonb_each(coalesce(plan_row.enabled_features, '{}'::jsonb))
    union all select entitlement_code, state = 'enabled' from public.saas_org_entitlements where org_id = p_org_id and item_kind = 'feature' and state <> 'expired' and (expires_at is null or expires_at > now())
  ) source;
  enabled_features := enabled_features || coalesce(settings_row.feature_overrides, '{}'::jsonb);
  select coalesce(jsonb_object_agg(entitlement_code, total), '{}'::jsonb) into quotas from (
    select entitlement_code, sum(case when state = 'enabled' then quantity else 0 end) as total from public.saas_org_entitlements where org_id = p_org_id and item_kind = 'quota' and state <> 'expired' and (expires_at is null or expires_at > now()) group by entitlement_code
  ) source;
  select count(*) into member_count from public.user_organization_memberships where org_id = p_org_id and is_active;
  billable_users := public.saas_billable_user_count(p_org_id);
  monthly_total := public.saas_plan_monthly_total(plan_row.code, p_org_id);
  select to_jsonb(wallet) into ai_wallet from public.org_ai_wallets wallet where wallet.org_id = p_org_id;
  select to_jsonb(wallet) into billing_wallet from public.org_billing_wallets wallet where wallet.org_id = p_org_id;
  select count(*) into instagram_count from public.instagram_accounts where org_id = p_org_id and is_active;
  select coalesce(jsonb_agg(row_data order by created_at desc), '[]'::jsonb) into history_rows from (
    select jsonb_build_object('kind','order','title','خرید حساب','status',status,'amount_irt',total_irt,'created_at',created_at) row_data, created_at from public.saas_orders where org_id=p_org_id
    union all select jsonb_build_object('kind','demo','title','دریافت نسخه دمو','status','completed','amount_irt',0,'created_at',issued_at), issued_at from public.saas_demo_issuance where org_id=p_org_id
    union all select jsonb_build_object('kind','admin_adjustment','title',title,'status',status,'amount_irt',amount_irt,'created_at',created_at,'metadata',metadata), created_at from public.saas_account_admin_history where org_id=p_org_id
    union all select jsonb_build_object('kind','wallet','title',coalesce(description,'تغییر کیف پول'),'status','completed','amount_irt',amount_irt,'created_at',created_at), created_at from public.org_billing_wallet_transactions where org_id=p_org_id
  ) history;
  return jsonb_build_object(
    'is_saas_org', true,
    'organization', jsonb_build_object('name',(select name from public.organizations where id=p_org_id),'status',settings_row.status,'is_demo',settings_row.is_demo,'trial_ends_at',settings_row.trial_ends_at,'billing_readonly',settings_row.billing_readonly),
    'plan', jsonb_build_object('code',plan_row.code,'title',plan_row.title,'description',plan_row.description,'short_description',plan_row.short_description,'display_features',plan_row.display_features,'enabled_modules',plan_row.enabled_modules,'enabled_features',plan_row.enabled_features,'price_monthly',coalesce(plan_row.price_per_user_monthly,plan_row.price_monthly),'price_per_user_monthly',coalesce(plan_row.price_per_user_monthly,plan_row.price_monthly),'included_users',coalesce(plan_row.minimum_users,3),'minimum_users',coalesce(plan_row.minimum_users,3),'max_users',plan_row.max_users,'storage_gb',plan_row.storage_gb,'included_quotas',plan_row.included_quotas),
    'access', jsonb_build_object('modules',enabled_modules,'features',enabled_features,'full_access',is_saas_admin_org),
    'management', jsonb_build_object('plan_code',settings_row.plan_code,'module_overrides',settings_row.module_overrides,'feature_overrides',settings_row.feature_overrides,'quota_adjustments',quotas),
    'quotas', jsonb_build_object('users_used',member_count,'users_included',greatest(coalesce(plan_row.minimum_users,3),coalesce((select max(quantity)::integer from public.saas_recurring_subscriptions where org_id=p_org_id and item_kind='plan' and status in ('active','grace')),0)),'users_extra',coalesce((quotas->>'users')::numeric,0),'users_billable',billable_users,'monthly_total_irt',monthly_total,'storage_gb',case when is_saas_admin_org then null else coalesce(plan_row.storage_gb,0)+coalesce((quotas->>'storage_gb')::numeric,0) end,'scheduled_runs',coalesce((plan_quotas->>'scheduled_runs')::numeric,0)+coalesce((quotas->>'scheduled_runs')::numeric,0),'active_workflows',coalesce((plan_quotas->>'active_workflows')::numeric,0)+coalesce((quotas->>'active_workflows')::numeric,0),'sms_credit',coalesce((quotas->>'sms_credit')::numeric,0),'instagram_accounts_used',instagram_count,'instagram_accounts',coalesce((quotas->>'instagram_accounts')::numeric,0)),
    'ai_wallet',coalesce(ai_wallet,'{}'::jsonb),'billing_wallet',coalesce(billing_wallet,'{}'::jsonb),
    'subscription_invoices',case when is_saas_admin_org then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(invoice) order by invoice.due_at asc) from (select id,status,total_irt,due_at,grace_ends_at,paid_at,created_at from public.saas_subscription_invoices where org_id=p_org_id order by created_at desc limit 20) invoice),'[]'::jsonb) end,
    'history',history_rows
  );
end; $$;


--
-- Name: saas_admin_user_audit_rows(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_admin_user_audit_rows() RETURNS TABLE(id uuid, profile_exists boolean, auth_exists boolean, full_name text, email text, mobile text, org_id uuid, org_name text, org_slug text, role_id uuid, role_title text, software_role text, is_active boolean, is_demo boolean, phone_confirmed boolean, audit_status text, issues text, tags jsonb, assignee_type text, assignee_id uuid, assignee_role_id uuid, process_template_id uuid, execution_process_draft jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with audited as (
    select
      coalesce(u.id, p.id) as id,
      p.id is not null as profile_exists,
      u.id is not null as auth_exists,
      nullif(trim(coalesce(p.full_name, u.raw_user_meta_data->>'full_name', '')), '') as full_name,
      nullif(trim(coalesce(p.email, u.email, '')), '') as email,
      nullif(trim(coalesce(p.mobile_1, p.mobile, u.phone, '')), '') as mobile,
      p.org_id,
      o.name as org_name,
      o.slug as org_slug,
      p.role_id,
      r.title as role_title,
      p.role as software_role,
      coalesce(p.is_active, false) as is_active,
      coalesce(s.is_demo, false) as is_demo,
      u.phone_confirmed_at is not null as phone_confirmed,
      array_remove(array[
        case when u.id is not null and p.id is null then 'حساب ورود بدون پروفایل' end,
        case when p.id is not null and u.id is null then 'پروفایل بدون حساب ورود' end,
        case when p.id is not null and nullif(trim(coalesce(p.full_name, '')), '') is null then 'نام ثبت نشده' end,
        case when p.id is not null and p.org_id is null then 'سازمان ندارد' end,
        case when p.id is not null and p.role_id is null then 'نقش سازمانی ندارد' end,
        case when p.role_id is not null and r.org_id is distinct from p.org_id then 'نقش متعلق به سازمان دیگری است' end,
        case when p.id is not null and coalesce(p.is_active, false) = false then 'کاربر غیرفعال' end,
        case when nullif(trim(coalesce(p.email, '')), '') is not null
               and nullif(trim(coalesce(u.email, '')), '') is not null
               and lower(trim(p.email)) <> lower(trim(u.email)) then 'ایمیل پروفایل با حساب ورود متفاوت است' end,
        case when nullif(trim(coalesce(p.mobile_1, p.mobile, '')), '') is not null
               and nullif(trim(coalesce(u.phone, '')), '') is not null
               and public.normalize_demo_mobile(coalesce(p.mobile_1, p.mobile))
                   <> public.normalize_demo_mobile(u.phone) then 'موبایل پروفایل با حساب ورود متفاوت است' end,
        case when u.phone is not null and u.phone_confirmed_at is null then 'ورود پیامکی تایید نشده' end
      ], null) as issue_list,
      coalesce(p.tags, '[]'::jsonb) as tags,
      p.assignee_type,
      p.assignee_id,
      p.assignee_role_id,
      p.process_template_id,
      coalesce(p.execution_process_draft, '{}'::jsonb) as execution_process_draft,
      coalesce(p.created_at, u.created_at) as created_at,
      p.updated_at as updated_at
    from auth.users u
    full join public.profiles p on p.id = u.id
    left join public.organizations o on o.id = p.org_id
    left join public.org_roles r on r.id = p.role_id
    left join public.saas_org_settings s on s.org_id = p.org_id
    where public.current_user_has_saas_admin_permission()
  )
  select
    id,
    profile_exists,
    auth_exists,
    full_name,
    email,
    mobile,
    org_id,
    org_name,
    org_slug,
    role_id,
    role_title,
    software_role,
    is_active,
    is_demo,
    phone_confirmed,
    case
      when not auth_exists or not profile_exists
        or issues like '%متفاوت است%'
        or issues like '%سازمان دیگری%'
      then 'critical'
      when issues like '%سازمان ندارد%'
        or issues like '%نقش سازمانی ندارد%'
        or issues like '%نام ثبت نشده%'
        or issues like '%غیرفعال%'
      then 'repair_required'
      when issues like '%ورود پیامکی تایید نشده%'
      then 'warning'
      else 'healthy'
    end as audit_status,
    coalesce(array_to_string(issue_list, ' | '), 'صحیح') as issues,
    tags,
    assignee_type,
    assignee_id,
    assignee_role_id,
    process_template_id,
    execution_process_draft,
    created_at,
    updated_at
  from (
    select a.*, array_to_string(a.issue_list, ' | ') as issues
    from audited a
  ) listed
$$;


--
-- Name: saas_billable_user_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_billable_user_count(p_org_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select greatest(
    3,
    coalesce((select count(*)::integer from public.user_organization_memberships where org_id = p_org_id and is_active), 0),
    coalesce((select max(quantity)::integer from public.saas_recurring_subscriptions where org_id = p_org_id and item_kind = 'plan' and status in ('active', 'grace')), 0)
  );
$$;


--
-- Name: saas_lifecycle_workflows_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_lifecycle_workflows_allowed() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.current_org_id() = public.support_provider_org_id() and exists (
    select 1 from public.profiles p
    join public.org_roles r on r.id = p.role_id and r.org_id = p.org_id
    where p.id = auth.uid() and p.is_active is distinct from false
      and p.org_id = public.support_provider_org_id()
      and coalesce((r.permissions -> '__saas_admin' ->> 'view')::boolean, false)
      and coalesce((r.permissions -> '__saas_admin' -> 'fields' ->> 'saas_workflows')::boolean, false)
  );
$$;


