--
-- Name: saas_plan_monthly_total(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_plan_monthly_total(p_plan_code text, p_org_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when public.org_is_saas_admin(p_org_id) then 0::numeric
    else greatest(0, coalesce(plan.price_per_user_monthly, 0)) * public.saas_billable_user_count(p_org_id)
  end
  from public.saas_plans plan
  where lower(plan.code) = lower(coalesce(p_plan_code, ''))
  limit 1;
$$;


--
-- Name: save_commission_calculation(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_commission_calculation(p_ledger_payload jsonb, p_draft_payloads jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_employee_id uuid := nullif(trim(p_ledger_payload->>'employee_id'), '')::uuid;
  v_period_start date := nullif(trim(p_ledger_payload->>'period_start'), '')::date;
  v_period_end date := nullif(trim(p_ledger_payload->>'period_end'), '')::date;
  v_source_key text := nullif(trim(p_ledger_payload->>'source_key'), '');
  v_basis text := nullif(trim(p_ledger_payload->'details'->>'basis'), '');
  v_percent_mode text := nullif(trim(p_ledger_payload->'details'->>'percent_mode'), '');
  v_ledger_id uuid;
  v_draft jsonb;
  v_draft_employee_id uuid;
  v_draft_invoice_id uuid;
begin
  if v_org_id is null then
    raise exception 'organization_context_required';
  end if;
  if not public.org_has_plan_feature(v_org_id,'advanced_commission',true) then
    raise exception 'پورسانت پیشرفته در پلن سازمان فعال نیست.' using errcode='42501';
  end if;
  if not public.current_user_has_role_permission_entry('payroll_slips', 'edit', null, true) then
    raise exception 'commission_calculation_not_allowed';
  end if;
  if v_employee_id is null or v_period_start is null or v_period_end is null
    or v_period_end < v_period_start or v_source_key is null or v_basis is null or v_percent_mode is null then
    raise exception 'invalid_commission_payload';
  end if;
  if jsonb_typeof(coalesce(p_draft_payloads, '[]'::jsonb)) <> 'array' then
    raise exception 'invalid_commission_drafts_payload';
  end if;
  if not exists (
    select 1 from public.employees
    where id = v_employee_id and org_id = v_org_id
  ) then
    raise exception 'commission_employee_not_found';
  end if;

  perform public.release_orphaned_payroll_sources(v_org_id);

  -- محاسبهٔ یک کارمند و یک دوره به‌صورت ترتیبی انجام می‌شود تا دو مرورگر
  -- نتوانند هم‌زمان ماندهٔ یک قلم را ثبت کنند.
  perform pg_advisory_xact_lock(hashtext('commission:' || v_source_key));

  for v_draft in select value from jsonb_array_elements(p_draft_payloads) as item(value) loop
    v_draft_employee_id := nullif(trim(v_draft->>'employee_id'), '')::uuid;
    v_draft_invoice_id := nullif(trim(v_draft->>'invoice_id'), '')::uuid;
    if v_draft_employee_id is distinct from v_employee_id
      or nullif(trim(v_draft->>'source_key'), '') is null
      or nullif(trim(v_draft->>'source_basis'), '') is distinct from v_basis
      or nullif(trim(v_draft->>'percent_mode'), '') is distinct from v_percent_mode then
      raise exception 'invalid_commission_draft_scope';
    end if;
    if not exists (
      select 1 from public.invoices
      where id = v_draft_invoice_id and org_id = v_org_id
    ) then
      raise exception 'commission_invoice_not_found';
    end if;

    insert into public.commission_drafts (
      org_id, source_key, employee_id, assignee_id, period_start, period_end,
      source_basis, percent_mode, eligibility_event_type, eligibility_event_at,
      invoice_id, invoice_item_key, entitled_amount, posted_amount, remaining_amount,
      decision_status, decision_reason, deferred_from_period, deferred_to_period,
      manual_decision_by, manual_decision_at, draft_status, details, updated_at
    ) values (
      v_org_id,
      v_draft->>'source_key',
      v_draft_employee_id,
      nullif(trim(v_draft->>'assignee_id'), '')::uuid,
      nullif(trim(v_draft->>'period_start'), '')::date,
      nullif(trim(v_draft->>'period_end'), '')::date,
      v_draft->>'source_basis',
      v_draft->>'percent_mode',
      nullif(trim(v_draft->>'eligibility_event_type'), ''),
      nullif(trim(v_draft->>'eligibility_event_at'), '')::timestamptz,
      v_draft_invoice_id,
      nullif(trim(v_draft->>'invoice_item_key'), ''),
      coalesce((v_draft->>'entitled_amount')::numeric, 0),
      coalesce((v_draft->>'posted_amount')::numeric, 0),
      coalesce((v_draft->>'remaining_amount')::numeric, 0),
      coalesce(nullif(trim(v_draft->>'decision_status'), ''), 'auto'),
      nullif(v_draft->>'decision_reason', ''),
      nullif(trim(v_draft->>'deferred_from_period'), '')::date,
      nullif(trim(v_draft->>'deferred_to_period'), '')::date,
      nullif(trim(v_draft->>'manual_decision_by'), '')::uuid,
      nullif(trim(v_draft->>'manual_decision_at'), '')::timestamptz,
      coalesce(nullif(trim(v_draft->>'draft_status'), ''), 'draft'),
      coalesce(v_draft->'details', '{}'::jsonb),
      now()
    )
    on conflict (source_key) where source_key is not null do update
    set
      employee_id = excluded.employee_id,
      assignee_id = excluded.assignee_id,
      period_start = excluded.period_start,
      period_end = excluded.period_end,
      source_basis = excluded.source_basis,
      percent_mode = excluded.percent_mode,
      eligibility_event_type = excluded.eligibility_event_type,
      eligibility_event_at = excluded.eligibility_event_at,
      invoice_id = excluded.invoice_id,
      invoice_item_key = excluded.invoice_item_key,
      entitled_amount = excluded.entitled_amount,
      posted_amount = excluded.posted_amount,
      remaining_amount = excluded.remaining_amount,
      decision_status = excluded.decision_status,
      decision_reason = excluded.decision_reason,
      deferred_from_period = excluded.deferred_from_period,
      deferred_to_period = excluded.deferred_to_period,
      manual_decision_by = excluded.manual_decision_by,
      manual_decision_at = excluded.manual_decision_at,
      draft_status = excluded.draft_status,
      details = excluded.details,
      updated_at = now()
    where public.commission_drafts.org_id = v_org_id;
  end loop;

  select id into v_ledger_id
  from public.payroll_calculation_entries
  where org_id = v_org_id
    and source_type = 'commission'
    and source_key = v_source_key
    and status <> 'voided'
  for update;

  if v_ledger_id is not null then
    if exists (
      select 1 from public.payroll_calculation_entries
      where id = v_ledger_id and status = 'included_in_payroll'
    ) then
      raise exception 'commission_already_in_payroll';
    end if;
    update public.payroll_calculation_entries
    set
      entry_type = coalesce(nullif(trim(p_ledger_payload->>'entry_type'), ''), entry_type),
      source_module_id = nullif(trim(p_ledger_payload->>'source_module_id'), ''),
      source_record_id = nullif(trim(p_ledger_payload->>'source_record_id'), '')::uuid,
      title = coalesce(p_ledger_payload->>'title', ''),
      amount = coalesce((p_ledger_payload->>'amount')::numeric, 0),
      quantity = nullif(trim(p_ledger_payload->>'quantity'), '')::numeric,
      rate = nullif(trim(p_ledger_payload->>'rate'), '')::numeric,
      status = coalesce(nullif(trim(p_ledger_payload->>'status'), ''), 'draft'),
      assignee_id = nullif(trim(p_ledger_payload->>'assignee_id'), '')::uuid,
      details = coalesce(p_ledger_payload->'details', '{}'::jsonb),
      updated_at = now()
    where id = v_ledger_id and org_id = v_org_id;
  else
    insert into public.payroll_calculation_entries (
      org_id, employee_id, period_start, period_end, entry_type, source_type,
      source_key, source_module_id, source_record_id, title, amount, quantity,
      rate, status, assignee_id, details
    ) values (
      v_org_id, v_employee_id, v_period_start, v_period_end,
      coalesce(nullif(trim(p_ledger_payload->>'entry_type'), ''), 'commission_calculation'),
      'commission', v_source_key,
      nullif(trim(p_ledger_payload->>'source_module_id'), ''),
      nullif(trim(p_ledger_payload->>'source_record_id'), '')::uuid,
      coalesce(p_ledger_payload->>'title', ''),
      coalesce((p_ledger_payload->>'amount')::numeric, 0),
      nullif(trim(p_ledger_payload->>'quantity'), '')::numeric,
      nullif(trim(p_ledger_payload->>'rate'), '')::numeric,
      coalesce(nullif(trim(p_ledger_payload->>'status'), ''), 'draft'),
      nullif(trim(p_ledger_payload->>'assignee_id'), '')::uuid,
      coalesce(p_ledger_payload->'details', '{}'::jsonb)
    ) returning id into v_ledger_id;
  end if;

  update public.payroll_calculation_entries
  set status = 'voided', updated_at = now()
  where org_id = v_org_id
    and source_type = 'commission'
    and employee_id = v_employee_id
    and period_start = v_period_start
    and period_end = v_period_end
    and id <> v_ledger_id
    and status in ('draft', 'proposed')
    and details->>'basis' = v_basis
    and details->>'percent_mode' = v_percent_mode;

  return v_ledger_id;
end;
$$;


--
-- Name: save_tenant_site_page_draft(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_tenant_site_page_draft(p_page_id uuid, p_slug text, p_title text, p_blocks jsonb) RETURNS TABLE(page_id uuid, draft_version_id uuid, version_number integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_user_id uuid := auth.uid();
  v_page_id uuid;
  v_version_id uuid;
  v_version_number integer;
begin
  if v_user_id is null or v_org_id is null or not public.can_manage_tenant_site_pages(v_org_id) then
    raise exception 'Not authorized to manage site pages';
  end if;
  if length(trim(coalesce(p_title, ''))) not between 1 and 180
    or coalesce(p_slug, '') !~ '^[a-z0-9][a-z0-9-]{0,119}$'
    or not public.is_valid_tenant_site_blocks(p_blocks) then
    raise exception 'Invalid site page draft';
  end if;
  if p_page_id is null then
    insert into public.site_pages(org_id, slug, title, created_by, updated_by)
      values (v_org_id, p_slug, trim(p_title), v_user_id, v_user_id) returning id into v_page_id;
  else
    select p.id into v_page_id from public.site_pages p where p.id = p_page_id and p.org_id = v_org_id for update;
    if v_page_id is null then raise exception 'Site page not found'; end if;
    update public.site_pages p set slug = p_slug, title = trim(p_title), updated_by = v_user_id, updated_at = now()
      where p.id = v_page_id and p.org_id = v_org_id;
  end if;
  select coalesce(max(v.version_number), 0) + 1 into v_version_number
    from public.site_page_versions v where v.page_id = v_page_id and v.org_id = v_org_id;
  insert into public.site_page_versions(page_id, org_id, version_number, title, slug, blocks, created_by)
    values (v_page_id, v_org_id, v_version_number, trim(p_title), p_slug, p_blocks, v_user_id)
    returning id into v_version_id;
  update public.site_pages p set draft_version_id = v_version_id, updated_by = v_user_id, updated_at = now()
    where p.id = v_page_id and p.org_id = v_org_id;
  return query select v_page_id, v_version_id, v_version_number;
end;
$_$;


--
-- Name: search_call_contact_identities(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_call_contact_identities(p_query text, p_phone_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
declare ctx jsonb:=public.get_current_organization_context();org uuid:=public.current_org_id();m text;cols text[];phone_cols text[];name_cols text[];projection text;predicate text;rows jsonb;result jsonb:='[]';
begin
 if org is null or length(trim(coalesce(p_query,'')))<2 or length(p_query)>100 then return result;end if;
 if p_phone_key is not null and p_phone_key!~'^[0-9]{7,15}$' then return result;end if;
 foreach m in array array['customers','suppliers','employees']loop
  if not public.current_org_has_plan_module(m,false) then continue;end if;
  if not(ctx->'permissions'?m) or coalesce((ctx->'permissions'->m->>'view')::boolean,true)=false then continue;end if;
  cols:=array['id','full_name','first_name','last_name','mobile_1','mobile_2','phone','updated_at','created_at'];
  if m<>'employees' then cols:=cols||array['business_name','rank'];else cols:=cols||array['job_title'];end if;
  select array_agg(c) into cols from unnest(cols)c where c='id' or
   (coalesce(ctx->'permissions'->m->'fields'->c,'true')<>'false'::jsonb and coalesce(ctx->'permissions'->m->'fields'->c->>'view','true')<>'false');
  select array_agg(c) into phone_cols from unnest(cols)c where c in('mobile_1','mobile_2','phone');
  select array_agg(c) into name_cols from unnest(cols)c where c in('full_name','first_name','last_name','business_name');
  select 'jsonb_build_object('||string_agg(format('%L,t.%I',c,c),',')||')' into projection from unnest(cols)c;
  if p_phone_key is not null then
   select string_agg(format('public.kalam_phone_lookup_key(t.%I)=$3',c),' or ') into predicate from unnest(phone_cols)c;
   predicate:=coalesce(predicate,'false')||format(' or exists(select 1 from public.phone_number_links l join public.phone_numbers n on n.id=l.phone_number_id and n.org_id=l.org_id where l.org_id=$1 and l.entity_type=%L and l.entity_id=t.id and (l.source_field=any($5) or (cardinality($5)>0 and l.source_table=''manual_phone_binding'' and l.source_field=''identity'')) and n.lookup_key=$3)',m);
  else
   select string_agg(format('position(lower($2) in lower(coalesce(t.%I,'''')))>0',c),' or ') into predicate from unnest(name_cols)c;
   predicate:=coalesce(predicate,'false');
  end if;
  execute format('select coalesce(jsonb_agg(value),''[]''::jsonb) from(select (%s)||jsonb_build_object(''moduleId'',%L) value from public.%I t where t.org_id=$1 and (%s) and public.call_contact_scope_visible($4,%L,to_jsonb(t)) order by greatest(t.updated_at,t.created_at) desc nulls last,t.id desc limit 20)matched',projection,m,m,predicate,m)
   into rows using org,p_query,p_phone_key,ctx,phone_cols;
  result:=result||rows;
 end loop;
 return result;
end;$_$;


--
-- Name: search_org_identity_options(text, text[], integer, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_org_identity_options(p_query text DEFAULT NULL::text, p_scopes text[] DEFAULT ARRAY['user'::text, 'role'::text], p_limit_per_scope integer DEFAULT 50, p_offset integer DEFAULT 0, p_exact_tokens text[] DEFAULT NULL::text[]) RETURNS TABLE(kind text, id uuid, token text, label text, subtitle text, avatar_url text, icon_key text, role_id uuid, hierarchy_rank bigint, is_active boolean, search_text text, total_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with recursive
  context as (
    select public.current_org_id() as org_id,
           greatest(1, least(coalesce(p_limit_per_scope, 50), 100)) as page_size,
           greatest(0, coalesce(p_offset, 0)) as page_offset,
           nullif(translate(lower(btrim(coalesce(p_query, ''))), 'يىك', 'ییک'), '') as search_term
  ),
  scoped_roles as (
    select r.*
    from public.org_roles r
    cross join context c
    where c.org_id is not null
      and r.org_id = c.org_id
  ),
  role_tree as (
    select
      r.id,
      r.parent_id,
      array[r.id]::uuid[] as visited,
      (lpad((coalesce(r.sort_order, 0) + 1000000000)::text, 10, '0') || ':' || lower(coalesce(r.title, '')) || ':' || r.id::text) as sort_path
    from scoped_roles r
    where r.parent_id is null
       or not exists (select 1 from scoped_roles parent where parent.id = r.parent_id)

    union all

    select
      child.id,
      child.parent_id,
      parent.visited || child.id,
      parent.sort_path || '/' || lpad((coalesce(child.sort_order, 0) + 1000000000)::text, 10, '0') || ':' || lower(coalesce(child.title, '')) || ':' || child.id::text
    from scoped_roles child
    join role_tree parent on parent.id = child.parent_id
    where not child.id = any(parent.visited)
  ),
  role_order as (
    select id, row_number() over (order by sort_path, id)::bigint as hierarchy_rank
    from role_tree
  ),
  raw_options as (
    select
      'user'::text as kind,
      p.id,
      'user:' || p.id::text as token,
      coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(p.email), ''), nullif(btrim(p.mobile_1), ''), 'کاربر بدون نام') as label,
      coalesce(nullif(btrim(p.job_title), ''), nullif(btrim(r.title), '')) as subtitle,
      p.avatar_url,
      null::text as icon_key,
      p.role_id,
      coalesce(ro.hierarchy_rank, 9223372036854775806::bigint) as hierarchy_rank,
      coalesce(p.is_active, true) as is_active,
      translate(lower(coalesce(p.full_name, '') || ' ' || coalesce(p.email, '') || ' ' || coalesce(p.mobile_1, '') || ' ' || coalesce(p.job_title, '') || ' ' || coalesce(r.title, '')), 'يىك', 'ییک') as search_text
    from public.organization_identity_profiles() p
    cross join context c
    left join scoped_roles r on r.id = p.role_id
    left join role_order ro on ro.id = p.role_id
    where c.org_id is not null
      and p.org_id = c.org_id
      and 'user' = any(coalesce(p_scopes, array['user', 'role']::text[]))

    union all

    select
      'role'::text,
      r.id,
      'role:' || r.id::text,
      coalesce(nullif(btrim(r.title), ''), 'نقش بدون عنوان'),
      'جایگاه سازمانی'::text,
      null::text,
      coalesce(nullif(btrim(r.icon_key), ''), 'team'),
      null::uuid,
      coalesce(ro.hierarchy_rank, 9223372036854775806::bigint),
      true,
      translate(lower(coalesce(r.title, '')), 'يىك', 'ییک')
    from scoped_roles r
    left join role_order ro on ro.id = r.id
    where 'role' = any(coalesce(p_scopes, array['user', 'role']::text[]))

    union all

    select
      'chat_group'::text,
      g.id,
      'chat_group:' || g.id::text,
      coalesce(nullif(btrim(g.name), ''), 'گروه داخلی'),
      'گروه داخلی'::text,
      null::text,
      null::text,
      null::uuid,
      9223372036854775806::bigint,
      true,
      translate(lower(coalesce(g.name, '')), 'يىك', 'ییک')
    from public.chat_groups g
    cross join context c
    where c.org_id is not null
      and g.org_id = c.org_id
      and 'chat_group' = any(coalesce(p_scopes, array['user', 'role']::text[]))
  ),
  filtered as (
    select raw.*
    from raw_options raw
    cross join context c
    where
      case
        when coalesce(cardinality(p_exact_tokens), 0) > 0 then raw.token = any(p_exact_tokens)
        else raw.is_active = true
          and (c.search_term is null or raw.search_text like '%' || c.search_term || '%')
      end
  ),
  ranked as (
    select
      filtered.*,
      count(*) over (partition by filtered.kind) as total_count,
      row_number() over (
        partition by filtered.kind
        order by filtered.hierarchy_rank, translate(lower(filtered.label), 'يىك', 'ییک'), filtered.id
      ) as row_index
    from filtered
  )
  select
    ranked.kind,
    ranked.id,
    ranked.token,
    ranked.label,
    ranked.subtitle,
    ranked.avatar_url,
    ranked.icon_key,
    ranked.role_id,
    ranked.hierarchy_rank,
    ranked.is_active,
    ranked.search_text,
    ranked.total_count
  from ranked
  cross join context c
  where coalesce(cardinality(p_exact_tokens), 0) > 0
     or ranked.row_index between c.page_offset + 1 and c.page_offset + c.page_size
  order by
    case ranked.kind when 'user' then 0 when 'role' then 1 else 2 end,
    ranked.hierarchy_rank,
    translate(lower(ranked.label), 'يىك', 'ییک'),
    ranked.id;
$$;


--
-- Name: search_relation_options_v1(text, text, text, uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_relation_options_v1(p_target_module text, p_target_field text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_exact_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 50) RETURNS TABLE(value uuid, label text, search_text text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_module text := trim(coalesce(p_target_module, ''));
  v_search text := trim(coalesce(p_search, ''));
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_like text := case when v_search = '' then null else '%' || v_search || '%' end;
begin
  if v_module = 'customers' then
    return query
    select
      c.id,
      trim(coalesce(nullif(c.full_name, ''), nullif(c.business_name, ''), nullif(c.legal_name, ''), nullif(c.system_code, ''), 'بدون نام')) as label,
      lower(trim(concat_ws(' ', c.full_name, c.business_name, c.legal_name, c.mobile_1, c.phone, c.system_code))) as search_text
    from public.customers c
    where c.org_id = public.current_org_id()
      and (p_exact_ids is null or c.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', c.full_name, c.business_name, c.legal_name, c.mobile_1, c.phone, c.system_code) ilike v_like)
    order by c.updated_at desc nulls last, c.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module = 'projects' then
    return query
    select
      p.id,
      trim(coalesce(nullif(p.name, ''), nullif(p.system_code, ''), 'بدون عنوان')) as label,
      lower(trim(concat_ws(' ', p.name, p.system_code, p.status))) as search_text
    from public.projects p
    where p.org_id = public.current_org_id()
      and (p_exact_ids is null or p.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', p.name, p.system_code, p.status) ilike v_like)
    order by p.updated_at desc nulls last, p.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module = 'products' then
    return query
    select
      p.id,
      trim(coalesce(nullif(p.name, ''), nullif(p.system_code, ''), 'بدون عنوان')) as label,
      lower(trim(concat_ws(' ', p.name, p.system_code, p.status))) as search_text
    from public.products p
    where p.org_id = public.current_org_id()
      and (p_exact_ids is null or p.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', p.name, p.system_code, p.status) ilike v_like)
    order by p.updated_at desc nulls last, p.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module = 'suppliers' then
    return query
    select
      s.id,
      trim(coalesce(nullif(s.full_name, ''), nullif(s.business_name, ''), nullif(s.system_code, ''), 'بدون نام')) as label,
      lower(trim(concat_ws(' ', s.full_name, s.business_name, s.mobile_1, s.phone, s.system_code))) as search_text
    from public.suppliers s
    where s.org_id = public.current_org_id()
      and (p_exact_ids is null or s.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', s.full_name, s.business_name, s.mobile_1, s.phone, s.system_code) ilike v_like)
    order by s.updated_at desc nulls last, s.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module = 'invoices' then
    return query
    select
      i.id,
      trim(coalesce(nullif(i.name, ''), nullif(i.system_code, ''), 'بدون عنوان')) as label,
      lower(trim(concat_ws(' ', i.name, i.system_code, i.status))) as search_text
    from public.invoices i
    where i.org_id = public.current_org_id()
      and (p_exact_ids is null or i.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', i.name, i.system_code, i.status) ilike v_like)
    order by i.updated_at desc nulls last, i.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module = 'purchase_invoices' then
    return query
    select
      i.id,
      trim(coalesce(nullif(i.name, ''), nullif(i.system_code, ''), 'بدون عنوان')) as label,
      lower(trim(concat_ws(' ', i.name, i.system_code, i.status))) as search_text
    from public.purchase_invoices i
    where i.org_id = public.current_org_id()
      and (p_exact_ids is null or i.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', i.name, i.system_code, i.status) ilike v_like)
    order by i.updated_at desc nulls last, i.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module = 'tasks' then
    return query
    select
      t.id,
      trim(coalesce(nullif(t.name, ''), nullif(t.system_code, ''), 'بدون عنوان')) as label,
      lower(trim(concat_ws(' ', t.name, t.system_code, t.status))) as search_text
    from public.tasks t
    where t.org_id = public.current_org_id()
      and (p_exact_ids is null or t.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', t.name, t.system_code, t.status) ilike v_like)
    order by t.updated_at desc nulls last, t.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module = 'profiles' then
    return query
    select
      p.id,
      trim(coalesce(nullif(p.full_name, ''), nullif(p.email, ''), nullif(p.mobile_1, ''), 'کاربر بدون نام')) as label,
      lower(trim(concat_ws(' ', p.full_name, p.email, p.mobile_1))) as search_text
    from public.profiles p
    where p.org_id = public.current_org_id()
      and (p_exact_ids is null or p.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', p.full_name, p.email, p.mobile_1) ilike v_like)
    order by p.updated_at desc nulls last, p.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module in ('org_roles', 'roles') then
    return query
    select
      r.id,
      trim(coalesce(nullif(r.title, ''), 'بدون عنوان')) as label,
      lower(trim(coalesce(r.title, ''))) as search_text
    from public.org_roles r
    where r.org_id = public.current_org_id()
      and (p_exact_ids is null or r.id = any(p_exact_ids))
      and (v_like is null or r.title ilike v_like)
    order by r.sort_order asc nulls last, r.title asc
    limit v_limit;
    return;
  end if;

  if v_module = 'shelves' then
    return query
    select
      s.id,
      trim(coalesce(nullif(s.shelf_number, ''), nullif(s.name, ''), 'بدون عنوان')) as label,
      lower(trim(concat_ws(' ', s.shelf_number, s.name))) as search_text
    from public.shelves s
    where s.org_id = public.current_org_id()
      and (p_exact_ids is null or s.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', s.shelf_number, s.name) ilike v_like)
    order by s.updated_at desc nulls last, s.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  if v_module = 'process_templates' then
    return query
    select
      pt.id,
      trim(coalesce(nullif(pt.name, ''), 'بدون عنوان')) as label,
      lower(trim(concat_ws(' ', pt.name, pt.module_id, array_to_string(pt.module_ids, ' ')))) as search_text
    from public.process_templates pt
    where pt.org_id = public.current_org_id()
      and (p_exact_ids is null or pt.id = any(p_exact_ids))
      and (v_like is null or concat_ws(' ', pt.name, pt.module_id, array_to_string(pt.module_ids, ' ')) ilike v_like)
    order by pt.updated_at desc nulls last, pt.created_at desc nulls last
    limit v_limit;
    return;
  end if;

  return;
end;
$$;


--
-- Name: seed_seniority_annual_rates_for_new_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_seniority_annual_rates_for_new_org() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.seniority_annual_rates (
    org_id, persian_year, daily_rate_rials, monthly_rate_30day_rials, monthly_rate_31day_rials
  ) values
    (new.id, 1404, 94000, 2820000, 2914000),
    (new.id, 1405, 166667, 5000010, 5166677)
  on conflict (org_id, persian_year) do nothing;
  return new;
end;
$$;


--
-- Name: seed_standard_chart_of_accounts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_standard_chart_of_accounts(p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_org_id is null then
    raise exception 'شناسه سازمان برای ایجاد جدول حساب‌ها الزامی است.';
  end if;

  -- ابتدا همه حساب‌های استانداردِ جاافتاده را می‌سازیم. parent_id در مرحله بعد
  -- تنظیم می‌شود تا ترتیب ثبت، وابستگی ایجاد نکند.
  with seed(code, name, account_type, account_level, nature, parent_code, is_leaf) as (
    values
      ('1', 'دارایی ها', 'asset', 'group', 'debit', null, false),
      ('11', 'دارایی های جاری', 'asset', 'general', 'debit', '1', false),
      ('110', 'وجوه نقد و بانک', 'asset', 'subsidiary', 'debit', '11', false),
      ('1101', 'صندوق', 'asset', 'detail', 'debit', '110', true),
      ('1102', 'بانک ها', 'asset', 'detail', 'debit', '110', true),
      ('1103', 'تنخواه', 'asset', 'detail', 'debit', '110', true),
      ('111', 'مطالبات تجاری', 'asset', 'subsidiary', 'debit', '11', false),
      ('1111', 'حساب های دریافتنی تجاری', 'asset', 'detail', 'debit', '111', true),
      ('1112', 'اسناد دریافتنی', 'asset', 'detail', 'debit', '111', true),
      ('112', 'پیش پرداخت ها', 'asset', 'subsidiary', 'debit', '11', false),
      ('1121', 'پیش پرداخت خرید', 'asset', 'detail', 'debit', '112', true),
      ('1122', 'مساعده کارکنان', 'asset', 'detail', 'debit', '112', true),
      ('13', 'موجودی ها', 'asset', 'general', 'debit', '1', false),
      ('130', 'موجودی کالا', 'asset', 'subsidiary', 'debit', '13', false),
      ('1301', 'موجودی کالا', 'asset', 'detail', 'debit', '130', true),
      ('14', 'دارایی های ثابت', 'asset', 'general', 'debit', '1', false),
      ('140', 'دارایی ثابت مشهود', 'asset', 'subsidiary', 'debit', '14', false),
      ('1401', 'ماشین آلات و تجهیزات', 'asset', 'detail', 'debit', '140', true),

      ('2', 'بدهی ها', 'liability', 'group', 'credit', null, false),
      ('21', 'بدهی های جاری', 'liability', 'general', 'credit', '2', false),
      ('210', 'بدهی های تجاری', 'liability', 'subsidiary', 'credit', '21', false),
      ('2101', 'حساب های پرداختنی تجاری', 'liability', 'detail', 'credit', '210', true),
      ('2102', 'اسناد پرداختنی', 'liability', 'detail', 'credit', '210', true),
      ('211', 'مالیات و عوارض', 'liability', 'subsidiary', 'credit', '21', false),
      ('2111', 'مالیات و عوارض ارزش افزوده پرداختنی', 'liability', 'detail', 'credit', '211', true),
      ('212', 'سایر بدهی های جاری', 'liability', 'subsidiary', 'credit', '21', false),
      ('2121', 'حقوق و دستمزد پرداختنی', 'liability', 'detail', 'credit', '212', true),
      ('2122', 'مالیات حقوق پرداختنی', 'liability', 'detail', 'credit', '212', true),
      ('2123', 'بیمه پرداختنی', 'liability', 'detail', 'credit', '212', true),
      ('2124', 'حساب واسط تهاتر', 'liability', 'detail', 'credit', '212', true),
      ('22', 'بدهی های غیرجاری', 'liability', 'general', 'credit', '2', false),
      ('220', 'وام ها', 'liability', 'subsidiary', 'credit', '22', false),
      ('2201', 'وام بلندمدت', 'liability', 'detail', 'credit', '220', true),

      ('3', 'حقوق مالکانه', 'equity', 'group', 'credit', null, false),
      ('31', 'سرمایه و اندوخته ها', 'equity', 'general', 'credit', '3', false),
      ('310', 'سرمایه', 'equity', 'subsidiary', 'credit', '31', false),
      ('3101', 'سرمایه', 'equity', 'detail', 'credit', '310', true),
      ('320', 'سود و زیان انباشته', 'equity', 'subsidiary', 'credit', '31', false),
      ('3201', 'سود و زیان انباشته', 'equity', 'detail', 'credit', '320', true),

      ('4', 'درآمدها', 'income', 'group', 'credit', null, false),
      ('41', 'درآمد عملیاتی', 'income', 'general', 'credit', '4', false),
      ('410', 'فروش', 'income', 'subsidiary', 'credit', '41', false),
      ('4101', 'فروش کالا و خدمات', 'income', 'detail', 'credit', '410', true),
      ('4102', 'برگشت از فروش و تخفیفات', 'income', 'detail', 'debit', '410', true),
      ('42', 'سایر درآمدها', 'income', 'general', 'credit', '4', false),
      ('420', 'درآمدهای متفرقه', 'income', 'subsidiary', 'credit', '42', false),
      ('4201', 'سایر درآمدهای عملیاتی', 'income', 'detail', 'credit', '420', true),

      ('5', 'هزینه ها', 'expense', 'group', 'debit', null, false),
      ('51', 'بهای تمام شده', 'expense', 'general', 'debit', '5', false),
      ('510', 'بهای تمام شده کالای فروش رفته', 'expense', 'subsidiary', 'debit', '51', false),
      ('5101', 'بهای تمام شده کالای فروش رفته', 'expense', 'detail', 'debit', '510', true),
      ('52', 'هزینه های اداری و عمومی', 'expense', 'general', 'debit', '5', false),
      ('520', 'هزینه های عمومی', 'expense', 'subsidiary', 'debit', '52', false),
      ('5201', 'هزینه حقوق و دستمزد', 'expense', 'detail', 'debit', '520', true),
      ('5202', 'هزینه حمل و نقل', 'expense', 'detail', 'debit', '520', true),
      ('5203', 'هزینه بیمه سهم کارفرما', 'expense', 'detail', 'debit', '520', true),
      ('5204', 'هزینه‌های عمومی و اداری', 'expense', 'detail', 'debit', '520', true),
      ('53', 'مالیات و عوارض خرید', 'expense', 'general', 'debit', '5', false),
      ('530', 'اعتبار مالیاتی خرید', 'expense', 'subsidiary', 'debit', '53', false),
      ('5301', 'مالیات و عوارض ارزش افزوده خرید', 'expense', 'detail', 'debit', '530', true),
      ('54', 'هزینه های مالی', 'expense', 'general', 'debit', '5', false),
      ('540', 'هزینه های مالی', 'expense', 'subsidiary', 'debit', '54', false),
      ('5401', 'کارمزد و بهره بانکی', 'expense', 'detail', 'debit', '540', true)
  )
  insert into public.chart_of_accounts (
    org_id, code, name, account_type, account_level, nature,
    is_leaf, is_system, is_active
  )
  select p_org_id, code, name, account_type, account_level, nature,
    is_leaf, true, true
  from seed
  on conflict (org_id, code) do nothing;

  -- فقط حساب‌های سیستمی به ساختار استاندارد متصل می‌شوند؛ حساب سفارشیِ Tenant
  -- با کد یکسان هرگز جابه‌جا یا بازنویسی نمی‌شود.
  with seed(code, parent_code) as (
    values
      ('1', null), ('11', '1'), ('110', '11'), ('1101', '110'), ('1102', '110'), ('1103', '110'),
      ('111', '11'), ('1111', '111'), ('1112', '111'), ('112', '11'), ('1121', '112'), ('1122', '112'),
      ('13', '1'), ('130', '13'), ('1301', '130'), ('14', '1'), ('140', '14'), ('1401', '140'),
      ('2', null), ('21', '2'), ('210', '21'), ('2101', '210'), ('2102', '210'), ('211', '21'), ('2111', '211'),
      ('212', '21'), ('2121', '212'), ('2122', '212'), ('2123', '212'), ('2124', '212'), ('22', '2'), ('220', '22'), ('2201', '220'),
      ('3', null), ('31', '3'), ('310', '31'), ('3101', '310'), ('320', '31'), ('3201', '320'),
      ('4', null), ('41', '4'), ('410', '41'), ('4101', '410'), ('4102', '410'), ('42', '4'), ('420', '42'), ('4201', '420'),
      ('5', null), ('51', '5'), ('510', '51'), ('5101', '510'), ('52', '5'), ('520', '52'),
      ('5201', '520'), ('5202', '520'), ('5203', '520'), ('5204', '520'), ('53', '5'), ('530', '53'), ('5301', '530'),
      ('54', '5'), ('540', '54'), ('5401', '540')
  )
  update public.chart_of_accounts account
  set parent_id = parent_account.id
  from seed
  left join public.chart_of_accounts parent_account
    on parent_account.org_id = p_org_id
   and parent_account.code = seed.parent_code
  where account.org_id = p_org_id
    and account.code = seed.code
    and account.is_system = true
    and account.parent_id is distinct from parent_account.id;

  -- هر حساب استانداردی که در این ساختار والد دارد، نباید برگ نهایی باشد.
  with seed(code, parent_code) as (
    values
      ('11', '1'), ('110', '11'), ('1101', '110'), ('1102', '110'), ('1103', '110'),
      ('111', '11'), ('1111', '111'), ('1112', '111'), ('112', '11'), ('1121', '112'), ('1122', '112'),
      ('13', '1'), ('130', '13'), ('1301', '130'), ('14', '1'), ('140', '14'), ('1401', '140'),
      ('21', '2'), ('210', '21'), ('2101', '210'), ('2102', '210'), ('211', '21'), ('2111', '211'),
      ('212', '21'), ('2121', '212'), ('2122', '212'), ('2123', '212'), ('2124', '212'), ('22', '2'), ('220', '22'), ('2201', '220'),
      ('31', '3'), ('310', '31'), ('3101', '310'), ('320', '31'), ('3201', '320'),
      ('41', '4'), ('410', '41'), ('4101', '410'), ('4102', '410'), ('42', '4'), ('420', '42'), ('4201', '420'),
      ('51', '5'), ('510', '51'), ('5101', '510'), ('52', '5'), ('520', '52'), ('5201', '520'), ('5202', '520'), ('5203', '520'), ('5204', '520'),
      ('53', '5'), ('530', '53'), ('5301', '530'), ('54', '5'), ('540', '54'), ('5401', '540')
  )
  update public.chart_of_accounts account
  set is_leaf = false
  where account.org_id = p_org_id
    and account.is_system = true
    and account.is_leaf = true
    and account.code in (select distinct parent_code from seed where parent_code is not null);
end;
$$;


