  return new;
end;
$$;


--
-- Name: send_delivery_confirm_otp(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_delivery_confirm_otp(p_code text, p_party text, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid;
  v_delivery_id uuid;
  v_status text;
  v_party text := btrim(coalesce(p_party, ''));
  v_phone text := public._delivery_normalize_phone(p_phone);
  v_phone_options jsonb := '[]'::jsonb;
  v_already_confirmed boolean := false;
  v_otp_code text;
  v_otp_hash text;
begin
  if v_party not in ('delivered_by', 'received_by') then
    return jsonb_build_object('error', 'invalid_party');
  end if;
  if v_phone !~ '^09[0-9]{9}$' then
    return jsonb_build_object('error', 'invalid_phone');
  end if;

  v_org_id := public._resolve_org_for_public_delivery(p_code);
  if v_org_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  select d.id, d.status,
    case when v_party = 'delivered_by' then d.delivered_by_confirmed_at is not null else d.received_by_confirmed_at is not null end,
    case
      when v_party = 'delivered_by' and d.delivered_by_type = 'customer' then public._delivery_public_phone_options(c_del.mobile_1, c_del.mobile_2, c_del.assistant_phone)
      when v_party = 'delivered_by' and d.delivered_by_type = 'supplier' then public._delivery_public_phone_options(s_del.mobile_1, s_del.mobile_2, null)
      when v_party = 'delivered_by' and d.delivered_by_type = 'other' then public._delivery_public_phone_options(d.external_delivered_by_phone, null, null)
      when v_party = 'delivered_by' then public._delivery_public_phone_options(e_del.mobile_1, e_del.mobile_2, p_del.mobile)
      when v_party = 'received_by' and d.received_by_type = 'customer' then public._delivery_public_phone_options(c_rec.mobile_1, c_rec.mobile_2, c_rec.assistant_phone)
      when v_party = 'received_by' and d.received_by_type = 'supplier' then public._delivery_public_phone_options(s_rec.mobile_1, s_rec.mobile_2, null)
      when v_party = 'received_by' and d.received_by_type = 'other' then public._delivery_public_phone_options(d.external_received_by_phone, null, null)
      else public._delivery_public_phone_options(e_rec.mobile_1, e_rec.mobile_2, p_rec.mobile)
    end
  into v_delivery_id, v_status, v_already_confirmed, v_phone_options
  from public.delivery_forms d
  left join public.employees e_del on e_del.id = d.delivered_by_employee_id and e_del.org_id = d.org_id
  left join public.employees e_rec on e_rec.id = d.received_by_employee_id and e_rec.org_id = d.org_id
  left join public.profiles p_del on p_del.id = d.delivered_by_id and p_del.org_id = d.org_id
  left join public.profiles p_rec on p_rec.id = d.received_by_id and p_rec.org_id = d.org_id
  left join public.customers c_del on c_del.id = d.delivered_by_customer_id and c_del.org_id = d.org_id
  left join public.customers c_rec on c_rec.id = d.received_by_customer_id and c_rec.org_id = d.org_id
  left join public.suppliers s_del on s_del.id = d.delivered_by_supplier_id and s_del.org_id = d.org_id
  left join public.suppliers s_rec on s_rec.id = d.received_by_supplier_id and s_rec.org_id = d.org_id
  where d.org_id = v_org_id
    and (d.public_slug = p_code or d.public_token = p_code)
  limit 1;

  if v_delivery_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  if v_status not in ('draft', 'pending_signature', 'signed') then
    return jsonb_build_object('error', 'invalid_status');
  end if;
  if v_already_confirmed then
    return jsonb_build_object('error', 'already_confirmed');
  end if;
  if not exists (
    select 1
    from jsonb_array_elements(coalesce(v_phone_options, '[]'::jsonb)) item
    where item->>'phone' = v_phone
  ) then
    return jsonb_build_object('error', 'phone_not_allowed');
  end if;

  v_otp_code := lpad(floor(random() * 1000000)::text, 6, '0');
  v_otp_hash := encode(sha256(cast(v_otp_code || v_phone as bytea)), 'hex');

  if v_party = 'delivered_by' then
    update public.delivery_forms
    set delivered_by_confirm_otp_hash = v_otp_hash,
        delivered_by_confirm_otp_expires_at = now() + interval '3 minutes',
        status = case when status = 'draft' then 'pending_signature' else status end
    where id = v_delivery_id and org_id = v_org_id;
  else
    update public.delivery_forms
    set received_by_confirm_otp_hash = v_otp_hash,
        received_by_confirm_otp_expires_at = now() + interval '3 minutes',
        status = case when status = 'draft' then 'pending_signature' else status end
    where id = v_delivery_id and org_id = v_org_id;
  end if;

  return jsonb_build_object('otp_code', v_otp_code);
end;
$_$;


--
-- Name: send_internal_message_v2(text, uuid[], uuid[], uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_internal_message_v2(p_content text, p_mention_user_ids uuid[] DEFAULT '{}'::uuid[], p_mention_role_ids uuid[] DEFAULT '{}'::uuid[], p_reply_to uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb, p_module_id text DEFAULT NULL::text, p_record_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_author_name text := null;
  v_metadata jsonb := case when jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object' then coalesce(p_metadata, '{}'::jsonb) else '{}'::jsonb end;
  v_group_id uuid := public.kalam_try_uuid(v_metadata->>'chat_group_id');
  v_group_users uuid[] := '{}'::uuid[];
  v_group_roles uuid[] := '{}'::uuid[];
  v_target_users uuid[] := '{}'::uuid[];
  v_target_roles uuid[] := '{}'::uuid[];
  v_conversation_key text := null;
  v_is_saved boolean := false;
  v_note public.notes%rowtype;
begin
  if v_user_id is null or v_org_id is null then
    raise exception 'UNAUTHORIZED';
  end if;
  if nullif(trim(coalesce(p_content, '')), '') is null then
    raise exception 'MESSAGE_CONTENT_REQUIRED';
  end if;

  select profile.role_id, nullif(trim(profile.full_name), '')
    into v_role_id, v_author_name
  from public.profiles profile
  where profile.id = v_user_id
    and profile.org_id = v_org_id
  limit 1;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  v_is_saved := lower(trim(coalesce(v_metadata->>'saved_message', 'false'))) in ('true', '1', 'yes');
  v_metadata := v_metadata || jsonb_build_object('source_type', 'internal_message');

  if v_group_id is not null then
    select coalesce(group_row.user_ids, '{}'::uuid[]), coalesce(group_row.role_ids, '{}'::uuid[])
      into v_group_users, v_group_roles
    from public.chat_groups group_row
    where group_row.id = v_group_id
      and group_row.org_id = v_org_id
      and (
        v_user_id = any(coalesce(group_row.user_ids, '{}'::uuid[]))
        or (v_role_id is not null and v_role_id = any(coalesce(group_row.role_ids, '{}'::uuid[])))
      )
    limit 1;
    if not found then
      raise exception 'CHAT_GROUP_ACCESS_DENIED';
    end if;
  end if;

  v_target_users := public.kalam_distinct_uuid_array(
    coalesce(p_mention_user_ids, '{}'::uuid[])
    || coalesce(v_group_users, '{}'::uuid[])
    || array[v_user_id]
  );
  v_target_roles := public.kalam_distinct_uuid_array(
    coalesce(p_mention_role_ids, '{}'::uuid[]) || coalesce(v_group_roles, '{}'::uuid[])
  );

  if v_is_saved then
    v_target_users := array[v_user_id];
    v_target_roles := '{}'::uuid[];
  elsif cardinality(v_target_users) <= 1 and cardinality(v_target_roles) = 0 then
    raise exception 'INTERNAL_MESSAGE_RECIPIENT_REQUIRED';
  end if;

  if exists (
    select 1
    from unnest(v_target_users) target_user_id
    where target_user_id <> v_user_id
      and not exists (
        select 1 from public.profiles recipient
        where recipient.id = target_user_id
          and recipient.org_id = v_org_id
      )
  ) then
    raise exception 'INTERNAL_MESSAGE_RECIPIENT_INVALID';
  end if;
  if exists (
    select 1
    from unnest(v_target_roles) target_role_id
    where not exists (
      select 1 from public.org_roles recipient_role
      where recipient_role.id = target_role_id
        and recipient_role.org_id = v_org_id
    )
  ) then
    raise exception 'INTERNAL_MESSAGE_ROLE_INVALID';
  end if;

  v_conversation_key := case
    when v_is_saved then 'mine'
    when v_group_id is not null then 'group:' || v_group_id::text
    when nullif(trim(v_metadata->>'conversation_key'), '') is not null then trim(v_metadata->>'conversation_key')
    when cardinality(coalesce(p_mention_user_ids, '{}'::uuid[])) = 1
      then public.kalam_direct_conversation_key(v_user_id, p_mention_user_ids[1])
    else 'mine'
  end;
  v_metadata := v_metadata || jsonb_build_object('conversation_key', v_conversation_key);

  insert into public.notes (
    org_id, module_id, record_id, content, reply_to,
    mention_user_ids, mention_role_ids, author_id, author_name, metadata
  ) values (
    v_org_id,
    nullif(trim(coalesce(p_module_id, '')), ''),
    nullif(trim(coalesce(p_record_id, '')), ''),
    p_content,
    p_reply_to,
    case when v_is_saved then '{}'::uuid[] else public.kalam_distinct_uuid_array(coalesce(p_mention_user_ids, '{}'::uuid[]) || coalesce(v_group_users, '{}'::uuid[])) end,
    case when v_is_saved then '{}'::uuid[] else public.kalam_distinct_uuid_array(coalesce(p_mention_role_ids, '{}'::uuid[]) || coalesce(v_group_roles, '{}'::uuid[])) end,
    v_user_id,
    v_author_name,
    v_metadata
  ) returning * into v_note;

  perform public.kalam_upsert_notification_item(
    v_org_id,
    'note',
    v_note.id::text,
    'notes',
    case when v_group_id is not null then 'group' else 'internal' end,
    'insert',
    'پیام داخلی',
    nullif(left(v_note.content, 240), ''),
    nullif(trim(coalesce(v_note.module_id, '')), ''),
    nullif(trim(coalesce(v_note.record_id, '')), ''),
    v_target_users,
    v_target_roles,
    false,
    jsonb_build_object(
      'note_source', 'internal_message',
      'chat_group_id', v_group_id,
      'reply_to', v_note.reply_to,
      'conversation_key', v_conversation_key
    ),
    coalesce(v_note.updated_at, v_note.created_at, now())
  );

  return to_jsonb(v_note);
end;
$$;


--
-- Name: send_invoice_confirm_otp(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_invoice_confirm_otp(p_system_code text, p_module text, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_invoice_id uuid;
  v_status text;
  v_otp_code text;
  v_otp_hash text;
  v_phone_allowed boolean := false;
  v_phone_normalized text := public._normalize_phone_for_match(p_phone);
begin
  v_org_id := public._resolve_org_for_public_invoice(p_system_code, p_module);
  if v_org_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  if p_module = 'invoices' then
    select
      i.id,
      i.status,
      (
        public._normalize_phone_for_match(c.mobile_1) = v_phone_normalized
        or public._normalize_phone_for_match(c.mobile_2) = v_phone_normalized
        or public._normalize_phone_for_match(c.assistant_phone) = v_phone_normalized
      )
    into v_invoice_id, v_status, v_phone_allowed
    from public.invoices i
    left join public.customers c
      on c.id = i.customer_id
     and c.org_id = i.org_id
    where i.org_id = v_org_id
      and (i.public_slug = p_system_code or i.public_token = p_system_code)
    limit 1;
  else
    select
      i.id,
      i.status,
      (
        public._normalize_phone_for_match(s.mobile_1) = v_phone_normalized
        or public._normalize_phone_for_match(s.mobile_2) = v_phone_normalized
      )
    into v_invoice_id, v_status, v_phone_allowed
    from public.purchase_invoices i
    left join public.suppliers s
      on s.id = i.supplier_id
     and s.org_id = i.org_id
    where i.org_id = v_org_id
      and (i.public_slug = p_system_code or i.public_token = p_system_code)
    limit 1;
  end if;

  if v_invoice_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  if v_status not in ('created', 'proforma') then
    return jsonb_build_object('error', 'invalid_status');
  end if;
  if coalesce(v_phone_allowed, false) = false then
    return jsonb_build_object('error', 'phone_not_allowed');
  end if;

  v_otp_code := lpad(floor(random() * 1000000)::text, 6, '0');
  v_otp_hash := encode(sha256(cast(v_otp_code || v_phone_normalized as bytea)), 'hex');

  if p_module = 'invoices' then
    update public.invoices
    set confirm_otp_hash = v_otp_hash,
        confirm_otp_expires_at = now() + interval '3 minutes'
    where id = v_invoice_id
      and org_id = v_org_id;
  else
    update public.purchase_invoices
    set confirm_otp_hash = v_otp_hash,
        confirm_otp_expires_at = now() + interval '3 minutes'
    where id = v_invoice_id
      and org_id = v_org_id;
  end if;

  return jsonb_build_object('otp_code', v_otp_code);
end;
$$;


