CREATE FUNCTION public.set_audit_user_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.created_by is null then
      new.created_by := auth.uid();
    end if;
  end if;

  if new.updated_by is null then
    new.updated_by := auth.uid();
  else
    new.updated_by := coalesce(auth.uid(), new.updated_by);
  end if;

  return new;
end;
$$;


--
-- Name: set_cheque_collection_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_cheque_collection_date() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if lower(coalesce(new.status, '')) in ('cleared', 'collected', 'cashed', 'settled', 'completed', 'passed', 'paid')
     and (tg_op = 'INSERT' or lower(coalesce(old.status, '')) not in ('cleared', 'collected', 'cashed', 'settled', 'completed', 'passed', 'paid')) then
    new.cleared_at := coalesce(new.cleared_at, new.spent_date::timestamptz, now());
  end if;
  return new;
end;
$$;


