--
-- Name: set_employee_full_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_employee_full_name() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_computed_name text;
begin
  v_computed_name := nullif(trim(concat_ws(
    ' ',
    nullif(trim(coalesce(new.prefix, '')), ''),
    nullif(trim(coalesce(new.first_name, '')), ''),
    nullif(trim(coalesce(new.last_name, '')), '')
  )), '');
  new.full_name := coalesce(v_computed_name, nullif(trim(coalesce(new.full_name, '')), ''));
  new.children_count := coalesce(new.children_count, 0);
  return new;
end;
$$;


--
-- Name: set_invoice_lifecycle_dates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_invoice_lifecycle_dates() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_new_status text := lower(coalesce(new.status, ''));
  v_old_status text := case when tg_op = 'INSERT' then '' else lower(coalesce(old.status, '')) end;
  v_approved_statuses text[] := array['confirmed', 'final', 'prepayment', 'settled', 'completed'];
begin
  if v_new_status = any(v_approved_statuses)
    and (tg_op = 'INSERT' or not (v_old_status = any(v_approved_statuses))) then
    new.approved_at := coalesce(new.approved_at, now());
  end if;
  if v_new_status = 'settled' and (tg_op = 'INSERT' or v_old_status <> 'settled') then
    new.settled_at := coalesce(new.settled_at, now());
  end if;
  if v_new_status = 'completed' and (tg_op = 'INSERT' or v_old_status <> 'completed') then
    new.completed_at := coalesce(new.completed_at, now());
  end if;
  return new;
end;
$$;


--
-- Name: set_local_installation_availability(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_local_installation_availability(p_features jsonb, p_modules jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 perform public.get_local_installation_status();
 if jsonb_typeof(p_features)<>'object' or jsonb_typeof(p_modules)<>'object'
  or exists(select 1 from jsonb_each(p_features) where jsonb_typeof(value)<>'boolean')
  or exists(select 1 from jsonb_each(p_modules) where jsonb_typeof(value)<>'boolean') then raise exception 'تنظیم قابلیت‌ها معتبر نیست.'; end if;
 update public.local_deployment_runtime set features=p_features,modules=p_modules,updated_at=now() where org_id=public.current_org_id();
end $$;


--
-- Name: set_org_story_auth_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_org_story_auth_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  -- همیشه server-side از JWT می‌گیریم
  new.creator_id := auth.uid();

  -- current_org_id() خودش SECURITY DEFINER است
  v_org_id := public.current_org_id();
  if v_org_id is null then
    raise exception 'کاربر به هیچ سازمانی تعلق ندارد'
      using errcode = 'P0001';
  end if;
  new.org_id := v_org_id;

  return new;
end;
$$;


--
-- Name: set_record_locks_state(text, uuid[], boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_record_locks_state(p_module_id text, p_record_ids uuid[], p_locked boolean, p_reason text DEFAULT NULL::text) RETURNS TABLE(record_id uuid, is_locked boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_module_id text := btrim(coalesce(p_module_id, ''));
  v_record_ids uuid[] := array[]::uuid[];
  v_record_id uuid;
begin
  if v_org_id is null or auth.uid() is null then
    raise exception 'دسترسی سازمانی معتبر برای تغییر قفل رکوردها پیدا نشد.';
  end if;
  if v_module_id = '' then
    raise exception 'ماژول انتخاب‌شده برای تغییر قفل معتبر نیست.';
  end if;

  select coalesce(array_agg(distinct candidate.record_id), array[]::uuid[])
    into v_record_ids
  from unnest(coalesce(p_record_ids, array[]::uuid[])) as candidate(record_id)
  where candidate.record_id is not null;

  if cardinality(v_record_ids) = 0 then
    return;
  end if;
  if not public.record_lock_user_can(v_module_id, case when p_locked then 'lock' else 'unlock' end) then
    raise exception 'دسترسی تغییر قفل رکوردهای انتخاب‌شده را ندارید.';
  end if;

  foreach v_record_id in array v_record_ids loop
    if not public.record_lock_target_exists(v_module_id, v_record_id, v_org_id) then
      raise exception 'یکی از رکوردهای انتخاب‌شده در این سازمان پیدا نشد.';
    end if;
  end loop;

  if coalesce(p_locked, false) then
    insert into public.record_locks(
      org_id,
      module_id,
      record_id,
      locked_by,
      lock_reason,
      source_type,
      metadata
    )
    select
      v_org_id,
      v_module_id,
      selected_record_id,
      auth.uid(),
      nullif(btrim(coalesce(p_reason, '')), ''),
      'manual',
      jsonb_build_object('table_name', public.resolve_record_lock_table_name(v_module_id))
    from unnest(v_record_ids) as selected_record_id
    on conflict (org_id, module_id, record_id)
    do update set
      lock_reason = coalesce(public.record_locks.lock_reason, excluded.lock_reason),
      metadata = public.record_locks.metadata || excluded.metadata;
  else
    delete from public.record_locks
    where org_id = v_org_id
      and module_id = v_module_id
      and record_id = any(v_record_ids);
  end if;

  return query
  select selected_record_id, coalesce(p_locked, false)
  from unnest(v_record_ids) as selected_record_id;
end;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: snapshot_invoice_commission_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_invoice_commission_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_item jsonb;
  v_items jsonb := '[]'::jsonb;
  v_position bigint;
  v_product_id uuid;
  v_commission_percentage numeric;
begin
  for v_item, v_position in
    select value, ordinality
    from jsonb_array_elements(coalesce(new."invoiceItems", '[]'::jsonb)) with ordinality
  loop
    begin
      v_product_id := nullif(trim(v_item->>'product_id'), '')::uuid;
    exception when invalid_text_representation then
      v_product_id := null;
    end;

    if nullif(trim(v_item->>'row_key'), '') is null then
      v_item := v_item || jsonb_build_object('row_key', gen_random_uuid()::text);
    end if;

    -- صفر snapshot نمی‌شود: اگر در زمان ساخت فاکتور درصدی تعیین نشده باشد،
    -- نخستین محاسبهٔ واقعی می‌تواند نرخ درست را تثبیت کند.
    if nullif(trim(v_item->>'commission_percentage_snapshot'), '') is null then
      v_commission_percentage := null;
      if coalesce(nullif(trim(v_item->>'commission_percentage'), '') ~ '^[0-9]+([.][0-9]+)?$', false)
        and (v_item->>'commission_percentage')::numeric > 0 then
        v_commission_percentage := (v_item->>'commission_percentage')::numeric;
      elsif v_product_id is not null then
        select commission_percentage into v_commission_percentage
        from public.products
        where id = v_product_id and org_id = new.org_id;

        if not found then
          select commission_percentage into v_commission_percentage
          from public.billboards
          where id = v_product_id and org_id = new.org_id;
        end if;
      end if;

      if coalesce(v_commission_percentage, 0) > 0 then
        v_item := v_item || jsonb_build_object('commission_percentage_snapshot', v_commission_percentage);
      end if;
    end if;

    v_items := v_items || jsonb_build_array(v_item);
  end loop;

  new."invoiceItems" := v_items;
  return new;
end;
$_$;


--
-- Name: snooze_notification_overlay_v1(text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snooze_notification_overlay_v1(p_section text, p_source_type text, p_source_id text, p_snoozed_until timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_section text := lower(trim(coalesce(p_section, '')));
  v_source_type text := trim(coalesce(p_source_type, ''));
  v_source_id text := trim(coalesce(p_source_id, ''));
  v_allowed boolean := false;
begin
  if v_user_id is null
     or v_org_id is null
     or v_source_type = ''
     or v_source_id = ''
     or p_snoozed_until is null
     or p_snoozed_until <= now() then
    return false;
  end if;

  select p.role_id
  into v_role_id
  from public.profiles p
  where p.id = v_user_id
    and p.org_id = v_org_id
  limit 1;

  if v_section in ('notes', 'responsibilities') then
    select exists (
      select 1
      from public.notification_inbox_items nii
      where nii.org_id = v_org_id
        and nii.section = v_section
        and nii.source_type = v_source_type
        and nii.source_id = v_source_id
        and (
          nii.is_org_wide = true
          or v_user_id = any(nii.target_user_ids)
          or (v_role_id is not null and v_role_id = any(nii.target_role_ids))
        )
    ) into v_allowed;
  elsif v_section = 'tasks' then
    select exists (
      select 1
      from public.tasks t
      where t.org_id = v_org_id
        and t.id::text = v_source_id
        and (
          (t.assignee_type = 'user' and t.assignee_id = v_user_id)
          or (t.assignee_type = 'role' and v_role_id is not null and (t.assignee_role_id = v_role_id or t.assignee_id = v_role_id))
          or (nullif(trim(coalesce(t.assignee_type, '')), '') is null and (t.assignee_id = v_user_id or t.assignee_id = v_role_id))
        )
    ) into v_allowed;
  elsif v_section = 'bot_messages' then
    select exists (
      select 1
      from public.counterparty_bot_messages m
      where m.org_id = v_org_id
        and m.id::text = v_source_id
        and public.kalam_can_access_bot_group(m.bot_group_id, m.org_id)
    ) into v_allowed;
  elsif v_section = 'sms' then
    select exists (
      select 1
      from public.outbound_messages m
      where m.org_id = v_org_id
        and m.id::text = v_source_id
        and m.channel_type = 'sms'
        and m.direction = 'inbound'
    ) into v_allowed;
  elsif v_section = 'voip_calls' then
    select exists (
      select 1
      from public.voip_call_logs c
      where c.org_id = v_org_id
        and c.id::text = v_source_id
        and c.direction = 'incoming'
    ) into v_allowed;
  end if;

  if not v_allowed then
    return false;
  end if;

  insert into public.notification_read_states (
    org_id,
    user_id,
    section,
    source_type,
    source_id,
    snoozed_until,
    updated_at
  )
  values (
    v_org_id,
    v_user_id,
    v_section,
    v_source_type,
    v_source_id,
    p_snoozed_until,
    now()
  )
  on conflict (org_id, user_id, source_type, source_id) do update
  set section = excluded.section,
      snoozed_until = excluded.snoozed_until,
      updated_at = now();

  return true;
end;
$$;


--
-- Name: stamp_ai_message_notification_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_ai_message_notification_ready() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
 if tg_op='INSERT' then
  new.notification_ready_at:=case when public.ai_message_notification_ready(new.role,new.content,new.metadata) then clock_timestamp() else null end;
 elsif public.ai_message_notification_ready(new.role,new.content,new.metadata)
   and not public.ai_message_notification_ready(old.role,old.content,old.metadata) then
  new.notification_ready_at:=clock_timestamp();
 else new.notification_ready_at:=old.notification_ready_at;
 end if;
 return new;
end $$;


--
-- Name: store_external_order(uuid, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_external_order(p_connection_id uuid, p_external_id text, p_external_status text, p_source_updated_at timestamp with time zone, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  select org_id into v_org_id
  from public.external_connections
  where id = p_connection_id and is_active = true;
  if v_org_id is null or nullif(trim(p_external_id), '') is null
     or p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'Invalid external order';
  end if;

  insert into public.external_order_inbox
    (org_id, connection_id, external_id, external_status, source_updated_at, payload)
  values
    (v_org_id, p_connection_id, p_external_id, p_external_status, p_source_updated_at, p_payload)
  on conflict (connection_id, external_id) do update
    set external_status = excluded.external_status,
        source_updated_at = excluded.source_updated_at,
        payload = excluded.payload,
        received_at = now(),
        processing_status = 'pending'
  where coalesce(excluded.source_updated_at, '-infinity'::timestamptz)
      >= coalesce(public.external_order_inbox.source_updated_at, '-infinity'::timestamptz)
    and excluded.payload is distinct from public.external_order_inbox.payload;
end;
$$;


--
-- Name: submit_public_web_form(text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_public_web_form(p_slug text, p_submission jsonb DEFAULT '{}'::jsonb, p_meta jsonb DEFAULT '{}'::jsonb, p_hostname text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_slug text := lower(trim(coalesce(p_slug, '')));
  v_org_id uuid;
  v_form public.web_forms%rowtype;
  v_field record;
  v_submission jsonb := coalesce(p_submission, '{}'::jsonb);
  v_meta jsonb := coalesce(p_meta, '{}'::jsonb);
  v_defaults jsonb := '{}'::jsonb;
  v_record_payload jsonb := '{}'::jsonb;
  v_insert_payload jsonb := '{}'::jsonb;
  v_submission_record_payload jsonb := '{}'::jsonb;
  v_record_files jsonb := '[]'::jsonb;
  v_field_value jsonb;
  v_target_record jsonb := '{}'::jsonb;
  v_existing_record jsonb := '{}'::jsonb;
  v_target_record_id uuid;
  v_existing_record_id uuid;
  v_submission_id uuid;
  v_generated_title text;
  v_duplicate_match_field text := '';
  v_duplicate_strategy text := 'allow';
  v_target_has_org_id boolean := false;
  v_duplicate_column_exists boolean := false;
  v_record_action text := 'created';
  v_update_assignments text := '';
  v_insert_columns text := '';
  v_insert_select_columns text := '';
  v_match_value_text text := '';
  v_first_upload_url text := '';
  v_target_record_id_text text := '';
begin
  if v_slug = '' then
    raise exception 'WEB_FORM_SLUG_REQUIRED';
  end if;

  select b.org_id
    into v_org_id
  from public.get_public_branding(p_hostname) b
  limit 1;

  select *
    into v_form
  from public.web_forms wf
  where wf.org_id = v_org_id
    and wf.is_active = true
    and lower(wf.route_slug) = v_slug
  order by wf.updated_at desc nulls last, wf.created_at desc nulls last
  limit 1;

  if v_form.id is null then
    raise exception 'WEB_FORM_NOT_FOUND';
  end if;

  if v_form.access_scope = 'internal' then
    if auth.uid() is null then
      raise exception 'WEB_FORM_AUTH_REQUIRED';
    end if;
    if not exists (
      select 1 from public.user_organization_memberships m
      join public.organizations o on o.id = m.org_id and o.is_active
      where m.org_id = v_form.org_id and m.user_id = auth.uid() and m.is_active
    ) then
      raise exception 'WEB_FORM_ORG_ACCESS_DENIED' using errcode = '42501';
    end if;
  end if;

  if trim(coalesce(v_form.target_module_id, '')) = '' then
    raise exception 'WEB_FORM_TARGET_REQUIRED';
  end if;

  if v_form.target_module_id = any(array[
    'organizations','org_roles','profiles','company_settings','integration_settings','dynamic_options',
    'saved_views','tags','record_tags','changelogs','user_login_events','notes','sidebar_unread',
    'workflows','workflow_logs','report_definitions','report_widgets','report_data_sources',
    'web_forms','web_form_fields','web_form_submissions','fiscal_years','chart_of_accounts',
    'accounting_event_rules','cost_centers','cash_boxes','bank_accounts','cheques',
    'cash_bank_operations','barters','journal_entries'
  ]) then
    raise exception 'WEB_FORM_TARGET_NOT_ALLOWED';
  end if;

  if not exists (
    select 1
    from information_schema.tables t
    where t.table_schema = 'public'
      and t.table_name = v_form.target_module_id
  ) then
    raise exception 'WEB_FORM_TARGET_INVALID';
  end if;

  v_defaults := coalesce(v_form.config->'default_record_values', '{}'::jsonb);
  if jsonb_typeof(v_defaults) is distinct from 'object' then
    v_defaults := '{}'::jsonb;
  end if;

  v_record_payload := v_defaults || jsonb_build_object('org_id', v_org_id);

  select exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = v_form.target_module_id
      and c.column_name = 'org_id'
  )
  into v_target_has_org_id;

  if exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = v_form.target_module_id
      and c.column_name = 'lead_source'
  ) and not (v_record_payload ? 'lead_source') then
    v_record_payload := v_record_payload || jsonb_build_object('lead_source', 'web_form');
  end if;

  for v_field in
    select *
    from public.web_form_fields
    where web_form_id = v_form.id
      and is_active = true
    order by sort_order asc, created_at asc
  loop
    v_field_value := v_submission -> v_field.field_key;
    if v_field_value is null and v_field.default_value is not null then
      v_field_value := v_field.default_value;
    end if;
    if v_field_value is null then
      continue;
    end if;

    if coalesce(v_field.field_type, '') in ('image', 'file') then
      select coalesce(item->>'url', '')
        into v_first_upload_url
      from jsonb_array_elements(
        case when jsonb_typeof(v_field_value) = 'array' then v_field_value else '[]'::jsonb end
      ) item
      where trim(coalesce(item->>'url', '')) <> ''
      limit 1;

      v_record_files := v_record_files || (
        select coalesce(
          jsonb_agg(
            jsonb_build_object(
              'url', trim(coalesce(item->>'url', '')),
              'name', nullif(trim(coalesce(item->>'name', '')), ''),
              'mime_type', nullif(trim(coalesce(item->>'mimeType', item->>'mime_type', '')), ''),
              'file_type', case when v_field.field_type = 'image' then 'image' else 'file' end,
              'field_key', v_field.field_key,
              'target_field_key', nullif(trim(coalesce(v_field.target_field_key, '')), '')
            )
          ),
          '[]'::jsonb
        )
        from jsonb_array_elements(
          case when jsonb_typeof(v_field_value) = 'array' then v_field_value else '[]'::jsonb end
        ) item
        where trim(coalesce(item->>'url', '')) <> ''
      );

      if (v_field.field_type = 'image' or v_field.target_field_key = 'image_url')
         and trim(coalesce(v_field.target_field_key, '')) <> ''
         and v_field.target_field_key <> '__record_image__'
         and v_field.target_field_key <> '__record_files__'
         and trim(coalesce(v_first_upload_url, '')) <> '' then
        v_record_payload := v_record_payload || jsonb_build_object(v_field.target_field_key, v_first_upload_url);
      end if;
      continue;
    end if;

    if trim(coalesce(v_field.target_field_key, '')) = '' then
      continue;
    end if;

    v_record_payload := v_record_payload || jsonb_build_object(v_field.target_field_key, v_field_value);
  end loop;

  if v_form.target_module_id = 'attendance_logs' then
    if nullif(coalesce(v_record_payload->>'log_type', ''), '') is null then
      v_record_payload := v_record_payload || jsonb_build_object('log_type', 'check_in');
    end if;

    if nullif(coalesce(v_record_payload->>'source_type', ''), '') is null then
      v_record_payload := v_record_payload || jsonb_build_object('source_type', 'web_form');
    end if;

    if nullif(coalesce(v_record_payload->>'occurred_at', ''), '') is null then
      if nullif(coalesce(v_record_payload->>'manual_check_in_time', ''), '') is not null then
        v_record_payload := v_record_payload || jsonb_build_object('occurred_at', v_record_payload->>'manual_check_in_time');
      elsif nullif(coalesce(v_record_payload->>'manual_check_out_time', ''), '') is not null then
        v_record_payload := v_record_payload || jsonb_build_object('occurred_at', v_record_payload->>'manual_check_out_time');
      else
        v_record_payload := v_record_payload || jsonb_build_object('occurred_at', now());
      end if;
    end if;

    if nullif(coalesce(v_record_payload->>'assignee_type', ''), '') is null then
      v_record_payload := v_record_payload || jsonb_build_object('assignee_type', 'user');
    end if;
  end if;

  v_duplicate_match_field := trim(coalesce(v_form.config->>'duplicate_match_field', ''));
  v_duplicate_strategy := case
    when coalesce(v_form.config->>'duplicate_strategy', '') in ('allow', 'update', 'skip') then (v_form.config->>'duplicate_strategy')
    else 'allow'
  end;

  if v_duplicate_match_field <> '' then
    select exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = v_form.target_module_id
        and c.column_name = v_duplicate_match_field
    )
    into v_duplicate_column_exists;

    v_match_value_text := trim(coalesce(v_record_payload->>v_duplicate_match_field, ''));
  end if;

  if v_duplicate_column_exists and v_match_value_text <> '' then
    if v_target_has_org_id then
      execute format(
        'select to_jsonb(t)
         from public.%1$I t
         cross join lateral jsonb_populate_record(null::public.%1$I, $2) as src
         where t.org_id = $1
           and t.%2$I is not distinct from src.%2$I
         limit 1',
        v_form.target_module_id,
        v_duplicate_match_field
      )
      into v_existing_record
      using v_org_id, v_record_payload;
    else
      execute format(
        'select to_jsonb(t)
         from public.%1$I t
         cross join lateral jsonb_populate_record(null::public.%1$I, $1) as src
         where t.%2$I is not distinct from src.%2$I
         limit 1',
        v_form.target_module_id,
        v_duplicate_match_field
      )
      into v_existing_record
      using v_record_payload;
    end if;

    if nullif(coalesce(v_existing_record->>'id', ''), '') is not null then
      v_existing_record_id := (v_existing_record->>'id')::uuid;
    end if;
  end if;

  if v_existing_record_id is not null and v_duplicate_strategy = 'skip' then
    v_target_record := v_existing_record;
    v_target_record_id := v_existing_record_id;
    v_record_action := 'skipped';
    v_submission_record_payload := v_record_payload;
  elsif v_existing_record_id is not null and v_duplicate_strategy = 'update' then
    select string_agg(format('%1$I = src.%1$I', c.column_name), ', ')
      into v_update_assignments
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = v_form.target_module_id
      and c.column_name not in ('id', 'org_id', 'created_at', 'created_by', 'updated_at', 'updated_by')
      and exists (
        select 1
        from jsonb_object_keys(v_record_payload) as payload_key(key)
        where payload_key.key = c.column_name
      );

    if coalesce(v_update_assignments, '') <> '' then
      execute format(
        'update public.%1$I as t
         set %2$s
         from (select * from jsonb_populate_record(null::public.%1$I, $2)) as src
         where t.id = $1
         returning to_jsonb(t)',
        v_form.target_module_id,
        v_update_assignments
      )
      into v_target_record
      using v_existing_record_id, v_record_payload;
    else
      v_target_record := v_existing_record;
    end if;

    v_target_record_id := v_existing_record_id;
    v_record_action := 'updated';
    v_submission_record_payload := v_record_payload;
  else
    v_insert_payload := v_record_payload;

    v_generated_title := coalesce(
      nullif(trim(coalesce(v_insert_payload->>'title', '')), ''),
      nullif(trim(coalesce(v_insert_payload->>'name', '')), ''),
      nullif(trim(coalesce(v_insert_payload->>'full_name', '')), ''),
      nullif(trim(coalesce(v_insert_payload->>'subject', '')), ''),
      nullif(trim(coalesce(v_insert_payload->>'business_name', '')), ''),
      nullif(trim(concat_ws(' ', v_insert_payload->>'first_name', v_insert_payload->>'last_name')), ''),
      nullif(trim(coalesce(v_form.name, '')), ''),
      'Web form ' || to_char(now(), 'YYYY-MM-DD HH24:MI')
    );

    if exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = v_form.target_module_id
        and c.column_name = 'title'
        and c.is_nullable = 'NO'
    ) and nullif(coalesce(v_insert_payload->>'title', ''), '') is null then
      v_insert_payload := jsonb_build_object('title', v_generated_title) || v_insert_payload;
    end if;

    if exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = v_form.target_module_id
        and c.column_name = 'name'
        and c.is_nullable = 'NO'
    ) and nullif(coalesce(v_insert_payload->>'name', ''), '') is null then
      v_insert_payload := jsonb_build_object('name', v_generated_title) || v_insert_payload;
    end if;

    if exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = v_form.target_module_id
        and c.column_name = 'full_name'
        and c.is_nullable = 'NO'
    ) and nullif(coalesce(v_insert_payload->>'full_name', ''), '') is null then
      v_insert_payload := jsonb_build_object('full_name', v_generated_title) || v_insert_payload;
    end if;

    if exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = v_form.target_module_id
        and c.column_name = 'subject'
        and c.is_nullable = 'NO'
    ) and nullif(coalesce(v_insert_payload->>'subject', ''), '') is null then
      v_insert_payload := jsonb_build_object('subject', v_generated_title) || v_insert_payload;
    end if;

    if exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = v_form.target_module_id
        and c.column_name = 'id'
        and c.data_type = 'uuid'
        and c.is_nullable = 'NO'
    ) and nullif(coalesce(v_insert_payload->>'id', ''), '') is null then
      v_insert_payload := jsonb_build_object('id', gen_random_uuid()) || v_insert_payload;
    end if;

    select string_agg(format('%I', c.column_name), ', ' order by c.ordinal_position),
           string_agg(format('src.%I', c.column_name), ', ' order by c.ordinal_position)
      into v_insert_columns, v_insert_select_columns
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = v_form.target_module_id
      and exists (
        select 1
        from jsonb_each(v_insert_payload) payload
        where payload.key = c.column_name
      );

    if coalesce(v_insert_columns, '') = '' then
      raise exception 'WEB_FORM_EMPTY_INSERT_PAYLOAD';
    end if;

    execute format(
      'insert into public.%1$I as t (%2$s)
       select %3$s
       from jsonb_populate_record(null::public.%1$I, $1) as src
       returning to_jsonb(t)',
      v_form.target_module_id,
      v_insert_columns,
      v_insert_select_columns
    )
    into v_target_record
    using v_insert_payload;

    if nullif(v_target_record->>'id', '') is not null then
      v_target_record_id := (v_target_record->>'id')::uuid;
    end if;

    v_record_action := 'created';
    v_submission_record_payload := v_insert_payload;
  end if;

  v_target_record_id_text := trim(coalesce(v_target_record->>'id', ''));
  if v_target_record_id_text = '' and v_target_record_id is not null then
    v_target_record_id_text := v_target_record_id::text;
  end if;

  if jsonb_typeof(v_record_files) = 'array' and jsonb_array_length(v_record_files) > 0 then
    if not exists (
      select 1
      from information_schema.tables t
      where t.table_schema = 'public'
        and t.table_name = 'record_files'
    ) then
      raise exception 'WEB_FORM_RECORD_FILES_TABLE_REQUIRED';
    end if;

    if v_target_record_id_text = '' then
      raise exception 'WEB_FORM_FILE_TARGET_ID_REQUIRED';
    end if;

    insert into public.record_files (
      org_id,
      module_id,
      record_id,
      file_url,
      file_type,
      file_name,
      mime_type,
      sort_order,
      source_module_id,
      source_record_id,
      source_record_title
    )
    select
      v_org_id,
      v_form.target_module_id,
      v_target_record_id_text,
      item.value->>'url',
      coalesce(nullif(item.value->>'file_type', ''), 'file'),
      nullif(item.value->>'name', ''),
      nullif(item.value->>'mime_type', ''),
      greatest(item.ordinality - 1, 0),
      'web_forms',
      v_form.id::text,
      nullif(trim(coalesce(v_form.name, '')), '')
    from jsonb_array_elements(v_record_files) with ordinality as item(value, ordinality)
    where trim(coalesce(item.value->>'url', '')) <> '';
  end if;

  insert into public.web_form_submissions (
    org_id, web_form_id, target_module_id, target_record_id, status,
    submission_data, record_payload, source_context
  )
  values (
    v_org_id,
    v_form.id,
    v_form.target_module_id,
    v_target_record_id,
    'submitted',
    v_submission,
    coalesce(v_submission_record_payload, v_record_payload, '{}'::jsonb),
    coalesce(v_meta, '{}'::jsonb) || jsonb_build_object(
      'record_action', v_record_action,
      'duplicate_strategy', v_duplicate_strategy,
      'duplicate_match_field', nullif(v_duplicate_match_field, ''),
      'uploaded_files_count', case when jsonb_typeof(v_record_files) = 'array' then jsonb_array_length(v_record_files) else 0 end
    )
  )
  returning id into v_submission_id;

  return jsonb_build_object(
    'submission_id', v_submission_id,
    'web_form_id', v_form.id,
    'target_module_id', v_form.target_module_id,
    'target_record_id', v_target_record_id,
    'target_record', coalesce(v_target_record, '{}'::jsonb),
    'record_action', v_record_action,
    'duplicate_strategy', v_duplicate_strategy,
    'duplicate_match_field', nullif(v_duplicate_match_field, ''),
    'uploaded_files_count', case when jsonb_typeof(v_record_files) = 'array' then jsonb_array_length(v_record_files) else 0 end,
    'success_message', coalesce(v_form.config->>'success_message', '')
  );
exception
  when others then
    if v_form.id is not null then
      insert into public.web_form_submissions (
        org_id, web_form_id, target_module_id, status,
        submission_data, record_payload, source_context, error_message
      )
      values (
        v_org_id,
        v_form.id,
        v_form.target_module_id,
        'failed',
        coalesce(v_submission, '{}'::jsonb),
        coalesce(v_submission_record_payload, v_record_payload, '{}'::jsonb),
        coalesce(v_meta, '{}'::jsonb) || jsonb_build_object(
          'record_action', v_record_action,
          'duplicate_strategy', v_duplicate_strategy,
          'duplicate_match_field', nullif(v_duplicate_match_field, ''),
          'uploaded_files_count', case when jsonb_typeof(v_record_files) = 'array' then jsonb_array_length(v_record_files) else 0 end
        ),
        sqlerrm
      );
    end if;
    raise;
end;
$_$;


--
-- Name: submit_public_web_form(text, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_public_web_form(p_slug text, p_submission jsonb, p_meta jsonb, p_hostname text, p_access_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_slug text := lower(trim(coalesce(p_slug, '')));
  v_submission jsonb := coalesce(p_submission, '{}'::jsonb);
  v_meta jsonb := coalesce(p_meta, '{}'::jsonb);
  v_org_id uuid;
  v_form public.web_forms%rowtype;
  v_result jsonb := '{}'::jsonb;
  v_token_context jsonb := '{}'::jsonb;
  v_field record;
  v_binding_type text;
  v_template_values jsonb := '{}'::jsonb;
  v_snapshot_fields jsonb := '[]'::jsonb;
  v_snapshot jsonb := '{}'::jsonb;
  v_target_record_id uuid;
  v_target_record jsonb := '{}'::jsonb;
  v_submission_id uuid;
  v_source_context jsonb := '{}'::jsonb;
  v_supports_template_target boolean := false;
  v_has_template_fields boolean := false;
begin
  if v_slug = '' then
    raise exception 'WEB_FORM_SLUG_REQUIRED';
  end if;

  select b.org_id
    into v_org_id
  from public.get_public_branding(p_hostname) b
  limit 1;

  select *
    into v_form
  from public.web_forms wf
  where wf.org_id = v_org_id
    and wf.is_active = true
    and lower(wf.route_slug) = v_slug
  order by wf.updated_at desc nulls last, wf.created_at desc nulls last
  limit 1;

  if v_form.id is null then
    raise exception 'WEB_FORM_NOT_FOUND';
  end if;

  if nullif(trim(coalesce(p_access_token, '')), '') is not null then
    v_token_context := public._resolve_web_form_link_context(p_access_token, v_form.id, v_org_id);
  end if;

  v_source_context := coalesce(v_meta, '{}'::jsonb);
  if v_token_context <> '{}'::jsonb then
    v_source_context := v_source_context
      || jsonb_build_object(
        'access_token', lower(trim(coalesce(p_access_token, ''))),
        'link_context', v_token_context
      );
  end if;

  v_supports_template_target := coalesce(v_form.target_module_id, '') in (
    'surveys',
    'marketing_leads',
    'recruitment_applicants',
    'employees'
  );

  if v_form.target_module_id = 'attendance_logs' then
    if nullif(coalesce(v_submission->>'assignee_type', ''), '') is null then
      v_submission := v_submission || jsonb_build_object('assignee_type', 'user');
    end if;

    if nullif(coalesce(v_submission->>'log_type', ''), '') is null then
      v_submission := v_submission || jsonb_build_object('log_type', 'check_in');
    end if;

    if nullif(coalesce(v_submission->>'source_type', ''), '') is null then
      v_submission := v_submission || jsonb_build_object('source_type', 'web_form');
    end if;
  end if;

  v_result := public.submit_public_web_form(p_slug, v_submission, v_meta, p_hostname);
  v_target_record_id := nullif(coalesce(v_result->>'target_record_id', ''), '')::uuid;
  v_submission_id := nullif(coalesce(v_result->>'submission_id', ''), '')::uuid;

  if not v_supports_template_target or v_target_record_id is null then
    if v_submission_id is not null and v_source_context <> coalesce(v_meta, '{}'::jsonb) then
      update public.web_form_submissions
      set source_context = coalesce(source_context, '{}'::jsonb) || v_source_context,
          updated_at = now()
      where id = v_submission_id
        and org_id = v_org_id;
    end if;

    return v_result;
  end if;

  for v_field in
    select *
    from public.web_form_fields
    where web_form_id = v_form.id
      and is_active = true
    order by sort_order asc, created_at asc
  loop
    v_binding_type := case
      when coalesce(v_field.config->>'binding_type', '') = 'template_field' then 'template_field'
      when nullif(trim(coalesce(v_field.target_field_key, '')), '') is null then 'template_field'
      else 'record_field'
    end;

    if v_binding_type = 'template_field' then
      v_has_template_fields := true;

      if v_submission ? v_field.field_key then
        v_template_values := v_template_values || jsonb_build_object(v_field.field_key, v_submission -> v_field.field_key);
      elsif v_field.default_value is not null then
        v_template_values := v_template_values || jsonb_build_object(v_field.field_key, v_field.default_value);
      end if;
    end if;

    v_snapshot_fields := v_snapshot_fields || jsonb_build_array(
      jsonb_build_object(
        'field_key', v_field.field_key,
        'label', v_field.label,
        'target_field_key', nullif(trim(coalesce(v_field.target_field_key, '')), ''),
        'field_type', v_field.field_type,
        'placeholder', v_field.placeholder,
        'help_text', v_field.help_text,
        'default_value', v_field.default_value,
        'is_required', coalesce(v_field.is_required, false),
        'is_hidden', coalesce(v_field.is_hidden, false),
        'sort_order', coalesce(v_field.sort_order, 10),
        'binding_type', v_binding_type,
        'config', coalesce(v_field.config, '{}'::jsonb)
      )
    );
  end loop;

  if v_form.target_module_id <> 'surveys' and not v_has_template_fields then
    if v_submission_id is not null then
      update public.web_form_submissions
      set source_context = coalesce(source_context, '{}'::jsonb) || v_source_context,
          updated_at = now()
      where id = v_submission_id
        and org_id = v_org_id;
    end if;

    return v_result;
  end if;

  v_snapshot := jsonb_build_object(
    'template_id', v_form.id,
    'template_name', coalesce(nullif(trim(coalesce(v_form.name, '')), ''), nullif(trim(coalesce(v_form.route_slug, '')), '')),
    'fields', v_snapshot_fields
  );

  if v_form.target_module_id = 'surveys' then
    update public.surveys s
    set survey_template_id = v_form.id,
        related_module_id = nullif(trim(coalesce(v_token_context->>'related_module_id', '')), ''),
        related_record_id = nullif(coalesce(v_token_context->>'related_record_id', ''), '')::uuid,
        template_field_values = coalesce(v_template_values, '{}'::jsonb),
        template_schema_snapshot = v_snapshot,
        updated_at = now()
    where s.id = v_target_record_id
      and s.org_id = v_org_id
    returning to_jsonb(s) into v_target_record;
  else
    execute format(
      'with updated as (
         update public.%1$I
            set survey_template_id = $1,
                template_field_values = $2,
                template_schema_snapshot = $3,
                updated_at = now()
          where id = $4
            and org_id = $5
          returning *
       )
       select to_jsonb(updated) from updated',
      v_form.target_module_id
    )
    using
      v_form.id,
      coalesce(v_template_values, '{}'::jsonb),
      v_snapshot,
      v_target_record_id,
      v_org_id
    into v_target_record;
  end if;

  if v_submission_id is not null then
    update public.web_form_submissions
    set source_context = coalesce(source_context, '{}'::jsonb) || v_source_context,
        record_payload = coalesce(record_payload, '{}'::jsonb)
          || jsonb_build_object(
            'survey_template_id', v_form.id,
            'template_field_values', coalesce(v_template_values, '{}'::jsonb),
            'template_schema_snapshot', v_snapshot,
            'related_module_id', nullif(trim(coalesce(v_token_context->>'related_module_id', '')), ''),
            'related_record_id', nullif(coalesce(v_token_context->>'related_record_id', ''), '')::uuid
          ),
        updated_at = now()
    where id = v_submission_id
      and org_id = v_org_id;
  end if;

  return v_result || jsonb_build_object(
    'target_record', coalesce(v_target_record, '{}'::jsonb)
  );
end;
$_$;


--
-- Name: support_assign_ticket(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_assign_ticket(p_ticket_id uuid, p_assignee uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.saas_support_tickets%rowtype;
begin
  if not (public.support_is_operator('support_view') and public.support_is_operator('support_manage')) then raise exception 'support_access_denied' using errcode='42501'; end if;
  select * into t from public.saas_support_tickets where id=p_ticket_id and org_id=public.support_provider_org_id() for update;
  if not found then raise exception 'support_ticket_not_found'; end if;
  if p_assignee is not null and not exists (select 1 from public.user_organization_memberships m join public.org_roles r on r.id=m.role_id
    where m.user_id=p_assignee and public.org_is_saas_admin(m.org_id) and m.is_active
      and coalesce((r.permissions -> '__saas_admin' ->> 'view')::boolean,false)
      and coalesce((r.permissions -> '__saas_admin' -> 'fields' ->> 'support_view')::boolean,true)) then raise exception 'support_assignee_invalid'; end if;
  update public.saas_support_tickets set assigned_to=p_assignee,updated_at=now() where id=t.id;
  insert into public.saas_support_events(org_id,ticket_id,actor_id,event_type,old_value,new_value)
  values(t.org_id,t.id,auth.uid(),'assignment',t.assigned_to::text,p_assignee::text);
  return jsonb_build_object('success',true);
end $$;


--
-- Name: support_broadcast_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_broadcast_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare provider_org uuid; customer_org uuid; target_org uuid;
begin
  if tg_table_name='saas_support_tickets' then provider_org:=new.org_id;customer_org:=new.customer_org_id;
  else select t.org_id,t.customer_org_id into provider_org,customer_org from public.saas_support_tickets t where t.id=new.ticket_id; end if;
  for target_org in select distinct id from public.organizations
    where id in(provider_org,customer_org) or public.org_is_saas_admin(id) loop
    perform public.kalam_broadcast_notification(public.kalam_realtime_org_topic(target_org),'support_tickets_changed','{}'::jsonb);
  end loop;
  return new;
end $$;


--
-- Name: support_can_attach_to_message(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_can_attach_to_message(p_message_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m public.saas_support_messages%rowtype; t public.saas_support_tickets%rowtype;
begin
  select * into m from public.saas_support_messages where id=p_message_id;
  if not found or m.author_id is distinct from auth.uid() then return false; end if;
  select * into t from public.saas_support_tickets where id=m.ticket_id;
  if not found then return false; end if;
  if public.support_is_operator('support_view') then return public.support_is_operator('support_reply'); end if;
  return m.visibility='customer' and public.support_customer_can(t.customer_org_id,'reply',coalesce(t.customer_user_id,t.created_by));
end $$;


--
-- Name: support_can_view_ticket(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_can_view_ticket(p_ticket_id uuid, p_internal boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.saas_support_tickets%rowtype;
begin
  select * into t from public.saas_support_tickets where id = p_ticket_id;
  if not found then return false; end if;
  if public.support_is_operator('support_view') then return true; end if;
  if p_internal then return false; end if;
  return public.support_customer_can(t.customer_org_id, 'view', coalesce(t.customer_user_id,coalesce(t.customer_user_id,t.created_by)));
end $$;


--
-- Name: support_create_activity(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_create_activity(p_ticket_id uuid, p_title text, p_assignee uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.saas_support_tickets%rowtype; task_id uuid;
begin
  if not (public.support_is_operator('support_view') and public.support_is_operator('support_reply')) then raise exception 'support_access_denied' using errcode='42501'; end if;
  select * into t from public.saas_support_tickets where id=p_ticket_id and org_id=public.support_provider_org_id();
  if not found then raise exception 'support_ticket_not_found'; end if;
  if p_assignee is not null and not exists (select 1 from public.user_organization_memberships
    where user_id=p_assignee and org_id=t.org_id and is_active) then raise exception 'support_assignee_invalid'; end if;
  insert into public.tasks(org_id,name,status,priority,description,assignee_id,assignee_type,
    source_module_id,source_record_id,related_to_module,created_by,updated_by)
  values(t.org_id,coalesce(nullif(trim(p_title),''),'پیگیری تیکت ' || public.support_ticket_code(t.ticket_no)),
    'todo','medium','گفتگوی پشتیبانی: ' || t.subject,p_assignee,case when p_assignee is null then null else 'user' end,
    'saas_support_tickets',t.id::text,'saas_support_tickets',auth.uid(),auth.uid()) returning id into task_id;
  insert into public.saas_support_events(org_id,ticket_id,actor_id,event_type,new_value)
  values(t.org_id,t.id,auth.uid(),'activity',task_id::text);
  return jsonb_build_object('id',task_id);
end $$;


--
-- Name: support_create_outgoing_ticket(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_create_outgoing_ticket(p_customer_org_id uuid, p_customer_user_id uuid, p_category text, p_subject text, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare provider uuid:=public.support_provider_org_id(); ticket public.saas_support_tickets%rowtype; message_id uuid;
begin
  if not public.support_is_operator('support_view') or not public.support_is_operator('support_reply') then raise exception 'support_access_denied' using errcode='42501'; end if;
  if provider is null or p_customer_org_id is null or p_customer_org_id=provider or public.org_is_saas_admin(p_customer_org_id) then raise exception 'support_customer_invalid'; end if;
  if not exists(select 1 from public.user_organization_memberships m left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
    where m.org_id=p_customer_org_id and m.user_id=p_customer_user_id and m.is_active
      and coalesce(r.permissions->'__support_tickets'->'view','true')<>'false'::jsonb
      and (coalesce(r.permissions->'__support_tickets'->'fields'->'view_own','true')<>'false'::jsonb
        or coalesce(r.permissions->'__support_tickets'->'fields'->'view_all','false')='true'::jsonb)) then raise exception 'support_recipient_invalid'; end if;
  if not exists(select 1 from public.saas_support_categories where code=p_category and is_active) then raise exception 'support_category_invalid'; end if;
  if length(trim(coalesce(p_subject,''))) not between 3 and 180 or length(trim(coalesce(p_body,''))) not between 1 and 10000 then raise exception 'support_content_invalid'; end if;
  insert into public.saas_support_tickets(org_id,customer_org_id,customer_user_id,created_by,category_code,subject,status,ticket_type,first_response_at)
    values(provider,p_customer_org_id,p_customer_user_id,auth.uid(),p_category,trim(p_subject),'answered','outgoing',now()) returning * into ticket;
  insert into public.saas_support_messages(org_id,ticket_id,author_id,visibility,body)
    values(provider,ticket.id,auth.uid(),'customer',trim(p_body)) returning id into message_id;
  insert into public.saas_support_events(org_id,ticket_id,actor_id,event_type,new_value)
    values(provider,ticket.id,auth.uid(),'created',ticket.status);
  perform public.kalam_upsert_notification_item(ticket.customer_org_id,'support_ticket',message_id::text,'support','reply','insert',
    'تیکت جدید از پشتیبانی '||public.support_ticket_code(ticket.ticket_no),left(trim(p_body),240),'saas_support_tickets',ticket.id::text,
    public.support_customer_notification_recipients(ticket.id),'{}'::uuid[],false,
    jsonb_build_object('path','/support/tickets/'||ticket.id::text),now());
  return jsonb_build_object('id',ticket.id,'code',public.support_ticket_code(ticket.ticket_no),'message_id',message_id);
end $$;


--
-- Name: support_create_ticket(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_create_ticket(p_category text, p_subject text, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare provider uuid := public.support_provider_org_id(); customer_org uuid := public.current_org_id(); t public.saas_support_tickets%rowtype; first_message uuid;
begin
  if provider is null or not public.support_customer_can(customer_org, 'create') then raise exception 'support_access_denied' using errcode = '42501'; end if;
  if not exists (select 1 from public.saas_support_categories where code=p_category and is_active) then raise exception 'support_category_invalid'; end if;
  if length(trim(coalesce(p_subject,''))) not between 3 and 180 or length(trim(coalesce(p_body,''))) not between 1 and 10000 then raise exception 'support_content_invalid'; end if;
  insert into public.saas_support_tickets(org_id,customer_org_id,created_by,category_code,subject)
  values(provider,customer_org,auth.uid(),p_category,trim(p_subject)) returning * into t;
  insert into public.saas_support_messages(org_id,ticket_id,author_id,visibility,body)
  values(provider,t.id,auth.uid(),'customer',trim(p_body)) returning id into first_message;
  insert into public.saas_support_events(org_id,ticket_id,actor_id,event_type,new_value)
  values(provider,t.id,auth.uid(),'created',t.status);
  return jsonb_build_object('id',t.id,'code',public.support_ticket_code(t.ticket_no),'message_id',first_message);
end $$;


--
-- Name: support_customer_can(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_customer_can(p_customer_org_id uuid, p_action text, p_creator uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare membership record; settings jsonb; fields jsonb; is_manager boolean; can_view_all boolean; can_reply_all boolean;
begin
  if auth.uid() is null or p_customer_org_id is null or public.current_org_id() is distinct from p_customer_org_id
     or public.org_is_saas_admin(p_customer_org_id) then return false; end if;
  select m.is_owner, m.software_role, r.permissions into membership
  from public.user_organization_memberships m left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
  where m.user_id=auth.uid() and m.org_id=p_customer_org_id and m.is_active limit 1;
  if not found then return false; end if;
  settings := coalesce(membership.permissions->'__support_tickets','{}'::jsonb);
  fields := coalesce(settings->'fields','{}'::jsonb);
  if coalesce((settings->>'view')::boolean,true)=false then return false; end if;
  is_manager := coalesce(membership.is_owner,false) or membership.software_role in ('admin','super_admin');
  if p_action='create' then return coalesce((fields->>'create')::boolean,true); end if;
  can_view_all := coalesce((fields->>'view_all')::boolean,is_manager);
  can_reply_all := coalesce((fields->>'reply_all')::boolean,is_manager);
  if p_creator=auth.uid() then return (coalesce((fields->>'view_own')::boolean,true) or can_view_all)
    and (p_action<>'reply' or coalesce((fields->>'reply_own')::boolean,true) or can_reply_all); end if;
  return can_view_all and (p_action<>'reply' or can_reply_all);
end $$;


--
-- Name: support_customer_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_customer_capabilities() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'can_create',public.support_customer_can(public.current_org_id(),'create'),
    'can_view_own',public.support_customer_can(public.current_org_id(),'view',auth.uid()),
    'can_view_all',public.support_customer_can(public.current_org_id(),'view',null)
  )
$$;


--
-- Name: support_customer_notification_recipients(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_customer_notification_recipients(p_ticket_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(array_agg(distinct m.user_id), '{}'::uuid[])
  from public.saas_support_tickets t
  join public.user_organization_memberships m on m.org_id=t.customer_org_id and m.is_active
  left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
  where t.id=p_ticket_id and coalesce((r.permissions -> '__support_tickets' ->> 'view')::boolean,true)
    and (m.user_id=coalesce(t.customer_user_id,t.created_by) and coalesce((r.permissions -> '__support_tickets' -> 'fields' ->> 'view_own')::boolean,true)
      or coalesce((r.permissions -> '__support_tickets' -> 'fields' ->> 'view_all')::boolean,
        m.is_owner or m.software_role in ('admin','super_admin')))
$$;


--
-- Name: support_forward_message(uuid, uuid[], uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_forward_message(p_message_id uuid, p_recipient_ids uuid[], p_attachment_ids uuid[] DEFAULT '{}'::uuid[], p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare source_message public.saas_support_messages%rowtype; t public.saas_support_tickets%rowtype;
  note_message public.saas_support_messages%rowtype; recipient uuid; attachment uuid; saved_forward uuid;
begin
  if not (public.support_is_operator('support_view') and public.support_is_operator('support_reply')) then raise exception 'support_access_denied' using errcode='42501'; end if;
  select * into source_message from public.saas_support_messages where id=p_message_id and visibility='customer';
  if not found then raise exception 'support_message_not_found'; end if;
  select * into t from public.saas_support_tickets where id=source_message.ticket_id and org_id=public.support_provider_org_id();
  if not found then raise exception 'support_ticket_not_found'; end if;
  if not exists (select 1 from public.user_organization_memberships m where m.user_id=source_message.author_id
    and m.org_id=t.customer_org_id and m.is_active) then raise exception 'support_message_not_forwardable'; end if;
  if coalesce(array_length(p_recipient_ids,1),0) < 1 or array_length(p_recipient_ids,1)>20 then raise exception 'support_recipients_invalid'; end if;
  if exists (select 1 from unnest(p_attachment_ids) aid where not exists
    (select 1 from public.saas_support_attachments a where a.id=aid and a.message_id=source_message.id)) then raise exception 'support_attachment_invalid'; end if;
  if exists (select 1 from unnest(p_recipient_ids) rid where not exists
    (select 1 from public.user_organization_memberships m join public.org_roles r on r.id=m.role_id
      where m.user_id=rid and m.org_id=t.org_id and m.is_active
        and coalesce((r.permissions -> '__saas_admin' ->> 'view')::boolean,false)
        and coalesce((r.permissions -> '__saas_admin' -> 'fields' ->> 'support_view')::boolean,true))) then raise exception 'support_recipients_invalid'; end if;
  insert into public.saas_support_messages(org_id,ticket_id,author_id,visibility,message_kind,body)
  values(t.org_id,t.id,auth.uid(),'internal','forward',coalesce(nullif(trim(p_note),''),'ارجاع پیام مشتری به همکاران'))
  returning * into note_message;
  for recipient in select distinct unnest(p_recipient_ids) loop
    insert into public.saas_support_forwards(org_id,ticket_id,source_message_id,note_message_id,recipient_id,created_by)
    values(t.org_id,t.id,source_message.id,note_message.id,recipient,auth.uid()) returning id into saved_forward;
    for attachment in select distinct unnest(coalesce(p_attachment_ids,'{}'::uuid[])) loop
      insert into public.saas_support_forward_attachments(org_id,forward_id,attachment_id) values(t.org_id,saved_forward,attachment);
    end loop;
  end loop;
  insert into public.saas_support_events(org_id,ticket_id,actor_id,event_type,details)
  values(t.org_id,t.id,auth.uid(),'forward',jsonb_build_object('source_message_id',source_message.id,'recipient_count',array_length(p_recipient_ids,1)));
  perform public.kalam_upsert_notification_item(t.org_id,'support_forward',note_message.id::text,
    'support','forward','insert','ارجاع تیکت ' || public.support_ticket_code(t.ticket_no),left(note_message.body,240),
    'saas_support_tickets',t.id::text,p_recipient_ids,'{}'::uuid[],false,
    jsonb_build_object('path','/taze-system/tickets/' || t.id::text),now());
  return jsonb_build_object('id',note_message.id);
end $$;


--
-- Name: support_get_ticket(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_get_ticket(p_ticket_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.saas_support_tickets%rowtype; operator_view boolean := public.support_is_operator('support_view');
begin
  select * into t from public.saas_support_tickets where id = p_ticket_id;
  if not found or not public.support_can_view_ticket(p_ticket_id) then raise exception 'support_access_denied' using errcode = '42501'; end if;
  return jsonb_build_object(
    'ticket', jsonb_build_object('id',t.id,'code',public.support_ticket_code(t.ticket_no),'subject',t.subject,
      'ticket_type',t.ticket_type,'customer_user_id',t.customer_user_id,'category_code',t.category_code,
      'category_title',(select title from public.saas_support_categories where code=t.category_code),
      'status',t.status,'customer_org_id',t.customer_org_id,
      'customer_org_name',(select name from public.organizations where id=t.customer_org_id),
      'created_by',t.created_by,'assigned_to',case when operator_view then t.assigned_to else null end,
      'created_at',t.created_at,'first_response_at',t.first_response_at,'closed_at',t.closed_at),
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'body',m.body,'visibility',m.visibility,
      'message_kind',m.message_kind,'author_id',m.author_id,'author_name',coalesce(p.full_name,p.email,'کاربر'),
      'created_at',m.created_at,'attachments',
        (select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'file_name',a.file_name,'mime_type',a.mime_type,'file_size',a.file_size,'object_path',a.object_path)), '[]'::jsonb)
         from public.saas_support_attachments a where a.message_id=m.id)) order by m.created_at,m.id), '[]'::jsonb)
      from public.saas_support_messages m left join public.profiles p on p.id=m.author_id
      where m.ticket_id=t.id and (operator_view or m.visibility='customer')),
    'forwards', case when operator_view then (select coalesce(jsonb_agg(jsonb_build_object(
      'id',f.id,'source_message_id',f.source_message_id,'note_message_id',f.note_message_id,
      'recipient_id',f.recipient_id,'attachment_ids',(select coalesce(jsonb_agg(fa.attachment_id),'[]'::jsonb)
        from public.saas_support_forward_attachments fa where fa.forward_id=f.id))), '[]'::jsonb)
      from public.saas_support_forwards f where f.ticket_id=t.id) else '[]'::jsonb end,
    'events', (select coalesce(jsonb_agg(jsonb_build_object('event_type',e.event_type,'old_value',e.old_value,
      'new_value',e.new_value,'created_at',e.created_at) order by e.created_at), '[]'::jsonb)
      from public.saas_support_events e where e.ticket_id=t.id and (operator_view or e.event_type='status'))
  );
end $$;


--
-- Name: support_is_operator(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_is_operator(p_permission text DEFAULT 'support_view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare role_permissions jsonb; base jsonb; explicit_value text; active_org uuid := public.current_org_id();
begin
  if auth.uid() is null or active_org is null or not public.org_is_saas_admin(active_org) then return false; end if;
  if not public.current_user_has_saas_admin_permission() then return false; end if;
  select r.permissions into role_permissions from public.user_organization_memberships m join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
  where m.user_id=auth.uid() and m.org_id=active_org and m.is_active limit 1;
  base := coalesce(role_permissions->'__saas_admin','{}'::jsonb);
  if p_permission<>'support_view' and coalesce((base->'fields'->>'support_view')::boolean,true)=false then return false; end if;
  explicit_value := base->'fields'->>p_permission;
  if explicit_value is not null then return explicit_value::boolean; end if;
  return case when p_permission='support_view' then true else coalesce((base->>'edit')::boolean,false) end;
end $$;


--
-- Name: support_list_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_list_categories() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when auth.uid() is null then '[]'::jsonb else coalesce(jsonb_agg(jsonb_build_object('code',code,'title',title) order by sort_order), '[]'::jsonb) end
  from public.saas_support_categories where is_active
$$;


--
-- Name: support_list_operators(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_list_operators() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when public.support_is_operator('support_view') then
    coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'name',coalesce(p.full_name,p.email,'اپراتور')) order by p.full_name),'[]'::jsonb)
    else '[]'::jsonb end
  from public.user_organization_memberships m join public.org_roles r on r.id=m.role_id
  join public.profiles p on p.id=m.user_id
  where public.org_is_saas_admin(m.org_id) and m.is_active
    and coalesce((r.permissions -> '__saas_admin' ->> 'view')::boolean,false)
    and coalesce((r.permissions -> '__saas_admin' -> 'fields' ->> 'support_view')::boolean,true)
$$;


--
-- Name: support_list_tickets(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_list_tickets(p_status text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare is_operator boolean := public.support_is_operator('support_view'); current_org uuid := public.current_org_id(); result jsonb;
begin
  if auth.uid() is null or current_org is null then raise exception 'support_access_denied' using errcode = '42501'; end if;
  if not is_operator and not public.support_customer_can(current_org, 'create') then
    -- A role may be allowed to view existing tickets without creating new ones.
    if not exists (select 1 from public.saas_support_tickets t where t.customer_org_id = current_org
      and public.support_customer_can(current_org, 'view', coalesce(t.customer_user_id,coalesce(t.customer_user_id,t.created_by)))) then
      return '[]'::jsonb;
    end if;
  end if;
  select coalesce(jsonb_agg(row_data order by (row_data ->> 'last_message_at') desc), '[]'::jsonb) into result
  from (
    select jsonb_build_object(
      'id', t.id, 'code', public.support_ticket_code(t.ticket_no), 'subject', t.subject,
      'ticket_type',t.ticket_type,'customer_user_id',t.customer_user_id,'category_code', t.category_code, 'category_title', c.title, 'status', t.status,
      'customer_org_id', t.customer_org_id, 'customer_org_name', o.name, 'created_by', t.created_by,
      'assigned_to', case when is_operator then t.assigned_to else null end,
      'created_at', t.created_at, 'last_message_at', t.last_message_at,
      'first_response_at', t.first_response_at, 'closed_at', t.closed_at,
      'unread_count', (select count(*) from public.saas_support_messages m
        where m.ticket_id = t.id and m.author_id <> auth.uid()
          and (is_operator or m.visibility = 'customer')
          and m.created_at > coalesce((select r.last_read_at from public.saas_support_reads r
            where r.ticket_id = t.id and r.user_id = auth.uid()), '-infinity'::timestamptz))
    ) as row_data
    from public.saas_support_tickets t
    join public.saas_support_categories c on c.code = t.category_code
    join public.organizations o on o.id = t.customer_org_id
    where (is_operator and t.org_id = public.support_provider_org_id() or
      not is_operator and t.customer_org_id = current_org and public.support_customer_can(current_org, 'view', coalesce(t.customer_user_id,coalesce(t.customer_user_id,t.created_by))))
      and (p_status is null or t.status = p_status)
      and (nullif(trim(coalesce(p_search, '')), '') is null or t.subject ilike '%' || trim(p_search) || '%'
        or public.support_ticket_code(t.ticket_no) ilike '%' || trim(p_search) || '%')
    order by t.last_message_at desc, t.id desc
    limit least(greatest(coalesce(p_limit, 50), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  ) listed;
  return result;
end $$;


--
-- Name: support_mark_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_mark_read(p_ticket_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.saas_support_tickets%rowtype;
begin
  select * into t from public.saas_support_tickets where id=p_ticket_id;
  if not found or not public.support_can_view_ticket(p_ticket_id) then raise exception 'support_access_denied' using errcode='42501'; end if;
  insert into public.saas_support_reads(org_id,ticket_id,user_id,last_read_at) values(t.org_id,t.id,auth.uid(),now())
  on conflict(ticket_id,user_id) do update set last_read_at=excluded.last_read_at;
end $$;


--
-- Name: support_notify_new_ticket(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_notify_new_ticket() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare admin_org record; recipients uuid[];
begin
  for admin_org in select id from public.organizations where public.org_is_saas_admin(id) loop
    select coalesce(array_agg(distinct m.user_id),'{}'::uuid[]) into recipients
    from public.user_organization_memberships m join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
    where m.org_id=admin_org.id and m.is_active
      and coalesce((r.permissions->'__saas_admin'->>'view')::boolean,false)
      and coalesce((r.permissions->'__saas_admin'->'fields'->>'support_view')::boolean,true);
    if cardinality(recipients)>0 then
      perform public.kalam_upsert_notification_item(admin_org.id,'support_ticket_created',new.id::text,
        'support','ticket','insert','تیکت جدید '||public.support_ticket_code(new.ticket_no),left(new.subject,240),
        'saas_support_tickets',new.id::text,recipients,'{}'::uuid[],false,
        jsonb_build_object('path','/taze-system/tickets/'||new.id::text),new.created_at);
    end if;
  end loop;
  return new;
end $$;


--
-- Name: support_provider_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_provider_org_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select s.org_id from public.saas_org_settings s
  where s.is_billing_provider = true and s.status = 'active'
    and (s.provisioning_source = 'saas_provider' or lower(coalesce(s.slug,'')) = 'panel')
  order by case when s.provisioning_source = 'saas_provider' then 0 else 1 end, s.created_at limit 1
$$;


--
-- Name: support_register_attachment(uuid, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_register_attachment(p_message_id uuid, p_object_path text, p_file_name text, p_mime_type text, p_file_size bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m public.saas_support_messages%rowtype; a public.saas_support_attachments%rowtype;
begin
  select * into m from public.saas_support_messages where id=p_message_id;
  if not found or not public.support_can_attach_to_message(m.id)
    or p_object_path not like m.ticket_id::text || '/' || m.id::text || '/%'
    or p_file_size not between 1 and 20971520 then raise exception 'support_attachment_invalid' using errcode='42501'; end if;
  if not exists (select 1 from storage.objects where bucket_id='saas-support-private' and name=p_object_path
    and metadata->>'mimetype'=p_mime_type and metadata->>'size'=p_file_size::text) then
    raise exception 'support_attachment_missing'; end if;
  insert into public.saas_support_attachments(org_id,ticket_id,message_id,object_path,file_name,mime_type,file_size)
  values(m.org_id,m.ticket_id,m.id,p_object_path,left(trim(p_file_name),255),p_mime_type,p_file_size)
  returning * into a;
  return jsonb_build_object('id',a.id,'file_name',a.file_name,'object_path',a.object_path);
end $$;


--
-- Name: support_search_customers(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_search_customers(p_search text DEFAULT NULL::text, p_org_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.support_is_operator('support_view') or not public.support_is_operator('support_reply') then raise exception 'support_access_denied' using errcode='42501'; end if;
  if p_org_id is null then
    return (select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name)),'[]') from
      (select o.id,o.name from public.organizations o where not public.org_is_saas_admin(o.id)
        and (nullif(trim(p_search),'') is null or o.name ilike '%'||trim(p_search)||'%')
        order by o.name,o.id limit 30) matched);
  end if;
  if public.org_is_saas_admin(p_org_id) then raise exception 'support_customer_invalid'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name)),'[]') from
    (select m.user_id id,coalesce(nullif(p.full_name,''),'کاربر سازمان') name
      from public.user_organization_memberships m join public.profiles p on p.id=m.user_id
      left join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
      where m.org_id=p_org_id and m.is_active
        and coalesce(r.permissions->'__support_tickets'->'view','true')<>'false'::jsonb
        and (coalesce(r.permissions->'__support_tickets'->'fields'->'view_own','true')<>'false'::jsonb
          or coalesce(r.permissions->'__support_tickets'->'fields'->'view_all','false')='true'::jsonb)
        and (nullif(trim(p_search),'') is null or p.full_name ilike '%'||trim(p_search)||'%')
      order by name,m.user_id limit 30) matched);
end $$;


--
-- Name: support_send_message(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_send_message(p_ticket_id uuid, p_body text, p_internal boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.saas_support_tickets%rowtype; m public.saas_support_messages%rowtype;
  operator_reply boolean := public.support_is_operator('support_view') and public.support_is_operator('support_reply');
  next_status text;
begin
  select * into t from public.saas_support_tickets where id=p_ticket_id for update;
  if not found then raise exception 'support_ticket_not_found'; end if;
  if operator_reply then null;
  elsif p_internal or not public.support_customer_can(t.customer_org_id,'reply',coalesce(t.customer_user_id,t.created_by)) then
    raise exception 'support_access_denied' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_body,''))) not between 1 and 10000 then raise exception 'support_content_invalid'; end if;
  insert into public.saas_support_messages(org_id,ticket_id,author_id,visibility,message_kind,body)
  values(t.org_id,t.id,auth.uid(),case when p_internal then 'internal' else 'customer' end,
    case when p_internal then 'note' else 'reply' end,trim(p_body)) returning * into m;
  insert into public.saas_support_events(org_id,ticket_id,actor_id,event_type,new_value,details)
  values(t.org_id,t.id,auth.uid(),'message',m.id::text,jsonb_build_object('visibility',m.visibility));
  if not p_internal then
    next_status := case when operator_reply then 'answered' else 'waiting_operator' end;
    update public.saas_support_tickets set
      status=next_status,
      first_response_at=case when operator_reply then coalesce(first_response_at,now()) else first_response_at end,
      closed_at=null, last_message_at=m.created_at, updated_at=now()
    where id=t.id;
    if t.status is distinct from next_status then
      insert into public.saas_support_events(org_id,ticket_id,actor_id,event_type,old_value,new_value)
      values(t.org_id,t.id,auth.uid(),'status',t.status,next_status);
    end if;
    if operator_reply then
      perform public.kalam_upsert_notification_item(t.customer_org_id,'support_ticket',m.id::text,'support','reply','insert',
        'پاسخ جدید به تیکت ' || public.support_ticket_code(t.ticket_no),left(m.body,240),'saas_support_tickets',t.id::text,
        public.support_customer_notification_recipients(t.id), '{}'::uuid[], false, jsonb_build_object('path','/support/tickets/' || t.id::text),m.created_at);
    end if;
  else
    update public.saas_support_tickets set last_message_at=m.created_at,updated_at=now() where id=t.id;
  end if;
  return jsonb_build_object('id',m.id,'created_at',m.created_at);
end $$;


--
-- Name: support_set_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_set_status(p_ticket_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.saas_support_tickets%rowtype;
begin
  if not (public.support_is_operator('support_view') and public.support_is_operator('support_manage')) then raise exception 'support_access_denied' using errcode='42501'; end if;
  if p_status not in ('waiting_operator','in_review','answered','closed') then raise exception 'support_status_invalid'; end if;
  select * into t from public.saas_support_tickets where id=p_ticket_id and org_id=public.support_provider_org_id() for update;
  if not found then raise exception 'support_ticket_not_found'; end if;
  if t.status <> p_status then
    update public.saas_support_tickets set status=p_status,closed_at=case when p_status='closed' then now() else null end,
      updated_at=now() where id=t.id;
    insert into public.saas_support_events(org_id,ticket_id,actor_id,event_type,old_value,new_value)
    values(t.org_id,t.id,auth.uid(),'status',t.status,p_status);
    perform public.kalam_upsert_notification_item(t.customer_org_id,'support_ticket_status',gen_random_uuid()::text,
      'support','status','update','وضعیت تیکت ' || public.support_ticket_code(t.ticket_no) || ' تغییر کرد',
      case p_status when 'waiting_operator' then 'منتظر پاسخ اوپراتور' when 'in_review' then 'در حال بررسی'
        when 'answered' then 'پاسخ داده شده' else 'بسته شده' end,
      'saas_support_tickets',t.id::text,public.support_customer_notification_recipients(t.id),'{}'::uuid[],false,
      jsonb_build_object('path','/support/tickets/' || t.id::text),now());
  end if;
  return jsonb_build_object('success',true);
end $$;


--
-- Name: support_storage_can_read(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_storage_can_read(p_path text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.saas_support_attachments a
    join public.saas_support_messages m on m.id=a.message_id
    where a.object_path=p_path and public.support_can_view_ticket(a.ticket_id,m.visibility='internal'))
$$;


--
-- Name: support_storage_can_upload(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_storage_can_upload(p_path text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare ticket_part text := split_part(p_path,'/',1); message_part text := split_part(p_path,'/',2); m public.saas_support_messages%rowtype;
begin
  if ticket_part !~* '^[0-9a-f-]{36}$' or message_part !~* '^[0-9a-f-]{36}$'
    or nullif(split_part(p_path,'/',3),'') is null or split_part(p_path,'/',4) <> '' then return false; end if;
  select * into m from public.saas_support_messages where id=message_part::uuid and ticket_id=ticket_part::uuid;
  return found and public.support_can_attach_to_message(m.id);
end $_$;


--
-- Name: support_ticket_code(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_ticket_code(p_ticket_no bigint) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$ select 'TS-' || lpad(p_ticket_no::text, 6, '0') $$;


--
-- Name: support_unread_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_unread_total() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare active_org uuid := public.current_org_id(); operator_view boolean := public.support_is_operator('support_view'); result integer;
begin
  if auth.uid() is null or active_org is null then return 0; end if;
  select count(*)::integer into result from public.saas_support_messages m
  join public.saas_support_tickets t on t.id=m.ticket_id
  where m.author_id<>auth.uid()
    and m.created_at>coalesce((select r.last_read_at from public.saas_support_reads r where r.ticket_id=t.id and r.user_id=auth.uid()),'-infinity'::timestamptz)
    and ((operator_view and t.org_id=public.support_provider_org_id()) or
      (not operator_view and t.customer_org_id=active_org and m.visibility='customer' and public.support_customer_can(active_org,'view',coalesce(t.customer_user_id,t.created_by))));
  return result;
end $$;


--
-- Name: support_workflow_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_workflow_context() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare provider uuid:=public.support_provider_org_id(); permission jsonb;
begin
  if not public.support_is_operator('support_view') or not public.support_is_operator('support_workflows') then
    raise exception 'support_access_denied' using errcode='42501';
  end if;
  select r.permissions->'__saas_admin' into permission from public.user_organization_memberships m
    join public.org_roles r on r.id=m.role_id and r.org_id=m.org_id
    where m.user_id=auth.uid() and m.org_id=provider and m.is_active limit 1;
  if not found or not(coalesce(permission->'view','false')='true'::jsonb or coalesce(permission->'edit','false')='true'::jsonb)
    or permission->'fields'->'support_view'='false'::jsonb
    or coalesce(permission->'fields'->'support_workflows',permission->'edit','false')<>'true'::jsonb then
    raise exception 'support_workflow_membership_required' using errcode='42501';
  end if;
  return provider;
end $$;


--
-- Name: sync_activity_performance_entries(date, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_activity_performance_entries(p_period_start date, p_period_end date, p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_entry jsonb;
  v_employee_id uuid;
  v_task_id uuid;
  v_source_key text;
  v_existing public.payroll_calculation_entries%rowtype;
  v_result jsonb := '[]'::jsonb;
begin
  if v_org_id is null then raise exception 'organization_context_required'; end if;
  if p_period_start is null or p_period_end is null or p_period_end < p_period_start then
    raise exception 'invalid_payroll_period';
  end if;
  if jsonb_typeof(coalesce(p_entries, '[]'::jsonb)) <> 'array' then
    raise exception 'invalid_activity_performance_entries';
  end if;

  for v_entry in select value from jsonb_array_elements(p_entries) as item(value) loop
    v_employee_id := nullif(trim(v_entry->>'employee_id'), '')::uuid;
    v_task_id := nullif(trim(v_entry->>'task_id'), '')::uuid;
    v_source_key := nullif(trim(v_entry->>'source_key'), '');
    if v_employee_id is null or v_task_id is null or v_source_key is null
      or v_source_key !~ '^activity_performance:[^:]+:[^:]+:[^:]+:[^:]+$' then
      raise exception 'invalid_activity_performance_entry';
    end if;
    if not exists (select 1 from public.employees where id = v_employee_id and org_id = v_org_id) then
      raise exception 'activity_performance_employee_not_found';
    end if;
    if not exists (select 1 from public.tasks where id = v_task_id and org_id = v_org_id) then
      raise exception 'activity_performance_task_not_found';
    end if;

    -- قفل منبع مانع محاسبهٔ هم‌زمان از تب عملکرد و ویزارد فیش می‌شود.
    perform pg_advisory_xact_lock(hashtext('activity-performance:' || v_org_id::text || ':' || v_source_key));
    select * into v_existing
    from public.payroll_calculation_entries
    where org_id = v_org_id
      and employee_id = v_employee_id
      and source_type = 'activity_performance'
      and source_key = v_source_key
      and status <> 'voided'
    for update;

    if found and v_existing.status = 'included_in_payroll' then
      v_result := v_result || jsonb_build_array(jsonb_build_object('id', v_existing.id, 'source_key', v_source_key, 'status', 'included_in_payroll'));
      continue;
    end if;

    if found then
      update public.payroll_calculation_entries
      set
        period_start = p_period_start,
        period_end = p_period_end,
        entry_type = coalesce(nullif(trim(v_entry->>'entry_type'), ''), 'activity_performance'),
        source_module_id = 'tasks',
        source_record_id = v_task_id,
        title = coalesce(nullif(v_entry->>'title', ''), 'محاسبه عملکرد'),
        amount = coalesce((v_entry->>'amount')::numeric, 0),
        quantity = nullif(trim(v_entry->>'quantity'), '')::numeric,
        rate = nullif(trim(v_entry->>'rate'), '')::numeric,
        status = 'proposed',
        assignee_id = nullif(trim(v_entry->>'assignee_id'), '')::uuid,
        details = coalesce(v_entry->'details', '{}'::jsonb),
        updated_at = now()
      where id = v_existing.id and org_id = v_org_id;
      v_result := v_result || jsonb_build_array(jsonb_build_object('id', v_existing.id, 'source_key', v_source_key, 'status', 'proposed'));
    else
      insert into public.payroll_calculation_entries (
        org_id, employee_id, period_start, period_end, entry_type, source_type,
        source_key, source_module_id, source_record_id, title, amount, quantity,
        rate, status, assignee_id, details
      ) values (
        v_org_id, v_employee_id, p_period_start, p_period_end,
        coalesce(nullif(trim(v_entry->>'entry_type'), ''), 'activity_performance'),
        'activity_performance', v_source_key, 'tasks', v_task_id,
        coalesce(nullif(v_entry->>'title', ''), 'محاسبه عملکرد'),
        coalesce((v_entry->>'amount')::numeric, 0),
        nullif(trim(v_entry->>'quantity'), '')::numeric,
        nullif(trim(v_entry->>'rate'), '')::numeric,
        'proposed', nullif(trim(v_entry->>'assignee_id'), '')::uuid,
        coalesce(v_entry->'details', '{}'::jsonb)
      ) returning id into v_existing.id;
      v_result := v_result || jsonb_build_array(jsonb_build_object('id', v_existing.id, 'source_key', v_source_key, 'status', 'proposed'));
    end if;
  end loop;
  return v_result;
end;
$_$;


--
-- Name: sync_activity_performance_entries_v2(date, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

