--
-- Name: sync_assets_from_finalized_expense(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_assets_from_finalized_expense() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item jsonb;
  v_row_key text;
  v_title text;
  v_quantity numeric;
  v_unit integer;
begin
  if new.org_id is null or new.status not in ('approved', 'paid', 'posted') then
    return new;
  end if;

  for v_item in
    select value from jsonb_array_elements(coalesce(new.items, '[]'::jsonb))
  loop
    if not coalesce((v_item ->> 'is_asset')::boolean, false) then
      continue;
    end if;

    v_title := nullif(btrim(coalesce(v_item ->> 'description', '')), '');
    v_row_key := nullif(btrim(coalesce(v_item ->> 'row_key', '')), '');
    begin
      v_quantity := nullif(btrim(coalesce(v_item ->> 'quantity', '')), '')::numeric;
    exception when invalid_text_representation then
      v_quantity := null;
    end;

    if v_title is null then
      raise exception 'برای ثبت مال، شرح ردیف هزینه الزامی است.';
    end if;
    if v_row_key is null then
      raise exception 'شناسه داخلی ردیف مال معتبر نیست؛ ردیف هزینه را دوباره ذخیره کنید.';
    end if;
    if v_quantity is null or v_quantity <= 0 or trunc(v_quantity) <> v_quantity then
      raise exception 'تعداد ردیف ثبت به‌عنوان مال باید یک عدد صحیحِ بزرگ‌تر از صفر باشد.';
    end if;

    for v_unit in 1..v_quantity::integer loop
      insert into public.assets (
        org_id, name, status, source_expense_document_id,
        source_expense_row_key, source_expense_unit_index, metadata
      )
      values (
        new.org_id, v_title, 'available', new.id,
        v_row_key, v_unit,
        jsonb_build_object('source', 'expense_document', 'source_item_key', v_row_key, 'source_unit_index', v_unit)
      )
      on conflict (org_id, source_expense_document_id, source_expense_row_key, source_expense_unit_index) do nothing;
    end loop;
  end loop;

  return new;
end;
$$;


--
-- Name: sync_attendance_actual_times(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_attendance_actual_times() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_base_date date;
  v_check_in_ts timestamptz;
  v_check_out_ts timestamptz;
  v_duration_seconds numeric;
begin
  if new.attendance_date is null then
    new.attendance_date := coalesce(
      case when new.manual_check_in_time is not null then (new.manual_check_in_time at time zone 'Asia/Tehran')::date else null end,
      case when new.manual_check_out_time is not null then (new.manual_check_out_time at time zone 'Asia/Tehran')::date else null end,
      case when new.actual_check_in_time is not null then (new.actual_check_in_time at time zone 'Asia/Tehran')::date else null end,
      case when new.actual_check_out_time is not null then (new.actual_check_out_time at time zone 'Asia/Tehran')::date else null end,
      case when new.occurred_at is not null then (new.occurred_at at time zone 'Asia/Tehran')::date else null end
    );
  end if;

  if new.check_in_time is null then
    new.check_in_time := coalesce(
      case when new.manual_check_in_time is not null then (new.manual_check_in_time at time zone 'Asia/Tehran')::time else null end,
      case when new.actual_check_in_time is not null then (new.actual_check_in_time at time zone 'Asia/Tehran')::time else null end,
      case
        when coalesce(new.log_type, 'check_in') = 'check_in' and new.occurred_at is not null
          then (new.occurred_at at time zone 'Asia/Tehran')::time
        else null
      end
    );
  end if;

  if new.check_out_time is null then
    new.check_out_time := coalesce(
      case when new.manual_check_out_time is not null then (new.manual_check_out_time at time zone 'Asia/Tehran')::time else null end,
      case when new.actual_check_out_time is not null then (new.actual_check_out_time at time zone 'Asia/Tehran')::time else null end,
      case
        when coalesce(new.log_type, '') = 'check_out' and new.occurred_at is not null
          then (new.occurred_at at time zone 'Asia/Tehran')::time
        else null
      end
    );
  end if;

  v_base_date := coalesce(
    new.attendance_date,
    case
      when coalesce(new.occurred_at, new.manual_check_in_time, new.manual_check_out_time, new.actual_check_in_time, new.actual_check_out_time) is not null
        then (coalesce(new.occurred_at, new.manual_check_in_time, new.manual_check_out_time, new.actual_check_in_time, new.actual_check_out_time) at time zone 'Asia/Tehran')::date
      else null
    end,
    (now() at time zone 'Asia/Tehran')::date
  );

  if new.attendance_date is null then
    new.attendance_date := v_base_date;
  end if;

  v_check_in_ts := coalesce(
    new.manual_check_in_time,
    public.combine_attendance_date_time(v_base_date, new.check_in_time),
    new.actual_check_in_time
  );

  v_check_out_ts := coalesce(
    new.manual_check_out_time,
    public.combine_attendance_date_time(v_base_date, new.check_out_time),
    new.actual_check_out_time
  );

  if new.manual_check_in_time is null and new.check_in_time is not null then
    new.manual_check_in_time := public.combine_attendance_date_time(v_base_date, new.check_in_time);
    v_check_in_ts := coalesce(v_check_in_ts, new.manual_check_in_time);
  end if;

  if new.manual_check_out_time is null and new.check_out_time is not null then
    new.manual_check_out_time := public.combine_attendance_date_time(v_base_date, new.check_out_time);
    v_check_out_ts := coalesce(v_check_out_ts, new.manual_check_out_time);
  end if;

  if coalesce(new.log_type, 'check_in') = 'check_in' and (new.check_in_time is not null or new.manual_check_in_time is not null) then
    new.occurred_at := coalesce(v_check_in_ts, new.occurred_at, now());
  elsif coalesce(new.log_type, '') = 'check_out' and (new.check_out_time is not null or new.manual_check_out_time is not null) then
    new.occurred_at := coalesce(v_check_out_ts, new.occurred_at, now());
  end if;

  if coalesce(new.log_type, '') = 'check_in' then
    new.actual_check_in_time := coalesce(new.actual_check_in_time, new.occurred_at, v_check_in_ts, now());
    if tg_op = 'UPDATE' and new.actual_check_out_time is null and old.actual_check_out_time is not null then
      new.actual_check_out_time := old.actual_check_out_time;
    end if;
  elsif coalesce(new.log_type, '') = 'check_out' then
    new.actual_check_out_time := coalesce(new.actual_check_out_time, new.occurred_at, v_check_out_ts, now());
    if tg_op = 'UPDATE' and new.actual_check_in_time is null and old.actual_check_in_time is not null then
      new.actual_check_in_time := old.actual_check_in_time;
    end if;
  end if;

  if v_check_in_ts is not null and v_check_out_ts is not null and v_check_out_ts >= v_check_in_ts and (v_check_out_ts - v_check_in_ts) < interval '1 day' then
    v_duration_seconds := extract(epoch from (v_check_out_ts - v_check_in_ts));
  else
    v_duration_seconds := null;
  end if;

  if new.presence_minutes is null then
    if new.presence_hours is not null then
      new.presence_minutes := round((new.presence_hours * 60)::numeric)::integer;
    elsif v_duration_seconds is not null then
      new.presence_minutes := floor(v_duration_seconds / 60)::integer;
    end if;
  end if;

  if new.presence_hours is null then
    if new.presence_minutes is not null and new.presence_minutes between 0 and 1440 then
      new.presence_hours := round((new.presence_minutes::numeric / 60), 2);
    elsif v_duration_seconds is not null then
      new.presence_hours := round((v_duration_seconds / 3600)::numeric, 2);
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: sync_bot_direct_chat_identity(text, uuid, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_bot_direct_chat_identity(p_target_module_id text, p_target_record_id uuid, p_channel_type text, p_chat_id text DEFAULT NULL::text, p_previous_chat_id text DEFAULT NULL::text, p_username text DEFAULT NULL::text, p_phone_number text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_thread_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_auth_user_id uuid := auth.uid();
  v_channel_type text := nullif(btrim(coalesce(p_channel_type, '')), '');
  v_target_module_id text := nullif(btrim(coalesce(p_target_module_id, '')), '');
  v_chat_id text := nullif(btrim(coalesce(p_chat_id, '')), '');
  v_previous_chat_id text := nullif(btrim(coalesce(p_previous_chat_id, '')), '');
  v_current_chat_id text;
  v_stale_chat_id text;
  v_profile_id uuid;
  v_display_candidate text;
  v_final_display_name text;
  v_binding_id uuid;
  v_thread_id uuid;
  v_metadata jsonb := case when p_thread_metadata is null then null else coalesce(p_thread_metadata, '{}'::jsonb) end;
begin
  if v_org_id is null then
    raise exception 'سازمان فعال پیدا نشد.' using errcode = '42501';
  end if;

  if v_auth_user_id is null then
    raise exception 'برای اتصال مخاطب بات باید وارد سیستم شوید.' using errcode = '42501';
  end if;

  if v_channel_type not in ('telegram', 'bale', 'rubika') then
    raise exception 'کانال بات معتبر نیست.' using errcode = '22023';
  end if;

  if v_target_module_id not in ('customers', 'suppliers', 'employees') then
    raise exception 'نوع مخاطب برای اتصال بات معتبر نیست.' using errcode = '22023';
  end if;

  if v_target_module_id = 'customers' then
    select
      case v_channel_type
        when 'telegram' then nullif(btrim(coalesce(c.telegram_chat_id, '')), '')
        when 'bale' then nullif(btrim(coalesce(c.bale_chat_id, '')), '')
        else nullif(btrim(coalesce(c.rubika_chat_id, '')), '')
      end,
      nullif(btrim(coalesce(c.full_name, c.business_name, c.legal_name, c.system_code, '')), '')
    into v_current_chat_id, v_display_candidate
    from public.customers c
    where c.id = p_target_record_id
      and c.org_id = v_org_id
    for update;

    if not found then
      raise exception 'مخاطب انتخاب‌شده پیدا نشد.' using errcode = 'P0002';
    end if;

    update public.customers
    set
      telegram_chat_id = case when v_channel_type = 'telegram' then v_chat_id else telegram_chat_id end,
      bale_chat_id = case when v_channel_type = 'bale' then v_chat_id else bale_chat_id end,
      rubika_chat_id = case when v_channel_type = 'rubika' then v_chat_id else rubika_chat_id end
    where id = p_target_record_id
      and org_id = v_org_id;
  elsif v_target_module_id = 'suppliers' then
    select
      case v_channel_type
        when 'telegram' then nullif(btrim(coalesce(s.telegram_chat_id, '')), '')
        when 'bale' then nullif(btrim(coalesce(s.bale_chat_id, '')), '')
        else nullif(btrim(coalesce(s.rubika_chat_id, '')), '')
      end,
      coalesce(
        nullif(btrim(coalesce(s.business_name, '')), ''),
        nullif(btrim(concat_ws(' ', s.first_name, s.last_name)), ''),
        nullif(btrim(coalesce(s.system_code, '')), '')
      )
    into v_current_chat_id, v_display_candidate
    from public.suppliers s
    where s.id = p_target_record_id
      and s.org_id = v_org_id
    for update;

    if not found then
      raise exception 'تأمین‌کننده انتخاب‌شده پیدا نشد.' using errcode = 'P0002';
    end if;

    update public.suppliers
    set
      telegram_chat_id = case when v_channel_type = 'telegram' then v_chat_id else telegram_chat_id end,
      bale_chat_id = case when v_channel_type = 'bale' then v_chat_id else bale_chat_id end,
      rubika_chat_id = case when v_channel_type = 'rubika' then v_chat_id else rubika_chat_id end
    where id = p_target_record_id
      and org_id = v_org_id;
  else
    select
      case v_channel_type
        when 'telegram' then nullif(btrim(coalesce(e.telegram_chat_id, '')), '')
        when 'bale' then nullif(btrim(coalesce(e.bale_chat_id, '')), '')
        else nullif(btrim(coalesce(e.rubika_chat_id, '')), '')
      end,
      e.related_profile_id,
      coalesce(
        nullif(btrim(coalesce(e.full_name, '')), ''),
        nullif(btrim(concat_ws(' ', e.first_name, e.last_name)), ''),
        nullif(btrim(coalesce(e.system_code, '')), ''),
        nullif(btrim(coalesce(e.legacy_system_code, '')), '')
      )
    into v_current_chat_id, v_profile_id, v_display_candidate
    from public.employees e
    where e.id = p_target_record_id
      and e.org_id = v_org_id
    for update;

    if not found then
      raise exception 'کارمند انتخاب‌شده پیدا نشد.' using errcode = 'P0002';
    end if;

    update public.employees
    set
      telegram_chat_id = case when v_channel_type = 'telegram' then v_chat_id else telegram_chat_id end,
      bale_chat_id = case when v_channel_type = 'bale' then v_chat_id else bale_chat_id end,
      rubika_chat_id = case when v_channel_type = 'rubika' then v_chat_id else rubika_chat_id end
    where id = p_target_record_id
      and org_id = v_org_id;

    if v_profile_id is not null then
      update public.profiles
      set
        telegram_chat_id = case when v_channel_type = 'telegram' then v_chat_id else telegram_chat_id end,
        bale_chat_id = case when v_channel_type = 'bale' then v_chat_id else bale_chat_id end,
        rubika_chat_id = case when v_channel_type = 'rubika' then v_chat_id else rubika_chat_id end
      where id = v_profile_id
        and org_id = v_org_id;
    end if;
  end if;

  v_final_display_name := coalesce(nullif(btrim(coalesce(p_display_name, '')), ''), v_display_candidate);

  if v_chat_id is not null then
    insert into public.bot_chat_identity_bindings (
      org_id,
      channel_type,
      chat_id,
      target_module_id,
      target_record_id,
      profile_id,
      display_name,
      username,
      phone_number,
      last_seen_at,
      metadata
    )
    values (
      v_org_id,
      v_channel_type,
      v_chat_id,
      v_target_module_id,
      p_target_record_id,
      v_profile_id,
      v_final_display_name,
      nullif(btrim(coalesce(p_username, '')), ''),
      nullif(btrim(coalesce(p_phone_number, '')), ''),
      now(),
      coalesce(v_metadata, '{}'::jsonb)
    )
    on conflict (org_id, channel_type, chat_id) do update
    set
      target_module_id = excluded.target_module_id,
      target_record_id = excluded.target_record_id,
      profile_id = coalesce(excluded.profile_id, public.bot_chat_identity_bindings.profile_id),
      display_name = coalesce(excluded.display_name, public.bot_chat_identity_bindings.display_name),
      username = coalesce(excluded.username, public.bot_chat_identity_bindings.username),
      phone_number = coalesce(excluded.phone_number, public.bot_chat_identity_bindings.phone_number),
      last_seen_at = now(),
      metadata = case
        when v_metadata is null then public.bot_chat_identity_bindings.metadata
        else coalesce(public.bot_chat_identity_bindings.metadata, '{}'::jsonb) || v_metadata
      end,
      updated_at = now()
    returning id into v_binding_id;

    insert into public.counterparty_bot_direct_threads (
      org_id,
      binding_id,
      channel_type,
      chat_id,
      target_module_id,
      target_record_id,
      customer_id,
      supplier_id,
      employee_id,
      profile_id,
      display_name,
      username,
      phone_number,
      last_seen_at,
      metadata
    )
    values (
      v_org_id,
      v_binding_id,
      v_channel_type,
      v_chat_id,
      v_target_module_id,
      p_target_record_id,
      case when v_target_module_id = 'customers' then p_target_record_id else null end,
      case when v_target_module_id = 'suppliers' then p_target_record_id else null end,
      case when v_target_module_id = 'employees' then p_target_record_id else null end,
      v_profile_id,
      v_final_display_name,
      nullif(btrim(coalesce(p_username, '')), ''),
      nullif(btrim(coalesce(p_phone_number, '')), ''),
      now(),
      coalesce(v_metadata, '{}'::jsonb)
    )
    on conflict (org_id, channel_type, chat_id) do update
    set
      binding_id = excluded.binding_id,
      target_module_id = excluded.target_module_id,
      target_record_id = excluded.target_record_id,
      customer_id = excluded.customer_id,
      supplier_id = excluded.supplier_id,
      employee_id = excluded.employee_id,
      profile_id = coalesce(excluded.profile_id, public.counterparty_bot_direct_threads.profile_id),
      display_name = coalesce(excluded.display_name, public.counterparty_bot_direct_threads.display_name),
      username = coalesce(excluded.username, public.counterparty_bot_direct_threads.username),
      phone_number = coalesce(excluded.phone_number, public.counterparty_bot_direct_threads.phone_number),
      last_seen_at = now(),
      metadata = case
        when v_metadata is null then public.counterparty_bot_direct_threads.metadata
        else coalesce(public.counterparty_bot_direct_threads.metadata, '{}'::jsonb) || v_metadata
      end,
      updated_at = now()
    returning id into v_thread_id;
  end if;

  for v_stale_chat_id in
    select distinct stale.value
    from unnest(array[v_previous_chat_id, v_current_chat_id]) as stale(value)
    where stale.value is not null
      and (v_chat_id is null or stale.value <> v_chat_id)
  loop
    delete from public.bot_chat_identity_bindings
    where org_id = v_org_id
      and channel_type = v_channel_type
      and chat_id = v_stale_chat_id
      and target_module_id = v_target_module_id
      and target_record_id = p_target_record_id;

    update public.counterparty_bot_direct_threads
    set
      binding_id = null,
      target_module_id = null,
      target_record_id = null,
      customer_id = null,
      supplier_id = null,
      employee_id = null,
      profile_id = null,
      updated_at = now()
    where org_id = v_org_id
      and channel_type = v_channel_type
      and chat_id = v_stale_chat_id
      and target_module_id = v_target_module_id
      and target_record_id = p_target_record_id;
  end loop;

  return jsonb_build_object(
    'display_name', v_final_display_name,
    'profile_id', v_profile_id,
    'previous_chat_id', v_current_chat_id,
    'chat_id', v_chat_id,
    'binding_id', v_binding_id,
    'direct_thread_id', v_thread_id
  );
end;
$$;


--
-- Name: sync_commission_review_cases(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_commission_review_cases(p_employee_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_org uuid := public.current_org_id();
begin
  if v_org is null or public.current_user_has_role_permission_entry('payroll_slips', 'edit', null, true) is not true then
    raise exception 'commission_calculation_not_allowed';
  end if;
  if (select public.current_org_has_plan_feature('advanced_commission', true)) is not true then
    raise exception 'پورسانت پیشرفته در پلن سازمان فعال نیست.' using errcode = '42501';
  end if;
  if not exists(select 1 from public.employees where org_id = v_org and id = p_employee_id) then
    raise exception 'commission_employee_not_found';
  end if;
  for v_id in select id from public.cheques where org_id = v_org and status in ('bounced', 'returned') loop
    perform public.capture_commission_cheque_review(v_id, p_employee_id);
  end loop;
end;
$$;


--
-- Name: sync_content_calendar_public_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_content_calendar_public_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' and (new.public_slug is null or btrim(new.public_slug) = '') then
    new.public_slug := public.generate_short_share_token(10);
  elsif tg_op = 'UPDATE' and new.public_slug is distinct from old.public_slug then
    new.public_slug := old.public_slug;
  end if;
  new.public_link := '/calendar/' || new.public_slug;
  return new;
end;
$$;


--
-- Name: sync_counterparty_bot_direct_thread_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_counterparty_bot_direct_thread_activity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  preview_text text;
begin
  preview_text := nullif(trim(coalesce(new.content_text, new.file_name, '')), '');

  update public.counterparty_bot_direct_threads
  set
    last_message_at = coalesce(new.created_at, now()),
    last_message_preview = coalesce(preview_text, last_message_preview),
    last_seen_at = greatest(coalesce(last_seen_at, '-infinity'::timestamptz), coalesce(new.created_at, now())),
    last_inbound_at = case
      when new.direction = 'inbound' then greatest(coalesce(last_inbound_at, '-infinity'::timestamptz), coalesce(new.created_at, now()))
      else last_inbound_at
    end,
    last_outbound_at = case
      when new.direction = 'outbound' then greatest(coalesce(last_outbound_at, '-infinity'::timestamptz), coalesce(new.created_at, now()))
      else last_outbound_at
    end,
    updated_at = now()
  where id = new.direct_thread_id;

  return new;
end;
$$;


--
-- Name: sync_customer_club_credit_from_entity_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_club_credit_from_entity_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.sync_customer_club_credit_group(case coalesce(new.recipient_module_id, old.recipient_module_id) when 'customers' then 'customer' when 'suppliers' then 'supplier' else 'employee' end, coalesce(new.recipient_record_id, old.recipient_record_id));
  return coalesce(new, old);
end;
$$;


--
-- Name: sync_customer_club_credit_from_legacy_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_club_credit_from_legacy_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.sync_customer_club_credit_group('customer', coalesce(new.customer_id, old.customer_id));
  return coalesce(new, old);
end;
$$;


--
-- Name: sync_customer_club_credit_from_person_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_club_credit_from_person_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_type text := case tg_table_name when 'customers' then 'customer' when 'suppliers' then 'supplier' else 'employee' end;
begin
  perform public.sync_customer_club_credit_group(v_type, new.id);
  if tg_table_name = 'customers' then
    if old.linked_supplier_id is not null then perform public.sync_customer_club_credit_group('supplier', old.linked_supplier_id); end if;
    if old.linked_employee_id is not null then perform public.sync_customer_club_credit_group('employee', old.linked_employee_id); end if;
  elsif tg_table_name = 'suppliers' then
    if old.linked_customer_id is not null then perform public.sync_customer_club_credit_group('customer', old.linked_customer_id); end if;
    if old.linked_employee_id is not null then perform public.sync_customer_club_credit_group('employee', old.linked_employee_id); end if;
  else
    if old.linked_customer_id is not null then perform public.sync_customer_club_credit_group('customer', old.linked_customer_id); end if;
    if old.linked_supplier_id is not null then perform public.sync_customer_club_credit_group('supplier', old.linked_supplier_id); end if;
  end if;
  return new;
end;
$$;


--
-- Name: sync_customer_club_credit_group(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_club_credit_group(p_entity_type text, p_entity_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_total numeric(18,2) := 0;
begin
  if v_org_id is null or p_entity_id is null or lower(trim(coalesce(p_entity_type, ''))) not in ('customer', 'supplier', 'employee') then
    return 0;
  end if;

  with scope as (
    select * from public.get_customer_club_credit_scope(v_org_id, lower(trim(p_entity_type)), p_entity_id)
  ), sums as (
    select coalesce(sum(case when l.entry_type = 'debit' then -l.amount else l.amount end), 0)::numeric as amount
    from public.customer_loyalty_ledger l
    join scope s on s.entity_type = 'customer' and s.entity_id = l.customer_id
    where l.org_id = v_org_id
    union all
    select coalesce(sum(case when e.entry_type = 'debit' then -e.amount else e.amount end), 0)::numeric
    from public.customer_club_entity_credits e
    join scope s on s.entity_type = e.recipient_module_id and s.entity_id = e.recipient_record_id
    where e.org_id = v_org_id
  ) select coalesce(sum(amount), 0) into v_total from sums;

  update public.customers c set loyalty_credit_balance = v_total
  where c.org_id = v_org_id and c.id in (select entity_id from public.get_customer_club_credit_scope(v_org_id, lower(trim(p_entity_type)), p_entity_id) where entity_type = 'customer');
  update public.suppliers s set loyalty_credit_balance = v_total
  where s.org_id = v_org_id and s.id in (select entity_id from public.get_customer_club_credit_scope(v_org_id, lower(trim(p_entity_type)), p_entity_id) where entity_type = 'supplier');
  update public.employees e set loyalty_credit_balance = v_total
  where e.org_id = v_org_id and e.id in (select entity_id from public.get_customer_club_credit_scope(v_org_id, lower(trim(p_entity_type)), p_entity_id) where entity_type = 'employee');
  return v_total;
end;
$$;


--
-- Name: sync_customer_club_levels(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_club_levels(p_customer_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_customer_id uuid;
  v_customer record;
  v_settings jsonb := '{}'::jsonb;
  v_enabled boolean := true;
  v_rank text;
  v_old_rank text;
  v_processed integer := 0;
  v_silver jsonb := '{}'::jsonb;
  v_gold jsonb := '{}'::jsonb;
  v_vip jsonb := '{}'::jsonb;
begin
  if v_org_id is null or coalesce(array_length(p_customer_ids, 1), 0) = 0 then return 0; end if;

  select coalesce(nullif(to_jsonb(cs)->'customer_leveling_config', 'null'::jsonb), '{}'::jsonb)
    into v_settings
  from public.company_settings cs where cs.org_id = v_org_id limit 1;
  if v_settings = '{}'::jsonb then
    select coalesce(nullif(settings->'customer_leveling_config', 'null'::jsonb), '{}'::jsonb)
      into v_settings
    from public.integration_settings
    where org_id = v_org_id and connection_type = 'site' limit 1;
  end if;
  v_enabled := coalesce((v_settings->>'enabled')::boolean, true);
  v_silver := coalesce(v_settings->'silver', '{}'::jsonb);
  v_gold := coalesce(v_settings->'gold', '{}'::jsonb);
  v_vip := coalesce(v_settings->'vip', '{}'::jsonb);

  for v_customer_id in
    select id from public.customers where org_id = v_org_id and id = any(p_customer_ids) order by id
  loop
    perform public.sync_customer_financial_stats(v_customer_id);
    select * into v_customer from public.customers where id = v_customer_id and org_id = v_org_id;
    if not found then continue; end if;

    v_rank := 'normal';
    if v_enabled then
      if coalesce(v_customer.purchase_count, 0) >= coalesce((v_vip->>'min_purchase_count')::numeric, 15)
         and coalesce(v_customer.loyalty_total_spend, 0) >= coalesce((v_vip->>'min_total_spend')::numeric, 300000000)
         and coalesce(v_customer.acquaintance_days, 0) >= coalesce((v_vip->>'min_acquaintance_days')::numeric, 365) then v_rank := 'vip';
      elsif coalesce(v_customer.purchase_count, 0) >= coalesce((v_gold->>'min_purchase_count')::numeric, 8)
         and coalesce(v_customer.loyalty_total_spend, 0) >= coalesce((v_gold->>'min_total_spend')::numeric, 120000000)
         and coalesce(v_customer.acquaintance_days, 0) >= coalesce((v_gold->>'min_acquaintance_days')::numeric, 120) then v_rank := 'gold';
      elsif coalesce(v_customer.purchase_count, 0) >= coalesce((v_silver->>'min_purchase_count')::numeric, 3)
         and coalesce(v_customer.loyalty_total_spend, 0) >= coalesce((v_silver->>'min_total_spend')::numeric, 30000000)
         and coalesce(v_customer.acquaintance_days, 0) >= coalesce((v_silver->>'min_acquaintance_days')::numeric, 30) then v_rank := 'silver';
      end if;
    end if;

    v_old_rank := coalesce(v_customer.rank, 'normal');
    update public.customers set rank = v_rank
    where id = v_customer_id and org_id = v_org_id and rank is distinct from v_rank;
    if v_old_rank is distinct from v_rank then
      perform public.log_customer_club_event(
        'level_changed', 'تغییر سطح مشتری', v_customer_id, null, null, null,
        'customers', v_customer_id, jsonb_build_object('from', v_old_rank, 'to', v_rank)
      );
    end if;
    v_processed := v_processed + 1;
  end loop;
  return v_processed;
end;
$$;


--
-- Name: sync_customer_club_rank(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_club_rank(p_customer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id(); v_customer record; v_settings jsonb := '{}'::jsonb;
  v_enabled boolean := true; v_rank text := 'normal';
  v_silver jsonb := '{}'::jsonb; v_gold jsonb := '{}'::jsonb; v_vip jsonb := '{}'::jsonb;
  v_old_rank text;
begin
  if v_org_id is null or p_customer_id is null then return; end if;
  select * into v_customer from public.customers where id = p_customer_id and org_id = v_org_id;
  if not found then return; end if;
  select coalesce(to_jsonb(cs)->'customer_leveling_config', '{}'::jsonb) into v_settings
  from public.company_settings cs where cs.org_id = v_org_id limit 1;
  v_enabled := coalesce((v_settings->>'enabled')::boolean, true);
  if not v_enabled then v_rank := 'normal'; else
    v_silver := coalesce(v_settings->'silver', '{}'::jsonb); v_gold := coalesce(v_settings->'gold', '{}'::jsonb); v_vip := coalesce(v_settings->'vip', '{}'::jsonb);
    if coalesce(v_customer.purchase_count, 0) >= coalesce((v_vip->>'min_purchase_count')::numeric, 15) and coalesce(v_customer.loyalty_total_spend, 0) >= coalesce((v_vip->>'min_total_spend')::numeric, 300000000) and coalesce(v_customer.acquaintance_days, 0) >= coalesce((v_vip->>'min_acquaintance_days')::numeric, 365) then v_rank := 'vip';
    elsif coalesce(v_customer.purchase_count, 0) >= coalesce((v_gold->>'min_purchase_count')::numeric, 8) and coalesce(v_customer.loyalty_total_spend, 0) >= coalesce((v_gold->>'min_total_spend')::numeric, 120000000) and coalesce(v_customer.acquaintance_days, 0) >= coalesce((v_gold->>'min_acquaintance_days')::numeric, 120) then v_rank := 'gold';
    elsif coalesce(v_customer.purchase_count, 0) >= coalesce((v_silver->>'min_purchase_count')::numeric, 3) and coalesce(v_customer.loyalty_total_spend, 0) >= coalesce((v_silver->>'min_total_spend')::numeric, 30000000) and coalesce(v_customer.acquaintance_days, 0) >= coalesce((v_silver->>'min_acquaintance_days')::numeric, 30) then v_rank := 'silver'; end if;
  end if;
  v_old_rank := coalesce(v_customer.rank, 'normal');
  update public.customers set rank = v_rank where id = p_customer_id and org_id = v_org_id and rank is distinct from v_rank;
  if v_old_rank is distinct from v_rank then perform public.log_customer_club_event('level_changed', 'تغییر سطح مشتری', p_customer_id, null, null, null, 'customers', p_customer_id, jsonb_build_object('from', v_old_rank, 'to', v_rank)); end if;
end;
$$;


--
-- Name: sync_customer_club_stats_and_rank_from_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_club_stats_and_rank_from_invoice() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op in ('INSERT', 'UPDATE') then
    perform public.sync_customer_financial_stats(new.customer_id); perform public.sync_customer_club_rank(new.customer_id);
    if tg_op = 'UPDATE' and old.customer_id is distinct from new.customer_id then perform public.sync_customer_financial_stats(old.customer_id); perform public.sync_customer_club_rank(old.customer_id); end if;
    return new;
  end if;
  perform public.sync_customer_financial_stats(old.customer_id); perform public.sync_customer_club_rank(old.customer_id); return old;
end; $$;


--
-- Name: sync_customer_financial_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_financial_stats(p_customer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
begin
  if v_org_id is null then return; end if;
  perform public._sync_customer_financial_stats_for_org(v_org_id, p_customer_id);
end;
$$;


--
-- Name: sync_customer_financial_stats_for_entity(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_financial_stats_for_entity(p_entity_type text, p_entity_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_entity_type text := lower(trim(coalesce(p_entity_type, '')));
  v_customer_id uuid;
begin
  if v_org_id is null or p_entity_id is null or v_entity_type not in ('customer', 'supplier', 'employee') then return; end if;
  if v_entity_type = 'customer' and not exists(select 1 from public.customers where id = p_entity_id and org_id = v_org_id) then return; end if;
  if v_entity_type = 'supplier' and not exists(select 1 from public.suppliers where id = p_entity_id and org_id = v_org_id) then return; end if;
  if v_entity_type = 'employee' and not exists(select 1 from public.employees where id = p_entity_id and org_id = v_org_id) then return; end if;

  for v_customer_id in
    select entity_id
    from public.get_customer_club_credit_scope(v_org_id, v_entity_type, p_entity_id)
    where entity_type = 'customer'
  loop
    perform public._sync_customer_financial_stats_for_org(v_org_id, v_customer_id);
  end loop;
end;
$$;


--
-- Name: sync_customer_financial_stats_from_customer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_financial_stats_from_customer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform public.sync_customer_financial_stats(new.id);
  return new;
end;
$$;


--
-- Name: sync_customer_financial_stats_from_financial_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_financial_stats_from_financial_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op <> 'DELETE' then perform public.sync_customer_financial_stats_from_financial_source_row(to_jsonb(new)); end if;
  if tg_op <> 'INSERT' then perform public.sync_customer_financial_stats_from_financial_source_row(to_jsonb(old)); end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: sync_customer_financial_stats_from_financial_source_row(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_financial_stats_from_financial_source_row(p_row jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_customer_id uuid := nullif(coalesce(p_row ->> 'customer_id', ''), '')::uuid;
  v_supplier_id uuid := nullif(coalesce(p_row ->> 'supplier_id', ''), '')::uuid;
  v_employee_id uuid := nullif(coalesce(p_row ->> 'employee_id', ''), '')::uuid;
  v_source_id uuid;
begin
  if p_row is null then return; end if;
  if v_customer_id is not null then perform public.sync_customer_financial_stats_for_entity('customer', v_customer_id); end if;
  if v_supplier_id is not null then perform public.sync_customer_financial_stats_for_entity('supplier', v_supplier_id); end if;
  if v_employee_id is not null then perform public.sync_customer_financial_stats_for_entity('employee', v_employee_id); end if;

  v_source_id := nullif(coalesce(p_row ->> 'sales_invoice_id', ''), '')::uuid;
  if v_source_id is not null then
    select customer_id into v_customer_id from public.invoices where id = v_source_id and org_id = public.current_org_id();
    if v_customer_id is not null then perform public.sync_customer_financial_stats_for_entity('customer', v_customer_id); end if;
  end if;
  v_source_id := nullif(coalesce(p_row ->> 'purchase_invoice_id', ''), '')::uuid;
  if v_source_id is not null then
    select supplier_id into v_supplier_id from public.purchase_invoices where id = v_source_id and org_id = public.current_org_id();
    if v_supplier_id is not null then perform public.sync_customer_financial_stats_for_entity('supplier', v_supplier_id); end if;
  end if;
  v_source_id := nullif(coalesce(p_row ->> 'expense_document_id', ''), '')::uuid;
  if v_source_id is not null then
    select customer_id, supplier_id, employee_id into v_customer_id, v_supplier_id, v_employee_id from public.expense_documents where id = v_source_id and org_id = public.current_org_id();
    if v_customer_id is not null then perform public.sync_customer_financial_stats_for_entity('customer', v_customer_id); end if;
    if v_supplier_id is not null then perform public.sync_customer_financial_stats_for_entity('supplier', v_supplier_id); end if;
    if v_employee_id is not null then perform public.sync_customer_financial_stats_for_entity('employee', v_employee_id); end if;
  end if;
  v_source_id := nullif(coalesce(p_row ->> 'payroll_slip_id', ''), '')::uuid;
  if v_source_id is not null then
    select employee_id into v_employee_id from public.payroll_slips where id = v_source_id and org_id = public.current_org_id();
    if v_employee_id is not null then perform public.sync_customer_financial_stats_for_entity('employee', v_employee_id); end if;
  end if;
  v_source_id := nullif(coalesce(p_row ->> 'employee_advance_id', ''), '')::uuid;
  if v_source_id is not null then
    select employee_id into v_employee_id from public.employee_advances where id = v_source_id and org_id = public.current_org_id();
    if v_employee_id is not null then perform public.sync_customer_financial_stats_for_entity('employee', v_employee_id); end if;
  end if;
end;
$$;


--
-- Name: sync_customer_financial_stats_from_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_financial_stats_from_invoice() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op in ('INSERT', 'UPDATE') then
    perform public.sync_customer_financial_stats(new.customer_id);
    if tg_op = 'UPDATE' and old.customer_id is distinct from new.customer_id then
      perform public.sync_customer_financial_stats(old.customer_id);
    end if;
    return new;
  end if;

  perform public.sync_customer_financial_stats(old.customer_id);
  return old;
end;
$$;


--
-- Name: sync_customer_financial_stats_from_person_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_financial_stats_from_person_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_entity_type text := case tg_table_name when 'customers' then 'customer' when 'suppliers' then 'supplier' else 'employee' end;
begin
  if tg_op <> 'DELETE' then perform public.sync_customer_financial_stats_for_entity(v_entity_type, new.id); end if;
  if tg_op <> 'INSERT' then perform public.sync_customer_financial_stats_for_entity(v_entity_type, old.id); end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


