--
-- Name: sync_customer_supplier_mirror(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_supplier_mirror() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_supplier_id uuid;
  v_business_name text;
begin

  if tg_op = 'UPDATE' and row(new.org_id, new.business_name, new.first_name, new.last_name, new.mobile_1, new.mobile_2, new.phone, new.prefix, new.province, new.city, new.address, new.location, new.image_url, new.is_supplier, new.linked_supplier_id)
     is not distinct from row(old.org_id, old.business_name, old.first_name, old.last_name, old.mobile_1, old.mobile_2, old.phone, old.prefix, old.province, old.city, old.address, old.location, old.image_url, old.is_supplier, old.linked_supplier_id) then
    return new;
  end if;
  if pg_trigger_depth() > 1 then
    return new;
  end if;

  if not coalesce(new.is_supplier, false) then
    if new.linked_supplier_id is not null then
      update public.suppliers s
      set is_customer = false
      where s.id = new.linked_supplier_id
        and s.org_id = new.org_id
        and s.linked_customer_id = new.id;
    end if;
    return new;
  end if;

  v_supplier_id := new.linked_supplier_id;
  v_business_name := nullif(trim(coalesce(new.business_name, '')), '');
  if v_business_name is null then
    v_business_name := nullif(trim(concat_ws(' ', new.first_name, new.last_name)), '');
  end if;
  if v_business_name is null then
    v_business_name := 'طرف حساب';
  end if;

  if v_supplier_id is not null then
    perform 1 from public.suppliers where id = v_supplier_id and org_id = new.org_id;
    if not found then
      v_supplier_id := null;
    end if;
  end if;

  if v_supplier_id is null then
    select s.id
    into v_supplier_id
    from public.suppliers s
    where s.linked_customer_id = new.id
      and s.org_id = new.org_id
    limit 1;
  end if;

  if v_supplier_id is null then
    insert into public.suppliers (
      org_id,
      business_name,
      first_name,
      last_name,
      mobile_1,
      mobile_2,
      phone,
      prefix,
      province,
      city,
      address,
      location,
      image_url,
      is_customer,
      linked_customer_id,
      created_by,
      updated_by
    ) values (
      new.org_id,
      v_business_name,
      new.first_name,
      new.last_name,
      new.mobile_1,
      new.mobile_2,
      new.phone,
      new.prefix,
      new.province,
      new.city,
      new.address,
      new.location,
      new.image_url,
      true,
      new.id,
      new.created_by,
      new.updated_by
    )
    returning id into v_supplier_id;
  else
    update public.suppliers s
    set
      org_id = coalesce(new.org_id, s.org_id),
      business_name = coalesce(v_business_name, s.business_name),
      first_name = coalesce(new.first_name, s.first_name),
      last_name = coalesce(new.last_name, s.last_name),
      mobile_1 = coalesce(new.mobile_1, s.mobile_1),
      mobile_2 = coalesce(new.mobile_2, s.mobile_2),
      phone = coalesce(new.phone, s.phone),
      prefix = coalesce(new.prefix, s.prefix),
      province = coalesce(new.province, s.province),
      city = coalesce(new.city, s.city),
      address = coalesce(new.address, s.address),
      location = coalesce(new.location, s.location),
      image_url = coalesce(new.image_url, s.image_url),
      is_customer = true,
      linked_customer_id = new.id,
      updated_by = coalesce(new.updated_by, s.updated_by),
      updated_at = now()
    where s.id = v_supplier_id and s.org_id = new.org_id;
  end if;

  update public.customers set linked_supplier_id = v_supplier_id
  where id = new.id and org_id = new.org_id
    and linked_supplier_id is distinct from v_supplier_id;
  new.linked_supplier_id := v_supplier_id;
  return new;
end;
$$;


--
-- Name: sync_delivery_form_public_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_delivery_form_public_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.public_token is null or btrim(new.public_token) = '' then
      new.public_token := substr(encode(sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text as bytea)), 'hex'), 1, 48);
    end if;
    if new.public_slug is null or btrim(new.public_slug) = '' then
      new.public_slug := public.generate_delivery_share_token(10);
    end if;
  else
    if new.public_token is distinct from old.public_token then
      new.public_token := old.public_token;
    end if;
    if new.public_slug is distinct from old.public_slug then
      new.public_slug := old.public_slug;
    end if;
  end if;

  new.public_link := '/d/' || coalesce(new.public_slug, new.public_token);
  return new;
end;
$$;


--
-- Name: sync_employee_advance_summary_from_payments(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_employee_advance_summary_from_payments() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_payment jsonb;
  v_payment_status text;
  v_has_payment_status boolean := false;
  v_payment_count integer := 0;
  v_paid_amount numeric := 0;
  v_total_amount numeric := greatest(0, coalesce(new.amount, 0));
begin
  select exists (
    select 1
    from jsonb_array_elements(coalesce(new.payments, '[]'::jsonb)) as payment(value)
    where payment.value ? 'status'
  ) into v_has_payment_status;

  select jsonb_array_length(coalesce(new.payments, '[]'::jsonb))
  into v_payment_count;

  for v_payment in
    select value from jsonb_array_elements(coalesce(new.payments, '[]'::jsonb))
  loop
    v_payment_status := lower(trim(coalesce(v_payment->>'status', '')));
    if v_has_payment_status
      and v_payment_status <> ''
      and v_payment_status not in ('received', 'paid', 'approved', 'cleared')
    then
      continue;
    end if;
    v_paid_amount := v_paid_amount + public.employee_advance_payment_amount(v_payment);
  end loop;

  -- سازگاری با مساعده‌های قدیمی که پرداخت‌شان پیش از ثبت ریزپرداخت‌ها ثبت شده است.
  -- با وجود حتی یک ریزپرداخت، فقط همان ریزپرداخت‌ها مرجع مبلغ پرداختی هستند.
  if v_payment_count = 0 then
    v_paid_amount := greatest(0, coalesce(new.paid_amount, 0));
  end if;

  new.amount := v_total_amount;
  new.paid_amount := least(v_total_amount, v_paid_amount);
  new.remaining_amount := greatest(0, v_total_amount - new.paid_amount);
  return new;
end;
$$;


--
-- Name: sync_employee_counterparty_financial_role_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_employee_counterparty_financial_role_links() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin

  if tg_op = 'UPDATE' then
    if tg_table_name in ('customers', 'suppliers') then
      if row(new.org_id, new.is_employee, new.linked_employee_id)
         is not distinct from row(old.org_id, old.is_employee, old.linked_employee_id) then
        return new;
      end if;
    elsif tg_table_name = 'employees' then
      if row(new.org_id, new.is_customer, new.is_supplier, new.linked_customer_id, new.linked_supplier_id)
         is not distinct from row(old.org_id, old.is_customer, old.is_supplier, old.linked_customer_id, old.linked_supplier_id) then
        return new;
      end if;
    end if;
  end if;
  if pg_trigger_depth() > 1 then return new; end if;

  if tg_table_name = 'customers' then
    if coalesce(new.is_employee, false) and new.linked_employee_id is not null then
      update public.employees
      set is_customer = true, linked_customer_id = new.id, updated_at = now()
      where id = new.linked_employee_id and org_id = new.org_id;
    elsif not coalesce(new.is_employee, false) then
      update public.employees set is_customer = false, updated_at = now()
      where linked_customer_id = new.id and org_id = new.org_id;
    end if;
  elsif tg_table_name = 'suppliers' then
    if coalesce(new.is_employee, false) and new.linked_employee_id is not null then
      update public.employees
      set is_supplier = true, linked_supplier_id = new.id, updated_at = now()
      where id = new.linked_employee_id and org_id = new.org_id;
    elsif not coalesce(new.is_employee, false) then
      update public.employees set is_supplier = false, updated_at = now()
      where linked_supplier_id = new.id and org_id = new.org_id;
    end if;
  elsif tg_table_name = 'employees' then
    if coalesce(new.is_customer, false) and new.linked_customer_id is not null then
      update public.customers
      set is_employee = true, linked_employee_id = new.id, updated_at = now()
      where id = new.linked_customer_id and org_id = new.org_id;
    end if;
    if coalesce(new.is_supplier, false) and new.linked_supplier_id is not null then
      update public.suppliers
      set is_employee = true, linked_employee_id = new.id, updated_at = now()
      where id = new.linked_supplier_id and org_id = new.org_id;
    end if;
    if not coalesce(new.is_customer, false) then
      update public.customers set is_employee = false, updated_at = now()
      where linked_employee_id = new.id and org_id = new.org_id;
    end if;
    if not coalesce(new.is_supplier, false) then
      update public.suppliers set is_employee = false, updated_at = now()
      where linked_employee_id = new.id and org_id = new.org_id;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: sync_invoice_public_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_invoice_public_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.public_token is null or btrim(new.public_token) = '' then
      new.public_token := substr(
        encode(sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text as bytea)), 'hex'),
        1,
        48
      );
    end if;
    if new.public_slug is null or btrim(new.public_slug) = '' then
      new.public_slug := public.generate_short_share_token(10);
    end if;
  elsif new.public_token is distinct from old.public_token then
    new.public_token := old.public_token;
  elsif new.public_slug is distinct from old.public_slug then
    new.public_slug := old.public_slug;
  end if;

  if tg_table_name = 'invoices' then
    new.public_link := '/i/' || coalesce(new.public_slug, new.public_token);
  else
    new.public_link := '/i/' || coalesce(new.public_slug, new.public_token) || '?t=p';
  end if;

  return new;
end;
$$;


--
-- Name: sync_leave_request_employee_names(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_leave_request_employee_names() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_name text := '';
begin
  if new.employee_id is null then
    return new;
  end if;

  select trim(coalesce(e.full_name, ''))
    into v_employee_name
  from public.employees e
  where e.id = new.employee_id
    and (new.org_id is null or e.org_id = new.org_id)
  limit 1;

  if v_employee_name = '' then
    return new;
  end if;

  if nullif(trim(coalesce(new.employee_name, '')), '') is null then
    new.employee_name := v_employee_name;
  end if;

  if nullif(trim(coalesce(new.requester_name, '')), '') is null then
    new.requester_name := v_employee_name;
  end if;

  return new;
end;
$$;


--
-- Name: sync_online_account_card_entity_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_online_account_card_entity_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.entity_type = 'customer' then
    update public.customers set online_account_card_link = new.public_link
    where id = new.entity_id and org_id = new.org_id and online_account_card_link is distinct from new.public_link;
  elsif new.entity_type = 'supplier' then
    update public.suppliers set online_account_card_link = new.public_link
    where id = new.entity_id and org_id = new.org_id and online_account_card_link is distinct from new.public_link;
  elsif new.entity_type = 'employee' then
    update public.employees set online_account_card_link = new.public_link
    where id = new.entity_id and org_id = new.org_id and online_account_card_link is distinct from new.public_link;
  end if;
  return new;
end;
$$;


--
-- Name: sync_online_account_card_public_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_online_account_card_public_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.public_token is null or btrim(new.public_token) = '' then
      new.public_token := substr(encode(sha256(cast(gen_random_uuid()::text || clock_timestamp()::text || random()::text as bytea)), 'hex'), 1, 48);
    end if;
    if new.public_slug is null or btrim(new.public_slug) = '' then
      new.public_slug := public.generate_short_share_token(10);
    end if;
  elsif new.public_token is distinct from old.public_token then
    new.public_token := old.public_token;
  elsif new.public_slug is distinct from old.public_slug then
    new.public_slug := old.public_slug;
  end if;
  new.public_link := '/account/' || coalesce(new.public_slug, new.public_token);
  return new;
end;
$$;


--
-- Name: sync_payroll_slip_employee_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_payroll_slip_employee_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.employee_id is null then
    new.employee_national_code := null;
    new.employee_father_name := null;
    new.employee_marital_status := null;
    new.employee_military_service_status := null;
    new.employee_children_count := null;
    new.employee_insurance_number := null;
    return new;
  end if;

  select
    employee.national_code,
    employee.father_name,
    employee.marital_status,
    employee.military_service_status,
    employee.children_count,
    employee.insurance_number
  into
    new.employee_national_code,
    new.employee_father_name,
    new.employee_marital_status,
    new.employee_military_service_status,
    new.employee_children_count,
    new.employee_insurance_number
  from public.employees as employee
  where employee.id = new.employee_id
    and employee.org_id = new.org_id;

  return new;
end;
$$;


--
-- Name: sync_payroll_slip_summary_from_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_payroll_slip_summary_from_lines() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_line jsonb;
  v_payment jsonb;
  v_line_type text;
  v_line_key text;
  v_amount numeric;
  v_base_salary numeric := 0;
  v_task_wage_total numeric := 0;
  v_bonus_total numeric := 0;
  v_deduction_total numeric := 0;
  v_employee_insurance numeric := 0;
  v_employer_insurance numeric := 0;
  v_paid_amount numeric := 0;
  v_has_payment_status boolean := false;
  v_has_employer_insurance boolean := false;
  v_payment_status text;
begin
  for v_line in
    select value from jsonb_array_elements(coalesce(new.lines, '[]'::jsonb))
  loop
    v_line_type := lower(trim(coalesce(v_line ->> 'line_type', 'earning')));
    v_line_key := lower(trim(coalesce(v_line ->> 'key', '')));

    -- ردیف‌های مساعدهٔ قدیمی در جدول اقلام باقی مانده‌اند تا تاریخچه قابل
    -- پیگیری باشد، اما اثر مالی‌شان فقط از جدول پرداخت‌های فیش خوانده می‌شود.
    if v_line_key = 'employee_advance'
      or nullif(trim(coalesce(v_line -> 'metadata' ->> 'employee_advance_id', '')), '') is not null
    then
      continue;
    end if;

    v_amount := public.payroll_slip_line_amount(v_line);
    if v_line -> 'metadata' ? 'employer_insurance_amount' then
      v_employer_insurance := v_employer_insurance
        + abs(public.payroll_safe_numeric(v_line -> 'metadata' ->> 'employer_insurance_amount'));
      v_has_employer_insurance := true;
    end if;
    if v_amount = 0 then continue; end if;

    if v_line_type = 'deduction' then
      v_deduction_total := v_deduction_total + v_amount;
      if v_line_key = 'employee_insurance'
        or lower(coalesce(v_line ->> 'title', '')) like '%بیمه سهم کارمند%'
      then
        v_employee_insurance := v_employee_insurance + v_amount;
      end if;
    elsif v_line_type = 'bonus' then
      v_bonus_total := v_bonus_total + v_amount;
    elsif v_line_key = 'task_wage'
      or lower(coalesce(v_line ->> 'title', '')) like '%حقوق عملکردی فعالیت%'
    then
      v_task_wage_total := v_task_wage_total + v_amount;
    else
      v_base_salary := v_base_salary + v_amount;
    end if;
  end loop;

  select exists (
    select 1
    from jsonb_array_elements(coalesce(new.payments, '[]'::jsonb)) as payment(value)
    where payment.value ? 'status'
  ) into v_has_payment_status;

  for v_payment in
    select value from jsonb_array_elements(coalesce(new.payments, '[]'::jsonb))
  loop
    v_payment_status := lower(trim(coalesce(v_payment ->> 'status', '')));
    if v_has_payment_status
      and v_payment_status <> ''
      and v_payment_status not in ('received', 'paid', 'approved', 'settled', 'cleared', 'completed')
    then
      continue;
    end if;
    v_paid_amount := v_paid_amount + public.financial_history_payment_amount(v_payment);
  end loop;

  new.base_salary := v_base_salary;
  new.task_wage_total := v_task_wage_total;
  new.bonus_total := v_bonus_total;
  new.earnings_total := v_base_salary + v_task_wage_total + v_bonus_total;
  new.deduction_total := v_deduction_total;
  new.insurance_employee_amount := v_employee_insurance;
  new.insurance_employer_amount := case when v_has_employer_insurance then v_employer_insurance else 0 end;
  new.gross_amount := new.earnings_total - v_deduction_total;
  new.net_amount := new.gross_amount - v_paid_amount;
  return new;
end;
$$;


--
-- Name: sync_process_graph_stage_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_process_graph_stage_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.process_node_key := coalesce(
    nullif(btrim(coalesce(new.process_node_key, '')), ''),
    nullif(btrim(coalesce(new.metadata ->> 'process_node_key', '')), ''),
    'stage_' || replace(new.id::text, '-', '')
  );
  new.process_lane_key := coalesce(
    nullif(btrim(coalesce(new.process_lane_key, '')), ''),
    nullif(btrim(coalesce(new.metadata ->> 'process_lane_key', '')), ''),
    'lane_1'
  );
  new.metadata := coalesce(new.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'process_node_key', new.process_node_key,
      'process_lane_key', new.process_lane_key
    );
  return new;
end;
$$;


--
-- Name: sync_process_graph_task_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_process_graph_task_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.process_node_key := coalesce(
    nullif(btrim(coalesce(new.process_node_key, '')), ''),
    nullif(btrim(coalesce(new.recurrence_info ->> 'process_node_key', '')), '')
  );
  new.process_lane_key := coalesce(
    nullif(btrim(coalesce(new.process_lane_key, '')), ''),
    nullif(btrim(coalesce(new.recurrence_info ->> 'process_lane_key', '')), ''),
    case when new.process_run_id is not null then 'lane_1' else null end
  );
  if new.process_node_key is not null or new.process_lane_key is not null then
    new.recurrence_info := coalesce(new.recurrence_info, '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
        'process_node_key', new.process_node_key,
        'process_lane_key', new.process_lane_key
      ));
  end if;
  return new;
end;
$$;


--
-- Name: sync_process_run_stage_from_task(uuid, uuid, text, uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_process_run_stage_from_task(p_process_run_stage_id uuid, p_task_id uuid, p_status text, p_assignee_user_id uuid DEFAULT NULL::uuid, p_assignee_role_id uuid DEFAULT NULL::uuid, p_planned_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_completed_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  select r.org_id
  into v_org_id
  from public.process_run_stages s
  join public.process_runs r on r.id = s.process_run_id
  where s.id = p_process_run_stage_id;

  if auth.uid() is null
    or v_org_id is null
    or public.current_org_id() is null
    or v_org_id <> public.current_org_id() then
    raise exception 'دسترسی بروزرسانی مرحله فرآیند وجود ندارد.' using errcode = '42501';
  end if;

  if p_task_id is not null and not exists (
    select 1
    from public.tasks t
    where t.id = p_task_id
      and t.org_id = v_org_id
  ) then
    raise exception 'فعالیت مرتبط متعلق به سازمان جاری نیست.' using errcode = '42501';
  end if;

  perform public.assert_process_assignee_org(
    v_org_id,
    p_assignee_user_id,
    p_assignee_role_id
  );

  update public.process_run_stages
  set task_id = p_task_id,
      status = case lower(coalesce(p_status, 'todo'))
        when 'in_progress' then 'in_progress'
        when 'done' then 'done'
        when 'completed' then 'done'
        when 'blocked' then 'blocked'
        when 'canceled' then 'canceled'
        else 'todo'
      end,
      assignee_user_id = p_assignee_user_id,
      assignee_role_id = p_assignee_role_id,
      planned_due_at = p_planned_due_at,
      started_at = p_started_at,
      completed_at = p_completed_at,
      updated_at = now()
  where id = p_process_run_stage_id;
end;
$$;


--
-- Name: sync_process_task_v2_custom_field_values(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_process_task_v2_custom_field_values(p_task_id uuid, p_field_values jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_task public.tasks%rowtype;
  v_recurrence jsonb;
  v_existing_values jsonb;
  v_links jsonb;
  v_field jsonb;
  v_field_key text;
  v_target_module text;
  v_record_id text;
  v_linked_module_ids text[] := array[]::text[];
  v_run_module_id text;
  v_run_record_id uuid;
begin
  if auth.uid() is null or v_org_id is null then raise exception using errcode = '42501', message = 'دسترسی سازمانی معتبر برای ذخیره فعالیت پیدا نشد.'; end if;
  if p_task_id is null or p_field_values is null or jsonb_typeof(p_field_values) <> 'object' then raise exception using errcode = '22023', message = 'مقادیر فیلدهای اختصاصی معتبر نیست.'; end if;
  select * into v_task from public.tasks where id = p_task_id and org_id = v_org_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'فعالیت موردنظر برای ذخیره پیدا نشد یا دسترسی آن وجود ندارد.'; end if;
  v_recurrence := case when jsonb_typeof(v_task.recurrence_info) = 'object' then v_task.recurrence_info else '{}'::jsonb end;
  v_existing_values := case when jsonb_typeof(v_recurrence -> 'process_task_custom_field_values') = 'object' then v_recurrence -> 'process_task_custom_field_values' else '{}'::jsonb end;
  v_links := case when jsonb_typeof(v_recurrence -> 'process_links') = 'object' then v_recurrence -> 'process_links' else '{}'::jsonb end;
  for v_field in select value from jsonb_array_elements(case when jsonb_typeof(v_recurrence -> 'process_task_custom_fields') = 'array' then v_recurrence -> 'process_task_custom_fields' else '[]'::jsonb end) loop
    v_field_key := nullif(trim(coalesce(v_field ->> 'key', '')), '');
    v_target_module := nullif(trim(coalesce(v_field -> 'relationConfig' ->> 'targetModule', '')), '');
    if v_field_key is null or v_target_module is null or coalesce(v_field ->> 'type', '') <> 'relation'
       or coalesce((v_field -> 'relationConfig' ->> 'linkToProcessRelatedRecord')::boolean, (v_field -> 'relationConfig' ->> 'link_to_process_related_record')::boolean, false) is not true
       or not (p_field_values ? v_field_key) then continue; end if;
    v_record_id := nullif(trim(coalesce(p_field_values ->> v_field_key, '')), '');
    if v_record_id is null then continue; end if;
    if v_record_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception using errcode = '22023', message = 'مقدار رابطه اختصاصی معتبر نیست.';
    end if;
    v_links := v_links || jsonb_build_object(v_target_module, v_record_id);
    v_linked_module_ids := array_append(v_linked_module_ids, v_target_module);
  end loop;
  v_recurrence := jsonb_set(v_recurrence, '{process_task_custom_field_values}', v_existing_values || p_field_values, true);
  v_recurrence := jsonb_set(v_recurrence, '{process_links}', v_links, true);
  update public.tasks set recurrence_info = v_recurrence, updated_at = now() where id = v_task.id and org_id = v_org_id returning * into v_task;
  if v_task.process_run_id is not null and coalesce(array_length(v_linked_module_ids, 1), 0) > 0 then
    select module_id, record_id into v_run_module_id, v_run_record_id from public.process_runs where id = v_task.process_run_id and org_id = v_org_id;
    delete from public.process_run_links where process_run_id = v_task.process_run_id and org_id = v_org_id and module_id = any(v_linked_module_ids);
    for v_target_module, v_record_id in select key, value from jsonb_each_text(v_links) loop
      if not v_target_module = any(v_linked_module_ids) then continue; end if;
      insert into public.process_run_links (org_id, process_run_id, module_id, record_id, is_primary)
      values (v_org_id, v_task.process_run_id, v_target_module, v_record_id::uuid, v_target_module = v_run_module_id and v_record_id::uuid = v_run_record_id)
      on conflict (process_run_id, module_id, record_id) do update set org_id = excluded.org_id, is_primary = excluded.is_primary;
    end loop;
  end if;
  return jsonb_build_object('id', v_task.id, 'status', v_task.status, 'recurrence_info', v_task.recurrence_info, 'process_run_id', v_task.process_run_id, 'process_run_stage_id', v_task.process_run_stage_id, 'updated_at', v_task.updated_at);
end;
$_$;


--
-- Name: sync_profile_contact_to_auth_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_profile_contact_to_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare normalized_mobile text;
begin
  normalized_mobile := public.normalize_iran_mobile_e164(coalesce(nullif(new.mobile_1,''),new.mobile));
  update auth.users
    set phone = case when normalized_mobile is null then null else substr(normalized_mobile,2) end,
        phone_confirmed_at = case
          when public.normalize_iran_mobile_e164(phone) is not distinct from normalized_mobile then phone_confirmed_at
          else null end,
        raw_user_meta_data = coalesce(raw_user_meta_data,'{}'::jsonb)
          || jsonb_build_object('full_name',coalesce(new.full_name,''),'avatar_url',coalesce(new.avatar_url,''))
    where id=new.id;
  return new;
end;
$$;


--
-- Name: sync_profile_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_profile_org_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- اگر org_id مستقیم در row ست شده، همان را نگه می‌داریم
  if NEW.org_id is not null then
    return NEW;
  end if;

  -- در غیر این صورت از org_roles می‌گیریم
  if NEW.role_id is not null then
    select r.org_id
      into NEW.org_id
    from public.org_roles r
    where r.id = NEW.role_id
    limit 1;
  end if;

  return NEW;
end;
$$;


