--
-- Name: sync_reservation_sales_invoice_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_reservation_sales_invoice_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  if tg_op = 'DELETE' then
    if old.reservation_id is null then
      return old;
    end if;
    v_org_id := old.org_id;
    if public.current_org_id() is null or v_org_id <> public.current_org_id() then
      raise exception 'invoice organization mismatch';
    end if;
    if old.reservation_id is not null then
      update public.reservations
         set sales_invoice_id = null, updated_at = now()
       where id = old.reservation_id
         and org_id = v_org_id
         and sales_invoice_id = old.id;
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' and new.reservation_id is null then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.reservation_id is null and new.reservation_id is null then
    return new;
  end if;

  v_org_id := new.org_id;
  if public.current_org_id() is null or v_org_id <> public.current_org_id() then
    raise exception 'invoice organization mismatch';
  end if;

  if tg_op = 'UPDATE' and old.reservation_id is not null
     and new.reservation_id is distinct from old.reservation_id then
    update public.reservations
       set sales_invoice_id = null, updated_at = now()
     where id = old.reservation_id
       and org_id = v_org_id
       and sales_invoice_id = old.id;
  end if;

  if new.reservation_id is not null then
    update public.reservations
       set sales_invoice_id = new.id, updated_at = now()
     where id = new.reservation_id
       and org_id = new.org_id;
    if not found then
      raise exception 'رزرو مرتبط معتبر نیست';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: sync_supplier_customer_mirror(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_supplier_customer_mirror() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_customer_id uuid;
  v_first_name text;
  v_last_name text;
  v_business_name text;
begin

  if tg_op = 'UPDATE' and row(new.org_id, new.business_name, new.first_name, new.last_name, new.mobile_1, new.mobile_2, new.phone, new.prefix, new.province, new.city, new.address, new.location, new.image_url, new.is_customer, new.linked_customer_id)
     is not distinct from row(old.org_id, old.business_name, old.first_name, old.last_name, old.mobile_1, old.mobile_2, old.phone, old.prefix, old.province, old.city, old.address, old.location, old.image_url, old.is_customer, old.linked_customer_id) then
    return new;
  end if;
  if pg_trigger_depth() > 1 then
    return new;
  end if;

  if not coalesce(new.is_customer, false) then
    if new.linked_customer_id is not null then
      update public.customers c
      set is_supplier = false
      where c.id = new.linked_customer_id
        and c.org_id = new.org_id
        and c.linked_supplier_id = new.id;
    end if;
    return new;
  end if;

  v_customer_id := new.linked_customer_id;
  v_business_name := nullif(trim(coalesce(new.business_name, '')), '');
  v_first_name := nullif(trim(coalesce(new.first_name, '')), '');
  v_last_name := nullif(trim(coalesce(new.last_name, '')), '');

  if v_first_name is null then
    v_first_name := coalesce(v_business_name, 'طرف');
  end if;
  if v_last_name is null then
    v_last_name := 'حساب';
  end if;

  if v_customer_id is not null then
    perform 1 from public.customers where id = v_customer_id and org_id = new.org_id;
    if not found then
      v_customer_id := null;
    end if;
  end if;

  if v_customer_id is null then
    select c.id
    into v_customer_id
    from public.customers c
    where c.linked_supplier_id = new.id
      and c.org_id = new.org_id
    limit 1;
  end if;

  if v_customer_id is null then
    insert into public.customers (
      org_id,
      first_name,
      last_name,
      business_name,
      mobile_1,
      mobile_2,
      phone,
      prefix,
      province,
      city,
      address,
      location,
      image_url,
      is_supplier,
      linked_supplier_id,
      created_by,
      updated_by
    ) values (
      new.org_id,
      v_first_name,
      v_last_name,
      v_business_name,
      new.mobile_1,
      new.mobile_2,
      new.phone,
      new.prefix,
      new.province,
      new.city,
      new.address,
      new.location,
      new.image_url,
      true,
      new.id,
      new.created_by,
      new.updated_by
    )
    returning id into v_customer_id;
  else
    update public.customers c
    set
      org_id = coalesce(new.org_id, c.org_id),
      first_name = coalesce(v_first_name, c.first_name),
      last_name = coalesce(v_last_name, c.last_name),
      business_name = coalesce(v_business_name, c.business_name),
      mobile_1 = coalesce(new.mobile_1, c.mobile_1),
      mobile_2 = coalesce(new.mobile_2, c.mobile_2),
      phone = coalesce(new.phone, c.phone),
      prefix = coalesce(new.prefix, c.prefix),
      province = coalesce(new.province, c.province),
      city = coalesce(new.city, c.city),
      address = coalesce(new.address, c.address),
      location = coalesce(new.location, c.location),
      image_url = coalesce(new.image_url, c.image_url),
      is_supplier = true,
      linked_supplier_id = new.id,
      updated_by = coalesce(new.updated_by, c.updated_by),
      updated_at = now()
    where c.id = v_customer_id and c.org_id = new.org_id;
  end if;

  update public.suppliers set linked_customer_id = v_customer_id
  where id = new.id and org_id = new.org_id
    and linked_customer_id is distinct from v_customer_id;
  new.linked_customer_id := v_customer_id;
  return new;
end;
$$;


--
-- Name: tenant_request_trial_renewal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_request_trial_renewal(p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  caller_id  uuid := auth.uid();
  org_id_val uuid := public.current_org_id();
  existing_id uuid;
begin
  if caller_id is null or org_id_val is null then
    return jsonb_build_object('success', false, 'message', 'احراز هویت ناموفق بود.');
  end if;

  -- بررسی وجود درخواست pending قبلی
  select id into existing_id
  from public.saas_renewal_requests
  where org_id = org_id_val
    and status = 'pending'
  limit 1;

  if existing_id is not null then
    return jsonb_build_object(
      'success', true,
      'already_exists', true,
      'request_id', existing_id,
      'message', 'درخواست تمدید قبلی شما هنوز در انتظار بررسی است.'
    );
  end if;

  insert into public.saas_renewal_requests (org_id, requested_by, notes)
  values (org_id_val, caller_id, nullif(trim(coalesce(p_notes, '')), ''))
  returning id into existing_id;

  return jsonb_build_object(
    'success', true,
    'already_exists', false,
    'request_id', existing_id,
    'message', 'درخواست تمدید ثبت شد. تیم ما در اسرع وقت بررسی می‌کند.'
  );
end;
$$;


--
-- Name: touch_communication_bot_thread_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_communication_bot_thread_summary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_preview text;
  v_direction text;
begin
  if tg_op = 'INSERT' then
    if new.org_id is null or new.bot_group_id is null then
      return new;
    end if;

    v_preview := coalesce(nullif(trim(new.content_text), ''), nullif(trim(new.file_name), ''), nullif(trim(new.message_type), ''));
    v_direction := trim(coalesce(new.direction, ''));

    insert into public.communication_bot_thread_summaries (
      org_id,
      bot_group_id,
      message_count,
      latest_message_id,
      latest_message_at,
      latest_message_preview,
      latest_message_direction,
      latest_inbound_at,
      latest_outbound_at,
      updated_at
    )
    values (
      new.org_id,
      new.bot_group_id,
      1,
      new.id,
      new.created_at,
      v_preview,
      v_direction,
      case when v_direction = 'inbound' then new.created_at else null end,
      case when v_direction = 'outbound' then new.created_at else null end,
      now()
    )
    on conflict (org_id, bot_group_id) do update
    set message_count = public.communication_bot_thread_summaries.message_count + 1,
        latest_message_id = case
          when public.communication_bot_thread_summaries.latest_message_at is null
            or new.created_at > public.communication_bot_thread_summaries.latest_message_at
            or (
              new.created_at = public.communication_bot_thread_summaries.latest_message_at
              and new.id::text > coalesce(public.communication_bot_thread_summaries.latest_message_id::text, '')
            )
          then new.id
          else public.communication_bot_thread_summaries.latest_message_id
        end,
        latest_message_at = greatest(coalesce(public.communication_bot_thread_summaries.latest_message_at, new.created_at), new.created_at),
        latest_message_preview = case
          when public.communication_bot_thread_summaries.latest_message_at is null
            or new.created_at > public.communication_bot_thread_summaries.latest_message_at
            or (
              new.created_at = public.communication_bot_thread_summaries.latest_message_at
              and new.id::text > coalesce(public.communication_bot_thread_summaries.latest_message_id::text, '')
            )
          then v_preview
          else public.communication_bot_thread_summaries.latest_message_preview
        end,
        latest_message_direction = case
          when public.communication_bot_thread_summaries.latest_message_at is null
            or new.created_at > public.communication_bot_thread_summaries.latest_message_at
            or (
              new.created_at = public.communication_bot_thread_summaries.latest_message_at
              and new.id::text > coalesce(public.communication_bot_thread_summaries.latest_message_id::text, '')
            )
          then v_direction
          else public.communication_bot_thread_summaries.latest_message_direction
        end,
        latest_inbound_at = case
          when v_direction = 'inbound'
            then greatest(coalesce(public.communication_bot_thread_summaries.latest_inbound_at, new.created_at), new.created_at)
          else public.communication_bot_thread_summaries.latest_inbound_at
        end,
        latest_outbound_at = case
          when v_direction = 'outbound'
            then greatest(coalesce(public.communication_bot_thread_summaries.latest_outbound_at, new.created_at), new.created_at)
          else public.communication_bot_thread_summaries.latest_outbound_at
        end,
        updated_at = now();

    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.org_id is distinct from new.org_id
       or old.bot_group_id is distinct from new.bot_group_id
       or old.created_at is distinct from new.created_at
       or old.direction is distinct from new.direction
       or old.content_text is distinct from new.content_text
       or old.file_name is distinct from new.file_name
       or old.message_type is distinct from new.message_type then
      perform public.rebuild_communication_bot_thread_summary(old.org_id, old.bot_group_id);
      perform public.rebuild_communication_bot_thread_summary(new.org_id, new.bot_group_id);
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    perform public.rebuild_communication_bot_thread_summary(old.org_id, old.bot_group_id);
    return old;
  end if;

  return null;
end;
$$;


