CREATE FUNCTION public.track_demo_seed_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare batch_key uuid; row_data jsonb := to_jsonb(new); batch_org uuid;
begin
