--
-- Name: trg_guard_journal_entry_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_guard_journal_entry_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(nullif(old.status, ''), 'draft') <> 'draft' then
    raise exception 'فقط اسناد پیش‌نویس قابل حذف هستند.';
  end if;
  return old;
end;
