--
-- Name: trg_guard_journal_entry_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_guard_journal_entry_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_start_date date;
  v_end_date date;
  v_is_closed boolean;
begin
  if new.fiscal_year_id is not null then
    select fy.start_date, fy.end_date, fy.is_closed
    into v_start_date, v_end_date, v_is_closed
    from public.fiscal_years fy
    where fy.id = new.fiscal_year_id;

    if not found then
      raise exception 'سال مالی سند پیدا نشد.';
    end if;

    if new.entry_date < v_start_date or new.entry_date > v_end_date then
      raise exception 'تاریخ سند (%) خارج از بازه سال مالی (% تا %) است.', new.entry_date, v_start_date, v_end_date;
    end if;

    if new.status = 'posted' and coalesce(v_is_closed, false) then
      raise exception 'ثبت نهایی در سال مالی بسته مجاز نیست.';
    end if;
  elsif new.status = 'posted' then
    raise exception 'برای ثبت نهایی، انتخاب سال مالی الزامی است.';
  end if;

  if tg_op = 'UPDATE' then
    if old.status = 'posted' and new.status = 'draft' then
      raise exception 'سند ثبت‌نهایی‌شده قابل برگشت به پیش‌نویس نیست.';
    end if;

    if old.status = 'posted' and new.status = 'posted' then
      if new.entry_date is distinct from old.entry_date
         or new.description is distinct from old.description
         or new.fiscal_year_id is distinct from old.fiscal_year_id
         or new.entry_no is distinct from old.entry_no
         or new.source_module is distinct from old.source_module
         or new.source_table is distinct from old.source_table
         or new.source_record_id is distinct from old.source_record_id then
        raise exception 'سند ثبت‌نهایی‌شده قفل است و قابل ویرایش مستقیم نیست.';
      end if;
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: trg_guard_journal_lines_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_guard_journal_lines_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_entry_id uuid;
  v_status text;
begin
  v_entry_id := coalesce(new.entry_id, old.entry_id);

  if v_entry_id is null then
    raise exception 'هر ردیف سند باید به یک سند حسابداری معتبر متصل باشد.';
  end if;

  select e.status
  into v_status
  from public.journal_entries e
  where e.id = v_entry_id;

  if v_status is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    raise exception 'سند والد برای تغییر ردیف پیدا نشد.';
  end if;

  if v_status <> 'draft' then
    raise exception 'فقط ردیف‌های اسناد پیش‌نویس قابل تغییر هستند.';
  end if;

  if tg_op = 'UPDATE' and new.entry_id is distinct from old.entry_id then
    select e.status
    into v_status
    from public.journal_entries e
    where e.id = new.entry_id;

    if v_status is null then
      raise exception 'سند مقصد برای انتقال ردیف پیدا نشد.';
    end if;

    if v_status <> 'draft' then
      raise exception 'انتقال ردیف به سند غیرپیش‌نویس مجاز نیست.';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


--
-- Name: trg_refresh_journal_entry_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_refresh_journal_entry_totals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (tg_op = 'DELETE') then
    perform public.refresh_journal_entry_totals(old.entry_id);
    return old;
  end if;

  perform public.refresh_journal_entry_totals(new.entry_id);

  if (tg_op = 'UPDATE' and old.entry_id is distinct from new.entry_id) then
    perform public.refresh_journal_entry_totals(old.entry_id);
  end if;

  return new;
end;
$$;


--
-- Name: trg_validate_posted_journal_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_validate_posted_journal_entry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_total_debit numeric(18,2);
  v_total_credit numeric(18,2);
begin
  if (new.status = 'posted' and coalesce(old.status, '') <> 'posted') then
    select
      coalesce(sum(l.debit), 0)::numeric(18,2),
      coalesce(sum(l.credit), 0)::numeric(18,2)
    into v_total_debit, v_total_credit
    from public.journal_lines l
    where l.entry_id = new.id;

    new.total_debit = v_total_debit;
    new.total_credit = v_total_credit;

    if v_total_debit <= 0 or v_total_credit <= 0 then
      raise exception 'برای ثبت نهایی، سند باید حداقل یک ردیف بدهکار و یک ردیف بستانکار با مبلغ غیرصفر داشته باشد.';
    end if;

    if abs(v_total_debit - v_total_credit) > 0.009 then
      raise exception 'سند تراز نیست. جمع بدهکار (%) و بستانکار (%) باید برابر باشد.', v_total_debit, v_total_credit;
    end if;

    new.posted_at = coalesce(new.posted_at, now());
    new.posted_by = coalesce(new.posted_by, auth.uid());
  end if;

  return new;
end;
$$;


--
-- Name: trigger_advertising_campaign_runtime(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_advertising_campaign_runtime() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_supabase_url text; v_service_key text;
begin
  if new.status <> 'queued' or (tg_op='UPDATE' and old.status is not distinct from new.status) then
    return null;
  end if;
  v_supabase_url := current_setting('app.supabase_url', true);
  v_service_key := current_setting('app.service_role_key', true);
  if coalesce(v_supabase_url,'')='' or coalesce(v_service_key,'')='' then return null; end if;
  perform net.http_post(
    url := rtrim(v_supabase_url,'/') || '/functions/v1/campaign-runtime',
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer ' || v_service_key,'x-kalam-internal','database-dispatch'),
    body := jsonb_build_object('action','drain','limit',10)
  );
  return null;
end;
$$;


--
-- Name: trigger_ai_image_worker(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_ai_image_worker() RETURNS void
