      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_service_key,
      'x-kalam-internal', 'ai-image-worker'
    ),
    body := jsonb_build_object('action', 'process_ai_image_jobs'),
    timeout_milliseconds := 900000
  );
end;
$$;


