--
-- Name: trigger_workflow_event_runner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_workflow_event_runner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_supabase_url text;
  v_service_key text;
  v_should_dispatch boolean := false;
begin
  v_supabase_url := current_setting('app.supabase_url', true);
  v_service_key := current_setting('app.service_role_key', true);
  if coalesce(v_supabase_url, '') = '' or coalesce(v_service_key, '') = '' then
    return null;
  end if;

  update public.workflow_runner_dispatch_state
  set
    last_dispatched_at = now(),
    updated_at = now()
  where dispatch_key = 'workflow-event-queue'
    and last_dispatched_at <= now() - interval '15 seconds'
  returning true into v_should_dispatch;

  if coalesce(v_should_dispatch, false) then
    perform net.http_post(
      url := rtrim(v_supabase_url, '/') || '/functions/v1/workflow-interval-runner',
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_service_key),
      body := jsonb_build_object('action', 'drain_events')
    );
  end if;

  return null;
end;
$$;


--
-- Name: trigger_workflow_interval_runner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_workflow_interval_runner() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_supabase_url  text;
  v_service_key   text;
  v_function_url  text;
BEGIN
  -- Read project URL and service role key stored as DB settings.
  -- Set them once with:
  --   ALTER DATABASE postgres SET "app.supabase_url" = 'https://xxx.supabase.co';
  --   ALTER DATABASE postgres SET "app.service_role_key" = 'eyJ...';
  v_supabase_url := current_setting('app.supabase_url', true);
  v_service_key  := current_setting('app.service_role_key', true);

  IF v_supabase_url IS NULL OR v_supabase_url = '' THEN
    RAISE WARNING 'trigger_workflow_interval_runner: app.supabase_url not configured';
    RETURN;
  END IF;
  IF v_service_key IS NULL OR v_service_key = '' THEN
    RAISE WARNING 'trigger_workflow_interval_runner: app.service_role_key not configured';
    RETURN;
  END IF;

  v_function_url := rtrim(v_supabase_url, '/') || '/functions/v1/workflow-interval-runner';

  PERFORM net.http_post(
    url     := v_function_url,
    headers := json_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    )::jsonb,
    body    := '{}'::jsonb
  );
END;
$$;


--
-- Name: unlock_record(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlock_record(p_module_id text, p_record_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid := public.current_org_id();
  v_module_id text := btrim(coalesce(p_module_id, ''));
begin
  if v_org_id is null or auth.uid() is null then
    raise exception 'دسترسی سازمانی معتبر برای باز کردن رکورد پیدا نشد.';
  end if;
  if v_module_id = '' or p_record_id is null then
    raise exception 'رکورد انتخاب‌شده برای باز کردن معتبر نیست.';
  end if;
  if not public.record_lock_user_can(v_module_id, 'unlock') then
    raise exception 'دسترسی باز کردن این رکورد را ندارید.';
  end if;

  delete from public.record_locks
  where org_id = v_org_id
    and module_id = v_module_id
    and record_id = p_record_id;

  return true;
end;
$$;


--
-- Name: update_advertising_campaign_collaboration_tool(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_advertising_campaign_collaboration_tool(p_tool_id uuid, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_tool public.advertising_campaign_tools%rowtype; v_patch jsonb:=coalesce(p_patch,'{}'::jsonb);
        v_config_patch jsonb:='{}'::jsonb; v_status text; v_actual_start timestamptz; v_actual_end timestamptz;
begin
  if auth.uid() is null or public.current_org_id() is null
     or not public.current_user_can_access_advertising_campaign_module()
     or not public.current_user_has_role_permission_entry('advertising_campaigns','view',null,true)
     or not public.can_collaborate_advertising_campaign_tool(p_tool_id) then
    raise exception 'دسترسی همکاری روی این ابزار را ندارید.' using errcode='42501';
  end if;
  select * into v_tool from public.advertising_campaign_tools
  where id=p_tool_id and org_id=public.current_org_id();
  if v_tool.id is null then raise exception 'ابزار کمپین پیدا نشد.' using errcode='P0002'; end if;
  if v_patch ? 'status' then
    v_status:=lower(btrim(coalesce(v_patch->>'status','')));
    if v_status not in ('ready','running','paused','completed','failed') then
      raise exception 'وضعیت ابزار برای همکاری مجاز نیست.' using errcode='22023';
    end if;
  else v_status:=v_tool.status; end if;
  begin
    v_actual_start:=case when v_patch ? 'actual_start_at' then nullif(v_patch->>'actual_start_at','')::timestamptz else v_tool.actual_start_at end;
    v_actual_end:=case when v_patch ? 'actual_end_at' then nullif(v_patch->>'actual_end_at','')::timestamptz else v_tool.actual_end_at end;
  exception when invalid_datetime_format then
    raise exception 'زمان واقعی ابزار معتبر نیست.' using errcode='22007';
  end;
  if v_actual_start is not null and v_actual_end is not null and v_actual_end < v_actual_start then
    raise exception 'پایان واقعی نمی‌تواند قبل از شروع واقعی باشد.' using errcode='23514';
  end if;
  if jsonb_typeof(v_patch->'config')='object' then
    select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into v_config_patch
    from jsonb_each(v_patch->'config')
    where key in ('result_notes','result_metrics','result_attachments','actual_reach','actual_impressions','actual_clicks','actual_responses','completion_percentage');
  end if;
  update public.advertising_campaign_tools set
    status=v_status,
    actual_cost=case when v_patch ? 'actual_cost' then greatest(coalesce((v_patch->>'actual_cost')::numeric,0),0) else actual_cost end,
    actual_leads=case when v_patch ? 'actual_leads' then greatest(coalesce((v_patch->>'actual_leads')::integer,0),0) else actual_leads end,
    actual_customers=case when v_patch ? 'actual_customers' then greatest(coalesce((v_patch->>'actual_customers')::integer,0),0) else actual_customers end,
    actual_start_at=v_actual_start,actual_end_at=v_actual_end,
    result_summary=case when v_patch ? 'result_summary' then left(nullif(btrim(v_patch->>'result_summary'),''),10000) else result_summary end,
    config=config || v_config_patch,updated_by=auth.uid()
  where id=v_tool.id and org_id=v_tool.org_id
  returning * into v_tool;
  return jsonb_build_object(
    'id',v_tool.id,'campaign_id',v_tool.campaign_id,'tool_type',v_tool.tool_type,
    'status',v_tool.status,'actual_cost',v_tool.actual_cost,'actual_leads',v_tool.actual_leads,
    'actual_customers',v_tool.actual_customers,'actual_start_at',v_tool.actual_start_at,
    'actual_end_at',v_tool.actual_end_at,'result_summary',v_tool.result_summary,
    'config',v_tool.config,'updated_at',v_tool.updated_at
  );
exception when invalid_text_representation or numeric_value_out_of_range then
  raise exception 'مقادیر واقعی ابزار معتبر نیست.' using errcode='22023';
end;
$$;


--
-- Name: update_advertising_campaign_import_progress(uuid, text, integer, integer, integer, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_advertising_campaign_import_progress(p_import_id uuid, p_status text, p_total_rows integer, p_processed_rows integer, p_valid_rows integer, p_duplicate_rows integer, p_invalid_rows integer, p_error_summary jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_status not in ('pending','processing','completed','failed','canceled') then return false; end if;
  update public.advertising_campaign_imports set
    status=p_status,total_rows=greatest(coalesce(p_total_rows,0),0),
    processed_rows=greatest(coalesce(p_processed_rows,0),0),valid_rows=greatest(coalesce(p_valid_rows,0),0),
    duplicate_rows=greatest(coalesce(p_duplicate_rows,0),0),invalid_rows=greatest(coalesce(p_invalid_rows,0),0),
    error_summary=coalesce(p_error_summary,'{}'::jsonb),
    started_at=case when p_status='processing' then coalesce(started_at,now()) else started_at end,
    completed_at=case when p_status in ('completed','failed','canceled') then now() else null end
  where id=p_import_id;
  return found;
end;
$$;


--
-- Name: update_current_saas_pending_order(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_current_saas_pending_order(p_order_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.saas_orders%rowtype; replacement jsonb;
begin
  if auth.uid() is null or public.current_org_id() is null then raise exception 'organization_access_denied' using errcode='42501'; end if;
  if not exists (select 1 from public.user_organization_memberships m where m.org_id=public.current_org_id() and m.user_id=auth.uid() and m.is_active and (m.is_owner or m.software_role='admin')) then raise exception 'organization_admin_required' using errcode='42501'; end if;
  select * into target from public.saas_orders where id=p_order_id and org_id=public.current_org_id() for update;
  if not found or target.status <> 'pending_payment' or target.payment_transaction_id is not null then raise exception 'saas_order_not_editable'; end if;
  if exists (select 1 from public.payment_transactions tx where tx.org_id=target.org_id and tx.purpose='saas_account_order'
    and tx.metadata->>'saas_order_id'=target.id::text and tx.status in ('pending','redirected')) then raise exception 'saas_order_payment_in_progress'; end if;
  replacement := public.create_current_saas_order(p_items);
  delete from public.saas_orders where id=target.id;
  return replacement;
end $$;


