--
-- Name: update_workflow_record(text, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_workflow_record(p_table_name text, p_org_id uuid, p_record_id uuid, p_patch jsonb, p_origin_execution_key text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_existing jsonb;
  v_write_patch jsonb := coalesce(p_patch, '{}'::jsonb);
  v_key text;
  v_value jsonb;
  v_set_clause text;
  v_has_business_change boolean := false;
  v_has_updated_at boolean := false;
  v_rows integer := 0;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'دسترسی بروزرسانی خودکار وجود ندارد.' using errcode = '42501';
  end if;
  if p_table_name !~ '^[a-z][a-z0-9_]*$' or p_org_id is null or p_record_id is null then
    raise exception 'پارامتر بروزرسانی خودکار نامعتبر است.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_write_patch) <> 'object' or v_write_patch = '{}'::jsonb then
    raise exception 'فیلد قابل بروزرسانی ارسال نشده است.' using errcode = '22023';
  end if;
  if not exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public' and c.table_name = p_table_name and c.column_name = 'id'
  ) or not exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public' and c.table_name = p_table_name and c.column_name = 'org_id'
  ) then
    raise exception 'ماژول مقصد برای بروزرسانی خودکار معتبر نیست.' using errcode = '22023';
  end if;

  for v_key, v_value in select key, value from jsonb_each(v_write_patch) loop
    if v_key in ('id', 'org_id', 'created_at') or not exists (
      select 1 from information_schema.columns c
      where c.table_schema = 'public' and c.table_name = p_table_name and c.column_name = v_key
    ) then
      raise exception 'فیلد بروزرسانی خودکار معتبر نیست.' using errcode = '22023';
    end if;
  end loop;

  execute format('select to_jsonb(t) from public.%I t where t.id = $1 and t.org_id = $2', p_table_name)
    into v_existing using p_record_id, p_org_id;
  if v_existing is null then
    raise exception 'رکورد مقصد در سازمان جاری پیدا نشد.' using errcode = 'P0002';
  end if;

  for v_key, v_value in select key, value from jsonb_each(v_write_patch) loop
    if v_key not in ('updated_at', 'updated_by')
       and (v_existing -> v_key) is distinct from v_value then
      v_has_business_change := true;
      exit;
    end if;
  end loop;
  if not v_has_business_change then
    return false;
  end if;

  select exists (
    select 1 from information_schema.columns c
    where c.table_schema = 'public' and c.table_name = p_table_name and c.column_name = 'updated_at'
  ) into v_has_updated_at;
  if v_has_updated_at then
    v_write_patch := v_write_patch || jsonb_build_object('updated_at', to_jsonb(now()));
  end if;

  select string_agg(format('%1$I = src.%1$I', key), ', ' order by key)
    into v_set_clause
  from jsonb_object_keys(v_write_patch) as key;
  if coalesce(v_set_clause, '') = '' then
    raise exception 'فیلد قابل بروزرسانی ارسال نشده است.' using errcode = '22023';
  end if;

  perform set_config('app.workflow_origin_execution_key', coalesce(nullif(trim(p_origin_execution_key), ''), ''), true);
  execute format(
    'update public.%I as t set %s from jsonb_populate_record(null::public.%I, $1) as src where t.id = $2 and t.org_id = $3',
    p_table_name, v_set_clause, p_table_name
  ) using v_write_patch, p_record_id, p_org_id;
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end;
$_$;


--
-- Name: user_belongs_to_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_belongs_to_org(p_org_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_exists boolean;
begin
  if p_org_id is null then
    return false;
  end if;

  select exists (
    select 1
    from public.profiles p
    left join public.org_roles r on r.id = p.role_id
    where p.id = auth.uid()
      and coalesce(p.org_id, r.org_id) = p_org_id
  ) into v_exists;

  return coalesce(v_exists, false);
end;
$$;


--
-- Name: validate_advertising_campaign_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_advertising_campaign_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_campaign_org uuid;
  v_tool_campaign uuid;
  v_tool_org uuid;
  v_source text;
  v_record jsonb;
begin
  -- NEW has a different row type for each table using this trigger. Reading
  -- table-specific fields directly here causes PostgreSQL to fail before the
  -- CASE branch can protect it (for example, outbound_messages has no source).
  v_record := to_jsonb(new);
  v_source := case tg_table_name
    when 'marketing_leads' then nullif(btrim(coalesce(v_record ->> 'source', '')), '')
    when 'customers' then nullif(btrim(coalesce(v_record ->> 'lead_source', '')), '')
    when 'invoices' then nullif(btrim(coalesce(v_record ->> 'sale_source', '')), '')
    else null
  end;

  -- Preserve all existing messages, groups, contacts and business records that
  -- are not linked to an advertising campaign.
  if new.advertising_campaign_id is null and new.advertising_campaign_tool_id is null then
    if v_source = 'advertising_campaign' then
      raise exception 'رکوردهای منتسب به کمپین تبلیغاتی باید کمپین یا ابزار تبلیغاتی معتبر داشته باشند.'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if new.advertising_campaign_id is null and new.advertising_campaign_tool_id is not null then
    select campaign_id, org_id
      into v_tool_campaign, v_tool_org
      from public.advertising_campaign_tools
     where id = new.advertising_campaign_tool_id;

    if v_tool_campaign is null or v_tool_org is distinct from new.org_id then
      raise exception 'ابزار تبلیغاتی متعلق به سازمان جاری نیست.' using errcode = '23514';
    end if;

    new.advertising_campaign_id := v_tool_campaign;
  end if;

  select org_id
    into v_campaign_org
    from public.advertising_campaigns
   where id = new.advertising_campaign_id;

  if v_campaign_org is null or v_campaign_org is distinct from new.org_id then
    raise exception 'کمپین تبلیغاتی متعلق به سازمان جاری نیست.' using errcode = '23514';
  end if;

  if new.advertising_campaign_tool_id is not null then
    select campaign_id, org_id
      into v_tool_campaign, v_tool_org
      from public.advertising_campaign_tools
     where id = new.advertising_campaign_tool_id;

    if v_tool_campaign is null
       or v_tool_campaign is distinct from new.advertising_campaign_id
       or v_tool_org is distinct from new.org_id then
      raise exception 'ابزار تبلیغاتی با کمپین یا سازمان رکورد سازگار نیست.' using errcode = '23514';
    end if;
  end if;

  -- Update the source marker only for tables that actually contain that field.
  if tg_table_name = 'marketing_leads' then
    new := jsonb_populate_record(
      new,
      jsonb_set(to_jsonb(new), '{source}', '"advertising_campaign"'::jsonb, true)
    );
  elsif tg_table_name = 'customers' then
    new := jsonb_populate_record(
      new,
      jsonb_set(to_jsonb(new), '{lead_source}', '"advertising_campaign"'::jsonb, true)
    );
  elsif tg_table_name = 'invoices' then
    new := jsonb_populate_record(
      new,
      jsonb_set(to_jsonb(new), '{sale_source}', '"advertising_campaign"'::jsonb, true)
    );
  end if;

  return new;
end;
$$;


--
-- Name: validate_content_calendar_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_content_calendar_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_calendar_org_id uuid;
begin
  if new.content_calendar_id is null then
    return new;
  end if;

  if tg_op = 'UPDATE' and new.content_calendar_id is not distinct from old.content_calendar_id then
    return new;
  end if;

  if not public.org_has_plan_feature(new.org_id, 'content_calendar', false) then
    raise exception 'ویژگی تقویم محتوایی در پلن این سازمان فعال نیست.' using errcode = '42501';
  end if;

  select calendar_row.org_id into v_calendar_org_id
  from public.content_calendars calendar_row
  where calendar_row.id = new.content_calendar_id;

  if v_calendar_org_id is null or v_calendar_org_id <> new.org_id then
    raise exception 'تقویم محتوایی انتخاب‌شده در سازمان جاری قابل استفاده نیست.' using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: validate_counterparty_financial_role_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_counterparty_financial_role_links() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_table_name = 'customers' then
    if new.linked_supplier_id is not null and not exists (
      select 1 from public.suppliers where id = new.linked_supplier_id and org_id = new.org_id
    ) then raise exception 'تامین‌کننده مرتبط باید متعلق به همین سازمان باشد'; end if;
    if new.linked_employee_id is not null and not exists (
      select 1 from public.employees where id = new.linked_employee_id and org_id = new.org_id
    ) then raise exception 'کارمند مرتبط باید متعلق به همین سازمان باشد'; end if;
  elsif tg_table_name = 'suppliers' then
    if new.linked_customer_id is not null and not exists (
      select 1 from public.customers where id = new.linked_customer_id and org_id = new.org_id
    ) then raise exception 'مشتری مرتبط باید متعلق به همین سازمان باشد'; end if;
    if new.linked_employee_id is not null and not exists (
      select 1 from public.employees where id = new.linked_employee_id and org_id = new.org_id
    ) then raise exception 'کارمند مرتبط باید متعلق به همین سازمان باشد'; end if;
  elsif tg_table_name = 'employees' then
    if new.linked_customer_id is not null and not exists (
      select 1 from public.customers where id = new.linked_customer_id and org_id = new.org_id
    ) then raise exception 'مشتری مرتبط باید متعلق به همین سازمان باشد'; end if;
    if new.linked_supplier_id is not null and not exists (
      select 1 from public.suppliers where id = new.linked_supplier_id and org_id = new.org_id
    ) then raise exception 'تامین‌کننده مرتبط باید متعلق به همین سازمان باشد'; end if;
  end if;
  return new;
end;
$$;


--
-- Name: validate_profile_mobile_uniqueness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_profile_mobile_uniqueness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  normalized_mobile text;
begin
  normalized_mobile := public.normalize_iran_mobile_e164(coalesce(new.mobile_1, new.mobile));

  if normalized_mobile is not null and exists (
    select 1
    from public.profiles p
    where p.id <> new.id
      and public.normalize_iran_mobile_e164(coalesce(p.mobile_1, p.mobile)) = normalized_mobile
  ) then
    raise exception using
      errcode = '23505',
      message = 'شماره موبایل این کاربر قبلا برای کاربر دیگری ثبت شده است.';
  end if;

  return new;
end;
$$;


--
-- Name: validate_reservation_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_reservation_capacity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_resource_id uuid;
  v_requested numeric;
  v_capacity integer;
  v_preparation_minutes integer;
  v_cleanup_minutes integer;
  v_reserved numeric;
  v_allow_overbooking boolean;
begin
  if public.current_org_id() is null or new.org_id <> public.current_org_id() then
    raise exception 'reservation organization mismatch';
  end if;
  if new.status in ('canceled', 'draft') then return new; end if;

  select coalesce((reservation_settings ->> 'allow_overbooking')::boolean, false)
    into v_allow_overbooking from public.company_settings where org_id = new.org_id limit 1;
  if v_allow_overbooking then return new; end if;

  for v_resource_id, v_requested in
    select nullif(item.value ->> 'resource_id', '')::uuid,
           sum(greatest(coalesce(nullif(item.value ->> 'quantity', '')::numeric, 1), 0))
      from jsonb_array_elements(coalesce(new."reservationItems", '[]'::jsonb)) item(value)
     where nullif(item.value ->> 'resource_id', '') is not null
     group by nullif(item.value ->> 'resource_id', '')::uuid
  loop
    -- قفل تراکنشی per-org/per-resource مانع عبور هم‌زمان دو رزرو از کنترل ظرفیت می‌شود.
    perform pg_advisory_xact_lock(hashtextextended(new.org_id::text || ':' || v_resource_id::text, 0));
    select capacity, preparation_minutes, cleanup_minutes
      into v_capacity, v_preparation_minutes, v_cleanup_minutes
      from public.reservation_resources
      where id = v_resource_id and org_id = new.org_id and status = 'active';
    if v_capacity is null then raise exception 'منبع قابل رزرو معتبر یا فعال نیست'; end if;
    select coalesce(sum(greatest(coalesce(nullif(i.value ->> 'quantity', '')::numeric, 1), 0)), 0)
      into v_reserved
      from public.reservations r cross join lateral jsonb_array_elements(coalesce(r."reservationItems", '[]'::jsonb)) i(value)
      where r.org_id = new.org_id and r.id <> new.id and r.status not in ('canceled', 'draft')
        and r.start_at - make_interval(mins => coalesce(v_preparation_minutes, 0)) < new.end_at + make_interval(mins => coalesce(v_cleanup_minutes, 0))
        and r.end_at + make_interval(mins => coalesce(v_cleanup_minutes, 0)) > new.start_at - make_interval(mins => coalesce(v_preparation_minutes, 0))
        and nullif(i.value ->> 'resource_id', '')::uuid = v_resource_id;
    if v_reserved + v_requested > v_capacity then raise exception 'ظرفیت منبع در بازه انتخاب‌شده تکمیل است'; end if;
  end loop;
  return new;
end;
$$;


--
-- Name: verify_delivery_confirm_otp(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_delivery_confirm_otp(p_code text, p_party text, p_phone text, p_otp_code text, p_confirmer_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid;
  v_delivery_id uuid;
  v_system_code text;
  v_status text;
  v_party text := btrim(coalesce(p_party, ''));
  v_phone text := public._delivery_normalize_phone(p_phone);
  v_stored_hash text;
  v_expires_at timestamptz;
  v_expected_hash text;
  v_delivered_done boolean := false;
  v_received_done boolean := false;
  v_confirmer_name text := left(btrim(coalesce(p_confirmer_name, 'مخاطب')), 160);
begin
  if v_party not in ('delivered_by', 'received_by') then
    return jsonb_build_object('error', 'invalid_party');
  end if;
  if v_phone !~ '^09[0-9]{9}$' then
    return jsonb_build_object('error', 'invalid_phone');
  end if;

  v_org_id := public._resolve_org_for_public_delivery(p_code);
  if v_org_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  select
    id,
    system_code,
    status,
    case when v_party = 'delivered_by' then delivered_by_confirm_otp_hash else received_by_confirm_otp_hash end,
    case when v_party = 'delivered_by' then delivered_by_confirm_otp_expires_at else received_by_confirm_otp_expires_at end,
    delivered_by_confirmed_at is not null,
    received_by_confirmed_at is not null
  into v_delivery_id, v_system_code, v_status, v_stored_hash, v_expires_at, v_delivered_done, v_received_done
  from public.delivery_forms
  where org_id = v_org_id
    and (public_slug = p_code or public_token = p_code)
  limit 1;

  if v_delivery_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  if v_status not in ('draft', 'pending_signature', 'signed') then
    return jsonb_build_object('error', 'invalid_status');
  end if;
  if (v_party = 'delivered_by' and v_delivered_done) or (v_party = 'received_by' and v_received_done) then
    return jsonb_build_object('error', 'already_confirmed');
  end if;
  if v_stored_hash is null or v_expires_at is null then
    return jsonb_build_object('error', 'otp_not_sent');
  end if;
  if now() > v_expires_at then
    return jsonb_build_object('error', 'otp_expired');
  end if;

  v_expected_hash := encode(sha256(cast(coalesce(p_otp_code, '') || v_phone as bytea)), 'hex');
  if v_stored_hash <> v_expected_hash then
    return jsonb_build_object('error', 'otp_invalid');
  end if;

  if v_party = 'delivered_by' then
    update public.delivery_forms
    set delivered_by_confirmed_at = now(),
        delivered_by_confirmer_name = v_confirmer_name,
        delivered_by_confirm_phone = v_phone,
        delivered_by_confirm_otp_hash = null,
        delivered_by_confirm_otp_expires_at = null
    where id = v_delivery_id and org_id = v_org_id;
  else
    update public.delivery_forms
    set received_by_confirmed_at = now(),
        received_by_confirmer_name = v_confirmer_name,
        received_by_confirm_phone = v_phone,
        received_by_confirm_otp_hash = null,
        received_by_confirm_otp_expires_at = null
    where id = v_delivery_id and org_id = v_org_id;
  end if;

  select delivered_by_confirmed_at is not null, received_by_confirmed_at is not null
  into v_delivered_done, v_received_done
  from public.delivery_forms
  where id = v_delivery_id and org_id = v_org_id;

  update public.delivery_forms
  set status = case when v_delivered_done and v_received_done then 'confirmed' else 'signed' end
  where id = v_delivery_id and org_id = v_org_id;

  insert into public.notes (org_id, module_id, record_id, content, author_name, is_public, metadata)
  values (
    v_org_id,
    'delivery_forms',
    v_delivery_id::text,
    case when v_party = 'delivered_by' then 'تحویل‌دهنده فرم تحویل را تایید کرد.' else 'تحویل‌گیرنده فرم تحویل را تایید کرد.' end,
    v_confirmer_name,
    true,
    jsonb_build_object(
      'source', 'online_delivery_confirm',
      'party', v_party,
      'phone', v_phone,
      'system_code', v_system_code
    )
  );

  return jsonb_build_object(
    'success', true,
    'confirmed_at', now(),
    'all_confirmed', v_delivered_done and v_received_done
  );
end;
$_$;


--
-- Name: verify_invoice_confirm_otp(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_invoice_confirm_otp(p_system_code text, p_module text, p_phone text, p_otp_code text, p_confirmer_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_invoice_id uuid;
  v_actual_system_code text;
  v_status text;
  v_stored_hash text;
  v_expires_at timestamptz;
  v_expected_hash text;
  v_phone_normalized text := public._normalize_phone_for_match(p_phone);
begin
  v_org_id := public._resolve_org_for_public_invoice(p_system_code, p_module);
  if v_org_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;

  if p_module = 'invoices' then
    select id, system_code, status, confirm_otp_hash, confirm_otp_expires_at
    into v_invoice_id, v_actual_system_code, v_status, v_stored_hash, v_expires_at
    from public.invoices
    where org_id = v_org_id
      and (public_slug = p_system_code or public_token = p_system_code)
    limit 1;
  else
    select id, system_code, status, confirm_otp_hash, confirm_otp_expires_at
    into v_invoice_id, v_actual_system_code, v_status, v_stored_hash, v_expires_at
    from public.purchase_invoices
    where org_id = v_org_id
      and (public_slug = p_system_code or public_token = p_system_code)
    limit 1;
  end if;

  if v_invoice_id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  if v_status not in ('created', 'proforma') then
    return jsonb_build_object('error', 'invalid_status');
  end if;
  if v_stored_hash is null or v_expires_at is null then
    return jsonb_build_object('error', 'otp_not_sent');
  end if;
  if now() > v_expires_at then
    return jsonb_build_object('error', 'otp_expired');
  end if;

  v_expected_hash := encode(sha256(cast(p_otp_code || v_phone_normalized as bytea)), 'hex');
  if v_stored_hash <> v_expected_hash then
    return jsonb_build_object('error', 'otp_invalid');
  end if;

  if p_module = 'invoices' then
    update public.invoices
    set status = 'confirmed',
        customer_confirmed_at = now(),
        customer_confirmer_name = left(btrim(coalesce(p_confirmer_name, 'مشتری')), 160),
        confirm_otp_hash = null,
        confirm_otp_expires_at = null
    where id = v_invoice_id
      and org_id = v_org_id;
  else
    update public.purchase_invoices
    set status = 'confirmed',
        supplier_confirmed_at = now(),
        supplier_confirmer_name = left(btrim(coalesce(p_confirmer_name, 'تامین‌کننده')), 160),
        confirm_otp_hash = null,
        confirm_otp_expires_at = null
    where id = v_invoice_id
      and org_id = v_org_id;
  end if;

  insert into public.notes (org_id, module_id, record_id, content, author_name, is_public, metadata)
  values (
    v_org_id,
    p_module,
    v_invoice_id::text,
    'فاکتور توسط ' || left(btrim(coalesce(p_confirmer_name, 'مخاطب')), 160) || ' تایید شد.',
    left(btrim(coalesce(p_confirmer_name, 'مخاطب')), 160),
    true,
    jsonb_build_object(
      'source', 'online_invoice_confirm',
      'phone', v_phone_normalized,
      'system_code', v_actual_system_code
    )
  );

  return jsonb_build_object('success', true, 'confirmed_at', now());
end;
$$;


--
-- Name: void_commission_calculation(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_commission_calculation(p_ledger_entry_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_org_id uuid := public.current_org_id();
  v_ledger_ids uuid[] := array[]::uuid[];
  v_source_keys text[] := array[]::text[];
  v_scope_token uuid := gen_random_uuid();
  v_requested_count integer := 0;
  v_verified_count integer := 0;
  v_released_count integer := 0;
begin
  if v_org_id is null then
    raise exception 'organization_context_required';
  end if;
  if not public.current_user_has_role_permission_entry('payroll_slips', 'edit', null, true) then
    raise exception 'commission_calculation_delete_not_allowed';
  end if;

  select coalesce(array_agg(distinct item), array[]::uuid[])
  into v_ledger_ids
  from unnest(coalesce(p_ledger_entry_ids, array[]::uuid[])) item
  where item is not null;

  v_requested_count := coalesce(cardinality(v_ledger_ids), 0);
  if v_requested_count = 0 then
    raise exception 'commission_calculation_not_found';
  end if;

  perform 1
  from public.payroll_calculation_entries entry
  where entry.org_id = v_org_id
    and entry.id = any(v_ledger_ids)
  for update;

  select count(*)
  into v_verified_count
  from public.payroll_calculation_entries entry
  where entry.org_id = v_org_id
    and entry.id = any(v_ledger_ids)
    and entry.source_type = 'commission'
    and (
      (
        entry.status in ('draft', 'proposed')
        and entry.payroll_slip_id is null
      )
      or (
        entry.status = 'included_in_payroll'
        and not exists (
          select 1
          from public.payroll_slips slip
          where slip.id = entry.payroll_slip_id
            and slip.org_id = entry.org_id
            and coalesce(slip.status, 'draft') <> 'canceled'
        )
      )
    );

  if v_verified_count <> v_requested_count then
    raise exception 'commission_calculation_cannot_be_deleted';
  end if;

  -- اگر فیش حذف یا لغو شده باشد، entry قدیمی ممکن است هنوز included مانده
  -- باشد. همان entry در همین تراکنش مستقیماً void می‌شود؛ وجود فیش فعال در
  -- شرط بالا fail-closed است و حذف پورسانت را متوقف می‌کند.

  -- فقط قلم‌هایی آزاد می‌شوند که مبلغ مثبت همین محاسبه را ساخته‌اند؛ تصمیم‌های
  -- دستی یا اقلام انتخاب‌نشده‌ای که صرفاً در snapshot آمده‌اند تغییر نمی‌کنند.
  select coalesce(array_agg(distinct source.source_key), array[]::text[])
  into v_source_keys
  from public.payroll_calculation_entries entry
  cross join lateral (
    select nullif(trim(line.value ->> 'source_key'), '') source_key
    from jsonb_array_elements(
      case when jsonb_typeof(entry.details -> 'rows') = 'array'
        then entry.details -> 'rows' else '[]'::jsonb end
    ) invoice_row(value)
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(invoice_row.value -> 'lines') = 'array'
        then invoice_row.value -> 'lines' else '[]'::jsonb end
    ) line(value)
    where case
      when coalesce(line.value ->> 'commission_amount', line.value ->> 'selected_amount', '')
        ~ '^[0-9]+([.][0-9]+)?$'
      then coalesce(line.value ->> 'commission_amount', line.value ->> 'selected_amount')::numeric > 0
      else false
    end

    union

    select nullif(trim(line.value ->> 'source_key'), '') source_key
    from jsonb_array_elements(
      case when jsonb_typeof(entry.details -> 'lines') = 'array'
        then entry.details -> 'lines' else '[]'::jsonb end
    ) line(value)
    where case
      when coalesce(line.value ->> 'commission_amount', line.value ->> 'selected_amount', '')
        ~ '^[0-9]+([.][0-9]+)?$'
      then coalesce(line.value ->> 'commission_amount', line.value ->> 'selected_amount')::numeric > 0
      else false
    end
  ) source
  where entry.org_id = v_org_id
    and entry.id = any(v_ledger_ids)
    and source.source_key is not null;

  insert into public.payroll_source_mutation_scopes(scope_token, org_id, table_name, record_id)
  select v_scope_token, v_org_id, 'payroll_calculation_entries', item
  from unnest(v_ledger_ids) item
  union all
  select v_scope_token, v_org_id, 'commission_drafts', draft.id
  from public.commission_drafts draft
  where draft.org_id = v_org_id
    and draft.source_key = any(v_source_keys)
  on conflict do nothing;

  update public.commission_drafts draft
  set posted_amount = 0,
      remaining_amount = greatest(0, draft.entitled_amount),
      draft_status = 'draft',
      updated_at = now(),
      updated_by = auth.uid()
  where draft.org_id = v_org_id
    and draft.source_key = any(v_source_keys);
  get diagnostics v_released_count = row_count;

  update public.payroll_calculation_entries entry
  set status = 'voided',
      updated_at = now(),
      updated_by = auth.uid()
  where entry.org_id = v_org_id
    and entry.id = any(v_ledger_ids);

  delete from public.payroll_source_mutation_scopes
  where scope_token = v_scope_token;

  return jsonb_build_object(
    'voided_calculations', v_verified_count,
    'released_commission_items', v_released_count
  );
end;
$_$;


--
-- Name: voip_org_namespace(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.voip_org_namespace(p_org_id uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select 'k_' || left(replace(coalesce(p_org_id, '00000000-0000-0000-0000-000000000000'::uuid)::text, '-', ''), 12);
$$;


--
-- Name: voip_sync_endpoint_realtime(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.voip_sync_endpoint_realtime() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ns text;
  v_ext_clean text;
  v_pjsip_id text;
  v_context text;
  v_transport text;
  v_callerid text;
begin
  if tg_op = 'DELETE' then
    delete from public.ps_endpoints where id = old.pjsip_id;
    delete from public.ps_auths where id = old.pjsip_id;
    delete from public.ps_aors where id = old.pjsip_id;
    return old;
  end if;

  v_ns := public.voip_org_namespace(new.org_id);
  v_ext_clean := regexp_replace(coalesce(new.extension, ''), '[^a-zA-Z0-9_]', '', 'g');
  if v_ext_clean = '' then
    raise exception 'شماره داخلی SIP معتبر نیست.';
  end if;

  if nullif(trim(coalesce(new.sip_secret, '')), '') is null then
    new.sip_secret := encode(gen_random_bytes(18), 'base64');
  end if;

  v_pjsip_id := v_ns || '_' || v_ext_clean;
  if tg_op = 'UPDATE' and old.pjsip_id is distinct from v_pjsip_id then
    delete from public.ps_endpoints where id = old.pjsip_id;
    delete from public.ps_auths where id = old.pjsip_id;
    delete from public.ps_aors where id = old.pjsip_id;
  end if;

  new.pjsip_id := v_pjsip_id;
  v_context := 'kalam-org-router';
  v_transport := case coalesce(new.transport, 'wss')
    when 'wss' then 'transport-wss'
    when 'tls' then 'transport-tls'
    when 'tcp' then 'transport-tcp'
    else 'transport-udp'
  end;
  v_callerid := format('%s <%s>', coalesce(nullif(trim(new.display_name), ''), v_ext_clean), v_ext_clean);

  if not coalesce(new.is_active, true) then
    delete from public.ps_endpoints where id = v_pjsip_id;
    delete from public.ps_auths where id = v_pjsip_id;
    delete from public.ps_aors where id = v_pjsip_id;
    return new;
  end if;

  insert into public.ps_aors (id, org_id, max_contacts, remove_existing, qualify_frequency)
  values (v_pjsip_id, new.org_id, coalesce(new.max_contacts, 3), 'yes', 30)
  on conflict (id) do update set
    org_id = excluded.org_id,
    max_contacts = excluded.max_contacts,
    remove_existing = excluded.remove_existing,
    qualify_frequency = excluded.qualify_frequency;

  insert into public.ps_auths (id, org_id, auth_type, username, password)
  values (v_pjsip_id, new.org_id, 'userpass', v_pjsip_id, new.sip_secret)
  on conflict (id) do update set
    org_id = excluded.org_id,
    auth_type = excluded.auth_type,
    username = excluded.username,
    password = excluded.password;

  insert into public.ps_endpoints (
    id, org_id, transport, aors, auth, context, disallow, allow,
    direct_media, force_rport, ice_support, rewrite_contact, rtp_symmetric,
    webrtc, dtls_auto_generate_cert, dtls_verify, dtls_setup,
    media_encryption, use_avpf, media_use_received_transport, rtcp_mux,
    callerid, identify_by
  )
  values (
    v_pjsip_id,
    new.org_id,
    v_transport,
    v_pjsip_id,
    v_pjsip_id,
    v_context,
    'all',
    case when coalesce(new.webrtc_enabled, true) then 'opus,alaw,ulaw' else 'alaw,ulaw' end,
    'no',
    'yes',
    case when coalesce(new.webrtc_enabled, true) then 'yes' else 'no' end,
    'yes',
    'yes',
    case when coalesce(new.webrtc_enabled, true) then 'yes' else 'no' end,
    case when coalesce(new.webrtc_enabled, true) then 'yes' else 'no' end,
    'fingerprint',
    'actpass',
    case when coalesce(new.webrtc_enabled, true) then 'dtls' else 'no' end,
    case when coalesce(new.webrtc_enabled, true) then 'yes' else 'no' end,
    case when coalesce(new.webrtc_enabled, true) then 'yes' else 'no' end,
    case when coalesce(new.webrtc_enabled, true) then 'yes' else 'no' end,
    v_callerid,
    'username,auth_username'
  )
  on conflict (id) do update set
    org_id = excluded.org_id,
    transport = excluded.transport,
    aors = excluded.aors,
    auth = excluded.auth,
    context = excluded.context,
    allow = excluded.allow,
    ice_support = excluded.ice_support,
    webrtc = excluded.webrtc,
    dtls_auto_generate_cert = excluded.dtls_auto_generate_cert,
    media_encryption = excluded.media_encryption,
    use_avpf = excluded.use_avpf,
    media_use_received_transport = excluded.media_use_received_transport,
    rtcp_mux = excluded.rtcp_mux,
    callerid = excluded.callerid;

  return new;
end;
$$;


--
-- Name: voip_sync_trunk_realtime(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.voip_sync_trunk_realtime() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ns text;
  v_trunk_id text;
  v_transport text;
  v_host text;
  v_port integer;
  v_server_uri text;
  v_client_uri text;
  v_contact_uri text;
begin
  if tg_op = 'DELETE' then
    if old.pjsip_trunk_id is not null then
      delete from public.ps_registrations where id = old.pjsip_trunk_id;
      delete from public.ps_identify where id = old.pjsip_trunk_id;
      delete from public.ps_endpoints where id = old.pjsip_trunk_id;
      delete from public.ps_auths where id = old.pjsip_trunk_id;
      delete from public.ps_aors where id = old.pjsip_trunk_id;
    end if;
    return old;
  end if;

  v_ns := public.voip_org_namespace(new.org_id);
  v_trunk_id := v_ns || '_trk_' || left(replace(new.id::text, '-', ''), 8);
  new.pjsip_trunk_id := v_trunk_id;
  v_host := nullif(trim(coalesce(new.sip_host, '')), '');
  v_port := coalesce(new.sip_port, 5060);
  v_transport := case coalesce(new.transport, 'udp')
    when 'wss' then 'transport-wss'
    when 'tls' then 'transport-tls'
    when 'tcp' then 'transport-tcp'
    else 'transport-udp'
  end;

  if not coalesce(new.is_active, true) or v_host is null then
    delete from public.ps_registrations where id = v_trunk_id;
    delete from public.ps_identify where id = v_trunk_id;
    delete from public.ps_endpoints where id = v_trunk_id;
    delete from public.ps_auths where id = v_trunk_id;
    delete from public.ps_aors where id = v_trunk_id;
    return new;
  end if;

  v_contact_uri := format('sip:%s:%s', v_host, v_port);

  insert into public.ps_aors (id, org_id, contact, max_contacts, qualify_frequency)
  values (v_trunk_id, new.org_id, v_contact_uri, 1, 60)
  on conflict (id) do update set
    org_id = excluded.org_id,
    contact = excluded.contact,
    qualify_frequency = excluded.qualify_frequency;

  if coalesce(new.auth_type, 'user_pass') <> 'ip_based' and nullif(trim(coalesce(new.sip_username, '')), '') is not null then
    insert into public.ps_auths (id, org_id, auth_type, username, password)
    values (v_trunk_id, new.org_id, 'userpass', trim(new.sip_username), coalesce(new.sip_secret, ''))
    on conflict (id) do update set
      org_id = excluded.org_id,
      username = excluded.username,
      password = excluded.password;
  else
    delete from public.ps_auths where id = v_trunk_id;
  end if;

  insert into public.ps_endpoints (
    id, org_id, transport, aors, outbound_auth, context, disallow, allow,
    direct_media, force_rport, ice_support, rewrite_contact, rtp_symmetric,
    webrtc, dtls_auto_generate_cert, media_encryption, use_avpf,
    media_use_received_transport, rtcp_mux, from_user, from_domain, identify_by
  )
  values (
    v_trunk_id,
    new.org_id,
    v_transport,
    v_trunk_id,
    case when coalesce(new.auth_type, 'user_pass') <> 'ip_based' and nullif(trim(coalesce(new.sip_username, '')), '') is not null then v_trunk_id else null end,
    'from-trunk',
    'all',
    'alaw,ulaw,opus',
    'no',
    'yes',
    'no',
    'yes',
    'yes',
    'no',
    'no',
    'no',
    'no',
    'no',
    'no',
    nullif(trim(coalesce(new.sip_username, '')), ''),
    v_host,
    'ip,username'
  )
  on conflict (id) do update set
    org_id = excluded.org_id,
    transport = excluded.transport,
    aors = excluded.aors,
    outbound_auth = excluded.outbound_auth,
    context = excluded.context,
    from_user = excluded.from_user,
    from_domain = excluded.from_domain;

  insert into public.ps_identify (id, org_id, endpoint, match)
  values (v_trunk_id, new.org_id, v_trunk_id, v_host)
  on conflict (id) do update set
    org_id = excluded.org_id,
    endpoint = excluded.endpoint,
    match = excluded.match;

  if coalesce(new.auth_type, 'user_pass') <> 'ip_based' and nullif(trim(coalesce(new.sip_username, '')), '') is not null then
    v_server_uri := format('sip:%s:%s', v_host, v_port);
    v_client_uri := format('sip:%s@%s:%s', trim(new.sip_username), v_host, v_port);
    insert into public.ps_registrations (
      id, org_id, transport, outbound_auth, server_uri, client_uri, contact_user, endpoint
    )
    values (
      v_trunk_id, new.org_id, v_transport, v_trunk_id, v_server_uri, v_client_uri, trim(new.sip_username), v_trunk_id
    )
    on conflict (id) do update set
      org_id = excluded.org_id,
      transport = excluded.transport,
      outbound_auth = excluded.outbound_auth,
      server_uri = excluded.server_uri,
      client_uri = excluded.client_uri,
      contact_user = excluded.contact_user,
      endpoint = excluded.endpoint;
  else
    delete from public.ps_registrations where id = v_trunk_id;
  end if;

  return new;
end;
$$;


--
-- Name: worker_local_installation(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_local_installation(p_action text, p_id uuid DEFAULT NULL::uuid, p_lease uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare j public.saas_local_jobs;i public.saas_local_installations;r public.saas_local_releases; o uuid;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception using errcode='42501',message='Worker access required'; end if;
 if p_action='expired_artifacts' then
  return coalesce((select jsonb_agg(x) from (select id,result->>'artifact_path' as path from public.saas_local_jobs
   where kind<>'prepare' and status='succeeded' and (result->>'expires_at')::timestamptz<=now() and not result ? 'purged_at'
   order by finished_at limit 100)x),'[]'::jsonb);
 elsif p_action='artifact_purged' then
  update public.saas_local_jobs set result=(result-'artifact_path')||jsonb_build_object('purged_at',now())
   where id=p_id and kind<>'prepare' and status='succeeded' and (result->>'expires_at')::timestamptz<=now();
  return jsonb_build_object('success',true);
 elsif p_action='restore_receipt' then
  select * into j from public.saas_local_jobs where id=p_id and status='succeeded' and kind in ('export_trial','export_final') for update;
  if not found or p_payload#>>'{receipt,installation_id}' is distinct from j.installation_id::text or p_payload#>>'{receipt,checksum}' is distinct from j.result->>'checksum'
   or p_payload#>>'{receipt,version}' is distinct from j.result->>'version' or p_payload#>>'{receipt,password_login}' is distinct from 'passed'
   or p_payload#>>'{receipt,data_integrity}' is distinct from 'passed' then raise exception 'Restore receipt does not match the snapshot'; end if;
  update public.saas_local_jobs set result=result||jsonb_build_object('restore_verified',true) where id=j.id;
  if j.kind='export_final' then
   update public.saas_local_transfer_locks set state='cutover' where installation_id=j.installation_id;
   update public.saas_local_installations set status='awaiting_cutover' where id=j.installation_id;
  end if;
  insert into public.saas_local_events(org_id,installation_id,job_id,event_type,message,actor_id) values(j.org_id,j.installation_id,j.id,'restore_verified','بازیابی و ورود با رمز قبلی با رسید امضاشده تأیید شد.',(p_payload->>'actor')::uuid);
  return jsonb_build_object('success',true);
 elsif p_action='publish' then
  o:=(p_payload->>'org_id')::uuid;
  if not public.org_is_saas_admin(o) or p_payload#>>'{manifest,checks,offline_install}' is distinct from 'passed'
   or p_payload#>>'{manifest,checks,clean_database}' is distinct from 'passed' or p_payload#>>'{manifest,checks,central_release}' is distinct from 'passed'
   then raise exception 'Release verification is incomplete'; end if;
  perform pg_advisory_xact_lock(hashtext(o::text||':local-release'));
  update public.saas_local_releases set is_current_central=false where org_id=o and is_current_central;
  insert into public.saas_local_releases(id,org_id,version,commit_sha,schema_version,manifest,artifact_path,signature_path,checksum,is_current_central,verified_at)
  values(coalesce((p_payload->>'id')::uuid,gen_random_uuid()),o,p_payload->>'version',p_payload->>'commit_sha',p_payload->>'schema_version',p_payload->'manifest',p_payload->>'artifact_path',p_payload->>'signature_path',p_payload->>'checksum',true,now());
  return jsonb_build_object('success',true);
 elsif p_action='claim' then
  -- Expired work may have had side effects: it is never blindly executed again.
  update public.saas_local_jobs set status='needs_review',error_code='WORKER_INTERRUPTED',message='اجرای worker قطع شده؛ خروجی و قفل انتقال باید بررسی شوند.'
   where status='running' and lease_until<now();
  select * into j from public.saas_local_jobs where status='queued' order by requested_at for update skip locked limit 1;
  if not found then return null; end if;
  update public.saas_local_jobs set status='running',stage='preflight',started_at=coalesce(started_at,now()),lease_token=gen_random_uuid(),lease_until=now()+interval '2 minutes',attempt=attempt+1 where id=j.id returning * into j;
 else
  select * into j from public.saas_local_jobs where id=p_id and status='running' and lease_token=p_lease and lease_until>now() for update;
  if not found then raise exception 'Job lease is no longer valid'; end if;
  if p_action='heartbeat' then
   update public.saas_local_jobs set lease_until=now()+interval '2 minutes' where id=j.id;
  elsif p_action='stage' then
   if coalesce(p_payload->>'stage','') !~ '^[a-z_]{1,48}$' then raise exception 'Invalid stage'; end if;
   update public.saas_local_jobs set stage=p_payload->>'stage',message=left(p_payload->>'message',300) where id=j.id;
   insert into public.saas_local_events(org_id,installation_id,job_id,event_type,stage,message) values(j.org_id,j.installation_id,j.id,'stage',p_payload->>'stage',left(p_payload->>'message',300));
  elsif p_action in ('succeed','fail') then
   if p_action='succeed' and (coalesce(p_payload#>>'{result,artifact_path}','') not like j.org_id::text||'/'||j.installation_id::text||'/'||j.id::text||'/%'
    or p_payload#>>'{result,artifact_path}' like '%..%' or coalesce(p_payload#>>'{result,checksum}','') !~ '^[a-f0-9]{64}$'
    or (j.kind<>'prepare' and ((p_payload#>>'{result,expires_at}')::timestamptz is null or (p_payload#>>'{result,expires_at}')::timestamptz>now()+interval '7 days')))
    then raise exception 'Verified artifact is required'; end if;
   update public.saas_local_jobs set status=case when p_action='succeed' then 'succeeded' else 'failed' end,stage=case when p_action='succeed' then 'complete' else stage end,
    finished_at=now(),lease_until=null,result=case when p_action='succeed' then p_payload->'result' else '{}'::jsonb end,
    error_code=left(p_payload->>'error_code',80),message=left(p_payload->>'message',300) where id=j.id;
   update public.saas_local_installations set status=case when p_action='fail' then 'failed' when j.kind='prepare' then 'ready' when j.kind='export_trial' then 'trial' else 'awaiting_cutover' end,updated_at=now() where id=j.installation_id;
   insert into public.saas_local_events(org_id,installation_id,job_id,event_type,message) values(j.org_id,j.installation_id,j.id,p_action,left(p_payload->>'message',300));
  else raise exception 'Unknown worker action'; end if;
 end if;
 select * into i from public.saas_local_installations where id=j.installation_id;
 select * into r from public.saas_local_releases where id=j.release_id;
 return jsonb_build_object('job',to_jsonb(j),'installation',to_jsonb(i),'release',to_jsonb(r));
end $_$;


--
-- Name: workflow_create_billboard_status_change(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_create_billboard_status_change(p_org_id uuid, p_actor_user_id uuid, p_input jsonb, p_origin_execution_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_input jsonb := coalesce(p_input, '{}'::jsonb);
  v_billboard public.billboards%rowtype;
  v_billboard_id uuid := nullif(trim(coalesce(v_input ->> 'billboard_id', '')), '')::uuid;
  v_status text := nullif(trim(coalesce(v_input ->> 'target_status', '')), '');
  v_mode text := lower(coalesce(nullif(trim(v_input ->> 'application_mode'), ''), 'main_status'));
  v_customer_id uuid := nullif(trim(coalesce(v_input ->> 'customer_id', '')), '')::uuid;
  v_invoice_id uuid := nullif(trim(coalesce(v_input ->> 'invoice_id', '')), '')::uuid;
  v_lead_id uuid := nullif(trim(coalesce(v_input ->> 'marketing_lead_id', '')), '')::uuid;
  v_template_id uuid := nullif(trim(coalesce(v_input ->> 'process_template_id', '')), '')::uuid;
  v_template_snapshot jsonb := '{}'::jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'دسترسی ثبت خودکار تغییر وضعیت تابلو وجود ندارد.' using errcode = '42501'; end if;
  if p_org_id is null or p_actor_user_id is null or jsonb_typeof(v_input) <> 'object' then raise exception 'اطلاعات ثبت خودکار تغییر وضعیت تابلو کامل نیست.' using errcode = '22023'; end if;
  if not exists (select 1 from public.profiles where id = p_actor_user_id and org_id = p_org_id)
     or not public.org_has_plan_module(p_org_id, 'billboards', false)
     or not public.org_has_plan_feature(p_org_id, 'billboard_status_management', true) then raise exception 'دسترسی سازمانی معتبر برای ثبت تغییر وضعیت وجود ندارد.' using errcode = '42501'; end if;
  if v_status not in ('free','oral_reserve','final_reserve','in_line','opening','near_finish','opening_deadline_ended','pickup_queue','inactive','blocked') then raise exception 'وضعیت مقصد معتبر نیست.' using errcode = '22023'; end if;
  if v_mode not in ('main_status', 'add_tag') or (v_mode = 'add_tag' and v_status not in ('oral_reserve','final_reserve','in_line')) then raise exception 'نحوه اعمال وضعیت معتبر نیست.' using errcode = '22023'; end if;
  if v_status = 'opening' and (nullif(trim(coalesce(v_input ->> 'start_date', '')), '') is null or nullif(trim(coalesce(v_input ->> 'end_date', '')), '') is null) then raise exception 'برای وضعیت در حال اکران، تاریخ شروع و پایان اکران الزامی است.' using errcode = '22023'; end if;
  select * into v_billboard from public.billboards where id = v_billboard_id and org_id = p_org_id for share;
  if not found then raise exception 'تابلوی انتخاب‌شده در سازمان جاری پیدا نشد.' using errcode = 'P0002'; end if;
  if v_customer_id is not null and not exists (select 1 from public.customers where id = v_customer_id and org_id = p_org_id) then raise exception 'مشتری انتخاب‌شده معتبر نیست.' using errcode = '22023'; end if;
  if v_invoice_id is not null and not exists (select 1 from public.invoices where id = v_invoice_id and org_id = p_org_id) then raise exception 'فاکتور انتخاب‌شده معتبر نیست.' using errcode = '22023'; end if;
  if v_lead_id is not null and not exists (select 1 from public.marketing_leads where id = v_lead_id and org_id = p_org_id) then raise exception 'لید انتخاب‌شده معتبر نیست.' using errcode = '22023'; end if;
  if v_template_id is not null then
    if not exists (
      select 1 from public.process_templates
      where id = v_template_id and org_id = p_org_id
        and ('billboard_status_changes' = module_id or 'billboard_status_changes' = any(coalesce(module_ids, '{}'::text[])))
    ) then
      raise exception 'الگوی فرآیند انتخاب‌شده برای درخواست تغییر وضعیت تابلو سازگار نیست.' using errcode = '22023';
    end if;
    select jsonb_build_object(
      'template', to_jsonb(template_row),
      'stages', coalesce((
        select jsonb_agg(to_jsonb(stage_row) order by stage_row.sort_order)
        from public.process_template_stages stage_row
        where stage_row.template_id = template_row.id
      ), '[]'::jsonb)
    ) into v_template_snapshot
    from public.process_templates template_row
    where template_row.id = v_template_id and template_row.org_id = p_org_id;
  end if;
  perform set_config('app.workflow_origin_execution_key', coalesce(nullif(trim(p_origin_execution_key), ''), ''), true);
  insert into public.billboard_status_changes (org_id, billboard_id, source_status, target_status, application_mode, execution_source, customer_id, invoice_id, marketing_lead_id, start_date, end_date, block_reason, description, requested_by, process_template_id, process_template_snapshot)
  values (p_org_id, v_billboard.id, v_billboard.status, v_status, v_mode, 'workflow', v_customer_id, v_invoice_id, v_lead_id, nullif(trim(coalesce(v_input ->> 'start_date', '')), '')::date, nullif(trim(coalesce(v_input ->> 'end_date', '')), '')::date, nullif(trim(coalesce(v_input ->> 'block_reason', '')), ''), nullif(trim(coalesce(v_input ->> 'description', '')), ''), p_actor_user_id, v_template_id, v_template_snapshot)
  returning id into v_id;
  perform public.apply_billboard_status_change(v_id, p_org_id, p_actor_user_id, true);
  return v_id;
end;
$$;


--
-- Name: workflow_interval_scheduled_due_at(timestamp with time zone, integer, text, text, timestamp with time zone, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_interval_scheduled_due_at(p_last_run_at timestamp with time zone, p_interval_value integer, p_interval_unit text, p_interval_at text, p_interval_first_run_at timestamp with time zone, p_interval_minute integer, p_interval_day_of_month integer, p_now timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_unit text := lower(coalesce(nullif(p_interval_unit, ''), 'day'));
  v_value integer := greatest(coalesce(p_interval_value, 1), 1);
  v_now_local timestamp := p_now at time zone 'Asia/Tehran';
  v_anchor timestamptz;
  v_candidate_local timestamp;
  v_candidate timestamptz;
  v_due timestamptz := null;
  v_time_text text;
  v_time_match text[];
  v_hour integer := null;
  v_minute integer := null;
  v_month_days integer;
  v_target_day integer;
  v_i integer;
begin
  if v_unit not in ('hour', 'day', 'week', 'month') then
    v_unit := 'day';
  end if;

  v_time_text := translate(
    coalesce(p_interval_at, ''),
    '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩',
    '01234567890123456789'
  );
  v_time_match := regexp_match(v_time_text, '^\s*(\d{1,2})\s*:\s*(\d{1,2})');
  if v_time_match is not null then
    v_hour := v_time_match[1]::integer;
    v_minute := v_time_match[2]::integer;
    if v_hour < 0 or v_hour > 23 or v_minute < 0 or v_minute > 59 then
      v_hour := null;
      v_minute := null;
    end if;
  end if;

  if p_last_run_at is null then
    if p_interval_first_run_at is not null then
      if p_now < p_interval_first_run_at then
        return null;
      end if;
      if v_unit <> 'week' then
        v_anchor := p_interval_first_run_at;
        v_due := p_interval_first_run_at;
      end if;
    end if;

    if v_anchor is null then
      if v_unit = 'hour' then
        if p_interval_minute is null then
          return p_now;
        end if;
        v_candidate_local := date_trunc('hour', v_now_local)
          + make_interval(mins => least(greatest(p_interval_minute, 0), 59));
        v_candidate := v_candidate_local at time zone 'Asia/Tehran';
        if v_candidate <= p_now then
          return v_candidate;
        end if;
        return null;
      elsif v_unit in ('day', 'week') then
        if v_hour is null or v_minute is null then
          return p_now;
        end if;
        v_candidate_local := date_trunc('day', v_now_local)
          + make_interval(hours => v_hour, mins => v_minute);
        v_candidate := v_candidate_local at time zone 'Asia/Tehran';
        if v_candidate <= p_now then
          return v_candidate;
        end if;
        return null;
      else
        if p_interval_day_of_month is not null then
          v_month_days := extract(day from (
            date_trunc('month', v_now_local) + interval '1 month' - interval '1 day'
          ))::integer;
          v_target_day := least(greatest(p_interval_day_of_month, 1), v_month_days);
          if extract(day from v_now_local)::integer <> v_target_day then
            return null;
          end if;
        end if;

        if v_hour is null or v_minute is null then
          return p_now;
        end if;
        v_candidate_local := date_trunc('day', v_now_local)
          + make_interval(hours => v_hour, mins => v_minute);
        v_candidate := v_candidate_local at time zone 'Asia/Tehran';
        if v_candidate <= p_now then
          return v_candidate;
        end if;
        return null;
      end if;
    end if;
  else
    v_anchor := p_last_run_at;
  end if;

  v_candidate_local := v_anchor at time zone 'Asia/Tehran';

  for v_i in 1..10000 loop
    if v_unit = 'hour' then
      v_candidate_local := v_candidate_local + make_interval(hours => v_value);
      if p_interval_minute is not null then
        v_candidate_local := date_trunc('hour', v_candidate_local)
          + make_interval(mins => least(greatest(p_interval_minute, 0), 59));
      end if;
    elsif v_unit = 'day' then
      v_candidate_local := v_candidate_local + make_interval(days => v_value);
      if v_hour is not null and v_minute is not null then
        v_candidate_local := date_trunc('day', v_candidate_local)
          + make_interval(hours => v_hour, mins => v_minute);
      end if;
    elsif v_unit = 'week' then
      v_candidate_local := v_candidate_local + make_interval(days => v_value * 7);
      if v_hour is not null and v_minute is not null then
        v_candidate_local := date_trunc('day', v_candidate_local)
          + make_interval(hours => v_hour, mins => v_minute);
      end if;
    else
      v_candidate_local := v_candidate_local + make_interval(months => v_value);
      if p_interval_day_of_month is not null then
        v_month_days := extract(day from (
          date_trunc('month', v_candidate_local) + interval '1 month' - interval '1 day'
        ))::integer;
        v_target_day := least(greatest(p_interval_day_of_month, 1), v_month_days);
        v_candidate_local := date_trunc('month', v_candidate_local)
          + make_interval(days => v_target_day - 1)
          + (v_candidate_local - date_trunc('day', v_candidate_local));
      end if;
      if v_hour is not null and v_minute is not null then
        v_candidate_local := date_trunc('day', v_candidate_local)
          + make_interval(hours => v_hour, mins => v_minute);
      end if;
    end if;

    v_candidate := v_candidate_local at time zone 'Asia/Tehran';
    if v_candidate <= v_anchor then
      continue;
    end if;
    if v_candidate > p_now then
      exit;
    end if;
    v_due := v_candidate;
  end loop;

  return v_due;
end;
$$;


--
-- Name: workflow_patch_process_task_v2_custom_field_values(uuid, uuid, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_patch_process_task_v2_custom_field_values(p_org_id uuid, p_task_id uuid, p_field_values jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_origin_execution_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_task public.tasks%rowtype;
  v_recurrence jsonb;
  v_existing_values jsonb;
  v_links jsonb;
  v_field jsonb;
  v_field_key text;
  v_target_module text;
  v_record_id text;
  v_linked_module_ids text[] := array[]::text[];
  v_run_module_id text;
  v_run_record_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'دسترسی ذخیره خودکار فیلد فعالیت وجود ندارد.' using errcode = '42501'; end if;
  if p_org_id is null or p_task_id is null or jsonb_typeof(coalesce(p_field_values, '{}'::jsonb)) <> 'object' then raise exception 'مقادیر فیلدهای اختصاصی معتبر نیست.' using errcode = '22023'; end if;
  select * into v_task from public.tasks where id = p_task_id and org_id = p_org_id for update;
  if not found then raise exception 'فعالیت موردنظر در سازمان جاری پیدا نشد.' using errcode = 'P0002'; end if;
  v_recurrence := case when jsonb_typeof(v_task.recurrence_info) = 'object' then v_task.recurrence_info else '{}'::jsonb end;
  v_existing_values := case when jsonb_typeof(v_recurrence -> 'process_task_custom_field_values') = 'object' then v_recurrence -> 'process_task_custom_field_values' else '{}'::jsonb end;
  v_links := case when jsonb_typeof(v_recurrence -> 'process_links') = 'object' then v_recurrence -> 'process_links' else '{}'::jsonb end;
  for v_field in select value from jsonb_array_elements(case when jsonb_typeof(v_recurrence -> 'process_task_custom_fields') = 'array' then v_recurrence -> 'process_task_custom_fields' else '[]'::jsonb end) loop
    v_field_key := nullif(trim(coalesce(v_field ->> 'key', '')), '');
    v_target_module := nullif(trim(coalesce(v_field -> 'relationConfig' ->> 'targetModule', '')), '');
    if v_field_key is null or v_target_module is null or coalesce(v_field ->> 'type', '') <> 'relation'
       or coalesce((v_field -> 'relationConfig' ->> 'linkToProcessRelatedRecord')::boolean, (v_field -> 'relationConfig' ->> 'link_to_process_related_record')::boolean, false) is not true
       or not (p_field_values ? v_field_key) then continue; end if;
    v_record_id := nullif(trim(coalesce(p_field_values ->> v_field_key, '')), '');
    if v_record_id is null then continue; end if;
    if v_record_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'مقدار رابطه اختصاصی معتبر نیست.' using errcode = '22023'; end if;
    v_links := v_links || jsonb_build_object(v_target_module, v_record_id);
    v_linked_module_ids := array_append(v_linked_module_ids, v_target_module);
  end loop;
  v_recurrence := jsonb_set(v_recurrence, '{process_task_custom_field_values}', v_existing_values || p_field_values, true);
  v_recurrence := jsonb_set(v_recurrence, '{process_links}', v_links, true);
  perform set_config('app.workflow_origin_execution_key', coalesce(nullif(trim(p_origin_execution_key), ''), ''), true);
  update public.tasks set recurrence_info = v_recurrence, updated_at = now(), updated_by = coalesce(p_actor_user_id, updated_by)
  where id = v_task.id and org_id = p_org_id returning * into v_task;
  if v_task.process_run_id is not null and coalesce(array_length(v_linked_module_ids, 1), 0) > 0 then
    select module_id, record_id into v_run_module_id, v_run_record_id from public.process_runs where id = v_task.process_run_id and org_id = p_org_id;
    delete from public.process_run_links where process_run_id = v_task.process_run_id and org_id = p_org_id and module_id = any(v_linked_module_ids);
    for v_target_module, v_record_id in select key, value from jsonb_each_text(v_links) loop
      if not v_target_module = any(v_linked_module_ids) then continue; end if;
      insert into public.process_run_links (org_id, process_run_id, module_id, record_id, is_primary)
      values (p_org_id, v_task.process_run_id, v_target_module, v_record_id::uuid, v_target_module = v_run_module_id and v_record_id::uuid = v_run_record_id)
      on conflict (process_run_id, module_id, record_id) do update set org_id = excluded.org_id, is_primary = excluded.is_primary;
    end loop;
  end if;
  return jsonb_build_object('id', v_task.id, 'recurrence_info', v_task.recurrence_info, 'process_run_id', v_task.process_run_id, 'process_run_stage_id', v_task.process_run_stage_id, 'updated_at', v_task.updated_at);
end;
$_$;


--
-- Name: workflow_update_billboard_status_change(uuid, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_update_billboard_status_change(p_org_id uuid, p_actor_user_id uuid, p_change_id uuid, p_patch jsonb, p_origin_execution_key text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_change public.billboard_status_changes%rowtype;
  v_next jsonb;
  v_status text;
  v_mode text;
  v_key text;
  v_allowed text[] := array['target_status','application_mode','customer_id','invoice_id','marketing_lead_id','start_date','end_date','block_reason','description'];
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'دسترسی ویرایش خودکار تغییر وضعیت تابلو وجود ندارد.' using errcode = '42501'; end if;
  if p_org_id is null or p_actor_user_id is null or p_change_id is null or jsonb_typeof(coalesce(p_patch, '{}'::jsonb)) <> 'object' then raise exception 'اطلاعات ویرایش خودکار تغییر وضعیت تابلو کامل نیست.' using errcode = '22023'; end if;
  if not exists (select 1 from public.profiles where id = p_actor_user_id and org_id = p_org_id)
     or not public.org_has_plan_module(p_org_id, 'billboards', false)
     or not public.org_has_plan_feature(p_org_id, 'billboard_status_management', true) then raise exception 'دسترسی سازمانی معتبر برای ویرایش تغییر وضعیت وجود ندارد.' using errcode = '42501'; end if;
  for v_key in select jsonb_object_keys(p_patch) loop if not v_key = any(v_allowed) then raise exception 'فیلد ویرایش درخواست تغییر وضعیت معتبر نیست.' using errcode = '22023'; end if; end loop;
  select * into v_change from public.billboard_status_changes where id = p_change_id and org_id = p_org_id for update;
  if not found then raise exception 'درخواست تغییر وضعیت در سازمان جاری پیدا نشد.' using errcode = 'P0002'; end if;
  if v_change.request_status <> 'pending_approval' then raise exception 'فقط درخواست در انتظار تأیید قابل ویرایش است.' using errcode = '22023'; end if;
  v_next := to_jsonb(v_change) || p_patch;
  v_status := nullif(trim(coalesce(v_next ->> 'target_status', '')), '');
  v_mode := lower(coalesce(nullif(trim(v_next ->> 'application_mode'), ''), 'main_status'));
  if v_status not in ('free','oral_reserve','final_reserve','in_line','opening','near_finish','opening_deadline_ended','pickup_queue','inactive','blocked') then raise exception 'وضعیت مقصد معتبر نیست.' using errcode = '22023'; end if;
  if v_mode not in ('main_status','add_tag') or (v_mode = 'add_tag' and v_status not in ('oral_reserve','final_reserve','in_line')) then raise exception 'نحوه اعمال وضعیت معتبر نیست.' using errcode = '22023'; end if;
  if v_status = 'opening' and (nullif(trim(coalesce(v_next ->> 'start_date', '')), '') is null or nullif(trim(coalesce(v_next ->> 'end_date', '')), '') is null) then raise exception 'برای وضعیت در حال اکران، تاریخ شروع و پایان اکران الزامی است.' using errcode = '22023'; end if;
  if to_jsonb(v_change) @> p_patch then return false; end if;
  perform set_config('app.workflow_origin_execution_key', coalesce(nullif(trim(p_origin_execution_key), ''), ''), true);
  update public.billboard_status_changes set target_status = v_status, application_mode = v_mode, customer_id = nullif(trim(coalesce(v_next ->> 'customer_id', '')), '')::uuid, invoice_id = nullif(trim(coalesce(v_next ->> 'invoice_id', '')), '')::uuid, marketing_lead_id = nullif(trim(coalesce(v_next ->> 'marketing_lead_id', '')), '')::uuid, start_date = nullif(trim(coalesce(v_next ->> 'start_date', '')), '')::date, end_date = nullif(trim(coalesce(v_next ->> 'end_date', '')), '')::date, block_reason = nullif(trim(coalesce(v_next ->> 'block_reason', '')), ''), description = nullif(trim(coalesce(v_next ->> 'description', '')), ''), updated_at = now(), updated_by = p_actor_user_id where id = p_change_id and org_id = p_org_id;
  return true;
end;
$$;


--
-- Name: can_insert_object(text, text, uuid, jsonb); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO "storage"."objects" ("bucket_id", "name", "owner", "metadata") VALUES (bucketid, name, owner, metadata);
  -- hack to rollback the successful insert
  RAISE sqlstate 'PT200' using
  message = 'ROLLBACK',
  detail = 'rollback successful insert';
END
$$;


--
-- Name: enforce_bucket_name_length(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.enforce_bucket_name_length() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if length(new.name) > 100 then
        raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
    end if;
    return new;
end;
$$;


--
-- Name: extension(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.extension(name text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
_parts text[];
_filename text;
BEGIN
	select string_to_array(name, '/') into _parts;
	select _parts[array_length(_parts,1)] into _filename;
	-- @todo return the last part instead of 2
	return reverse(split_part(reverse(_filename), '.', 1));
END
$$;


--
-- Name: filename(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.filename(name text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
_parts text[];
BEGIN
	select string_to_array(name, '/') into _parts;
	return _parts[array_length(_parts,1)];
END
$$;


--
-- Name: foldername(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.foldername(name text) RETURNS text[]
    LANGUAGE plpgsql
    AS $$
DECLARE
_parts text[];
BEGIN
	select string_to_array(name, '/') into _parts;
	return _parts[1:array_length(_parts,1)-1];
END
$$;


--
-- Name: get_common_prefix(text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.get_common_prefix(p_key text, p_prefix text, p_delimiter text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT CASE
    WHEN position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)) > 0
    THEN left(p_key, length(p_prefix) + position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)))
    ELSE NULL
END;
$$;


--
-- Name: get_size_by_bucket(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.get_size_by_bucket() RETURNS TABLE(size bigint, bucket_id text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    return query
        select sum((metadata->>'size')::int) as size, obj.bucket_id
        from "storage".objects as obj
        group by obj.bucket_id;
END
$$;


--
-- Name: list_multipart_uploads_with_delimiter(text, text, text, integer, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.list_multipart_uploads_with_delimiter(bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, next_key_token text DEFAULT ''::text, next_upload_token text DEFAULT ''::text) RETURNS TABLE(key text, id text, created_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $_$
BEGIN
    RETURN QUERY EXECUTE
        'SELECT DISTINCT ON(key COLLATE "C") * from (
            SELECT
                CASE
                    WHEN position($2 IN substring(key from length($1) + 1)) > 0 THEN
                        substring(key from 1 for length($1) + position($2 IN substring(key from length($1) + 1)))
                    ELSE
                        key
                END AS key, id, created_at
            FROM
                storage.s3_multipart_uploads
            WHERE
                bucket_id = $5 AND
                key ILIKE $1 || ''%'' AND
                CASE
                    WHEN $4 != '''' AND $6 = '''' THEN
                        CASE
                            WHEN position($2 IN substring(key from length($1) + 1)) > 0 THEN
                                substring(key from 1 for length($1) + position($2 IN substring(key from length($1) + 1))) COLLATE "C" > $4
                            ELSE
                                key COLLATE "C" > $4
                            END
                    ELSE
                        true
                END AND
                CASE
                    WHEN $6 != '''' THEN
                        id COLLATE "C" > $6
                    ELSE
                        true
                    END
            ORDER BY
                key COLLATE "C" ASC, created_at ASC) as e order by key COLLATE "C" LIMIT $3'
        USING prefix_param, delimiter_param, max_keys, next_key_token, bucket_id, next_upload_token;
END;
$_$;


--
-- Name: list_objects_with_delimiter(text, text, text, integer, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text) RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;

    -- Configuration
    v_is_asc BOOLEAN;
    v_prefix TEXT;
    v_start TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';
    v_prefix := coalesce(prefix_param, '');
    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;
    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);

    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE "C")
    IF v_prefix = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix, 1) = delimiter_param THEN
        v_upper_bound := left(v_prefix, -1) || chr(ascii(delimiter_param) + 1);
    ELSE
        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'AND o.name COLLATE "C" < $3 ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" >= $2 ' ||
                'ORDER BY o.name COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'AND o.name COLLATE "C" >= $3 ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND o.name COLLATE "C" < $2 ' ||
                'ORDER BY o.name COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- ========================================================================
    -- SEEK INITIALIZATION: Determine starting position
    -- ========================================================================
    IF v_start = '' THEN
        IF v_is_asc THEN
            v_next_seek := v_prefix;
        ELSE
            -- DESC without cursor: find the last item in range
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_next_seek FROM storage.objects o
                WHERE o.bucket_id = _bucket_id
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;

            IF v_next_seek IS NOT NULL THEN
                v_next_seek := v_next_seek || delimiter_param;
            ELSE
                RETURN;
            END IF;
        END IF;
    ELSE
        -- Cursor provided: determine if it refers to a folder or leaf
        IF EXISTS (
            SELECT 1 FROM storage.objects o
            WHERE o.bucket_id = _bucket_id
              AND o.name COLLATE "C" LIKE v_start || delimiter_param || '%'
            LIMIT 1
        ) THEN
            -- Cursor refers to a folder
            IF v_is_asc THEN
                v_next_seek := v_start || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_start || delimiter_param;
            END IF;
        ELSE
            -- Cursor refers to a leaf object
            IF v_is_asc THEN
                v_next_seek := v_start || delimiter_param;
            ELSE
                v_next_seek := v_start;
            END IF;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= max_keys;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek AND o.name COLLATE "C" < v_upper_bound
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" >= v_next_seek
                ORDER BY o.name COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek
                ORDER BY o.name COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Emit and skip to next folder (no heap access needed)
            name := rtrim(v_common_prefix, delimiter_param);
            id := NULL;
            updated_at := NULL;
            created_at := NULL;
            last_accessed_at := NULL;
            metadata := NULL;
            RETURN NEXT;
            v_count := v_count + 1;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := left(v_common_prefix, -1) || chr(ascii(delimiter_param) + 1);
            ELSE
                v_next_seek := v_common_prefix;
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query USING _bucket_id, v_next_seek,
                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := v_current.name;
                    EXIT;
                END IF;

                -- Emit file
                name := v_current.name;
                id := v_current.id;
                updated_at := v_current.updated_at;
                created_at := v_current.created_at;
                last_accessed_at := v_current.last_accessed_at;
                metadata := v_current.metadata;
                RETURN NEXT;
                v_count := v_count + 1;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := v_current.name || delimiter_param;
                ELSE
                    v_next_seek := v_current.name;
                END IF;

                EXIT WHEN v_count >= max_keys;
            END LOOP;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: operation(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.operation() RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN current_setting('storage.operation', true);
END;
$$;


--
-- Name: protect_delete(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.protect_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if storage.allow_delete_query is set to 'true'
    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN
        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'
            USING HINT = 'This prevents accidental data loss from orphaned objects.',
                  ERRCODE = '42501';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: search(text, text, integer, integer, integer, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text) RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;
    v_delimiter CONSTANT TEXT := '/';

    -- Configuration
    v_limit INT;
    v_prefix TEXT;
    v_prefix_lower TEXT;
    v_is_asc BOOLEAN;
    v_order_by TEXT;
    v_sort_order TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;

    -- Seek state
    v_next_seek TEXT;
    v_count INT := 0;
    v_skipped INT := 0;
BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_limit := LEAST(coalesce(limits, 100), 1500);
    v_prefix := coalesce(prefix, '') || coalesce(search, '');
    v_prefix_lower := lower(v_prefix);
    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);

    -- Validate sort column
    CASE lower(coalesce(sortcolumn, 'name'))
        WHEN 'name' THEN v_order_by := 'name';
        WHEN 'updated_at' THEN v_order_by := 'updated_at';
        WHEN 'created_at' THEN v_order_by := 'created_at';
        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
        ELSE v_order_by := 'name';
    END CASE;

    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

    -- ========================================================================
    -- NON-NAME SORTING: Use path_tokens approach (unchanged)
    -- ========================================================================
    IF v_order_by != 'name' THEN
        RETURN QUERY EXECUTE format(
            $sql$
            WITH folders AS (
                SELECT path_tokens[$1] AS folder
                FROM storage.objects
                WHERE objects.name ILIKE $2 || '%%'
                  AND bucket_id = $3
                  AND array_length(objects.path_tokens, 1) <> $1
                GROUP BY folder
                ORDER BY folder %s
            )
            (SELECT folder AS "name",
                   NULL::uuid AS id,
                   NULL::timestamptz AS updated_at,
                   NULL::timestamptz AS created_at,
                   NULL::timestamptz AS last_accessed_at,
                   NULL::jsonb AS metadata FROM folders)
            UNION ALL
            (SELECT path_tokens[$1] AS "name",
                   id, updated_at, created_at, last_accessed_at, metadata
             FROM storage.objects
             WHERE objects.name ILIKE $2 || '%%'
               AND bucket_id = $3
               AND array_length(objects.path_tokens, 1) = $1
             ORDER BY %I %s)
            LIMIT $4 OFFSET $5
            $sql$, v_sort_order, v_order_by, v_sort_order
        ) USING levels, v_prefix, bucketname, v_limit, offsets;
        RETURN;
    END IF;

    -- ========================================================================
    -- NAME SORTING: Hybrid skip-scan with batch optimization
    -- ========================================================================

    -- Calculate upper bound for prefix filtering
    IF v_prefix_lower = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
    ELSE
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'AND lower(o.name) COLLATE "C" < $3 ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" >= $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'AND lower(o.name) COLLATE "C" >= $3 ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata ' ||
                'FROM storage.objects o WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 ' ||
                'ORDER BY lower(o.name) COLLATE "C" DESC LIMIT $4';
        END IF;
    END IF;

    -- Initialize seek position
    IF v_is_asc THEN
        v_next_seek := v_prefix_lower;
    ELSE
        -- DESC: find the last item in range first (static SQL)
        IF v_upper_bound IS NOT NULL THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower AND lower(o.name) COLLATE "C" < v_upper_bound
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSIF v_prefix_lower <> '' THEN
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_prefix_lower
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        ELSE
            SELECT o.name INTO v_peek_name FROM storage.objects o
            WHERE o.bucket_id = bucketname
            ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
        END IF;

        IF v_peek_name IS NOT NULL THEN
            v_next_seek := lower(v_peek_name) || v_delimiter;
        ELSE
            RETURN;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= v_limit;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        IF v_is_asc THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSE
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSIF v_prefix_lower <> '' THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Handle offset, emit if needed, skip to next folder
            IF v_skipped < offsets THEN
                v_skipped := v_skipped + 1;
            ELSE
                name := split_part(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter), v_delimiter, levels);
                id := NULL;
                updated_at := NULL;
                created_at := NULL;
                last_accessed_at := NULL;
                metadata := NULL;
                RETURN NEXT;
                v_count := v_count + 1;
            END IF;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
            ELSE
                v_next_seek := lower(v_common_prefix);
            END IF;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size
            LOOP
                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it
                    v_next_seek := lower(v_current.name);
                    EXIT;
                END IF;

                -- Handle offset skipping
                IF v_skipped < offsets THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    -- Emit file
                    name := split_part(v_current.name, v_delimiter, levels);
                    id := v_current.id;
                    updated_at := v_current.updated_at;
                    created_at := v_current.created_at;
                    last_accessed_at := v_current.last_accessed_at;
                    metadata := v_current.metadata;
                    RETURN NEXT;
                    v_count := v_count + 1;
                END IF;

                -- Advance seek past this file
                IF v_is_asc THEN
                    v_next_seek := lower(v_current.name) || v_delimiter;
                ELSE
                    v_next_seek := lower(v_current.name);
                END IF;

                EXIT WHEN v_count >= v_limit;
            END LOOP;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: search_by_timestamp(text, text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_cursor_op text;
    v_query text;
    v_prefix text;
BEGIN
    v_prefix := coalesce(p_prefix, '');

    IF p_sort_order = 'asc' THEN
        v_cursor_op := '>';
    ELSE
        v_cursor_op := '<';
    END IF;

    v_query := format($sql$
        WITH raw_objects AS (
            SELECT
                o.name AS obj_name,
                o.id AS obj_id,
                o.updated_at AS obj_updated_at,
                o.created_at AS obj_created_at,
                o.last_accessed_at AS obj_last_accessed_at,
                o.metadata AS obj_metadata,
                storage.get_common_prefix(o.name, $1, '/') AS common_prefix
            FROM storage.objects o
            WHERE o.bucket_id = $2
              AND o.name COLLATE "C" LIKE $1 || '%%'
        ),
        -- Aggregate common prefixes (folders)
        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior
        aggregated_prefixes AS (
            SELECT
                rtrim(common_prefix, '/') AS name,
                NULL::uuid AS id,
                MIN(obj_created_at) AS updated_at,
                MIN(obj_created_at) AS created_at,
                NULL::timestamptz AS last_accessed_at,
                NULL::jsonb AS metadata,
                TRUE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NOT NULL
            GROUP BY common_prefix
        ),
        leaf_objects AS (
            SELECT
                obj_name AS name,
                obj_id AS id,
                obj_updated_at AS updated_at,
                obj_created_at AS created_at,
                obj_last_accessed_at AS last_accessed_at,
                obj_metadata AS metadata,
                FALSE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NULL
        ),
        combined AS (
            SELECT * FROM aggregated_prefixes
            UNION ALL
            SELECT * FROM leaf_objects
        ),
        filtered AS (
            SELECT *
            FROM combined
            WHERE (
                $5 = ''
                OR ROW(
                    date_trunc('milliseconds', %I),
                    name COLLATE "C"
                ) %s ROW(
                    COALESCE(NULLIF($6, '')::timestamptz, 'epoch'::timestamptz),
                    $5
                )
            )
        )
        SELECT
            split_part(name, '/', $3) AS key,
            name,
            id,
            updated_at,
            created_at,
            last_accessed_at,
            metadata
        FROM filtered
        ORDER BY
            COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz) %s,
            name COLLATE "C" %s
        LIMIT $4
    $sql$,
        p_sort_column,
        v_cursor_op,
        p_sort_column,
        p_sort_order,
        p_sort_order
    );

    RETURN QUERY EXECUTE v_query
    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after;
END;
$_$;


--
-- Name: search_v2(text, text, integer, integer, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_sort_col text;
    v_sort_ord text;
    v_limit int;
BEGIN
    -- Cap limit to maximum of 1500 records
    v_limit := LEAST(coalesce(limits, 100), 1500);

    -- Validate and normalize sort_order
    v_sort_ord := lower(coalesce(sort_order, 'asc'));
    IF v_sort_ord NOT IN ('asc', 'desc') THEN
        v_sort_ord := 'asc';
    END IF;

    -- Validate and normalize sort_column
    v_sort_col := lower(coalesce(sort_column, 'name'));
    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN
        v_sort_col := 'name';
    END IF;

    -- Route to appropriate implementation
    IF v_sort_col = 'name' THEN
        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))
        RETURN QUERY
        SELECT
            split_part(l.name, '/', levels) AS key,
            l.name AS name,
            l.id,
            l.updated_at,
            l.created_at,
            l.last_accessed_at,
            l.metadata
        FROM storage.list_objects_with_delimiter(
            bucket_name,
            coalesce(prefix, ''),
            '/',
            v_limit,
            start_after,
            '',
            v_sort_ord
        ) l;
    ELSE
        -- Use aggregation approach for timestamp sorting
        -- Not efficient for large datasets but supports correct pagination
        RETURN QUERY SELECT * FROM storage.search_by_timestamp(
            prefix, bucket_name, v_limit, levels, start_after,
            v_sort_ord, v_sort_col, sort_column_after
        );
    END IF;
END;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW; 
END;
$$;


