--
-- Name: ai_notification_events; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ai_notification_events WITH (security_invoker='true') AS
 WITH me AS (
         SELECT m.org_id,
            m.user_id,
            m.role_id
           FROM public.user_organization_memberships m
          WHERE ((m.org_id = public.current_org_id()) AND (m.user_id = auth.uid()) AND m.is_active)
        ), thread_events AS (
         SELECT me.org_id,
            me.user_id,
            'ai_message'::text AS source_type,
            (a.id)::text AS source_id,
            ('thread:'::text || (t.id)::text) AS conversation_key,
            t.id AS thread_id,
                CASE
                    WHEN ((t.metadata ->> 'free_chat'::text) = 'true'::text) THEN NULL::text
                    ELSE COALESCE(NULLIF(t.agent_key, ''::text), NULLIF((t.metadata ->> 'agent_key'::text), ''::text), NULLIF(((to_jsonb(t.*) -> 'selected_agents'::text) ->> 0), ''::text), NULLIF(((t.metadata -> 'selected_agents'::text) ->> 0), ''::text), 'lead_orchestrator'::text)
                END AS agent_key,
            COALESCE(NULLIF(t.title, ''::text), 'گفتگوی هوش مصنوعی'::text) AS title,
            a.content,
            COALESCE(a.notification_ready_at, a.created_at) AS created_at,
            COALESCE((ROW(COALESCE(a.notification_ready_at, a.created_at), (a.id)::text) > ROW(COALESCE(c.read_through_at, baseline.read_through_at, t.created_at), COALESCE(c.read_through_id, baseline.read_through_id, ''::text))), false) AS is_unread,
            false AS in_communication,
            false AS in_system_unread
           FROM ((((me
             JOIN public.ai_threads t ON (((t.org_id = me.org_id) AND ((t.user_id = me.user_id) OR (me.user_id = ANY (t.shared_user_ids)) OR (me.role_id = ANY (t.shared_role_ids))))))
             JOIN public.ai_messages a ON (((a.org_id = t.org_id) AND (a.thread_id = t.id) AND (a.role = 'assistant'::text))))
             LEFT JOIN public.communication_read_cursors c ON (((c.org_id = me.org_id) AND (c.user_id = me.user_id) AND (c.channel = 'ai'::text) AND (c.conversation_key = ('thread:'::text || (t.id)::text)))))
             LEFT JOIN public.communication_read_cursors baseline ON (((baseline.org_id = me.org_id) AND (baseline.user_id = me.user_id) AND (baseline.channel = 'ai'::text) AND (baseline.conversation_key = '*'::text))))
          WHERE ((COALESCE(t.status, 'active'::text) = 'active'::text) AND (t.archived_at IS NULL) AND (length(TRIM(BOTH FROM a.content)) > 0) AND (COALESCE(t.context_key, ''::text) !~~ 'reply:%'::text) AND (COALESCE((t.metadata ->> 'last_activity_kind'::text), ''::text) <> 'reply_suggestion'::text) AND (COALESCE((t.metadata ->> 'source'::text), ''::text) <> ALL (ARRAY['reply_suggestion'::text, 'notifications_chat_reply_suggest'::text])) AND (COALESCE((t.metadata ->> 'capability'::text), ''::text) <> 'customer_reply_suggestion'::text) AND (COALESCE((t.metadata ->> 'customer_reply_suggestion'::text), 'false'::text) <> 'true'::text) AND public.ai_message_notification_ready(a.role, a.content, a.metadata))
        ), note_events AS (
         SELECT me.org_id,
            me.user_id,
            'note'::text AS source_type,
            (n.id)::text AS source_id,
            ('agent:'::text || COALESCE(NULLIF((n.metadata ->> 'agent_key'::text), ''::text), NULLIF(substr((n.metadata ->> 'conversation_key'::text), 7), ''::text), 'lead_orchestrator'::text)) AS conversation_key,
            NULL::uuid AS thread_id,
            COALESCE(NULLIF((n.metadata ->> 'agent_key'::text), ''::text), NULLIF(substr((n.metadata ->> 'conversation_key'::text), 7), ''::text), 'lead_orchestrator'::text) AS agent_key,
            COALESCE(NULLIF(n.author_name, ''::text), 'ایجنت هوشمند'::text) AS title,
            n.content,
            n.created_at,
            ((rs.read_at IS NULL) AND (rs.dismissed_at IS NULL) AND ((c.read_through_at IS NULL) OR (ROW(n.created_at, (n.id)::text) > ROW(c.read_through_at, COALESCE(c.read_through_id, ''::text))))) AS is_unread,
            (EXISTS ( SELECT 1
                   FROM public.notification_inbox_items i
                  WHERE ((i.org_id = me.org_id) AND (i.section = 'notes'::text) AND (i.source_type = 'note'::text) AND (i.source_id = (n.id)::text)))) AS in_communication,
            ((rs.read_at IS NULL) AND (rs.dismissed_at IS NULL) AND ((s.read_through_at IS NULL) OR (ROW(n.created_at, (n.id)::text) > ROW(s.read_through_at, COALESCE(s.read_through_id, ''::text)))) AND public.kalam_internal_message_is_system_v2(n.source_type, n.metadata, NULL::text)) AS in_system_unread
           FROM ((((me
             JOIN public.notes n ON (((n.org_id = me.org_id) AND (n.author_id IS DISTINCT FROM me.user_id) AND ((me.user_id = ANY (n.mention_user_ids)) OR (me.role_id = ANY (n.mention_role_ids))))))
             LEFT JOIN public.notification_read_states rs ON (((rs.org_id = me.org_id) AND (rs.user_id = me.user_id) AND (rs.section = 'notes'::text) AND (rs.source_type = 'note'::text) AND (rs.source_id = (n.id)::text))))
             LEFT JOIN public.communication_read_cursors c ON (((c.org_id = me.org_id) AND (c.user_id = me.user_id) AND (c.channel = 'internal'::text) AND (c.conversation_key = ('agent:'::text || COALESCE(NULLIF((n.metadata ->> 'agent_key'::text), ''::text), NULLIF(substr((n.metadata ->> 'conversation_key'::text), 7), ''::text), 'lead_orchestrator'::text))))))
             LEFT JOIN public.communication_read_cursors s ON (((s.org_id = me.org_id) AND (s.user_id = me.user_id) AND (s.channel = 'internal'::text) AND (s.conversation_key = 'system'::text))))
          WHERE (((n.metadata ? 'agent_key'::text) OR ((n.metadata ->> 'conversation_key'::text) ~~ 'agent:%'::text)) AND (length(TRIM(BOTH FROM n.content)) > 0) AND (COALESCE((n.metadata ->> 'pending_status'::text), 'false'::text) <> 'true'::text) AND (COALESCE((n.metadata ->> 'failed'::text), 'false'::text) <> 'true'::text) AND (COALESCE((n.metadata ->> 'incomplete'::text), 'false'::text) <> 'true'::text))
        )
 SELECT note_events.org_id,
    note_events.user_id,
    note_events.source_type,
    note_events.source_id,
    note_events.conversation_key,
    note_events.thread_id,
    note_events.agent_key,
    note_events.title,
    note_events.content,
    note_events.created_at,
    note_events.is_unread,
    note_events.in_communication,
    note_events.in_system_unread
   FROM note_events
UNION ALL
 SELECT t.org_id,
    t.user_id,
    t.source_type,
    t.source_id,
    t.conversation_key,
    t.thread_id,
    t.agent_key,
    t.title,
    t.content,
    t.created_at,
    t.is_unread,
    t.in_communication,
    t.in_system_unread
   FROM thread_events t
  WHERE (NOT (EXISTS ( SELECT 1
           FROM note_events n
          WHERE ((n.agent_key = t.agent_key) AND (n.content = t.content) AND (abs(EXTRACT(epoch FROM (n.created_at - t.created_at))) <= (180)::numeric)))));


