--
-- Name: automation_execution_reports; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.automation_execution_reports WITH (security_invoker='true') AS
 SELECT l.id,
    l.org_id,
        CASE
            WHEN (l.run_type = 'process_automation'::text) THEN
            CASE
                WHEN (COALESCE((l.details ->> 'process_automation_trigger_type'::text), ''::text) = 'interval'::text) THEN 'automation_scheduled'::text
                ELSE 'automation_conditional'::text
            END
            WHEN (l.run_type = 'scheduled_report'::text) THEN 'report_scheduled'::text
            WHEN (l.run_type = 'scheduled'::text) THEN 'workflow_scheduled'::text
            ELSE 'workflow_conditional'::text
        END AS report_category,
        CASE
            WHEN (l.run_type = 'process_automation'::text) THEN 'automation'::text
            WHEN (l.run_type = 'scheduled_report'::text) THEN 'report'::text
            ELSE 'workflow'::text
        END AS source_type,
    COALESCE(NULLIF((l.details ->> 'report_name'::text), ''::text), NULLIF((l.details ->> 'workflow_name'::text), ''::text), NULLIF((l.details ->> 'process_automation_rule_name'::text), ''::text), NULLIF((l.details ->> 'process_automation_rule_id'::text), ''::text),
        CASE
            WHEN (l.run_type = 'scheduled_report'::text) THEN 'گزارش زمان‌دار'::text
            WHEN (l.run_type = 'process_automation'::text) THEN 'اتوماسیون'::text
            ELSE 'گردش کار'::text
        END) AS automation_name,
    COALESCE(NULLIF((l.details ->> 'process_automation_trigger_type'::text), ''::text), NULLIF((l.details ->> 'trigger_type'::text), ''::text), NULLIF((l.details ->> 'event'::text), ''::text),
        CASE
            WHEN (l.run_type = ANY (ARRAY['scheduled'::text, 'scheduled_report'::text])) THEN 'interval'::text
            ELSE ''::text
        END) AS trigger_type,
    COALESCE(NULLIF((l.details ->> 'execution_mode'::text), ''::text), ''::text) AS execution_mode,
        CASE
            WHEN ((l.status = 'failed'::text) AND (COALESCE(l.message, ''::text) ~~* '%نیازمند پیگیری%'::text)) THEN 'needs_attention'::text
            ELSE l.status
        END AS status,
    l.module_id,
    l.record_id,
    l.message,
    l.details,
    l.created_at,
    '[]'::jsonb AS tags,
    NULL::uuid AS assignee_id,
    NULL::text AS assignee_type,
    NULL::uuid AS assignee_role_id,
    NULL::uuid AS process_template_id,
    l.created_at AS updated_at,
    COALESCE(NULLIF((l.details ->> 'record_title'::text), ''::text), '[بدون عنوان]'::text) AS record_title
   FROM public.workflow_logs l;


