    CONSTRAINT chk_mbti_assessments_tf_answers CHECK ((COALESCE((tf_01 = ANY (ARRAY['t'::text, 'f'::text])), true) AND COALESCE((tf_02 = ANY (ARRAY['t'::text, 'f'::text])), true) AND COALESCE((tf_03 = ANY (ARRAY['t'::text, 'f'::text])), true) AND COALESCE((tf_04 = ANY (ARRAY['t'::text, 'f'::text])), true) AND COALESCE((tf_05 = ANY (ARRAY['t'::text, 'f'::text])), true) AND COALESCE((tf_06 = ANY (ARRAY['t'::text, 'f'::text])), true) AND COALESCE((tf_07 = ANY (ARRAY['t'::text, 'f'::text])), true) AND COALESCE((tf_08 = ANY (ARRAY['t'::text, 'f'::text])), true))),
