    execution_process_draft jsonb DEFAULT '{}'::jsonb NOT NULL,
    assignee_id uuid,
    assignee_type text,
    assignee_role_id uuid,
    demo_url text GENERATED ALWAYS AS (
CASE
    WHEN ((status = 'provisioned'::text) AND (NULLIF(TRIM(BOTH FROM requested_slug), ''::text) IS NOT NULL)) THEN (('https://'::text || TRIM(BOTH FROM requested_slug)) || '.tazesystem.ir'::text)
    ELSE NULL::text
END) STORED,
    CONSTRAINT saas_onboarding_requests_assignee_type_check CHECK ((assignee_type = ANY (ARRAY['user'::text, 'role'::text])))
);


