--
-- Name: saas_admin_org_candidates_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_admin_org_candidates_view WITH (security_invoker='true') AS
 WITH owner_members AS (
         SELECT DISTINCT ON (membership.org_id) membership.org_id,
            profile.full_name,
            profile.email
           FROM (public.user_organization_memberships membership
             JOIN public.profiles profile ON ((profile.id = membership.user_id)))
          WHERE (membership.is_active AND membership.is_owner)
          ORDER BY membership.org_id, membership.created_at
        )
 SELECT candidate.id,
    candidate.source_kind,
    candidate.source_id,
    candidate.org_id,
    candidate.request_id,
    candidate.org_name,
    candidate.owner_name,
    candidate.owner_email,
    candidate.primary_contact_mobile,
    candidate.slug,
    candidate.status,
    candidate.plan_code,
    candidate.is_demo,
    candidate.is_readonly,
    candidate.trial_ends_at,
    candidate.resolved_host,
    candidate.dns_status,
    candidate.dns_last_error,
    candidate.arvan_record_id,
    candidate.dns_attempt_count,
    candidate.provisioning_source,
    candidate.provisioned_at,
    candidate.provision_state,
    candidate.industry,
    candidate.employee_count_band,
    candidate.discovery_source,
    candidate.tags,
    candidate.process_template_id,
    candidate.execution_process_draft,
    candidate.created_at,
    candidate.updated_at,
    candidate.created_by,
    candidate.updated_by,
    candidate.assignee_type,
    candidate.assignee_id,
    candidate.assignee_role_id
   FROM ( SELECT organization.id,
            'org'::text AS source_kind,
            organization.id AS source_id,
            organization.id AS org_id,
            settings.request_id,
            organization.name AS org_name,
            COALESCE(NULLIF(TRIM(BOTH FROM settings.owner_name), ''::text), NULLIF(TRIM(BOTH FROM owner.full_name), ''::text), NULLIF(TRIM(BOTH FROM request.full_name), ''::text)) AS owner_name,
            COALESCE(NULLIF(TRIM(BOTH FROM settings.owner_email), ''::text), NULLIF(TRIM(BOTH FROM owner.email), ''::text), NULLIF(TRIM(BOTH FROM request.owner_email), ''::text), NULLIF(TRIM(BOTH FROM request.email), ''::text)) AS owner_email,
            COALESCE(NULLIF(TRIM(BOTH FROM settings.primary_contact_mobile), ''::text), NULLIF(TRIM(BOTH FROM request.mobile), ''::text)) AS primary_contact_mobile,
            settings.slug,
            settings.status,
            settings.plan_code,
            settings.is_demo,
            settings.is_readonly,
            settings.trial_ends_at,
            settings.resolved_host,
            settings.dns_status,
            settings.dns_last_error,
            settings.arvan_record_id,
            settings.dns_attempt_count,
            settings.provisioning_source,
            settings.created_at AS provisioned_at,
            'provisioned'::text AS provision_state,
            request.industry,
            request.employee_count_band,
            request.discovery_source,
            '[]'::jsonb AS tags,
            settings.process_template_id,
            COALESCE(settings.execution_process_draft, '{}'::jsonb) AS execution_process_draft,
            settings.created_at,
            settings.updated_at,
            NULL::uuid AS created_by,
            NULL::uuid AS updated_by,
            settings.assignee_type,
            settings.assignee_id,
            settings.assignee_role_id
           FROM (((public.saas_org_settings settings
             JOIN public.organizations organization ON ((organization.id = settings.org_id)))
             LEFT JOIN public.saas_onboarding_requests request ON ((request.id = settings.request_id)))
             LEFT JOIN owner_members owner ON ((owner.org_id = organization.id)))
        UNION ALL
         SELECT request.id,
            'request'::text AS text,
            request.id,
            NULL::uuid AS uuid,
            request.id,
            COALESCE(NULLIF(TRIM(BOTH FROM request.organization_name), ''::text), NULLIF(TRIM(BOTH FROM request.business_name), ''::text), NULLIF(TRIM(BOTH FROM request.full_name), ''::text), 'درخواست دمو'::text) AS "coalesce",
            NULLIF(TRIM(BOTH FROM request.full_name), ''::text) AS "nullif",
            COALESCE(NULLIF(TRIM(BOTH FROM request.owner_email), ''::text), NULLIF(TRIM(BOTH FROM request.email), ''::text)) AS "coalesce",
            NULLIF(TRIM(BOTH FROM request.mobile), ''::text) AS "nullif",
            NULLIF(public.normalize_saas_slug(request.requested_slug), ''::text) AS "nullif",
            request.status,
            NULL::text AS text,
            COALESCE(request.is_demo_request, true) AS "coalesce",
            false,
            NULL::timestamp with time zone AS timestamptz,
            NULL::text AS text,
            'pending'::text AS text,
            request.failure_message,
            NULL::text AS text,
            0,
            'demo_request'::text AS text,
            request.created_at,
            'request_pending'::text AS text,
            request.industry,
            request.employee_count_band,
            request.discovery_source,
            COALESCE(request.tags, '[]'::jsonb) AS "coalesce",
            request.process_template_id,
            COALESCE(request.execution_process_draft, '{}'::jsonb) AS "coalesce",
            request.created_at,
            request.updated_at,
            NULL::uuid AS uuid,
            NULL::uuid AS uuid,
            request.assignee_type,
            request.assignee_id,
            request.assignee_role_id
           FROM public.saas_onboarding_requests request
          WHERE ((request.org_id IS NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM public.saas_org_settings settings
                  WHERE (settings.request_id = request.id)))))) candidate
  WHERE public.current_user_has_saas_admin_permission();


--
-- Name: saas_admin_orgs_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_admin_orgs_view WITH (security_invoker='true') AS
 SELECT scoped.org_id,
    scoped.org_name,
    scoped.slug,
    scoped.status,
    scoped.plan_code,
    scoped.is_demo,
    scoped.is_readonly,
    scoped.trial_ends_at,
    scoped.resolved_host,
    scoped.dns_status,
    scoped.dns_last_error,
    scoped.arvan_record_id,
    scoped.dns_attempt_count,
    scoped.primary_contact_mobile,
    scoped.provisioning_source,
    scoped.provisioned_at,
    scoped.owner_name,
    scoped.owner_email
   FROM ( SELECT o.id AS org_id,
            o.name AS org_name,
            s.slug,
            s.status,
            s.plan_code,
            s.is_demo,
            s.is_readonly,
            s.trial_ends_at,
            s.resolved_host,
            s.dns_status,
            s.dns_last_error,
            s.arvan_record_id,
            s.dns_attempt_count,
            s.primary_contact_mobile,
            s.provisioning_source,
            s.created_at AS provisioned_at,
            r.full_name AS owner_name,
            r.email AS owner_email
           FROM ((public.saas_org_settings s
             JOIN public.organizations o ON ((o.id = s.org_id)))
             LEFT JOIN ( SELECT DISTINCT ON (p.org_id) p.org_id,
                    p.full_name,
                    p.email
                   FROM (public.profiles p
                     JOIN public.org_roles ro ON ((ro.id = p.role_id)))
                  WHERE ((ro.permissions -> '__saas_admin'::text) IS NULL)
                  ORDER BY p.org_id, p.created_at) r ON ((r.org_id = o.id)))) scoped
  WHERE public.current_user_has_saas_admin_permission();


--
-- Name: saas_admin_users_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.saas_admin_users_view WITH (security_invoker='true') AS
 SELECT saas_admin_user_audit_rows.id,
    saas_admin_user_audit_rows.profile_exists,
    saas_admin_user_audit_rows.auth_exists,
    saas_admin_user_audit_rows.full_name,
    saas_admin_user_audit_rows.email,
    saas_admin_user_audit_rows.mobile,
    saas_admin_user_audit_rows.org_id,
    saas_admin_user_audit_rows.org_name,
    saas_admin_user_audit_rows.org_slug,
    saas_admin_user_audit_rows.role_id,
    saas_admin_user_audit_rows.role_title,
    saas_admin_user_audit_rows.software_role,
    saas_admin_user_audit_rows.is_active,
    saas_admin_user_audit_rows.is_demo,
    saas_admin_user_audit_rows.phone_confirmed,
    saas_admin_user_audit_rows.audit_status,
    saas_admin_user_audit_rows.issues,
    saas_admin_user_audit_rows.tags,
    saas_admin_user_audit_rows.assignee_type,
    saas_admin_user_audit_rows.assignee_id,
    saas_admin_user_audit_rows.assignee_role_id,
    saas_admin_user_audit_rows.process_template_id,
    saas_admin_user_audit_rows.execution_process_draft,
    saas_admin_user_audit_rows.created_at,
    saas_admin_user_audit_rows.updated_at
   FROM public.saas_admin_user_audit_rows() saas_admin_user_audit_rows(id, profile_exists, auth_exists, full_name, email, mobile, org_id, org_name, org_slug, role_id, role_title, software_role, is_active, is_demo, phone_confirmed, audit_status, issues, tags, assignee_type, assignee_id, assignee_role_id, process_template_id, execution_process_draft, created_at, updated_at);


