--
-- Name: sms_delivery_reports; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sms_delivery_reports WITH (security_invoker='true') AS
 SELECT m.id,
    m.org_id,
    COALESCE(NULLIF(m.title, ''::text), NULLIF(m.sender, ''::text), NULLIF(m.recipient, ''::text), 'پیامک'::text) AS title,
    m.channel_type,
    m.provider,
    m.module_id,
    m.record_id,
    m.related_module_id,
    m.related_record_id,
    m.customer_id,
    m.recipient,
    m.message_text,
    m.status,
    m.provider_message_id,
    m.error_message,
    m.metadata,
    m.sent_at,
    m.created_at,
    m.updated_at,
    m.tags,
    m.assignee_id,
    m.assignee_type,
    m.assignee_role_id,
    m.operator_report,
    m.related_task_id,
    m.process_template_id,
    m.direction,
    m.sender,
        CASE
            WHEN (m.direction = 'inbound'::text) THEN m.sender
            ELSE m.recipient
        END AS phone_number,
    m.phone_number_id,
    m.phone_match_status,
    m.received_at,
    COALESCE(m.received_at, m.sent_at, m.created_at) AS message_at
   FROM public.outbound_messages m
  WHERE (m.channel_type = 'sms'::text);


