--
-- Name: workflows; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflows (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid DEFAULT public.current_org_id(),
    module_id text DEFAULT ''::text NOT NULL,
    name text DEFAULT ''::text NOT NULL,
    description text,
    trigger_type text DEFAULT 'on_create'::text NOT NULL,
    interval_value integer,
    interval_unit text,
    interval_at text,
    batch_size integer,
    conditions_all jsonb DEFAULT '[]'::jsonb NOT NULL,
    conditions_any jsonb DEFAULT '[]'::jsonb NOT NULL,
    actions jsonb DEFAULT '[]'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    last_run_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    execution_mode text DEFAULT 'first_match'::text NOT NULL,
    interval_first_run_at timestamp with time zone,
    interval_minute smallint,
    interval_allowed_from_hour smallint,
    interval_allowed_to_hour smallint,
    interval_day_of_month smallint,
    interval_day_condition text,
    interval_days_after_holiday smallint,
    server_queued_at timestamp with time zone,
    module_ids text[] DEFAULT '{}'::text[] NOT NULL,
    scope_type text DEFAULT 'standard'::text NOT NULL,
    process_template_id uuid,
    process_trigger_key text,
    process_source_node_key text,
    process_target_lane_keys text[] DEFAULT '{}'::text[] NOT NULL,
    manual_enabled boolean DEFAULT false NOT NULL,
    agent_key text,
    agent_task_config jsonb,
    agent_task_next_run_at timestamp with time zone,
    agent_task_revision integer DEFAULT 0 NOT NULL,
    agent_task_origin_action_id uuid,
    CONSTRAINT chk_workflows_agent_key CHECK (((agent_key IS NULL) OR (agent_key = ANY (ARRAY['lead_orchestrator'::text, 'sales_leads'::text, 'purchase_supply'::text, 'customer_response'::text, 'hr_manager'::text, 'reservation'::text, 'project_process'::text, 'instagrammer'::text, 'system_guide'::text])))),
    CONSTRAINT workflows_execution_mode_check CHECK ((execution_mode = ANY (ARRAY['first_match'::text, 'every_match'::text]))),
    CONSTRAINT workflows_interval_allowed_from_hour_check CHECK (((interval_allowed_from_hour IS NULL) OR ((interval_allowed_from_hour >= 0) AND (interval_allowed_from_hour <= 23)))),
    CONSTRAINT workflows_interval_allowed_to_hour_check CHECK (((interval_allowed_to_hour IS NULL) OR ((interval_allowed_to_hour >= 0) AND (interval_allowed_to_hour <= 23)))),
    CONSTRAINT workflows_interval_day_of_month_check CHECK (((interval_day_of_month IS NULL) OR ((interval_day_of_month >= 1) AND (interval_day_of_month <= 31)))),
    CONSTRAINT workflows_interval_days_after_holiday_check CHECK (((interval_days_after_holiday IS NULL) OR (interval_days_after_holiday >= 0))),
    CONSTRAINT workflows_interval_minute_check CHECK (((interval_minute IS NULL) OR ((interval_minute >= 0) AND (interval_minute <= 59)))),
    CONSTRAINT workflows_interval_unit_check CHECK (((interval_unit IS NULL) OR (interval_unit = ANY (ARRAY['hour'::text, 'day'::text, 'week'::text, 'month'::text])))),
    CONSTRAINT workflows_trigger_type_check CHECK ((trigger_type = ANY (ARRAY['on_create'::text, 'on_upsert'::text, 'interval'::text])))
);


