--
-- Name: COLUMN workflows.interval_minute; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workflows.interval_minute IS 'for hour-unit: minute within each hour to run (0-59)';


--
-- Name: COLUMN workflows.interval_allowed_from_hour; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workflows.interval_allowed_from_hour IS 'for hour-unit: start of allowed execution window (0-23)';


--
-- Name: COLUMN workflows.interval_allowed_to_hour; Type: COMMENT; Schema: public; Owner: -
--

